locales_quest = locales_quest or {}
locales_quest['esES'] = {
  [1] = {
    'Misión de Kanrethad',
    {'$GBienvenido:Bienvenida; de vuelta del mundo de los muertos.|n|nHace mucho tiempo tus hermanos te consideraban $Gun orgulloso héroe:una orgullosa heroína;. Ahora has caído y estás $Gdestrozado:destrozada;... no eres más que una reliquia del pasado. Colócate ante mí para que pueda volver a despertar la leyenda que fuiste antaño.|n|nTe devolveré los poderes y las armas que has perdido, y así volverás a estar $Gcompleto:completa;.', },
    {'Habla con Kanrethad para que restaure tus talentos, armas y montura.', },
  },
  [2] = {
    'Garfa de Garrafilada',
    {'El poderoso hipogrifo Garfafilada ha sido ejecutado, con la garfa de la bestia derribada como testimonio de tu victoria. Seguro que Senani Corazón Atronador, del Refugio Brisa de Plata, estará interesado en ver este trofeo que prueba tus actos.', },
    {'Llévale la garfa de Garfafilada a Senani Corazón Atronador en el Refugio Brisa de Plata, Vallefresno.', },
  },
  [5] = {
    'La hambruna de Alterio',
    {'¡Llevo semanas escondiéndome en esta ciudad fantasma y no he comido más que larvas y hierbajos! Necesito algo de comida decente. Estoy en disposición de pagar bien.|n|nSi me traes un festín, te pagaré generosamente.|n|nHe oído que el chef Grual del Mesón del Cuervo Escarlata de Villa Oscura hace unos estupendos pasteles de cangrejo oscuro...', },
    {'Habla con el Chef Grual.', },
  },
  [6] = {
    'La recompensa por Garrick Piesuaves',
    {'Garrick Piesuaves es un maleante que lleva semanas acosando a granjeros y mercaderes. Ha sido visto en una choza cerca de los viñedos, cruzando el puente al este de la abadía. Tráeme la cabeza de ese villano y podrás quedarte con su botín.|n|nPero ve con cuidado, $N. Garrick anda con una pandilla de matones. Puede que no te sea fácil llegar hasta él.', },
    {'Mata a Garrick Piesuaves y lleva su cabeza al ayudante de alguacil Willem a la Abadía de Villanorte.', },
  },
  [7] = {
    nil,
    {'$N, lo primero que tienes que hacer es limpiar; un clan de kóbolds ha invadido los bosques del norte. Ve y liquida a todos los kóbolds que encuentres; si reducimos sus filas podremos echarlos de Villanorte.', },
    nil,
  },
  [8] = {
    'Un trato de pícaro',
    {'¡Eh, colega! ¿Le harías un favor a un joven hombre que ha combatido contra más zombis y arañas de los que puede contar?|n|nTengo una carta que tiene que llegar a Rémol... Es para una tabernera llamada Renee no sé qué. No creo que importe cómo se apellida, la verdad.|n|nPero el sitio es muy acogedor y está lleno de víctimas de la Plaga que intentan abrirse paso en el mundo. Es el sitio ideal para descansar... si es que necesitas hacerlo. Anímate... si vas, te pagaré bien.', },
    {'Lleva la carta anodina a Claros de Tirisfal y entrégasela a la tabernera Renee.', },
  },
  [9] = {
    'Campos de la muerte',
    {'¡Mira lo que le ha ocurrido a este lugar! Estas tierras estaban antes en manos de buenos granjeros. Pero los condenados ladrones los han ahuyentado a todos. ¡Pero no a mí! Eso sí, parece que algunos vigías de la cosecha han invadido los campos.|n|nSi estás $Gpreparado:preparada; me gustaría que fueras y mataras a 20 de ellos. Vuelve cuando hayas terminado y te pagaré. Si terminas con los de mi campo, puedes limpiar también los campos vecinos.', },
    {'El granjero Saldean quiere que mates a 20 vigías de la cosecha.', },
  },
  [10] = {
    'La redención de Patagolpe',
    {'¡Oh, esto es horrible! Envié a mi mejor ayudante, el perito adjunto Patagolpe, al desierto situado al sudeste de aquí, una zona que se conoce como Sima Abierta. Bien, pues ha desaparecido y su último informe contenía más información acerca de esos extraños bichos que había visto por la zona. ¿Es posible que ya hayan infestado dos grandes regiones del desierto?|n|nPor favor, ¡necesito que vayas a Sima Abierta en busca de Patagolpe! Y si no lo encuentras a él, al menos a ver si aparece su equipo de análisis. Me temo que pueda ser lo único que quede de ese pobre chico.', },
    {'Descubre qué le ha ocurrido al perito adjunto Patagolpe y llévalo a él o su equipo de análisis ante el perito jefe Picoflojo, en Gadgetzan.', },
  },
  [11] = {
    'Recompensas por los gnolls Zarparrío',
    {'En las fronteras del Bosque de Elwynn se han avistado gnolls, unas criaturas salvajes que seguramente no están allí por trabajo. Un grupo enorme de ellos, uno más numeroso del que podemos contener solos, ha infestado los bosques que hay al sur de la torre de vigilancia. Otro grupo ha infestado las áreas cercanas al Lago del Hito, al este.|n|nEl ejército de Ventormenta elogiará a quienquiera que le ayude a matarlos. Tráeme sus bandas gnoll pintadas como prueba de tu hazaña.', },
    {'Lleva 8 bandas gnoll pintadas al ayudante de alguacil Rainer al Cuartel.', },
  },
  [12] = {
    'La Brigada de los Páramos de Poniente',
    {'La Milicia Popular solo tiene un objetivo: defender las tierras de los Páramos de Poniente y traer la paz a nuestro entorno. Por desgracia, el precio de la paz suele pagarse en sangre.|n|nSegún el informe de uno de mis exploradores, una banda de tramperos Defias ha sido vista cerca de la Mina de Jango al noroeste de aquí, en La Granja de Molsen y en la Plantación de Calabazas de Cejade. Si quieres unirte a nuestras filas, acaba con 15 tramperos Defias y con 15 contrabandistas Defias y vuelve a verme.', },
    {'Gryan Mantorrecio quiere que mates a 15 tramperos Defias y a 15 contrabandistas Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela.', },
  },
  [13] = {
    'La Brigada de los Páramos de Poniente',
    {'Una banda de despiadados saqueadores Defias ha sido vista saqueando la Mina de la Costa del Oro, el Arroyo de la Luna y la Hacienda de Alexston. La Milicia Popular no tolerarán ese comportamiento. Avisa inmediatamente, $N, y haz conocer la presencia de la Luz en los Páramos de Poniente.|n|nLa Mina de la Costa del Oro está cerca de la costa, al oeste de la torre. El siguiente paso de tu instrucción consistirá en acabar con 15 de esos saqueadores Defias y con 15 despojadores Defias.', },
    {'Gryan Mantorrecio quiere que mates a 15 saqueadores Defias y a 15 despojadores Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela.', },
  },
  [14] = {
    'La Brigada de los Páramos de Poniente',
    {'Algunos Defias nos han esquivado. Según informa mi mejor explorador, los Defias han estado saqueando y expoliando el campo, hasta la parte sureste de los Páramos de Poniente. Creemos que se están ocultando en Las Colinas Afiladas, planeando sus siguientes pasos. Acaba con esos miserables en nombre de La Milicia Popular', },
    {'Gryan Mantorrecio quiere que mates a 15 bandoleros Defias, a 5 acechacaminos Defias y a 5 nudillos Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela.', },
  },
  [15] = {
    '[DEPRECATED] Investigar la Mina del Eco',
    {'$N, los exploradores dicen que hay más kóbolds de lo que creíamos. Un grupo de trabajadores ha acampado cerca de la Mina del Eco, al norte de aquí.|n|nVe a la mina y liquídalos; sabemos que hay al menos ocho. Comprueba que no quede ninguno más y vuelve.', },
    {'Mata a 8 trabajadores kóbold y ve a hablar con el alguacil McBride.', },
  },
  [16] = {
    'Dale de beber a Gerard',
    nil,
    nil,
  },
  [17] = {
    'Componentes de Uldaman',
    {'Hace poco oí hablar de un organismo recién descubierto: las setas magenta. Crecen arracimadas en la excavación de Uldaman y pueden encontrarse en los túneles primitivos y en las profundidades de las zonas menos explotadas. Quiero ver qué usos potenciales pueden tener en la alquimia, por eso necesito tu ayuda.|n|nTráeme una docena de setas magenta. Es posible que se defiendan con esporas venenosas; ten cuidado.|n|n¡A cambio, te daré uno de mis famosos elixires vigorizantes!', },
    {'Lleva 12 setas magenta a Ghak Sanadón a Thelsamar.', },
  },
  [18] = {
    'Hermandad de ladrones',
    {'Hace poco llegó una banda de maleantes a Villanorte. Se hacen llamar la Hermandad Defias; se les ha visto cruzando el río hacia el este.|n|nNo sé qué están haciendo, ¡pero seguro que no es nada bueno! Tráeme sus pañuelos y te daré un arma como recompensa.', },
    {'Lleva 8 pañuelos de arpillera roja al ayudante de alguacil Willem cerca de la Abadía de Villanorte.', },
  },
  [19] = {
    nil,
    {'Hay avanzados y renegados Roca Negra tendiendo emboscadas entre aquí y el Fuerte de Petravista. El jefe de los avanzados se llama Tharil\'zun y lo queremos muerto. ¡Tráeme su cabeza!', },
    {'Lleva la cabeza de Tharil\'zun al alguacil Marris a Crestagrana.', },
  },
  [20] = {
    'La amenaza de los Roca Negra',
    {'Los orcos Roca Negra llegaron desde Las Estepas Ardientes y han invadido el Fuerte de Petravista, al norte de aquí. Andan merodeando por el norte de Villa del Lago y tienen a los ciudadanos encerrados como a ganado.|n|nLibra a Villa del Lago de esta amenaza. Mata a los orcos y tráeme 10 hachas desgastadas por la batalla como prueba.|n|nAunque nos amenazan desde el norte, sabemos que hay más al sureste de Crestagrana. Si los encuentras, mátalos también.', },
    {'Lleva 10 hachas desgastadas por la batalla al alguacil Marris a Villa del Lago.', },
  },
  [21] = {
    '[DEPRECATED] Escaramuza en la Mina del Eco',
    {'Ha quedado demostrado que tenemos que purgar la Mina del Eco. Vuelve allí y ayuda a eliminar a los kóbolds.|n|nDate prisa, $N. Cuanto más tiempo dejemos a los kóbolds en la mina, más nos costará expulsarlos de Villanorte.', },
    {'Mata 8 obreros kóbold y ve a hablar con el alguacil McBride a la Abadía de Villanorte.', },
  },
  [22] = {
    'Pastel de hígado de Dentosangre',
    {'Las cebollas están peladas. El ajo machacado. La corteza está tostada. Las hierbas de eneldo picadas. ¡Lo único que me falta para mi famosa empanada de carne son 8 hígados de dentosangre!', },
    {'Salma Saldean necesita 8 hígados de dentosangre para hacer un pastel de hígado de dentosangre.', },
  },
  [23] = {
    'Pata de Ursangous',
    {'¡El poderoso oso Ursangous ya es historia!|n|nLa pequeña media luna de su pata indica que a esta bestia la entrenaron los elfos de la noche para recorrer el bosque en busca de sus enemigos. Quién sabe cuántos de tus aliados de la Horda han caído ante esta criatura.|n|nDeberías llevarle la pata a Tarkan, en el Refugio Brisa de Plata.', },
    {'Llévale la pata de Ursangous al capitán Tarkan en el Refugio Brisa de Plata.', },
  },
  [24] = {
    'Cabeza de Shadumbra',
    {'El otrora veloz Shadumbra yace ahora inerte mientras tú reivindicas tu victoria sobre él.|n|nLos elfos de la noche aprecian a esta criatura legendaria. Su cabeza servirá como trofeo intimidatorio y como símbolo del fin de la Alianza en Vallefresno.|n|nEl Capitán Goggath, en la Avanzada Grito Infernal, estará encantado de recibir la cabeza del sable de la noche asesinado.', },
    {'Llévale la cabeza de Shadumbra al Capitán Goggath en la Avanzada Grito Infernal.', },
  },
  [25] = {
    'Un jarro de agua fría',
    nil,
    nil,
  },
  [26] = {
    'Una lección que aprender',
    {'$N, he seguido tus progresos con gran gozo. Sin duda te estás convirtiendo en $Gun valioso protector:una valiosa protectora; de la naturaleza.|n|nHa llegado el momento de que aprendas más sobre una de las formas animales con las que Cenarius nos ha bendecido. Una forma que podemos adoptar y que nos permite controlar el agua. Tendrás que viajar al poblado Amparo de la Noche, que está en Claro de la Luna, y hablar con Dendrita Rafagaestelar del Círculo Cenarion. Él será tu guía.', },
    {'Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.', },
  },
  [27] = {
    'Una lección que aprender',
    {'$N, he seguido tus progresos con gran gozo. Sin duda te estás convirtiendo en $Gun valioso protector:una valiosa protectora; de la naturaleza.|n|nHa llegado el momento de que aprendas más sobre una de las formas animales con las que Cenarius nos ha bendecido. Una forma que podemos adoptar y que nos permite controlar el agua. Tendrás que viajar al poblado Amparo de la Noche, que está en Claro de la Luna, y hablar con Dendrita Rafagaestelar del Círculo Cenarion. Él será tu guía.', },
    {'Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.', },
  },
  [28] = {
    'La prueba del lago',
    {'En tu primera prueba, debes ir a las profundidades del Lago Elune\'ara y encontrar un adorno de altar. Se descompone rápidamente, por lo que deberás ir inmediatamente al Santuario de Remulos. Coloca el adorno en el altar y habla con Tajarri; es una de las celadoras más apreciadas de Claro de la Luna.|n|nTienes un tiempo limitado para completar la tarea y es probable que tengas que competir con otros druidas en busca de adornos. Necesitarás toda tu destreza mental y física.|n|nSuerte, $N.', },
    {'Lleva un adorno de altar del Lago Elune\'ara al Santuario de Remulos, al noroeste de Claro de la Luna. Usa el adorno en el santuario. |n|nDespués, habla con Tajarri en el santuario para completar la prueba.', },
  },
  [29] = {
    'La prueba del lago',
    {'En tu primera prueba, debes ir a las profundidades del Lago Elune\'ara y encontrar un adorno de altar. Se descompone rápidamente, por lo que deberás ir inmediatamente al Santuario de Remulos. Coloca el adorno en el altar y habla con Tajarri; es una de las celadoras más apreciadas de Claro de la Luna.|n|nTienes un tiempo limitado para completar la tarea y es probable que tengas que competir con otros druidas en busca de adornos. Necesitarás toda tu destreza mental y física.|n|nSuerte, $N.', },
    {'Lleva un adorno de altar del Lago Elune\'ara al Santuario de Remulos, al noroeste de Claro de la Luna. Usa el adorno en el santuario. |n|nDespués, habla con Tajarri en el santuario para completar la prueba.', },
  },
  [30] = {
    'La prueba del león marino',
    {'En tu segunda prueba debes encontrar las dos mitades del colgante del león marino. Una obtiene su poder de la agilidad del león marino cuando se desliza en el agua, la otra lo obtiene de su increíble capacidad de resistencia. Los druidas se alimentan de ambos rasgos para asumir su forma acuática.|n|nHabla con la gente de Claro de la Luna para averiguar dónde están las mitades y tráemelas para que las unamos. Luego llevarás el colgante a Dendrita Rafagaestelar.', },
    {'Busca el colgante de Agilidad acuática y el colgante de Resistencia acuática. Habla con la gente de Claro de la Luna para conseguir pistas sobre la ubicación de los colgantes. |n|nForma el colgante del león marino con los otros dos cuando estés cerca del Santuario de Remulos. |n|nLleva el colgante completo a Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.', },
  },
  [31] = {
    'Forma acuática (elfo de la noche druida)',
    {'Has completado tu formación para la adopción de una forma acuática. Ve a ver a tu instructor, Turak Tótem de Runa, a Cima del Trueno. Enséñale el colgante y demuéstrale que puedes aprender lo que tenga que enseñarte. Él completará tu formación para que puedas fundirte con el agua.|n|nBuena suerte, joven druida. Volveremos a vernos.', },
    {'Vuelve a Cima del Trueno y enséñale el colgante del león marino a Turak Tótem de Runa.', },
  },
  [32] = {
    'La sublevación de los silítidos',
    {'Aquí tienes el informe. Te ruego que se lo entregues a alguien que tenga conocimientos de este tema.|n|nConozco a un trol erudito llamado Zilzibin Tambor Sabio que ha dedicado mucho tiempo al estudio de los seres vivos que solo se encuentran en Azeroth. ¡Es un historiador de los pies a la cabeza! Entrégale este informe si quieres que te ayude a entender a qué te enfrentas y el modo de detener esta amenaza. Vamos a necesitar toda la ayuda que podamos conseguir.|n|nZil vive en una casa en el segundo nivel de La Calle Mayor en Orgrimmar.', },
    {'Entrégale el informe a Zilzibin Tambor Sabio en Orgrimmar.', },
  },
  [33] = {
    '[DEPRECATED] Los lobos cruzan la frontera',
    {'Sea lo que sea lo que está afectando a estos lobos, no se va. Cada día que pasa hay más lobos enfermos. Me puede pedirle a alguien que mate a las bestias de la naturaleza, pero debemos acabar con los lobos jóvenes malsanos antes de que esta pequeña infección se convierta en una epidemia.|n|nMata lobos jóvenes malsanos en el valle y tráeme pelambres de lobo malsano como prueba de tu hazaña.', },
    {'Lleva 8 pelambres de lobo malsano a Eagan Desollapelambres junto a la Abadía de Villanorte.', },
  },
  [34] = {
    'Una visita poco grata',
    {'Han vuelto a arrasar mi jardín, y sé quién es el responsable. Es ese maldito jabalí, ese al que el alguacil Marris llama Panzallena.|n|nYa es demasiado tarde para replantar narcisos. Ese puerco ha devastado mis flores. ¡Acaba con ese bicharraco! Si me traes un colmillo suyo, te recompensaré. Dicen que anda husmeando por los campos que hay al suroeste de Villa del Lago, pero de vez en cuando viene a mi jardín.', },
    {'Martie Jainrose de Villa del Lago quiere que mates a Panzallena. Llévale un colmillo como prueba.', },
  },
  [35] = {
    'Más preocupaciones',
    {'Si te preocupa que los rumores sobre los múrlocs sean ciertos, viaja al puente del este de Elwynn y habla con el guardia Thomas. Esta última semana se encuentra emplazado en el puente y sabrá cuál es el estado de la situación.|n|nTengo un destrero de Ventormenta que te llevará hasta el guardia Thomas. Si quieres utilizar el caballo, dímelo.', },
    {'El alguacil Dughan quiere que hables con el guardia Thomas.', },
  },
  [36] = {
    'Estofado de los Páramos de Poniente',
    {'Nunca pensé que llegaría el día en el que tuviera que dejar la granja. Pero los campos están llenos de ladrones y es demasiado peligroso que sigamos aquí. En cuanto el granjero Cejade consiga arreglar el carro nos pondremos en marcha.|n|n¿Podrías hacerme un favor? Deja que te escriba mi receta del estofado de los Páramos de Poniente. Por favor, llévasela a Salma Saldean, estará en la Finca de Saldean, nada más pasar la bifurcación del camino.', },
    {'Verna Cejade quiere que le entregues su receta del estofado de los Páramos de Poniente a Salma Saldean.', },
  },
  [37] = {
    'Encuentra a los guardias perdidos',
    {'Hace unos días mandé a dos guardias, Rolf y Malakai, a investigar el río. Aún no han regresado. Para completar mi informe necesito saber qué les ocurrió a esos hombres.|n|nViaja al norte a lo largo del río y encuentra a mis guardias... o lo que quede de ellos.', },
    {'El guardia Thomas quiere que viajes al norte, río arriba, y busques a sus dos guardias, Rolf y Malakai.', },
  },
  [38] = {
    'Estofado de los Páramos de Poniente',
    {'¡Ayúdame a preparar el estofado de los Páramos de Poniente! Vuelve con estos ingredientes: |n |n 3 piezas de carne fibrosa de buitre |n 3 morros de dentosangre |n 3 ojos de múrloc |n 3 okras', },
    {'Salma Saldean quiere 3 carnes fibrosas de buitre, 3 morros de dentosangre, 3 ojos de múrloc y 3 okras.', },
  },
  [39] = {
    'Entrega el informe de Thomas',
    {'Habla al alguacil Dughan de la muerte de Malakai y Rolf, y después infórmale de que no podrá contener a los múrlocs del este de Elwynn con sus tropas.|n|nSé que no tenemos bastantes soldados, quizás Dughan pueda encontrar alguno más.', },
    {'Preséntate ante el alguacil Dughan en Villadorada.', },
  },
  [40] = {
    'Un peligro con olor a pescado',
    {'¡Hay una nueva amenaza en el Bosque de Elwynn, $N! ¡Los múrlocs están subiendo por los ríos al este de Elwynn, ahuyentando a los peces y atacando a las buenas gentes de allí!|n|nAvisé al alguacil Dughan, pero le preocupan más los gnolls y los bandidos. No cree que los múrlocs sean una amenaza.|n|n¡Por favor, $N! ¡Habla con Dughan y convéncele de que envíe más tropas al este!', },
    {'Remy "Dos Veces" quiere que hables con el alguacil Dughan de Villadorada.', },
  },
  [45] = {
    'Descubre el destino de Rolf',
    {'En tu exploración del área encuentras huellas palmeadas que llevan al este por la costa del Lago del Hito. Hacia el este, en la distancia, adivinas la silueta de una aldea múrloc.|n|nQuizás Rolf encontró allí su destino...', },
    {'Busca a Rolf o alguna prueba de su muerte en el poblado múrloc.', },
  },
  [46] = {
    'Recompensas por los múrlocs',
    {'El ejército de Ventormenta ha puesto precio a la cabeza de los rondadores y batidores múrloc de Elwynn. Mátalos y llévale sus aletas al guardia Thomas. El ejército de Ventormenta te recompensará bien.|n|nLos múrlocs han construido una aldea en el Lago del Hito, al norte de aquí, y otra en el sur, donde se divide el río.', },
    {'Lleva 8 aletas de múrloc rotas al guardia Thomas al puente oriental de Elwynn.', },
  },
  [47] = {
    'Intercambio de polvo de oro',
    {'Los kóbolds de esa zona a veces llevan polvo de oro. Me vendría muy bien. Consígueme un montón de polvo de oro y te pagaré el mejor precio de la ciudad, ¡el mejor!|n|nPuedes encontrar kóbolds en la Mina Abisal, al sur, y también alrededor de la Cantera de Jaspe, al noreste.', },
    {'Lleva 10 unidades de polvo de oro a Remy "Dos Veces" a Villadorada. Puedes obtener polvo de oro de los kóbolds del Bosque de Elwynn.', },
  },
  [48] = {
    'Dulce ámbar',
    {'Allá en el sur donde las zarzas irritan|nHay un manantial de aguas umbrías|nPura como la sagrada Hija de la Luz|nAgua del manantial sagrado me traerás tú.', },
    {'Lleva agua del manantial sagrado a Tragoamargo Cebatruenos.', },
  },
  [49] = {
    'Dulce ámbar',
    {'Ámbar es el color del amor de mi vida|nComo las luces de un final del día|nRecupéralo y el amor volverá a mí|nUn saco de cebada, uno de centeno y otro de maíz.', },
    {'Tragoamargo Cebatruenos quiere un saco de cebada, un saco de centeno y un saco de maíz.', },
  },
  [50] = {
    'Dulce ámbar',
    {'Mezclaré y mezclaré y un puré será todo|nSerá, amigo, nuestro más querido tesoro|nHaré un alambique fuerte y resistente|nDame veraplata y no daré la lata.', },
    {'Tragoamargo Cebatruenos quiere veraplata.', },
  },
  [51] = {
    'Dulce ámbar',
    {'Recién destilada, aunque aún no esté filtrada|nComo tierra sin semilla esperando a ser arada|nAhora haré nuestra pila de carbón|nUna rama de sicomoro es tu próxima misión.', },
    {'Lleva una rama de sicomoro a Tragoamargo Cebatruenos.', },
  },
  [52] = {
    'Proteger la frontera',
    {'Saludos, $N. Los animales salvajes son más agresivos cuanto más nos alejamos de Villadorada. El Aserradero de la Vega del Este sufre constantes ataques de lobos y osos.|n|nNos vendría bien tu ayuda ahí fuera.', },
    {'Mata a 8 merodeadores o lobos grisáceos del bosque y a 5 osos del bosque jóvenes y vuelve con el guardia Thomas al puente oriental de Elwynn.', },
  },
  [53] = {
    'Dulce ámbar',
    {'Es un líquido meloso que se vuelve delicioso|nDulce líquido ambarino que merece mi cariño|nPero algo necesito para darle mis cuidados|nUn magnífico tonel del mejor roble carbonizado.', },
    {'Lleva un montón de roble carbonizado a Tragoamargo Cebatruenos.', },
  },
  [54] = {
    'Informa en Villadorada',
    {'$N, eres $Gun:una:c; $C que ciertamente ha demostrado que le preocupa la seguridad de Villanorte. Tu siguiente misión será proteger el Bosque de Elwynn.|n|nSi aceptas, te daré unos papeles para el alguacil Dughan, que está en Villadorada. Para ir a Villadorada, sigue el camino hacia el sur, pasada la frontera.', },
    {'Lleva los documentos del alguacil McBride al alguacil Dughan a Villadorada, en el Bosque de Elwynn.', },
  },
  [55] = {
    'Morbent Vil',
    {'Morbent Vil se esconde en su guarida, una casa ubicada en la cima de la montaña que hay al este, da al Cementerio del Cerro del Cuervo. Su tiempo en esta tierra está llegando a su fin...|n|nUtiliza la pesadilla de Morbent contra él. Inutilizará su magia protectora.|n|nY mátalo. Mátalo y sálvanos de su maldad. ¡Sé el instrumento de mi venganza, y conviértete en $Gel héroe:la heroína; del Bosque del Ocaso!', },
    {'Utiliza la pesadilla de Morbent contra Morbent Vil, mata a Morbent Vil y luego ve al campamento de Sven y devuélvele la pesadilla de Morbent.', },
  },
  [56] = {
    'La Guardia Nocturna',
    {'Como Comandante de La Guardia Nocturna, es mi deber proteger a los ciudadanos de Villa Oscura. Ventormenta ha retirado a los guardias que estaban aquí destacados. Ahora tenemos que arreglárnoslas solos.|n|nSi crees estar a la altura de la tarea, nos vendría bien tu ayuda. Ayuda a La Guardia Nocturna aventurándote en el Jardín Sereno, al sur de Villa Oscura y matando a 8 guerreros esqueléticos y a 6 magos esqueléticos. ¡Hemos de acabar con la amenaza de los no-muertos!', },
    {'La comandante Althea Cerranegro de Villa Oscura quiere que mates a 8 guerreros esqueléticos y a 6 magos esqueléticos.', },
  },
  [57] = {
    'La Guardia Nocturna',
    {'$N, me están llegando informes de una infestación de no-muertos en el bosque. Si estás a la altura, viaja al Cementerio del Cerro del Cuervo y mata a 15 de esos malignos esqueléticos y a 15 horrores esqueléticos. También me han llegado noticias de la presencia de esqueletos al sur de Villa Oscura, en el Cementerio del Jardín Sereno y en sus alrededores. ¡Hemos de expulsar a los no-muertos del Bosque del Ocaso!', },
    {'La comandante Althea Cerranegro de Villa Oscura quiere que mates a 15 malignos esqueléticos y a 15 horrores esqueléticos.', },
  },
  [58] = {
    'La Guardia Nocturna',
    {'La situación de Cerro del Cuervo sigue siendo desalentadora. La seguridad de Villa Oscura está en tus manos, $N. Yo no tengo suficientes vigías para mantener la villa a salvo. Necesitamos que ayudes a Cerro del Cuervo una vez más y que liberes el mausoleo oriental de 20 propagadores de peste.', },
    {'La comandante Althea Cerranegro de Villa Oscura quiere que mates a 20 propagadores de peste en el mausoleo oriental de Cerro del Cuervo.', },
  },
  [59] = {
    'Armadura de paño y cuero',
    {'Por tu astucia y valor, te entrego un marcador que vale por una pieza de armadura. Quiero que se lo lleves a Sara Timberlain al Aserradero de la Vega del Este. Dale el marcador y ella te forjará una armadura. Y cuando la recibas, $N, úsala para defender Elwynn.|n|nLa Vega del Este está al este de este puesto, al otro lado del puente.', },
    {'Entrega a Sara Timberlain el marcador de armaduras de Ventormenta.', },
  },
  [60] = {
    'Las velas de los kóbolds',
    {'Hola, $Gchico:chica;. ¿Tienes un momento?|n|nMi hermano y yo tenemos un herbolario en Ventormenta. Yo estoy aquí para conseguir velas grandes, por la cera, ya me entiendes. ¿Puedes ayudarme?|n|nPuedes conseguir velas grandes de los kóbolds. He oído rumores de que están infestando las minas de Elwynn... La Mina Abisal del sur y la Cantera de Jaspe del este. Puedes empezar la búsqueda en uno de esos lugares.', },
    {'Lleva 8 velas grandes a William Mortero a Villadorada.', },
  },
  [61] = {
    'Un envío para Ventormenta',
    {'Mi hermano Morgan espera mi envío de velas en Ventormenta. No tengo tiempo para hacer el viaje en persona, pero si quisieras llevarle el envío, te pagaría bien.|n|nHe empaquetado las velas. Encontrarás a Morgan en nuestra tienda, Herbolario Mortero, en el Distrito de Mercaderes de Ventormenta.', },
    {'Lleva el envío de William a Morgan Mortero al Distrito de Mercaderes de Ventormenta.', },
  },
  [62] = {
    'La Mina Abisal',
    {'¡La mina de Villanorte no es la única que tiene problemas! Según mis informes, la Mina Abisal de Elwynn también ha sido ocupada por los kóbolds.|n|nExplora la mina y comprueba la veracidad de mis informes. Luego vuelve aquí. La mina está hacia el sur de Villadorada, entre La Granja Pedregosa y la granja Maclure.', },
    {'Explora la Mina Abisal y vuelve junto al alguacil Dughan a Villadorada.', },
  },
  [63] = {
    'La llamada del agua',
    {'Por la costa del Bosque de Argénteos, al oeste de El Sepulcro, verás un altar infestado por la peste. Los espíritus de ese lugar ya no se comunican con nuestro pueblo y de ti depende acabar con esa manifestación de la Plaga y limpiar el estanque.|n|nLlévate los brazales de elemental y las gotas restantes de la poción de Salmuera y colócalos en el blandón. El ritual debería bastar para invocar a un espíritu puro con el que comunicarte.|n|nTráeme una prueba de haber completado la tarea y te recompensaré con un tótem.', },
    {'Derrota a la manifestación de agua corrupta y coloca los brazales de manifestación corrupta con las gotas restantes del agua más pura en el blandón de Siemprefuente en el Bosque de Argénteos.', },
  },
  [64] = {
    'La reliquia olvidada',
    {'¡Fue horrible! Verna me despertó cuando oyó jaleo en los campos. Estaban llenos de gamberros. Nos fuimos corriendo y olvidé recoger mi reloj de bolsillo. Me lo dio el padre de Verna el día de nuestra boda y es horrible saber que está en manos de esos ladrones. Dejé el reloj de bolsillo en el guardarropa de la granja. Busca el campo de calabazas que está al Oeste... no tiene pérdida. ¡Si me lo devuelves te estaré muy agradecido!', },
    {'El granjero Cejade quiere que recuperes el reloj de bolsillo que dejó olvidado en el guardarropa de su granja en la plantación de calabazas del Oeste.', },
  },
  [65] = {
    'La hermandad de los Defias',
    {'La banda de desgraciados responsable de que las gentes de los Páramos de Poniente abandonaran sus tierras se llama a sí misma la Hermandad Defias. Necesito que te infiltres en este clan de matones. Debemos averiguar quién lidera el grupo y dónde se esconden. En Villa del Lago, en la posada, encontrarás a un pícaro que responde al nombre de Wiley; me debe un favor.|n|nViaja a Villa del Lago, en las Montañas Crestagrana, al este de Elwynn, y averigua todo lo que puedas.', },
    {'Gryan Mantorrecio quiere que hables con Wiley en Villa del Lago.', },
  },
  [66] = {
    'La leyenda de Stalvan',
    {'La otra noche, un terrible tumulto me recorrió las venas. Sentí que mi nieta Alyssa estaba en grave peligro. Consulté las cartas y vi a la Muerte contemplándome desde la mesa.|n|nBusqué la luz en un largo y oscuro trance... intentaba encontrar algo concreto que me ayudara a calmar el espíritu. Y un nombre vino a mí. Stalvan.|n|nAcude al secretario del Concejo e intenta averiguar algo más sobre ese nombre. Temo por todos nosotros.', },
    {'Busca al secretario Daltry en el Concejo de Villa Oscura.', },
  },
  [67] = {
    '[DEPRECATED]La leyenda de Stalvan',
    {'Stalvan, ¿eh? Deja que consulte el registro.|n|nStalvan... Stalvan... Veamos... ¡Ah! ¡Aquí está! Tengo un señor Stalvan Mantoniebla. Según consta aquí, su última dirección es la Escuela de Arroyo de la Luna. ¡Pero este dato es de hace mucho tiempo!|n|nHazme un favor, ¿quieres? Si pasas por Arroyo de la Luna, hazme saber si consigues información más reciente sobre este tipo. Me gusta llevar los registros al día.', },
    {'Viaja a la Escuela de Arroyo de la Luna y lleva cualquier información que descubras sobre Stalvan al secretario Daltry.', },
  },
  [68] = {
    'La leyenda de Stalvan',
    {'En el viejo arcón encuentras una carta polvorienta sin enviar.', },
    {'Lleva la carta polvorienta sin enviar al secretario Daltry.', },
  },
  [69] = {
    '[DEPRECATED]La leyenda de Stalvan',
    {'¡Ay, ay! Esto se me debió de pasar la primera vez. En el registro, justo debajo de la primera dirección de Stalvan, hay otra dirección. Está tachada... Parece que se dirigía a la Posada Orgullo de León, en Villadorada. Quizás quieras comprobarlo, $N.', },
    {'Ve a la Posada Orgullo de León a ver si alguien ha oído el nombre de Stalvan.', },
  },
  [70] = {
    'La leyenda de Stalvan',
    {'Stalvan... ese nombre me suena de algo. ¡Ya sé de qué!|n|nUna noche de tormenta de hace muchos años, llegó aquí un mensajero que buscaba refugio para la noche. Casi a medianoche, el hombre se precipitó escaleras abajo gritando, pálido de terror. Desapareció en la tormenta aún en pijama.|n|nCon las prisas, se olvidó sus cartas en el cofre de arriba. Y nunca volvió a buscarlas. Una de ellas es de ese tal Stalvan. Iba dirigida al distrito de Los Canales de Ventormenta. Puedes quedártela.', },
    {'Recupera la carta sin enviar de Stalvan del cofre y entrégala en el distrito de Los Canales de Ventormenta.', },
  },
  [71] = {
    'Informa a Thomas',
    {'Ahora que tienes los dos medallones, llévaselos al guardia Thomas al puente. Así sabrá que sus guardias murieron asesinados.', },
    {'Entrega los medallones de Rolf y Malakai al guardia Thomas. Lo encontrarás en el puente oriental de Elwynn.', },
  },
  [72] = {
    'La leyenda de Stalvan',
    {'Mi padre era el custodio de la propiedad mucho antes que yo. Tuvo que limpiar la sangre después de la masacre. Pero eso ahora no viene al caso.|n|nEl fondo de Cresta Sílex se ha agotado. Ahora, las últimas pertenencias de la familia serán subastadas. Es culpa de esos buitres de los recaudadores de impuestos. Como veo que te mueres por saber más, creo que puedes mirar entre toda esta basura. Quién sabe lo que puedes encontrar.', },
    {'Busca una pista entre los objetos empaquetados.', },
  },
  [73] = {
    '<TXT> No hay recompensa',
    nil,
    nil,
  },
  [74] = {
    'La leyenda de Stalvan',
    {'Dentro de la caja encuentras varios objetos: reliquias familiares mohosas, unos trofeos de caza, un retrato de familia y algunos libros antiguos. Al fondo, debajo de un jarrón, descubres una página arrancada de un diario.', },
    {'La página arrancada del diario que descubriste es tu siguiente pista.', },
  },
  [75] = {
    'La leyenda de Stalvan',
    {'Cuando me mudé aquí había un fajo de papiros en el cofre de arriba. Empecé a examinarlos, pero tuve que dejarlo cuando la niebla empezó a nublarme la vista.|n|nHazle un favor a un pobre anciano ciego. Sube y busca en el cofre cualquier cosa que te pueda ayudar a descubrir más sobre ese Stalvan. Sé que hay una página de un diario que, aunque está algo descolorida, podría interesarte mucho. Tráemela. Yo te ayudaré en lo que pueda.', },
    {'El mariscal Haggard quiere que busques la página del diario descolorida en el cofre que hay arriba.', },
  },
  [76] = {
    'La Cantera de Jaspe',
    {'Gracias a ti, ahora sabemos que la Mina Abisal está infestada de kóbolds. Ahora necesitamos un explorador que investigue la Cantera de Jaspe, que está más lejos.|n|nExplora la Cantera de Jaspe e infórmame si ves algún kóbold. Para llegar a la mina, viaja hacia el este por el camino hasta que llegues a la Torre de Azora. Cuando llegues allí, dirígete hacia el norte. Encontrarás la mina al pie de las colinas.', },
    {'Explora la Cantera de Jaspe y vuelve a informar al alguacil Dughan a Villadorada.', },
  },
  [77] = {
    'Una situación peliaguda',
    {'Tengo material de empaquetado original para el calimocho que quiere Dran Droffers. Te ayudaré a prepararlo para enviárselo a ese gruñón del padre de Malton... a cambio de dos botellas del mismo. Están en unas cajas en la base abandonada de la Horda cerca de Roca Oculta.|n|nSerá muy dificultoso; habrá babosas y mocos repugnantes por las ruinas. Dicen que su líder es una especie de jefe moco. Pero da igual; consigue el calimocho y vuelve aquí para empaquetarlo.', },
    {'Recoge 10 botellas de calimocho dulce de las Tierras del Interior de las cajas de la base abandonada de la Horda en Roca Oculta.', },
  },
  [78] = {
    'La leyenda de Stalvan',
    {'Sé de alguien que probablemente podrá ayudarte. Cuando yo comandaba la guardia de Ventormenta, iba con mis hombres a beber al Mesón del Cuervo Escarlata de Villa Oscura. El tabernero, Smitts, era todo un experto en las tradiciones de la zona. Enséñale esta página y escucha lo que te pueda decir sobre ella.', },
    {'Lleva la página de diario borrada al tabernero Smitts a Villa Oscura, en el Bosque del Ocaso.', },
  },
  [79] = {
    'La leyenda de Stalvan',
    {'Seguí la leyenda del tal Stalvan durante años. Hace unos años, cuando asesinaron a aquellos nobles, yo fui con Haggard a investigar el asunto. Encontré estas páginas llenas de barro, pero nunca conseguimos relacionar la caligrafía con ese lunático. Tus pruebas demuestran su culpabilidad. Lleva esto a la comandante Cerranegro de inmediato e infórmale de lo que has descubierto.', },
    {'Lleva la página embarrada a la comandante Cerranegro.', },
  },
  [80] = {
    'La leyenda de Stalvan',
    {'Estuve vigilando a ese asqueroso de Stalvan durante mucho tiempo. Si está página fue escrita por la misma mano... tenemos una prueba de su culpabilidad más allá de una duda razonable.|n|nEl secretario Daltry, a lo largo de sus años en el registro, se ha convertido en un experto calígrafo. Muéstrale esta página y pídele que compruebe si la caligrafía coincide con la de la firma del registro.', },
    {'Enseña la página del diario manchada de sangre al secretario Daltry.', },
  },
  [81] = {
    'Entrega el calimocho',
    {'He puesto la caja de calimocho y las otras botellas que se lleva Dran en el barril para que no se muevan. Él no me cae muy bien, pero la verdad es que no hay nada peor que el calimocho agitado.|n|nLlévale el barril a su local en Orgrimmar. Y transmite mi afectuoso saludo a Malton; dile que si alguna vez tiene sed de bebida y de buena compañía, nos honraría mucho su visita.', },
    {'Entrega el barril a Dran Droffers en Orgrimmar.', },
  },
  [82] = {
    'Investigación en la Guarida Ponzoñosa',
    {'A ver, en cuanto a estos informes sobre los bichos... lo que sabemos es que están drenando las pozas de agua que antes estaban donde se ubica La Guarida Ponzoñosa. Lo que NO sabemos es... bueno, todo lo demás.|n|n¡Descubramos en primer lugar a quién nos enfrentamos! Quiero que vayas a La Guarida Ponzoñosa y que obtengas algunos trozos de esos bichos. Consigue 5 trozos de centipaar y llévaselos al alquimista Morterozugg para que se encargue de ellos. Con su ayuda podremos descubrir qué son.', },
    {'Llévale 5 trozos de insectos centipaar de La Guarida Ponzoñosa al alquimista Morterozugg de Gadgetzan.', },
  },
  [83] = {
    'Pañuelos de lino rojo',
    nil,
    nil,
  },
  [84] = {
    'Vuelve con Billy',
    {'Aquí tienes. Y cuando le des el pastel a Billy, ¡dile que espero que se atragante con él!', },
    {'Lleva el pastel de tripa de cerdo a Billy Maclure a Los Viñedos de Maclure.', },
  },
  [85] = {
    'El collar perdido',
    {'He perdido mi collar... creo que me lo robó ese granuja de Billy Maclure. Normalmente pasa el día escondido como una rata en Los Viñedos de Maclure, al este de aquí.|n|nRecupera mi collar y darás una alegría al corazón de una anciana viuda.', },
    {'Habla con Billy Maclure.', },
  },
  [86] = {
    'Un pastel para Billy',
    {'Si me das un pastel, puede que te diga quién tiene el collar. Bernice, esa anciana de la otra granja, hace unos pasteles de tripa de cerdo increíbles...|n|nSi le llevas algo de carne de jabalí tierna de los jabalíes que rondan por nuestras granjas, y le dices para qué es, seguro que te hace un pastel.', },
    {'Lleva 4 carnes de jabalí tiernas a la tía Bernice Pedregosa a La Granja Pedregosa.', },
  },
  [87] = {
    'Dientes de Oro',
    {'Estaba jugando cerca de la Mina Abisal y creo que se me cayó... esto... quiero decir, creo que vi el collar de la señora. No me preguntes cómo llegó allí... ¡Yo no fui!|n|nPues eso, que vi a un enorme kóbold con dientes de oro que lo recogía y volvía corriendo a su cubil, encima de la mina. Si encuentras a ese kóbold, encontrarás el collar, ¡lo juro!', },
    {'Lleva el collar de Bernice a tía Bernice Pedregosa a La Granja Pedregosa.', },
  },
  [88] = {
    '¡Princesa debe morir!',
    {'Los Brackwell tienen una cerda que ganaría cualquier concurso. Se llama Princesa. Está ENORME, ¡y es gracias a mí! ¡Porque se alimenta de mis verduras!|n|n¡Princesa debe morir antes de que llegue a nuestros campos! Tráeme su collera como prueba de que está muerta y te daré algo para recompensarte.|n|nPrincesa suele estar justo en medio de nuestro campo de sandías. ¡Ve a por ella!', },
    {'Mata a Princesa, coge su collera y llévasela a la vieja Pedregosa a La Granja Pedregosa.', },
  },
  [89] = {
    'El puente sempiterno',
    {'Durante la última invasión orca tuvimos que usar todo el hierro para fabricar balas, espadas y armaduras. Hicimos un pedido de materia prima a Ventormenta, pero unos gnolls Crestagrana secuestraron la caravana y se ocultaron en las colinas de detrás de Villa del Lago.|n|nY ahora estamos sin material para reconstruir el puente. Te recompensaré, $N, si me traes 5 picas y 5 remaches de hierro.|n|nVenga, ¡a trabajar!', },
    {'Lleva 5 picas y 5 remaches de hierro al supervisor Olento a Villa del Lago.', },
  },
  [90] = {
    'Kebab de lobo sazonado',
    {'¡El kebab de lobo sazonado es el especial de la casa! ¡Claro que te puedo preparar un poco! Pero necesitaré algunos productos. Tráeme 10 ijadas magras de lobo y algunas hierbas aromatizadas de Ventormenta. En el bosque hay muchísimos lobos; encontrar ijadas no será un problema. Para las hierbas, busca a Felicia Gump. Tiene una floristería en el distrito de Los Canales de Ventormenta.', },
    {'Reúne 10 ijadas magras de lobo y hierbas aromáticas de Ventormenta y vuelve a Villa Oscura, a ver al Chef Grual.', },
  },
  [91] = {
    'Ley de Solomon',
    {'Se ha instalado un enemigo de Ventormenta en las laderas orientales de Crestagrana. Ese bellaco usa lo arcano para extender el terror entre nuestra gente. Se oculta bajo el nombre de Morganth.|n|nHa esclavizado al clan gnoll Pielsombra. De acuerdo con las leyes de Villa del Lago, asistir a un enemigo del Reino está penado con la muerte.|n|n¡Esos miserables gnolls deben morir!|n|nTráeme diez colgantes Pielsombra y te recompensaré.', },
    {'Lleva 10 colgantes Pielsombra a Bailiff Conacher al Concejo de Villa del Lago.', },
  },
  [92] = {
    'Estofado Crestagrana',
    {'Me encantaría prepararte un estofado Crestagrana. Pero tengo un problemita; durante los disturbios con los orcos alimenté a toda la guarnición de Ventormenta. No me queda nada en la despensa, pero si tú me traes los ingredientes, cocinaré para ti.|n|nTráeme cinco filetes de carne de cóndor dura, cinco morros de dentosangre grandes y cinco raciones de carne de araña crujiente.', },
    {'El chef Breanna de Villa del Lago quiere 5 piezas de carne de cóndor dura, 5 morros de dentosangre grandes y 5 raciones de carne de araña crujiente.', },
  },
  [93] = {
    'Pasteles de cangrejo oscuro',
    {'Te voy a contar un secreto: ¡los pasteles de "cangrejo" oscuro, en realidad se hacen con patas de araña! Sé que es un poco asqueroso, pero las patas de araña son muy sabrosas y los pasteles quedan estupendos. Tráeme patas pegajosas de araña y yo te preparo algunos pasteles.|n|nHe oído que las arañas de hilo venenoso son las mejores para cocinar. Están al norte, entre las laderas de las colinas y el río.', },
    {'Reúne 6 patas pegajosas de araña y llévaselas al Chef Grual a Villa Oscura.', },
  },
  [94] = {
    'Un ojo vigilante',
    {'Mi rival, Morganth, es un malvado mago de gran poder que vive en la Torre de Ilgalar, en Crestagrana. He creado un dispositivo que me permitirá espiar sus movimientos: el Ojo de Azora. Ahora puedo verlo desde lejos.|n|nPero no puedo saber lo que piensa... Necesito más ayuda.|n|nSi quieres ayudarme tú, lleva mi Glifo de Azora a la Torre de Ilgalar. Colócalo sobre la Estatua Leonida, cerca de la Torre.|n|nCuando lo hayas hecho, el poder de Azora me permitirá ver los planes de Morganth para el futuro.', },
    {'Lleva el Glifo de Azora a la Estatua Leonida, cerca de la Torre de Ilgalar, en Crestagrana.', },
  },
  [95] = {
    'La venganza de Sven',
    {'Yo antes trabajaba en una granja al sureste... hasta que un día que tuve que ausentarme, los Jinetes Oscuros del Paso de la Muerte arrasaron mi granja y asesinaron a mi familia.|n|nCuando regresé vi una figura misteriosa cerca de mi granero... enterrando algo. Huyó antes de que pudiera llegar a él y tampoco quería entretenerme: quería ir tras los Jinetes Oscuros. Así que nunca descubrí qué se escondía allí.|n|nTe agradecería que encontraras lo que enterró aquella figura misteriosa. El lugar en el que debes buscar está detrás del tocón que hay cerca de mi granero.', },
    {'Ve a la granja de Sven y averigua qué había enterrado detrás del viejo tocón.', },
  },
  [96] = {
    'La llamada del agua',
    {'Llevar fragmento. Llevar fragmento y dar vida.|n|nDar vida y entender. Entender que el agua es vida... la corrupción acaba con la vida.|n|nDas vida y la proteges con el poder del agua.', },
    {'Llévale el fragmento de agua a Islen Vidente del Agua al Escalón de la Marea, en Los Baldíos.', },
  },
  [97] = {
    '[DEPRECATED]La leyenda de Stalvan',
    {'¡Informa de inmediato a la comandante Cerranegro de que las caligrafías coinciden, $N! ¡Sus sospechas han resultado ser ciertas!', },
    {'Informa a la comandante Cerranegro.', },
  },
  [98] = {
    'La leyenda de Stalvan',
    {'Stalvan Mantoniebla llevó una vida de depravación. Su mano sesgó innumerables vidas inocentes. Es, sin duda alguna, culpable de incontables crímenes. Ahora ese lunático amenaza Villa Oscura. Solo la Luz sabe qué sórdidas acciones está planeando. Debes ejecutar a Stalvan, $C. Lo encontrarás en su casa, al norte de la ciudad.|n|nCuando lo hayas hecho, busca a Lady Eva y enséñale este anillo familiar. Después de todo, fue su premonición lo que nos guió a este terrible descubrimiento. Gracias a ella, Villa Oscura ahora es más segura.', },
    {'Mata a Stalvan Mantoniebla y muestra a Lady Eva su anillo familiar.', },
  },
  [99] = {
    'La locura de Arugal',
    {'Según aumenta mi conocimiento sobre la magia de Arugal, aumenta también mi desdén por el desafortunado necio. Estoy a punto de completar la investigación de su Remedio... Bonito nombre...|n|nMi conocimiento será completo cuando descubra qué encantamiento está causando el extraño comportamiento en la Aldea Piroleña. Por el día, los aldeanos parecen ser humanos. Pero, cuando el sol desaparece, se convierten en huargen Furia Lunar.|n|nNecesito extraer energía de los grilletes encantados que Arugal utilizó con ellos. Tráeme seis grilletes de Piroleña encantados, $N.', },
    {'Lleva 6 grilletes de Piroleña a Dalar Tejealba en El Sepulcro.', },
  },
  [100] = {
    'La llamada del agua',
    {'Hay un destello de luz cuando pronuncias las últimas palabras del conjuro. Se desvanece el sonido de las gotas de agua sobre la llama y la emoción embarga tus sentidos conforme se aniquilan los espíritus corruptos que te rodean.', },
    {'Habla con la manifestación de agua menor en la Cala Mareanorte, en el Bosque de Argénteos.', },
  },
  [101] = {
    'El Tótem de castigo',
    {'A medida que la corrupción mística invade el bosque, la necesidad de autoprotección se hace innegable, $N. El viento me susurra y me cuenta de grandes peligros que el futuro te depara.|n|nSi deseas protegerte, noble $C, tráeme 10 colmillos de necrófago, 10 dedos de esqueleto y 5 viales de veneno arácnido. Te encantaré un tótem de castigo que dañará a aquellos que intenten causarte daño a ti.', },
    {'Consigue 10 colmillos de necrófago, 10 dedos de esqueleto y 5 viales de veneno arácnido para Lady Eva en Villa Oscura.', },
  },
  [102] = {
    'En patrulla por los Páramos de Poniente',
    {'Ventormenta nos ha abandonado. Nauseabundos aires de depravación soplan por las llanuras de los Páramos de Poniente. Este era mi hogar y no daré la espalda a los ciudadanos que decidieron permanecer aquí. Nosotros, los antiguos granjeros, ofreceremos resistencia.|n|nTu tarea, si decidieras aceptar, consistirá en patrullar las praderas de los Páramos de Poniente. Localiza y aniquila a los infames gnolls que parecen colaborar con los ladrones de Las Minas de la Muerte. Tráeme 8 garras de gnoll y sabré recompensar tu valentía.', },
    {'Lleva 8 garras de gnoll al capitán Danuvin en la Colina del Centinela.', },
  },
  [103] = {
    'Guardián de la Llama',
    {'La noche en que murió la familia del guardián del Faro fue horrible. Contemplé, impotente, cómo el Viejo Ojosombrío lideraba el ataque. Pero lo pasado, pasado está, y lo que ahora me preocupa son las vidas de los que navegan por el Mare Magnum y se acercan demasiado a las peligrosas rocas de la costa. Como no hay nadie que vigile la llama, la responsabilidad es ahora mía.|n|nAyúdame a mantener la antorcha iluminada trayéndome 5 botellas de aceite de los monstruos de la cosecha.', },
    {'Lleva 5 botellas de aceite al capitán Grisillo en el Faro de Poniente.', },
  },
  [104] = {
    'La amenaza costera',
    {'Cuando acabó mi vida contra las rocas, no tenía ni idea de lo que me esperaba en el más allá. El Faro estaba sumido en la oscuridad aquella noche, ya que el Viejo Ojosombrío había asustado a la familia del guarda. Lograron regresar y volver a encender la llama, pero el Viejo Ojosombrío coaccionó a los múrlocs de mente más débil para que asaltaran el Faro con él de nuevo. La segunda vez, la familia no corrió la misma suerte y pereció inútilmente ante mis ojos.|n|nMata al Viejo Ojosombrío si lo ves por la costa y tráeme una de sus escamas, te recompensaré.', },
    {'Lleva una escama del Viejo Ojosombrío al capitán Grisillo en el Faro de Poniente.', },
  },
  [105] = {
    'Ah, Andorhal',
    {'¡Ay, se acerca el momento de atacar Andorhal y de hacer salir al exánime que lo controla!|n|nEs en el interior de las ruinas de la ciudad donde el exánime, Araj el Invocador, tiene sus dominios. Está custodiado por numerosos miembros de la Plaga que rodean los restos del centro de la ciudad, y su séquito personal de guardianes es realmente formidable. Necesitarás muchos aliados para tener alguna oportunidad de enfrentarte a él con éxito.|n|n¡Acaba con Araj, $N, y tráeme un trozo de su filacteria como prueba!', },
    {'Lleva el trozo de filacteria de Araj al sumo ejecutor Derrington en El Baluarte en las Tierras de la Peste del Oeste.', },
  },
  [106] = {
    'Jóvenes enamorados',
    {'¡Oh, estoy maldita! He entregado mi corazón a Tommy Joe Pedregosa, pero nuestras familias se odian a muerte. Así que no puedo verlo, ¡aunque me duelan los ojos por no poder mirar su hermoso rostro!|n|nTe lo ruego, lleva esta carta a Tommy Joe. Suele estar en el río que está al oeste de La Granja Pedregosa, al oeste de aquí.', },
    {'Entrega a Tommy Joe Pedregosa la carta de amor de Maybell.', },
  },
  [107] = {
    'Una nota para William',
    {'¡Seguro que William Mortero tiene una poción que reúna a los dos jóvenes amantes!|n|nTen, llévale esta nota a William. Está en la Posada Orgullo de León, en Villadorada.', },
    {'Lleva la nota de la Abuela Pedregosa a William Mortero.', },
  },
  [108] = {
    '<TXT> Mystery Reward',
    nil,
    nil,
  },
  [109] = {
    'Habla con Gryan Mantorrecio',
    {'Parece que has visto bastantes combates en tu vida, $C. Si no has tenido suficiente, busca a Gryan Mantorrecio. Comanda la Milicia Popular que protege las granjas de los Páramos de Poniente. Seguro que le vendrá bien tu ayuda. Puedes encontrarlo en la torre de piedra de la Colina del Centinela, saliendo de la carretera que cruza los Páramos de Poniente.', },
    {'Habla con Gryan Mantorrecio. Puedes encontrarlo en la torre de piedra de la Colina del Centinela, saliendo de la carretera que cruza los Páramos de Poniente.', },
  },
  [110] = {
    'Análisis de trozos de insecto',
    {'Voy a estudiar el equipo de análisis de Patagolpe y a ordenar sus efectos personales. Tengo la extraña sensación de que esta no es la última pérdida que sufriremos ante estos bichos.|n|nQuiero que vayas a ver al alquimista Morterozugg y compruebes si ya ha tenido oportunidad de procesar los trozos de insecto que le enviamos. Si es así, vuelve aquí.', },
    {'Busca al alquimista Morterozugg en Gadgetzan y comprueba su análisis de los trozos de insecto.', },
  },
  [111] = {
    'Habla con la abuelita',
    {'Por favor, $N, habla con mi abuelita. Si alguien puede encontrar la forma de reunirme con Maybell, esa es ella.|n|nEstá en nuestra casa, al este de aquí.', },
    {'Habla con la Abuela Pedregosa.', },
  },
  [112] = {
    'La recolección de algas',
    {'Puedo hacer un licor de invisibilidad para Maybell, para que pueda salir de Los Viñedos de Maclure y reunirse con Tommy Joe. Pero para hacer el licor necesito alga de cristal.|n|nAunque el alga normalmente crece en el océano, también se puede conseguir de los múrlocs. Ve a ver si los múrlocs que hay cerca del Lago de Cristal tienen algo. El Lago de Cristal está al este de Villadorada.', },
    {'Lleva 4 hojas de alga de cristal a William Mortero a Villadorada.', },
  },
  [113] = {
    'Análisis de trozos de insecto',
    {'El perito jefe Picoflojo tiene que ver este informe inmediatamente. En realidad... todo el que sepa leer debería echarle un vistazo. Nos enfrentamos a una grave y seria amenaza no solo para Tanaris y Gadgetzan, sino también para toda la zona meridional de Kalimdor si no le ponemos solución pronto. ¡Qué diablos! Incluso es posible que afecte a la totalidad de Azeroth pues no hay ningún indicio de que vaya a mejorar la situación.|n|nPídele a Picoflojo una copia del informe para poder distribuirlo. ¡Todos deben conocer la existencia de esta amenaza!', },
    {'Entrégale el informe al perito jefe Picoflojo de Gadgetzan. Asegúrate de que te da una copia del informe, tal y como el alquimista Morterozugg ha pedido.', },
  },
  [114] = {
    'La fuga',
    {'Lleva este licor de invisibilidad a la joven Maybell. Debería durar lo suficiente para que haga una visita a Tommy Joe.', },
    {'Lleva el licor de invisibilidad a Maybell Maclure.', },
  },
  [115] = {
    'Magia de las Sombras',
    {'Los Roca Negra han traído taumaturgos oscuros a los ataques en Crestagrana. Tienen unos objetos de poder oscuro, los orbes de medianoche. Estos orbes han malherido a muchos de los que luchan en Crestagrana; tenemos que hacernos con esos objetos demoníacos.|n|nTráeme los orbes de medianoche de los cadáveres de taumaturgos umbríos Roca Negra. Me encargaré de destruirlos; el mundo estará mejor sin ellos.', },
    {'Lleva 3 orbes de medianoche al alguacil Marris a Villa del Lago.', },
  },
  [116] = {
    'Tiempos de sequía',
    {'Tengo un problema, $N. Nos estamos quedando sin bebida y el envío se está retrasando mucho. Esta invasión orca ha sido terrible.|n|n¿Buscas trabajo?|n|nNecesito que vayas a recoger un barril de cerveza Cebatruenos de Tragoamargo Cebatruenos, que está en las colinas de los Páramos de Poniente, uno de Merlot en Ventormenta, una botella de licor de luna en Villa Oscura y una de ron dulce en Villadorada. Tráeme todo eso y te ganarás una recompensa.', },
    {'Lleva 1 barril de cerveza Cebatruenos, 1 barril de vino dulce, 1 botella de licor de luna y 1 botella de ron dulce al posadero Daniels a Villa del Lago.', },
  },
  [117] = {
    'Cerveza Cebatruenos',
    {'Rápido, $Gamigo:amiga; y date prisa|nNuestra cerveza está de risa|nMás cerveza y menos comida,|nDadnos lúpulo para hacer birra.', },
    {'Entrega a Tragoamargo Cebatruenos 5 lúpulos para que pueda terminar su cerveza especial.', },
  },
  [118] = {
    'El precio de unas herraduras',
    {'¡He necesitado tanto hierro para abastecer a la guardia de Ventormenta que no tengo bastante para hacer herraduras!|n|nVe a Villadorada y dale esta nota al herrero Argus; le cuento mi problema y le hago un pedido de herraduras.', },
    {'Lleva la nota de Verner al herrero Argus a Villadorada, en el Bosque de Elwynn.', },
  },
  [119] = {
    'Regresa junto a Verner',
    {'Muy bien, 50 herraduras...|n|n¡Aquí las tienes, listas para llevar! Dile a Verner que ha sido un placer y que lea la nota que he pegado a la caja.', },
    {'Vuelve a Villa del Lago, en Crestagrana, y entrega la caja de herraduras a Verner Osbien.', },
  },
  [120] = {
    'Mensajero a Ventormenta',
    {'Estamos en tiempos difíciles, $C. Vivimos bajo un asedio constante. Si no llegan refuerzos, solo nos queda la derrota. El mensaje que te confío es de la mayor importancia. Llévaselo al general Marcus Jonathan de Ventormenta inmediatamente. Después vuelve, ya sean tus noticias buenas o malas.|n|n¡Apresúrate!', },
    {'El magistrado Solomon te ha dado un informe para el general Marcus Jonathan de Ventormenta. Quiere que vuelvas en cuanto lo hayas entregado.', },
  },
  [121] = {
    'Mensajero a Ventormenta',
    {'Mientras espero la respuesta del Rey, llévale esta carta al magistrado Solomon.|n|nPuedes retirarte, $C.', },
    {'Lleva la respuesta del general Marcus Jonathan al magistrado Solomon a Villa del Lago.', },
  },
  [122] = {
    'Escamas de barriga',
    {'Necesito escamas de barriga de cachorro de dragón Negro para pagarle las herraduras que Argus me envió desde Villadorada. Si me traes 6 escamas, tendré para pagarle y también para hacerte un regalo.|n|nEsos bichos vuelan al sur de Villa del Lago, pero a menudo se alejan. Tendrás que estar ojo avizor para cazarlos en cuanto los veas.', },
    {'Lleva 6 escamas de barriga de cachorro de dragón Negro a Verner Osbien a Crestagrana.', },
  },
  [123] = {
    'El Coleccionista',
    {'Esta nota es una horario de los días y las horas a las que una persona –descrita como "el Coleccionista"– recibirá cargamentos de oro provenientes de las minas del Bosque de Elwynn.|n|nPor lo que pone en el horario, parece que el Coleccionista vive cerca de la Plantación de Calabazas de Brackwell, al este de Elwynn.|n|nParece importante. Deberías informar al alguacil McCree en el Aserradero de la Vega del Este.', },
    {'Ve a ver al alguacil McCree en el Aserradero de la Vega del Este y dale la lista del coleccionista.', },
  },
  [124] = {
    'El aullido de los gnolls',
    {'¡Como si no tuviera bastante con los orcos! Ahora tengo toscos y místicos gnolls en la cresta que hay al norte de mi establo y se llevan mis caballos cuando se pierden.|n|nSi nos libras de los gnolls, mis caballos y yo te lo agradeceremos eternamente.', },
    {'Mata a 10 toscos y 8 místicos Crestagrana y ve a ver a Verner Osbien.', },
  },
  [125] = {
    'Las herramientas perdidas',
    {'Échame una mano, $N. Con todo esto del asedio, es difícil conseguir suministros. Mis herramientas venían de camino de Villadorada, pero hicieron explotar el puente. Pusimos las herramientas en una barca, pero los orcos atacaron con una catapulta y todo acabó en el fondo del lago.|n|nRecupera mi caja de herramientas, $N, y te ganarás una buena recompensa.', },
    {'El supervisor Olento de Villa del Lago quiere que recojas su caja de herramientas del fondo del Lago Sempiterno.', },
  },
  [126] = {
    'El aullido de las colinas',
    {'$N, los gnolls siguen ahí. Los oigo aullar mientras cazan en las colinas de Villa del Lago. El que más fuerte aúlla es Ululante, el jefe.|n|n¡Mátalo! ¡Su manada se asustará y huirá! Tráeme su garra como prueba.|n|nY ten cuidado; si es el jefe, será por algo. Ya sabes lo que dicen de los perros viejos.', },
    {'Lleva la zarpa de Ululante a Verner Osbien a Villa del Lago.', },
  },
  [127] = {
    'Pescado a la venta',
    {'El Lago Sempiterno es famoso por su pez luna moteado. Tiene mucha demanda, ¡pero me estoy quedando sin existencias!|n|nTráeme 10 peces luna moteados; te pagaré bien. Y si no sabes pescar, intenta robárselo a los múrlocs.', },
    {'Lleva 10 peces luna moteados al maestro de embarcadero Baren a Villa del Lago.', },
  },
  [128] = {
    'La recompensa de Roca Negra',
    {'Tenemos que acabar con esos Roca Negra. El enemigo ha invadido nuestra tierra. Estas montañas pertenecen al rey de Ventormenta. Nuestras fuentes nos dicen que el jefe de cada unidad del clan se llama Campeón. Encontrarás su campamento hacia el norte, justo al oeste del camino a Las Estepas Ardientes.|n|nEl magistrado Solomon quiere que mueran. Acaba con 15 Campeones Roca Negra y vuelve a verme.', },
    {'Mata a 15 campeones Roca Negra y el guardia Howe te recompensará en Villa del Lago.', },
  },
  [129] = {
    'Una comida gratis',
    {'¿Puedes hacerme un favor? Le he preparado la comida al guardia Parker, pero ha salido de patrulla. Es un guardia de Ventormenta grande y fuerte que puede defenderse, pero para mí es demasiado peligroso.|n|n¡Si le llevas la comida, cuando vuelvas te invitaré a comer! ¿Qué me dices? Está de patrulla en el camino a Bosque del Ocaso.', },
    {'Llévale su comida al guardia Parker. Está de patrulla en el camino a Villa Oscura.', },
  },
  [130] = {
    'Una visita al herborista',
    {'¿Te importa entregarle unas flores a Darcy de mi parte? Cómpralas en el herbolario de Villa del Lago, en el extremo oeste de la ciudad.|n|nPero no vayas a decir en la tienda para quién son o quién las envía...', },
    {'Habla con Martie Jainrose, la herborista de Crestagrana.', },
  },
  [131] = {
    'Un ramo de narcisos',
    {'Aquí tienes el ramo. Lo he hecho de narcisos, mis flores favoritas.', },
    {'Dale el ramo de narcisos a Darcy.', },
  },
  [132] = {
    'La hermandad de los Defias',
    {'Lo que voy a contarte puede costarme la vida. La banda Defias está preparando algo grande. Lo último que oí fue que estaban colaborando con varios gnolls, kóbolds e incluso goblins.|n|nLlévale esta nota a Mantorrecio. Explica todo lo que sé sobre este asunto.', },
    {'Lleva la Nota de Wiley a Gryan Mantorrecio en los Páramos de Poniente.', },
  },
  [133] = {
    'Un espantapájaros para necrófagos',
    {'Vivo tan lejos de la protección de la ciudad que es un milagro que los necrófagos y los muertos andantes no me hayan devorado. ¡De hecho, ayer, sin ir más lejos, una manada de Mascahuesos intentó tirar abajo las paredes de mi casa!|n|nQuiero hacer un monigote... una especie de espantapájaros para necrófagos. Y para hacerlo necesito costillas de necrófago. Puedes conseguirlos de comecarnes, Mascahuesos, comesesos, podridos y propagadores de peste.|n|nConsígueme esas costillas y yo te pagaré.', },
    {'Reúne 7 costillas de necrófago y llévaselas a Abercrombie a su cabaña.', },
  },
  [134] = {
    'Ladrones ogros',
    {'Hace unas pocas semanas, mientras recogía hierbas lejos de mi casa, me atacó una manada de ogros. Huí a toda prisa y tuve que dejar atrás un cajón lleno de valiosas herramientas y hierbas.|n|nLos ogros volvieron a su túmulo del sur del Bosque del Ocaso pavoneándose de su hazaña. Tengo la seguridad de que mi cajón está cerca de ese túmulo.|n|nPor favor, $N, recupera ese cajón, lo necesito.', },
    {'Devuelve a Abercrombie el cajón de Abercrombie.', },
  },
  [135] = {
    'La hermandad de los Defias',
    {'Me pregunto qué querría decir Wiley cuando habló de los Albañiles. Quizás fue un lapsus. ¿Podría estar relacionada la banda Defias con los Albañiles? El único que podría saberlo es Mathias Shaw, líder del IV:7. Enséñale la nota de Wiley, tal vez tenga algo que añadir a este misterio. Si tienes problemas para encontrarlo, busca en el Cuartel, en el Casco Antiguo.', },
    {'Lleva la Nota de Wiley a Mathias Shaw de Ventormenta.', },
  },
  [136] = {
    'El tesoro escondido del capitán Sanders',
    {'Si estás leyendo esto, el capitán Sanders estará sepultado bajo el agua. Así que mi tesoro es tuyo, solo tienes que seguir las pistas.|n|nPrimero tienes que encontrar mi baúl. Seguramente estará enterrado en la arena, en la costa Oeste de los Páramos de Poniente, cerca de los restos de naufragios. Habrá muchos restos, pero solo un ancla oxidada en la costa. ¡Encuentra el ancla y encontrarás mi baúl! Allí encontrarás también la siguiente pista.', },
    {'Encuentra el baúl del capitán Sanders y busca la siguiente pista.', },
  },
  [137] = {
    '<NYI> <TXT> Mención honorífica de Ventormenta',
    {'Si consigues una mención de honor de uno de nuestros Mariscales, tráemela. Será útil para uno de nuestros guantes del Emblema del León.', },
    {'El general Marcus Jonathan en Ventormenta aceptará una mención honorífica del Bosque de Elwynn. Si le entregas ese documento, como recompensa, podrás elegir una armadura.', },
  },
  [138] = {
    'El tesoro escondido del capitán Sanders',
    {'Esto es lo que dice la siguiente pista: ¡Buen trabajo, compañero! Ahora tienes que ir al Este. Al Este hacia los riscos, al Este hacia el camino. Busca las ruinas de chimeneas a orillas del camino. Allí encontrarás un viejo barril con la siguiente pista.', },
    {'Busca el viejo barril junto a la chimenea en ruinas y busca la siguiente pista.', },
  },
  [139] = {
    'El tesoro escondido del capitán Sanders',
    {'Buscando en el barril descubres otro fragmento de papiro. En este se puede leer: Desde este barril, ve hacia el Norte. Tan recto como vuela el cuervo, anda hasta que veas una jarra vacía junto al solitario molino de viento sobre los riscos del mar. Si buscas alrededor de la jarra encontrarás lo que estás buscando.', },
    {'Busca la jarra vacía junto al molino de viento para encontrar la siguiente pista.', },
  },
  [140] = {
    'El tesoro escondido del capitán Sanders',
    {'Ciertamente, dentro de la vieja jarra hay otra pista sobre el tesoro de Sanders. La tinta se ha borrado en algunas partes y el papel huele a whisky, pero aún puedes entender algo: Ahora que has encontrado mi vieja jarra de whisky ¡casi has llegado al tesoro! Dirígete hacia el Oeste desde la botella y baja hasta la costa. Cuando llegues al agua, ¡sigue adelante! ¡Nada directo hacia el Oeste hasta encontrar la isla con la arqueta!', },
    {'Localiza la arqueta del capitán Sanders y ábrela para obtener tu recompensa.', },
  },
  [141] = {
    'La hermandad de los Defias',
    {'La Hermandad de los Albañiles estaba dirigida por un tal Edwin VanCleef. VanCleef fue responsable de la reconstrucción de Ventormenta cuando la ciudad fue arrasada por los orcos en la Primera Guerra. Al parecer, VanCleef y sus hombres no estaban satisfechos con el tratamiento que les brindó el rey cuando terminó la reconstrucción. Pero eso solo explicaría algunas cosas.|n|nHe redactado un informe más detallado para tu maestro en los Páramos de Poniente. ¡Llévaselo de una vez!', },
    {'Lleva el informe de Shaw a Gryan Mantorrecio de los Páramos de Poniente.', },
  },
  [142] = {
    'La hermandad de los Defias',
    {'Tenemos que descubrir la localización de la Ladronera Defias. $N, según los informes de mi explorador se ha visto a un mensajero Defias en los caminos entre el Arroyo de la Luna, la Mina de la Costa del Oro y la Mina de Jango. Quiero que le captures. Si ofrece resistencia, mátalo y tráeme lo que esté llevando.', },
    {'Localiza al mensajero Defias de los Páramos de Poniente y lleva su mensaje a Mantorrecio.', },
  },
  [143] = {
    'Mensajero a los Páramos de Poniente',
    {'En el ejército de Ventormenta pasa algo raro; ya deberían haber llegado. No tenemos tiempo que perder. No voy a quedarme a mirar cómo se sacrifica la gente de Villa del Lago sin intentar conseguir ayuda. He oído que en los Páramos de Poniente se ha formado una Milicia Popular.|n|nLleva nuestra súplica a su jefe, Gryan Mantorrecio; puede que sus hombres nos ayuden hasta que llegue la Reserva.', },
    {'El magistrado Solomon quiere que lleves su petición a Gryan Mantorrecio a los Páramos de Poniente.', },
  },
  [144] = {
    'Mensajero a los Páramos de Poniente',
    {'Me duele leer la nota del magistrado Solomon. Evidentemente, no sabe que hay guerra en los Páramos de Poniente, si no, no pediría ayuda a la Milicia. Si Ventormenta no nos hubiera abandonado también a nosotros, no necesitaríamos una milicia.|n|nLlévale la respuesta a tu señor en Crestagrana, $C. Dile que lamento la pérdida de tantos hombres buenos.', },
    {'Lleva la respuesta de Gryan Mantorrecio al magistrado Solomon.', },
  },
  [145] = {
    'Mensajero a Villa Oscura',
    {'Necesito tu ayuda una vez más. He escrito a Lord Cerranegro para pedir que mande a su Guardia Nocturna como refuerzo de la defensa de Villa del Lago. Es imprescindible que reciba este mensaje cuanto antes, pero debes ser extremadamente prudente. Cerranegro es el alcalde de Villa Oscura, en pleno corazón del Bosque del Ocaso. No te salgas de los caminos.', },
    {'El magistrado Solomon quiere que lleves una carta a Lord Cerranegro a Villa Oscura.', },
  },
  [146] = {
    'Mensajero a Villa Oscura',
    {'Si no conociera a Solomon, diría que se ha vuelto loco. ¿Que envíe a La Guardia Nocturna a Villa del Lago porque Ventormenta no envía ayuda? La Guardia Nocturna se creó porque Ventormenta nos abandonó cuando nos infestó esta magia inmunda. Si envío a la Guardia, esta ciudad sería invadida antes de que mis guardias lleguen al Linde del Bosque.|n|nLlévale la respuesta a tu señor en Villa del Lago.', },
    {'Lleva la respuesta de Lord Cerranegro al magistrado Solomon.', },
  },
  [147] = {
    'La persecución',
    {'Si el Coleccionista se está llevando oro de nuestras minas, ¡está robando al Rey! Lleva al Coleccionista ante la justicia. Y tráeme a mí el anillo que se mencionaba en la nota. Podría indicarnos para quién trabaja el Coleccionista...|n|nLa nota dice que el Coleccionista se esconde en la Plantación de Calabazas de Brackwell. Deberías buscarlo allí."', },
    {'Encuentra y mata al Coleccionista y vuelve junto al alguacil McCree con la sortija del coleccionista.', },
  },
  [148] = {
    'Suministros de Villa Oscura',
    {'Ay, ¿qué puede hacer un anciano como yo? Necesito suministros de Villa Oscura, pero está tan lejos y yo soy tan viejo y tan débil... No sobreviviría al viaje.|n|n¿Podrías ir a Villa Oscura y traerme un poco de hilo de cabello de fantasma? Puedes conseguirlo de Lady Eva. Ve a su casa en la plaza de Villa Oscura.', },
    {'Habla con Lady Eva.', },
  },
  [149] = {
    'Hilo de cabello de fantasma',
    {'Mary la Ciega es un desgraciado y triste espíritu que mora en una vieja granja en las colinas del sur de Villa Oscura.|n|nTen, coge este peine espectral y pide a Mary la Ciega que se peine el cabello. Luego tráeme el peine y yo extraeré de él el cabello de fantasma que necesito para crear el hilo.|n|nY ten cuidado... cerca de la casa acechan seres oscuros...', },
    {'Lleva el peine espectral a Mary la Ciega.', },
  },
  [150] = {
    'Cazadores furtivos',
    {'Los múrlocs nos están complicando la vida. Se están instalando en las orillas del Lago Sempiterno y pescan en cantidades increíbles. ¡Tenemos que echarlos o acabarán con todos los peces del lago!|n|n¿Te apetece cazar múrlocs? Tráeme 8 aletas y te llevarás algo a cambio...', },
    {'Lleva 8 aletas múrloc al maestro de embarcadero Baren a Villa del Lago.', },
  },
  [151] = {
    'La pobre y vieja Blanchy',
    {'¡Pobre vieja Blanchy! La bestia está agotada después de todo el trabajo que le dimos. Le di de comer antes de dejar la granja, pero no esperábamos que se rompiera el carro. Si pudieras traerle algunos puñados de avena te estaría muy agradecida.|n|nSeguro que podrás encontrar algunos por las granjas de los Páramos de Poniente, si puedes librarte de esas horribles máquinas que los han invadido. Hay varias granjas al suroeste de aquí.', },
    {'Verna Cejade de los Páramos de Poniente quiere que le lleves 8 puñados de avena.', },
  },
  [152] = {
    'Hay moros en la costa',
    {'Seguramente habrás visto todos los restos de naufragios a lo largo de la costa. El Mare Magnum es traicionero. La costa de los Páramos de Poniente tiene que estar limpia, de ese modo si algún marinero llega hasta nuestras costas, no correrá ningún peligro. Pero los múrlocs son un gran problema.|n|nMata 7 cazamareas, 7 guerreros, 7 oráculos y 7 correcostas y procuraré que seas $Grecompensado:recompensada;.', },
    {'Mata 7 cazamareas, 7 guerreros, 7 oráculos y 7 correcostas y vuelve con el capitán Grisillo en el Faro de Poniente.', },
  },
  [153] = {
    'Pañuelos rojos de cuero',
    {'La tapadera de los Defias cambia constantemente. He estado siguiendo sus movimientos desde hace algún tiempo. Aunque, recuerda, he averiguado que muchos miembros de la banda se identifican por sus pañuelos de cuero rojo.|n|nTráeme 15 de esos pañuelos y procuraré que seas $Grecompensado:recompensada;.', },
    {'Lleva 15 pañuelos de cuero rojo al explorador Galiaan en la Colina del Centinela.', },
  },
  [154] = {
    'Devuelve el peine',
    {'¡¡NO!!|n|n¡Aleja ese peine de mí!|n|n¡Soy un monstruo! ¡Nadie volverá a pensar que soy guapa!', },
    {'Lleva el peine de fantasma a Lady Eva a Villa Oscura.', },
  },
  [155] = {
    'La hermandad de los Defias',
    {'¿Así que Mantorrecio envía a $Gun:una; $R enclenque para protegerme? Supongo que tendrás que hacerlo. Pero será mejor que traigas algunos amigos.|n|n¿Ya conoces el trato, verdad? Tú me guardas las espaldas y yo te llevo hasta la Ladronera Defias. La banda Defias busca mi cabeza, así que si me ven contigo, intentarán matarme.|n|nAvísame cuando tú y los amigos que puedas reunir estéis listos para emprender la marcha.', },
    {'Escolta al Traidor de los Defias a la ladronera secreta de la Hermandad Defias. Cuando el Traidor de los Defias te enseñe dónde se esconden VanCleef y sus hombres, regresa con Gryan Mantorrecio con toda la información.', },
  },
  [156] = {
    'Busca flores podridas',
    {'Si me traes algunas flores podridas, podré prepararte algo de zumo de zombi.|n|nLas flores podridas crecen en lugares extraños. Se dice que se encuentran en el interior de las calaveras de los horrores esqueléticos y de los malignos esqueléticos. Claro que nunca lo he comprobado...|n|nEn el Cementerio del Cerro del Cuervo encontrarás esqueletos de esos a montones. Mientras buscas flores podridas, podrías aprovechar para deshacerte de algunos de ellos. Villa Oscura te estaría muy agradecida.', },
    {'Recoge 8 flores podridas y llévaselas al tabernero Smitts a Villa Oscura.', },
  },
  [157] = {
    'Devolver el pelo',
    {'Aquí tienes tu hilo, $N. Entre muchas otras cosas, sirve para atar espíritus malvados o para coser la vida en objetos inanimados.', },
    {'Lleva el hilo de cabello de fantasma a Abercrombie, a su choza al norte del Cementerio del Cerro del Cuervo.', },
  },
  [158] = {
    'Zumo de zombi',
    {'Necesito una botella de licor. De zumo de zombi. El tabernero Smitts, del Mesón del Cuervo Escarlata de Villa Oscura, debería tener alguna botella.|n|nPor favor, date prisa, $N. ¡Las noches empiezan a ser frías y necesito ese fuego en mis venas!', },
    {'Habla con el tabernero Smitts.', },
  },
  [159] = {
    'Entrega de zumo',
    {'Aquí tienes tu zumo de zombi...|n|nY... ten cuidado con él. ¡Es tan fuerte que resucitaría a un muerto!', },
    {'Lleva el zumo de zombi a Abercrombie a su choza.', },
  },
  [160] = {
    'Nota para el alcalde',
    {'Lleva esta nota a Ello Cerranegro, el alcalde de Villa Oscura.|n|nÉl y yo somos viejos amigos. Seguro que cuando la lea y sepa lo que has hecho por mí... ¡estará tan contento como yo! ¡Ja, ja, ja, ja!', },
    {'Lleva la carta de Abercrombie a Ello Cerranegro, el alcalde de Villa Oscura.', },
  },
  [161] = {
    'Se aproxima una oscura amenaza',
    {'Si mis sospechas son correctas, esto es un tipo de explosivo. Debemos hacerlo analizar por un experto en explosivos para saber qué tenemos exactamente entre manos.|n|nConozco al hombre más adecuado. A Ashlan Risapétrea le asignaron vigilar a los ogros de la Fortaleza de Mo\'Grosh, al este. Ve en esa dirección y encuéntralo para que pueda decirnos qué sustancia es esta.', },
    {'El ingeniero jefe Hinderweir quiere que lleves los polvos al experto en explosivos Ashlan Risapétrea, en la Fortaleza de Mo\'Grosh.', },
  },
  [162] = {
    'La sublevación de los silítidos',
    {'Te ruego que le entregues este informe a alguien que tenga conocimientos de este tema.|n|nConozco a una erudita elfa de la noche llamada Gracina Poderespíritu que ha dedicado mucho tiempo al estudio de los seres vivos que solo se encuentran en Azeroth. ¡Es una historiadora de los pies a la cabeza! Entrégale este informe si quieres que te ayude a entender a qué te enfrentas y, lo más importante, el modo de detener esta amenaza. Necesitaremos ayuda.|n|nLo último que he sabido de ella es que residía en el Templo de la Luna, ubicado en Darnassus.', },
    {'Dirígete a Darnassus y entrégale el informe del análisis del insecto a Gracina Poderespíritu.', },
  },
  [163] = {
    'Cerro del Cuervo',
    {'Algo ocurre en Cerro del Cuervo, $N. Calor jura que alguien –o algo– está rondando los edificios de la zona. Ha visto sombras moviéndose dos noches seguidas y dice que hace tres noches vio luz en una de las ventanas.|n|nSi, como dices, te preocupa la seguridad del Bosque del Ocaso, averigua qué monstruo acecha el Cerro del Cuervo.', },
    {'Averigua qué está acechando Cerro del Cuervo.', },
  },
  [164] = {
    'Entrega a Sven',
    {'¿Conoces a Sven? ¡Pues él sí que trabaja para la Luz! Él y sus seguidores están acampados en la linde noroccidental del Bosque del Ocaso.|n|nPor desgracia, son muy pocos, y no pueden permitirse enviar a nadie a buscar suministros a la ciudad. ¿No podrías llevarles tú estos suministros?', },
    {'Entrega los suministros a Sven.', },
  },
  [165] = {
    'El Ermitaño',
    {'Antes venía por aquí un anciano... venía a comprar suministros con bastante frecuencia, pero hace un tiempo que no lo veo. Vive en una choza cerca del Cementerio del Cerro del Cuervo, si no recuerdo mal. ¿Podrías ir a ver si le ha ocurrido algo?', },
    {'Ve a ver cómo está el anciano de la choza que hay cerca del Cementerio del Cerro del Cuervo.', },
  },
  [166] = {
    'La hermandad de los Defias',
    {'Todavía hay una tarea que debes cumplir. Edwin VanCleef debe ser asesinado. Aunque me entristece condenar a alguien a la pena de muerte, el bien común de las gentes de los Páramos de Poniente exige que VanCleef descanse de una vez por todas. Tráeme la cabeza de ese villano cuando hayas terminado tu hazaña.', },
    {'Mata a Edwin VanCleef y lleva su cabeza a Gryan Mantorrecio.', },
  },
  [167] = {
    'Oh, hermano...',
    {'Estábamos en las profundidades de una gran mina en los Páramos de Poniente, oculta tras un granero en el Arroyo de la Luna. No tenemos ni idea de dónde salieron esos ladrones. En fin, el túnel se derrumbó sobre nosotros. Conseguí salir, pero los otros... bueno... de los otros no sé nada.|n|nCreo que tú podrías tener más suerte ahí abajo. Si pudieras buscar a mi hermano, te lo agradecería mucho. Siempre llevaba su insignia de la Liga de Expedicionarios. Si no puedes encontrarle, al menos la insignia me daría algo de paz mental.', },
    {'Lleva la insignia de la Liga de Expedicionarios del supervisor Cardortiga a Wilder Cardortiga, en Ventormenta.', },
  },
  [168] = {
    'Recolección de recuerdos',
    {'Muchos de mis amigos murieron ese horrible día cuando se derrumbó el túnel de la mina. Si tus aventuras te llevan de casualidad a esa parte de la mina en el Arroyo de la Luna, por favor, busca alguna señal que pueda identificarles. Si te encuentras con alguna de sus Tarjetas del Sindicato Minero, tráemelas y me aseguraré de que sus familias reciban la resolución de este horrible accidente.', },
    {'Recupera 4 Tarjetas del Sindicato Minero y llévaselas a Wilder Cardortiga, en Ventormenta.', },
  },
  [169] = {
    'Se busca: Gath\'Ilzogg',
    {'Se busca a Gath\'Ilzogg por dirigir los ataques Roca Negra al Fuerte de Petravista y las incursiones en Villa del Lago.|n|nGath\'Ilzogg es extremadamente peligroso. Se encuentra en el Fuerte maquinando nuevos crímenes del clan contra la humanidad. Debemos sofocar la infestación de orcos cueste lo que cueste. Se ofrece recompensa a quien presente la cabeza de Gath\'Ilzogg al magistrado Solomon.', },
    {'Mata a Gath\'Ilzogg y lleva su cabeza al magistrado Solomon a Villa del Lago para recibir tu recompensa.', },
  },
  [170] = {
    'Una nueva amenaza',
    {'Espero que estés aquí para echar una mano, $C. Después del último ataque de los troggs, nos vendría bien cualquier ayuda.|n|nHe oído que esos malnacidos han estado apareciendo por todas partes y parece que el Valle de Crestanevada no es una excepción. Han sido vistos en los montes del sureste y cerca del lago helado.|n|nY eso no es todo. Hace unas noches atacaron e invadieron nuestro campamento del oeste.|n|nNecesitamos ayuda, $Gmuchacho:muchacha;. Necesitamos brazos fuertes para hacer retroceder a los troggs.', },
    {'Balir Martilloescarcha quiere que mates a 6 troggs Comepiedras y a 6 troggs Comepiedras fornidos.', },
  },
  [171] = {
    'Alcaide de la Alianza',
    {'Has sido muy $Gbueno:buena; conmigo, $N. Nunca había soñado con divertirme tanto en la Semana de los Niños. Gracias.|n|nOjalá todos los huérfanos tuvieran la suerte de hacer lo que hemos hecho nosotros. ¿Quieres que vayamos a buscar a Chichón Perinola de nuevo y que le compremos un expositor para espadas de gomaespuma? Creo que todavía está empujando esa vagoneta en Los Canales, fuera del Distrito de Mercaderes. ¡Así todo el mundo en el orfanato podrá hacer algo divertido!|n|nDespués, ya será hora de que me vaya a casa.', },
    {'Compra un expositor para espadas de gomaespuma a Chichón Perinola y después habla con la supervisora de huérfanos Ruiseñor en el Distrito de la Catedral para llevar a tu pupilo de vuelta al orfanato de Ventormenta.', },
  },
  [172] = {
    'Semana de los Niños',
    {'¿Quieres ayudarnos aquí en el orfanato? $GBendito:Bendita; seas, $Gamigo:amiga;. Tu ayuda durante la Semana de los Niños no tiene precio.|n|nCoge este silbato. Solo podrás utilizarlo durante un breve período de tiempo, básicamente, hasta que se acabe la Semana de los Niños. Cuando lo uses, podrás hablar con el niño que esté a tu cuidado. Utilízalo de nuevo para que el niño se vaya.|n|nSea como sea, $N, utiliza el silbato y conoce a tu pupilo. Seguro que el niño estará encantado de conocerte.', },
    {'Usa el silbato de huérfano orco para hablar con el niño al que cuidarás durante la Semana de los Niños.', },
  },
  [173] = {
    'Huargen en el bosque',
    {'La oscuridad se siente inexorablemente atraída hacia el Bosque del Ocaso. El maestro Carevin lucha por erradicar el mal y la herejía. Y con nuestros esfuerzos mantenemos a salvo a las gentes de Villa Oscura.|n|n¿Te crees $Gmerecedor:merecedora; de unirte a nosotros?|n|nHace tiempo pensaba como tú. La complacencia de la Guardia me decepcionó y acabé uniéndome al maestro Carevin. Si quieres probar tu valía, no utilices las palabras.|n|nMide tus habilidades con un huargen delirante tejesombras Penumbría en la Arboleda del Destello y en El Vergel Pútrido.', },
    {'Mata a 6 huargen Tejesombras Penumbría para Calor de Villa Oscura.', },
  },
  [174] = {
    '[DEPRECATED]Mira las estrellas',
    {'Cog, mi amigo gnomo, me ha prometido ayuda para crear un instrumento que me servirá para ver las estrellas. Más allá de la magia hay una verdad que puede explicar las extrañas transformaciones del bosque.|n|nTráeme un tubo de bronce creado por un ingeniero cualificado. Ese es el primer paso según el manual de Cog.', },
    {'Viktori Prism\'Antras de Villa Oscura quiere que le lleves un tubo de bronce.', },
  },
  [175] = {
    '[DEPRECATED]Mira las estrellas',
    {'Según el manual de Cog, ahora necesito encontrar algo para reflejar la luz. Me acuerdo de una mujer llamada Mary que se hizo muy famosa por aquí porque siempre llevaba un espejo consigo. Quizás puedas encontrar a Mary y pedirle que nos preste una superficie reflectante para este proyecto... Vive al sur del Bosque del Ocaso. Al menos, es donde vivía antes...', },
    {'Localiza a Mary y convéncela de que te dé una superficie reflectora para el proyecto de Viktori.', },
  },
  [176] = {
    'Se busca: Hogger',
    {'Se busca: Hogger.|n|nUn gnoll enorme, Hogger, está al acecho en el bosque al suroeste de Elwynn. Ha sofocado todos los intentos de capturarlo.|n|nEl ejército de Ventormenta ofrece una generosa recompensa por atrapar al gnoll. Para ganarla, los cazarrecompensas tendrán que adentrarse en el bosque y eliminar a la bestia.', },
    {'Encárgate de "la situación Hogger" y vuelve a ver al alguacil Dughan.', },
  },
  [177] = {
    '[DEPRECATED]Mira las estrellas',
    {'El espejo era uno de mis tesoros más preciados hasta... el incidente. Después de lo que ocurrió, lo escondí detrás del granero. Antes venía por aquí un necrófago demente... Quizás lo cogió él. Se dice que esa bestia inmunda vive en el Cementerio del Jardín Sereno.', },
    {'Quita el espejo de Mary la Ciega al necrófago demente y llévaselo a Viktori a Villa Oscura.', },
  },
  [178] = {
    'Theocritus recupera el colgante',
    {'<Oyes una voz...>|n|nNo te asustes; soy Theocritus, Mago Supremo de la Torre de Azora, en el Bosque de Elwynn. El colgante es un medio de comunicación entre los gnolls Pielsombra y su señor, Morganth.|n|nHe investigado durante meses y creo que yo también puedo usar los colgantes. Si oyes este mensaje, mi hechizo ha funcionado.|n|nTráeme el colgante y te recompensaré.', },
    {'Lleva el colgante Pielsombra descolorido a Theocritus el Mago a la Torre de Azora, en el Bosque de Elwynn.', },
  },
  [179] = {
    'Los enanos modistos',
    {'¿Qué tenemos aquí? Tienes pinta de necesitar algo para mantener las manos calientes, ¿mm?|n|nYo te diré lo que necesitas: un par de estupendos guantes bien calentitos. Y, como soy un alma generosa, me encantaría proporcionarte ese par de guantes. Pero con una condición.|n|nNecesito que me consigas carne de lobo. Es un buen trato, ¿mm? Tú me traes un poco de carne de lobo y yo evito que pierdas los dedos por congelación. ¿Y bien? ¿Qué dices?', },
    {'Sten Brazorrecio quiere 8 piezas de carne de lobo dura.', },
  },
  [180] = {
    '¡Se busca!',
    {'Se busca al teniente Fangore|n|nSe acusa al jefe del clan gnoll Pielsombra de colaborar con el enemigo del Reino Morganth. El magistrado Solomon ha decretado la pena de muerte para este traidor a Ventormenta. Su zarpa se considerará prueba de su muerte.', },
    {'Mata al teniente Fangore y lleva su zarpa al magistrado Solomon a Villa del Lago.', },
  },
  [181] = {
    '[DEPRECATED]Mira las estrellas',
    {'Necesito un objeto más para completar el instrumento. Según el manual de Cog necesito una lente de algún tipo. La única lente que conozco, aunque sería lo suficientemente grande, es difícil de conseguir.|n|nSé de un ogro que tiene un monóculo... se llama Zzarc\'Vul y vive en el montículo que hay al sur del Bosque del Ocaso. Si puedes, tráeme su monóculo y lo usaremos como lente.', },
    {'Localiza a Zzarc\'Vul en el montículo meridional del Bosque del Ocaso y llévale su monóculo a Viktori a Villa Oscura.', },
  },
  [182] = {
    'La amenaza trol',
    nil,
    nil,
  },
  [183] = {
    'Cazador de jabalíes',
    {'No hay nada como pasar un día cazando jabalíes, ¿eh?|n|nAunque con la de jabalíes que tenemos en el Valle de Crestanevada, la cosa pierde un poco de gracia. Ni siquiera hay que provocarlos. Ya están todos enfadados e inquietos, no necesitan ayuda para eso. De hecho, últimamente hay tantos jabalíes en la zona que mi caza diaria se está convirtiendo en una actividad peligrosa.|n|nPara abreviar, si pudieras ayudarme a matar algunos jabalíes, te lo agradecería mucho.', },
    {'Talin Ojo Ávido quiere que mates a 12 jabalíes del risco pequeños.', },
  },
  [184] = {
    'Escrituras de Cejade',
    {'Estas son las viejas escrituras de una extensión de tierras de labranza de los Páramos de Poniente. Están firmadas por un tal Theodore Cejade y por su mujer, Verna. En el reverso de las escrituras hay unas palabras garabateadas con gran prisa:|n|n"Presionamos a Cejade y conseguimos sus escrituras. Pensé que te vendría bien si querías falsificar una para ti.|n|nLos Cejade no nos darán problemas. La última vez que los vi estaban saliendo de los Páramos de Poniente con un carro roto."|n|nCrees que probablemente los Cejade querrán recuperar sus escrituras...', },
    {'Lleva las escrituras de Cejade a la Finca de Jansen en Páramos de Poniente.', },
  },
  [185] = {
    'Caza al tigre',
    nil,
    nil,
  },
  [186] = {
    'Persigue al tigre',
    nil,
    nil,
  },
  [187] = {
    'Somete al tigre',
    nil,
    nil,
  },
  [188] = {
    'Caza al tigre',
    {'Las leyendas hablan de una tigresa muy evasiva... un felino tan poderoso que hace parecer enclenques a los tigres mayores. Los cazadores de la Expedición de Nesingwary le han estado dando caza sin éxito. Muchos han caído víctimas de sus garras lacerantes; sus cuerpos se pudren en la falda de su colina, al norte de Grom\'gol.|n|nLlaman a esta bestia Sin\'Dall.|n|nDecídete a conseguir lo que $Gningún:ninguna; $R: dar caza, matar y tomar la garra de Sin\'Dall.', },
    {'Caza a Sin\'Dall y regresa con su garra.', },
  },
  [189] = {
    'Orejas de Sangrapellejo',
    {'¡Malditos trols! ¡Han estado matando a nuestros agentes en la jungla! Ya he perdido a un buen número de mis mejores guardias en esas escaramuzas. ¡Los costes se multiplican! ¿Cómo se lo voy a explicar al Barón Revilgaz?|n|nAcción decisiva... Piensa, Kebok... no te asignaron al puesto que tienes hoy por estar de brazos cruzados... ¡Lo tengo! Tú... $N, ¿verdad? Me ayudarás, ¿no? ¡Hay dinero en juego!|n|nEste es el trato: tráeme las orejas de quince trols Sangrapellejo y te compensaré generosamente.', },
    {'Consigue 15 orejas Sangrapellejo y llévaselas a Kebok en la Bahía del Botín.', },
  },
  [190] = {
    'Si quieres formar parte del grupo de caza de Hemet Jr., tendrás que demostrar que eres capaz de cazar una pantera. No te preocupes, empezaremos con algo fácil: céntrate en las panteras jóvenes por ahora. A medida que vayas mejorando y ganando experiencia como $Gcazador:cazadora;, tendrás que enfrentarte a presas más peligrosas.|n|nEmpieza por dirigirte al este. Vuelve conmigo cuando te hayas convertido en $Gun maestro cazador:una maestra cazadora; de panteras.',
    {'Si quieres formar parte del grupo de caza de Hemet Jr., tendrás que demostrar que eres capaz de cazar una pantera. No te preocupes, empezaremos con algo fácil: céntrate en las panteras jóvenes por ahora. A medida que vayas mejorando y ganando experiencia como $Gcazador:cazadora;, tendrás que enfrentarte a presas más peligrosas.|n|nEmpieza por dirigirte al este. Vuelve conmigo cuando te hayas convertido en $Gun maestro cazador:una maestra cazadora; de panteras.', },
    nil,
  },
  [191] = {
    'Persigue a la pantera',
    nil,
    nil,
  },
  [192] = {
    'Somete a la pantera',
    nil,
    nil,
  },
  [193] = {
    'Caza la pantera',
    {'Casi has demostrado ser $Gun maestro cazador:una maestra cazadora; de panteras, pero hay una que se te ha escapado.|n|nHay canciones que hablan de una poderosa pantera llamada Bhag\'thera. Veamos si puedes usar tus habilidades para matar a la gran bestia.|n|nSi le traes el colmillo de Bhag\'thera a Erlgadin demostrarás ser $Gun maestro cazador:una maestra cazadora; de panteras.', },
    {'Consigue el colmillo de Bhag\'thera.', },
  },
  [194] = {
    'Caza al raptor',
    nil,
    nil,
  },
  [195] = {
    'Persigue al raptor',
    nil,
    nil,
  },
  [196] = {
    'Somete al raptor',
    nil,
    nil,
  },
  [197] = {
    'Caza al raptor',
    {'Antes de regresar a la Expedición de Nesingwary, tendrás que realizar lo imposible: cazar al raptor que ningún otro cazador ha conseguido matar. La bestia se llama Tethis y se sabe que tiene aterrorizada toda la esquina sureste del Norte de la Vega de Tuercespina.|n|nSi le entregas la garfa de Tethis a ese enano cazador, demostrarás que no eres $Gun:una; $R común y corriente.', },
    {'Caza a Tethis.', },
  },
  [198] = {
    'Suministros para el soldado Thorsen',
    {'Mmm. Sí, de hecho, tengo algo que podrías hacer. El teniente Doren y sus seguidores que están al norte, necesitan que les enviemos sus suministros.|n|nTodavía no lo hemos podido hacer y, con el ataque de los trols, necesito que alguien lo haga. El campamento de Doren está en la parte noroeste del camino, en la entrada de Tuercespina desde el Bosque del Ocaso. Lleva los suministros al soldado Thorsen, si no está en el campamento, estará patrullando la zona sur. Él se encargará de todo.|n|nPor cierto, si fallas, me deberás una indemnización.', },
    {'Entrega los suministros goblin variados al soldado Thorsen.', },
  },
  [199] = {
    'Se aproxima una oscura amenaza',
    {'Coges una muestra de esas partículas con olor extraño.', },
    {'Enséñale la pista al ingeniero jefe Hinderweir.', },
  },
  [200] = {
    'Corredor Herod',
    {'Si Kurzen sabe lo del secreto de Thorsen, significa que tenemos un espía. ¡Debemos determinar cómo se filtró el secreto!|n|nEl contacto de Thorsen en la Base de Kurzen era el corredor Herod. Herod es el oficial de logística de Kurzen y lo sabe todo sobre la Base de Kurzen. Si consigues hacerte con las notas o los registros de Herod, quizás podamos saber cómo descubrieron a Thorsen.|n|nCuando todavía estábamos con Kurzen, la oficina de Bookie estaba en la parte de arriba de la casa de dos pisos de la Base. Probablemente, sus registros sigan allí.', },
    {'Encuentra los registros del corredor Herod.', },
  },
  [201] = {
    'Investiga el campamento',
    {'Me han informado de un grupo de cazadores acampados río arriba del campamento minero de Ventura y Cía. en Lago Nazferiti. Normalmente los ignoraría, pero dicen que uno de los cazadores es Hemet Nesingwary Jr., que tiene muy, pero que muy buenos contactos; hay que velar por su seguridad.|n|nVe a echar un vistazo al campamento, $N, a ver qué están haciendo por allí.', },
    {'Encuentra el campamento de los cazadores e informa sobre su ubicación a Krazek en la Bahía del Botín.', },
  },
  [202] = {
    'Coronel Kurzen',
    {'Has demostrado tu valía otra vez y tus recursos parecen rivalizar con los del mismísimo Kurzen. Quizás seas la salvación de nuestro grupo de rebeldes... si consigues enfrentarte a Kurzen y vencer.|n|nLidera a sus hombres desde las profundidades de Las Reservas. Debes entrar en la cueva, derrotar a sus defensores y enfrentarte a Kurzen y a sus líderes.|n|nAdiós, $N. Mi esperanza, y el destino de mis hombres, van contigo.', },
    {'Mata 6 unidades de élite de Kurzen y 4 subjefes de Kurzen. Lleva la cabeza de Kurzen al teniente Doren en el Asentamiento Rebelde.', },
  },
  [203] = {
    'La segunda rebelión',
    {'Estamos luchando una batalla perdida con el coronel Kurzen. No solo es un estratega brillante, sino que nos supera en número, ¡al menos 10 a 1! Para sobrevivir, tenemos que usar sus propias tácticas de cobertura contra él.|n|nVete a su campamento del este y mata a sus hombres. A muchos de ellos. Y sal de ahí antes de que los refuerzos te alcancen.', },
    {'Mata a 15 jíbaros de Kurzen.|n|nVuelve a ver a la sargento Yohwa en el Asentamiento Rebelde.', },
  },
  [204] = {
    'Mala medicina',
    {'Para tener una oportunidad contra Kurzen, necesitamos neutralizar su fuerza de curación. Ha reunido a un gran número de auxiliadores que curarán a sus tropas con pócimas de la selva y envenenarán a las nuestras con extractos de helecho venenoso.|n|nNecesitamos esas pócimas y extractos para nuestro propio provecho. Busca en la Base de Kurzen. Sus auxiliadores y jíbaros tendrán las pócimas y, probablemente, guardan los extractos en algunas de las cajas de suministros del campamento.', },
    {'Lleva 7 pócimas de la selva y 1 extracto de helecho venenoso a la sargento Yohwa en el Asentamiento Rebelde.', },
  },
  [205] = {
    'Brujería trol',
    {'Mientras estudio esas leyendas, necesito que consigas instrumentos de magia trol maligna. Entra en el territorio de los trols Machacacráneos, la segunda tribu del sur, y consigue fetiches Machacacráneos de sus médicos brujos y místicos.', },
    {'Lleva 4 fetiches Machacacráneos al hermano Nimetz en el Asentamiento Rebelde.', },
  },
  [206] = {
    nil,
    {'Quizás Kurzen esté muerto, pero... eso que le volvió maligno sigue vivo. Gracias a mis estudios he descubierto esto: hay un ogro mago, Mai\'Zoth, que vive en un Túmulo Ogro en las montañas del este de Tuercespina. Se dice que utiliza magia de control mental y creo que fue él quien corrompió a Kurzen.|n|nSi permitimos que Mai\'Zoth siga con vida, su magia podría influenciar a otros y quizás incluso provocar que apareciese otro Kurzen.|n|nMátale y tráeme su Ojo de la mente, el artefacto que utiliza para corromper.', },
    {'Lleva el Ojo de la mente al hermano Nimetz en el Asentamiento Rebelde.', },
  },
  [207] = {
    'El misterio de Kurzen',
    {'El coronel Kurzen fue un gran hombre de gran nobleza, ¡debo descubrir qué hizo que cayese en la depravación! Quizás está bajo el influjo de alguna magia trol. Para confirmarlo, debo estudiar algunas de sus leyendas.|n|nHay 4 tablillas escondidas en las ruinas trol de Tuercespina. ¡Necesito leer esas tablillas! Transcribe las tablillas y tráeme las transcripciones.|n|nLa primera tablilla está en las Ruinas de Bal\'lal, la segunda en El Arrecife Mortal, y la tercera y cuarta en las Ruinas de Zul\'Kunda.', },
    {'Encuentra las 4 tablillas y lleva las leyendas al hermano Nimetz.', },
  },
  [208] = {
    'Caza mayor',
    {'$N, eres $Gun cazador digno:una cazadora digna; de estar en nuestro grupo. Desde los campos de batalla de Lordaeron hasta las profundidades de la jungla, muy pocas veces he visto tal destreza con las armas como la que has demostrado tú.|n|nHas matado al feroz Sin\'Dall, a la esquiva Bag\'thera y al traicionero Tethis. Pero el verdadero trofeo es la cabeza del rey Bangalash. Ese tigre blanco es la razón por la que estoy aquí, pero sigue provocándome desde su refugio al sur. Mata al rey Bangalash y tu dominio de la cacería será insuperable.', },
    {'Caza la cabeza del rey Bangalash, el gran tigre blanco.', },
  },
  [209] = {
    'Colmillos Machacacráneos',
    {'Matar los suficientes tigres para mantener la exportación de colmillos de tigre a las islas de los Mares del Sur, es caro y complicado. Por suerte, hemos desarrollado una técnica que nos permite coger objetos normales en forma de cuerno y convertirlos en falsificaciones perfectas.|n|nLo más parecido que hemos encontrado, sorprendentemente, son los colmillos de trols Machacacráneos.|n|nEh, antes de que digas nada, ojo de comprador que no ve, corazón de tonto que no siente, ¿tengo razón? Tráeme muchos colmillos para que podamos ponernos a trabajar en el pedido del mes.', },
    {'Consigue 18 colmillos Machacacráneos y llévaselos a Kebok.', },
  },
  [210] = {
    'La cocina de Krazek',
    {'Yo me encargo de la mayor parte de la cocina del campamento. Y solía ser un montón de trabajo, hasta que le compré una olla mecánica a un mercader goblin en la Bahía del Botín. ¡Esa olla es una maravilla! Me ha ahorrado un montón de horas... ¡Pero se ha roto!|n|n¿Podrías llevar la olla al goblin para que me la pueda arreglar? Se llama Krazek.', },
    {'Lleva la olla mecánica de Krazek al goblin Krazek.', },
  },
  [211] = {
    'Ah, Andorhal',
    {'¡Ay, se acerca el momento de atacar Andorhal y de hacer salir al exánime que lo controla!|n|nEs en el interior de las ruinas de la ciudad donde el exánime, Araj el Invocador, tiene sus dominios. Está custodiado por numerosos miembros de la Plaga que rodean los restos del centro de la ciudad, y su séquito personal de guardianes es realmente formidable. Necesitarás muchos aliados para tener alguna oportunidad de enfrentarte a él con éxito.|n|n¡Acaba con Araj, $N, y tráeme un trozo de su filacteria como prueba!', },
    {'Lleva el trozo de filacteria de Araj al comandante Ashlam Puñovalor del Campamento del Orvallo, en las Tierras de la Peste del Oeste.', },
  },
  [212] = {
    'Un plato bien frío',
    {'Uno de mis platos más famosos es basilisco helado en vinagreta de lima. Pero el problema es que es imposible mantener fresca la carne y tengo que servir el plato esta noche en el cumpleaños de un noble.|n|nSi pudieras traerme un anca de basilisco helado de un Basilisco Ojogélido recién muerto y rápidamente... ¡estaré en deuda contigo!|n|nLos Basiliscos Ojogélido suelen vagar por las dunas de la playa al noroeste de la Vega de Tuercespina, así que te espera un largo viaje. ¡Y rápido!', },
    {'Mata un Basilisco Ojogélido, consigue un anca de basilisco helado y llévasela a Angus Stern en El Ermitaño Taciturno.', },
  },
  [213] = {
    'OPA hostil',
    {'¡Lo ha hecho! Ya es bastante malo que Gelriz se meta por el medio de los magnates que nombraron los príncipes mercantes como para que ahora intente meterse con el pirata más famoso.|n|nRevilgaz no lo tolerará y me ha dicho que me encargue del problema a mi manera.|n|n¿Mi manera? El robo. Los geólogos de Ventura y Cía. que están cerca del Lago Nazferiti están muy interesados en esos extraños cristales azules que han encontrado en las minas. Tráeme muestras de los cristales de los geólogos, no me importa lo que tengas que hacer para conseguirlas.', },
    {'Consigue 8 cristales caídos y llévaselos a Kebok en la Bahía del Botín.', },
  },
  [214] = {
    'Pañuelos rojos de seda',
    {'No es ningún secreto que la marca distintiva de la banda Defias son los pañuelos rojos. Pero hemos averiguado que el material del que están hechos los pañuelos sirve para identificar el rango del miembro.|n|nDicho esto, quiero que elimines tantos miembros Defias de alto rango como puedas. Podrás encontrarlos en la ladronera secreta de VanCleef. Cuando hayas terminado tráeme 10 pañuelos de seda roja y sabré recompensarte. Buena suerte, $N.', },
    {'La exploradora Riell de la Colina del Centinela quiere que le lleves 10 pañuelos de seda roja.', },
  },
  [215] = {
    'Los secretos de la jungla',
    {'Gracias por salvarme, $N. Sé lo que parece esto, pero... deja que te lo explique.|n|nEl teniente Doren me encargó alistarme con los hombres de Kurzen para que pudiera espiarles y llevar información a los rebeldes. Lo que has visto es lo que yo pensaba que sería mi oportunidad para infiltrarme en la Base de Kurzen. Me equivoqué y, otra vez, gracias por salvarme.|n|nEsto era una misión de alto secreto, así que no se lo puedes decir a nadie. Pero si hablas con Doren, te lo explicará.', },
    {'Habla con el teniente Doren en el Asentamiento Rebelde.', },
  },
  [216] = {
    'Entre una roca y un Piel de Cardo',
    {'¡Los fúrbolgs Piel de Cardo son una amenaza para nuestra expansión! El Poblado Piel de Cardo, al oeste, obstruye nuestro paso entre este lugar y el Puesto del Hachazo. Es un camino que rodearía el pueblo de Astranaar; sin él, ofrecemos a la Alianza una vía más para la expansión.|n|n$N, no podemos permitir... ¡un hueco en el camino de expansión!|n|nVe al Poblado Piel de Cardo y acaba con los fúrbolgs. Recibirás una compensación por esta tarea y lo que es más importante, ¡estarás cumpliendo con tu deber para con la Horda!', },
    {'Karang Amakkar en Avanzada Grito Infernal quiere que acabes con 15 fúrbolgs Piel de Cardo de cualquier tipo en el Poblado Piel de Cardo.', },
  },
  [217] = {
    'Un golpe decisivo',
    nil,
    nil,
  },
  [218] = {
    'Hielo y fuego',
    nil,
    nil,
  },
  [219] = {
    'Desaparecido en combate',
    {'¡Al fin, ayuda para la Alianza!|n|nAyúdame...|n|nLo último que recuerdo es que esos malditos orcos nos tenían rodeados. Los mataron a casi todos. A mí me dieron un golpe en la cabeza y perdí el conocimiento, y ahora me encuentro cautivo. Ayúdame, estoy malherido.|n|nTienes que ayudarme a volver... Por favor, eres mi única esperanza.', },
    {'Protege al cabo Keeshan en el camino a Crestagrana.', },
  },
  [220] = {
    'La llamada del agua',
    {'Islen tendrá una tarea más para ti antes de recompensarte con tu siguiente tótem. Sea cual sea esa tarea, te hará falta el vial de agua que te he dado.|n|nAhora vete y encuéntrala. Volveremos a encontrarnos algún día.', },
    {'Llévale el vial del agua más pura a Islen Vidente del Agua al Escalón de la Marea, en Los Baldíos.', },
  },
  [221] = {
    'Huargen en el bosque',
    {'Quizás te hayas fijado en esos enormes huargen que deambulan por los bosques con los tejesombras... Por lo que sabemos, esos corredores oscuros son el grueso de las filas de los huargen.|n|nEn mis patrullas también he notado que han invadido El Vergel Pútrido al suroeste de la ciudad. Esos huargen son más fuertes que los últimos a los que te enfrentaste.|n|nNo bajes la guardia.', },
    {'Mata a 12 huargen sombracechadores Penumbría para Calor de Villa Oscura.', },
  },
  [222] = {
    'Huargen en el bosque',
    {'Tus anteriores hazañas me han hecho pensar que ya estás $Glisto:lista; para afrontar a los huargen más duros del bosque.|n|nDe todos los huargen que han establecido aquí su morada, los Colmillo Vil y los Mancillados han demostrado ser los más peligrosos. Se han instalado cerca de las cuevas y en la mina que hay al sur.|n|nEl fuego de sus hogueras puede verse desde muy lejos...', },
    {'Mata 8 Colmillovil nocturnos y 8 huargen corruptos Penumbría para Calor de Villa Oscura.', },
  },
  [223] = {
    'Huargen en el bosque',
    {'Ten, $N. Lleva este mensaje al maestro Carevin.|n|n<Con un rápido movimiento saca un papiro descolorido y te lo tiende.>|n|n¡Unos pocos más como tú y superaremos en número a La Guardia Nocturna! Quizás así podríamos acabar entre todos el trabajo que hacemos nosotros.', },
    {'Lleva la nota de Calor a Jonathan Carevin.', },
  },
  [224] = {
    'Un golpe decisivo',
    {'¡Tenemos que proteger Loch Modan, $N! Casi todas nuestras tropas están luchando en otros frentes; nos hemos quedado desprotegidos. ¡Están saliendo troggs de debajo de las piedras! Esta invasión supone la mayor amenaza para Forjaz. Tenemos que acabar con esos asquerosos mutantes.|n|nNecesitamos a alguien valiente como tú para acabar con esos seres. Acaba con seis troggs Rompecantos y seis exploradores Rompecantos. Encontrarás a la mayoría de esas alimañas en los pasos hacia las montañas del sur.', },
    {'El montaraz Pedernal, de Thelsamar, quiere que mates a 6 troggs y 6 exploradores Rompecantos.', },
  },
  [225] = {
    'La lápida desgastada',
    {'La lápida, desgastada por el tiempo, reza sencillamente:|n|nMORGAN LADIMOR|n|n<Cuando te acercas más, te das cuenta de que la tierra que hay sobre la tumba ha sido removida recientemente; parte de ella ha sido extraída...>', },
    {'Ve a Villa Oscura y habla con Sirra Von\'Indi.', },
  },
  [226] = {
    'Con los lobos en los talones',
    {'A Sven y a mí nos esperan días peligrosos, con el nigromántico al este... y aquí solos... tenemos que cazar nuestra propia comida. Y cada vez que vuelvo al campamento con algo de carne, aparecen lobos hambrientos o rabiosos buscando un bocado. ¡Vivir aquí es peligroso, no hace falta que lo jure!|n|nPero si consiguieras librarnos de algunos de esos lobos, nos facilitarías mucho la cosa. Se concentran sobre todo al norte y al este de aquí, cerca del río.', },
    {'Mata a 12 lobos feroces hambrientos y a 8 lobos feroces rabiosos y vuelve al campamento de Sven en la frontera oeste de Bosque del Ocaso a buscar a Lars.', },
  },
  [227] = {
    nil,
    {'<Busca entre las estanterías y vuelve con un libro encuadernado en cuero.>|n|nSi quieres saber algo más, podrías preguntar a Althea. Ella ha sido la que ha... tratado el... problema... con él.', },
    {'Ve a Villa Oscura y habla con la comandante Althea Cerranegro.', },
  },
  [228] = {
    nil,
    {'Por lo que me dicen los exploradores, Mor\'Ladim deambula por el Bosque del Ocaso; recorre un extraño y serpenteante camino por el cementerio. Lo enterramos pasada la casa de la colina, ¿sabes dónde digo?|n|nNo hay nada que pueda hacer para ayudarte, pero te deseo buena suerte.', },
    {'Mata a Mor\'Ladim y luego lleva su calavera a la comandante Althea Cerranegro a Villa Oscura.', },
  },
  [229] = {
    'La hija superviviente',
    {'Tendría que haberte dicho esto antes...|n|nVeamos cómo podría explicarlo...|n|nMorgan cree que toda su familia está muerta pero, de hecho, su hija Sarah Ladimor ahora es una guardia. Siempre ha estado atormentada por las... circunstancias que rodearon la muerte de su padre. Quizás podrías ir a llevarle estas noticias.', },
    {'Ve a Villa Oscura y habla con la vigilante Sarah Ladimor.', },
  },
  [230] = {
    'El campamento de Sven',
    {'Cavando en el montículo encuentras un pequeño libro manchado de tierra.|n|nNo tiene título pero... contiene información que a Sven le gustaría tener.', },
    {'Lleva el libro de la granja de Sven a Sven.', },
  },
  [231] = {
    'El amor de una hija',
    {'Ten, lleva esto a su tumba. Quizás... de alguna forma, él sepa que estoy bien y que nadie le hace responsable de lo que ocurrió.|n|n<Los ojos se le llenan de lágrimas mientras se quita el anillo de la mano derecha y lo coloca en tus manos.>|n|nY... gracias, $N.', },
    {'Lleva el anillo de Sarah Ladimor a la tumba de Morgan Ladimor.', },
  },
  [232] = {
    'Un recado para la boticaria Zinge',
    {'La Sociedad Real de Boticarios necesita tu ayuda. Escucha bien esto, y puede que ambos podamos beneficiarnos con mi plan.|n|nEl boticario Keever, en la sala contigua, puede que esté... un poco tocado... pero su investigación promete dar muy buenos resultados, sobre todo si la condujera un investigador más inteligente. Afortunadamente, yo soy investigadora. Quiero que lleves esta orden de compra a Alessandro Luca, el propietario de Cachivaches Luna Azul; él te dará un equipo de estudio. Cuando lo tengas, tráemelo y yo me encargaré de explicarte tu encomienda con todo detalle.', },
    {'Llévale la orden de compra a Alessandro Luca en Entrañas.', },
  },
  [233] = {
    'Entrega de correo en el Valle de Crestanevada',
    {'Mm, oye, tú no querrás hacerme un favor... ¿o sí? Hoy ha llegado un fajo de cartas a través del paso, pero no tengo tiempo para entregarlas.|n|nEstán todas dirigidas a Talin Ojo Ávido. Lo encontrarás al oeste. Solo tienes que seguir el camino. Ha establecido su campamento en la orilla del lago helado.|n|n¿Qué respondes?', },
    {'Entrega el fajo de cartas a Talin Ojo Ávido en el Valle de Crestanevada.', },
  },
  [234] = {
    'Entrega de correo en el Valle de Crestanevada',
    {'Si no recuerdo mal, el campamento de Grelin está al sureste, por el camino. Estará ansioso por recibir su correo.', },
    {'Entrega la carta a Grelin Barbablanca en el Valle de Crestanevada.', },
  },
  [235] = {
    'La Caza de Vallefresno',
    {'¡Atención, jóvenes aventureros! ¡Los páramos de Vallefresno os esperan!|n|nLa Horda ha aumentado su presencia en las tierras al norte de Los Baldíos. Nuestras dos avanzadas, Puesto del Hachazo y La Ensenada de Zoram, se esfuerzan por traer gloria a la Horda. Aquellos que deseen demostrar su valía deben buscar ayuda allí. Nota: Senani Corazón Atronador del Puesto del Hachazo, al norte de Los Baldíos, busca a aventureros que deseen participar en la gran Caza de Vallefresno.', },
    {'Habla con Senani Corazón Atronador en Puesto del Hachazo, en Vallefresno.', },
  },
  [236] = {
    'Vigía Callahan',
    {'¡$N! Ya era hora de que aparecieras. Puede que esta batalla haya terminado, ¡pero aún tenemos que prepararnos para la siguiente! Viaja hasta El Caldero de Llamas, al sureste de Conquista del Invierno, y recoge algunas ascuas eternas.|n|nLas ascuas están mezcladas con carbón para repostar el demoledor y las máquinas de asedio.|n|nOh, y si ves a algún miembro de la Horda por El Caldero, no dudes en matarlo y quedarte con sus ascuas. No podemos dejar que nos saquen ventaja en la próxima batalla.', },
    {'El maestro de asedio Durasa, en la Fortaleza de Conquista del Invierno, quiere que arrebates 10 ascuas eternas a los jugadores de la Horda en El Caldero de Llamas.', },
  },
  [237] = {
    'Un golpe decisivo',
    {'El montaraz Pedernal habla muy bien de ti, $R. Por eso he decidido confiarte una misión de extrema importancia. Tenemos que mantener a raya a los troggs invasores hasta que nuestros hermanos regresen de luchar por la Alianza.|n|nDirígete a las colinas del sur y mata a diez aplastacráneos y diez videntes Rompecantos. Eso nos hará ganar tiempo. Regresa cuando termines la misión.', },
    {'El montaraz Gravagau, de la torre de vigilancia sur, quiere que mates a 10 aplastacráneos y 10 videntes Rompecantos. Luego ve a informarle.', },
  },
  [238] = {
    'Un recado para la boticaria Zinge',
    {'Este equipo está listo, $N. No cabe duda de que a la boticaria Zinge le gustaría recibirlo lo antes posible. Llévaselo cuanto antes, y dile que le cargaré los costes del equipo a la Sociedad. De paso, por favor, hazle llegar mi más afectuoso saludo.|n|nBueno, no te quedes ahí. Esa es la vida de $Gun simple mensajero:una simple mensajera;, ¿no?', },
    {'Llévale el equipo de prueba de campo a la boticaria Zinge en Entrañas.', },
  },
  [239] = {
    'El Cuartel de Arroyoeste necesita ayuda',
    {'La plaza fuerte de la frontera occidental informa de un aumento de actividad de gnolls y ladrones. Solicitan que enviemos más soldados de Ventormenta, ¡pero no podemos prescindir de ninguno!|n|nTu ayuda nos vendría bien. Habla con el ayudante de alguacil Rainer en el Cuartel de Arroyoeste y que te diga qué necesita.|n|nLa plaza fuerte está al oeste, bajando por el camino. Encontrarás un puente sobre un arroyo. Crúzalo. La plaza fuerte estará a la derecha.', },
    {'Ve al Cuartel de Arroyoeste y habla con el ayudante de alguacil Rainer.', },
  },
  [240] = {
    'Regresa junto a Alterio',
    {'¡¡Y voilà!! ¡Croquetas de "cangrejo" à la Grual!', },
    {'Vuelve a donde Alterio con los pasteles de cangrejo oscuro.', },
  },
  [241] = {
    '<TEST> ¡Eh, señor Wilson!',
    {'Descripción', },
    {'Cuaderno de bitácora', },
  },
  [242] = {
    nil,
    {'Throm-ka, $C. No hay tiempo que perder. Los orcos del clan Faucedraco se han atrincherado en el valle al sur de este lugar.|n|nNo reconocen el mando del Jefe de Guerra, así que solo nos dejan una opción. Los eliminaremos para que no vuelvan a mancillar el nombre de la Horda.', },
    {'Mata a 8 asaltantes Faucedraco, a 3 guardahuesos Faucedraco y a 1 maestro de batalla Faucedraco.', },
  },
  [243] = {
    'In situ',
    {'Dirígete al Desierto de Tanaris, y allí comprueba la consistencia del tejido de los basiliscos, escórpidos y de las hienas autóctonas del lugar. Consigue muestras de tejido con el equipo de estudio que llevas; eso sí, hazte a la idea de que parte de las muestras serán inservibles. Necesito 8 muestras buenas de cada tipo de criatura.|n|nAdemás, los goblins de Gadgetzan tienen una fuente de energía que debe emplearse con este tipo de equipo modificado. Habla con el ingeniero jefe Pasaquillas y consigue una para el equipo.|n|nVuelve a hablar conmigo cuando la tengas.', },
    {'Ve a Gadgetzan y encuentra al ingeniero jefe Pasaquillas para que te explique cómo obtener una fuente de energía para el equipo de estudio.', },
  },
  [244] = {
    'Gnolls invasores',
    {'Saludos, $C. Estoy patrullando esta parte del camino. De momento todo está en calma, pero he visto campamentos gnoll al norte y al este de aquí.|n|n¡Debes informar de esto en Villa del Lago! Preséntate ante el ayudante de alguacil Feldon en Villa del Lago y dile lo de los gnolls. Seguro que te paga sueldo de explorador.|n|nLo encontrarás al sur del puente a Villa del Lago.', },
    {'Preséntate ante el ayudante de alguacil Feldon en el puente que hay al sur de Villa del Lago, en las Montañas Crestagrana.', },
  },
  [245] = {
    '[DEPRECATED]Las amenazas de ocho patas',
    {'Salve, $C. ¿Has visto esas arañas que han invadido la frontera occidental? Esas amenazas de ocho patas son demasiado para nosotros pero el Comandante no tiene suficientes hombres. No puede enviar a nadie tan lejos de Villa Oscura.|n|nOdio tener que pedirte esto pero, parece que tú podrías manejar a esos bichos. No puedo prometerte una gran recompensa, pero si nos ayudas a erradicar a esos arácnidos, encontraré la forma de compensarte.|n|nAh, y deja que te dé un consejo: evita su veneno a toda costa.', },
    {'Mata a 15 telarácnidas pigmeovenenosas y vuelve al Bosque del Ocaso a informar al vigía Dodds.', },
  },
  [246] = {
    'Evaluar la amenaza',
    {'Andamos escasos de tropas, pero hay que hacer algo con esos gnolls.|n|nRastrea el sur de Crestagrana en busca de gnolls. Espíalos, mata a tantos como puedas y vuelve para informarme de cuántos son y si suponen una amenaza. Sus campamentos están por todo el camino meridional de Crestagrana.|n|nEl ejército de Ventormenta te recompensará, $N.', },
    {'Mata a 10 bastardos y 6 furtivos Crestagrana e informa al ayudante de alguacil Feldon en Villa del Lago.', },
  },
  [247] = {
    'El fin de la Caza',
    nil,
    nil,
  },
  [248] = {
    'Ver más allá',
    {'He estado observando la Torre de Ilgalar; Morganth está en conflicto con los orcos en el Fuerte de Petravista. Desconozco los motivos, pero tú me ayudarás a descubrirlos.|n|nCoge otro Glifo de Azora y sube a la atalaya intacta que hay junto al Fuerte de Petravista.|n|nEncuentra un objeto en el que depositar el glifo. Un cofre o un tarro iría bien, un lugar en el que nadie se fije en él.', },
    {'Sube a la atalaya intacta que hay junto al Fuerte de Petravista en las Montañas Crestagrana. |n|nEncuentra un objeto en el que esconder el Glifo de Azora.', },
  },
  [249] = {
    'Gran mago Doane',
    {'Después de mucha observación, he descubierto los planes de Morganth.|n|nBusca la Guadaña de Elune, ¡y es posible que ya la haya encontrado! Si ese es el caso, pronto las Montañas Crestagrana y el Reino de Ventormenta sentirán su siniestro poder.|n|nNo estoy preparado para enfrentarme a Morganth, pero me temo que debemos ocuparnos de él cuanto antes. Debes ir a la Torre de Ilgalar y enfrentarte a Morganth.|n|nDerrótalo y tráeme su colgante de las Sombras. El reino quedará en deuda contigo.', },
    {'Derrota a Morganth. |n|nLleva el colgante de las Sombras a Theocritus a la Torre de Azora, en el Bosque de Elwynn.', },
  },
  [250] = {
    'Se aproxima una oscura amenaza',
    {'Menos mal que alguien se interesa por el bienestar de la Presa. ¡Primero la destrucción del Puente Thandol y después el saqueo de Dun Modr! No dudo que el objetivo del siguiente ataque de los Hierro Negro será la Presa. Casi todos los agentes de seguridad se han destinado a luchar con la Alianza, incluido mi mejor inspector.|n|nPor eso te necesito, $N. He visto algunos zapadores Hierro Negro en la rampa oriental de la Presa. Investiga la zona y trae una pista.', },
    {'Investiga los alrededores de la rampa este de la Presa y lleva al ingeniero jefe Hinderweir alguna pista sobre lo que traman los Hierro Negro.', },
  },
  [251] = {
    '[DEPRECATED]Traduce la nota de Abercrombie',
    {'Lleva la nota que me diste a Sirra Von\'Indi. Es un experto en idiomas y artes antiguas. Si alguien puede traducir este mensaje, ese alguien es él.', },
    {'Lleva la carta de Ello a Sirra Von\'Indi.', },
  },
  [252] = {
    'Una traducción para Ello',
    {'¡Ay, ay! Si lo que dice esta nota es cierto, Abercrombie ha hecho algo... indescriptible.|n|nSerá mejor que le lleves la nota traducida a Ello.|n|nY date prisa. Temo que una maldición se acerca hacia nosotros...', },
    {'Lleva la carta traducida a Lord Ello Cerranegro.', },
  },
  [253] = {
    '[DEPRECATED]La novia del embalsamador',
    {'El Embalsamador es el nombre de un personaje de uno de nuestros cuentos para niños. Era un alquimista bueno que enloqueció tras la muerte de su esposa Eliza. Para recuperarla, utilizó magia negra y colocó su propio corazón en el pecho de su mujer.|n|nEliza resucitó... pero con un hambre insaciable de carne humana y eso obligó al Embalsamador a mantenerla enterrada.|n|nSu corazón es su poder. Encuentra la tumba de su esposa, quítale el corazón y tráemelo a mí mientras aún lata. Hazlo y romperás su poder.', },
    {'Encuentra la tumba de Eliza. Quítale el corazón del embalsamador y luego vuelve a Ello Cerranegro.', },
  },
  [254] = {
    'Excavar la tierra',
    nil,
    nil,
  },
  [256] = {
    'SE BUSCA: Chok\'sul',
    {'Por orden del magistrado de Thelsamar:|n|nSe busca muerto a Chok\'sul, ogro culpable de dirigir los ataques contra la ciudad de Thelsamar, la Presa de las Tres Cabezas y la excavación.|n|nSe ofrece recompensa a quien presente al magistrado una prueba de la muerte de Chok\'sul.|n|nFue visto por última vez en el campamento ogro situado al noreste de Loch Modan.', },
    {'Mata a Chok\'sul y lleva su cabeza al magistrado Narizroma a Thelsamar.', },
  },
  [257] = {
    'La fanfarronada de un cazador',
    {'Crees que estás a la altura de Daryl el Audaz, ¿eh? ¡No lo creo! Por supuesto, puedes ponerte a prueba. Te propongo un desafío que seguro estará por encima de tus posibilidades, así que no te sientas mal si no eres capaz de superarlo.|n|nUna banda de águilas ratoneras ha anidado aquí, en Loch Modan. ¿Qué tal si acabas con algunas de esas bestias? Mira, si superas mi desafío, te daré mi arco o mi pistola.|n|n<Te mira por encima del hombro.>|n|nNo parece que tengas mucho que perder de todas formas.', },
    {'Mata 8 águilas ratoneras montesas y ve a ver a Daryl el Jovenzuelo en la Cabaña del Errante.', },
  },
  [258] = {
    'El reto de un cazador',
    {'Así que eres $N, ¿eh? Te llena de orgullo tu destreza como $Gcazador:cazadora;, ¿verdad? Tampoco hay para tanto.|n|nA ver si te atreves a cazar un jabalí. Créeme, esta no será una cacería como las del Valle de Crestanevada, así que será mejor que tengas cuidado.|n|nNo te sientas mal si no lo consigues. ¡Si lo haces, te daré mi camisa!|n|n¿Te he contado cómo me hice mi famosa cicatriz? ¿No? Fue hace dos años...', },
    {'Mata 10 jabalíes monteses mayores y ve a ver a Daryl el Jovenzuelo en la Cabaña del Errante.', },
  },
  [259] = {
    nil,
    {'Hola, $N. Mucho he oído hablar de tus hazañas y debo decir que es un honor conocerte. Supongo que no has oído la historia de Ol\'Kelt. Bueno, pues Ol\'Kelt, es decir Kelt Thomasin, era otrora considerado uno de los diestros cazadores de todo el reino. Lo había conseguido casi todo, pero un día se obsesionó con una antigua historia... un mito en realidad. Bien, cuenta la historia que un colosal trillanodonte vive en las aguas del lago. Tonterías, por lo que a mí respecta. Si te interesa, deberías hablar con Kelt.', },
    {'Habla con Kelt Thomasin.', },
  },
  [260] = {
    nil,
    {'Bien, esto sin duda te convencerá de que estoy, como dicen y no lo niego, sé que lo dicen, completamente perturbado, obsesionado con una leyenda imposible. Cuenta una antigua leyenda de enanos, que un enorme monstruo vive en las profundidades de Loch Modan. He pasado buena parte de mi vida tratando de localizarlo y creo que estuve cerca pero, por desgracia, me temo que me ha alcanzado antes la vejez. Si deseas intentar cazar al monstruo de Loch Modan, tráeme unos dientes y unas garras de trillanodonte.|n|n<Sonríe misteriosamente.>', },
    {'Reúne 5 colmillos de trillanodonte y 5 garras de trillanodonte, y llévaselas a Kelt Thomasin.', },
  },
  [261] = {
    'El sendero Escarlata',
    {'Te hablaré con franqueza. Estamos en guerra con la Plaga. Es un mal que corrompe a nuestra gente e infesta nuestra tierra. Hay que detenerlo antes de que nos arrolle y arrastre a nuestro mundo a las sombras. Los miembros de la Cruzada Escarlata hemos jurado combatir a la Plaga en cuerpo y alma.|n|nSi estás con nosotros, reúne valor y prueba tu lealtad: acaba con los devastadores no-muertos de Desolace. Búscalos en el Valle de los Huesos, al sur.|n|nHazlo y la Cruzada te acogerá con los brazos abiertos.', },
    {'Aniquila 30 devastadores no-muertos y luego ve a buscar al hermano Anton a Punta de Nijel.', },
  },
  [262] = {
    'La figura en las sombras',
    {'¡Debí adivinar quién era esa figura que vi en las sombras la noche en que mi familia fue asesinada!|n|nPor favor, $N, has demostrado ser $Gun hombre:una mujer; de recursos. Te lo ruego, encuentra a ese ser misterioso. ¡He de saber qué secretos guarda!|n|nNo sé nada que tú no sepas ya pero, ten, coge el libro que encontraste en mi granja. Quizás alguien del pueblo pueda decirte a quién pertenece el libro.', },
    {'Llévate el libro que encontraste en la granja de Sven a Villa Oscura y enséñaselo a sus habitantes.', },
  },
  [263] = {
    'Un golpe decisivo',
    {'Los montaraces me dicen que eres valiente y capaz, $N. Nos hace falta $Gun:una; $R como tú por aquí. La situación con los troggs no mejora. La reserva está en combate; estamos solos. Pero con tu experiencia como $C, la cosa va a cambiar.|n|nLiquida a ocho chamanes Rompecantos y a ocho Cascahuesos Rompecantos.|n|nA ver si los troggs aprenden a temer tu reputación, mata-troggs.', },
    {'El montaraz Muroplof, de la torre de vigilancia sur, quiere que mates a 8 chamanes y 8 Cascahuesos Rompecantos.', },
  },
  [264] = {
    'Hasta que la muerte nos separe',
    {'¡Sucia escoria! Me abandona por su maldita cruzada porque "la Luz es lo más importante que tenemos contra la amenaza que representan los no-muertos."|n|n¡¿Y sus hijos?! ¡¿Y YO?! Noche tras noche me quedaba esperando por él... ¡siempre en segundo lugar después de sus condenadas obligaciones!|n|nBueno, ¡mira lo que te depara la "justicia", $N! ¡Él está muerto y yo tengo precisamente lo que estaba intentando detener!|n|nCoge esto y ponlo encima de su tumba en El Sepulcro. ¡No quiero tener nunca más nada que ver con eso... ni con él!', },
    {'Coloca el colgante de Clarice sobre la tumba de Yuriv en Argénteos.', },
  },
  [265] = {
    'La búsqueda de la figura continúa',
    {'Te devuelvo tu libro, $N. Y te deseo mucha suerte. Si preguntas a la gente del pueblo, quizás puedas conseguir más pistas.|n|nEmpezaré por darte yo una: aunque el autor de este libro no es de Villa Oscura, el libro fue comprado aquí.', },
    {'Averigua si otros habitantes tienen pistas sobre la figura misteriosa.', },
  },
  [266] = {
    '[DEPRECATED]Búsqueda en la posada',
    {'Ten tu libro. Y buena suerte con tus pesquisas.|n|nQuizás quieras continuar la búsqueda en la posada. Si la persona a la que buscas pasó algo de tiempo en el pueblo, es probable que alguien le viera allí.', },
    {'Busca pistas sobre la figura misteriosa en la posada.', },
  },
  [267] = {
    'La amenaza trogg',
    {'$C, es posible que no estés al corriente de la amenaza trogg que se cierne sobre tierras enanas. Con las fuerzas de reserva de Forjaz en el frente de la Alianza, solo nos queda una fracción de las fuerzas de defensa necesarias para proteger estas tierras. Mi regimiento debe quedarse aquí protegiendo la ciudad, por lo que no podemos abandonar nuestros puestos, nos arriesgaríamos a una invasión.|n|nPero tenemos que presionar un poco a esos malditos troggs que merodean por las colinas. Si te ves capaz, lanza un ataque contra los troggs. Tráeme ocho dientes de trogg de piedra como prueba de tu acción.', },
    {'Lleva 8 dientes de trogg de piedra al capitán Rugelfuss a la torre de vigilancia sur.', },
  },
  [268] = {
    'Entrega para Sven',
    {'El libro que encontraste no estaba acabado. Tuve que dejarlo en la granja de Sven cuando huí...|n|nTen. Lleva mi diario completo a Sven. Describe con más detalle lo que ocurrió en su granja.|n|nAunque este diario ha sido mi única compañía todas estas semanas, si renunciando a él me evito tener que afrontar la ira de Sven... ¡te lo doy encantado!', },
    {'Lleva a Sven el diario completo de Alterio.', },
  },
  [269] = {
    'En busca de sabiduría',
    {'Ve a la ciudad de Ventormenta y habla con el obispo Lontananza. Búscalo en la Catedral de la Luz. Dale el diario de Alterio y dile que deseas enfrentarte a Morbent Vil.|n|nAunque Ventormenta ha abandonado a Villa Oscura, Lontananza es un alma buena y sabia. Puede que te ayude a salvarnos.|n|nTu misión es peligrosa, pero date prisa, $N. Las sombras del Bosque del Ocaso son más cada vez más oscuras.', },
    {'Entrega el diario completo de Alterio al obispo Lontananza de Ventormenta.', },
  },
  [270] = {
    'La flota maldita',
    {'Años atrás, la Tercera Flota de Kul Tiras se hundió en la costa de Los Humedales, una expansión pantanosa al norte del reino enano de Forjaz. A bordo del barco había un envío de hierro Forjaluz.|n|nEste metal es muy valioso para nosotros, porque los objetos forjados con él, golpean con toda la verdad sagrada. Si te vas a enfrentar a Morbent Vil, necesitarás un arma así.|n|nVete al Puerto de Menethil y habla con mi colega enano Glorin Frenteacerada. Si es posible encontrar ese metal perdido, él sabrá dónde.', },
    {'Vete al Puerto de Menethil en Los Humedales y habla con Glorin Frenteacerada.', },
  },
  [271] = {
    'La venganza de Vyrin',
    {'Supongo que no te interesará devolvérsela a Su Señoría Osadía. Daryl tiene cierta habilidad, lo reconozco.|n|nHace un año el objetivo de la Cabaña del Errante era un gran oso, pero ni uno solo de los cazadores lo consiguió. Ni siquiera Daryl que también probó suerte con él. Lo único que sacó en claro fue esa terrible cicatriz que luce sobre el ojo.|n|nMata al oso. No me cabe duda de que eso le cerrará el pico a Daryl aunque solo sea por una vez.|n|nEl oso, el viejo Tiznado, se encuentra en las inmediaciones de su guarida, en una cueva al norte de aquí.', },
    {'Mata al viejo Tiznado y llévale una prueba a Daryl el Jovenzuelo en la Cabaña del Errante.', },
  },
  [272] = {
    'La prueba del león marino',
    {'En tu segunda prueba debes encontrar las dos mitades del colgante del león marino. Una obtiene su poder de la agilidad del león marino cuando se desliza en el agua, la otra lo obtiene de su increíble capacidad de resistencia. Los druidas se alimentan de ambos rasgos para asumir su forma acuática.|n|nHabla con la gente de Claro de la Luna para averiguar dónde están las mitades y tráemelas para que las unamos. Luego llevarás el colgante a Dendrita Rafagaestelar.', },
    {'Busca el colgante de Agilidad acuática y el colgante de Resistencia acuática. Habla con la gente de Claro de la Luna para conseguir pistas sobre la ubicación de los colgantes. |n|nForma el colgante del león marino con los otros dos cuando estés cerca del Santuario de Remulos. |n|nLleva el colgante completo a Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.', },
  },
  [273] = {
    'Aprovisionar la excavación',
    {'Pero aún hay tiempo, ayúdanos a buscar a Huldar. No puede estar muy lejos; aunque son fuertes, no creo que Miran y Saean puedan ir muy rápido cargando con esos barriles.|n|nEstán siguiendo la ruta normal, hacia el sur y siguiendo la curva de Loch Modan.|n|nSi todavía no han llegado, los encontrarás.', },
    {'Habla con Huldar.', },
  },
  [274] = {
    'Se aproxima una oscura amenaza',
    {'Rápido, llévale esta mezcla al jefe. Los Hierro Negro no descansan, así que nosotros tampoco podemos.', },
    {'Ashlan Risapétrea quiere que lleves la mezcla neutralizadora al ingeniero jefe Hinderweir.', },
  },
  [275] = {
    'Ampollas en la tierra',
    {'No sé la causa pero una auténtica podredumbre está creciendo en Los Humedales. Han aparecido trepadores del pantano. Son burbujas enfermas y febriles en el país, y para detener la fiebre deben poder a asentarse de nuevo en los pantanos.|n|nLos trepadores del pantano se arrastran por los canales de Los Humedales.', },
    {'Mata 8 trepadores del pantano y regresa con Rethiel el Guardaverde en Los Humedales.', },
  },
  [276] = {
    'Patas sucias',
    {'Los gnolls Pellejomusgo han vivido en paz en Los Humedales durante mucho tiempo, pero ahora su número está creciendo. Sus pies pisotean las flores y arbustos del pantano y sus hachas no dejan de talar árboles para alimentar sus fuegos.|n|nHan dejado de estar en equilibrio con la tierra. Para que sobrevivan Los Humedales, debemos reducir a los gnolls.|n|nMata a 15 gnolls Pellejomusgo y a 10 bastardos Pellejomusgo en el Sur, junto a la puerta enana de Algaz. Cuando lo hayas hecho vuelve aquí.', },
    {'Mata 15 gnolls Pellejomusgo y 10 bastardos Pellejomusgo y regresa con Rethiel el Guardaverde en Los Humedales.', },
  },
  [277] = {
    'No al fuego',
    {'Los Pellejomusgo están talando los árboles de Los Humedales, y utilizan su carne para darse calor. ¡No seguiré sufriendo este dolor!|n|nArrebata a los Pellejomusgo los sílex rudimentarios que utilizan para hacer fuego. Todos los Pellejomusgo llevan esos sílex rudimentarios, excepto los pequeños gnolls y bastardos Pellejomusgo.', },
    {'Lleva 9 sílex rudimentarios a Rethiel el Guardaverde.', },
  },
  [278] = {
    'Se aproxima una oscura amenaza',
    {'Ponte a buscar los ingredientes de inmediato, $N. Puedes sacar el veneno de las arañas locales cercanas. Las lágrimas de crocolisco las encontrarás en el Loch en sí. El cristal de Mo\'Grosh ya será más difícil de conseguir. Los extraen los ogros del noreste, pero son muy raros de encontrar.|n|n¡Tenemos que prepararnos para rechazar un ataque de los Hierro Negro! Vuelve cuando tengas todos los ingredientes y prepararé la mezcla.', },
    {'Ashlan Risapétrea que está en el Campamento Mo\'grosh quiere reúnas veneno de rondador, sangre frenética y 1 cristal de Mo\'grosh.', },
  },
  [279] = {
    'Zarpas de las profundidades',
    {'Los múrlocs están emergiendo de las profundidades y construyendo sus aldeas en la costa. Están acosando a nuestros pescadores y mercaderes, y es necesario detenerlos.|n|nEngullidor, uno de esos múrlocs, anda con otros múrlocs Branquiazul y asalta a los mercaderes que pasan por el camino, regresando después a la seguridad de sus casitas. Nuestros mercaderes están amenazados y tenemos que darles seguridad.|n|nEngullidor acecha el río hacia el norte de aquí. Encuéntralo y acaba con él y sus semejantes. Tráeme su cabeza.', },
    {'Mata a 12 múrlocs Branquiazul.|n|nMata a Engullidor y coge su cabeza.|n|nLleva la cabeza de Engullidor a Karl Boran en Puerto de Menethil.', },
  },
  [280] = {
    'Se aproxima una oscura amenaza',
    {'Antes he visto a unos cuantos insurgentes Hierro Negro nadando hacia la Presa con un barril grande. ¡No había ningún montaraz para detenerlos! ¡Creo que han colocado el seforio en la base de la Presa y va a explotar de un momento a otro!|n|n¡Necesito que cojas esta mezcla y la disuelvas en el barril antes de que sea demasiado tarde! ¡Date prisa!', },
    {'El ingeniero jefe Hinderweir quiere que nades hasta la base de la presa, localices el barril de pólvora y disuelvas en él la mezcla neutralizadora para evitar que explote.', },
  },
  [281] = {
    'Recuperación de bienes',
    {'No hace mucho los múrlocs atacaron una nave de mercaderes, La princesa ciega. Aunque el barco escapó intacto, esas inmundas criaturas sacaron gran parte de su cargamento por la borda, incluida una valiosa estatuilla de Terenas Menethil. Queremos recuperar la estatuilla.|n|nRegistra las casuchas múrloc de la costa en busca de cajones, barriles o cualquier otra evidencia del cargamento perdido. Encuentra la estatuilla y vuelve a verme.', },
    {'Busca los cajones y barriles en los campamentos múrloc de la costa.', },
  },
  [282] = {
    'Las observaciones de Senir',
    {'Tenía intención de enviar a mi aprendiz a que entregara a mi hermano Senir mi informe, pero por mi tranquilidad de espíritu... preferiría confiarlo a manos más seguras. Si es que no te importa, claro.|n|nMmm... tendrás que atravesar el túnel para llegar a Kharanos.|n|nHabla con el montaraz Thalos antes de adentrarte en el túnel. Ahora está infestado de troggs.|n|nSigue la carretera para regresar a Yunquemar y luego ve hacia el este hasta llegar al túnel. Thalos no andará lejos.', },
    {'Habla con el montaraz Thalos.', },
  },
  [283] = {
    'Se aproxima una oscura amenaza',
    {'El barril crepita.', },
    {'Parece que la mezcla neutralizadora funciona. Ve a darle la buena noticia al ingeniero jefe Hinderweir.', },
  },
  [284] = {
    'La búsqueda continúa',
    {'Registras a fondo el grupo de casuchas múrloc y no encuentras ni un rastro de la Estatuilla de Menethil.|n|nTal vez encuentres más pistas en las casuchas del Norte y del Noreste.', },
    {'Busca la Estatuilla de Menethil.', },
  },
  [285] = {
    'Inspecciona más casuchas',
    {'Este grupo de casuchas de múrloc, tras inspeccionarlo a fondo, no revela nada.|n|nPe... pero estás $Gseguro:segura; de que la próxima pista que encuentres será muy fructífera.|n|n¡La Estatuilla de Menethil debe estar en alguna de las casuchas del Norte!', },
    {'Sigue buscando la Estatuilla de Menethil en las casuchas de los múrlocs.', },
  },
  [286] = {
    'Devuelve la Estatuilla',
    {'Después de sacar el barril de toda la mugre y abrirlo, descubres una figurilla plateada empaquetada entre paja. Representa a un joven paladín de pelo largo, con un martillo alzado.|n|n¡Tiene que ser la Estatuilla de Menethil! Debes regresar con Karl Boran en el Puerto de Menethil.', },
    {'Lleva la Estatuilla de Menethil a Karl Boran al Puerto de Menethil, en Los Humedales.', },
  },
  [287] = {
    'Poblado Peloescarcha',
    {'Llevo mucho retraso con mi informe y me vendría bien tu ayuda, $N. Conseguí averiguar dónde se esconden los trols, pero vi tantos de ellos que me dio miedo entrar.|n|nPor eso... necesito que entres en la cueva, eches un vistazo y mates a algunos de los trols. Luego vuelves aquí.|n|nSigue la carretera norte que sale de Kharanos, cuando llegues al puente, sigue el río helado hacia el oeste hasta que llegues al Lago Glacial. En la orilla oeste encontrarás Las Birras. La cueva está al suroeste del poblado.', },
    {'Explora el Poblado Peloescarcha y mata a 5 rebanacabezas Peloescarcha para Senir Barbablanca de Kharanos.', },
  },
  [288] = {
    'La Tercera Flota',
    {'En su día fui contramaestre del Dueña de las olas, una nave de alto bordo de la Tercera Flota de Kul Tiras. La flota maldita. Maldita, porque en su último viaje fue atacada por dragones Rojos. ¡Dragones controlados por orcos!|n|nNo teníamos ninguna oportunidad contra el fuego de los dragones... y nuestra flota ardió y se hundió en esta costa. Soy el único superviviente de todas esas desgraciadas naves...|n|n... ¡Oh me va a estallar la cabeza! Tengo que beber algo fresco si quiero acabar con esta resaca y seguir con mi historia.', },
    {'Compra un cántaro de hidromiel para el contramaestre Fistimos.', },
  },
  [289] = {
    'La tripulación maldita',
    {'<Algo recuperado Fistimos sigue contando su historia...>|n|nSoy el único superviviente de la Tercera Flota de Kul Tiras, naufragada en la costa del Norte. ¡Pero aunque soy el único miembro de la flota que sigue con vida, no soy el único que sigue por aquí! Uno de nuestros barcos ocultaba un gran y terrible tesoro y su espeluznante poder tiene atrapadas las almas de mis hermanos entre los descompuestos cascos de los barcos.|n|nSi quieres liberar a algunos de mis hermanos tal vez puedas romper su maldición.', },
    {'Mata 13 marineros malditos, 5 marinos malditos y al contramaestre Snellig. Lleva la tabaquera de Snellig al contramaestre Fistimos en Puerto de Menethil.', },
  },
  [290] = {
    'Purga de la maldición',
    {'Para romper la maldición y liberar a todos mis hermanos, hay que recuperar y purificar la... cosa... que guardaba mi barco. No sé lo que era, pero sé que estaba almacenada en la caja fuerte del barco. El capitán Halyndor era el único que tenía la llave.|n|nMi buen capitán sigue presente en mis sueños. Sé que sigue en el barco, El Intrépido. Hazte con la llave y utilízala para abrir la caja fuerte de El Intrépido.|n|nEntonces, cuando tengas esa maldita cosa, llévasela al sacerdote Glorin Frenteacerada en la ciudad.', },
    {'Obtén la llave de la caja fuerte de El Intrépido del capitán Halyndor.|n|nUtiliza la llave para abrir la caja fuerte de El Intrépido.', },
  },
  [291] = {
    'Los informes',
    {'¡Fantástico! Lleva mi informe al senador Barin Rocarroja. Es un tipo muy agrio; procura que no te contagie su desbordante alegría. Está en Forjaz, en la cámara en la que el rey Magni celebra sus audiencias.|n|n¿Que no sabes llegar a Forjaz? Sigue la carretera norte que sale de Kharanos, cruza el puente, sigue el camino del este que verás bordeado de estandartes, y que sube por la ladera de la montaña.|n|nPor cierto... ¿podrías no mencionar eso de que me has ayudado? No me gustaría que pensaran que no trabajo duro, ya me entiendes.', },
    {'Entrega el informe de Senir al senador Barin Rocarroja de Forjaz.', },
  },
  [292] = {
    'El ojo de Paleth',
    {'Al abrir el cofre descubres un orbe ennegrecido, que parpadea con una luz espeluznante. Es el tesoro del que hablaba Fistimos: un Ojo maldito de Paleth.|n|nLleva el Ojo maldito de Paleth al sacerdote enano Glorin Frenteacerada, en el Puerto de Menethil. Pregúntale como eliminar la maldición del Ojo.', },
    {'Lleva el Ojo maldito de Paleth a Glorin Frenteacerada al Puerto de Menethil en Los Humedales.', },
  },
  [293] = {
    'Limpieza del ojo',
    {'No puedo borrar la maldición del ojo de Paleth. Los ojos fueron creados por sacerdotes humanos, así que tendrás que ir a Ventormenta para encontrar a alguien que pueda ayudarte. Habla con el arzobispo Benedictus. Está al frente de la Catedral de la Luz de Ventormenta. El podrá ayudarte.|n|nEso espero, por tu bien.', },
    {'Lleva el Ojo maldito de Paleth al arzobispo Benedictus. Benedictus se encuentra en la Catedral de la Luz, en la ciudad de Ventormenta.', },
  },
  [294] = {
    'La venganza de Ormer',
    {'La situación es grave, ciertamente. Cuando descubrimos estos huesos acudieron los raptores, atraídos por ellos. Esas bestias inmundas mataron a mis hermanos y nos atraparon a mí, a Merrin y al pobre prospector.|n|nLimpia Los Humedales de esos raptores, $N. Encontrarás raptores jaspeados y estridadores jaspeados al oeste de este risco. Mata 10 ejemplares de cada, si puedes.|n|nSerá un buen comienzo para la venganza que he planeado.', },
    {'Ormer Trenzaferro de la Excavación de Whelgar quiere que mates 10 estridadores jaspeados y 10 raptores jaspeados.', },
  },
  [295] = {
    'La venganza de Ormer',
    {'Ha llegado el momento de que esos pavorosos raptores lamenten su sed de sangre. Aquí debajo podrás encontrar decenas de segadores jaspeados y tajobuches jaspeados. Haz pagar todas sus deudas a esas terribles criaturas matando a 10 de cada clase.', },
    {'Ormer Trenzaferro quiere que mates 10 raptores segadores jaspeados y 10 raptores tajobuches jaspeados y que vuelvas a verle en la Excavación de Whelgar.', },
  },
  [296] = {
    'La venganza de Ormer',
    {'Mientras estabas ahí abajo pude observar que una de esas bestias destacaba sobre el resto. Era más grande y amenazadora. Apuesto a que es la que condujo hasta aquí al resto para atacar la excavación.|n|nTe pido una última tarea, $N. Hay que hacer justicia con ese Sarldente, y de acuerdo a la gravedad de sus crímenes, justicia no significa otra cosa que pena de muerte. Tráeme una de sus garras como prueba de su muerte.', },
    {'Ormer Trenzaferro de la Excavación de Whelgar quiere que mates a Sarldente y que le lleves una de sus garfas cuando completes la tarea.', },
  },
  [297] = {
    'Recoger ídolos',
    {'Hace poco, justo antes de que los troggs emergieran en esta excavación, descubrimos una gran cantidad de extraños ídolos grabados. Pero no tuvimos oportunidad de estudiarlos, ya que poco después del descubrimiento ¡los troggs nos echaron de las ruinas! Y esos ídolos tienen un efecto extraño en los troggs. ¡Los vuelve locos!|n|nTráeme 8 ídolos: quiero estudiarlos y ¡quiero apartarlos de las manos de los troggs! Encontrarás los ídolos en los troggs que infestan la zona.', },
    {'Lleva 8 ídolos de piedra grabados a Magmar Ceñimal en la Excavación de Vetaferro.', },
  },
  [298] = {
    'Un informe sobre el avance de la excavación',
    {'Tengo que enviar un informe a Thelsamar. ¡Eso, e insistir en mi pedido de pólvora! Este es el informe. Llévaselo a Jern Cornamenta, es nuestro contacto en Thelsamar.|n|nNo es un encargo difícil, pero no tengo a nadie más para hacerlo.', },
    {'Lleva el informe de Vetaferro a Jern Cornamenta a Thelsamar.', },
  },
  [299] = {
    'Desvelando el pasado',
    {'Justo antes de la invasión descubrí una tablilla, era la llamada piedra Goaz. El texto traducido se interrumpe en cuatro puntos. Se habla de un "plan divino" y de una "profecía maldita."|n|nTemo que nos estemos quedando sin tiempo. Soy demasiado viejo para ir a enfrentarme con esas bestias. Pero tú eres fuerte.|n|nRegistra la excavación y encuentra los 4 trozos perdidos de la tablilla: Ados, Modr, Golm y Neru. Búscalos en artefactos antiguos o donde veas tierra suelta. ¡Tráemelos y podré empezar a descifrar este misterio!', },
    {'El prospector Whelgar quiere que te adentres en la excavación en busca de los 4 fragmentos de tablilla perdidos: Ados, Modr, Golm y Neru.', },
  },
  [301] = {
    'Informe a Forjaz',
    {'Necesitamos autorización para llevar más pólvora a Vetaferro. Lleva este informe a la oficina central de la Liga de Expedicionarios, en Forjaz.|n|nAquí tienes el informe. Dáselo al prospector Pico Tormenta y no olvides agacharte en cuanto lo hagas. Pico Tormenta tiene muy mal genio y no le va a gustar lo lento que va Vetaferro.|n|nLo encontrarás en la Asamblea de Expedicionarios.', },
    {'Lleva el informe de Vetaferro al prospector Pico Tormenta.', },
  },
  [302] = {
    'Pólvora para Vetaferro',
    {'¡Si Vetaferro necesita más pólvora, por Magni que la va a tener! Ya le he enviado la autorización a Jern Cornamenta a Thelsamar. Él preparará el envío para Vetaferro.|n|nY otra cosa: quiero que te ocupes personalmente de que la pólvora llega a su destino. El último envío no llegó, así que mantén los ojos abiertos.', },
    {'Habla con Jern Cornamenta en Thelsamar.', },
  },
  [303] = {
    'La guerra contra los Hierro Negro',
    {'La guerra arde aquí en casa y en el extranjero. Mientras los grandes soldados enanos dan sus vidas en tierras lejanas en nombre de la Alianza, nuestras propias tierras caen víctimas de la depravación de los enanos Hierro Negro. Arrasaron el Puente Thandol y Dun Modr cayó poco después.|n|nTe necesitamos para reunir fuerzas y hacer retroceder el frente. Si puedes matar a 10 enanos Hierro Negro, 5 tuneladores, 5 saboteadores y 5 demoledores, tal vez la reserva consiga llegar a tiempo para terminar la ofensiva.|n|n¡Date prisa!', },
    {'Motley Garmason de Dun Modr quiere que mates 10 enanos Hierro Negro, 5 tuneladores Hierro Negro, 5 saboteadores Hierro Negro y 5 demoledores Hierro Negro.', },
  },
  [304] = {
    'Una misión hedionda',
    {'Muchos de mis soldados murieron en la batalla de Dun Modr. Mi propio hermano murió cuando fue destruido el Paso Oeste del Puente Thandol. Sí señor, los enanos Hierro Negro son una raza diabólica. A partir de lo que Roggo pudo reunir, el líder de matones en Los Humedales es un brujo llamado Balgaras el Hediondo. Es un auténtico cobarde, que envía a sus soldados para que cumplan sus órdenes y él se queda escondido en Cerro Fraguaferoz, al sureste.|n|nSi puedes encontrar a esa escoria escurridiza, mátalo y tráeme su oreja. Sabré recompensarte, $C.', },
    {'Mata a Balgaras el Hediondo y lleva su oreja a Largatrenza el Nefasto a las afueras de Dun Modr.', },
  },
  [305] = {
    'La búsqueda del equipo de excavación',
    {'¡Oh, debes ser $Gel explorador enviado:la exploradora enviada; por Largatrenza! No puedes imaginar lo preocupado que he estado.|n|nDurante un mes, mi mujer, Merrin, me ha estado enviando cartas cada semana. Forma parte del equipo de la Excavación de Whelgar, pero hace casi dos semanas que he dejado de recibir sus cartas. ¡Seguro que algo va mal!|n|nLargatrenza dijo que si no recibíamos noticias del equipo enviaría a un explorador para comprobar cómo va todo. Supongo que tú eres ese explorador, $N. ¡Busca a Merrin en la excavación, al Este!', },
    {'Tarrel Tejepiedra quiere que viajes a la Excavación y que contactes con Merrin Tejepiedra.', },
  },
  [306] = {
    'La búsqueda del equipo de excavación',
    {'¡Fue horrible! Estábamos desenterrando unos extraños artefactos cuando dimos con estos grandes huesos.|n|nAntes de poder saber qué sucedía, los raptores jaspeados inundaron la excavación. Se perdieron muchas vidas.|n|nOrmer... tan valiente... nos salvó al prospector y a mí. Nos defendió mientras corríamos a buscar refugio. Ahora estamos atrapados y todo nuestro trabajo está perdido.|n|nToma, lleva esta nota a mi querido Tarrel. En ella le explico cuál es nuestra situación.', },
    {'Lleva la nota de Merrin a Tarrel Tejepiedra al Puerto de Menethil, en Los Humedales.', },
  },
  [307] = {
    'Zarpas asquerosas',
    {'La Mina de Fuenteplata, que cae al este, se agotó hace tiempo. La Liga de Mineros la usaba como almacén, pero ahora se han instalado unos kóbolds allí, ¡con esas magníficas herramientas enanas a su alcance!|n|nLos expulsaremos, pero la Liga quiere que vaya alguien a recoger el material antes de que lleguemos los soldados a romperlo todo. Es muy arriesgado; será mejor que lleves compañía.|n|nEl material está en unas cajas con la marca de la Liga de Mineros a lo largo de la mina. Suerte.', },
    {'Ve a la Mina de Fuenteplata y recoge 6 cargas de equipamiento de minero. |n|nLuego ve a ver al montaraz Pico Tormenta.', },
  },
  [308] = {
    'Distraer a Jarven',
    nil,
    nil,
  },
  [309] = {
    'Proteger el envío',
    {'Tenemos que llevar esta pólvora a Vetaferro, pero este carro no va a ninguna parte. Es una carga muy pesada y esta zona es peligrosa. Además, quién sabe qué más nos tienen reservado los Hierro Negro ahora que Saean está con ellos.|n|nMe tranquilizaría bastante que me ayudases a vigilar. Miran puede descargar los barriles de pólvora en el campamento mientras tú y yo protegemos el carro.', },
    {'Protege a Huldar y la caravana Vetaferro y luego informa al prospector Vetaferro.', },
  },
  [310] = {
    'Rivales acérrimos',
    {'Tengo que reconocer que esos Cebatruenos preparan unas bebidas estupendas. ¡Pero hay que bajarles los humos! ¡La suya no es la única bebida decente del mundo! Quizás tú puedas ayudarme a darles una lección...|n|nTen, coge este barril de brebaje de Cebadiz. Cuélate en el sótano de la Destilería Cebatruenos de Kharanos y cámbialo por uno de sus barriles de Cerveza del Trueno. ¡Y ya veremos qué brebaje les gusta más a los clientes!|n|nY si encuentras guardias vigilando los barriles, intenta distraerlos...', },
    {'Ve al sótano de la Destilería Cebatruenos de Kharanos y sustituye un barril de cerveza del Trueno con uno de brebaje de Cebadiz.', },
  },
  [311] = {
    'Regresa junto a Marleth',
    {'Ya has dejado el barril del brebaje de Marleth en el almacén de la destilería de Kharanos y recoges un barril de Cerveza del Trueno como prueba de que has cumplido...', },
    {'Lleva el barril de cerveza del Trueno a Marleth Cebadiz a Las Birras.', },
  },
  [312] = {
    'La reserva robada de Tundra MacGrann',
    {'Tenía carne seca para un mes, salada y bien guardada para la estación fría. ¡Estaba bajo llave para que los osos no se la comieran! Pero cuando salí a cazar ciervos, esa bestia, el Viejo Barbahielo, se las arregló para romper la cerradura. Eso sí, no podrá con el torio, seguro. Claro que yo me moriré de hambre si no recupero mi carne.|n|nSeguro que tú te mueves con más sigilo que yo. ¿No podrías ir a recuperar mi alijo? Con esta pierna coja no conseguiré entrar y salir de esa cueva con suficiente rapidez.', },
    {'Ve a la cueva del Viejo Barbahielo y recupera la carne seca de Tundra MacGrann de la caja fuerte robada.', },
  },
  [313] = {
    'Vigilando desde lejos',
    nil,
    nil,
  },
  [314] = {
    'La protección del rebaño',
    {'Oímos los gritos en medio de la noche. Y esta mañana faltaban dos cabezas de ganado. Esa ruin bestia conocida como Vagash ha estado alimentándose de nuestro sustento. Con la mayoría del ejército de Forjaz mermado, no queda nadie para mantener a raya a Vagash.|n|nQuizás tú tengas el valor necesario para buscar a ese animal y matarlo. Tráeme uno de sus colmillos y te daré una recompensa. Vagash acecha desde encima de este rancho. Ten cuidado, es peligroso.', },
    {'Consigue el colmillo de Vagash.', },
  },
  [315] = {
    'La cerveza perfecta',
    {'Mi misión consiste en conseguir la cerveza perfecta. Sé que puedo hacerlo, llevo la cebada en la sangre. Solo tengo que encontrar la receta adecuada...|n|nLos trols Peloescarcha cultivan una planta llamada cardaluz en lo alto de Monte Luz, al noroeste. La utilizan para rituales extraños y tribales. Nosotros los enanos casi no la usamos, pero tiene un sabor único... y quisiera experimentar con él en mis cervezas.|n|nConseguir el cardaluz puede ser peligroso, pero pagaré bien por lo que "cojas prestado" de las canastas del poblado trol.', },
    {'Llévale 7 cardaluz a Rejold Cebadiz en Kharanos.', },
  },
  [317] = {
    'Los suministros del reactor a vapor',
    {'Me estoy preparando para empezar una misión para la Brigada de Asedio. Es una misión larga y tengo que cargar un mes de suministros en mi reactor a vapor. Así que, mientras Brasacerada trabaja en mi tanque, quizás podrías ir de caza por mí...|n|nNecesito pieles para hacerme una cama y carne para comer. Puedes cazar jabalíes para la carne y osos para las pieles... ve a los campos nevados que hay al sur de El Cubil Pardo.', },
    {'Reúne 4 trozos de carne de jabalí y 2 pelajes de oso grueso y llévaselas al piloto Bramiz al Almacén de Brasacerada.', },
  },
  [318] = {
    'La tajada',
    {'Rejold Cebadiz experimenta con sus brebajes. Algunos saben bien, otros mal y otros... bueno, esos tumbarían al enano más fuerte.|n|nVive en Las Birras, al oeste de Kharanos. Y lo que quiero es una de sus bebidas: tajada. Me mantendrá caliente en los caminos más fríos.|n|nY... ¡ese bendito líquido quema tanto que también puedo usarlo para aumentar la potencia de mi reactor a vapor! Me ha sacado de un apuro más de una vez.', },
    {'Consigue un tonel de tajada de Rejold Cebadiz de Las Birras.', },
  },
  [319] = {
    'Un favor a cambio de un barril de tajada',
    {'Tengo un tonel de tajada, pero... ¿podrías hacerme un favor? En Las Birras vendría bien un poco de ayuda con los animales salvajes que deambulan por las nieves de los alrededores. A veces se acercan demasiado.|n|nNo es que tengamos miedo de los osos, los gatos ni los jabalíes... ningún enano que se precie lo tiene. Pero si tú pudieras ocuparte de esos animales, tendríamos más tiempo para trabajar y hacer cerveza.', },
    {'Mata a 6 osos zarpahelada, 8 jabalíes del risco mayores y 8 leopardos de la nieve y luego vuelve a Las Birras con Rejold Cebadiz.', },
  },
  [320] = {
    'Regresa junto a Bramiz',
    {'Aquí tienes tu tonel de tajada, $N. Y, una vez más, gracias por la caza.', },
    {'Entrega el tonel de tajada al piloto Bramiz en el Almacén de Brasacerada.', },
  },
  [321] = {
    'Hierro Forjaluz',
    {'Los restos de naufragios que puedes ver en nuestra costa son la Tercera Flota maldita de Kul Tiras, incendiada y hundida por los dragones Rojos durante la última Gran Guerra.|n|nLa flota procedía de Lordaeron, pero un destructor élfico, el Pigargo volador, estaba con ella. Transportaba un envío de hierro Forjaluz y se unió a la Tercera Flota en busca de protección. Irónicamente lo hundieron los mismos dragones...|n|nPero basta de hablar. El Pigargo volador naufragó al sur del Puerto de Menethil. Si encuentras el hierro Forjaluz, tráemelo.', },
    {'Busca los restos del Pigargo volador en Los Humedales.', },
  },
  [322] = {
    'Brazo bendito',
    {'Hay un armero enano en el Distrito de los Enanos de Ventormenta que puede trabajar con este hierro Forjaluz. Su nombre es Grimand Elmore.|n|nHe empaquetado en un cajón el hierro que encontraste. Llévaselo a Grimand y cuéntale toda tu historia. Seguro que estará muy agradecido a alguien comprometido con una búsqueda como la tuya y te hará un arma... ¡un arma que haría temblar hasta al mismísimo Morbent Vil!', },
    {'Lleva el cajón de lingotes Forjaluz a Grimand Elmore en Ventormenta.', },
  },
  [323] = {
    'Pon a prueba tu valor',
    {'Morbent Vil es un nigromántico y un aliado de los Jinetes Oscuros. Te enfrentaría al poder de Morbent Vil, pero no te enviaré a luchar contra ese demonio sin conocer tu fuerza.|n|nYa me has probado tu valentía pero, si de verdad quieres enfrentarte al nigromántico, tendrás que probar primero que puedes derrotar a sus esbirros.', },
    {'Mata a 15 asaltantes esqueléticos, 3 sanadores esqueléticos y 3 depositarios esqueléticos y vuelve a donde Sven.', },
  },
  [324] = {
    'Los lingotes perdidos',
    {'Después de sacar un único lingote Forjaluz del cofre anegado, está claro que los múrlocs robaron el resto. Da caza a los asaltantes múrloc que rodean los restos del Pigargo volador y busca el resto del hierro Forjaluz perdido.', },
    {'Reúne 5 lingotes de Forjaluz y vuelve junto a Glorin Frenteacerada en Los Humedales.', },
  },
  [325] = {
    'Armado y listo',
    {'Aquí tienes el arma para vencer al demonio ese del que me hablaste. Ya estás $Gpreparado:preparada;, $N. Te deseo mucha suerte, ¡y esperaré con ansia escuchar la leyenda de tu gloria!', },
    {'Lleva la Pesadilla de Morbent a Sven en el Bosque del Ocaso.', },
  },
  [326] = {
    nil,
    {'En todo, los paladines deben reflejar la Luz, que complementa nuestra fuerza. Esforzarse por ser divino para uno de nuestra clase no significa esforzarse por la divinidad, nos esforzamos por hacerlo bien en todas las acciones.|n|nAunque nos llaman para golpear al mal en estos tiempos difíciles, debes recordar siempre que ayudar a los demás es lo que te distingue de los demás ciudadanos. Compasión, paciencia, valor... esas cosas significan tanto para un paladín como la fuerza en la batalla.|n|nApréndelo y no lo olvides nunca', },
    nil,
  },
  [328] = {
    'La llave oculta',
    {'Si bien en los registros no aparece ninguna mención al soldado Thorsen, escondida en la tapa de uno de los libros de contabilidad de Herod hay una pequeña llave de latón.|n|nY, tras estudiar en profundidad sus notas, aparecen algunas referencias entre varios papeles, a una "caja fuerte segura". La caja está en algún lugar de Las Reservas, el complejo de cuevas que está en la parte trasera de la Base de Kurzen.|n|nSi encontramos la caja fuerte y la pequeña llave de latón puede abrirla, quizás descubramos el misterio tras la detección de Thorsen.', },
    {'Utiliza la pequeña llave de latón para abrir la caja fuerte del corredor Herod.', },
  },
  [329] = {
    '¡Espía descubierto!',
    {'Entre los objetos de la caja fuerte hay una nota sucia llena de garabatos. Aunque casi es imposible de leer, parece ser un itinerario para el soldado Thorsen. Detalla sus rutas de patrulla, con quién habla y cómo pasa su tiempo con los rebeldes. Está firmada con una letra: M.|n|nPero quien fuera que escribiera esta nota debe de haber estado muy cerca de Thorsen. Quien escribió esta nota es el traidor del Asentamiento Rebelde.', },
    {'Lleva la nota sucia al teniente Doren en el Asentamiento Rebelde.', },
  },
  [330] = {
    'Horarios de patrulla',
    {'Esa nota que me diste está firmada con una "M"... No sé lo que puede significar.|n|nPero... la nota también dice que esta persona compartió las rutas de patrulla con Thorsen la semana pasada. Así que, quien compartió las rutas de patrulla con Thorsen la semana pasada es el traidor.|n|nVete a ver al cabo Sethman. Se encarga de hacer los horarios de patrulla y podrá decirte quién estaba con Thorsen.', },
    {'Habla con el cabo Sethman.', },
  },
  [331] = {
    'Informa a Doren',
    {'¿Te pidió el teniente Doren que volvieses a informarle sobre las patrullas?', },
    {'Habla con el teniente Doren.', },
  },
  [332] = {
    'Publicidad de la bodega',
    {'Si hablas sobre vino con alguien, sabrás que nosotros, los Galina, vendemos el mejor vino de Ventormenta. Y no estamos lejos; seguimos en el Distrito de Mercaderes, en los preciosos canales de la ciudad.|n|nToma, coge este panfleto. Llévaselo a mi hermana Suzetta a nuestra tienda. A cambio te dará una botella de regalo de nuestro famoso Dalaran Noir. ¡No lo lamentarás!', },
    {'Ve a la Bodega Galina y lleva a Suzetta Galina el cupón de vino para una botella gratis.', },
  },
  [333] = {
    'Harlan necesita un nuevo suministro',
    {'Últimamente el negocio ha ido bien. Parece que todo el mundo está comprando armaduras y ropas resistentes. Es casi como si esperasen una época dura y fría...|n|nPero esas son preocupaciones futuras. Mi preocupación del día es que me estoy quedando sin ropas tejidas que vender. Necesito otro cargamento de nuestro suministrador.|n|nSi puedes llevar este pedido a Rema Schneider en Trajes y Arreglos a Medida, te lo agradecería mucho.', },
    {'Ve a Trajes y Arreglos a Medida y lleva a Rema Schneider el paño que ha pedido Harlan Bagley.', },
  },
  [334] = {
    'Un paquete para Thurman',
    {'Mi hijo Thurman es un aprendiz en Diseños Larson, en el Barrio de los Magos. Hoy salió con prisa y se olvidó su trasquiladora y las agujas. Sé que $Gun gran:una gran; $C como tú debe de tener importantes tareas entre manos, ¡pero sin sus herramientas, Thurman no puede hacer su trabajo de aprendiz!|n|nPor favor, $N. ¿Podrías llevar las herramientas de coser a mi hijo? Diseños Larson es una de las dos tiendas de ropa en el Barrio de los Magos, la que está más al fondo, cerca de la torre de los magos.', },
    {'Ve a Diseños Larson en el Barrio de los Magos de Ventormenta y entrega a Thurman Schneider sus herramientas de coser.', },
  },
  [335] = {
    'Una noble cerveza',
    {'Lord Wishock está causando gran agitación en la Casa de Nobles. Se ha enterado de lo de nuestro pequeño "establecimiento" aquí abajo y está presionando para que se realice una investigación en toda regla. Tengo un plan para mantener a Wishock "preocupado", pero necesito tu ayuda.|n|nEn el Jardín de Stalvan, a las afueras de Villa Oscura, crece una flor. Esta pequeña flor blanca es conocida como la lágrima de Tilloa. También necesitaré una zibética, que solo se puede encontrar en la base de las cascadas bajo la Presa de las Tres Cabezas, en Los Humedales.', },
    {'Zardeth de los Zarpanegra, quiere que le lleves una lágrima de Tilloa de Villa Oscura y una zibética de Los Humedales.', },
  },
  [336] = {
    'Una noble cerveza',
    {'Lord Wishock, como todos los hombres, tiene sus puntos débiles. Y, resulta que su punto más débil es el licor. La hipocresía es asombrosa. El pobre necio pasa sus días intentando cerrar nuestra pequeña "taberna" y las noches arriba, bebiendo y aumentando una cuenta que nunca paga. Bueno, veamos qué le parece a Wishock este brebaje especial que le he preparado: cerveza Zarpanegra. Es bastante fuerte, $N.|n|nLlévasela y veamos si le gusta. Lo más probable es que el viejo tonto esté dando vueltas por la Sala de los Ruegos.', },
    {'Lleva la cerveza Zarpanegra a Lord Wishock en la Sala de los Ruegos.', },
  },
  [337] = {
    'Un viejo libro de Historia',
    {'Aunque la cubierta de este libro está llena de arañazos y de barro, aún se pueden leer las palabras del lomo: La Historia de Ventormenta. Al abrir el libro se ve claramente el sello de la biblioteca de Ventormenta en la primera página.|n|nParece que alguien sacó este libro y no lo llegó a devolver...', },
    {'Devuelve el libro: La Historia de Ventormenta a La Biblioteca de Ventormenta.', },
  },
  [338] = {
    'Las verdes colinas de Tuercespina',
    {'¡Oh, el maestro Nesingwary se sentirá muy disgustado si lo descubre!|n|nConfiaba en mí para revisar el manuscrito de su novela, Las verdes colinas de Tuercespina. Todo iba bien, pero un golpe de viento pasó por el campamento y las páginas quedaron dispersas por todas partes.|n|nConseguí reunir la mayor parte de las páginas, pero hay muchas todavía por la jungla. Reúne las páginas para completar los cuatro capítulos.|n|nYo te ayudaré a organizarlas. Devuélveme los capítulos cuando tengas los cuatro.', },
    {'Reúne las páginas perdidas del manuscrito Las verdes colinas de Tuercespina. Cuando los cuatro capítulos estén completos, llévaselos a Barnil.', },
  },
  [339] = {
    'Capítulo 1',
    {'¡El capítulo I es fascinante! El maestro Nesingwary establece el telón de fondo de la historia y menciona a sus compañeros de caza, ¡incluyéndome a mí!|n|nPero eso no viene al caso. Déjame ver las páginas que faltan. Parece ser que las páginas 1, 4, 6 y 8 siguen todavía por algún lado en la jungla.', },
    {'Lleva las páginas 1, 4, 6 y 8 de Las verdes colinas de Tuercespina de Nesingwary a Barnil Jarropetra para completar el capítulo I.', },
  },
  [340] = {
    'Capítulo 2',
    {'El capítulo II está lleno de historias excitantes sobre la caza de panteras y tigres. ¡Me patearía la cara por haber dejado que las páginas volaran!|n|nParece ser que conseguí recuperar todas las páginas menos las 10, 11, 14, y 16.', },
    {'Lleva las páginas 10, 11, 14 y 16 de Las verdes colinas de Tuercespina de Nesingwary a Barnil Jarropetra para completar el capítulo II.', },
  },
  [341] = {
    'Capítulo 3',
    {'El capítulo III es mi favorito. Habla de la primera caza de Sir Erlgadin y Lady Rouack con un rifle enano. Y, al final del capítulo III, ¡menudo suspense!|n|nMe parece que todavía necesitamos las páginas 18, 20, 21 y 24 para terminar el capítulo. Esas páginas están ahí fuera, en algún lugar...', },
    {'Lleva las páginas 18, 20, 21 y 24 de Las verdes colinas de Tuercespina de Nesingwary a Barnil Jarropetra para completar el capítulo III.', },
  },
  [342] = {
    'Capítulo 4',
    {'Ah, el capítulo IV, ¡el gran final! ¡Y menudo final!|n|nSolo nos faltan tres páginas de este capítulo. Necesitamos las páginas 25, 26 y 27 para finalizar el capítulo IV.', },
    {'Lleva las páginas 25, 26, y 27 de Las verdes colinas de Tuercespina de Nesingwary a Barnil Jarropetra para completar el capítulo IV.', },
  },
  [343] = {
    'Hablando de entereza',
    {'Voy a dar un discurso sobre la fortaleza de espíritu y me gustaría recitar unos pasajes de un libro sobre metalurgia, "La tensión del hierro". En el Archivo Real, en el Castillo de Ventormenta debería haber una copia del libro. ¿Podrías ir a buscarlo para mí? Si lo haces, ¡que las bendiciones de la Luz te acompañen!|n|nEl Archivo Real es enorme, pero el bibliotecario jefe, Milton Gavilla, conoce todas las estanterías como la palma de su mano. Habla con él, te dará el libro.', },
    {'Ve al Archivo Real en el Castillo de Ventormenta y habla con Milton Gavilla. Podrá encontrar el libro sobre metalurgia que el hermano Kristoff necesita para su charla.', },
  },
  [344] = {
    'Hermano Paxton',
    {'¿La tensión del hierro? Sí, conozco el libro. Es bastante bueno, lo escribió el minero enano Margulf Blaggon hace unas décadas. Pasó la mayor parte de su vida en las profundidades de Khaz Modan, extrayendo minerales. ¡Un tipo listo!|n|n¿Por dónde iba? ¡Oh, sí, La tensión del hierro! Me temo que el libro se llevó a la Abadía de Villanorte. El custodio de la biblioteca de la Abadía, el hermano Paxton, quería hacer una copia del libro para su biblioteca.|n|nPero eso fue hace meses. Me pregunto por qué estará tardando tanto...', },
    {'Habla con el hermano Paxton en la Abadía de Villanorte.', },
  },
  [345] = {
    'Suministros de tinta',
    {'Quería terminar mi copia de La tensión del Hierro, pero...|n|nBueno, verás, hago mi propia tinta para los libros que copio. Es mi propia receta. No se corre ni mancha y se seca muy rápido. Por desgracia, ¡se seca demasiado rápido! La que me quedaba se secó antes de que pudiera acabar la copia y no he tenido oportunidad de hacer más tinta.|n|nPara hacer más, necesito mineral de hierro de Rethban, de las Montañas Crestagrana. El supervisor Olento, en Villa del Lago, es quien me lo suele suministrar.', },
    {'Habla con el supervisor Olento en Villa del Lago y pregúntale sobre el mineral de hierro de Rethban.', },
  },
  [346] = {
    'Regresa junto a Kristoff',
    {'Ahora que he terminado de copiar el libro, aquí tienes el original de La tensión del hierro. Gracias por tu paciencia y, si ves a Milton, por favor, dile que siento haberme retrasado tanto.', },
    {'Vuelve a hablar con el hermano Kristoff en la Plaza de la Catedral. Entrégale el libro La tensión del hierro.', },
  },
  [347] = {
    'Mena de Rethban',
    {'La mena de Rethban tiene ese nombre por el hombre que lo descubrió, Bart Rethban. Cuando se funde, no es tan fuerte como el hierro, pero tiene un color oscuro que algunos escribas utilizan en sus tintes. Se puede encontrar en las Cavernas de Rethban, al norte de aquí.|n|nGeneralmente lo tenemos almacenado, pero estamos demasiado ocupados preparándonos para los atacantes orcos que no hemos tenido tiempo de recogerlo. Y, además, los gnolls de Crestagrana viven ahora en las Cavernas de Rethban y sus esclavos se encargan de recoger el mineral.|n|nAsí que si necesitas recogerlo, tendrás que ir a por él.', },
    {'Reúne 5 montones de mineral de hierro de Rethban y llévaselos al hermano Paxton en la biblioteca de Villanorte.', },
  },
  [348] = {
    'La fiebre de Tuercespina',
    {'M... me... m... muero...|n|n... T... tengo la fiebre de Tuercespina... un virus m... mortal...|n|n... La única cura... es... comer el corazón de M... mokk el Salvaje... una esquiva bestia blanca...|n|n... El médico brujo Unbagwa... es el único que p... puede invocar...|n|n... Busca a Unbagwa en una cueva oculta en el cabo... del sur...|n|n... Rápido... m... me... muero...', },
    {'Busca al médico brujo Unbagwa y haz que invoque a Mokk el Salvaje. Lleva el corazón de Mokk a Fin Fizqueta.', },
  },
  [349] = {
    'La fiebre de Tuercespina',
    {'temp text 02 – descripción', },
    {'temp text 02 - registro', },
  },
  [350] = {
    'Mira por un viejo amigo',
    {'Ese Marzon tenía que contactar con un miembro de los Defias y llegar a un acuerdo con Lescovar...|n|nCon VanCleef y Thredd muertos, no sería fácil llevar a Lescovar ante la justicia, ya que las pruebas no sirven de nada sin sus testimonios. Y eso, sin considerar que Lescovar es un noble, y está muy bien conectado. Efectivamente, eso hace que esté por encima de la ley.|n|nVas a necesitar más ayuda. Odio hacer esto, pero conozco a alguien que nos ayudará. Busca a Trias en el Distrito de Mercaderes de la ciudad.', },
    {'Habla con Elling Trias en Ventormenta.', },
  },
  [351] = {
    '¡Encontrar a OOX-17/TN!',
    {'Has descubierto una especie de dispositivo metálico extraño con forma de huevo. Al tocar uno de sus botones el huevo cobra vida y descubres que se trata de algún tipo de artilugio robótico de invención gnómica. A continuación, una voz resuena en su interior.|n|n"Mi nombre es Oglethorpe y he perdido a mi robot mensajero. Si lo encuentras te daré una recompensa. Por favor, llévale este localizador al robot. ¡Genial, acabo de obtener las coordenadas! ¡Parece que se estropeó cerca de Sima Abierta en Tanaris!"', },
    {'Llévale el localizador de emergencia al robot mensajero de Oglethorpe.', },
  },
  [352] = {
    nil,
    {'Gran Mammoda. Esa criatura era gigantesca, con unas garras y unos dientes como espadas. Me cogió por sorpresa, pero no creo que haber estado listo hubiera sido de mucha ayuda. ¡Un golpe y puf! Oscuridad. Dicen que tengo suerte de poder seguir andando...|n|nBueno, no es muy alegre el relato de esa vieja historia, ¿verdad? De todos modos, $N, si te apetece medirte a esa bestia que es la Dama de Loch Modan,', },
    nil,
  },
  [353] = {
    'Una entrega a Pico Tormenta',
    {'Los Pico Tormenta son unos enanos muy respetados y famosos por su exigente gusto. Así que no es sorprendente que Gringer Pico Tormenta, un montaraz de Forjaz, me encargase que forjase un arma para él.|n|nHe terminado el arma, pero... el montaraz Pico Tormenta está muy lejos, en Loch Modan. Si tienes planeado viajar al norte, ¿podrías entregarle este paquete?|n|nEl último mensaje que recibí del montaraz Pico Tormenta, decía que estaba estacionado en la torre de vigilancia del norte, en Loch Modan.', },
    {'Entrega el paquete Pico Tormenta al montaraz Pico Tormenta en Loch Modan.', },
  },
  [354] = {
    'Muertes en la familia',
    {'Los Agamand eran una de las familias más prósperas de los Claros de Tirisfal. Yo solía trabajar en sus molinos... antes de la Peste.|n|nCuando la Plaga apareció por primera vez, los Agamand fortificaron su casa y convencieron a todos sus empleados para que se quedaran y les ayudaran a defenderse. Fuimos unos insensatos pero, al menos, fuimos unos insensatos leales.|n|nLos Agamand, a causa de su orgullo, nos abocaron a todos a la desgracia. ¡Y ahora son esbirros de la Plaga!|n|nSirve a los Renegados y derrota a los Agamand, que sucumbieron a la peste. Sírveme a mí y tráeme sus restos.', },
    {'Llévale los restos de Gregor, los restos de Nissa y los restos de Thurman a Coleman Farthing, que está en Rémol.', },
  },
  [355] = {
    'Habla con Sevren',
    {'Me has entregado los restos de los Agamand y con ello, has satisfecho mis deseos de venganza. Pero los Molinos de Agamand encierran una amenaza para todos los Renegados, no solo para mí.|n|nHe informado al magistrado Sevren acerca de tus hazañas contra los Agamand y desea hablar contigo.', },
    {'Habla con el magistrado Sevren de Rémol.', },
  },
  [356] = {
    'Patrulla de la retaguardia',
    {'En El Baluarte, debemos permanecer en alerta constante para proteger Tirisfal de las incursiones de la Plaga, pero, incluso a veces, consigue colarse.|n|nNuestro éxito en El Baluarte depende de una batalla de un solo frente. No podemos, pues, permitir un ataque desde la retaguardia ni dejar que corten la línea de abastecimiento de El Baluarte.|n|nPatrulla por el oeste y mata a todo miembro de la Plaga que encuentres. Céntrate sobre todo en la Hacienda Balnir, pues, parece que se ha convertido en el refugio de numerosos miembros de la Plaga.', },
    {'Mata a 8 horrores sangrantes y a 8 espíritus deambulantes.', },
  },
  [357] = {
    'La identidad del exánime',
    {'Hay un exánime que mora en la isla Lago Aguasclaras, en el norte. Aunque es un Renegado independiente, cree que los otros no-muertos son esclavos de la Plaga por lo que sus esbirros atacan a todo aquel que se acerca a él.|n|nPero, dado que es un Renegado, la Reina lo reclama. Y si tiene conocimientos de nigromancia, estos serán... muy útiles para nosotros.|n|nPara descubrir su identidad y talentos, debo ver su libro de hechizos. Irrumpe en su campamento, róbalo y tráemelo aquí.', },
    {'Llévale el libro de hechizos del exánime a Bethor Duroyelo en Entrañas.', },
  },
  [358] = {
    'Profanadores',
    {'Las fosas comunes, al suroeste de la Granja de Garren situada hacia el norte de aquí, se hicieron para albergar la impresionante cantidad de cadáveres de aquellos que perecieron en Tirisfal cuando la Peste golpeó por primera vez.|n|nDe estas tumbas no había salido ni un solo no-muerto hasta el momento, pero ahora la Plaga envía a gnolls Putrepellejo a recoger cadáveres para que engrosen las filas de sus ejércitos. ¡Esto es inaceptable!|n|nTienes una doble tarea que cumplir: mata a los Putrepellejo de las fosas comunes y la Granja de Garren, y quítales el icor embalsamante que les da vida.', },
    {'Mata a los asaltatumbas Putrepellejo y a los bastardos Putrepellejo. |n|nLlévale 8 icores embalsamantes al magistrado Sevren de Rémol.', },
  },
  [359] = {
    'Las obligaciones de los Renegados',
    {'Necesito conocer las últimas noticias de nuestro puesto del Guardia de la Muerte situado al este de aquí.|n|nTengo que saber si las fuerzas de la Plaga han pasado por El Baluarte y han entrado en Tirisfal. Debemos mantener la vigilancia en la frontera con las Tierras de la Peste pues no podemos permitir que la Plaga afiance su presencia aquí.|n|nViaja hacia el sur siguiendo el camino y cuando este se bifurque, continúa en dirección este hasta el puesto. Habla con la Guardia de la Muerte Linnea. Ella tiene la información que necesito.', },
    {'Habla con la guardia de la muerte Linnea.', },
  },
  [360] = {
    'Regresa junto al magistrado',
    {'Ahora llévale la información que te he dado al magistrado Sevren. Le gustará recibirla lo antes posible así que date prisa.|n|nY si ves a algún miembro de la Plaga por el camino, acaba con él. No podemos permitir que vaguen por nuestras tierras a su antojo.', },
    {'Ve a ver de nuevo al magistrado Sevren de Rémol.', },
  },
  [361] = {
    'Una carta sin entregar',
    {'Esta carta la escribió Thurman, el hijo mayor de Gregor Agamand. Está dirigida a una tal Yvette Farthing, aunque parece que nunca llegó a recibirla...', },
    {'Encuentra a Yvette Farthing y entrégale la carta de Thurman Agamand.', },
  },
  [362] = {
    'Los molinos fantasma',
    {'Devlin Agamand era el más joven de los dos hijos de la familia Agamand y en vida ambos no podían ser más diferentes. Thurman era alto y amable mientras que su hermano pequeño era débil y tenía la lengua muy afilada.|n|nCuando la Peste llegó a los Molinos de Agamand, no me sorprendió de que Devlin sucumbiera casi de inmediato. Sus desbarres todavía pueden oírse cerca del camino que conduce a los Molinos de Agamand.|n|nEstoy recogiendo lo que queda de los Agamand y quiero al pobre Devlin. Encuéntralo, acaba con él y tráeme sus huesos.', },
    {'Acaba con Devlin Agamand y llévale los restos de Devlin a Coleman Farthing en Rémol.', },
  },
  [363] = {
    'Desvelo brutal',
    nil,
    {'Habla con el sacerdote de las Sombras Sarvis.', },
  },
  [364] = {
    'Los autómatas',
    {'Desde que los primeros Renegados se arrastraron fuera de sus tumbas, hemos estado en guerra con el ejército de la Plaga del Rey Exánime: ejércitos de no-muertos reanimados mediante nigromancia, asquerosas bestias del norte, y espectros atormentados.|n|nEl Rey Exánime ya no ocupa el Trono Helado, pero la parte norte del poblado sigue estando invadida por sus esclavos. Destrúyelos, no muestres piedad, aunque sean nuestros antiguos hermanos y hermanas.', },
    {'Mata a 5 zombis descerebrados y a 5 necrófagos desdichados.', },
  },
  [365] = {
    'Campos de pena',
    {'¿Qué tenemos aquí? Pareces un poco $Gnovato:novata;, $C. Si quieres demostrar tu valía a la Dama Oscura, tendrás que aprender los caminos de los Renegados.|n|nEncontrarás una plantación en dirección oeste. Los humanos infestan la tierra al igual que el moho un cuerpo en descomposición. Y lo que es peor, la Cruzada Escarlata vigila la zona desde su torre. Dales una lección a esos canallas y roba 10 de sus preciadas calabazas.|n|nCuando tengas 10, llévaselas al boticario Johaan a Rémol.', },
    {'Roba 10 calabazas de la plantación que encontrarás en dirección oeste, justo al norte de Camposanto, y llévaselas al boticario Johaan a Rémol.', },
  },
  [366] = {
    'Devuelve el libro',
    {'Hace tiempo, Gunther y yo, junto con el ahora nigromántico de la Plaga Thule Corvozarpa, fuimos amigos y estudiamos juntos en el Kirin Tor (una sociedad de magos de Dalaran).|n|nTanto Gunther como yo sucumbimos a la Peste pero creí que él estaría muerto o sirviendo al Rey Exánime. ¡Es estupendo saber que está libre!|n|nTenemos que conseguir que se una a nosotros. He lanzado un hechizo sobre su libro de forma que, cuando lo vea, sepa que yo también estoy libre del Rey Exánime. Cuando se entere de esto, espero que se una a nosotros.', },
    {'Devuélvele el libro de hechizos de Gunther a su dueño, que se encuentra en la isla del Refugio de Gunther.', },
  },
  [367] = {
    'Una nueva Peste',
    {'Lady Sylvanas ha recurrido a la Sociedad Real de Boticarios. La Dama Oscura cree que nuestro conocimiento, unido a la recién descubierta magia, proporcionará la clave para derrotar a Arthas. Nos ha instado a idear una nueva peste, una peste mucho más mortífera que cualquier otra dolencia conocida en Azeroth. Esta nueva enfermedad llevará a la ruina al ejército de la Plaga de Arthas.|n|nMis estudios revelan que la clave podría estar en la sangre de las bestias. Tráeme 5 viales de sangre de can oscuro para que pueda comprobar mi teoría.', },
    {'El boticario Johaan de Rémol quiere que recojas 5 viales de sangre de can oscuro.', },
  },
  [368] = {
    'Una nueva Peste',
    {'Mientras recogías las muestras, me he dado cuenta gracias a mis experimentos de que serán necesarios más componentes para que esta nueva enfermedad se propague como es debido. Envenenar a unas cuantas víctimas es un juego de niños pero extender una plaga por todo un mundo es algo más complicado.|n|nNecesitaré 5 escamas de Anca Vil de los múrlocs de la zona. Encontrarás a estas criaturas en la costa hacia el norte o el oeste.', },
    {'El boticario Johaan de Rémol necesita 5 escamas de Anca Vil de los múrlocs de los Claros de Tirisfal.', },
  },
  [369] = {
    'Una nueva Peste',
    {'Mientras recogías lo que te pedí, descubrí un viejo texto en uno de mis tomos que explica cómo una antigua peste arrasó con miles de víctimas inocentes. Más tarde se descubrió que el agente mortal de dicha peste estaba presente en el veneno de las nocturácnidas.|n|nTráeme un poco de veneno de una nocturácnida sañosa para completar este experimento. Quiero comprobar si el elemento contagioso presente en el veneno servirá para mi nuevo brebaje. Se dice que hay muchas arañas en los Claros de Tirisfal del Este.', },
    {'El boticario Johaan de Rémol quiere que le lleves 4 muestras de veneno de nocturácnida sañosa.', },
  },
  [370] = {
    'En guerra con la Cruzada Escarlata',
    {'Los documentos del ejecutor Arren contienen exactamente todos los detalles que necesitamos para erradicar la infestación humana de nuestras tierras. De acuerdo con esta información, la Cruzada Escarlata ha enviado al capitán Perrine y a una brigada a las ruinas de la torre situada al suroeste de Rémol.|n|nMata a Perrine, a 3 zelotes y a 3 misioneros y regresa aquí.', },
    {'El ejecutor Zygand de Rémol quiere que mates al capitán Perrine, a 3 zelotes Escarlata y a 3 misioneros Escarlata.', },
  },
  [371] = {
    'En guerra con la Cruzada Escarlata',
    {'Seguimos en guerra y la Cruzada Escarlata se hace cada vez más fuerte. El informe que el ejecutor Arren me ha enviado indica que la Cruzada Escarlata ha estado atacando desde las ruinas de la torre situada al sudeste de Tirisfal, cerca de la Hacienda Balnir, bajo las órdenes del capitán Vachon.|n|nMata a Vachon y a 5 frailes Escarlata. ¡Será un duro golpe para la Cruzada!', },
    {'El ejecutor Zygand de Rémol te ha encargado que mates al capitán Vachon y a 5 frailes Escarlata.', },
  },
  [372] = {
    'En guerra con la Cruzada Escarlata',
    {'La Cruzada Escarlata ha estado atacando desde las ruinas de la torre situada al norte de Tirisfal, más allá de la Tumba de Faol. De acuerdo con los datos que tenemos, están bajo las órdenes del implacable capitán Melrache.|n|nTe voy a confiar una misión tan poco habitual como peligrosa. Mata a Melrache y a sus dos guardaespaldas en nombre de la Dama Oscura.', },
    {'El ejecutor Zygand de Rémol quiere que asesines al capitán Melrache y a sus dos guardaespaldas.', },
  },
  [373] = {
    'La carta sin enviar',
    {'Registrando a Edwin VanCleef descubres, entre otras cosas, una carta sin enviar. Va dirigida a Baros Alexston, el arquitecto jefe de Ventormenta, Ayuntamiento, Plaza de la Catedral.|n|nParece ser que ha sido escrita y sellada recientemente.', },
    {'Entrega la carta destinada al arquitecto jefe a Baros Alexston en Ventormenta.', },
  },
  [374] = {
    'Prueba de defunción',
    {'El ejecutor Zygand me dice que has estado matando a miembros de la Cruzada Escarlata. Los Claros de Tirisfal están plagados de ellos.|n|nVarimathras, teniente de la Dama Oscura, se está encargando personalmente de exterminar a la escoria de Azeroth: la raza de los humanos. Aquí en los Claros de Tirisfal nos enfrentamos a un nuevo género de humanos: la Cruzada Escarlata.|n|nCorre el riesgo y lanza una ofensiva contra la Cruzada Escarlata, $C. Tráeme 10 anillos con la insignia Escarlata como muestra de tu lealtad a Varimathras y a la Dama Oscura.', },
    {'Llévale 10 anillos con la insignia escarlata al Guardia de la Muerte Burgess de Rémol.', },
  },
  [375] = {
    'El frío de la muerte',
    {'Tengo tanto frío... La Peste de los no-muertos corre por mis venas como una serpiente de hielo. Pronto me embargará el estado de automatismo pero nada me impedirá que sirva a nuestra Dama Oscura. En su momento yo misma cosí bolsas de cadáveres para los soldados caídos del poderoso ejército de Sylvanas.|n|nPero ahora mis manos tiemblan de frío. Si me trajeras 5 pelambres de Murciumbrío y un hilo burdo, podría coser yo mismo una manta. Ayúdame, $N, para que así pueda seguir sirviendo a la causa.', },
    {'Llévale 5 pelambres de Murciumbrío y un hilo burdo a Gretchen Dedmar, que está en Rémol.', },
  },
  [376] = {
    'Los Malditos',
    {'Mis deberes son atender a nuestros guerreros heridos, suministrar ropa y armaduras y asistir al sacerdote de las Sombras Sarvis en lo que necesite.|n|nParece que tú también vas a acabar a su servicio... dando caza a los autómatas. Seguro, sé cómo piensa. Si quieres seguir de una pieza, que seguro que sí, quizás pueda ayudarte. Me estoy quedando sin patas y alas. Si me traes algunas, te buscaré una armadura. Encontrarás muchos lobos y murciélagos hacia el sur.', },
    {'Consigue 4 garras de carroñero y 4 alas de Murciumbrío.', },
  },
  [377] = {
    'Crimen y castigo',
    {'Como si no tuviéramos suficiente con la negligencia de los residentes del Bosque del Ocaso, ahora la Casa de Nobles escupe en el ojo al Consejo de Villa Oscura con su decisión de encarcelar a Dextren Ward en Ventormenta en lugar de decapitarlo como establecía la sentencia de Lord Cerranegro.|n|nTutor fue descubierto vendiendo cadáveres del cementerio a Morbent Vil, y ese es un delito que se castiga con la muerte. Y sin embargo, Ventormenta lo reclama como prisionero.|n|nAsesina a Ward en las Mazmorras de Ventormenta. Tráeme su mano y yo te recompensaré.', },
    {'El consejero Tallolino de Villa Oscura quiere que le lleves la mano de Dextren Ward.', },
  },
  [378] = {
    'La furia mora en las profundidades',
    {'Has demostrado tu lealtad al rey Magni, $C. Y tu odio por la escoria Hierro Negro es tan grande como el mío.|n|nHay una tarea que me gustaría hacer por mí mismo, pero el honor me obliga a permanecer junto a Largatrenza. Roggo ha conseguido reunir datos que demuestran que Kam Furiahonda fue miembro de la conspiración para el ataque del Puente Thandol. Fueron los planes de Furiahonda los que hicieron perder a Largatrenza a toda su familia.|n|nFuriahonda está retenido, por razones políticas, en las Mazmorras de Ventormenta. Le quiero muerto, $N. ¡Por Largatrenza! ¡Tráeme su cabeza!', },
    {'Motley Garmason quiere que le lleves la cabeza de Kam Furiahonda a Dun Modr.', },
  },
  [379] = {
    'Aplacar esa sed',
    {'Si quieres una fuente de calor, yo puedo ayudarte a conseguirla. ¿Y sabes qué quiero yo? ¡Algo de beber! Tráeme cinco faltriqueras de agua de Vagayermos y yo te daré la 4711-FTZ.|n|nYa solo te falta saber dónde puedes encontrar faltriqueras de agua de Vagayermos. ¿Por qué no te diriges al este en busca de nómadas Vagayermos y les pides una? Ya me contarás cómo resulta.', },
    {'Llévale 5 faltriqueras de agua de Vagayermos al ingeniero jefe Pasaquillas, en Gadgetzan.', },
  },
  [380] = {
    'Hoya Nocturácnidas',
    {'Obtener los recursos naturales que necesitamos para sobrevivir es una de nuestras luchas más arduas. El oro escaseaba incluso en los tiempos en los que el poder de la Alianza estaba en su cumbre.|n|nHay una mina de oro al noroeste que ha sido invadida por arañas. Necesitamos el oro de esa mina, pero no podemos extraerlo mientras las arañas estén por ahí. No tengo mucho personal para la tarea, así que tendremos que encargarnos de ellas poco a poco.|n|nSube allí y a ver si puedes hacer algo por nosotros, $N.', },
    {'El ejecutor Arren quiere que mates a 8 nocturácnidas jóvenes y a 5 nocturácnidas.', },
  },
  [381] = {
    'La Cruzada Escarlata',
    {'Te alegrará saber que estamos haciendo algunos progresos en la mina, gracias, en gran parte, a tus esfuerzos. Ahora podemos centrarnos en otros problemas.|n|nMis exploradores me han comunicado que un destacamento de la Cruzada Escarlata está estableciendo un campamento al sureste de aquí. La Cruzada Escarlata es una despreciable organización que nos da caza. No descansarán hasta que hayan acabado con todos los no-muertos, sean de la Plaga del Rey Exánime o no. ¡Debemos atacar primero!|n|nTen cuidado, su impuro celo los convierte en adversarios muy peligrosos.', },
    {'Lleva al ejecutor Arren 12 bandas Escarlata de conversos Escarlata y de iniciados Escarlata.', },
  },
  [382] = {
    'El mensajero rojo',
    {'Los informes que me envían mis superiores desde Rémol indican que un agente de la Cruzada Escarlata fue enviado desde el Monasterio Escarlata hasta el Camposanto. Sabemos que ese mensajero transporta una información muy importante. No tengo más detalles pero, lleve lo que lleve, ¡debemos conseguirlo!|n|nEres la persona más cualificada a la que puedo enviar, $N. Encuentra a ese mensajero y tráeme cualquier información que encuentres.', },
    {'Mata a Meven Korgal, el mensajero, en el campamento de los Cruzados y vuelve a comunicar al ejecutor Arren cualquier información que encuentres.', },
  },
  [383] = {
    'Información decisiva',
    {'Hay que hacer llegar esto a mi superior, el ejecutor Zygand, en Rémol. Con esta información podremos asestar un golpe definitivo a la Cruzada Escarlata. Has sido muy útil en Camposanto, pero necesito que alguien lleve esto a Zygand y además, creo que él podrá asignarte tareas más adecuadas.|n|nCuando salgas de Camposanto, sigue la carretera del norte. Poco después de entrar en Tirisfal, encontrarás un cruce. Toma el sendero del este y sigue en esa dirección. En tu camino pasarás por la Mansión Fríogar.', },
    {'Ve a Rémol y entrega los documentos de la Cruzada Escarlata al ejecutor Zygand.', },
  },
  [384] = {
    'Costillas de jabalí a la cerveza',
    {'¡Nada les gusta más a mis clientes que unas ricas costillas de jabalí a la cerveza! El problema es que el trampero local que solía traerme los suministros, se ha alistado en el ejército del Rey para ayudar en el frente de la Alianza.|n|nQuizás puedas ayudarme tú... Si me traes seis costillas de jabalí montés y algo de malta rapsódica de la taberna, compartiré contigo una receta familiar: mis famosas costillas de jabalí a la cerveza. ¡Y te daré una muestra gratis! ¡El secreto está en la malta!', },
    {'Ragnar Cebatruenos de Kharanos quiere 4 costillas de jabalí tiernas y una jarra de malta rapsódica.', },
  },
  [385] = {
    'La caza de crocoliscos',
    {'Vienen muchos cazadores a Loch Modan por los crocoliscos. Los mercaderes compran pieles de crocolisco para hacer ropa y armaduras, e incluso hay a quien le gusta su carne.|n|nHacemos negocio, pero no mucho, porque esos bichos son muy feroces y se esconden en las islas del lago. Pero tú no te prives, enfrentarse a esos dientes es toda una experiencia.|n|nMe acuerdo de una vez que...', },
    {'Lleva 5 piezas de carne de crocolisco y 6 pieles de crocolisco a Marek Coracero, en la Cabaña del Errante.', },
  },
  [386] = {
    'Lo que sucede alrededor...',
    {'Targorr el Pavoroso sirvió bajo las órdenes de Gath\'llzogg como Verdugo supremo. Sus métodos eran los más despiadados, incluso para los orcos. No dudó en torturar a hombres que habían servido lealmente en la defensa del Reino. Ahora se encuentra recluso en las Mazmorras de Ventormenta, a la espera de que se cumpla su sentencia de muerte. Aun así, hay algo que no encaja. Uno de los nobles burócratas ha detenido su ejecución. Seguro que se trata de una maniobra oscura.|n|nTienes que acabar con Targorr el Pavoroso, $N. Viaja a Las Mazmorras y decapítalo antes de que logre escapar a su destino.', },
    {'Lleva la cabeza de Targorr el Pavoroso al guardia Berton a Villa del Lago.', },
  },
  [387] = {
    'Detener el motín',
    {'¡Hay que detener el motín! Necesito tu ayuda. ¡Si alguien se entera de que la prisión es un caos perderé mi trabajo! Esto es juego sucio. Pero lo importante es obligar a los prisioneros a rendirse, por la seguridad de Ventormenta.|n|nEl castigo por sublevación es la muerte. Mata a alguno de esos desviados. Y verás cómo vuelven al buen camino...', },
    {'El celador Thelagua de Ventormenta quiere que mates 10 prisioneros, 8 presidiarios, y 8 insurgentes en Las Mazmorras.', },
  },
  [388] = {
    'El color de la sangre',
    {'El resentimiento corre por mis venas como una corriente fría. Mi nieto, Mac, era un chico muy bueno. 14 años recién cumplidos. Cuando el ejército fue mandado al frente, Mac cogió las armas para defender la ciudad. Fue un guardia de Las Mazmorras, donde está encerrada la banda Defias. Mac reprendió a algunos de los prisioneros por romper sus mantas de lana para hacer bufandas, un símbolo de la banda. Por hacerlo, recibió una puñalada en la espalda.|n|nQuiero venganza. Tráeme 10 de sus valiosos pañuelos de lana. Son del color de la sangre.', },
    {'Nikova Raskol, de Ventormenta, quiere que consigas 10 pañuelos de lana roja.', },
  },
  [389] = {
    nil,
    {'VanCleef y yo fuimos miembros de la Hermandad de los Albañiles. Nuestro primer proyecto después de la Guerra era reconstruir Ventormenta.|n|nCuando terminamos, nos estafaron. Los nobles se negaron a pagarnos. A algunos de los Albañiles mayores les ofrecieron trabajos gubernamentales, pero VanCleef y yo los rechazamos debido a nuestra lealtad con los Albañiles. Él lideró un motín y abandonó la ciudad, jurando venganza.|n|nEs posible que su teniente, Bazil Thredd, sepa más sobre los planes de VanCleef. Está prisionero en las Mazmorras.', },
    {'Habla con el celador Thelagua en las Mazmorras.', },
  },
  [391] = {
    'El motín de Las Mazmorras',
    {'Dejemos esto claro, $N. No confío en ti. Pero en estas circunstancias, tendré que pasarlo por alto.|n|nEsto es lo que vamos a hacer: baja ahí y habla con Thredd. Si realmente estás de nuestra parte, mátale y tráeme su cabeza como prueba. Si descubrimos que estás de su parte, cuando te encontremos... morirás junto con el resto de esos gusanos.', },
    {'Mata a Bazil Thredd y lleva su cabeza al celador Thelagua en las Mazmorras.', },
  },
  [392] = {
    'Extraño visitante',
    {'Durante los primeros años del encarcelamiento de Thredd, nunca recibió visitas. Supuse que ya no resultaba útil para la Hermandad y que le habían abandonado.|n|nEn fin, hace unos meses, todo cambió. Comenzó a recibir visitas regularmente... una, o quizás dos veces por semana. Era un hombre extraño... un tipo tranquilo. Tenía sospechas, pero sus papeles estaban en regla.|n|nEn los documentos venía que su nombre era Maelik; esta es su descripción. No creo que venga a visitar más a Thredd.', },
    {'Lleva la descripción del visitante de Thredd lacrada a Baros Alexston en Ventormenta.', },
  },
  [393] = {
    'Sombras del pasado',
    {'No tengo ni idea, $N. Hay alguien más que quizás pueda ayudarte y resulta que me debe un favor por... bueno, no hace falta entrar en detalles. En los cuarteles del Casco Antiguo, puedes encontrar al maestro Mathias Shaw del IV:7. Shaw está metido en la mayor parte de los negocios sucios o turbios de la ciudad.|n|nSi alguien puede saberlo, es él.', },
    {'Lleva la descripción del visitante de Thredd lacrada al maestro Mathias Shaw en Ventormenta.', },
  },
  [394] = {
    'La cabeza de la bestia',
    {'Encuentra a Shaw en el Casco Antiguo. Dile que nos hemos encargado de la amenaza de Lescovar y cuéntale lo de tu participación en los planes del señor contra la ciudad. Seguro que se sentirá orgulloso de tener a otro héroe entre los ciudadanos de Ventormenta.|n|nLo más probable es que te envíe a ver al príncipe o a otro noble. Pero que no se te suba a la cabeza, $N. Los nobles pueden creer que gobiernan la ciudad, pero hay algunas cosas que se les escapan de las manos.', },
    {'Habla con Mathias Shaw en Ventormenta.', },
  },
  [395] = {
    'El fin de la Hermandad',
    {'¡Ah, casi lo olvidaba! Alexston vino cuando no estabas, quería hablar contigo. Sin duda quiere informar a los nobles de los tejemanejes de la Hermandad Defias.|n|nUn pequeño consejo, $N: si alguien te pregunta, da todos los detalles, menos que fue tu mano la que mató a Lescovar. Confía en mí. Sé cómo van esas cosas...|n|nY, con respecto a Trias, bueno, si puedes evitarlo, nunca jamás hables de él con nadie.', },
    {'Habla con Baros Alexston en Ventormenta.', },
  },
  [396] = {
    'Una audiencia con el Rey',
    {'He preparado un informe para el rey. Creo que tú deberías entregárselo, junto con un resumen de tus descubrimientos. No te preocupes, sin duda te elogiará por hacer tu deber con el pueblo de Ventormenta.|n|nTu audiencia comenzará pronto, así que será mejor que te des prisa, todavía te queda un buen tramo hasta el Castillo de Ventormenta.', },
    {'Lleva el informe de Baros Alexston sobre la Hermandad Defias al rey Varian Wrynn en el Castillo de Ventormenta.', },
  },
  [397] = {
    'Nos has hecho un gran servicio',
    {'He oído que a Lord Wishock le gustó mucho la bebida.|n|nNos has hecho un gran servicio, $N. Los brujos de Ventormenta podremos seguir trabajando sin más interrupciones gracias a ti. Por tus esfuerzos, te he preparado un regalo especial. Habla con mi sirviente, Zggi, y pídele tu recompensa.', },
    {'Habla con Zggi, el sirviente de Zardeth de los Zarpanegra, para pedir tu recompensa.', },
  },
  [398] = {
    'Se busca: Ojo de cresa',
    {'Se busca: ¡Ojo de cresa!|n|nConsiderado una bestia incluso entre los propios gnolls, Ojo de cresa ha sido sentenciado a muerte por sus crímenes en contra de los Renegados. Este infame villano ha estado robando cuerpos y poniéndolos a disposición del ejército del Rey Exánime. Ojo de cresa fue visto por última vez saqueando las tierras situadas en las proximidades de la Granja de Garren, al norte de Rémol.|n|nA partir de este momento, la ciudad de Rémol ofrece una recompensa al que sea capaz de llevar a cabo su ejecución. Muéstrale al ejecutor Zygand la garra del villano una vez ejecutada la sentencia.|n|nLa clemencia queda relegada a los débiles.', },
    {'Mata a Ojo de cresa y llévale su garra al ejecutor Zygand de Rémol para obtener una recompensa.', },
  },
  [399] = {
    'Principios humildes',
    {'Parece que hace una eternidad desde que tan solo era un chico trabajando en la granja de los Páramos de Poniente. Dicen que nunca puedes regresar, y es cierto. Doblemente cierto en mi caso, unos pasajeros quemaron y tomaron mi casa.|n|nHe hablado con mi padre para descubrir el destino de alguna de mis posesiones, incluyendo mi primera brújula. No fue capaz de salvarlas. Sin embargo, también dice que deberían estar escondidas en la granja.|n|nEncontrarás la Hacienda de Alexston al oeste de la Colina del Centinela. ¿Quizás podrías ir y recuperarla?', },
    {'Ve a la casa de Baros Alexston en los Páramos de Poniente y busca su brújula. A continuación, llévasela al Distrito de la Catedral, en Ventormenta.', },
  },
  [400] = {
    'Herramientas para Brasacerada',
    {'Beldin Brasacerada es el dueño de la tienda de mecánica local y además es el mejor técnico de máquinas de asedio. Pero es implacable con sus herramientas. ¡Te aseguro que rompe más llaves de tuerca arcoluz de las que le podemos suministrar!|n|nAcabamos de completar su último pedido. Si se lo llevas, seguro que te compensa el esfuerzo.|n|nSu tienda, el Almacén de Brasacerada, está al noreste de Kharanos. Y es un lugar en el que se reúnen los pilotos veteranos de máquinas de asedio, así que estate $Gatento:atenta; por si oyes algo interesante.', },
    {'Entrega las herramientas de Brasacerada a Beldin Brasacerada.', },
  },
  [401] = {
    'Espera a que Sirra acabe',
    {'Casi he acabado de traducir esa nota. Vuelve en un rato, probablemente habré acabado.', },
    {'Espera un momento y luego vuelve a hablar con Sirra Von\'Indi.', },
  },
  [402] = {
    'Sirra está ocupada',
    {'Lo siento pero, tal y como están las cosas, tengo otros asuntos que atender. Intentaré acabar la traducción más tarde... Si sobrevivimos.', },
    {'Vuelve más tarde a ver si Sirra sigue aún ocupado.', },
  },
  [403] = {
    'El barril de Cebatruenos custodiado',
    nil,
    nil,
  },
  [404] = {
    'Una tarea pútrida',
    {'La Plaga ha alcanzado los Claros de Tirisfal y ha infestado el área al oeste de Rémol, cerca del puente viejo.|n|nDirígete allí y enfréntate a los muertos podridos. Trae sus garras podridas y los Guardias de la Muerte te recompensarán.', },
    {'Llévale 7 garras podridas al Guardia de la Muerte Dillinger de Rémol.', },
  },
  [405] = {
    'El exánime pródigo',
    {'Bethor Duroyelo, un poderoso mago de alto rango de Entrañas, que cae al sur, me ha pedido que le envíe a alguien capaz de hacer frente a la Plaga. Tú, $N, eres $Gel elegido:la elegida;.|n|nHázselo saber a Bethor y él te explicará cuál es tu misión. Yo desconozco los detalles pero sé que tiene algo que ver con reclutar a un exánime, y parece peligroso.|n|nPrepárate, $C, pues no debes fallar.|n|nBusca a Bethor en el Barrio de la Magia de Entrañas.', },
    {'Comunícale las órdenes de Sevren a Bethor Duroyelo en Entrañas.', },
  },
  [407] = {
    'Campos de pena',
    {'¿Simples e inofensivas calabazas, verdad? Eso es lo que deben parecer... Si queremos detener el avance de Arthas por el norte y la infestación humana por el sur, tenemos que comenzar a valorar nuestro propio potencial.|n|nCon un poco de ingenio, una simple calabaza se convierte en un arma de nuestra Dama Oscura. Solo hay que echarle un poco de mi última fórmula.|n|nHan capturado a otro zelote Escarlata y está encerrado en el sótano del Mesón La Horca. Llévale a ese desgraciado esta calabaza.', },
    {'Llévale la calabaza envenenada al zelote Escarlata capturado que está encerrado en el sótano del Mesón La Horca.', },
  },
  [408] = {
    'La Cripta de la Familia',
    {'Los miembros de la Plaga han encontrado cobijo en los Molinos de Agamand. El punto más sólido es la Cripta de la Familia Agamand, lugar en el que su líder militar, un esqueleto llamado capitán Dargol, ha establecido su puesto de mando. Por medio de la nigromancia, ha revivido a los ancestros de los Agamand y planea utilizarlos contra nosotros.|n|nEsto no puede ocurrir y tú has de evitarlo. Viaja a la Cripta de la Familia Agamand y derrota a los ancestros de los Agamand.|n|n¡Ah! Y tráeme la calavera del capitán Dargol.', },
    {'Mata a 8 ancestros gemebundos y a 8 ancestros en podredumbre.|n|nMata al capitán Dargol y llévale su calavera al magistrado Sevren de Rémol.', },
  },
  [409] = {
    'Prueba de lealtad',
    {'Afirmas que no estás $Gsometido:sometida; a la voluntad del Rey Exánime y el encantamiento que Bethor lanzó sobre mi libro lo corrobora. Sin embargo, para que pueda confiar en ti debes darme una prueba de que estás en contra de la Plaga.|n|nHay un viejo altar, a poca distancia de la costa sur de esta isla, que utiliza un poderoso agente de la Plaga llamado Lillith Nefara.|n|nCoge una vela de señalización de este cajón. Enciéndela en el altar y Lillith se despertará. Acaba con Lillith y creeré que en verdad eres $Gun enemigo:una enemiga; del Rey Exánime.', },
    {'Coge una vela de señalización.|n|nDespierta a Lillith Nefala y mátala.|n|nVuelve a ver a Gunther a su isla.', },
  },
  [410] = {
    'Sombra durmiente',
    nil,
    nil,
  },
  [411] = {
    'El regreso del exánime pródigo',
    {'Dale esta gema abisal a mi viejo camarada Bethor. A través de ella podremos comunicarnos... y en verdad tengo mucho que contarle.', },
    {'Llévale la gema abisal a Bethor Duroyelo en Entrañas.', },
  },
  [412] = {
    'Operación Recombobulación',
    {'Debería regresar a Gnomeregan y seguir buscando una cura para los gnomos irradiados.|n|nSin embargo, me he quedado en Kharanos porque es mi hogar y quería ayudar a defenderlo de los ataques de los Peloescarcha. He estado trabajando en el mantenimiento y la reparación de los tanques de vapor.|n|nPor alguna razón, los carroñeros Peloescarcha se han aficionado a los engranajes giromecánicos que necesito para completar las reparaciones. Se encuentran esparcidos por todo el Frente de Peloescarcha, al sureste de la ciudad. ¿Me ayudas a conseguir traer los engranajes de vuelta?', },
    {'Lleva 8 engranajes giromecánicos a Razzle Engranágil.', },
  },
  [413] = {
    'Cerveza negra Brillante',
    {'Me gustaría que mi hermano Wellart probara mi nueva cerveza negra Brillante. Es un montaraz. Está destacado en la torre de vigilancia del sur, en la frontera del Loch Modan.|n|nNo se dedica a hacer cerveza, como los demás Cebadiz, pero le encanta beberla y sé que esta le gustará.|n|n¿Podrías llevarle este tonel de cerveza negra Brillante de mi parte?', },
    {'Lleva el tonel de cerveza negra Brillante al montaraz Cebadiz.', },
  },
  [414] = {
    'Cerveza negra para Kadrell',
    {'He estado bebiendo la cerveza negra Brillante esa que hizo mi hermano. ¡Está buenísima! Quiero que la pruebe un compañero mío. Se llama Kadrell y normalmente patrulla por el camino de Thelsamar en Loch Modan.|n|nPara llegar a Thelsamar, ve al sureste a través del túnel y gira al noreste cuando el camino se divida. Sigue en esa dirección y llegarás $Gderecho:derecha; a Thelsamar.|n|nDale este tonel de cerveza negra Brillante al montaraz Kadrell. ¡A ver qué le parece!', },
    {'Lleva el tonel de cerveza negra Brillante al montaraz Kadrell.', },
  },
  [415] = {
    'La nueva bebida de Rejold',
    {'Rejold Cebadiz de Las Birras ha estado preguntando por ti.|n|nQuiere hablar contigo sobre una nueva bebida que ha estado preparando... dijo algo de que quería que le ayudaras. Quizás quieras ir a Las Birras a ver qué necesita de ti.|n|nPodrías ganarte una cervecita...', },
    {'Habla con Rejold Cebadiz.', },
  },
  [416] = {
    'Mata ratas',
    {'Tenemos una infestación grave. Esas ratas de túnel kóbold asquerosas se han instalado en las laderas. ¡Están cavando madrigueras y ensuciándolo todo!|n|nQueremos erradicarlos. Si los cazas y me traes sus orejas, puedes quedarte con su botín.|n|nLa mayor concentración de ratas de túnel kóbold está en el interior y en los alrededores de la Mina de Fuenteplata, al este.', },
    {'Lleva 8 orejas de rata de túnel al montaraz Pico Tormenta a Thelsamar.', },
  },
  [417] = {
    'Vengar al piloto',
    {'Hildelve escribió en su diario que fue atacado por Sarnagarra, un gran oso zarpahelada. Ahuyentó a la bestia, pero no antes de que esta lo atacara salvajemente.|n|nA juzgar por el estado del cuerpo de Hildelve, Sarnagarra debió de regresar para matarlo.|n|nPero Hildelve tuvo tiempo de escribir un último deseo en su diario:|n|nSarnagarra debe pagar por esto.', },
    {'Mata a Sarnagarra.|n|nLleva su garra sarnosa y el diario de Hildelve al piloto Podomartillo en la Avanzada de la Puerta Sur.', },
  },
  [418] = {
    'Morcillas de Thelsamar',
    {'Aquí en Thelsamar siempre hay alguien que quiere comer, críos por todos lados, los obreros de la excavación y eso. Lo más conocido es la morcilla, ¿la has probado?|n|n¿No? Bueno, pues aquí hay que trabajar para comer, no creas que te libras porque seas $C.|n|nLo único que necesito es carne de oso, el resto está incluido en el preparado. ¡Tú trae eso y de cocinar me ocupo yo, Vidra!', },
    {'Lleva 8 trozos de carne de oso a Vidra Hogartufa, en Thelsamar.', },
  },
  [419] = {
    'El piloto perdido',
    {'Mi compañero y amigo, Mori Hildelve, que es piloto de máquinas de asedio, está perdido en los montes. Buscábamos un raro mineral necesario para fabricar un potente tipo de pólvora y durante nuestra búsqueda, subió con su máquina una empinada montaña ¡y la máquina se averió!|n|nAún convencido de que el mineral estaba en estas montañas, Hildelve me encargó que custodiara las máquinas mientras él continuaba a pie.|n|nPero ya han pasado días y por las noches oigo unos estremecedores aullidos al norte del Lago de Helm, al oeste del túnel. Mori es duro como una roca, pero estoy preocupado.|n|nTe lo ruego, $N. Encuéntralo.', },
    {'El piloto Podomartillo, en la Avanzada de la Puerta Sur, quiere que encuentres al piloto Hildelve.', },
  },
  [420] = {
    'Las observaciones de Senir',
    {'Los troggs del túnel son extremadamente hostiles y no dudan en atacar a los viajeros que lo cruzan. Pero tú pareces fuerte. No deberías tener problemas para pasar.|n|nMmm... indicaciones... Pues para hablar con Senir tienes que ir a Kharanos.|n|nÁbrete paso a través del túnel y cuando lo hayas cruzado, sigue el camino. Te llevará directamente a Kharanos.', },
    {'Lleva el informe de Grelin a Senir Barbablanca a Kharanos.', },
  },
  [421] = {
    'Demuestra tu valía',
    {'Lady Sylvanas ha encomendado a Varimathras la conquista de las tierras humanas y enanas del sur.|n|nPero ese necio, Arugal, charlatán de Dalaran y ahora bestia maldita del Castillo de Colmillo Oscuro, dejó que su imprudente magia causara estragos en el bastión estratégico del Bosque de Argénteos.|n|nNecesito a alguien muy diestro en combate para ayudar a arreglar el desastre de Arugal. Demuéstrame tu valía matando a 5 canosos Furia Lunar. Es fácil encontrar a esas bestias salvajes al final del camino, hacia la colina de abajo.', },
    {'Dalar Tejealba en El Sepulcro quiere que mates a 5 canosos Furia Lunar.', },
  },
  [422] = {
    'La locura de Arugal',
    {'No me puedo imaginar cómo Arugal consiguió que el Kirin Tor le aceptase.|n|nLo que importa ahora es descubrir exactamente, qué magia utilizó Arugal. Así podré volverla contra él y asegurar el Bosque de Argénteos para la Dama Oscura.|n|nAl principio, Arugal se estableció en la granja de trigo que está justo al norte del puente. Uno de los mortacechadores, informó sobre algunos libros de hechizos que había visto, pero no pudo hacerse con ellos. Consigue el hechizo llamado Remedio de Arugal que está en esos libros.', },
    {'Recupera el Remedio de Arugal para Dalar Tejealba, en El Sepulcro.', },
  },
  [423] = {
    'La locura de Arugal',
    {'Tras examinar el trabajo de Arugal, se han confirmado mis peores sospechas. Ese viejo chiflado no estaba cualificado ni para limpiar orinales en Dalaran, y mucho menos para representar al Kirin Tor en su momento más desesperado. ¡Imbéciles!|n|nArugal utilizó objetos encantados para reforzar su débil magia. Necesito examinar esos objetos. Continúa tu viaje y mata glotones Furia Lunar y almanegras Furia Lunar hasta que hayas reunido suficientes grilletes encantados para mi investigación. Puedes encontrar a estas repugnantes criaturas hacia el norte y el este.', },
    {'Lleva 6 grilletes de glotón y 3 grilletes de almanegra a Dalar Tejealba en El Sepulcro.', },
  },
  [424] = {
    'La locura de Arugal',
    {'Voy a tardar mucho más de lo que había pensado en descubrir los oscuros secretos que yacen tras los encantamientos que Arugal estaba usando.|n|nPero, mientras tanto, necesito que te encargues de un pequeño problema que nuestros acechadores negros han descubierto. Parece ser que Arugal permitió que su magia se extendiera hasta la Mina de Elem, en las colinas del sureste.|n|nLa mina resultó ser un lugar estratégico para el avance de Varimathras.|n|nQuiero que decapites al supervisor contaminado de la mina, Grimson el Pálido. Tras su muerte, la mina será nuestra.', },
    {'Mata a Grimson el Pálido y lleva su cabeza a Dalar Tejealba en El Sepulcro.', },
  },
  [425] = {
    'Ivar el Hediondo',
    {'Mi hermano Quinn y yo teníamos que explorar el Bosque de Argénteos e informar al sumo ejecutor Hadrec. Pero no llegamos muy lejos... Cuando atravesábamos una granja, fuimos atacados por el necrófago Ivar el Hediondo.|n|nConseguimos escapar de Ivar, pero hirió gravemente a Quinn. Ahora se está recuperando gracias a la poción que le diste, pero Ivar podría volver antes de que Quinn esté totalmente bien.|n|nMata a Ivar para que Quinn tenga tiempo para curarse. Generalmente, Ivar está en el establo de allí, esperando a que baje la guardia.', },
    {'Mata a Ivar el Hediondo y lleva la cabeza de Ivar a Rane Yorick en Los Dominios de Ivar.', },
  },
  [426] = {
    'La invasión de los molinos',
    {'Los miembros de la Plaga están intentando establecer una base en los Molinos de Agamand. Si lo consiguen, podrán lanzar más ataques sobre Tirisfal.|n|nLas órdenes son claras: hay que detener a la Plaga en los Molinos.|n|nVe a los Molinos. Recoge costillas con cortes de los soldados armadóseos y los soldados testapartida, y calaveras ennegrecidas de los tirahuesos Ojosombra.|n|nPara llegar hasta los Molinos, sigue el camino en dirección oeste. Tras cruzar el puente, toma el siguiente desvío hacia el norte y continúa en esa dirección. Cuando veas los molinos de viento, dará comienzo la batalla.', },
    {'Recoge 5 costillas con cortes y 3 calaveras ennegrecidas, y después regresa ente el Guardia de la Muerte Dillinger de Rémol.', },
  },
  [427] = {
    'En guerra con la Cruzada Escarlata',
    {'Los documentos que el ejecutor Arren nos ha proporcionado son exactamente lo que necesitábamos para dar un giro a nuestra batalla contra la desdichada Cruzada Escarlata. Ahora sabemos sus ubicaciones exactas en Claros de Tirisfal.|n|nPero la Guardia de la Muerte tiene otras preocupaciones mayores. El ejército del Rey Exánime es más numeroso cada día que pasa. Necesitamos a alguien con un poco de "iniciativa" como tú para que envíe a la Cruzada Escarlata a la tumba.|n|nDemuéstrame que eres capaz de servir a la Dama Oscura; para ello, viaja al oeste hasta la torre que encontrarás pasada la Hacienda Solliden y mata a 10 guerreros Escarlata.', },
    {'El ejecutor Zygand de Rémol quiere que mates a 10 guerreros Escarlata.', },
  },
  [428] = {
    'Los Mortacechadores desaparecidos',
    {'Hace un par de semanas, dos de nuestros Mortacechadores, Rane y Quinn Yorick, fueron a una misión de reconocimiento por la parte norte de Argénteos. No hemos vuelto a tener noticias suyas.|n|nQuizás hayan caído en manos de la Plaga pero, si es así, necesito una confirmación. Encuentra a estos mortacechadores.|n|nSu primer objetivo era explorar las granjas al norte de Argénteos. Deberías comenzar por allí.', },
    {'Encuentra a los Mortacechadores Quinn y Rane Yorick.', },
  },
  [429] = {
    'Corazones salvajes',
    {'El necrófago, Ivar el Hediondo, hirió de gravedad a mi hermano Quinn y no sé si podrá curarse sin ayuda mágica. Si bien yo no soy un boticario, sé que nuestros boticarios pueden preparar pociones curativas a partir de corazones de huargos descoloridos.|n|nConsigue esos corazones y llévaselos al boticario Renferrel en El Sepulcro, al sur. Después, vuelve aquí con la poción.|n|nEncontrarás muchos huargos entre aquí y la Huerta de Malden, al este.', },
    {'Consigue 6 corazones de huargo descoloridos y llévaselos al boticario Renferrel en El Sepulcro.', },
  },
  [430] = {
    'Regresa junto a Quinn',
    {'Aquí está la poción para curar a Quinn Yorick.|n|nAhora, si me perdonas, tengo algo muy importante que hacer...', },
    {'Lleva la poción de Quinn a Quinn Yorick en Los Dominios de Ivar, al norte de El Sepulcro.', },
  },
  [431] = {
    'Velas de señalización',
    nil,
    nil,
  },
  [432] = {
    '¡Malditos troggs!',
    {'¡Esos malditos troggs están destrozando mi excavación! ¡Mira! ¡Ahí va otro barril de polvo!|n|n¡Ay! ¡Cómo me gustaría bajar ahí y retorcerles a todos ese pescuezo huesudo que tienen! ¡Quiero matarlos a todos!|n|nEsto no puede ser bueno para la salud. Tanta ira, tanto estrés... ¿Qué puedo hacer sin perjudicarme la salud? ¡Nada!|n|nLos mataría yo mismo, pero mi puntería no es la que era. ¡Entra tú en la cantera y mata a un puñadito de esos bichos asquerosos! Te pagaré... ¡Tú hazles daño! ¡Mátalos!', },
    {'Mata a 8 aplastacráneos Comepiedras y a 8 cascahuesos Comepiedras en la Cantera de Gol\'Bolar o en la mina.', },
  },
  [433] = {
    'El servidor público',
    {'Como miembro del Senado y de la Liga de Expedicionarios, he asumido la responsabilidad de investigar las condiciones de la cantera. ¡Los troggs se han vuelto locos!|n|nHan convertido en un caos la Cantera de Gol\'Bolar. Van saliendo a medida que profundizamos en nuestra excavación, y destruyen nuestro equipo y dejan atrapados bajo tierra a nuestros mineros.|n|nTenemos que sacarlos de ahí. Algunos magos han estado haciendo horas extra para encantar estas runas de retorno. Si consigues llevárselas a los mineros atrapados, podrán regresar a la superficie a salvo.', },
    {'Reparte 7 runas de retorno a los mineros atrapados en la Cantera de Gol\'Bolar.', },
  },
  [434] = {
    'El ataque',
    {'Cuando le ponga el disfraz al robot espía, irá a hablar con Lescovar. Los guardias le dejarán pasar sin problemas.|n|nMientras estabas reuniendo los materiales, me encargué de informar a Marzon de que tenía que reunirse de nuevo con Lescovar. Incluso le di información falsa.|n|nLescovar dirá a sus guardias que se retiren y esperará a Marzon aquí fuera, en el jardín. En cuanto empiecen a hablar de los Defias, te toca mover ficha. Tienes que matarlos antes de que vuelvan los guardias. Cuando hayas terminado, habla con Trias.', },
    {'Quédate en el jardín hasta que Lord Gregor Lescovar y Marzon el Filo Silencioso hayan terminado de hablar. A continuación, mátalos antes de volver a reunirte con Elling Trias en Ventormenta.', },
  },
  [435] = {
    'Escolta a Erland',
    {'Los lobos que están fuera no se mueven y me miran de forma malvada cada vez que salgo por esa puerta. Deben de estar increíblemente hambrientos si piensan que puede merecer la pena comerme.|n|nTengo que informar a mi compañero de equipo, el Mortacechador Rane Yorick. Y, para conseguir llegar donde está Rane, necesitaré ayuda con esos lobos.|n|n¡Por favor, escóltame! Hay un montón de lobos ahí fuera, así que tendríamos más oportunidades si tienes algún amigo que pueda ayudarnos...', },
    {'Escolta a Erland a través de los lobos, hasta llegar a Rane Yorick.', },
  },
  [436] = {
    'La excavación de Vetaferro',
    {'El prospector Vetaferro dirige la excavación de unas antiguas ruinas al este del lago. Últimamente está haciendo pocos progresos, a pesar de todos los suministros que le hemos enviado.|n|nVetaferro es un enano honrado y tenaz que valora los resultados. Por eso sospecho que hay otros factores en su contra.|n|nVe a la Excavación de Vetaferro y habla con Magmar Ceñimal. Él se encarga de los detalles de la excavación y sabrá a qué se debe el retraso en los trabajos.|n|nPara llegar a la excavación, rodea el extremo sur del lago y luego dirígete al este.', },
    {'Habla con el explorador Ceñimal.', },
  },
  [437] = {
    'El Campo Muerto',
    {'Los informes iniciales de nuestros exploradores en Argénteos, muestran que los Putrepellejo tienen una base en una vieja granja del norte, El Campo Muerto. Hemos lanzado pequeños asaltos contra ellos, pero cada vez que lo intentamos, el alma en pena Latipesadilla les ayuda, utilizando su magia para diezmar nuestras tropas.|n|nQueremos acabar con Latipesadilla.|n|nVete a El Campo Muerto y ataca a los Putrepellejo. Si no ves a Latipesadilla, mata a los Putrepellejo hasta que aparezca y, después, mátala a ella.|n|nSu esencia se convertirá en polvo. Tráeme ese polvo como prueba.', },
    {'Mata gnolls Putrepellejo en El Campo Muerto.|n|nCuando aparezca Latipesadilla, mátala.|n|nLleva la esencia de Latipesadilla al sumo ejecutor Hadrec en El Sepulcro.', },
  },
  [438] = {
    'El Viejo Embarcadero',
    {'$N, hemos descubierto una nueva infestación de la Plaga: El Viejo Embarcadero. El embarcadero está al este de El Sepulcro y está muy protegido por los Putrepellejo y otros no-muertos.|n|nDebe de haber una razón para la ocupación de la Plaga de esa zona. Vete a El Viejo Embarcadero y descubre por qué está allí la Plaga.', },
    {'Ve a El Viejo Embarcadero.|n|nEncuentra la razón por la que la Plaga está ahí.', },
  },
  [439] = {
    'Pistas de Putrepellejos',
    {'Entre los cadáveres sobresale una mano, abierta. Es la mano de una mujer, con marcas de la peste, pero relativamente fresca.|n|nEn la mano hay un anillo. Al sacar el anillo e inspeccionarlo revela una inscripción:|n|n"Para Deliah"', },
    {'Lleva el anillo de Deliah al sumo ejecutor Hadrec en El Sepulcro.', },
  },
  [440] = {
    'El anillo grabado',
    {'Si quieres encontrar al marido o bienamado de Deliah, quien le dio el anillo... habla con el magistrado Sevren en Rémol. Debería tener registros de los fallecimientos recientes y, con suerte, podrás descubrir quién es Deliah.|n|nPero yo no contendría el aliento. Quienquiera que le dio el anillo, está probablemente muerto. Y, si no está muerto, probablemente ya no le importa Deliah.', },
    {'Lleva el anillo de Deliah al magistrado Sevren en Rémol.', },
  },
  [441] = {
    'Raleigh y Entrañas',
    {'Deliah tenía un marido, Raleigh, que ahora vive en Entrañas. Si la Deliah que vivía en Rémol es la dueña de este anillo, Raleigh lo sabrá.|n|nRaleigh está en el Barrio del Comercio, en Entrañas.', },
    {'Lleva el anillo de Deliah a Raleigh.', },
  },
  [442] = {
    'Asalto a la Isla de Fenris',
    {'Ha llegado el momento de asaltar el punto fuerte de la Plaga en Argénteos: la Isla de Fenris.|n|nDebes volver a la isla y acabar con a Thule Corvozarpa. ¡Quiero su cabeza!|n|nEsta misión es tan peligrosa como vital, $N. No puedes fallar.', },
    {'Lleva la cabeza de Thule al sumo ejecutor Hadrec en El Sepulcro.', },
  },
  [443] = {
    'Icor de Putrepellejo',
    {'Antes de lanzar un asalto en la Isla de Fenris, debemos determinar quién está detrás de los gnolls Putrepellejo. Nuestros boticarios creen que su origen yace en el extraño líquido que fluye por sus cuerpos.|n|nVete a la Isla de Fenris, al este de El Viejo Embarcadero y recoge icor de los gnolls que encuentres allí. Llévaselo al boticario Renferrel, está fuera de El Sepulcro.', },
    {'Lleva 8 botellas de icor de Putrepellejo al boticario Renferrel en El Sepulcro.', },
  },
  [444] = {
    'El origen de los Putrepellejos',
    {'He reducido el icor que me has traído y he separado sus componentes básicos. Mis descubrimientos no son concluyentes, pero he determinado que en la creación del icor se utilizó brujería y nigromancia.|n|nMientras sigo estudiando el icor, quiero que le lleves una muestra a Bethor Duroyelo en Entrañas. Bethor no es un boticario, pero su conocimiento de la magia, puede ayudarnos a descubrir el misterio de los Putrepellejo.|n|nVete. Encontrarás a Bethor en el Barrio de la Magia de Entrañas.', },
    {'Lleva la muestra de icor a Bethor Duroyelo en Entrañas.', },
  },
  [445] = {
    'Entrega a Bosque de Argénteos',
    {'El tiempo es un lujo que no nos podemos permitir quienes trabajamos para Lady Sylvanas. Pero seguro que ya te habías dado cuenta.|n|nComo miembro de la Sociedad Real de Boticarios es mi deber compartir mis conocimientos con mis colegas para que con nuestro esfuerzo colectivo logremos algún día proporcionarle a la Dama Oscura su tan ansiada Nueva Peste.|n|nLlévale estas conclusiones al boticario Renferrel que está en El Sepulcro en el Bosque de Argénteos. Sigue los caminos que parten en dirección sur desde Rémol. Desde Entrañas, dirígete hacia el suroeste.', },
    {'Llévale los descubrimientos del boticario Holland al boticario Renferrel del Bosque de Argénteos.', },
  },
  [446] = {
    'Thule Corvozarpa',
    {'Este icor fue creado por un viejo amigo mío: Thule Corvozarpa. Antes de la Gran Guerra, era un joven mago muy prometedor, pero cuando el Rey Exánime ocupó el trono, traicionó a sus hermanos y aliados con la Plaga.|n|nNo me había dado cuenta de que todavía sigue con vida, ni de que él es quien lidera a los Putrepellejo contra nosotros.|n|nConozco muchos de sus hechizos y puedo ayudar a preparar una poción para contrarrestarlos. Lleva este pergamino al boticario Renferrel. Tiene los conjuros necesarios para la poción.', },
    {'Lleva el pergamino de Bethor al boticario Renferrel en El Sepulcro de Argénteos.', },
  },
  [447] = {
    'Una fórmula mortal',
    {'Arthas cuenta con innumerables tropas. Pero, con una Nueva Plaga podríamos erradicar tanto al ejército de la Plaga como a la infestación humana.|n|nMis estudios han demostrado que la sangre de araña combinada con una toxina derivada del corazón de un oso grisáceo resulta en un elixir letal. Reúne muestras de las arañas en Penumbra de las Celerácnidas, al noroeste, y de los osos que vagan por el Bosque de Argénteos. Lleva los componentes al maestro boticario Faranell de la Sociedad Real de Boticarios, en Entrañas.', },
    {'Consigue 6 corazones de oso grisáceo y 6 muestras de sangre de celerácnida y llévaselas al maestro boticario Faranell en Entrañas.', },
  },
  [448] = {
    'Preséntate ante Hadrec',
    {'Antes de iniciar un asalto a la Isla de Fenris, ve a ver al sumo ejecutor Hadrec. Es posible que tenga equipamiento o información adicional que pueda serte útil.', },
    {'Preséntate ante el sumo ejecutor Hadrec en El Sepulcro.', },
  },
  [449] = {
    'El informe de los Mortacechadores',
    {'Si bien las heridas de Quinn se están curando, quiero entregar nuestro informe al sumo ejecutor Hadrec lo antes posible. Contiene información vital para la ocupación de los Renegados de Argénteos.', },
    {'Lleva el informe de los Mortacechadores al sumo ejecutor Hadrec en El Sepulcro.', },
  },
  [450] = {
    'Una fórmula mortal',
    {'Puedes seguir ayudando a la Sociedad Real de Boticarios, $N.|n|nCuando Arugal utilizó su magia maligna en el bosque, maldijo a uno de nuestros miembros más prometedores, el boticario Berard. Ahora es un sirviente de Arugal, sin dominio de sí mismo. En estas condiciones, Berard no nos sirve de nada. Pero sus descubrimientos podrían servirnos. Estaba estudiando una antigua plaga que acabó con la vida acuática del Lago Lordamere años atrás.|n|nVe a buscar el Diario de Berard. Está en su estudio, el la Posada de la Aldea Piroleña, y llévaselo al boticario Renferrel.', },
    {'Recupera el Diario del boticario Berard de la Aldea Piroleña y llévaselo al boticario Renferrel en El Sepulcro.', },
  },
  [451] = {
    'Una fórmula mortal',
    {'Según el Diario de Berard, el musgo de los vagadores del Lago y los trepadores podría ser útil para nuestro objetivo de crear una Nueva Plaga. Esas bestias viven en las islas del Lago Lordamere, al este.|n|nTambién menciona un tumor endurecido muy extraño que descubrió en un múrloc Anca Vil. Por lo visto, el tumor es tan poco común, que Berard solo pudo obtener uno.|n|nReúne muestras del musgo y del tumor endurecido y llévaselas al maestro boticario Faranell en Entrañas.', },
    {'Lleva 6 muestras de moho de trepador del Lago, 6 muestras de moho de vagador del Lago y un tumor endurecido al maestro boticario Faranell en Entrañas.', },
  },
  [452] = {
    'La emboscada de Aldea Piroleña',
    {'¡Has llegado justo a tiempo, $N!|n|nEl Consejo Piroleña está a punto de regresar. Arugal tiene que encargarse de otras cosas en el bastión. Utiliza el Consejo como si fueran marionetas, para mantener a los ineptos esbirros de la Aldea Piroleña bajo su control. Pero creo que sin la ayuda del Consejo Piroleña, los hijos de Arugal se volverían contra su maestro.|n|nNo puedo encargarme de todo sin ayuda. Te necesito. Juntos podemos acabar con el Consejo para Lady Sylvanas.', },
    {'Ayuda a la mortacechadora Faerleia a destruir al Consejo Piroleña.', },
  },
  [453] = {
    'Encuentra la figura misteriosa',
    {'Buena suerte, $N. Espero que encuentres al tipo este... y que lo encuentres vivo.|n|nSi dejó la seguridad de Villa Oscura, podría haber sido víctima de las bestias salvajes.', },
    {'Encuentra a la figura misteriosa. Las pistas que tienes: |n|nNo es oriundo de Villa Oscura. |n|nEs una persona nerviosa, que se altera fácilmente. |n|nDejó Villa Oscura y se dirigió al oeste.', },
  },
  [454] = {
    'Tras la emboscada',
    {'Antes llevábamos juntos los barriles de pólvora. Pero ahora que ha pasado esto... Ahora tenemos que dividir el trabajo, Miran lleva los barriles y yo vigilo los otros.|n|nNo me gusta que Miran vaya por ahí solo con los barriles. ¿Te importa acompañarlo?', },
    {'Habla con Miran.', },
  },
  [455] = {
    'El asedio de Algaz',
    {'Los orcos del clan Faucedraco tienen un refugio en Los Humedales ¡y ahora se han adentrado en Dun Algaz! No podemos permitir que continúen afianzándose aquí o Loch Modan perderá el contacto con el Puerto de Menethil, nuestro puerto y bastión en Los Humedales.|n|nAtraviesa Dun Algaz y dirígete a Los Humedales, ¡cuando estés allí mata a tantos orcos como puedas! Informa a Valstag Quijahierro en Puerto de Menethil.|n|nMenethil está pasado Dun Algaz, siguiendo el camino hacia el Norte y al Oeste en el cruce.|n|nContamos contigo, $N. No nos falles.', },
    {'Atraviesa Dun Algaz.|n|nMata 8 exploradores Faucedraco y 6 brutos Faucedraco.|n|nInforma a Valstag Quijahierro de Puerto de Menethil.', },
  },
  [456] = {
    'El equilibrio de la naturaleza',
    {'Saludos, $N. Soy el conservador Ilthalaine. He venido a Cañada Umbría para asegurarme de que se mantiene el equilibrio de la naturaleza.|n|nEsta primavera ha llovido más de lo normal, lo que ha beneficiado mucho a algunas criaturas del bosque, pero ha perjudicado a otras.|n|nAhora hay demasiados sables de la noche y jabalíes Cardo; Cañada Umbría no puede alimentar a tantas bestias. Joven $C, reduce las poblaciones de jabalí Cardo y sable de la noche para mantener la armonía de la naturaleza.', },
    {'Mata a 3 sables de la noche y 3 jabalíes cardo jóvenes.', },
  },
  [457] = {
    'En deuda con la naturaleza',
    nil,
    nil,
  },
  [458] = {
    'La protectora de los bosques',
    {'Me alegro de que hayas llegado, $C. El susurro de los espíritus del bosque me ha traído extrañas nuevas.|n|nLa misteriosa protectora de los bosques, Tarindrella, ha regresado a Cañada Umbría. La presencia de la dríade en estos bosques no se conocía desde antes de la bendición de Teldrassil. Si ha viajado de nuevo hasta estas tierras, entonces sin duda algo va mal.|n|nBusca a Tarindrella y averigua qué asuntos la han traído aquí. Uno de los centinelas la ha avistado al suroeste de Aldrassil.', },
    {'Busca a la dríade Tarindrella.', },
  },
  [459] = {
    'Ladrones demoníacos',
    nil,
    nil,
  },
  [460] = {
    'Descansar en piezas',
    {'"No pareces un Putrepellejo. Bien. Ya había perdido la esperanza...|n|nMe llamo Alaric, y fui el jefe de los sirvientes y guardaespaldas de Thule. Utilizó su magia para "protegerme" de la peste de no-muertos, pero su hechizo me dio una no-vida de la que no puedo escapar. Después de crear a los malvados gnolls Putrepellejo, Thule me decapitó... y dio mi cabeza a los gnolls como juguete.|n|nPor favor, llévame con mi cuerpo. Creo que los gnolls lo enterraron aquí, en el Castillo de Fenris cerca del establo, en una tumba sin nombre."', },
    {'Lleva la cabeza de Alaric a su tumba.', },
  },
  [461] = {
    'El nicho oculto',
    {'Conozco un nicho oculto en el castillo que contiene un objeto muy valioso para Thule y sus viejos colegas. También contiene algo que podrías encontrar útil. ¡Llévame allí!|n|nEl nicho está en la torre suroeste del castillo, detrás de una estantería polvorienta.|n|nCoge mi cuerpo, pero deja mis botas. De todas formas... nunca me quedaron bien...', },
    {'Lleva a Alaric al nicho oculto.', },
  },
  [462] = {
    nil,
    {'Antes de enviarte a ti, enviamos a dos exploradores a Algaz. Solo regresó uno. Y esto es lo que descubrió:|n|nLos Faucedraco enviaron a uno de sus tenientes, Maruk Vermiscama, a organizar un grupo de orcos en Algaz para cortar la ruta terrestre al Puerto de Menethil.|n|nDebemos detenerles. Ahora. Mata a Maruk y luego ve al Puerto de Menethil a informar a Valstag Quijahierro.|n|nMaruk ha establecido su cuartel general en una pequeña cueva a la que se llega cruzando un lago entre el segundo y tercer túnel de Algaz. Cruza Algaz y ve hacia el oeste por la carretera para llegar a Menethil.', },
    {'Mata a Maruk Vermiscala.|n|nInforma a Valstag Quijahierro en el Puerto de Menethil.', },
  },
  [463] = {
    'El Guardaverde',
    {'¿Has oído hablar del Guardaverde? ¿No lo estarás buscando, verdad? Si lo buscas es que estás $Gloco:loca;, ¿pero quién soy yo para apartar a un idiota de su muerte?|n|nSi estás buscando a esa bestia, he oído decir que está en los pantanos, al este del camino cuando se divide hacia Dun Modr. Está escondido entre los crocoliscos... ¡y cosas aún peores!|n|nDeja aquí tu dinero. No lo necesitarás allí a donde vas... no querrás que Verdín se rompa un diente con tus monedas cuando te parta en dos de un bocado, ¿verdad?', },
    {'Encuentra al Guardaverde.', },
  },
  [464] = {
    'Estandartes de batalla',
    {'El clan orco Faucedraco fue prácticamente exterminado al final de la Segunda Guerra, cuando perdieron su control sobre los dragones Rojos que eran sus mascotas. Los dragones no estaban muy contentos con sus antiguos dueños y dieron caza despiadadamente a todos los Faucedraco. Los pocos que quedaron huyeron de Grim Batol y se refugiaron en las montañas al este de la Excavación de Whelgar.|n|nAhora han ganado fuerza y tienen un campamento al noreste de Menethil.|n|nQueremos que ataques ese campamento. Recoge sus estandartes de guerra y tráemelos como prueba.', },
    {'Lleva 8 estandartes de guerra Faucedraco al capitán Puñorrecio.', },
  },
  [465] = {
    'La estrategia de Nek\'rosh',
    {'Mientras estabas combatiendo a los Faucedraco, descubrimos más cosas sobre sus planes.|n|nNek\'rosh ha construido catapultas ¡y pretende asediar Menethil! ¡Además, debido a la lucha en Dun Algaz no podemos recibir refuerzos!|n|nTienes que acabar con esas catapultas. Están en el campamento Faucedraco.|n|nToma, coge esta yesca. Ábrete camino hasta las catapultas y préndeles fuego con la yesca.|n|nCuando hayas terminado, encuentra y mata a Nek\'rosh. Necesitamos acabar con esta bestia Faucedraco... de raíz.', },
    {'Destruye las catapultas Faucedraco.', },
  },
  [466] = {
    'Búsqueda de incendicita',
    {'He oído decir que se encontró un extraño mineral, incendicita, en Los Humedales, en una cueva al noroeste de la Puerta de Algaz. La incendicita es un material volátil y es difícil de utilizar sin que explote, ¡pero seguro que si se funde de la forma adecuada podría hacer proyectiles de cañón que harían un daño tremendo!|n|nTráeme mineral de incendicita y encontraré a alguien que se atreva a experimentar con él.|n|nOh, una cosa más, para extraer el mineral de un filón tendrás que saber minería. ¡Si no eres $Gminero:minera; lleva uno contigo a la cueva!', },
    {'Lleva 6 piezas de mineral de incendicita al piloto Roscapiedra de Dun Morogh.', },
  },
  [467] = {
    'La búsqueda de los Roscapiedra',
    {'¡Al piloto Roscapiedra le encanta su máquina de asedio! ¡Y siempre anda buscando maneras de mejorar su cilindrada!|n|nHa oído hablar de un mineral muy raro y necesita a alguien que se lo consiga. Si te apetece una aventurilla, ve a hablar con él en el Almacén de Brasacerada en Dun Morogh.', },
    {'Habla con el piloto Roscapiedra.', },
  },
  [468] = {
    'Preséntate ante el montaraz Piedragar',
    {'El montaraz Piedragar está buscando voluntarios para una misión que les llevará a través de Dun Algaz hasta Los Humedales.|n|nSi quieres mojarte las botas en ese embarrado condado del Norte, habla con Piedragar en Dun Algaz, siguiendo el camino hacia el Norte, pasada la torre de vigilancia.', },
    {'Habla con el montaraz Piedragar.', },
  },
  [469] = {
    'Entrega cotidiana',
    {'¡Saludos $Gviajero:viajera;!|n|n¿Acaso te diriges hacia Menethil? Si no es así, te recomendaría ir y hacer un alto. Es un buen lugar para hacer unas compras o para disfrutar de una buena pinta y de algo de descanso.|n|nAhora bien, si ya te dirigías hacia allí, no creo que te importe llevarle este fardo de pieles de crocolisco a James Halloran, el curtidor.|n|nLo haría yo mismo, pero últimamente mi mujer no está de muy buen humor, me gustaría verla lo más tarde que pueda.', },
    {'Entrega el fardo de pieles de crocolisco a James Halloran, el curtidor, en Puerto de Menethil.', },
  },
  [470] = {
    'Abriéndose paso entre los mocos',
    {'¡Durante mi visita semanal a la Tumba de Barbaférrea fui atacada por espantosos y pringosos mocos! Por supuesto, me entró pánico.|n|nLe lancé mi bolsa a uno de ellos, ¡pero no le hizo nada! El moco la absorbió... Por fortuna eso me dio algo de tiempo para escapar.|n|n¡La mala noticia es que necesito recuperar el contenido de mi bolsa!|n|nNo sé a qué moco le lancé la bolsa, ¡todos parecían iguales! La Tumba de Barbaférrea está al noreste de aquí, cerca de Dun Modr. ¡Muchísimas gracias!', },
    {'Uno de los mocos de la Tumba de Barbaférrea tiene la Bolsa de Shida, recupérala y devuélvesela en Puerto de Menethil.', },
  },
  [471] = {
    'Deberes de aprendiz',
    {'Envié a mi aprendiz a los pantanos para desollar algunos de nuestros famosos crocoliscos gigantes de Los Humedales. Cuando no regresó salí a buscarlo... Basta decir que no fue una visión muy agradable.|n|nLa matrona dice que el chico podría recuperarse, ¡pero hasta entonces sigo necesitando pieles!|n|n... Si quisieras matar unas cuantas de esas bestias no estaría en contra, después de todo lo que hicieron. Encontrarás a los crocoliscos al Norte, siguiendo la costa y pasadas las casuchas de los múrlocs.', },
    {'Reúne 6 pieles de crocolisco gigante y llévaselas a James Halloran en Puerto de Menethil.', },
  },
  [472] = {
    'La caída de Dun Modr',
    {'¡Dun Modr ha caído en manos de los enanos Hierro Negro!|n|nMis heridas son graves, $C. ¡Y casi todo mi regimiento fue asesinado! Los matones Hierro Negro nos atacaron antes de que pudiéramos reagruparnos tras la emboscada del Puente Thandol.|n|nNuestro líder, Largatrenza, hizo sonar el cuerno de retirada. Cuando dejamos la ciudad fui herido en la espalda con un hacha perdida. Todo se volvió negro.|n|nDesperté aquí, en Menethil, pero estoy preocupado por mis compañeros. Aún abrigo esperanzas. ¡Quizás Largatrenza siga con vida! ¡Ve a ver si puedes encontrarle cerca de Dun Modr, $R!', },
    {'Busca a Largatrenza junto a la ciudad de Dun Modr.', },
  },
  [473] = {
    'Preséntate ante el capitán Puñorrecio',
    {'$N. El clan orco Faucedraco está mostrando su fuerza, y no solo en Algaz. El capitán Puñorrecio ha pedido hablar con quienes quieran ofrecer su ayuda contra esos orcos. Lo encontrarás en el castillo, en la Sala de Mandos.', },
    {'Habla con el capitán Puñorrecio.', },
  },
  [474] = {
    'Derrota a Nek\'rosh',
    {'Ahora que las catapultas han ardido, encuentra y mata al jefe Nek\'rosh.', },
    {'Mata al jefe Nek\'rosh.|n|nLleva la cabeza de Nek\'rosh al capitán Puñorrecio.', },
  },
  [475] = {
    'Una brisa problemática',
    {'Se avecinan problemas en el bosque.|n|nGaerolas Talvethren es el Gran celador de los druidas hibernantes de la Garra en Túmulo de Ban\'ethil. Su función como protector de los Adormecidos es preservar su seguridad de modo que no se rompa el pacto que tienen con Ysera. |n|nPero hace tiempo que no sé nada de él y me inquieta. Viaja al este hasta la Aldea Brisa Estelar para hablar con Gaerolas y regresa para informarme de todo. Cuando sepa que mis hermanos duermen apaciblemente, me quedaré más tranquilo.', },
    {'Busca a Gaerolas Talvethren en la Aldea Brisa Estelar.', },
  },
  [476] = {
    'Corrupción en Tuercepinos',
    {'¡La corrupción de la tribu de los Tuercepinos ha resurgido!|n|nMe tendieron una emboscada cuando me marchaba para Túmulo de Ban\'ethil y saquearon la Aldea Brisa Estelar. Algo del bosque ha corrompido a Ursal el Violento, su jefe, que está empleando los maléficos poderes del musgovil para volverlos locos.|n|nYo estoy malherido y no puedo llevarle estas trágicas noticias a Athridas; tendrás que hacerlo tú, joven $C. ¡Esperemos que los trastornados Tuercepinos aún no hayan llegado a Ban\'ethil!', },
    {'Ve a ver a Athridas Manto de Oso a Dolanaar.', },
  },
  [477] = {
    'Pasa la frontera',
    {'Como sabrás, la ciudad de Molino Ámbar sigue siendo una fuente de oposición humana, principalmente gracias al apoyo que reciben de los magos de Dalaran.|n|nNo sé cuál es su plan, pero que se hayan interesado por un lugar tan remoto como Molino Ámbar, indica que tiene que ser más importante de lo que pensamos.|n|nHan estado enviando cajas por carro desde Trabalomas. Muchos de esos suministros acaban en un pequeño campamento al norte de la Aldea Piroleña. Consigue los contenidos de una caja y tráemelos.', },
    {'Recupera el contenido de una de las cajas de zahoríes de Dalaran. Encontrarás la Aldea Piroleña hacia el sur.', },
  },
  [478] = {
    'Mapas y runas',
    {'<Rápidamente coges el colgante de la caja y vuelves a colocar la tapa.>', },
    {'Lleva el extraño colgante al sacerdote de las Sombras Allister en El Sepulcro.', },
  },
  [479] = {
    'Las investigaciones de Molino Ámbar',
    {'Dalar está intentando localizar la fuente de los hechizos de los magos. Por ahora, tendremos que ralentizar su avance como podamos...|n|nLos conjuradores, magos y protectores tienen, sin lugar a dudas, los colgantes. Quítaselos.|n|nSigue hacia el sur por el camino principal y después, dirígete al este, a Molino Ámbar.', },
    {'Consigue 8 colgantes de Dalaran al sacerdote de las Sombras Allister en El Sepulcro.', },
  },
  [480] = {
    'El Tejedor',
    {'Un archimago de gran poder está supervisando la reactivación del nodo de energía Ley. Con el progreso que han conseguido, nuestra única esperanza de detenerles es matándole. Será difícil, estará protegido por muchos magos y depositarios.|n|nDebes ir y acabar con él rápidamente. Cuando esté muerto, tráeme su bastón. Ahora, vete.', },
    {'Mata al archimago Dalaran, recupera su bastón y llévaselo al sacerdote de las Sombras Allister en El Sepulcro.', },
  },
  [481] = {
    'El análisis de Dalar',
    {'Lleva el colgante a Dalar Tejealba, quizás pueda ayudarnos a entender los planes de los magos.', },
    {'Lleva el colgante con runas grabadas a Dalar Tejealba en El Sepulcro.', },
  },
  [482] = {
    'Las intenciones de los Dalaran',
    {'¡Por supuesto! ¿Cómo se me ha podido olvidar?|n|nMolino Ámbar fue uno de los lugares marcados por el Kirin Tor, debido a que tiene un nodo de energía Ley inactivo. Los magos deben de estar planeando reactivar el nodo y usar sus energías para algo.|n|nNo podemos permitir que esto ocurra...|n|nPara activar las energías Ley de la zona, necesitarán una gran cantidad de poder. Podemos paralizarlo todo si conseguimos los colgantes de los magos.|n|nCuéntale esto a Allister, él decidirá lo que tenemos que hacer.', },
    {'Habla con el sacerdote de las Sombras Allister en El Sepulcro.', },
  },
  [483] = {
    'Las Reliquias del Despertar',
    {'Los invasores Tuercepinos han sido vistos saqueando Túmulo de Ban\'ethil, en la colina hacia el oeste.|n|nLos druidas durmientes quedarán atrapados en el Sueño Esmeralda por toda la eternidad, ajenos a sus destinos, a menos que les ayudemos. El delicado ritual de hibernación no puede detenerse sin las Reliquias del Despertar.|n|nViaja al Túmulo y consigue el talismán de la garra del cuervo, el plumón pluma negra, el zafiro de cielo y la runa de Nidal que los druidas guardan en cofres sagrados. Tráemelos y podré preparar el ritual del despertar.', },
    {'Consigue las Reliquias del Despertar.', },
  },
  [484] = {
    'Piel de crocolisco joven',
    {'Soy James Halloran, el curtidor. Mis pieles curtidas de crocolisco son las más apreciadas de todas y llegan cargamentos a todos los puertos del mundo.|n|n¿Viste a Einar? Es uno de los cazadores encargados de proporcionarme pieles de crocolisco.|n|nMe estoy quedando sin las suaves pieles de crías de crocolisco.|n|nPor eso te pagaré generosamente por una pila de esas pieles. Podrás encontrar crías de crocolisco en los pantanos que están a las mismas puertas de la ciudad.', },
    {'Consigue 4 pieles de crocoliscos jóvenes para James Halloran de Puerto de Menethil.', },
  },
  [485] = {
    '¡Encuentra a OOX-09/TI!',
    {'Has descubierto una especie de instrumento extraño de metal y con forma de huevo. Si jugueteas con uno de los botones del huevo, este toma vida. ¡Se convierte en una especie de artilugio robótico gnomo! Y del interior del huevo sale una voz.|n|n"Mi nombre es Oglethorpe Obnoticus, ¡y mi robot mensajero se ha averiado! Te recompensaré por su rescate. Por favor, lleva este localizador hasta el robot."|n|n"He procesado las coordenadas del robot: falló en la cabecera del río, cerca de Roca Oculta."', },
    {'Lleva el localizador al robot mensajero de Oglethorpe, en el nacimiento del río de las Tierras del Interior, cerca de Roca Oculta.', },
  },
  [486] = {
    'Ursal el Violento',
    {'Ha llegado el momento de salvar a los druidas de la Garfa. Si fallamos ahora, $N, nunca podrán despertar de su sueño.|n|nPrepararé las Reliquias del Despertar para llevar a cabo el ritual. Para que mis esfuerzos surtan efecto, hay que eliminar a las malditas bestias responsables de esta horrible situación. Solo en ese momento podrá completarse el ritual.|n|nUrsal el Violento fue quien se metió con nuestros hermanos y él será el que pague las consecuencias de su liberación. Sigue el camino al noroeste y encontrarás un sendero hacia el norte que lleva a La Grieta. El cubil de Ursal estará ahí.', },
    {'Mata a Ursal el Violento.', },
  },
  [487] = {
    'El camino a Darnassus',
    {'Hay que reforzar la seguridad en el camino que conduce a Darnassus. Unos fúrbolgs corruptos de la tribu de los Tuercepinos han estado atacando despiadadamente a los viajeros.|n|nEse camino se utiliza a diario para transporte de mercancías y es la vía de comunicación más importante de Darnassus. No podemos permitir que esa pandilla de delincuentes paganos aterrorice a la gente.|n|nLevántate en armas en nombre del bosque sagrado, $C. Su guarida se encuentra siguiendo este camino, hacia el norte. Acaba con los emboscadores Tuercepinos y después vuelve para informarme.|n', },
    {'Acaba con 8 emboscadores Tuercepinos.', },
  },
  [488] = {
    'Las apuestas de Zenn',
    {'Veo que tienes ganas de trabajar... Por suerte para ti, no hay un día que pase que no desee tener cerca a $Gun:una; inocente $C a quien proponerle mi oferta.|n|n¿Sabes, $N? Puedo hacerte muy feliz y ofrecerte cosas que jamás hubieras soñado tener, pero para ello deberás traerme una serie de objetos.|n|nPara desempeñar mi trabajo en el bosque a veces necesito ciertos... componentes. Tráeme colmillos de sable de la noche, plumas de lechuza estrígida y muestras de seda de araña Tejemadera.|n|nY que esto quede entre nosotros, $R.', },
    {'Consigue 2 colmillos de sable de la noche, 2 plumas de lechuza estrígida y 2 muestras de seda de araña Tejemadera.', },
  },
  [489] = {
    '¡Búsqueda de redención!',
    {'El Consejo del Bosque se ha enterado de que ayudaste a Zenn Nauseapezuña, un sátiro enemigo del bosque. Como $Gbuen:buena:r; $R que eres, no deberías dedicarte a mancillar el bosque matando criaturas de la naturaleza.|n|nHas de reparar tu error ante el Consejo si deseas seguir siendo $Gamigo:amiga; de Teldrassil.|n|nDale a Nauseapezuña una lección y recibirás tu perdón. Las bellotas viles son semillas corruptas que caen de los árboles y que expulsan humo verde.|n|nDale algunas a Nauseapezuña, él creerá que se trata de un inofensivo aperitivo.', },
    {'Recoge 3 bellotas viles.', },
  },
  [490] = {
    nil,
    {'Por orden estricta del Consejo de Darnassus, establezco una recompensa por la tribu Tuercepinos. Ya no son amigos del bosque. Su corrupción los ha convertido en una amenaza salvaje para nuestro pueblo y las criaturas del claro.|n|nConforme ha decretado el Consejo, se te recompensará por eliminar la amenaza fúrbolg de Kalidar. Tráeme sus colmillos como prueba de tus actos.', },
    {'Shayla Brisa Nocturna, en las afueras de Darnassus, desea que le traigas 20 colmillos de Tuercepinos.', },
  },
  [491] = {
    'Una varita para Bethor',
    {'Una vez Thule me dijo que, mucho tiempo atrás, él y dos de sus colegas crearon una varita mágica, combinando las varitas de aprendiz que cada uno de los magos tenía. Esta varita fue un símbolo de su amistad y, aunque Thule llegó a despreciarla, no pudo deshacerse de ella, ni permitir que los otros la tuvieran. Así que robó la varita y la escondió en el Castillo de Fenris.|n|nAquí. Lleva la varita a Bethor Duroyelo, uno de los antiguos amigos de Thule. Seguro que la quiere.', },
    {'Lleva la varita tejida a Bethor Duroyelo en el Barrio de la Magia, en Entrañas.', },
  },
  [492] = {
    'Una nueva Peste',
    {'De acuerdo con la Guardia de la Muerte, acaban de capturar a otro de esos insensatos enanos montaraces. La Guardia de la Muerte suele encerrar a los prisioneros en el sótano del Mesón La Horca hasta que pueda encargarse "debidamente" de ellos.|n|n¿Por qué no vas a comprobar si al montaraz capturado le gusta la bebida especial que he preparado para él? Contiene una pequeña muestra de lo que la Dama Oscura tiene reservado para todo Azeroth.', },
    {'Llévale la bebida especial de Johaan al montaraz capturado.', },
  },
  [493] = {
    'Viaja a Laderas de Trabalomas',
    {'La Dama Oscura está presionando mucho a la Sociedad Real de Boticarios para que creen una Nueva Plaga. Estamos trabajando diligentemente y hemos avanzado mucho. Creemos que lo conseguiríamos antes si compartiésemos información entre la Sociedad.|n|nPor esa razón, quiero que entregues mis últimos descubrimientos al boticario Lydon en el Molino Tarren, una pequeña ciudad en las Laderas de Trabalomas. El viaje será largo.|n|nDirígete al sur y no te alejes de los caminos. ¡Sigue las señales de cerca!', },
    {'Lleva el descubrimiento del boticario Renferrel al boticario Lydon en la ciudad de Molino Tarren, en las Laderas de Trabalomas.', },
  },
  [494] = {
    '[DEPRECATED]El momento de atacar',
    {'Cállate y presta atención, $C.|n|nMe han enviado aquí para vigilar Trabalomas. La mía es una misión de reconocimiento. Debes enviar un mensaje a la suma ejecutora Darthalia, a Molino Tarren, de inmediato. Dile que la mortacechadora Lesh le envía este mensaje:|n|n"Desde el oeste nos llega el llanto del cuervo."|n|nSigue el camino que va al este y fíjate bien en las indicaciones. ¡Apresúrate! ¡Ve a Molino Tarren a toda prisa!', },
    {'Ve a Molino Tarren para llevar el mensaje de la mortacechadora Lesh a la suma ejecutora Darthalia.', },
  },
  [495] = {
    'Corona de Voluntad',
    {'Jarra\'thol y sus ogros debían ir a Alterac en busca de la Corona de Voluntad para Lady Sylvanas. Por desgracia, en lugar de regresar con ella, el muy idiota decidió probarla... Supongo que los ogros no se pueden resistir a nada luminoso y brillante.|n|nSin embargo, su constante incompetencia se está convirtiendo en un problema. La Corona de Voluntad le permitió resistirse a la posesión que le obligaba a servir a Lady Sylvanas.|n|nLa Dama Oscura quiere darle un castigo ejemplar; viaja al Molino Tarren en Trabalomas e informa a Melisara, mi teniente.', },
    {'Preséntate ante Melisara que está en Molino Tarren, en las Laderas de Trabalomas.', },
  },
  [496] = {
    '[DEPRECATED]Elixir de sufrimiento',
    {'Otro maldito día en el Molino Tarren. Todo este aire puro me pone enfermo, $N.|n|nTenemos que infestar a los humanos cuanto antes. He estado estudiando potenciales agentes letales para utilizar en mis brebajes pero no he tenido tiempo de recogerlos todos.|n|nSi quieres hacer algo útil, podrías procurarme los siguientes objetos: diez lenguas de oso gris e icor de trepador, que es muy raro y difícil de encontrar. Nada más salir del Molino Tarren encontrarás osos y trepadores.', },
    {'El boticario Lydon de Molino Tarren quiere 10 lenguas de oso gris y un poco de icor de trepador.', },
  },
  [497] = {
    nil,
    {'De niño, me formaron para ser gladiador en el Castillo de Durnholde, trabé amistad con Taretha, la hija de mi nodriza y amante del malnacido de Lodonegro.|n|nEl pasado enterrado está, $N, pero los informes de movimientos de humanos en Trabalomas me han recordado esos tiempos. Envié a un reducido grupo de hombres a esa región para investigar y recuperar un... objeto... que Taretha me dio, si les era posible.|n|nUna tarea infructuosa, sin duda, pero quizás...|n|nYa deberían haber vuelto, deseo que vayas a Molino Tarren a investigar.', },
    {'Ve a Molino Tarren y averigua en qué situación se encuentra el grupo que Thrall envió.', },
  },
  [498] = {
    '[DEPRECATED]El rescate',
    {'El Jefe de Guerra me envió con algunos compañeros a Durnholde para recoger un objeto e investigar a esa tal Hermandad.|n|nFuimos a echar un vistazo, pero un numeroso grupo de humanos nos atacó por sorpresa. Luchamos como fieras, pero estábamos en franca minoría. Nos tomaron cautivos a algunos, pero conseguí escapar.|n|nDurnholde está al otro lado del río, hacia el sureste. Drull y Tog\'thar están retenidos allí; debes ir a rescatarlos.', },
    {'Krusk de Molino Tarren quiere que liberes a Drull y a Tog\'thar en el Castillo de Durnholde.', },
  },
  [499] = {
    '[DEPRECATED]Elixir de sufrimiento',
    {'Tardaré un momento en mezclar estos ingredientes para crear lo que yo llamo mi elixir de sufrimiento.|n|n¡Allá vamos! Ah, nada me alegra tanto la vida en este lugar miserable como traer padecimientos al mundo.|n|nVeamos si la poción tiene el efecto deseado.|n|nDale a probar a mi asistente Umpi lo que la Dama Oscura ha planeado tanto para los humanos como para la Plaga.', },
    {'Dale el elixir de sufrimiento a Umpi.', },
  },
  [500] = {
    '[DEPRECATED]La recompensa Aplastacresta',
    {'Los ogros Aplastacresta han construido un túmulo en las Montañas de Alterac, cerca de la ciudad arrasada de Alterac. Los exploradores indican que también han invadido las ruinas.|n|nSi dejamos que se queden ahí, su siguiente paso será bajar las colinas y llegar hasta nosotros.|n|nVe a liquidar ogros en las Montañas de Alterac, hacia el norte. Si quieres ganar un buen botín, tráeme todos los nudillos sucios que llevan.', },
    {'Recoge 9 nudillos sucios de ogros Aplastacresta en las Montañas de Alterac. Llévaselos al alguacil Rutagrana a Costasur.', },
  },
  [501] = {
    '[DEPRECATED]Elixir de dolor',
    {'Oh, $N. En Trabalomas todo está florecido y el aire es puro y fresco. No puedo soportarlo. Miro por mi mugrienta ventana y espero el día en que nuestra Nueva Plaga traiga a este mundo la muerte que merece.|n|nAunque me gustaría perderme en mis negras reflexiones, el deber hacia la Dama Oscura me llama. ¿Quieres ayudarme? Según mis estudios, puedo obtener una estupenda poción letal con sangre de león de montaña. Tráeme un poco, verás qué bien lo pasaremos.', },
    {'Lleva 10 viales de sangre de león de montaña al boticario Lydon de Molino Tarren.', },
  },
  [502] = {
    '[DEPRECATED]Elixir de dolor',
    {'¡No hay nada como el olor a sangre fresca!|n|nAhora añadimos un poquito de esto y una pizca de esto otro ¡y ya está! Esta poción se llama elixir de dolor. Si mis cálculos son correctos, este brebaje complacerá enormemente a Lady Sylvanas. Pero antes hay que probarlo.|n|nLlévalo a la granja norteña de Campos de Trabalomas, que está al suroeste. A ver qué le parece esta golosina a Stanley, el perrito del granjero Ray.', },
    {'Dale el elixir de dolor a Stanley.', },
  },
  [503] = {
    '[DEPRECATED]Gol\'dir',
    {'Según los documentos que has traído, tienen a Gol\'dir en una importante base de la Hermandad situada al norte, probablemente en las Montañas de Alterac. Ya lleva demasiado tiempo cautivo; hay que liberarlo.', },
    {'Libera a Gol\'dir e informa a Krusk en Molino Tarren.', },
  },
  [504] = {
    '[DEPRECATED]Belicistas Aplastacresta',
    {'Ahora que has conocido a los ogros Aplastacresta, quiero que les revientes las narices...|n|nVe a las Ruinas de Alterac y busca a esos belicistas Aplastacrestas. Quiero que liquides a un buen número de ellos. Es la única forma de que esos brutos aprendan a mantenerse alejados del territorio de la Alianza.', },
    {'Mata a 10 belicistas Aplastacresta y vuelve a hablar con el alguacil Rutagrana en Costasur.', },
  },
  [505] = {
    '[DEPRECATED]Hermandad de asesinos',
    {'Soy el nuevo magistrado de Costasur. Mi ilustre predecesor fue asesinado. No se ha encontrado a los asesinos, pero la investigación apunta a que eran mercenarios de la Hermandad, un grupo de ladrones liderados por unos nobles sin honor del desaparecido reino de Alterac.|n|nLa Hermandad tiene un campamento en el Saliente de Sofera y en Daga de Corahn, al norte y al oeste de Molino Tarren, territorio ocupado por la Horda. Elimina a los miembros de la Hermandad que encuentres en estos campamentos.', },
    {'Mata a 12 asaltantes de caminos y 8 ladrones de la Hermandad e informa al magistrado Henry Maleb en Costasur.', },
  },
  [506] = {
    '[DEPRECATED]El legado de Lodonegro',
    {'Hace uno o dos días me visitó el líder de una organización que se llama la Hermandad. Su nombre era Aliden Perenolde y se considera a sí mismo el señor de esta tierra. Me confió sus planes de convertir en esclavos a los orcos que se enfrentan a él, tal y como su padre y su mentor, el despreciado Lodonegro, habían planeado.|n|nPero lo más importante es que traía consigo a su querida, una chica menudita llamada Elysa. Que llevaba puesto el colgante que desea el Jefe.|n|nAhora ve. Yo seguiré mi camino cuando haya acabado de arreglar mis asuntos.', },
    {'Lleva la información recopilada por Gol\'dir a Krusk a Molino Tarren.', },
  },
  [507] = {
    '[DEPRECATED]Lord Aliden Perenolde',
    {'Es evidente que hay que eliminar a Perenolde, erradicar su vileza. Su mansión está hacia el norte, a orillas del Lago Lordamere. $N, cumple con tu deber, recupera el colgante que anhela el Jefe de Guerra y vuelve aquí.', },
    {'Mata a Aliden Perenolde y pregunta a su querida, Elysa, por el colgante de Taretha.', },
  },
  [508] = {
    '[DEPRECATED]Un regalo de Taretha',
    {'¿El colgante? Claro que te lo puedes quedar... ¡Llévatelo! No quiero ningún recuerdo de él... tan solo, solo deja en paz...', },
    {'Devuélvele el colgante de Taretha a Krusk, que está en el Molino Tarren, en las Laderas de Trabalomas.', },
  },
  [509] = {
    '[DEPRECATED]Elixir de agonía',
    {'Un día más, un elixir más. Si por mí fuera, dejaría que esos ridículos humanos y la Plaga se mataran mutuamente. De hecho, ese parece ser su único objetivo.|n|nNuestra Dama Oscura quiere acelerar el proceso, así que ¿por qué no pasar estos negros días sembrando muerte y enfermedad por el lugar?|n|nEste es el plan, $N: ve a la Granja Nethander, al sur de Molino Tarren y al este del río y de Costasur. Tráeme seis flores Morrobarro para mi próximo elixir.', },
    {'Lleva 6 flores Morrobarro al boticario Lydon de Molino Tarren.', },
  },
  [510] = {
    '[DEPRECATED]Documentos de planificación',
    {'Entre los documentos hay un pedido de suministros. Incluye objetos de uso diario (alimentos, armas, ropas) y otros menos usuales (máscaras, combustible, veneno).|n|nPero lo más importante es la urgencia del pedido: los suministros eran necesarios para lo que se describe como "una importante misión contra Costasur."', },
    {'Lleva los documentos de planificación al magistrado Maleb a Costasur.', },
  },
  [511] = {
    '[DEPRECATED]Una carta cifrada',
    {'Una de las cartas de la mesa está cifrada y es inescrutable.', },
    {'Lleva la carta cifrada al maestro cultural Dibbs en Costasur.', },
  },
  [512] = {
    '[DEPRECATED]Nobles muertes',
    {'Temo que la Hermandad aspire a provocar la caída de Costasur. Debemos eliminar a la cúpula para que no puedan llevar a cabo sus planes.|n|nVe a las ruinas de Strahnbrad; están al norte, en las Montañas de Alterac. Creemos que la Hermandad se concentra en esa zona.|n|nSabemos que los jefes de estos maleantes son antiguos nobles de Alterac. Puede que estén disfrazados de agentes ordinarios de la Hermandad, pero los distinguirás por los sellos que llevan.|n|nTráeme los sellos.', },
    {'Lleva 7 sellos de Alterac al magistrado Maleb a Costasur.', },
  },
  [513] = {
    '[DEPRECATED]Elixir de agonía',
    {'Justo cuando pensaba que este sería otro día triste y sin alegría, me traes estas maravillosas flores Morrobarro.|n|nEl primer paso es molerlas. Luego el maestro boticario Faranell de Entrañas aplicará su coloide de decadencia y ya estará listo.|n|nLlévale este compuesto Morrobarro al maestro boticario Faranell a toda prisa, $N.', },
    {'Lleva el compuesto Morrobarro al maestro boticario Faranell a Entrañas.', },
  },
  [514] = {
    nil,
    {'Tengo un colega en Forjaz que quizás pueda descifrarla. Ve a la biblioteca de la Sala de los Expedicionarios, en Forjaz, y habla con el prospector Pico Tormenta. Dile que vas de mi parte y enséñale la carta. Si hay alguien que pueda descifrar esto al norte de Cumbre de Roca Negra, ese es él.', },
    {'Lleva la carta cifrada con ingenio al prospector Pico Tormenta a Forjaz.', },
  },
  [515] = {
    '[DEPRECATED]Elixir de agonía',
    {'¿Una mezcla Morrobarro? ¡Brillante! ¿Cómo no se me ha ocurrido a mí?|n|nVoy a añadir mi coloide de decadencia a este maléfico brebaje.|n|nPara activar los agentes contaminantes de este preparado, Lydon necesitará una poción de sangre de trol fuerte, escamas Espinadaga y ojos de aleta rasgados de la costa sur de Trabalomas. Él ya sabrá qué hacer con esos reactivos. ¡Ardo en deseos de saber el resultado del experimento!', },
    {'Lleva la mezcla Morrobarro, una poción de sangre de trol fuerte, 5 escamas Espinadaga y 5 ojos de aleta rasgados al boticario Lydon a Molino Tarren.', },
  },
  [516] = {
    'El Desafío de Beren',
    {'Me han informado sobre un grupo de no-muertos que están reagrupándose para preparar un ataque contra nosotros. Con esta información, podemos hacer algo y atacar primero, poniendo fin de un manotazo a su pequeño plan.|n|nPor desgracia, la información de la que dispongo es bastante incompleta. Se supone que están escondidos en El Desafío de Beren. Se desconoce la ubicación exacta, pero parece ser una cueva en las colinas, cerca de unos magos de Dalaran.|n|nConfío en tus recursos. Encuéntrales y acaba con ellos.', },
    {'Encuentra El Desafío de Beren y, a continuación, mata 6 esclavos Corvozarpa y 6 guardianes Corvozarpa. Por último, vuelve a ver al sacerdote de las Sombras Allister en El Sepulcro.', },
  },
  [517] = {
    '[DEPRECATED]Elixir de agonía',
    {'El nuevo elixir ya está listo para probar. Pero sería una pena malgastar una plaga potente y altamente contagiosa en un sapo o un perro. Vamos a divertirnos en nombre de Lady Sylvanas.|n|nVete a Dun Garok. ¿Sabes las barracas en las que se hacinan esos asquerosos enanos? Tráeme un barril de cerveza Machacacanillas. Y cuando lo traigas nos pegaremos una buena fiesta, $N.', },
    {'Lleva un barril de cerveza Machacacanillas al boticario Lydon de Molino Tarren.', },
  },
  [518] = {
    '[DEPRECATED]Corona de Voluntad',
    {'Jarra\'thol y sus ogros Aplastacresta han invadido las ruinas de Alterac. Tenemos que reducir sus filas si queremos castigarlo.|n|nPrimero los debilitamos y después procedemos.|n|n¿Entendido? Bien. Adelante.', },
    {'Melisara de Molino Tarren quiere que mates a 10 aplastadores Aplastacresta.', },
  },
  [519] = {
    '[DEPRECATED]Corona de Voluntad',
    {'Targ, Rastrazo y Glommus son los generales de Jarra\'thol. Le son leales, aunque quién sabe qué instiga la lealtad de un ogro.|n|nTráeme sus cabezas, $N, y después solo quedará separar a Jarra\'thol de la suya, corona incluida.', },
    {'Mata a Targ, Rastrazo y Glommus y lleva sus cabezas a Melisara a Molino Tarren.', },
  },
  [520] = {
    '[DEPRECATED]Corona de Voluntad',
    {'Con los tenientes de Jarra\'thol muertos, ya solo queda matar a Jarra\'thol y hacerse con la Corona de Voluntad. No tengo dudas de que no querrá dártela voluntariamente, y menos ahora que has acabado con sus servidores.|n|nEncuentra a Jarra\'thol y tráeme su cabeza y su corona. La resistencia Aplastacresta tiene que terminar.', },
    {'Mata a Jarra\'thol y lleva su cabeza con la Corona de Voluntad a Melisara a Molino Tarren.', },
  },
  [521] = {
    '[DEPRECATED]Corona de Voluntad',
    {'Ahora solo falta ir a Entrañas para entregarle la corona a Sharlindra. Ella se ocupará de entregársela a Lady Sylvanas. Te advierto que no debes usarla para tus propios fines, $N; recuerda lo que le ha pasado a Jarra\'thol.', },
    {'Ve a Entrañas para entregarle la Corona de Voluntad a Sharlindra.', },
  },
  [522] = {
    '[DEPRECATED]Contrato de asesino',
    {'Esto es un contrato para el asesinato del magistrado Henry Maleb. Estaba lacrado con cera roja y un sello muy distintivo.', },
    {'Lleva el contrato de asesinato al magistrado Maleb a Costasur.', },
  },
  [523] = {
    '[DEPRECATED]Muerte al Barón',
    {'Está firmado por el Barón Vardus, un noble del antiguo reino de Alterac conocido por su crueldad y brutalidad. No me sorprende que el Barón sea responsable de esto.|n|nDebes buscarlo. Encuéntralo y entrégalo a las autoridades. Debe de estar en alguna guarida de la Hermandad, en las ruinas de Strahnbrad o en el valle que hay al norte de ellas.', },
    {'Lleva la cabeza del Barón Vardus al magistrado Maleb a Costasur.', },
  },
  [524] = {
    '[DEPRECATED]Elixir de agonía',
    {'Los Guardias de la Muerte tienen retenidos a varios granjeros. La suma ejecutora Darthalia sospechaba que uno de los estrategas militares de Ventormenta estaba entre ellos. Al parecer fue encontrado muerto anoche en las Tierras de la Peste. Darthalia, siempre pensando en mí, decidió que yo me ocuparía de los prisioneros.|n|nCreo que ya es hora de montarles una fiesta a los granjeros. ¡Va a ser estupendo!|n|nColoca este barril contaminado en la alfombra de su cuarto. ¡Cerveza apestada para todos!', },
    {'Coloca el barril contaminado en la alfombra para los granjeros.', },
  },
  [525] = {
    'Más misterios',
    {'He descifrado la carta, pero no sé cómo interpretarla. ¿Y la tenían unos ladrones en las laderas de Alterac? Qué raro...|n|nLlévasela al magistrado de Costasur. Aunque la carta es críptica, su ciudad es la más cercana a Alterac; si se está cociendo algo, es mejor que lo sepa.', },
    {'Lleva la carta descifrada al magistrado Maleb a Costasur.', },
  },
  [526] = {
    'Lingotes Forjaluz',
    {'Has encontrado un lingote Forjaluz en el cofre, ¡pero no es suficiente para hacer nada decente!|n|nDeberías volver y buscar más. Quizás los múrlocs que rodean los restos del naufragio tengan más lingotes Forjaluz.', },
    {'Reúne 5 lingotes de Forjaluz y vuelve junto a Glorin Frenteacerada en Los Humedales.', },
  },
  [527] = {
    '[DEPRECATED]La batalla de Trabalomas',
    nil,
    {'Mata a 6 mozos de labranza de Trabalomas y 6 granjeros de Trabalomas, al granjero Ray y al granjero Getz e informa a Darthalia en Molino Tarren.', },
  },
  [528] = {
    '[DEPRECATED]La batalla de Trabalomas',
    {'El ataque a las granjas del norte tiene aterrados a los lugareños. Excelente.|n|nNuestros mortacechadores informan que los campesinos huyen a los campos del sur de Trabalomas. Esos necios creen que pueden escapar a su destino escondiéndose en el huerto.|n|nPero se equivocan, $N. Vuelve a Campos de Trabalomas y busca a los campesinos ocultos. Aniquílalos en el nombre de nuestra Dama Oscura.|n|nPuedes retirarte.', },
    {'Mata a 15 campesinos de Trabalomas e informa a Darthalia en Molino Tarren.', },
  },
  [529] = {
    '[DEPRECATED]La batalla de Trabalomas',
    {'Los humanos de Trabalomas han opuesto más resistencia de la esperada. Al parecer, el herrero del lugar está fabricando armas. Tenemos que interrumpir todo suministro.|n|nTu misión es ejecutar al herrero Verringtan. Elimina también a los aprendices. Y trae un envío de hierro de su almacén. Nos irá bien cuando terminemos con Trabalomas y pasemos a conquistar Costasur.', },
    {'Mata al herrero Verringtan y a 4 herreros aprendices de Trabalomas.|n|nRecupera un envío de hierro e informa a Darthalia en Molino Tarren.', },
  },
  [530] = {
    'La venganza de un esposo',
    {'Valdred, el que una vez fue mi mejor amigo, es el asesino de mi esposa. Aunque soy incapaz de llorar su muerte, sí que anhelo venganza. Si matas a Valdred y me traes sus manos malditas, te recompensaré.|n|nLa última información de que dispongo es que se encuentra en La Muralla de Cringris, al sur del Bosque de Argénteos, con intención de escapar al reino de Gilneas.', },
    {'Mata a Valdred Moray.|n|nLlévale sus manos a Raleigh Andrean, que está en Entrañas.', },
  },
  [531] = {
    'La venganza de Vyrin',
    {'¡Por la Luz! No puedes meter eso aquí, es antihigiénico, antiestético y... ¡y huele mal!|n|nLlévatelo, ¿quieres? ¡Ese trofeo sangriento no le interesa a nadie!', },
    {'Lleva la cabeza del viejo Tiznado a Vyrin Vientoveloz a la Cabaña del Errante.', },
  },
  [532] = {
    '[DEPRECATED]La batalla de Trabalomas',
    {'Trabalomas está en ruinas y creemos que a punto de caer. Pero debemos mantenernos firmes hasta erradicar a toda la chusma humana para toda la eternidad.|n|nLos humanos resisten y siguen luchando pese a sus abrumadoras pérdidas. Debemos eliminar a su líder, el magistrado Ladoquemado, además de a los consejeros. También debes acabar con su más preciado documento, la Declaración de Trabalomas. Y ya que estás, saquea el registro civil.', },
    {'Mata al magistrado Ladoquemado y a 4 consejeros de Trabalomas. Acaba con la Declaración de Trabalomas. Saquea el registro de Trabalomas. Después informa a Darthalia en Molino Tarren.', },
  },
  [533] = {
    '[DEPRECATED]Infiltración',
    {'Por fin empezamos a tener noticias acerca del paradero de Gol\'dir. Los humanos lo han llevado de un lado a otro, pero hemos centrado la búsqueda en el campamento de la Hermandad que está al norte de aquí.|n|n$N, tienes que ir y conseguir toda la información que puedas.', },
    {'Consigue información sobre el paradero de Gol\'dir\'s e informa a Krusk en Molino Tarren.', },
  },
  [535] = {
    nil,
    {'Urrg... Herido, agonizante y frente al enemigo.|n|nDe todos modos, seguro que me matarás, pero si me traes cerveza de Costasur, los de tu clase beben, ¿no?, te contaré lo que deseas saber.', },
    {'Llévale 1 jarra de cerveza de Costasur a Valik en el campamento de la Hermandad.', },
  },
  [536] = {
    '[DEPRECATED]Al lo largo de la costa',
    {'Me han transferido de la guardia de la Ciudad de Ventormenta a Costasur, un lugar que merecería ser abandonado, a juzgar por su aspecto. No me quito de encima el olor a puerto.|n|nPor no hablar de Rutagrana... Quiere que me encargue de los múrlocs. ¡Ja!|n|nApenas me animo a acercarme a esos pescados gigantescos de la Playa del Oeste. Te agradecería mucho que te ocuparas de ello en mi lugar.', },
    {'Mata a 10 cazamareas y 10 oráculos Rompeanca por orden del teniente Farren Orinelle de Costasur.', },
  },
  [537] = {
    '[DEPRECATED]Consejo oscuro',
    {'La carta fue escrita por un ser que responde al nombre de Nagaz, miembro del Despertar de Argus. No sé quiénes son, pero si están aliados con la Hermandad debemos considerarlos una amenaza.|n|nQuiero que localices a Nagaz y a los magos de la Sombra Argus mencionados en la carta. Localízalos y elimínalos.|n|nExplora las Tierras Altas, el bastión de la Hermandad. Está al norte de Strahnbrad.|n|nCon un poco de suerte, encontrarás a los enviados del Despertar de Argus allí.', },
    {'Mata a 4 magos de la Sombra Argus.|n|nLleva la cabeza de Nagaz al magistrado Maleb de Costasur.', },
  },
  [538] = {
    'Costasur',
    {'$N. Si no te molestan los viajes largos, tengo una tarea para ti, para ayudar a llenar la biblioteca de Ventormenta.|n|nEl viejo reino de Alterac cayó tras la Gran Guerra y tenía una gran colección de libros. Es una tragedia que la ciudad esté en ruinas, pero mucho más trágico es haber perdido todo su conocimiento. Debemos recuperar todo lo que podamos.|n|nCostasur es la ciudad más próxima a las Ruinas de Alterac. Vete allí y habla con el maestro cultural Dibbs. Podrá guiarte hasta las ruinas y sabe qué libros puedes encontrar allí.', },
    {'Habla con el maestro cultural Dibbs en Costasur.', },
  },
  [539] = {
    '[DEPRECATED]La batalla de Trabalomas',
    {'El Registro de Trabalomas indica que la Mina Azur se encuentra bajo el control de la Alianza. Esa mina es una de las principales fuentes de hierro de la armería de la Alianza.|n|nAunque hemos asestado un golpe mortal a Trabalomas, la Alianza sigue defendiendo la Mina Azur con entusiasmo.|n|nEstá al sur de Trabalomas. Ve y asesina al supervisor, un humano llamado Bonds. Elimina también a los mineros. Eso le enseñará a la Alianza.', },
    {'Mata al supervisor Bonds y 10 mineros de Trabalomas e informa a Darthalia en Molino Tarren.', },
  },
  [540] = {
    '[DEPRECATED]Proteger el conocimiento',
    {'Esos bestiales ogros viven en las ruinas de Alterac. Me estremezco al pensar en lo que estarán haciendo con los valiosos libros que quedaron allí. ¡Debes recuperar tantos como puedas!|n|nVe a las Ruinas de Alterac y busca los volúmenes que hayan robado. Tráeme todos los que puedas, pero hay un libro en especial que debes buscar: El Arma de Gri\'lek. En ese libro hay ciencia trol antigua que necesito; en las Ruinas de Alterac había un ejemplar intacto, el último del que se tiene noticia.', },
    {'Lleva 5 tomos y el libro de piel gastado que contiene El Arma de Gri\'lek al maestro cultural Dibbs a Costasur.', },
  },
  [541] = {
    '[DEPRECATED]La batalla de Trabalomas',
    {'¿Enanos ayudando a los humanos? Malditas sean esas pequeñas y sucias bestias.|n|nPondremos a prueba la solidez de esa supuesta Alianza. Veremos si esos medias piernas están tan ansiosos por ayudar a los humanos cuando hayan sufrido nuestra ira. Sabemos exactamente dónde se encuentra su fortaleza en este territorio.|n|nSe han instalado en un barracón llamado Dun Garok, al sureste de Trabalomas, junto a la Muralla de Thoradin. La misión final de esta batalla es asediar Dun Garok, $C. El capitán Ferrocolina, su líder, debe morir.', },
    {'Ve a Dun Garok y mata a 8 montaraces, 4 fusileros, 2 sacerdotes y al capitán Ferrocolina e informa a Darthalia en Molino Tarren.', },
  },
  [542] = {
    '[DEPRECATED]Regresa junto a Milton',
    {'Voy a dedicar cierto tiempo a estudiar El Arma de Gri\'lek, pero seguro que Milton espera con impaciencia los demás libros para incluirlos en la colección de Ventormenta.|n|nAquí tienes los libros que has traído de las Ruinas de Alterac, ya catalogados y empaquetados. Ve a Ventormenta y dáselos a Milton Gavilla; seguro que te lo agradecerá.', },
    {'Lleva los Tomos de Alterac a Milton Gavilla a Ventormenta.', },
  },
  [543] = {
    'La Tiara Perenolde',
    {'La Tiara Perenolde es una antigua reliquia familiar de los "nobles" Perenolde, la familia soberana de Alterac antes de que comenzara el declive del reino. Se dice que ha sido forjada por los maestros joyeros de Forjaz y que lleva engarzadas unas esmeraldas de gran calidad.|n|nCuando Alterac fue destruido, se perdió la Tiara, pero corren rumores de que un ogro mago, Grel\'borg el Avaro, encontró la Tiara y ahora vaga por las Ruinas de Alterac en busca de más tesoros.|n|nNos gustaría que recuperases la Tiara para nosotros.', },
    {'Recupera la Tiara Perenolde.', },
  },
  [544] = {
    '[DEPRECATED]Colarse en la cárcel',
    {'Había venido a Molino Tarren para estudiar, pero ahora debo solucionar una crisis. Verás, hace unos meses, cuatro Renegados huyeron de Entrañas. Dieron la espalda a su gente, pero lo peor es que robaron a la Dama Oscura.|n|nEntraron en una cámara de seguridad y robaron cuatro objetos que usaron nuestros boticarios en algunos proyectos. Sylvanas quiere recuperar esos objetos.|n|nLos ladrones huyeron de Entrañas a Dalaran y esos magos los pusieron en cuarentena en el Campo de Reclusión de Lordamere.', },
    {'Localiza a los traidores y recupera los objetos robados. Luego habla otra vez con el magus Vacuamirada en Molino Tarren.', },
  },
  [545] = {
    '[DEPRECATED]Las patrullas de Dalaran',
    {'Los magos de Dalaran construyeron una gran cúpula mágica alrededor del corazón de la ciudad. Hay quien dice que fue un medio de protección en estos tiempos violentos, y quien cree que los magos buscaban soledad para estudiar y conspirar.|n|nLa razón no me importa. Lo que me importa es que entre las ruinas de los alrededores de su ciudad puede haber muchos tesoros mágicos.|n|nPero los magos patrullan la zona con sus esclavos elementales.|n|nTienes que eliminarlos. Vuelve cuando hayas reducido sus filas.', },
    {'Mata a 6 invocadores de Dalaran y 12 esclavos elementales. Luego vuelve a hablar con el magus Vacuamirada en Molino Tarren.', },
  },
  [546] = {
    '[DEPRECATED]Recuerdos de muerte',
    {'Oí que has sido reclutado por Darthalia para luchar contra los humanos de Trabalomas. Estoy celoso.|n|nMientras tú te diviertes matando humanos, saqueando el pueblo y aterrorizando a gente inocente... yo estoy aquí clavado haciendo guardia en el Molino Tarren.|n|n¿No podrías apiadarte de un viejo Guardia de la Muerte como yo? Verás, colecciono calaveras humanas. Y tú pasarás algún tiempo combatiendo contra humanos. Reúne 30 calaveras mientras combates tu larga batalla y tráemelas. Haré que te merezca la pena.', },
    {'El Guardia de la Muerte Samsa de Molino Tarren quiere 30 calaveras humanas de Trabalomas.', },
  },
  [547] = {
    '[DEPRECATED]La espada de Humbert',
    {'La suma ejecutora Darthalia me envió a vigilar Dun Garok desde cierta distancia. Acampé donde no pudieran verme. A la mañana siguiente fui a buscar leña para el fuego.|n|nY al volver descubrí que me habían robado el equipamiento.|n|nParece que unos exploradores enanos de Dun Garok pasaron por allí y se lo llevaron todo. ¡Necesito la espada! Te agradecería mucho que me la trajeras. Aquí hay tantos enanos que será difícil descubrir al ladrón.', },
    {'Recoge la espada del Guardia de la Muerte Humbert en Dun Garok y llévasela a Molino Tarren.', },
  },
  [548] = {
    '[DEPRECATED]&lt;NYI&gt; &lt;TXT&gt; Colgante de sangrita',
    nil,
    nil,
  },
  [549] = {
    '[DEPRECATED]SE BUSCA: Personal de la Hermandad',
    {'Por orden de la Lady Sylvanas, se decreta la pena de muerte para todos los miembros de la organización conocida como la Hermandad. Aquellos que sean tomados como prisioneros serán ejecutados. Se sabe que se están reuniendo en las ruinas del Castillo de Durnholde, al sureste de Molino Tarren.|n|nSe ofrece una generosa recompensa a quien pueda dar cuenta de sus actividades a la suma ejecutora Darthalia.', },
    {'Mata a 10 pícaros y 10 veladores de la Hermandad. La suma ejecutora Darthalia te dará tu recompensa en Molino Tarren.', },
  },
  [550] = {
    '[DEPRECATED]La batalla de Trabalomas',
    {'He redactado una mención de honor describiendo tu heroica actitud en combate para que el alto mando reconozca tu valor y entrega en la Batalla de Trabalomas.|n|nLleva esta mención lacrada a Bragor Puñosangre; está en Entrañas. Ve con la frente muy alta, $C.', },
    {'Lleva la mención de honor lacrada de Darthalia a Bragor Puñosangre, que está en Entrañas.', },
  },
  [551] = {
    '[DEPRECATED] El papiro encantado',
    {'Este papiro está encantado con un hechizo que lo hace indescifrable. Aunque se puede leer una palabra en la parte de arriba:|n|nNagaz$', },
    {'Lleva el pergamino encantado al maestro cultural Dibbs a Costasur en las Laderas de Trabalomas.', },
  },
  [552] = {
    '[DEPRECATED]La venganza de Helcular',
    {'El maestro Helcular casi había completado su transformación en exánime cuando una multitud airada descubrió su refugio ritual en las colinas y lo asesinó brutalmente. Para empeorar las cosas, lo enterraron en el cementerio de Costasur.|n|nTamaño desprecio por tan gran mago es inaceptable. Yo, su aprendiz, me aseguraré de que el fuego de la venganza arrase Costasur.|n|nNecesitamos la Vara de Helcular. Los yeti invadieron el refugio ritual. Seguro que una de esas bestias tiene la vara.', },
    {'Róbale la Vara de Helcular a los yetis y llévasela al novicio Thaivand a Molino Tarren.', },
  },
  [553] = {
    '[DEPRECATED]La venganza de Helcular',
    {'Toma la Vara de Helcular; la vas a necesitar.|n|nHelcular diseñó tres piras ceremoniales como parte de su hechizo más potente. La Llama de Azel y la Llama de Veraz reposan en las cuevas de la ladera. La Llama de Uzel está en una gruta situada sobre las cuevas, hacia el norte.|n|nDebes cargar la Vara de Helcular en estas tres llamas. Cuando hayas completado el ritual, lleva la vara a la tumba de Helcular en Costasur, la muy bien protegida ciudad humana del sur. ¡Nos vengaremos!', },
    {'Carga la Vara de Helcular con el poder de la Llama de Azel, la Llama de Veraz y la Llama de Uzel.|n|nLuego llévala a la tumba de Helcular en Costasur.', },
  },
  [554] = {
    '[DEPRECATED] La descodificación de Pico Tormenta',
    {'El prospector Pico Tormenta es un maestro de la descodificación. Llévale el papiro que has encontrado; con un poco de suerte, podrá descifrarlo. Está estudiando en la oficina central de prospección, en Forjaz.|n|nDile que has hablado conmigo; últimamente le mando bastante trabajo.', },
    {'Lleva el papiro codificado al prospector Pico Tormenta a Forjaz.', },
  },
  [555] = {
    '[DEPRECATED]Sopa de tortuga reconfortante',
    {'¡Lo que más vas a apreciar en Costasur es que tenemos la mejor cocina al norte de Ventormenta!|n|nPor ejemplo, mi sopa de tortuga. Sé de gente que ha venido incluso de Villa Oscura solo para probarla. Por cierto, hace mucho que no la hago. Antes iba pasado Dalaran hasta el Lago Lordamere para cazar quijafortes, pero ahora es demasiado peligroso. ¡Si me traes carne de tortuga de la de los quijafortes del norte te preparo una sopa!', },
    {'Lleva 10 piezas de carne de tortuga y al chef Jessen a Costasur.', },
  },
  [556] = {
    '[DEPRECATED]Muestras de piedra',
    {'Los magos de Dalaran tienen una notable facilidad para relacionarse con elementales, que son poderosas criaturas de otras dimensiones. Los magos controlan a los elementales con talismanes mágicos. El mago Vacuamirada quiere analizar estos talismanes.|n|nVe a buscarlos al territorio de los magos de Dalaran, al oeste de Trabalomas.|n|nCualquier ciudadano de Dalaran puede llevar uno, pero te sugiero que busques en el campo de reclusión. Es más seguro que ir a Dalaran.', },
    {'Lleva 10 muestras de piedra desgastada al vigilante Bel\'varil de Molino Tarren.', },
  },
  [557] = {
    '[DEPRECATED]Brazales de vínculo',
    {'El mago está ocupado estudiando las muestras de piedra que has traído, pero pronto querrá ver sus opuestos: los brazales de vínculo. Cuando un elemental los lleva, queda ligado al servicio del mago.|n|nCaza elementales en las ruinas de Dalaran y recoge sus brazales de vínculo de Tierra para ganarte el favor del mago.', },
    {'Lleva 4 brazales de vínculo de Tierra al vigilante Bel\'varil de Molino Tarren.', },
  },
  [558] = {
    'Autógrafo de Jaina',
    {'Dicen que Lady Jaina Valiente de Theramore es una de las mayores heroínas de la Alianza de todos los tiempos. ¡Cuando sea mayor también seré un héroe de la Alianza!|n|n¿Conoces a Jaina, $N? ¿Me puedes hacer un favor? ¿Me conseguirás su autógrafo? No me atrevo a pedírselo, seguramente estará muy ocupada para alguien como yo... ¡pero tú! ¡Tú eres $Gun aventurero:una aventurera; como ella! ¡Seguro que te dará su autógrafo!|n|n¡¡Por favor!!', },
    {'Viaja a Theramore para intentar conseguir un autógrafo de Lady Jaina Valiente para tu pupilo.', },
  },
  [559] = {
    '[DEPRECATED]La prueba de Farren',
    {'¿Qué te parece, $N? A Rutagrana no le basta con todos los múrlocs que hemos matado. Sí, hemos, tú también has tenido algo que ver. Ahora quiere que le traiga pruebas, que me dedique a rebanar cabezas de múrloc para que las inspeccione.', },
    {'Recoge 10 cabezas de múrloc en la Playa del Oeste por orden del teniente Farren Orinelle de Costasur.', },
  },
  [560] = {
    '[DEPRECATED]La prueba de Farren',
    {'Verás, $N, a mí esto de las cabezas me pone mal cuerpo... Ya que le has cogido el gusto a la cosa, ¿te importaría ir a llevárselas a Rutagrana por mí?', },
    {'Entrega las cabezas de múrloc al alguacil Rutagrana de Costasur.', },
  },
  [561] = {
    '[DEPRECATED]La prueba de Farren',
    {'Informa al teniente Orinelle que debe concentrarse en los nagas que han infestado la Playa del Este. Dile que me informe personalmente del resultado de la operación.', },
    {'Habla con el teniente Farren Orinelle en Costasur.', },
  },
  [562] = {
    '[DEPRECATED]Cambio de destino',
    {'Mi antiguo mentor de la guardia de la Ciudad de Ventormenta me dice que el alto mando de la Alianza está preocupado por la amenaza de los nagas. Según él, quien pueda ayudar a este respecto recibirá un ascenso, o al menos un cambio de destino.|n|nSolo hay un problema... No puedo enfrentarme a los nagas, $N. Puedo intervenir en una pelea de borrachos o reducir a un indigente belicoso, pero los nagas me superan. ¡$N, tienes que ayudarme!', },
    {'Mata a 10 cazacostas y 10 sirenas Espinadaga por orden del teniente Farren Orinelle de Costasur.', },
  },
  [563] = {
    '[DEPRECATED]Nueva asignación',
    {'No debería ser un problema conseguir que vea mi informe. El nuevo capitán de la guardia, el mayor Samuelson, fue mi mentor cuando estuve destinado en Ventormenta. Eso debería ser excusa suficiente para que me traslade a la ciudad de nuevo. Pero necesitaré que le lleves mi informe... no quiero que Rutagrana se entere de nada.', },
    {'Entrega el informe de Farren al mayor Samuelson en el Castillo de Ventormenta.', },
  },
  [564] = {
    '[DEPRECATED]Una amenaza costosa',
    {'Nada me duele más que perder estos hermosos caballos. Y hemos perdido unos cuantos entre los puñeteros no-muertos, la maldita Hermandad y toda la demás chusma que corre por aquí.|n|nPero te juro por mi abuelo que la amenaza más grave para los caballos son los leones de montaña de Alterac. ¡Siempre bajan de la montaña y me complican la vida!|n|n¿Te apetece una aventura? ¡Pues ve y ocúpate de ellos!', },
    {'Darren Malavista de Costasur quiere que mates 8 leones de montaña y 10 leones de montaña descomunales.', },
  },
  [565] = {
    '[DEPRECATED]Capa de piel de yeti de Bartolo',
    {'Yo, el gran Bartolo, te haré una de mis capas de piel de yeti, admiradas por toda la Alianza.|n|nTe desafío a recorrer el mundo en busca de una capa mejor. ¿Cómo dices, $R? "¡Bartolo, no hay una capa mejor!" Sí, sí. Ya lo había oído antes.|n|nBartolo necesita una madeja de lana, una capa de montañero hecha por un buen peletero, hilo refinado y, naturalmente, piel de yeti. ¡Tráeme todo eso y te haré una capa magnífica!', },
    {'Lleva una madeja de lana, una capa de montañero, hilo refinado y 10 trozos de piel de yeti a Bartolo Ginsetti a Costasur.', },
  },
  [566] = {
    '[DEPRECATED]SE BUSCA: Barón Vardus',
    {'Por orden de la suma ejecutora Darthalia, se busca al humano conocido como el Barón Vardus por crímenes contra los Renegados. Vardus es un miembro dirigente de la organización conocida como la Hermandad.|n|nFue visto por última vez en las Tierras Altas de las Montañas de Alterac, al norte de Molino Tarren.|n|nSe halla bajo pena de muerte. Se ofrece recompensa a quien presente una prueba de su muerte a la suma ejecutora Darthalia.', },
    {'Mata al Barón Vardus y entrega su cabeza a la suma ejecutora Darthalia en Molino Tarren.', },
  },
  [567] = {
    '[DEPRECATED]¡Peligrosos!',
    {'¡Atención!|n|nLos siguientes humanos de Trabalomas son peligrosos. La suma ejecutora Darthalia ha designado una recompensa por su captura:|n|nFuncionario Horracio Corzalbal. Se busca por el asesinato del Guardia de la Muerte Toma.|n|nCiudadano Wilkes. Se busca por el asesinato del boticario Eli.|n|nMinero Hackett. Se busca por el asesinato del mortacechador Fry.|n|nGranjera Kalaba. Se busca por el bloqueo de suministros de Entrañas.|n|nTodos estos enemigos se encuentran fugados y su captura se hará difícil. Se recompensará a quien pueda certificar su muerte.', },
    {'La suma ejecutora Darthalia de Molino Tarren ofrece recompensa por el funcionario Horraceio Corzalbal, el ciudadano Wilkes, el minero Hackett y la granjera Kalaba.', },
  },
  [568] = {
    'La defensa de Grom\'gol',
    {'¡Throm\'ka, $C!|n|nLlegas a tiempo a Grom\'gol. Como Comandante del campamento base del Jefe de Guerra aquí, en la jungla, he jurado encargarme de la seguridad de todos los miembros de la Horda. Nuestra misión de proporcionar una cadena de suministros segura hasta Rocal se ha visto obstaculizada por algunos de los habitantes locales.|n|nTe pongo al cargo de disminuir la población de raptores en las afueras de Grom\'gol. Cuando hayas conseguido un avance significativo, vuelve a informarme y te reasignaré.', },
    {'El comandante Aggro\'gosh del Campamento Grom\'gol, quiere que mates 15 raptores colazote.', },
  },
  [569] = {
    'La defensa de Grom\'gol',
    {'Cuando llegamos por primera vez a esta jungla, no pretendíamos tener que luchar con las tribus locales. Nuestra primera prioridad es enviar suministros a Rocal. Pero han surgido complicaciones. Una banda de ogros ha ocupado las Ruinas de Mizjah al sureste de Grom\'gol. A pesar de las advertencias, siguen preparando emboscadas a nuestras caravanas de suministros.|n|nTe pongo al cargo de tratar con esos ogros tan poco cooperativos.|n|nVete a las Ruinas e intenta expulsarlos de la zona. Al menos, con esto les mandaremos un firme mensaje.', },
    {'El comandante Aggro\'gosh del Campamento Grom\'gol, quiere que mates 10 toscos ogros y 5 médicos brujos ogros.', },
  },
  [570] = {
    'El encantamiento de Mok\'thardin',
    {'La Horda tiene que darse cuenta del poder de la magia de la jungla y, después, utilizarlo. Hasta ahora, mis rituales han tenido éxito. Puedo lanzar encantamientos muy poderosos. Para ti, valiente $C, crearé un objeto muy especial.|n|nTráeme algunas garras de panteras Faucesombría junto con un colmillo de tigresa. No valdrá cualquier colmillo. Debe estar en perfecto estado.|n|nLas bestias moran en la jungla, pero encontrarás algunas por aquí cerca, justo al otro lado del río que va desde las Ruinas de Mizjah hasta el sureste.', },
    {'El clarividente Mok\'thardin del Campamento Grom\'gol, quiere 8 garras Faucesombría y un colmillo de tigresa prístino.', },
  },
  [571] = {
    'El encantamiento de Mok\'thardin',
    {'Lo que necesito ahora, es bastante difícil de conseguir.|n|nPara guardar las plumas, las zarpas y el colmillo inmaculado, necesito una cadena mágica. Solo servirá un tendón de gorila mayor.|n|nEl único lugar donde podrás encontrar uno es en un gorila Velo de Bruma anciano. Suelen ir a por comida al este de la Bahía del Botín.|n|nEl tendón debe ser perfecto. Quizás necesites usar algunas de tus habilidades para encontrar exactamente lo que necesito, pero merecerá la pena.', },
    {'Lleva un tendón de gorila mayor al clarividente Mok\'thardin en Grom\'gol.', },
  },
  [572] = {
    'El encantamiento de Mok\'thardin',
    {'Los objetos que has conseguido de las bestias felinas del Valle son solo el primer requisito para un poderoso objeto encantado. Estas joyas de la selva combinadas con mi ritual chamanístico, te proporcionarán una herramienta muy útil para ayudar a la Horda y al Jefe de Guerra.|n|nPero ahora debes conseguirme Plumas de acechadores de la selva. Tradicionalmente, las bestias llevan las plumas en sus brazaletes. Encontrarás una tribu de raptores directamente al sur de Grom\'gol, no muy lejos de La Gran Arena.', },
    {'Lleva 10 plumas de acechadores de la selva al clarividente Mok\'thardin en el Campamento Grom\'gol.', },
  },
  [573] = {
    'El encantamiento de Mok\'thardin',
    {'Necesito un componente más para completar el encantamiento.|n|nAl sur, hacia la costa oeste, por encima de los riscos, hay un manantial sagrado. Este manantial es el sujeto de un gran conflicto entre eruditos religiosos y místicos. Todas las razas de Azeroth afirman que las aguas del manantial se hicieron divinas para su gente.|n|nMi última petición: tráeme agua de manantial sagrado. Ten cuidado. Una expedición de exploradores naga ha avanzado hacia el manantial. Tendrás que encargarte de ellos.', },
    {'El clarividente Mok\'thardin de Grom\'gol necesita agua de manantial sagrado. También quiere que mates 10 expedicionarios naga.', },
  },
  [574] = {
    'Fuerzas especiales',
    {'Ahora que hemos conseguido reducir algunas de sus tropas regulares, debes enfrentarte a las tropas de élite. Cuando no están fuera matando a nuestros soldados rebeldes, se retiran a las profundidades de la parte trasera de la Base de Kurzen, a una cueva a la que llaman Las Reservas.|n|nConozco personalmente a muchas de las tropas de Kurzen y sé que son habilidosas, leales y crueles. La tarea que tienes ante ti no es fácil, $N.|n|nCuando las derrotes, informa al teniente Doren, mi oficial en jefe. Quiere recibir tu informe de primera mano.', },
    {'Mata 10 comandos de Kurzen y 6 reductores de cabezas de Kurzen.|n|nPreséntate ante el teniente Doren en el Asentamiento Rebelde.', },
  },
  [575] = {
    'La oferta y la demanda',
    {'"El mejor artesano peletero de los Mares del Sur, del mundo antiguo y del mundo nuevo." ¡Así es como me llaman! ¡A mí! ¡Drizzlik! El mejor... ejem. Bueno.|n|nMis objetos de cuero se conocen en el mundo entero como los más exquisitos, ¡la elección de los entendidos!|n|nAcabo de recibir un pedido del director Riddlevox del Gremio de Manitas, de una docena de borceguíes. El producto que más vendemos.|n|nPara el molde básico, necesitaré pieles de crocolisco de los crocoliscos que están en el río en el Norte de la Vega de Tuercespina.', },
    {'Lleva 2 pieles grandes de crocoliscos fluviales a Drizzlik en la Bahía del Botín.', },
  },
  [576] = {
    '¡Ojo!',
    {'¡Alto! ¿Quién va?|n|nAaah, no soy na sin mi ojo encantao especial. ¡De entrada ya fue bah\'tante malo perdel mi propio ojo en combate! Pero, por un golpe de sueh\'te, atracamo en Menethil y un zahorí viajante encantó un ojo especial de cristal para que pudiera ver de nuevo.|n|nAyel por la noche uno Bucaneros Velasangre me atacaron cuando salía. ¡Y cogieron mi ojo! Parece ser que esos tipos han conseguio llegal a la Bahía del Botín.|n|n¿Quieres ayudal a un viejo lobo de mar a recuperal su ojo?', },
    {'Dizzy el Tuerto, en la Bahía del Botín, quiere que recuperes su ojo de los Bucaneros Velasangre.', },
  },
  [577] = {
    'Hay que ensamblar',
    {'Bien, ya tengo el molde básico y todo va bien, pero con las pieles que has traído no tendré suficiente para las capas interiores.|n|n"¿Qué vamos a hacer, Drizzlik?" Sin duda esa es la pregunta que ibas a hacer y, en fin, qué suerte que estés hablando con Drizzlik, porque te va a decir lo que vamos a hacer.|n|nLas capas interiores no se ven, así que podemos coger unas pieles más gruesas y baratas de los crocoliscos que están por el Lago Nazferiti.', },
    {'Lleva 5 pieles de crocoliscos Quijaforte a Drizzlik en la Bahía del Botín.', },
  },
  [578] = {
    'La piedra de las mareas',
    {'Si realmente hay un mago goblin y elementales de agua en esa isla, ¡la Piedra de las Mareas podría ser mía!|n|nQuiero que encuentres esa isla encantada... descubre lo que está pasando. Oh, y si quieres saber algo más sobre la Piedra de las Mareas, lleva este manuscrito a la Biblioteca de Ventormenta, deberían poder encontrarte una copia del libro donde me encontré la leyenda por primera vez.|n|n¿Podría ser que Gazban realmente descubriese la Piedra...?', },
    {'Encuentra la isla encantada para el Barón Revilgaz en la Bahía del Botín.', },
  },
  [579] = {
    'La biblioteca de Ventormenta',
    nil,
    nil,
  },
  [580] = {
    'El grog de Whiskey el Delgado',
    {'Estábamos ajustando la braza mayor y soplaba fuerte en Los Acantilados Dominantes, veíamos las Tierras del Interior a distancia. Creí que el mar iba a tragarnos enteros.|n|nEl viejo Slim lo sabe todo sobre el coraje líquido. El Capitán tenía una caja de oporto Pupellyverbos que le encargamos a un corsario que iba a Ventormenta.|n|nAsí que cuando cayó la tormenta de las Tierras del Interior, trinqué el grog. Una gran ola y todas las botellas cayeron por la borda. El capitán va a darme una buena paliza si no me ayudas a recuperarlas.', },
    {'Whiskey el Delgado, en la Bahía del Botín, quiere que le lleves las botellas de oporto Pupellyverbos que perdió.', },
  },
  [581] = {
    'Caza para Yenniku',
    {'Es su fin, sí. El fin de Yenniku, el hijo menor de mi jefe. Como es tradición entre nuestra gente, fue entregao a los trols Gurubashi Trolls de Zul\'Gurub pero, deh\'pués de que mi tribu, los Lanza Negra, pa\'htiese con el orco Thrall, le perdimos el rastro al pobre Yenniku. Me enviaron de la distante Orgrimmar, de vuelta a Tuercespina, para buscá al hijo de mi jefe.|n|nY creo que la tribu Sangrapellejo lo tiene.|n|nSi quieres ayudarme, da caza a los Sangrapellejo. Los encontrarás al norte. Reúne sus colmillos y tráemelos.', },
    {'Lleva 9 colmillos Sangrapellejo a Nimboya en el Campamento Grom\'gol.', },
  },
  [582] = {
    'Caza cabezas',
    {'Hemos de descubrí si Yenniku eh\'tá muerto.|n|nMata a los rebanacabezas Sangrapellejo y arrebátales sus cabezas reducidas. Tienes que reuní muchas, muchas cabezas y yo las inspeccionaré para vé que la de Yenniku no eh\'té entre ellas.|n|nY, si Yenniku murió a manos de los Sangrapellejo, ¡una maldición de 600 años caerá sobre el eh\'píritu de Gan\'zulah, su jefe!|n|nVenga, $N. Encontrarás muchos rebanacabezas en la Ruinas Zuuldaia y Zul\'Kunda, a lo largo de la costa del norte.', },
    {'Lleva 20 cabezas reducidas a Nimboya en el Campamento Grom\'gol.', },
  },
  [583] = {
    'Bienvenido a la jungla',
    {'¡$GBienvenido:Bienvenida; a Tuercespina!|n|nPor si no lo sabes, aquel enano de allí es el hijo del mismísimo Hemet Nesingwary, famoso héroe de guerra de la Alianza y maestro de la caza mayor. Igual que a su padre, no le gusta tener a desconocidos en el campamento, pero tú tienes cara de haber guerreado bastante, $C.|n|nHabla con él; ha heredado el talento cazador de su padre, así que podrá darte buenos consejos.', },
    {'Habla con Hemet Nesingwary Jr.', },
  },
  [584] = {
    'Las cabezas de los Sangrapellejo',
    {'Doy gracias a la Gran serpiente de que la cabeza de Yenniku no eh\'tuviese entre las que me has traído. Pero eso no nos facilita el encontrarlo.|n|nHemos de descubrir la verdad y me temo que solo el jefe de los Sangrapellejo y su médico brujo lo saben. Son los enemigos de la tribu Lanza Negra y no van a coloborá, ¡así que tenemos que sacá la verdad de sus labios muertos!|n|nTráeme las cabezas de Gan\'zulah y Nezzliok el Temible y colócalas en esta caldera.|n|nEstán en las profundidades de Zul\'Kunda. Trae sus cabezas... Las haremos hablá.', },
    {'Lleva la cabeza de Gan\'zulah y la cabeza de Nezzliok a la caldera en ebullición en el Campamento Grom\'gol.', },
  },
  [585] = {
    'Hablando con Nezzliok',
    {'<La cabeza de Nezzliok habla.>|n|nEs cieh\'to. Sé dónde se llevaron al niño de los Lanza Negra. Me has vencío y has sometido mi eh\'píritu, ¡pero no diré nada si no me apaciguas!|n|nLos Sangrapellejo eh\'tán en guerra con los Machacacráneos. Para obtené mi favor, roba 3 cráneos trofeo a los Machacacráneos y colócalos aquí con nosotros, pa\' que mi eh\'píritu tenga esclavos en el Vacío Abisal. Uno de los cráneos debe procedé de su pila de trofeos en Balia\'mah, el otro debe vení de Ziata\'jai y el último de Zul\'Mamwe.', },
    {'Lleva un trofeo de Balia\'mah, un trofeo de Ziata\'jai y un trofeo de Zul\'Mamwe a la caldera en ebullición del Campamento Grom\'gol.', },
  },
  [586] = {
    'Hablando con Gan\'zulah',
    {'<La cabeza de Gan\'zulah habla.>|n|n¡Yo te maldigo! ¡Y maldigo a tus ancestros!|n|nSolo la sangre y la venganza podrán templar mi ira, así que si eso es lo que deseas... Haz esto:|n|nlánzate de pleno al corazón de los Machacacráneos, al este. Mata a los más fieros y, si sobrevives, enfréntate a su jefe, Ana\'thek el Cruel. ¡Ja! Tráeme su armadura despedazada si puedes.|n|nQue te desgarre tus miembros y deje que tu carne se pudra y sea comida de buitres.', },
    {'Mata 8 cazadores Machacacráneos, 6 rebanacabezas Machacacráneos y 4 rabiosos Machacacráneos.|n|nLleva la armadura de Ana\'thek rota a la caldera en ebullición del Campamento Grom\'gol.', },
  },
  [587] = {
    'Tabaco rapé',
    {'Ah, la vida del mar. No diré que es una buena vida, pero es mi vida.|n|nCuando llego a puet-to me guh\'ta buscal una buena botella de grog y rapé de buena calidad. Unas costumbre muy mala, ¿pero qué es un pirata sin sus vicio, eh?|n|nAsí que te puede imaginal cómo me sentí cuando me enteré de que el herborih\'ta de la ciudad se había ido y lo había vendio to. Parece ser que esos maldito asaltantes Velasangre secuestraron su cargamento.|n|nApuesto a que $Gun audaz:una audaz:c; $C como tú podría convencerlos para compartil las mercancías, ¿eh?', },
    {'Deeg, en la Bahía del Botín, quiere que le lleves 15 pizcas de tabaco.', },
  },
  [588] = {
    'El destino de Yenniku',
    {'<Nezzliok habla.>|n|nNos has complacio a mí y a mi jefe, así que te contaré aquello que deseas descubrí...|n|nEl joven Yenniku eh\'tá perdio para su clan.|n|nSe lo llevó el médico brujo Zanzil el Desterrado. Ahora Zanzil lo controla en cuerpo y alma, y solo la magia más poderosa podría liberarlo.|n|nUna magia que tú no tienes, $C.|n|nPuede que tus aliados Lanza Negra en Bambala, hacia el este, puedan ofrece\'hte una posibilidad para la salvación de Yenniku. Pero lo dudo.', },
    {'Habla con Kin\'weelay.', },
  },
  [589] = {
    'Los cristales canto',
    {'Las leyendas hablan de una joya oculta en las profundidades del corazón de Tuercespina. Llamamos a esa joya el Ojo de la mente, y tiene grandes poderes. Si consigues el Ojo, quizás podamos usarlo para traer de la oscuridad al joven Yenniku.|n|nPreguntaré a los espíritus de la jungla cómo encontrar el Ojo de la mente. Mientras lo hago, ve a la Mina de Cristal, al sureste de aquí y recoge fragmentos azul pulsante de los basiliscos Quijahierro. Los fragmentos son poco comunes, pero necesitamos su magia para conseguir dominar el Ojo de la mente.', },
    {'Lleva 3 fragmentos azul pulsante a Kin\'weelay en el Campamento Grom\'gol.', },
  },
  [590] = {
    'Un trato de pícaro',
    {'¿Qué?|n|n¡¿Qué?!|n|n¿Quieres dinero? Yo no te debo dinero.|n|n¿Una carta? ¿Qué carta? Ah, estás buscando pelea. Muy bien, colega. ¡Vamos allá! Que te debo dinero...', },
    {'Derrota a Calvin Montesco en Camposanto.', },
  },
  [591] = {
    'El Ojo de la mente',
    {'El Ojo de la mente eh\'tá en posesión de un ogro mago, al este de aquí, en las profundidades del Túmulo Ogro Mosh\'Ogg. Se llama Mai\'Zoth. Le conozco de cuando los Lanza Negra vivían en Tuercespina, es feroz y su magia es poderosa.|n|nY, si tiene el Ojo de la mente, entonces su magia será más fuerte todavía.|n|nDebes enfrentarte a Mai\'Zoth y conseguí el Ojo de la mente. Se trata de una misión peligrosa, pero es la única opo\'htunidad que tenemos de salvá a Yenniku.', },
    {'Lleva el Ojo de la mente a Kin\'weelay en el Campamento Grom\'gol.', },
  },
  [592] = {
    'Salvar a Yenniku',
    {'He convertido el Ojo de la mente en una gema de alma. Tiene un doble propósito: debes usarla para aturdir a Yenniku y, cuando lo hayas hecho, colócala sobre su cabeza para atrapar su alma.|n|nA continuación, lleva la gema a Nimboya.|n|nYenniku vive con Zanzil el Desterrado, en las Ruinas de Aboraz, junto a La Costa de Cristal, en El Cabo de Tuercespina.', },
    {'Lleva la gema de alma llena a Nimboya.', },
  },
  [593] = {
    'Gema de alma',
    nil,
    nil,
  },
  [594] = {
    'Mensaje en una botella',
    {'La nota dice, con buena caligrafía:|n|nA quien pueda ayudarme.|n|nPor favor, necesito ayuda urgentemente. Un gran Cieloleno me tiene cautivo en una isla en los Mares del Sur.|n|nLas estrellas de la noche son extrañas y los árboles de la jungla oscurecen el firmamento pero, en los días más claros, puedo ver la Orilla Salvaje al noroeste y lo que parecen grandes barcos cargueros al suroeste.|n|nTe lo suplico, ven a rescatarme.', },
    {'Encuentra al autor del mensaje en la botella.', },
  },
  [595] = {
    'Bucaneros Velasangre',
    {'Parece que tienes muchas ganas de ponerte a trabajar, colega. No tengo muy claro por qué $Gun:una; $R $C $Gmarinero:marinera; de agua dulce, se ofrece a ayudar a los Asaltantes Aguasnegras, pero no voy a rechazar tu ayuda.|n|nNuestro barco acaba de atracar aquí, en la Bahía del Botín, y corren rumores de que nuestros rivales, esos malditos y asquerosos Bucaneros Velasangre, están por todo el sur de Tuercespina.|n|nTodos los hombres están muy ocupados dándole al grog y buscando damiselas. Lo que necesitamos es un explorador.|n|nExplora la cala que está justo al norte de la Bahía del Botín en La Costa Salvaje, a ver lo que descubres.', },
    {'El contramaestre Crazz quiere que eches un vistazo a la cala norte de la Bahía del Botín.', },
  },
  [596] = {
    'Collares de huesos sangrientos',
    {'Me enviaron a Grom\'gol para ayudar a Nimboya en su misión, pero... yo también tengo razones para estar aquí.|n|nLa tribu Sangrapellejo es enemiga de mi tribu. Conseguir trofeos de nuestros enemigos nos da poder sobre ellos. Podrías ayudar a nuestra tribu dando caza a nuestros enemigos.|n|nViven al norte. Mata trols Sangrapellejo y coge sus collares de huesos sangrientos. Consigue muchos y tendrás una gran recompensa.', },
    {'Lleva 25 collares de huesos sangrientos a Kin\'weelay en el Campamento Grom\'gol.', },
  },
  [597] = {
    'Bucaneros Velasangre',
    {'En el mapa, la Bahía del Botín aparece marcada con una "X" roja, dibujada exactamente en el lugar donde estás ahora.|n|nEl texto lleno de garabatos dice:|n|n"Debéis asegurar un campamento en esta ubicación y mantener la calma. Esperad la señal del puesto de mando del sur antes de atacar. Si alguien se aproxima, matadle."', },
    {'Informa sobre tus descubrimientos al contramaestre Crazz en la Bahía del Botín.', },
  },
  [598] = {
    'Collar de hueso partido',
    {'Ahora que has conseguido traerme trofeos de los Sangrapellejos, tengo otra misión para ti. La tribu de trols Machacacráneos vive al sureste y, durante años, hemos luchado con ellos. Si bien los Lanza Negra ya no estamos asentados en Tuercespina, estamos atados a nuestro conflicto con los Machacacráneos.|n|nVete a por ellos. Consigue sus collares de hueso partidos y vuelve a verme. Ayúdanos en nuestra guerra y conseguirás la amistad de los Lanza Negra.', },
    {'Lleva 25 collares de hueso partidos a Kin\'weelay en el Campamento Grom\'gol.', },
  },
  [599] = {
    'Bucaneros Velasangre',
    {'¡Voto a bríos! ¿Así que los Bucaneros Velasangre están planeando atacar la Bahía del Botín? ¡No me puedo creer lo de esos bribones! La Bahía del Botín siempre estará dominada por los Asaltantes Aguasnegras.|n|nEsto es más grande de lo que yo había pensado. Informa al maestro de flota Cuernomarino inmediatamente. Ese viejo lobo de mar está por la ciudad, en alguna parte...', },
    {'Informa del ataque planeado de los Velasangre al maestro de flota Cuernomarino.', },
  },
  [600] = {
    'La minería de Ventura y Cía.',
    {'Ventura y Cía. está llevando varias operaciones en Tuercespina que priva a los duros trabajadores goblins, como yo, de conseguir un dinero honrado. ¡Por favor, tienes que ayudarme!|n|nVentura y Cía. está excavando cerca de la Mina de Cristal, al norte. No pueden entrar en la Mina debido a los basiliscos, pero consiguen extraer cristales canto de las colinas de alrededor.|n|nCoge los cristales y demuéstrales que no son los amos de la jungla.|n|nY... mmm... ¡tráeme esos cristales como prueba!', },
    {'Lleva 10 cristales canto azules a Loquillo Pinchabujas en la Bahía del Botín.', },
  },
  [601] = {
    'Elementales de agua',
    {'Sin duda, Gazban, el mago goblin que se rumorea que ha descubierto la Piedra de las Mareas, invocó a los elementales de agua. Como quizás sepas, la Piedra de las Mareas maldice a su portador, provocando que entre y salga del plano existencial...|n|nQuizás podamos encontrar la forma de contraatacar la maldición. Podemos conseguir que un mago de Dalaran analice el residuo mágico de uno de los brazales de un elemental de agua. Necesito que vuelvas a la isla y consigas algunos especímenes.', },
    {'Consigue 6 brazales de elementales de agua para el Barón Revilgaz en la Bahía del Botín.', },
  },
  [602] = {
    'Análisis mágico',
    {'Por lo que he oído, los magos de Dalaran han conseguido reconstruir su mágica ciudad. La han movido a Rasganorte y han dejado un cráter enorme. Sin embargo, algunos magos se han quedado aquí, seguro que alguno tiene algo de tiempo para echar un vistazo a los brazales. Si algo sé de los magos es que no pueden resistirse a un rompecabezas mágico.|n|nCoge la bolsa de brazales de elemental de agua y veamos si nos pueden ayudar con lo de la maldición de la Piedra. Busca al archimago Ansirem Tejerruna. Ya he tratado antes con él y es muy sabio.', },
    {'Lleva los brazales de elementales de agua al archimago Ansirem Tejerruna en el Cráter de Dalaran.', },
  },
  [603] = {
    'Llave de Ansirem',
    {'El mago que tiene la Piedra está ampliando su poder mediante algún punto focal... un altar de algún tipo. Deberías poder detenerlo destruyéndolo.|n|nResulta que sé cómo hacerlo: hay una daga antigua, otra reliquia trol. Y solo hay un pequeño... problema.|n|nVerás, encontré la daga mientras estaba investigando en Tuercespina, pero se la di a mi testaruda hija, Catelyn, que se escapó a la Bahía del Botín para convertirse en pirata.', },
    {'Habla con Catelyn en la Bahía del Botín.', },
  },
  [604] = {
    'Bucaneros Velasangre',
    {'Crazz habla muy bien de tu entrega a los Asaltantes Aguasnegras. Voy a confiarte una misión de vital importancia para la flota.|n|nInfíltrate en el puesto de mando del sur que los Bucaneros Velasangre han establecido en la Orilla Salvaje. Asalta el campamento. Tráeme sus cartas de navegación y las órdenes escritas. Veremos exactamente qué pretenden hacer esas babosas.', },
    {'El maestro de flota Cuernomarino en la Bahía del Botín quiere que mates 10 espadachines Velasangre y le lleves las cartas de navegación y las órdenes de los Velasangre.', },
  },
  [605] = {
    'Fragmentos de cristales canto azules',
    {'Solo hay cristales canto en Tuercespina y, para ciertos grupos, son muy valiosos. Yo puedo conseguir esos cristales, pero la maldita Ventura y Cía. ha complicado las cosas para los empresarios como yo.|n|nMe gustaría contratarte.|n|nLos basiliscos de Tuercespina comen esos cristales. Eso es lo que les da su piel endurecida y, algunas veces, se pueden conseguir cristales de calidad decente de la piel.|n|nPuedes conseguirlos de cualquier basilisco, pero los menos asquerosos están en la orilla sur de Zul\'Kunda, hacia el norte.', },
    {'Lleva 10 fragmentos de cristales canto a Loquillo Pinchabujas.', },
  },
  [606] = {
    'Asusta al Trémulo',
    {'Si hay algo que no soporto, ¡es la gente que no paga sus deudas de juego! Y hay muchos que me deben dinero. ¿Crees que podrías ayudarme?|n|nPrimero, está Phillipe el "Trémulo", ahí, en el muelle. Me debe mucho después de la timba de la semana pasada, ¡y quiero lo que me corresponde! Pero para conseguirlo, tendremos que asustarle.|n|nSal de la ciudad y caza gorilas Velo de Bruma ancianos. Encuentra una bonita selección de menudillos y llévaselos al Trémulo. No le digas que son de un animal. Deja que piense lo peor.', },
    {'Lleva 5 menudillos de Velo de Bruma a Phillipe el "Trémulo" en la Bahía del Botín.', },
  },
  [607] = {
    'Regresa junto a MacKinley',
    {'Toma, coge esta bolsa y dásela a Lobo de Mar. ¡Y dile que le iba a pagar! ¡¡Lo juro!!|n|nSolo que me emborraché un poco y me perdí... ya sabes cómo son estas cosas. Lo entenderá, ¡no hace falta que te pongas así!', },
    {'Lleva el pago del Trémulo a "Lobo de Mar" MacKinley.', },
  },
  [608] = {
    'Bucaneros Velasangre',
    {'¡Maldito sea Firallon! No podría navegar un esquife por el Lago de Cristal y mucho menos liderar toda una flota contra nosotros.|n|nLos Bucaneros Velasangre pagarán su descuido. Ahora que sabemos su plan de ataque, podemos atacar y tomarles por sorpresa.|n|n¿Pero por qué enviar a toda la flota para hacer el trabajo de un grupo de aventureros? $N, coge a algunos de tus camaradas más capaces, id al lugar de atraque de Firallon y asesinad al líder Velasangre. Su flota se hundirá poco después...', },
    {'El maestro de flota Cuernomarino en la Bahía del Botín quiere que mates al capitán Aguasmansas, al capitán Sinquilla y al maestro de flota Firallon.', },
  },
  [609] = {
    'El vudú debido',
    {'La lista empieza a menguar, pero todavía hay muchos que me deben dinero.|n|nA continuación tenemos a Maury "Patapalo" Wilkins, Jon-Jon el Cuervo, y Chucky "Diez Pulgares".|n|nLas deudas de esos malditos perros son de varios meses y creí que se habían largado de la ciudad para evitar pagarme. Pero después me enteré de que están malditos y hechizados y se dedican a vagar por las ruinas de la jungla. Pero no me importa su destino, ¡quiero lo que me pertenece!|n|nEstán en las Ruinas de Aboraz y en las Ruinas de Jubuwal, al noreste de aquí. Encuéntralos y consigue mi dinero.', },
    {'Lleva la pata de palo de Maury, el catalejo dorado de Jon-Jon y el anillo enorme de Chucky a "Lobo de Mar" MacKinley en la Bahía del Botín.', },
  },
  [610] = {
    '"El Guapo" Duncan',
    {'¿Mi PADRE te ha enviado? Pensaba que ese viejo chocho ya habría dejado de intentar encontrarme.|n|nRealmente no me escapé por su culpa, es solo que él no debería haber supuesto que aceptaría tener una vida aburrida, leyendo libros polvorientos y tratando a magos canosos, estirados y acartonados.|n|nSi necesitas mi daga, tendrás que recuperarla, la tiene "el Guapo" Duncan, uno de los Bucaneros Velasangre. Pon algo entre sus hombros y seguro que te la da.', },
    {'Consigue la daga de Catelyn de "El Guapo" Duncan.', },
  },
  [611] = {
    'La maldición de las mareas',
    {'¿Así que estás buscando un altar? Bueno, no soy tan experta en ruinas trol como mi padre, pero he oído hablar de una ciudad trol hundida cerca de esa isla que estás buscando. Quizás podrías probar allí.|n|nHas recuperado mi cuchillo, así que supongo que puedes usarlo... ¡Pero lo quiero de vuelta cuando hayas terminado!', },
    {'Destruye el Altar de las Mareas con la daga de Catelyn, mata a Gazban y lleva la Piedra de las Mareas y la daga de Catelyn al Barón Revilgaz.', },
  },
  [612] = {
    nil,
    {'Es un palo de ciego, pero ¿por qué no tratas de convencer a Catelyn de que se separe de su daga? El corazón de un coleccionista, ¿sabes cómo es?|n|nA lo mejor, si mencionas que es para mí, puede que se muestre más dispuesta a vendérmela.', },
    {'Devuelve la espada de Catelyn.', },
  },
  [613] = {
    'Abrir la pata de Maury',
    {'¡Maldición! Ese aq-queroso de Maury ha pueh\'to un candao en su pata, ¡y no consigo abril-la! Guarda el botín en el pie, ¡y es justo lo que me debe!|n|nTenemos que encontral la llave que abre el candao. Todos saben que Maury apostaba con los ogro Mosh\'Ogg, en su túmulo, al noreste. Y me dijo, cuando todavía eh\'taba vivo, que la última vez que fue al túmulo, acabó siendo perseguido porque había ganao mucho. Quizás los ogros de allí tengan su llave.|n|nSi es así, probablemente tengas que matal a muchos de ellos pa encontral al que la tiene...', },
    {'Lleva la llave de Maury a "Lobo de Mar" Mackinley en la Bahía del Botín.', },
  },
  [614] = {
    'El cofre del Capitán',
    {'Yo solía navegar en barco desde aquí hasta Trinquete, en Kalimdor. Fui un capitán de mucho éxito e inmejorable reputación.|n|nHasta que...|n|nEsos malditos gigantes marinos acabaron conmigo. Destruyeron mi barco, mataron a mi tripulación y me dejaron en un barco salvavidas con dirección a la Bahía del Botín. Y uno de esos gigantes, Gorlash, robó mi cofre del Capitán. Dijo que lo quería para usarlo como caja de rapé. ¡Increíble!|n|nHe oído que Gorlash está cerca de la costa al este de aquí. ¡Encuéntrale y recupera mi cofre! Hazlo y conseguirás la gratitud de un capitán.', },
    {'Lleva el cofre de Smotts a Hecklebury Smotts en la Bahía del Botín.', },
  },
  [615] = {
    'El alfanje del Capitán',
    {'Cuando perdí mi primer barco por culpa de esos gigantes, compré otro. Se llamaba La Venganza de Smott, lo llené de suministros y una tripulación y partí en busca de los villanos. Les encontré... pero me vencieron. Destruyeron La venganza de Smott, mataron a mi segunda tripulación y de nuevo me dejaron en un barco salvavidas.|n|nEsta vez, otro de los gigantes, Negolash, robó mi alfanje.|n|nEnfréntate a Negolash y tráeme mi alfanje.|n|nHabla con Tardo. Fue mi cocinero en La venganza de Smott y sobrevivió al ataque. Podrá ayudarte a encontrar al gigante.', },
    {'Habla con Tardo.', },
  },
  [616] = {
    'La isla fantasma',
    {'El Barón Revilgaz me ha pedido permanecer alerta en busca de rumores y cosas extrañas que ocurren en la Bahía del Botín y en Tuercespina. Generalmente no creo mucho en historias de fantasmas, pero oí a unos marineros en la taberna hablando sobre una isla encantada a poca distancia de la costa. Dicen que hay elementales de agua y un fantasma goblin enloquecido.|n|nSi vas a ver a Revilgaz, ¿podrías contarle la historia?', },
    {'Habla con el Barón Revilgaz en la Bahía del Botín.', },
  },
  [617] = {
    'Tallos de juncos akiris',
    {'¿Andas buscando trabajo, $N? Quizás tenga algo pa ti si t\'apetece un pequeño desafío.|n|nTengo un amigo llamado Groy que se está forrando vendiendo lo que los nagas llaman junco akiris: es un tipo de valioso junco del océano. No tengo muy claro pa qué sirve, pero paga bien por fajos de esa cosa.|n|nTráeme diez fajos de eso y haremos negocios. La última vez que vimos a los nagas fue en la playa que está al norte de aquí.', },
    {'Consigue 10 fajos de junco akiris para el corsario Bloads en Bahía del Botín.', },
  },
  [618] = {
    'Enfréntate a Negolash',
    {'Negolash es un gigante hambriento.|n|nCuando los gigantes destruyeron nuestro barco, Negolash fue directo a la cocina. No quería comerse a la tripulación, como los otros gigantes. Negolash quería vino... y mis alas de águila ratonera a la parrilla. Son mi especialidad, y he tenido que ir hasta las Tierras Inhóspitas para encontrar la receta.|n|nSi quieres atraer al gigante, consigue vino y un montón de alas de águila ratonera. Ponlo todo en nuestro viejo barco salvavidas, en la costa, al sureste de aquí. Cuando Negolash huela toda esa comida, ¡irá seguro!', },
    {'Lleva 10 Alas de águila ratonera a la parrilla y 5 botellas de vino de vid de jungla al barco salvavidas del capitán Smotts.|n|nMata a Negolash y lleva el alfanje de Smotts al capitán Smotts en Tuercespina.', },
  },
  [619] = {
    'La tentación de Negolash',
    nil,
    nil,
  },
  [620] = {
    'La banda con monograma',
    {'Esta preciosa banda tiene bordadas las letras "HS" en el dobladillo.', },
    {'Devuelve la banda con monograma a su propietario.', },
  },
  [621] = {
    'El secreto de Zanzil',
    {'Zanzil el Desterrado vive con sus seguidores en las Ruinas de Jubuwal y Aboraz, al noreste de la Bahía del Botín. Está exiliado de su tribu. ¿Por qué? Bueno...|n|nZanzil sabe cómo someter la mente de otros y sus líderes le temen. Utiliza una mezcla de plantas de la jungla con sus seguidores para eliminar su voluntad y fortalecer sus cuerpos.|n|nEsa mezcla sería muy valiosa para aquellos que deseen controlar a otros.|n|nTráeme muestras de esa mezcla y seguro que encuentro un buen uso.', },
    {'Lleva 12 muestras de la mezcla de Zanzil a Loquillo Pinchabujas en la Bahía del Botín.', },
  },
  [622] = {
    'Regresa junto al cabo Kaleb',
    {'Mientras no estabas arreglé la olla. Incluso añadí un pitorro de vapor extra, ¡y mira! Hay una nueva hoja en el fondo que puede cortar incluso huesos de piernas.|n|nSí, sí, la olla mecánica de Krazek, es una herramienta que satisface al cocinero en un 100%. Seguro que su dueño estará satisfecho.', },
    {'Lleva la olla mecánica de Krazek arreglada al cabo Kaleb en el Asentamiento Rebelde.', },
  },
  [623] = {
    'Tallos de juncos akiris',
    {'$N, ya que tás aquí, he recibío un mensaje de Groy cuando no estabas. Dijo que estaba satisfecho con el último cargamento y que tiene un cliente que quiere más de esa cosa ahora mismo.|n|nYo no voy a Theramore hasta dentro de una semana, pero si tú quieres hacer el viaje, podrías llevar los juncos por mí.|n|n¿Te apetece una aventura? Sabes dónde está el Marjal Revolcafango, ¿no? Yo iría con cuidado, Theramore puede ser peligroso dependiendo de quién seas...', },
    {'Lleva un fajo de juncos akiris al corsario Groy, en Theramore.', },
  },
  [624] = {
    'El enigma de Cortello',
    {'Hay un puente ornamentado y con mucho tránsito|nAl este de Viento Muerto y al sur de Crestagrana|nBajo el puente te espera algo|nAlgunos lo llaman un consejo otros, una pista|nAllí te esperará eternamente|nViendo pasar el tiempo en el Pantano de las Penas', },
    {'¡Resuelve el enigma!', },
  },
  [625] = {
    'El enigma de Cortello',
    {'Te espera una tierra muy lejana, en Kalimdor|nDonde el peligro ha destruido las esperanzas y los destinos|nAl este de Los Baldíos el tiempo es severo|nLa penumbra y el peligro imperan en el Marjal Revolcafango|nPero allí hay una pista, para aquellos dispuestos a aceptar el desafío|nEsperando ser encontrada... en una cueva... al suroeste', },
    {'¡Resuelve el enigma!', },
  },
  [626] = {
    'El enigma de Cortello',
    {'¡A Lordaeron! La gran tierra de confusión|nDonde valientes soldados juegan con la muerte|nEncuentra tu camino a través del gran disturbio|nAllí encontrarás el final de esta misión|nJunto a la costa de las Tierras del Interior, en la base de las cataratas|nDesde las profundidades del agua, te llama tu tesoro.', },
    {'¡Resuelve el enigma!', },
  },
  [627] = {
    'Un favor a Krazek',
    {'Hay una cueva en la montaña, en el Cañón Mostacho Seco, al norte de las Tierras Altas de Arathi. En esa cueva hay un extraño mineral: sangrita. La sangrita de esta cueva no tiene una calidad superior, pero incluso la sangrita de baja calidad es valiosa... para aquellos que sepan usarla.|n|nMe gustaría conseguir sangrita.|n|nArreglaré tu olla mecánica, pero mientras lo hago... tráeme algunas muestras de sangrita. Si me traes las suficientes, te daré una bonificación.|n|nOh, y si no tienes la habilidad necesaria para extraerla... ¡encuentra a alguien que la tenga!', },
    {'Lleva 4 fajos de mena de sangrita inferior a Krazek en la Bahía del Botín.', },
  },
  [628] = {
    'Borceguí',
    {'Ahora que hemos terminado el interior, lo único que queda es añadir la capa exterior. Para esto, solo utilizo la mejor piel de crocolisco mayor. Duran más y son un lienzo perfecto para añadir los diseños y dibujos que completan el estilo borceguí de Drizzlik.|n|nPero no es fácil encontrar la piel perfecta, la única que podría servir es la piel de un crocolisco marino mayor. Los crocoliscos mayores solo salen fuera para defender a los otros crocoliscos marinos, así que quizás tengas que matar a unos cuantos para que salgan.', },
    {'Lleva una piel de crocolisco mayor a Drizzlik en la Bahía del Botín.', },
  },
  [629] = {
    'El Arrecife Mortal',
    {'Mucho tiempo atrás, un gran temblor de tierra sumergió una antigua ciudad trol bajo las aguas de La Costa Salvaje, al noroeste. Llamamos a ese lugar El Arrecife Mortal, ya que ahora los múrlocs residen en las ruinas de la ciudad, atacando a todo el que se acerca.|n|nEn esas ruinas hay una antigua tablilla que narra la vieja fábula de Gri\'lek, un héroe de leyendas trol. La fábula es sagrada para la tribu Lanza Negra y, aunque la tablilla es muy grande como para moverla, quiero un fragmento para consagrarlo en nuestro nuevo hogar de Orgrimmar.', },
    {'Lleva un fragmento de tablilla a Kin\'weelay en el Campamento Grom\'gol.', },
  },
  [630] = {
    'Mensaje en una botella',
    {'$N, pongo mi fe en ti y en cualquiera que te ayude a liberarme. Mi secuestrador es el gran Cieloleno rey Mukla. Domina a las bestias de esta isla que me tienen aquí contra mi voluntad con ayuda de una cadena. Si puedes matarle y encuentras la llave de estos grilletes, estaré en deuda contigo eternamente.|n|nA menudo puedo oírle en la parte sureste de la isla, pero ten cuidado. Hay que tomarle muy en serio.', },
    {'Mata al rey Mukla y vuelve a por la princesa Poobah con la llave para liberarla.', },
  },
  [631] = {
    'El Puente Thandol',
    {'Se oyó el estruendo de una enorme explosión por todas las colinas. \'¡Fue horrible, créeme!|n|nLos buenos soldados murieron en la defensa el Puente Thandol. Largatrenza dice que nos vengaremos de los Hierro Negro en un santiamén.|n|nPero estamos en un mundo lleno de dolor y no veo ningún refuerzo. Largatrenza envió a Herrumbra a explorar el puente del Este para ver si podemos ganarlo.|n|nEso fue hace días. Con Dun Modr bajo asedio no tenemos hombres suficientes para ir a buscarlo.|n|nQuizás tú puedas ayudarnos...', },
    {'Rhag Garmason quiere que localices a Herrumbra.', },
  },
  [632] = {
    'El Puente Thandol',
    {'Parece que el pobre Herrumba cayó en una emboscada de los Hierro Negro. Descubres un papiro junto a su puño cerrado.|n|nLleva la desalentadora noticia a Rhag Garmason y enséñale lo que has descubierto.', },
    {'Vuelve a informar a Rhag Garmason en Dun Modr, en Los Humedales, y enséñale el papiro que encontraste en el cadáver de Herrumbra.', },
  },
  [633] = {
    'El Puente Thandol',
    {'¡¡¡Cielos!!! ¡¡¡No!!! Pobre Herrumbra. Es una tragedia.|n|nNo debemos permitir que su muerte haya sido en vano. El pergamino que has descubierto indica que Kam Furiahonda, el cerebro del ataque, ordenó atesorar un alijo de explosivos al otro lado del Puente Thandol, en las Tierras Altas de Arathi.|n|n¡Si esos explosivos llegan al puente, nuestra principal vía de suministros recibirá un duro golpe! ¡Hay que destruir el alijo, $N! Vuelve a verme cuando hayas terminado tu misión.|n|nEres nuestra única esperanza.', },
    {'Destruye el cajón de explosivos.', },
  },
  [634] = {
    'Petición a la Alianza',
    {'Voy a pedirte otro pequeño favor, $C. Estamos esperando las reservas de Forjaz. Pero Roggo tiene noticias de un campamento de la Alianza al norte de las Tierras Altas de Arathi, en el Refugio de la Zaga.|n|nViaja hasta allí y busca a la capitana Nials. Pregunta a la buena capitana si la Alianza puede ofrecernos algunos soldados que nos ayuden a recuperar Dun Modr y el Puente Thandol.', },
    {'Busca a la capitana Nials en el Refugio de la Zaga, en las Tierras Altas de Arathi.', },
  },
  [635] = {
    'Cristal en las montañas',
    {'El fragmento palpita cuando lo agarras...|n|nSientes una especie de súplica saliendo del fragmento, como si alguien estuviera intentando comunicarse contigo, alguien que necesita tu ayuda desesperadamente.|n|nUna visión llena tu mente... son las montañas septentrionales de Arathi, y ves también un cristal brillante sobresaliendo del suelo.|n|nTe sientes $Gatraído:atraída; hacia ese lugar.', },
    {'Encuentra el cristal de tu visión.', },
  },
  [636] = {
    'Leyendas de la tierra <NYI>',
    {'El libro cuenta la historia de una princesa elemental y de su cautiverio en las profundidades de las Tierras Altas de Arathi.|n|nTambién habla de un afloramiento secreto de cristales en las Tierras Altas. Estos cristales, los Fragmentos de Myzrael, son una ventana a la prisión de la princesa.|n|nSi un alma valiente encontrara los Fragmentos de Myzrael, tal vez pudiera hablar con ella...', },
    {'Encuentra los Fragmentos de Myzrael.', },
  },
  [637] = {
    'Carta de Sully Balloo',
    {'El sobre empapado y desgastado se deshace entre tus manos, revelando varias páginas de una carta escrita con una cuidada caligrafía.|n|nLa carta está dirigida a Sara Balloo de Forjaz y comienza así: "Querida Sara..."', },
    {'Entrégale la carta de Sully Balloo a Sara Balloo.', },
  },
  [638] = {
    'Aterratrols',
    {'Con Thoras Aterratrols muerto y Stromgarde en ruinas, Vol\'jin ha ordenado que hagamos todo lo posible por robar la legendaria espada Trol\'kalar a los humanos, para que podamos usarla en nuestras próximas batallas contra los trols de Zul\'Gurub.|n|nZengu, uno de nuestros cazadores más expertos, se ha dirigido a Sentencia, al noreste de las Tierras Altas de Arathi, para encargarse de todo.', },
    {'Viaja a Sentencia en las Tierras Altas de Arathi y habla con Zengu.', },
  },
  [639] = {
    'Sigilo de Strom',
    {'En tiempos ancestrales, los trols lucharon contra el Imperio Arathoriano y contra nuestro más temible adversario, Lord Ignaeus de Strom, al que llamaban Aterratrols. Acudía a la batalla empuñando a Trol\'kalar, verdugo de trols en su antigua lengua.|n|nPero ahora la estirpe de Aterratrols se ha debilitado, su bastión está en ruinas.|n|nLa espada está protegida por varios sigilos que se dividieron entre los supervivientes de Stromgarde, debemos recuperarlos.|n|nLa Hermandad se llevó el primero, lo custodia uno de sus hombres en Stromgarde.', },
    {'Consigue el sigilo de Strom para Zengu en Sentencia.', },
  },
  [640] = {
    'El sigilo roto',
    {'La tumba de Thoras Aterratrols está protegida por tres sigilos, el primero de los cuales recuperaste de la Hermandad. Será más difícil conseguir los otros dos ya que la milicia de Stromgarde los tiene firmemente atrincherados.|n|nEl hijo de Thoras, Galen, dividió el sigilo de Thoradin en cinco fragmentos que dispersaría entre los defensores de Stromgarde. Recupera todos los fragmentos y llévaselos a Tor\'gan, el chamán trol, será capaz de recomponer con ellos el sigilo completo.', },
    {'Recupera los 5 trozos de sigilo de los defensores de Stromgarde y llévaselos a Tor\'gan en Sentencia.', },
  },
  [641] = {
    'Sigilo de Thoradin',
    {'La reconstrucción ha funcionado perfectamente. Ahora se puede usar el sigilo para desbloquear el sello de la tumba de Aterratrols. Devuélveselo a Zengu, seguro que tiene más tareas para ti.', },
    {'Llévale el sigilo de Thoradin restaurado a Zengu en Sentencia.', },
  },
  [642] = {
    'La princesa encerrada',
    {'Me llamo Myzrael. Soy una princesa de la tierra, y mis captores, los gigantes, me han encerrado en el subsuelo de las Tierras Altas de Arathi. Estos fragmentos de cristal son mi único medio para hablar con el mundo de la superficie.|n|nPor favor, ayúdame. Los aliados de los gigantes, los kóbolds Mostacho Seco, tienen un fragmento como este en el Cañón Mostacho Seco, hacia el este. Para que ese pedazo cobre poder, debes conseguir motas de Myzrael de los kóbolds y aplicárselas.|n|nTe lo suplico, $N, ¡ayúdame!', },
    {'Recolecta 12 motas de Myzrael y llévalas a los fragmentos iridiscentes en el Cañón Mostacho Seco.', },
  },
  [643] = {
    'Sigilo de Arathor',
    {'Aunque apenas pueda afirmarse que controlan Stromgarde, y no digamos las Tierras Altas de Arathi, el príncipe humano lleva los restos de su caballería por el campo. No logro entender por qué lo hace, aunque ¿quién entiende a los humanos?|n|nSean cuales sean sus motivos, le ha dado uno de los sigilos al teniente Valeroso, el jefe de su caballería. Encuéntralo y tráeme el sigilo.', },
    {'Recupera el sigilo de Arathor y llévaselo a Zengu en Sentencia.', },
  },
  [644] = {
    'Sigilo de Aterratrols',
    {'El último sigilo necesario para desbloquear la tumba de Thoras Aterratrols está en manos de su propio hijo. Mora en lo más recóndito de Stromgarde, en una capilla en los distritos de la milicia. El príncipe Galen está bien protegido y es él mismo un guerrero respetable, así que esta tarea podría resultar de lo más difícil.', },
    {'Mata al príncipe Galen Aterratrols y llévale el sigilo de Aterratrols a Zengu en Sentencia.', },
  },
  [645] = {
    nil,
    {'¿Qué es esto? Con los cuatro sigilos reunidos, han logrado recomponerlos y crear un solo sigilo. No hay duda de que con este lograrán atravesar la protección de la tumba de Aterratrols.|n|nLos restos de Aterratrols están enterrados en el Sagrario detrás de la capilla de Stromgarde. Recupera Trol\'kalar.', },
    {'Recupera la espada Trol\'kalar de la Tumba de Aterratrols en Stromgarde.', },
  },
  [646] = {
    nil,
    {'La luz se desvanece despacio, la espada Trol\'kalar, retenida en una funda pétrea se ha liberado.', },
    {'Entrega Trol\'kalar a Zengu en Sentencia.', },
  },
  [647] = {
    'Licor de MacKreel',
    {'¡Anoche tomé un poco de licor de luna! Largatrenza me mataría si supiera que perdí el sentido mientras estaba de guardia.|n|nEsa bebida sí que es fuerte... Sentía como si una brigada entera de máquinas de asedio me hubiera pasado por encima.|n|n¡Oh, mira qué hora es! Le prometí al maestro cervecero Bilger de Costasur que saldaría mi deuda con él enviándole licor de luna.|n|nEl problema es que solo dispongo de 15 minutos para ello. ¿Te importaría llevárselo tú? ¡Date prisa!', },
    {'Llévale el licor de luna de MacKreel al maestro cervecero Bilger de Costasur.', },
  },
  [648] = {
    '¡Rescatar a OOX-17/TN!',
    {'Vuelves a oír la voz del gnomo que sale del robot:|n|n"Tengo que llevar a OOX-17/TN a un lugar abierto y seguro en el que pueda iniciar el largo proceso de despegue. Tiene un dispositivo de invisibilidad integrado, pero necesito tiempo para que vuelva a estar operativo. Escolta al robot hasta, digamos, cerca de las Cavernas del Tiempo. Allí podré tomarme mi tiempo para hacer que todo vuelva a funcionar correctamente."|n|n"¡Escóltalo para que llegue sano y salvo y después ven a verme a Bahía del Botín! Oglethorpe Obnoticus. ¡Corto y cierro!"', },
    {'Escolta a OOX-17/TN para que llegue sano y salvo y después preséntate ante Oglethorpe Obnoticus en Bahía del Botín.', },
  },
  [649] = {
    'Recupera el calimocho',
    {'Tengo un trabajito de rescate para ti, y si te gusta el buen calimocho, seguro que lo aceptas. ¿Que qué es?|n|nPues una bebida, ¿qué va a ser?|n|nHay un cargamento de calimocho dulce de las Tierras del Interior en una avanzada abandonada de la Horda. ¡Ya no se hace un calimocho como ese! Uno de esos atontados con los que trabaja Malton está interesado, así que tráeme una caja de calimocho para él y un par para mí. Habla con Malton para que te dé los detalles.', },
    {'Habla con Malton Droffers en Orgrimmar.', },
  },
  [650] = {
    'Recupera el calimocho',
    {'El elfo con el que necesitas hablar se llama Gilveradin Cazasol. ¡Puede identificar cualquier vino, con cosecha y todo, con solo olerlo! Él puede embotellar el calimocho que necesitamos, así que tendrás que hablar con él. Necesitamos seis botellas en total: dos para papá y todas las que él quiera y, créeme, querrá alguna que otra. Cuando hayas embotellado el calimocho y tengas las dos botellas de papá, vuelve aquí.|n|nEl campamento de Gilveradin está por las Tierras del Interior, cerca de la casa de un elfo noble... y esos elfos nobles no son buena gente. Créeme.', },
    {'Habla con Gilveradin Cazasol; su campamento está en las Tierras del Interior.', },
  },
  [651] = {
    'Piedras de Vínculo',
    {'Hay cuatro Piedras de Vínculo diseminadas por todo Arathi. Esas piedras son las que me mantienen anclada bajo la tierra.|n|nPara desbloquearlas tienes que desbloquear primero la más fuerte: la Piedra de Vínculo interior. Y para hacerlo debes reunir las llaves de las otras tres.|n|nLas piedras están custodiadas por guardias pero, con un poco de astucia o suerte, encontrarás la forma de sortearlos.', },
    {'Reúne la llave ardiente, la llave blasonada y la llave del trueno de la Piedra de Vínculo Occidental, la Piedra de Vínculo Este y la Piedra de Vínculo Exterior.|n|nLlévalas a la Piedra de Vínculo Interior.', },
  },
  [652] = {
    'Desbloquear la piedra angular',
    {'Desbloquear las Piedras de Vínculo me liberó en gran parte de mi confinamiento. Pero aún queda una cerradura por abrir. Es la piedra angular que ves en ese círculo de piedras. Y la llave la tiene uno de mis captores, Fozruk, el guardián de las piedras.|n|nDebes conseguir esa llave. Los guardianes de las piedras la llaman la vara del Orden. Arrebátasela a Fozruk y úsala para abrir la piedra angular.|n|n$N, me has ayudado mucho. Pero necesito un poco más de ayuda... ¡Mi gratitud hará temblar los mismísimos pilares de la tierra!', },
    {'Encuentra a Fozruk y mátalo. Lleva la vara del Orden a la piedra angular en las Tierras Altas de Arathi.', },
  },
  [653] = {
    'Aliados de Myzrael',
    {'<Myzrael habla.>|n|n¡Libre! ¡SOY LIBRE! Libre para recuperar la fuerza, sin que me vean mis captores. Porque si me enfrentara a ellos ahora, seguro que me vencerían y me volverían a encerrar.|n|nPero con el tiempo haré frente a los gigantes ¡y se arrepentirán de haber sido mis guardias!|n|nEres $Gun:una; noble $Galiado:aliada;, $N. Dentro de algún tiempo volveré a necesitarte. Cuando esté listo, necesitaré que me conjures para devolverme a la superficie.|n|nHabla con Gerrig Agarrahueso. Se encuentra en Forjaz, en una tienda de La Caverna Abandonada. Él sabe cómo realizar el conjuro.', },
    {'Habla con Gerrig Agarrahueso en La Caverna Abandonada de Forjaz.', },
  },
  [654] = {
    'Recogida de muestras en Tanaris',
    {'Al activar la fuente de energía el equipo de prueba de campo empieza a brillar y a vibrar. Parece una señal de que todo funciona correctamente.|n|nLo enviaré de inmediato.|n|nDe acuerdo con el ingeniero jefe Pasaquillas, a partir de ahora tienes algo de tiempo para recoger los datos necesarios en el desierto de Tanaris.|n|nVuelve a hablar con él cuando hayas concluido tu tarea.', },
    {'Consigue muestras no estudiadas de 8 basiliscos, 8 hienas y 8 escorpiones. Devuélvele el equipo de estudio al ingeniero jefe Pasaquillas, en Gadgetzan, antes de que se agote la fuente de energía.', },
  },
  [655] = {
    'Sentencia',
    {'Lo recuerdo como si fuera ayer... Tantos años sin esperanza. Con la madera y el acero ligándome a este terrible lugar. ¡Y por fin, por fin! Ahí estaba el Jefe. Martillo Maldito, con sus agoreras placas y su martillo de guerra en alto.|n|nFue terrible... Que el golpe asestado por la mano de un cobarde acabara con nuestro héroe más admirado. Cargó por detrás con su caballo y lo atravesó con su lanza... Yo caí de rodillas. ¿Qué esperanza nos quedaba? ¿Qué esperanza nos queda...?', },
    {'Habla con Tor\'gan en Sentencia.', },
  },
  [656] = {
    'Invocar a la princesa',
    {'Debes derrotar a Myzrael antes de que se vuelva más fuerte. Si no lo haces, en cuanto tenga suficientes poderes ¡desafiará a sus captores! Hay quien piensa que puede controlarla, pero si así fuera, ¡¿por qué la encadenaron los gigantes?!|n|n¿A que no tiene ni pies ni cabeza?|n|nPara derrotarla, conjúrala en los fragmentos de Myzrael donde hablaste con ella la primera vez. Derrótala, coge sus grilletes tétricos y pónselos a los fragmentos de Myzrael.|n|nHazlo y volverá a estar presa.', },
    {'Ve a los fragmentos de Myzrael, invócala y derrótala.|n|nRecolecta sus grilletes de Eldritch y pónselos a los fragmentos de Myzrael.', },
  },
  [657] = {
    'Sospechas de una nueva Peste',
    {'<Quae empieza a examinar la carpeta.>|n|nEsto SÍ que es interesante. Al parecer, el boticario Jorell ha estado trabajando en unos experimentos letales aquí en Go\'Shek. No estoy seguro de cuál es la relación con Trabalomas pero a Phin no le gustaría que dejásemos que siga adelante.|n|nTuvimos un roce con unos orcos cuando no estabas, por lo que no estoy en condiciones de ayudar a Kinelory. Si te apetece, va a necesitar que la protejan cuando vaya a la Granja a robar lo que sea que Jorell aún no haya enviado a Molino Tarren.', },
    {'Habla con Kinelory cerca de la Granja Go\'shek, en las Tierras Altas de Arathi.', },
  },
  [658] = {
    'Sospechas de una nueva Peste',
    {'¿Así que Phin te ha mandado ver qué hacemos? No me sorprende. Se preocupa demasiado.|n|nHemos vigilado la granja durante días y Kin dice que hace poco ha visto a un mensajero saliendo de esa casita que hay hacia el sur.|n|nHabla mucho, pero me fío de su instinto cuando estamos en sitios peligrosos.|n|n¿No sabrás seguir rastros, por un casual? Creemos que el mensajero podría llevar notas al Molino Tarren. Si pudiéramos echar el guante a esos documentos... Seguro que nos ayudan a entender qué está pasando en Trabalomas.', },
    {'Encuentra a la mensajera Renegada y lleva su carpeta sellada a Quae cerca de la Granja Go\'shek.', },
  },
  [659] = {
    'Sospechas de una nueva Peste',
    {'Saludos. Te doy la bienvenida, $N. Dirijo un grupo de aventureros que investigan sucesos extraños que han tenido lugar en esta zona.|n|nMi primo de Trabalomas ha tenido que sacrificar a su perro Stanley porque el animal creció místicamente hasta alcanzar un gran tamaño y empezó a atacar a todo el que se le acercara.|n|nCreo que los no-muertos están involucrados en eso y estamos buscando indicios que lo prueben.|n|nDos compañeras mías, Quae y Kinelory, fueron a la Granja Go\'shek en las Tierras Altas de Arathi y hace días que no tenemos noticias suyas. ¿Podrías encontrarlas por mí? Empiezo a preocuparme de verdad.', },
    {'Encuentra a Quae y a Kinelory cerca de la Granja Go\'shek en las Tierras Altas de Arathi.', },
  },
  [660] = {
    'Sospechas de una nueva Peste',
    {'Muy bien, $N. Si tú estás $Glisto:lista;, yo también.|n|n¿Vamos?', },
    {'Protege a Kinelory hasta que haya regresado con Quae.', },
  },
  [661] = {
    'Sospechas de una nueva Peste',
    {'He visto a Kinelory con mucho peor aspecto después de una noche en la taberna que ahora. No hay duda de que tu protección fue de gran ayuda.|n|nCon los objetos que trajo de la Granja, Phin debería hacerse una idea de lo que está ocurriendo en Arathi. Solo para asegurarnos de que no hay represalias después de vuestra incursión, nos quedaremos aquí un poco más. ¿Te gustaría volver a Costasur y hablar con Phin?', },
    {'Encuentra a Phin Odelic en Costasur, en las Laderas de Trabalomas.', },
  },
  [662] = {
    'Rescate en alta mar',
    {'O\'Breen guió a las naves hasta la cala. Estábamos seguros de que ahí encontraríamos el tesoro. El Heraldo atracó sin novedad pero cuando El Capricho y el Espíritu de Argénteos se acercaban, la marea empezó a bajar. ¡Lo más extraño que haya visto nunca!|n|nLas dos naves encallaron en algo... una especie de templo que había en el arrecife. Se hundieron a gran velocidad... Fue una tragedia.|n|nNecesitamos recuperar sus cuadernos de bitácora y sus cartas de navegación antes de partir. ¡No podemos permitir que nadie vea esa información!', },
    {'El contramaestre Nizlix quiere que recuperes los cuadernos de bitácora y las cartas de navegación de El Capricho y del Espíritu de argénteos.', },
  },
  [663] = {
    '¡Tierra a vista!',
    {'Lolo ve a un minúsculo $R! ¡Siempre al loro, Lolo está!|n|n$GBienvenido:Bienvenida; a la Cala de Faldir. El capitán O\'Breen dijo que solo estaríamos aquí durante unas horas. Lo justo para reunir el tesoro y volver a Bahía del Botín.|n|nPero Lolo piensa que vamos a estar allí más tiempo. Perdimos otros dos barcos de nuestra formación. Pobres Espíritu de argénteos y El Capricho. ¡En el fondo del mar ahora descansan!|n|nLolo sugiere que hables con el capitán O\'Breen si te vas a quedar por aquí.', },
    {'Habla con el capitán O\'Breen en la Cala de Faldir, en las Tierras Altas de Arathi.', },
  },
  [664] = {
    'Ahogar las penas',
    {'Ah, esta vida es terrible. Debería estar en una tumba de agua ahora mismo, no aquí, junto al fuego y respirando aire fresco.|n|nLa tripulación se esforzó tanto para salvar El Capricho, mi hermosa nave... Benditos sean, benditos sean sus corazones.|n|nO\'Breen llegó a la costa sano y salvo, pero nosotros no tuvimos tanta suerte. La mar nos hundió, lo juro.|n|nUn momento antes estábamos a flote y después... el agua empezó a entrar. ¡Y esas bestias! Mataron a todos los supervivientes. Esa escoria naga... Yo perdí el conocimiento y acabé aquí, a salvo.|n|nQuiero ver a esas bestias muertas.', },
    {'El capitán Tripacero de Cala de Faldir quiere que mates a 10 asaltantes Espinadaga y a 3 hechiceras Espinadaga.', },
  },
  [665] = {
    'El tesoro sumergido',
    {'Ahora que somos Asaltantes Aguasnegras hechos y derechos, debemos ayudar a O\'Breen a encontrar el tesoro elfo perdido.|n|nEs casi imposible encontrar las gemas en el mar sin ayuda. El doctor ha creado unas gafas que ayudan a ver en la oscuridad del mar. Pero hay que cargarlas con la energía que emana una piedra encantada de la cueva que hay en la colina.|n|n¡Y la cueva está maldita! Cuando alguien se acerca, cae en una emboscada. Defiéndeme para que pueda recoger la energía de la piedra con las gafas.', },
    {'Escolta al profesor Fiseltor hasta la cueva y a su regreso.', },
  },
  [666] = {
    'El tesoro sumergido',
    {'El tesoro lleva tanto tiempo en el fondo del mar que las gemas se han calcificado y convertido en piedras. Pero gracias al poder de estas gafas las localizarás sin esfuerzos.|n|n¡Un inventito gnomo de gran utilidad!|n|nAsí que toma prestadas estas gafas de caza de gemas, $N, y mira a ver si puedes recolectar algo del tesoro perdido para el capitán O\'Breen.|n|nYo mismo bucearía hasta allí pero... mm... estooo, tengo importantes asuntos científicos que atender en tierra firme y seca... digo, pues eso.', },
    {'El doctor Draxlegauge de la Cala de Faldir quiere que reúnas 10 gemas de elfo y le devuelvas las gafas de caza de gemas cuando hayas acabado.', },
  },
  [667] = {
    'Muerte desde abajo',
    {'Vaya, malas noticias. Al parecer, los Espinadaga están amasando recursos para un ataque.|n|nLos nagas son famosos por su crueldad en el combate. Seguirán atacando hasta que me maten.|n|nNo valoro mi propia vida más que la de mis hombres, pero debes defenderme. La tripulación no será capaz de volver a Bahía del Botín sin mis conocimientos de navegación.|n|nLos nagas vendrán desde el mar. Necesito que permanezcas aquí conmigo para eludir el ataque. Controla el cañón y recházalos.|n|n¿Estás $Glisto:lista;, $N?', },
    {'Protege a Temblores O\'Breen durante el ataque.', },
  },
  [668] = {
    'El tesoro sumergido',
    {'No hagamos esperar al capitán O\'Breen. Querrá ver estas gemas el primero. A fin de cuentas, ¡a eso ha venido!|n|nY después de unas semanas tratando con los piratas, el profesor y yo no hemos dado cuenta de que lo peor para nuestra salud sería que nos pillaran con su tesoro en las manos.|n|nAhí va, $N, llévaselas a O\'Breen.', },
    {'Llévale las gemas de elfo al capitán O\'Breen a la Cala de Faldir, en las Tierras Altas de Arathi.', },
  },
  [669] = {
    'El tesoro sumergido',
    {'El maestro de flota Cuernomarino querrá enterarse de nuestro hallazgo sin demora.|n|nPero como puedes ver, no estamos precisamente en posición de salir de aquí No solo la marea es demasiado baja, sino que esas malditas criaturas a las que hemos perturbado no nos quitan ojo de encima.|n|nPuedes ser de gran ayuda para los incursores Aguasnegras si consigues llegar a Bahía del Botín y decirle al maestro de flota Cuernomarino que hemos descubierto el tesoro y estamos trabajando para extraer más. Llévate esta muestra como prueba.', },
    {'Llévale una muestra de gema de elfo al maestro de flota Cuernomarino a Bahía del Botín, en la Vega de Tuercespina.', },
  },
  [670] = {
    'El tesoro sumergido',
    {'Tú, $N, pareces tener un espíritu aventurero. Mi flota está anclada en Bahía del Botín hasta que podamos reabastecernos.|n|nEstán ocurriendo cosas graves aquí y en el extranjero y necesito hacer llegar una comunicación de alto secreto a Temblores O\'Breen que está amarrado en la costa de Arathi.|n|n¿Puedo confiar en que entregues este mensaje a salvo y sin traicionar su secreto?', },
    {'Llévale la carta de Cuernomarino a Temblores O\'Breen a la Cala de Faldir, en las Tierras Altas de Arathi.', },
  },
  [671] = {
    'Magia demoníaca',
    {'He notado algo extraño en el aire... un sentimiento que me hace hervir la sangre. Algo sospechaba. Me puse en camino para encontrar el origen de mi desasosiego y descubrí al oeste, en la Mansión Redilnorte, restos residuales de un conjuro demoníaco. Conforme me acercaba, me empezó a hervir la sangre y crecía mi rabia.|n|nDescubrí en el suelo un amuleto de sangrita, que se usa para conjuros demoníacos. Aunque, el que encontré estaba agotado. Necesitaré otro para poder investigar pero no me atrevo a volver a la mansión. ¿Podrías traerme alguno?', },
    {'Consigue 10 amuletos de sangrita para Tor\'gan en Sentencia.', },
  },
  [672] = {
    'El despertar de los espíritus',
    {'Tratamos de tranquilizarlo, alegrarlo, contarle historias de nuestra poderosa ciudad de Orgrimmar en Kalimdor, pero nada lo motivaba.|n|nRelatos de nuestro joven Jefe de Guerra, Thrall, que lleva la armadura y el martillo de Orgrim... pero, quizás... ¡Quizás! Una prueba de nuestra recién encontrada magia chamán le devolvería la esperanza. ¡Merece la pena intentarlo!|n|nUn pequeño objeto que podríamos hacer para él, sí... Tráeme unos ojos de raptor y veré lo que puedo hacer.', },
    {'Consigue 10 ojos de raptor de las Tierras Altas de los zancudos y de los descarnadores de las Tierras Altas para Tor\'gan en Sentencia.', },
  },
  [673] = {
    'Magia demoníaca',
    {'No me cabe la menor duda de que un poderoso brujo reside entre las paredes de Stromgarde. De vez en cuando, usando una reliquia mágica arcana, este brujo ha invocado a gran número de terribles demonios. Tenemos que eliminar la fuente de su energía.|n|nEncuentra al brujo y mátalo. Tráeme cualquier objeto mágico que encuentres sobre su persona y tomaré las medidas necesarias para acabar con él y asegurarme de que su poder no se usará para contaminar esta tierra.', },
    {'Recupera el orbe de sangrita de Marez Cogulla y llévaselo a Tor\'gan en Sentencia.', },
  },
  [674] = {
    'El despertar de los espíritus',
    {'Toma, lleva este amuleto a Gor\'mul y veamos si la fuerza del raptor puede encender la llama del guerrero que otrora ardía en él.', },
    {'Dale el amuleto de garfa de raptor a Gor\'mul en Sentencia, en las Tierras Altas de Arathi.', },
  },
  [675] = {
    'El despertar de los espíritus',
    {'<Gor\'mul tira el amuleto al suelo.>|n|n¿Te ha enviado Tor\'gan? ¡Bah! Por qué él compadecerse de mí ahora, no alcanzo entender. Compasión ser negada mí cuando no permitir mí morir con mi Jefe de Guerra en la batalla. Cruel golpe del destino tocar mí...', },
    {'Habla con Tor\'gan en Sentencia, en las Tierras Altas de Arathi.', },
  },
  [676] = {
    'La Sentencia',
    {'Alfeñiques miserables... ¿Se puede saber qué miras, $C? Te crees muy especial, ¿eh? Demuéstralo.|n|nLa avanzada de Sentencia, en Arathi, está siendo atacada. La derrota es inevitable si no les enviamos ayuda de inmediato.|n|nPero antes de salir corriendo, será mejor que te pongas a prueba. Al noreste de Stromgarde, en Arathi, hay un túmulo de ogros en el que vive la tribu Puño de Roca. Cuando seas capaz de manejarte con esos ogros, preséntate ante Bombo Vil en Sentencia.', },
    {'Mata a 8 ogros y 10 déspotas Puño de Roca; luego ve a ver a Bombo Vil a la avanzada de Sentencia, en las Tierras Altas de Arathi.', },
  },
  [677] = {
    'Un llamamiento a las armas',
    {'Los trols Secacorteza y los ogros Puño de Roca de Arathi se han unido para arrebatarnos esta tierra, pero no dejaremos nuestro sino en sus manos ni en las de nadie más. Los ejecutaremos y les demostraremos que este lugar es nuestro hogar.|n|nLos trols nos han traicionado; los ogros nos usarían de comida y de cama si les dejásemos, eso jamás ocurrirá.|n|nEmpezamos el ataque sobre los trols Secacorteza al sur de este lugar. Ejecútalos por docenas y regresa solo cuando sus campamentos estén bañados en sangre.', },
    {'Mata a 10 lanzahachas Secacorteza, 10 rebanacabezas y 8 médicos brujos y vuelve junto a Bombo Vil en la avanzada de Sentencia.', },
  },
  [678] = {
    'Un llamamiento a las armas',
    {'Tu fuerza es evidente, $N. Veamos ahora cómo te va frente a un enemigo real.|n|nLos Puño de Roca tienen una guarida al suroeste de este lugar hacia el puente de los enanos y, si no me equivoco, los destructores y los magis lugareños supondrán para ti un desafío aún mayor, así ha sido para nosotros hasta ahora.|n|nEjecuta a tantos como puedas y regresa ante mí con ese cuerpo cuando lo hayas conseguido, o que lo haga tu espíritu si fracasas. Sea como fuere, alabaré tu tenacidad en la batalla.', },
    {'Mata a 10 toscos Puño de Roca y 4 magi Puño de Roca y vuelve junto a Bombo Vil en la avanzada de Sentencia.', },
  },
  [679] = {
    'Un llamamiento a las armas',
    {'La bestia está lista para la decapitación, y con toda la fuerza, $N. Has demostrado tu valía a la hora de ayudarnos y creemos que eres la persona indicada para este golpe final. Los líderes de estos ataques han construido su guarida en las ruinas de Stromgarde, un claro símbolo de la fragilidad humana.|n|nEncuentra y mata a los señores Puño de Roca y su lacayo chamán, antes de que nos logren expulsar de estas tierras.', },
    {'Mata a 7 chamanes Puño de Roca y a 3 señores Puño de Roca y vuelve junto a Bombo Vil en la avanzada de Sentencia.', },
  },
  [680] = {
    'Una auténtica amenaza',
    {'Eres de gran ayuda para mi marido, $C, pero él no sabe por qué Sentencia está siendo atacada.|n|nOr\'Kalar, el peón de Jarra\'thol\' en Stromgarde, odia visceralmente a mi marido y desea por encima de cualquier cosa su muerte por derrotarlo hace años.|n|nSegún mis augurios, Or\'Kalar le ha tendido una trampa a mi marido, así que le he ocultado signos de la presencia del ogro.|n|nMi marido se lanzaría sin más miramientos si supiera el paradero del ogro y me gustaría pedirte tu ayuda para ejecutar a la criatura.', },
    {'Mata a Or\'Kalar y lleva su cabeza a Korin Vil en la avanzada de Sentencia.', },
  },
  [681] = {
    'Mansión Redilnorte',
    {'Estamos librando una guerra por Stromgarde, y la estamos perdiendo. Los ogros, la Hermandad y nosotros mismos hemos dividido nuestra otrora gran ciudad, y cada facción se encuentra atrapada en un sangriento enfrentamiento.|n|nNuestras fuerzas menguan mientras las del enemigo aumentan.|n|nNecesitamos ayuda de la ciudad de Costasur pero es difícil recibir suministros mientras la Hermandad controle el territorio que hay que cruzar.|n|nVe a la base de la Hermandad en Mansión Redilnorte y ejecútalos. Quizás entonces disminuya la presión sobre los trenes de suministros y nos llegarán más.', },
    {'Mata a 10 bandoleros de la Hermandad y 6 mercenarios de la Hermandad.|n|nVuelve junto a la capitana Nials en el Refugio de la Zaga.', },
  },
  [682] = {
    'Distintivos de Stromgarde',
    {'La Hermandad de Stromgarde se resiste a nuestro contingente de la milicia allí desplazado. Para incentivar a la chusma a enfrentarse a nuestros más disciplinados soldados, los jefes de la Hermandad han puesto precio a los nuestros, prometiendo oro por cada distintivo de Stromgarde arrebatado a soldados muertos.|n|nQuiero que recuperes esos distintivos, ¡no podemos permitir que esos degolladores se lleven el trofeo de nuestros valientes caídos!|n|nPenetra en la zona de Stromgarde controlada por la Hermandad y busca nuestros distintivos.', },
    {'Llévale 7 distintivos de Stromgarde a la capitana Nials en el Refugio de la Zaga.', },
  },
  [683] = {
    'Petición de Sara Balloo',
    {'$N, tengo un pequeño favor que pedirte.|n|nLlévale esta nota al gran monarca de Forjaz, el rey Magni Barbabronce. Es poca cosa para ti, que tanto has ayudado ya a la causa de la Alianza.|n|nPresentarme yo ante el Rey en mi estado de duelo resultaría contraproducente. Seguro que lo entiendes.', },
    {'Lleva la nota de Sara Balloo al rey Magni Barbabronce de Forjaz.', },
  },
  [684] = {
    'Se busca: Marez Cogulla',
    {'Le han puesto precio a la cabeza de Marez Cogulla, una consejera de alto nivel y agente de la Hermandad. La vieron por última vez en el territorio controlado por la Hermandad en Stromgarde.|n|nLa recompensa se reclama a la capitana Nials.|n|nOjo: Marez es una hábil y taimada bruja, famosa por sus trapicheos con los demonios. Se recomienda extremar la precaución en su caza.', },
    {'Llévale la cabeza de Marez a la capitana Nials en el Refugio de la Zaga.', },
  },
  [685] = {
    'Se busca: Otto y Lord Falconcrest',
    {'La Milicia de Stromgarde ha puesto precio a la cabeza de Lord Falconcrest y a la de su guardaespaldas Otto. Falconcrest dirige a la Hermandad en las Tierras Altas de Arathi y su muerte supondría un duro golpe para ellos.|n|nSu guardaespaldas Otto, aunque no sea un objetivo estratégico, es un feroz adversario y ha acabado con docenas de nuestros defensores.|n|nLas recompensas se reclaman a la capitana Nials.', },
    {'Llévale la cabeza de Otto y la de Lord Falconcrest a la capitana Nials en el Refugio de la Zaga.', },
  },
  [686] = {
    'Un homenaje real',
    {'No espero que una buena enana como la señora Balloo entienda que las farsas de guerra son por el bien de nuestra gente. La muerte de su marido, como la de cada enano que lucha en nombre de la Alianza, me pesa en el alma.|n|nAunque no puedo traer a su marido de vuelta de El Vacío Abisal, al menos puedo rendirle homenaje.|n|nVoy a encargar al gran mampostero Marmolez un monumento a la memoria de Sully Balloo.|n|nInfórmale, $C. Serás el custodio de mi voluntad.', },
    {'El rey Magni Barbabronce quiere que hables con el gran mampostero Marmolez.', },
  },
  [687] = {
    'Theldurin el Perdido',
    {'Theldurin el Perdido fue un día miembro de nuestra orden, el Martillo Crepuscular. Pero perdió la cabeza y desdeñó nuestras enseñanzas. Antes de huir de nuestro lado, robó el Pergamino de Myzrael. No pudimos cogerle, pero hay rumores de que se oculta en las Tierras Inhóspitas, ha enloquecido y no dice más que incoherencias.|n|nPara traer de vuelta a la Dama, debemos encontrar el pergamino. Y para hacerlo, debes encontrar a Theldurin.', },
    {'Encuentra a Theldurin el Perdido.', },
  },
  [688] = {
    'Aliados de Myzrael',
    {'<Myzrael habla.>|n|n¡Libre! ¡SOY LIBRE! Libre para recuperar la fuerza, sin que me vean mis captores. Porque si me enfrentara a ellos ahora, seguro que me vencerían y me volverían a encerrar.|n|nPero con el tiempo haré frente a los gigantes ¡y se arrepentirán de haber sido mis guardias!|n|nEres $Gun:una; noble $Galiado:aliada;, $N. Dentro de algún tiempo volveré a necesitarte. Cuando esté lista, necesitaré que me conjures para devolverme a la superficie.|n|nHabla con Zaruk en Sentencia. Él sabe cómo realizar el conjuro.', },
    {'Habla con Zaruk en Sentencia, en las Tierras Altas de Arathi.', },
  },
  [689] = {
    'Un homenaje real',
    {'¿Así que el Rey quiere un monumento en honor de un soldado llamado Sully Balloo? ¿Y dices que el pobre diablo murió durante la tragedia del Puente Thandol?|n|n¿Habrá alguna vez paz en Azeroth?|n|nSea como sea, todos los encargos del Rey son de la máxima importancia. Para crear una obra épica y duradera, necesito una de las mejores piedras disponibles. Tráeme granito de Alterac; lo encontrarás en las Colinas de Darrow, en Trabalomas.', },
    {'El gran mampostero Marmolez de Forjaz quiere 5 piezas de granito de Alterac.', },
  },
  [690] = {
    'Una petición de Malin',
    {'Saludos, $N. Tienes aspecto de aventurero y tengo una tarea que requiere atención.|n|nEl archimago Trelane, mi primer maestro, huyó de Stromgarde en las Tierras Altas de Arathi no hace mucho, y me ha pedido que le ayude a recuperar unas cosas que se dejó.|n|nSitiaron la ciudad e intentó defender la Torre de Arathor pero fue en vano. Ya tengo a agentes en las Tierras Altas pero me han pedido que envíe refuerzos. ¿Te interesa?', },
    {'Encuentra a Skuerto en el Refugio de la Zaga, en las Tierras Altas de Arathi.', },
  },
  [691] = {
    'Valer su peso en oro',
    {'El archimago Malin nos ha enviado a Skuerto y a mí a recolectar componentes para él. No sabía ni por dónde empezar pero ahora que estás aquí, creo que el problema está resuelto.|n|nNecesito lo siguiente: colmillos Secacorteza, bolsas medicinales Secacorteza y un cuchillo de cazador de las Sombras.|n|n¿Podrías encontrar estas cosas para mí? Los Secacorteza viven al sudeste de Arathi.', },
    {'Encuentra 10 colmillos Secacorteza, 4 bolsas de medicina Secacorteza y un cuchillo de cazador de las Sombras para el aprendiz Kryten en el Refugio de la Zaga.', },
  },
  [692] = {
    'Los trozos perdidos',
    {'El pergamino de Myzrael... ¡¿el pergamino de Myzrael?! ¡Yo que tú, ni me acercaba! Su magia puede sacar a Myzrael a la superficie del mundo y si lo haces, ¡estaremos en un lío!|n|nO... quizás ya es demasiado tarde. A lo mejor ya está libre. Quizás solo esté recobrando fuerzas antes de desatar toda su ira sobre nosotros. De ser así, entonces ¡NECESITAS el pergamino!|n|n... ¡qué mala suerte que esté en pedazos! Elementales iracundos lo robaron, lo desgarraron y luchan ahora por los fragmentos.|n|nPero puedes reunir esos trozos, quizás podamos arreglarlo...', },
    {'Lleva el trozo de pergamino roto, el trozo de pergamino arrugado y el trozo de pergamino chamuscado a Theldurin el Perdido.', },
  },
  [693] = {
    'Empuñar la varita',
    {'Eh, $N. Perdona, puede que antes me quedara corto... y no, no es un chiste.|n|nM\'he enterao del lugar donde acabó el primer objeto de Trelane: Kor\'gresh lo tiene en la Sala Puño de Roca. Y, por cierto, le disparaba con hielo pa\' mantenerla firme, no debería de tardar en enterarse de pa\' qué sirven sus poderes.|n|nLa Sala Puño de Roca está al sur de donde estamos, luego tira pa\'l este de Puente Thandol. Encuentra al ogro y trae pa\'cá esa varita.|n|nMientras no estás, veré si se m\'ocurre qué hacer con Stromgarde.', },
    {'Encuentra la varita de evocación de Trelane y llévasela a Skuerto en el Refugio de la Zaga.', },
  },
  [694] = {
    'Las defensas de Trelane',
    {'¿Has descansado?|n|nEste será nuestro siguiente paso: hay ogros rodeando la Torre de Arathor en Stromgarde. Tendremos que activar las defensas de la torre pa\' tener la más mínima posibilidad de vencerles y llegar vivos hasta los objetos. Pa\' eso, necesitaremos unas gemas a las que les han tomao cariño los chamanes Puño de Roca. Las arrebataron de la torre pero pa\' mí que no les van a durar.|n|nConsigue una d\'esas gemas y llévasela a Kryten, él conoce el hechizo pa\' que funcionen de llave.', },
    {'Encuentra un ágata azur y llévasela al aprendiz Kryten en el Refugio de la Zaga.', },
  },
  [695] = {
    'Un encantamiento de aprendiz',
    {'Aquí tienes, $N. Solo hay que apretar la gema contra uno de los pedestales cerca de la base de la torre para activar las defensas. Úsala cuando estés $Glisto:lista; para entrar en la torre a buscar los objetos de Trelane que faltan.|n|nQue tengas suerte. Estaré en el campamento esperando tu regreso. Ah, y habla con Skuerto antes de marcharte. Te dará el resto de detalles que necesitarás.', },
    {'Habla con Skuerto en el Refugio de la Zaga, en la Cuenca de Arathi.', },
  },
  [696] = {
    'Ataque a la torre',
    {'Esto es lo que tienes que buscar: la filacteria de Trelane, el orbe de Trelane y el ágata de ascuas de Trelane.|n|nLos tres deberían encontrarse en unos baúles en el interior de la torre y no deberías tener ningún problema pa\' abrirlos $Gsolo:sola;, aunque ten cuidado con los ogros.|n|nLas defensas de la torre no bastarán pa\' detenerlos; tendrás que tener las armas preparadas. Los ogros sabrán qu\'estás allí robándoles, así que no s\'andarán con mimos si te pillan.|n|nTen cuidado y suerte.', },
    {'Encuentra la filacteria de Trelane, el orbe de Trelane y el ágata de ascuas de Trelane, y llévaselo todo a Skuerto en el Refugio de la Zaga.', },
  },
  [697] = {
    'Una petición de Malin',
    {'Lleva esta carta a Ventormenta y dile a Malin que Kryten y yo pronto iremos pa\'llá. Te recompensará debidamente por habernos ayudado aquí, $N, de eso no me cabe la menor duda.|n|nQue viajes sin percances.', },
    {'Lleva la carta lacrada al archimago Malin en el Barrio de los Magos de Ventormenta.', },
  },
  [698] = {
    '[DEPRECATED]Falta de suministros',
    {'Estoy intentando reunir algunos suministros para enviarlos a nuestra avanzada cerca de la playa del este. Tok\'Kar hace lo que puede, pero entre sus guardias y cocinar para los soldados, no le queda mucho tiempo.|n|nLes encanta cocinar carne de Denteserra cuando pueden, pero no he tenido tiempo de conseguirles otro cargamento. ¿Te importaría echarles una mano?|n|nLos Denteserra jóvenes no son tan sabrosos como los viejos, así que no los cojas. Hay que esperar un año o dos para que alcancen el tamaño ideal.', },
    {'Lleva 8 costillares de Denteserra sin preparar a Tok\'Kar en el Pantano de las Penas.', },
  },
  [699] = {
    '[DEPRECATED]Falta de suministros',
    {'Con la amenaza de múrlocs en la costa, nos hemos quedado aquí para proteger, o advertir si no podemos hacer más, de cualquier amenaza a Rocal. No nos deja mucho tiempo para relajarnos y nos vendría bien algo de ayuda...|n|nLas garras de sacudidores Denteserra son unas armas excelentes si se preparan bien. Tráeme algunas garras y te recompensaremos con una de nuestras armas como agradecimiento por la carne fresca y la buena compañía.', },
    {'Lleva 6 garras de sacudidores Denteserra a Tok\'Kar en el Pantano de las Penas.', },
  },
  [700] = {
    'Un homenaje real',
    {'Ah, esta piedra tan buena es de Lordaeron. Es una lástima que la tierra esté arrasada.|n|n¡Pero el monumento ha quedado muy bien! Creo que el Rey estará satisfecho.|n|nPor favor, ve a notificar a Su Majestad que el monumento ya está terminado.', },
    {'Preséntate ante el rey Magni Barbabronce.', },
  },
  [701] = {
    'La astucia del raptor',
    {'Con algunos elementos más, poder crear un objeto que imbuir Gor\'mul ¡con la astucia del raptor! Con el poder del raptor recorriéndolo, ¡Gor\'mul conocer nuevo poder y descubrir otra vez al guerrero durmiente en é!|n|nNecesitar corazones de raptor para componer el objeto y el hechizo.', },
    {'Consigue 12 corazones de raptor de los acechacarnes de las Tierras Altas para Tor\'gan.', },
  },
  [702] = {
    'La astucia del raptor',
    {'Toma este orbe y usa su energía para darle a Gor\'mul la esencia del raptor. Seguro que su ánimo recobrará el ímpetu y volverá a encontrarle sentido a la vida. Cuando vuelva a la normalidad, podremos explicarle el estado actual de la Horda y contaremos con la ayuda de un gran guerrero en nuestras incesantes batallas.', },
    {'Dale el orbe de Tor\'gan a Gor\'mul. Está en Sentencia, en las Tierras Altas de Arathi.', },
  },
  [703] = {
    'Alas de águila ratonera a la parrilla',
    {'¡Sí señor, mis alas de águila ratonera a la parrilla son para chuparse los dedos! La salsa es cremosa y la carne, penetrante. ¡Y su aroma atraerá a los hambrientos de kilómetros a la redonda!|n|nTengo todo lo necesario para cocinar una tanda. Todo... ¡excepto las alas de águila ratonera!|n|nSi quieres algunas, tráemelas. Consígueme suficientes alas de águila ratonera ¡y hasta podría compartir la receta contigo!', },
    {'Llévale 4 alas de águila ratonera a Aparejez.', },
  },
  [704] = {
    'El sino de Agmond',
    {'El último informe de Agmond es preocupante, ¡sobre todo ahora que ha muerto! Mencionaba que en sus excavaciones había desenterrado unas "urnas antiguas" en la explotación situada en las afueras de Uldaman. Me temo que las urnas que encontró instigaron a los troggs, igual que lo hicieron los ídolos que encontré aquí.|n|nNecesito que recuperes esas urnas para nuestros estudios. Ve a la excavación de Uldaman, encuentra las urnas y tráemelas aquí.', },
    {'Llévale 4 urnas de piedra labrada al prospector Vetaferro en Loch Modan.', },
  },
  [705] = {
    'La pesca de perlas',
    {'Las Tierras Inhóspitas son un lugar hostil, lleno de sanguinarios depredadores y de carroñeros sin escrúpulos. Aterrador, sobre todo para un diminuto goblin. Para sobrevivir, ¡tengo que ser astuto!|n|nConozco la receta de las bombas centelleantes. Las uso para espantar a los animales. Pero se me está acabando uno de los ingredientes: polvo de perla azul triturada. Consígueme un puñado y no te arrepentirás.|n|nEh, y espero que lleves puestas unas buenas botas. Las perlas azules que necesito se encuentran en unas almejas de El Arrecife Mortal.|n|nEse mismo, ¡El Arrecife Mortal de Tuercespina!', },
    {'Llévale 9 perlas azules a Aparejez en las Tierras Inhóspitas.', },
  },
  [706] = {
    'Encantamientos Llamarada ígnea',
    {'Cuando era aprendiz de Feranor Ferrodedo, aprendí su técnica especial para imbuir armas con encantamientos ígneos. Lo último que supe de él es que estaba trabajando en una herrería para una partida de cazadores en Lordaeron.|n|nNo puedo contarte demasiados detalles del proceso pero sí puedo decirte que requiere sangre del corazón de una cría de draco negro que aún esté latiendo. No estoy demasiado ocupado ahora, espero instrucciones de Forjaz. Si me traes un corazón de las crías del Barranco Lethlor, ¡te demostraré de lo que soy capaz!', },
    {'Consigue 1 corazón de draco negro para Sigrun Extracero.', },
  },
  [707] = {
    '¡Vetaferro te necesita!',
    {'$N, he recibido unos informes del prospector Vetaferro sobre la excavación de Loch Modan; dice que necesita a alguien que estudie otra excavación.|n|nNo dice nada más, pero si te apetece estirar las piernas, ve a hablar con Vetaferro.', },
    {'Habla con el prospector Vetaferro en la Excavación de Vetaferro en Loch Modan.', },
  },
  [708] = {
    'La caja negra',
    {'La superficie de esta caja negra metálica está muy hundida, como si la hubiesen sumergido en ácido, debe de haber pasado una buena temporada en el estómago del cóndor gigante.|n|nAl girar la caja, se ve un símbolo estampado en la parte inferior. Debajo del símbolo hay inscritas unas palabras:|n|n"Motor n.º 19 - Brigada de Asedio de Forjaz".', },
    {'Lleva la caja negra corroída a la Sala de Armas de Forjaz.', },
  },
  [709] = {
    'La solución a la maldición',
    {'¡Ay, ay! ¡Ay, ay! Se acerca una catástrofe. ¡Recuerda mis palabras! ¡Una catástrofe!|n|nNo, no puedo hablar de ello... no puedo pronunciar sus nombres, ¡podrían oírme! Pero si aprendemos de ellos... Sí, si aprendemos más... ¡quizás logremos frustrar sus planes!|n|nQuizás.|n|nVe a Uldaman. ¡No! ¡Ya te lo dije! Tienes que encontrar... encontrar la tablilla de... Ryun\'eh. ¡Sí, encuéntrala! ¡Y no me hagas pronunciar ese nombre otra vez!|n|nSe encuentra en las profundidades de ese lugar, en un antiguo cofre. Ahí es donde se esconde... en un cofre creado antes del tiempo de los enanos.', },
    {'Llévale la tablilla de Ryun\'eh a Theldurin el Perdido.', },
  },
  [710] = {
    'Estudio de los elementos: roca',
    {'Aquí en las Tierras Inhóspitas, he dejado de trabajar en mi más reciente proyecto: mis grilletes de esclavitud elemental.|n|nCuando acabe, permitirán a los magos invocar a elementales aún más poderosos para fines de más alcance. Para empezar, necesito fragmentos de piedra pequeños para probar mis más recientes hechizos ofensivos y unos aparatitos que he compuesto.|n|nEs fácil reunir tales fragmentos de los elementales de piedra inferiores hacia el oeste de este lugar. ¿Podrías traerme algunos?', },
    {'Encuentra 10 fragmentos de piedra pequeños y llévaselos a Lotwil Veriatus en las Tierras Inhóspitas.', },
  },
  [711] = {
    'Estudio de los elementos: roca',
    {'$N, has demostrado ya más valía que todos mis aprendices juntos.|n|nLas siguientes piezas que necesito requerirán algo más de fuerza. Si tienes cuidado, encontrarás grandes losas de piedra en los elementales de piedra. Sus cuerpos son más resistentes y voluminosos, así que tendrás más probabilidades de poder extraer piezas lo suficientemente grandes para mis pruebas. Los hallarás más hacia el oeste desde aquí o al sureste bordeando las faldas de las montañas.|n|nTómate tu tiempo; estaré ocupado probando estos fragmentos más pequeños que me has traído.', },
    {'Llévale 3 losas de piedra grandes a Lotwil Veriatus en las Tierras Inhóspitas.', },
  },
  [712] = {
    'Estudio de los elementos: roca',
    {'$N, necesito una pieza más de los elementales de las Tierras Inhóspitas: los brazales de vínculo de roca de los grandes elementales de piedra. Según mis cálculos, esos brazales deberían bastar para medir la fuerza de mis grilletes.|n|nMis intentos de visualizar a los grandes elementales de roca me mostraron un grupo de ellos al suroeste de aquí, cerca de unos ogros, si no me equivoco.|n|nTráeme 5 de sus brazales. Así tendré reservas. Servo es famoso por su facilidad para perder mis reactivos e investigaciones.', },
    {'Llévale 5 brazales de vínculo de roca a Lotwil Veriatus en las Tierras Inhóspitas.', },
  },
  [713] = {
    'Mantener la cabeza fría',
    {'Déjame decirte algo sobre el aceite de Escarcha: nada impide que un motor o un engranaje se recalienten como ese aceite.|n|nSus propiedades de enfriamiento son extraordinarias y su longevidad como lubricante no tiene parangón. Y eso no es todo: también ayuda a retener los encantamientos de los objetos mágicos.|n|nNecesito un frasco de este aceite para aumentar la capacidad mágica de mis grilletes y hacerlos lo suficientemente poderosos para impedir que nuestros amigos invocados nos maten a todos.|n|nBro\'kin, un amigo goblin, te enseñará a confeccionarlo. Se encuentra en Alterac.', },
    {'Encuentra aceite de Escarcha y llévaselo a Lotwil Veriatus en las Tierras Inhóspitas.', },
  },
  [714] = {
    'Un giro... ¿Qué?',
    {'$N, has hecho un trabajo más allá de toda expectativa.|n|n<Lotwil se ve claramente centrado en su trabajo.>|n|nSi por ventura nos volvemos a encontrar en Kharanos, pasa cuando quieras a por trabajo.|n|n¡Vaya! Rápido, agarra el... sí, eso. Gracias.|n|nBien, ahora solo necesito una cosa más. Es una pieza pequeña pero me temo que bastante crucial: un girocronátomo.|n|nSi pudieras hacerte con uno y traérmelo, estaré listo para completar esto.', },
    {'Llévale 1 girocronátomo a Lotwil Veriatus en las Tierras Inhóspitas.', },
  },
  [715] = {
    'Piedra líquida',
    {'Creo que esos objetos que conseguiste para Lotwil van a ser la menor de nuestras preocupaciones, $N. Por otro lado, has demostrados ser más que hábil en las ciencias que Lotwil considera sagradas, así que ¿te apetece ayudarme?|n|nNecesito una poción de invisibilidad y una poción curativa; ambas podrían venir bien muy pronto si le sale esto.|n|nA cambio, te daré esta receta para una poción en la que he estado trabajando mientras aprendías cosas de Lotwil. Se basa en parte de la investigación que ha realizado aquí en las Tierras Inhóspitas.', },
    {'Llévale 1 poción de sanación y 1 poción de invisibilidad inferior a Lucien Borlallave en las Tierras Inhóspitas.', },
  },
  [716] = {
    'Es mejor la piedra que la tela',
    {'Sé lo agarrado que Lotwil puede llegar a ser, $N, así que permite que te haga algo por las molestias. A lo mejor hasta te protege de la próxima atrocidad que será el más reciente invento de Lotwil.|n|nHe estado trabajando con todas las piedras sobrantes que habías recolectado para él y puedo hacerte unos buenos brazales que podrían serte de utilidad. Tienen un encantamiento, claro.|n|nSolo necesito brazales de bronce estampados confeccionados por un herrero para poder fabricar los brazales que te estoy haciendo.', },
    {'Llévale unos brazales de bronce estampados a Lucien Borlallave en las Tierras Inhóspitas.', },
  },
  [717] = {
    'Terremotos',
    {'Ha quedado claro que no podemos garantizar que Latigoscuro y Hematus permanezcan encarcelados en Lethlor. Que esos dragones Negros se adueñaran del lugar y que los ogros consiguieran robar el Signo indica que se deben tomar medidas más drásticas.|n|nLa prisión de los dracos está controlada por tres piedras rúnicas que solo se pueden extraer con el Signo de la Tierra. Esas piedras rúnicas pueden entonces usarse para romper el sello que los mantiene presos.|n|n$N,... asegúrate de que su sueño es eterno.', },
    {'Usa el Signo de la Tierra para activar los pilares de amatista, de ópalo y de diamante y así obtener las piedras rúnicas.|n|nColoca las piedras rúnicas en el Sello de la Tierra para liberar a Latigoscuro y a Hematus.|n|nMátalos y llévale a Garek las ataduras de Latigoscuro, las cadenas de Hematus y el Signo de la Tierra.', },
  },
  [718] = {
    'Espejismos',
    {'Con las prisas por marcharnos de la excavación de Uldaman, nos obligaron a abandonar muchos carros y muchas cajas de suministros por el camino. Los ogros locales del Asentamiento Kosh se han lanzado sobre nuestro equipo abandonado como buitres sobre un cadáver en descomposición. No huele mucho mejor tampoco. Me refiero a los cadáveres.|n|nSea como fuere, se llevaron el carro en el que se transportaban todas nuestras armas y tal y tal..., bueno, esto es un poco violento, no hemos podido conseguir nada de comida.|n|nEstamos metidos en un lío, ¿nos podrías ayudar?', },
    {'Recupera el cajón de suministros para Sigrun Extracero.', },
  },
  [719] = {
    'Un enano y sus herramientas',
    {'Hola, $N. Ten cuidado por estos lares. Hay enanos Hierro Negro por todas partes, parecía del clan Forjatiniebla.|n|nAcaban de atacar la excavación donde trabajaba, se han cargado a casi todos, hasta a mi jefe Piemartillo. Me escapé por los pelos.|n|nEl sitio está justo al norte de este lugar y estoy intentando planear la forma de recuperar parte de nuestros suministros, sobre todo mi pico de la suerte.|n|n¿Te apetecería echarme una mano? ¡Uno de esos malditos Hierro Negro tendrá mi pico! Podría ser cualquiera.', },
    {'Encuentra el pico de la suerte de Ryedol y llévaselo al prospector Ryedol al sur de la excavación de Piemartillo.', },
  },
  [720] = {
    'Un signo de esperanza',
    {'<Hay texto garabateado de forma tosca con tiza en el mapa.>|n|n"Ryedol, |nMe llevan a Uldaman. Envía ayuda.|n-Piemartillo"', },
    {'Localiza al prospector Ryedol y dile que Grez Piemartillo está vivo.', },
  },
  [721] = {
    'Un signo de esperanza',
    {'$N, ¿puedes encontrarlo? ¿Puedes encontrar a Piemartillo en Uldaman?|n|nSi esos asquerosos Forjatiniebla lo han raptado para sonsacarle lo que sabe de las excavaciones de los titanes, entonces todo Forjaz podría estar en gran peligro.|n|nDurante mucho tiempo esos Hierro Negro han buscado magia para hacer gólems más poderosos. Piemartillo estaba haciendo lo mismo, claro, pero para detenerlos.|n|nProbablemente lo mantengan vivo hasta que se enteren de lo que sabe. ¡Espabila si quieres salvarlo!', },
    {'Encuentra a Grez Piemartillo en Uldaman.', },
  },
  [722] = {
    'El amuleto de los secretos',
    {'Eres valiente... <tose>... por venir a Uldaman para mí, $C.|n|nSi realmente estás aquí para ayudar... al viejo Piemartillo, entonces... <tose>... tendrás que encontrar... mi amuleto.|n|nSombraprofunda lo tiene... Magregan Sombraprofunda. está por aquí... en las ruinas, seguro. Ese amuleto los conducirá... <tose>... derechito a los pergaminos si no lo paran. Depende de ti, $N. Por favor... recupera el amuleto.|n|nCon los pergaminos los Hierro Negro conseguirán crear gólems aún más poderosos. Lo sé. Me lo dicen los huesos.', },
    {'Encuentra el amuleto de Piemartillo y llévaselo a Uldaman.', },
  },
  [723] = {
    'Tener fe en el porvenir',
    {'<Piemartillo se sujeta las heridas y se toma un momento para recuperarse antes de seguir hablando.>|n|nEncuentra a Ryedol, $N. Llévale mi amuleto. <Tose> Él... <tose> saber qué hacer. Sabe que estaba buscando los orígenes de nuestro pueblo, y él <tose> sabe que mi misión era detener al clan Forjatiniebla. Hay que impedir que encuentren esos pergaminos... <tose>', },
    {'Llévale el amuleto de Piemartillo al prospector Ryedol en las Tierras Inhóspitas.', },
  },
  [724] = {
    'Tener fe en el porvenir',
    {'Vale, vale... ¿quién sabrá qué hacer?|n|n¡Karnik el Historiador! ¡Eso es!|n|nSe encuentra en Forjaz. Podrá ayudarnos. Él y Piemartillo estaban trabajando juntos para encontrar los artefactos en Uldaman.|n|nSupongo que los Forjatiniebla se enteraron de que los dos sabían más de lo que dejaban ver.|n|nDile a Karnik lo que le ha ocurrido a Piemartillo y dale el amuleto, él te dirá qué hacer después.', },
    {'Llévale el amuleto de Piemartillo a Karnik el Historiador en Forjaz.', },
  },
  [725] = {
    'Advertir de la amenaza',
    {'$N, corre y encuentra al consejero Belgrum en cuanto puedas. Cuéntale lo que has presenciado y pregúntale qué quiere que hagamos a continuación. En esta nota encontrará más detalles.|n|nMientras tanto, dedicaré un tiempo a hablar con el espíritu de Piemartillo. A lo mejor sabe algo que nos ayudará a detener las actividades de esos cretinos Forjatiniebla en las Tierras Inhóspitas. Solo nos queda rezar.', },
    {'Encuentra al consejero Belgrum y dale su nota.', },
  },
  [726] = {
    'Advertir de la amenaza',
    {'<El consejero Belgrum acaba de leer la nota, los ojos se le abren aún más por un momento.>|n|nVaya unas malas noticias.|n|n$N, regresa con Karnik el Historiador y dile que por la autoridad del rey actúe pronto y de forma contundente sobre la base de esta información. Tiene que detener las actividades de los Forjatiniebla en las Tierras Inhóspitas.', },
    {'Habla con Karnik el Historiador.', },
  },
  [727] = {
    'Ir a Forjaz a buscar el "Compendio" de Yagyin',
    {'La tablilla es muy reveladora. ¡Aunque no lo suficiente! ¡Ni de lejos!|n|nHay un cuaderno, un compendio que Yagyin escribió en otros tiempos. La... gente de los que huí... guardan este cuaderno en muchos lugares. Y sus más eruditos lo estudian. El conocimiento en él contenido es muy vasto. ¡Conocimiento para protegernos!|n|nVe a ver a Gerrig Agarrahueso. Se encuentra en una tienda de Forjaz, en La Caverna Abandonada. Muéstrale este sigilo y creerá que eres de los suyos. Pregúntale por el Compendio de Yagyin... ¡y tráemelo!', },
    {'Dale el sigilo del Martillo a Gerrig Agarrahueso en La Caverna Abandonada de Forjaz.', },
  },
  [728] = {
    'Ir a Entrañas a buscar el "Compendio" de Yagyin',
    {'La tablilla es muy reveladora. ¡Aunque no lo suficiente! ¡Ni de lejos!|n|nHay un cuaderno, un compendio que Yagyin escribió en otros tiempos. La... gente de los que huí... guardan este cuaderno en muchos lugares. Y sus más eruditos lo estudian. El conocimiento en él contenido es muy vasto. ¡Conocimiento para protegernos!|n|nVe a ver al vigilante Bel\'dugur en Entrañas, Lordaeron. Muéstrale este sigilo y creerá que eres de los suyos. Pregúntale por el Compendio de Yagyin... ¡y tráemelo!', },
    {'Llévale el sigilo del Martillo al vigilante Bel\'dugur en Entrañas.', },
  },
  [729] = {
    'El prospector despistado',
    {'Fue un honor que el maestro Mostachogris me destinara a trabajar bajo la guía del gran prospector Tripirrem. En la Academia de Forjaz todo el mundo sabía de los grandes descubrimientos de Tripirrem.|n|nPero el prospector es un poco... mm... despistado... Vive en su mundo.|n|nPor ejemplo: habíamos descubierto pruebas de la existencia de una gran sociedad. Y un día, unos terribles gólems surgieron de la tierra e invadieron la excavación. Y Tripirrem ni se dio cuenta. Yo corrí a Auberdine a pedir ayuda.|n|n¡Te lo ruego, viaja hacia el sur y asegúrate de que el prospector está bien!', },
    {'Viaja al sur y asegúrate de que el prospector Tripirrem está bien.', },
  },
  [730] = {
    '¿Problemas en Costa Oscura?',
    {'Me agrada ver a $Gun:una; $C mostrando interés por las grandes maravillas arqueológicas de nuestro mundo.|n|nA menudo nuestro trabajo es considerado poco más que una afición por nuestros amigos de la Alianza. Pero es porque no se dan cuenta de que son los recientes descubrimientos de Khaz Modan los que han probado que una poderosa fuerza amenaza todo Azeroth, de Lordaeron a Kalimdor.|n|nEmpiezo a preocuparme de verdad por el personal que envié a Costa Oscura. Hace semanas que no tengo noticias suyas.|n|nViaja a Auberdine y busca pistas de su paradero.', },
    {'Viaja a Auberdine y busca rastros del equipo de excavación enano.', },
  },
  [731] = {
    'El prospector despistado',
    {'Dime, Hollee... ah, no, que no eres Hollee. ¿Dónde está Hollee?|n|nDeja, total, no es importante. Tenemos que encontrar ese cepillo de piedra... Quiero decir, el fósil misterioso. Tenemos que encontrar ese fósil. La Liga de Expedicionarios de Darnassus querrá algún informe de lo que he estado haciendo.|n|nAvísame cuando estés $Glisto:lista;. Iremos a la caza de ese cepillo. Quiero decir, ¡del fósil! Así encontraremos algo palpable para satisfacer a la Liga.|n|n¿Estás $Glisto:lista;?', },
    {'Protege al prospector Tripirrem mientras busca el fósil misterioso. Luego vuelve a Auberdine y busca a la arqueóloga Hollee.', },
  },
  [732] = {
    'Terremotos',
    {'Sigrun me ha dicho que habías sido de gran ayuda para él. Quizás te reclute para ayudarme. Mi maestro, Krasus del Kirin Tor, me envió aquí para poner fin a los disturbios que se estaban produciendo en Barranco Lethlor.|n|nNo puedo revelarte la naturaleza exacta de mi misión aquí ni de las tareas que debo acometer pero ten por seguro que son de vital importancia.|n|nUn grupo de ogros errantes, avistados en ocasiones cerca del Asentamiento Boff, robaron un objeto llamado el Signo de la Tierra; debo recuperarlo. Tráemelo y te contaré más detalles.', },
    {'Recupera el Signo de la Tierra para Garek.', },
  },
  [733] = {
    '¡A gorronear!',
    {'La cosa se va a poner fea aquí si no logro gorronear algunos materiales para construir unas defensas y otras necesidades. Me he dado cuenta de que los ogros de la zona parecen estar bien surtidos de chatarra. A lo mejor las historias de máquinas de asedio en las Tierras Inhóspitas no estaban muy alejadas de la realidad después de todo...|n|nEn cualquier caso, el prospector lleva un tiempo preocupado por el estado de nuestro campamento, así que debería ponerme manos a la obra pronto si es posible.|n|nEl principal campamento de ogros está en la Gruta Rotapolvo, una buena caminata hacia el oeste desde aquí.', },
    {'Consigue 7 restos de armadura para Sigrun.', },
  },
  [734] = {
    'Lo tienes crudo',
    {'¡Pero qué maravilla!|n|n<Lotwil te dedica una mirada breve antes de centrarse de nuevo en sus grilletes.|n|nVe a hablar con Lucien, $N. Necesito un piñón del n.º 5. ¿Me lo traerás?', },
    {'Habla con Lucien Borlallave en las Tierras Inhóspitas.', },
  },
  [735] = {
    'La Estrella, la Mano y el Corazón',
    {'El Compendio de Yagyin, ¿eh? ¿Se ha empezado a escribir otro capítulo sobre nosotros? Disculpa, no debería haber preguntado.|n|nTe ayudaré porque tengo dos ejemplares. Hay que ayudarse mutuamente, ¿eh? Así es como se prospera.|n|nQuiero tres objetos de poder. Tráemelos y te daré el Compendio.|n|nNo voy a decir los nombres en alto, nunca se sabe quién está escuchando. Te los voy a escribir.', },
    {'Devuelve los objetos de la lista a Gerrig Agarrahueso a Forjaz.', },
  },
  [736] = {
    'La Estrella, la Mano y el Corazón',
    {'¿Necesitas el Compendio de Yagyin? Así que, ¿tu plan es reunir a otro grupo? Claro que sí... y por supuesto te ayudaré, $Ghermano:hermana;.|n|nPero tendrás que darme algo a cambio.|n|nNecesito tres objetos de poder. Tráemelos y el compendio será tuyo.|n|nNo puedo decir en alto sus nombres así que te los escribiré.|n|nSi me consigues los objetos de esta lista, serás verdaderamente $Gmerecedor:merecedora; de crear tu propia sección dentro de nuestra orden.', },
    {'Llévale los objetos que aparecen en la nota de Bel\'dugur al vigilante Bel\'dugur de Entrañas.', },
  },
  [737] = {
    'El saber prohibido',
    {'Aquí tienes la revista, $N. Huelga decir que debes extremar el cuidado con ella. Además de mantenerla alejada de manos enemigas.|n|nEste cuaderno contiene muchas verdades...|n|n... Y la verdad puede encender chispas.', },
    {'Llévale el compendio de Yagyin a Theldurin.', },
  },
  [738] = {
    'Encontrar a Agmond',
    {'El prospector Agmond estaba a cargo de nuestra excavación en las Tierras Inhóspitas, hacia el suroeste. Y digo "estaba" porque... bueno, hace semanas que no sé nada de él. Necesito que encuentres a Agmond para poder conseguir su informe.|n|nLa última vez que oímos algo de Agmond se encontraba en la más meridional de nuestras excavaciones en las Tierras Inhóspitas, una pequeña explotación más allá de la Fortaleza de Angor. Yo empezaría a buscarlo allí.', },
    {'Encuentra a Agmond.', },
  },
  [739] = {
    nil,
    {'La pista de Agmond arranca en el oeste. Es fácil saber por las manchas de sangre en las rocas y en la arena que el enano se arrastró cierta distancia.|n|nY murió aquí.|n|nTras una inspección más detenida, se descubre la palabra "Murdaloc" toscamente garabateada en un pedazo de arenisca de las Tierras Inhóspitas.|n|nGarabateada junto a la inerte mano de Agmond.', },
    {'Mata al asesino de Agmond, Murdaloc.|n|nMata a 12 Cascahuesos Petracripta.|n|nPreséntate ante el prospector Vetaferro en Loch Modan.', },
  },
  [740] = {
    nil,
    {'Esta misión llevará a los jugadores a La Garganta de Fuego.|n|nSeguiremos informando...', },
    nil,
  },
  [741] = {
    'El prospector despistado',
    {'¿Así que el prospector quiere mandar el misterioso fósil a la Liga de Expedicionarios de Darnassus? No me gusta la idea de irme de Costa Oscura sin él.|n|nTen, $N, ve a Darnassus y entrega el misterioso fósil al arqueólogo jefe Mostachogris.', },
    {'Ve a Darnassus y entrega el fósil misterioso al arqueólogo jefe Mostachogris.', },
  },
  [742] = {
    'La Caza de Vallefresno',
    {'¡Atención, jóvenes aventureros! ¡Los páramos de Vallefresno os esperan!|n|nLa Horda ha aumentado su presencia en las tierras al norte de Los Baldíos. Nuestras dos avanzadas, Puesto del Hachazo y La Ensenada de Zoram, se esfuerzan por traer gloria a la Horda. Aquellos que deseen demostrar su valía deben buscar ayuda allí. Nota: Senani Corazón Atronador del Puesto del Hachazo, al norte de Los Baldíos, busca a aventureros que deseen participar en la gran Caza de Vallefresno.', },
    {'Habla con Senani Corazón Atronador en Puesto del Hachazo, en Vallefresno.', },
  },
  [743] = {
    'Las Viento Furioso son un peligro',
    {'Te agradezco que te pares a hablar conmigo, $N. Me llamo Ruul y soy guerrero y maestro.|n|nHas alcanzado la edad en la que debes prepararte para las pruebas que te esperan si quieres ir más allá de Mulgore.|n|nPara poner a prueba tu fuerza, ve al sureste a enfrentarte a las arpías Viento Furioso. Sus nidos están en los bordes de la montaña, alejados del camino.|n|nSon enemigas naturales de Mulgore y serán un buen indicativo de tu habilidad.', },
    {'Lleva 8 garfas de Viento Furioso a Ruul Garra de Águila al Poblado Pezuña de Sangre.', },
  },
  [744] = {
    'Preparación para la ceremonia',
    {'$N, mi hermano pronto se personará ante el jefe Pezuña de Sangre y será un honor para mí prepararle su penacho.|n|nMe gustaría pedirte un favor mientras acabo de curtir estas cintas de piel. No he podido reunir todas las plumas que necesito y me preguntaba si tú podrías ayudarme a conseguir más.|n|nPuedes obtener las plumas del tamaño adecuado de las arpías que habitan al norte y noroeste de Cima del Trueno. Solo necesito 6 plumas azur y 6 de bronce para completar mi diseño.', },
    {'Consigue 6 plumas azur y 6 de bronce.', },
  },
  [745] = {
    'Compartir la tierra',
    {'$N, esta tierra está herida por muchos conflictos. Espero que no tengas que presenciar tantos como yo en mi vida. Sin embargo, te pido que vayas a uno. Verás lo peligrosa que puede ser cualquier amenaza, por pequeña que sea, si no se ataja de inmediato.|n|nUnos gnolls Crines Pálidas se han instalado al sur de Pezuña de Sangre y en una cueva del oeste. No respetan nuestros intentos de establecer comunicación y matan a placer por todo Mulgore.|n|nLas palabras ya no sirven de nada.', },
    {'Mata a 10 curtidores, 8 desolladores y 5 furtivos Crines Pálidas y vuelve al Poblado Pezuña de Sangre para hablar con Baine Pezuña de Sangre.', },
  },
  [746] = {
    'Una excavación de los enanos',
    {'Al noroeste hay enanos preparando una excavación. Creen que la tierra está llena de secretos y eso es cierto, pero perforarla no es la mejor manera de descubrirlos.|n|nEncuentra las herramientas de los enanos, rómpelas y tráeme los pedazos.|n|nNecesitarás una forja para romperlas. Hay una en Cima del Trueno, pero te servirá cualquiera, incluso la del campamento enano.', },
    {'Recoge 5 picos de prospector. |n|nBusca una forja para destrozar los picos. |n|nLleva 5 trozos de herramienta rota a Baine Pezuña de Sangre al Poblado Pezuña de Sangre.', },
  },
  [747] = {
    'Empieza la caza',
    {'Tienes un aire prometedor, demostrarás tu valía ante la tribu. Puede que pronto te acojan en la gran ciudad de Cima del Trueno. Pero antes de eso, tendrás que mostrar tu valía ante mi padre, el Jefe Viento de Halcón.|n|nAquí en Mesa de la Nube Roja estamos orgullosos de nuestra habilidad para la caza. Los tauren cazamos por necesidad y por deporte. Nos estamos quedando sin carne y necesitamos plumas para la ropa. Caza zancudos de llanura y demuestra tu valor mientras reabasteces al poblado.', },
    {'Grull Viento de Halcón quiere que le lleves 7 plumas y 7 piezas de carne de zancudo de llanura al Campamento Narache.', },
  },
  [748] = {
    'Pozos envenenados',
    {'¡Los goblins han mancillado nuestros pozos de agua sagrada! No podemos permitirlo.|n|nPara limpiarlos necesito un tótem de limpieza; tú lo llevarás al pozo y realizarás el ritual de limpieza.|n|nEl primer tótem es para el Pozo Pezuña Invernal. Necesitamos la ayuda de la tierra. Tráeme zarpas de lobo de pradera y espolones de zancudo de llanura adulto. Los encontrarás al suroeste.|n|nSé prudente, $N.', },
    {'Lleva 6 zarpas de lobo de pradera y 4 garfas de zancudo de llanura a Mull Tronacuerno al Poblado Pezuña de Sangre.', },
  },
  [749] = {
    'La Caravana Devastada',
    {'Hace unos días nos encontramos una caravana escoltada de Ventura y Cía. en la costa norte del Lago Toro de Piedra. En un combate anterior habíamos perdido a dos de los nuestros, así que atacamos la caravana.|n|nDejamos las cajas porque lo incendiamos todo, pero hemos visto a rescatadores de Ventura y Cía. cerca de las carretas quemadas; quizás quedó algo de valor.|n|nPodrías acercarte a ver qué hay en las cajas.', },
    {'Morin Acechanubes quiere que registres las cajas de la Caravana Devastada.', },
  },
  [750] = {
    'La caza sigue',
    {'Un buen cazador tauren sabe que la presa no es un mero trofeo. Los animales de la llanura son nuestro medio de subsistencia. Si quieres impresionar a los ancestros, trae algunas pelambres de puma montés; son muy valiosas. Los pumas viven en esas colinas hacia el sur.|n|nLos niños necesitan ropa y tenemos que reparar las carpas.', },
    {'Grull Viento de Halcón quiere que le lleves 10 pelambres de puma montés al Campamento Narache.', },
  },
  [751] = {
    'La Caravana Devastada',
    {'Al abrir la caja ves que está llena de mineral, otra prueba de las operaciones mineras de Ventura y Cía. en Mulgore. Coges el paquete de documentos que hay encima del mineral.|n|nEn las laderas del este se oyen ruidos de actividad industrial y se ve una columna de humo.', },
    {'Lleva los documentos de Ventura y Cía. a Morin Acechanubes cerca del Poblado Pezuña de Sangre.', },
  },
  [752] = {
    'Una humilde contribución',
    {'Todos los miembros de la tribu contribuyen a la armonía de la vida. Vivimos juntos y trabajamos juntos.|n|nCada uno de nosotros es responsable del bienestar de los demás. Quisiera pedirte un pequeño favor.|n|nMi madre se fue esta mañana a coger agua del pozo que hay al sureste de Narache. Ya ha pasado un buen rato. ¿Podrías ir a buscarla mientras yo atiendo los asuntos de la tribu?', },
    {'El Jefe Viento de Halcón quiere que vayas a buscar a su madre cerca del pozo que hay al sureste del Campamento Narache.', },
  },
  [753] = {
    'Una humilde contribución',
    {'He recorrido muchos caminos en la vida, mis piernas ya no son fuertes. Todavía puedo ser útil para la tribu, es solo que tardo un poco más en hacer las cosas.|n|nPero tú rebosas vitalidad, $C. Vamos a ponerla a prueba; llena un cántaro en el pozo y llévaselo a mi hijo, el jefe del Campamento Narache.|n|nRecuerda que incluso el más insignificante servicio puede valerte el respeto de los ancestros.', },
    {'Llena un cántaro de agua en el pozo. |n|nLlévaselo al Jefe Viento de Halcón al Campamento Narache, que está al noroeste del pozo.', },
  },
  [754] = {
    'La purificación de Pezuña Invernal',
    {'Este es el tótem para el Pozo Pezuña Invernal. Llévalo al pozo y lleva a cabo el ritual de limpieza. El pozo está hacia el sureste y en poder de los repugnantes goblins.|n|nEs una misión difícil, pero no podemos perder el acceso a los pozos.|n|nSuerte, $N.', },
    {'Usa el tótem de limpieza en el Pozo Pezuña Invernal y ve a ver a Mull Tronacuerno.', },
  },
  [755] = {
    'Los ritos de la Madre Tierra',
    {'Tu buena disposición y entusiasmo por ayudar a los tauren de Narache te ennoblecen, $N. Creo que un día se te aclamará en Cima del Trueno con grandes honores como $C.|n|nPero antes de eso, debes cumplir con los tres Ritos de la Madre Tierra.|n|nLa primera prueba es el Rito de la Fuerza. Ve a ver al vidente Lenguagris y dile que vas de parte del Jefe Viento de Halcón.|n|nSu morada está al sur del Campamento Narache, escondida entre las colinas.', },
    {'Ve a ver al vidente Lenguagris, que vive en las colinas al sur del Campamento Narache.', },
  },
  [756] = {
    'El tótem de Tronacuerno',
    {'Para crear el tótem para el Pozo Tronacuerno necesitamos las garras de los depredadores de Mulgore. Tráeme garras de acechador de pradera y puma de las estepas.|n|nLos encontrarás tanto hacia el este como hacia el oeste.', },
    {'Lleva 6 garras de acechador y 6 garras de puma a Mull Tronacuerno.', },
  },
  [757] = {
    'Rito de la fuerza',
    {'Los Ritos de la Madre Tierra son los pasos con los que un joven tauren se gana el respeto de Cima del Trueno.|n|nEl primero que debes superar es el Rito de la Fuerza, con el que pruebas tu valor al matar enemigos de la tribu.|n|nLos Erizapúas del Barranco Cortazarza se están instalando en nuestro terreno de caza tribal. Atacan por emboscada a nuestros cazadores y roban en el poblado durante la noche.|n|nPara demostrar tu valor, acaba con esos villanos y entrega sus cinturones al jefe del Campamento Narache como prueba.', },
    {'Mata a varios Erizapúas en el Barranco Cortazarza y lleva 12 cinturones Erizapúas al Jefe Viento de Halcón al Campamento Narache.', },
  },
  [758] = {
    'La purificación de Tronacuerno',
    {'$N, el tótem ya está listo. Debes llevar a cabo el ritual una vez más.|n|nLlévate el tótem al Pozo Tronacuerno, que está al norte. Vuelve aquí cuando termines.|n|nQue los espíritus te acompañen.', },
    {'Usa el tótem de limpieza en el Pozo Tronacuerno y ve a ver a Mull Tronacuerno.', },
  },
  [759] = {
    'El tótem Ferocrín',
    {'Ya solo queda por limpiar el Pozo Ferocrín. Para ello, la tierra debe ofrecernos los dientes de un depredador feroz, el lobo alfa de pradera. Los encontrarás al norte. Vuelve cuando hayas conseguido los dientes.|n|nLos alfa suelen deambular alrededor de nuestra ciudad, Cima del Trueno.', },
    {'Lleva 8 dientes de alfa de pradera a Mull Tronacuerno al Poblado Pezuña de Sangre.', },
  },
  [760] = {
    'La purificación de Ferocrín',
    {'Los espíritus están complacidos contigo por la limpieza del Pozo Tronacuerno y el Pozo Pezuña Invernal, joven $N. El tótem de Ferocrín ya está listo y tu última tarea te espera.|n|nEl Pozo Ferocrín está al norte de Cima del Trueno. ¡Lleva a cabo el ritual! ¡Limpia la tierra del veneno de los Tótem Siniestro! Que las aguas vuelvan a fluir puras y claras.', },
    {'Usa el tótem de limpieza Ferocrín en el Pozo Ferocrín.', },
  },
  [761] = {
    'La caza de los aguilones',
    {'El aguilón es un ave muy astuta, difícil de encontrar y de cazar. Un trofeo de plumas de aguilón sería una prueba de tu talento cazador.|n|nVe a las llanuras y caza uno.|n|nTráeme las plumas y gana honor para tu clan.|n|nEstán por todo Mulgore, pero tendrás que estar ojo avizor para verlos y muy veloz para cazarlos.', },
    {'Lleva 8 péñolas trofeo de aguilón a Harken Tótem de Viento al Poblado Pezuña de Sangre.', },
  },
  [762] = {
    'Un embajador del mal',
    {'El propio Ragnaros envió al embajador Infernus a la Fortaleza de Angor para controlar a los Forjatiniebla en su búsqueda de artefactos perdidos en Uldaman.|n|nHa supuesto ya gran número de bajas entre nuestra gente pero, a todas luces, ha empeorado. Dudo en adelantar una cifra respecto a cuántos artefactos habrán encontrado y usarán contra Forjaz.|n|nNuestro objetivo es sencillo, $C. Vuelve a Tierras Inhóspitas y acaba con el embajador Infernus. Una vez eliminada la amenaza, vuelve con el consejero Belgrum con una prueba de tu victoria.|n|nAhora todo depende de ti.', },
    {'Mata al embajador Infernus en la Fortaleza de Angor y llévale la prueba de su muerte al consejero Belgrum en Forjaz.', },
  },
  [763] = {
    'Los ritos de la Madre Tierra',
    {'Si quieres seguir con los Ritos de la Madre Tierra tendrás que pasar otras dos pruebas. Debes ampliar tu experiencia, $N.|n|nVe al Poblado Pezuña de Sangre y habla con el Jefe Baine Pezuña de Sangre, hijo de Cairne Pezuña de Sangre. Allí podrás seguir tu viaje y ganarte la aceptación de los ancestros de Cima del Trueno.|n|nDale a Baine Pezuña de Sangre este tótem. Reconocerá mis grabados y te ayudará.|n|nSigue el camino que sale del Campamento Narache. Viaja deprisa y no te desvíes o te perderás.', },
    {'Lleva el tótem de Alalcón a Baine Pezuña de Sangre al Poblado Pezuña de Sangre. Sigue el camino que sale del Campamento Narache.', },
  },
  [764] = {
    'Los Ventura y Cía.',
    {'Esto explica el aumento de personal y equipamiento de Ventura y Cía. que hemos visto en Mulgore. Esos goblins... su empresa se expande demasiado rápido y contra su conveniencia. Ya conoces el dicho, enséñale algo a un goblin, y escucharás el sonido de fondo de la balanza.|n|nSon unos bichejos de lo más codiciosos. Por desgracia para sus negocios, los tauren no permitiremos que lleven a cabo sus operaciones en nuestras tierras. Dirígete a su mina, al noreste de la caravana saqueada y envíales un mensaje.', },
    {'Mata a 14 trabajadores de Ventura y Cía. y a 6 supervisores de Ventura y Cía. para Morin Acechanubes en Poblado Pezuña de Sangre.', },
  },
  [765] = {
    'Supervisor Saltatuercas',
    {'Según los documentos que recuperaste de la caravana, Ventura y Cía. ideó varios planes para tratar de echarnos de nuestras tierras, y así tener libertad total para saquearlas.|n|nLos límites a los que estaban dispuestos a llegar para conseguir sus objetivos me asquean. Quiero ver muerto al cerebro que ideó estos planes. Se llama supervisor Saltatuercas y lo encontrarás en la Mina Ventura y Cía., al este de la caravana saqueada. Tráeme su sujetapapeles y veremos si encontramos algo útil.', },
    {'Mata al supervisor Saltatuercas y lleva su sujetapapeles a Morin Acechanubes al Poblado Pezuña de Sangre.', },
  },
  [766] = {
    nil,
    {'Mi abuelo solía contarme historias sobre sus batallas con un zancudo llamado Mazzranache. Me hablaba de sus demoníacos ojos rojos, de sus afiladas garras y de su mordedura venenosa.|n|nLa casualidad quiso que, mientras viajaba por las llanuras, me lo encontrase; y me diese un terrible mordisco en el hombro. Era tan espantoso como mi abuelo solía describirlo. Para desinfectar la herida necesito unas cuantas cosas: un corazón de lobo, un fémur de puma, escamas de zancudo de llanura y una molleja.|n|nApresúrate, el tiempo corre.', },
    {'Lleva un corazón de lobo de pradera, un fémur de puma de las estepas, una escama de zancudo de llanura y una molleja de aguilón a Maur Clamalluvias en el Poblado Pezuña de Sangre.', },
  },
  [767] = {
    'Rito de la Visión',
    {'El Rito de la Visión, uno de los Ritos de la Madre Tierra, te enseñará cómo ganar el respeto de los ancestros de Cima del Trueno.|n|nNuestra gente ha aprendido que la tierra es la sagrada proveedora. Para tomar parte en la visión ritual, debes hablar con el guía espiritual de la aldea, Zarlman Dos Lunas.', },
    {'Habla con Zarlman Dos Lunas en el Poblado Pezuña de Sangre.', },
  },
  [768] = {
    'Recolecta cuero',
    {'Saludos, joven. El brillo en tus ojos me indica que estás impaciente por continuar la caza. ¡Ojalá traigas honor a tu clan!|n|nYo trabajo con pieles y con ellas confecciono ropajes y armaduras para las gentes de Cima del Trueno.|n|nSi cazas bestias y me traes sus pieles, confeccionaré algo especialmente para ti.', },
    {'Llévale 12 pieles de cuero ligero a Veren Zancaalta a Cima del Trueno.', },
  },
  [769] = {
    'Bolsa de pellejo de kodo',
    {'Los kodos de Mulgore son fuertes y robustos, unas cualidades que apreciamos mucho. Si tienes conocimientos de peletería y deseas aprender a fabricar una bolsa de piel de kodo, tráeme suministros para mi oficio.|n|nHazlo y compartiré mis conocimientos contigo.', },
    {'Llévale 4 pellejos de cuero ligero y 4 hilos gruesos a Veren Zancaalta a Cima del Trueno.', },
  },
  [770] = {
    'La capa del demonio marcado',
    {'La piel destrozada de Aullido Fantasma muestra la terrible herida que recibió en combate contra la Legión Ardiente.|n|nHabría que avisar de su muerte en el Campamento Rasguño de Sol...', },
    {'Busca a alguien que conozca a Aullido Fantasma.', },
  },
  [771] = {
    'Rito de la Visión',
    {'Para superar el Rito de la Visión debes conseguir los componentes necesarios para crear el Agua de los Videntes.|n|nNecesito piedras de pozo, que encontrarás cerca de los pozos de Mulgore. Las mezclaré con bellota ámbar, que cae de los orgullosos árboles de nuestra tierra.|n|nEstos ingredientes son mágicos; tómate el elixir resultante junto a la hoguera tribal para tener una visión. Síguela y te llevará al siguiente paso de esta misión sagrada.', },
    {'Lleva 2 piedras de pozo y 2 bellotas ámbar a Zarlman Dos Lunas al Poblado Pezuña de Sangre.', },
  },
  [772] = {
    'Rito de la Visión',
    {'Aquí tienes el Agua de los Videntes.|n|nTómatela cerca de la hoguera tribal. Al cabo de un momento la visión se materializará junto a la hoguera.|n|nA partir de ahí, de ti depende el seguirla...', },
    {'Bebe el Agua de los Videntes frente a la hoguera tribal del Poblado Pezuña de Sangre y sigue a la visión cuando aparezca.', },
  },
  [773] = {
    'Rito de la Sabiduría',
    {'Para que los ancestros de Cima del Trueno te acepten, tienes que superar el Rito de la Sabiduría.|n|nAhora que has superado el Rito de la Visión, los espíritus ancestrales de Roca Roja te darán las bendiciones de los ancestros. Solo quien ha bebido el Agua de los Videntes merece recibir la bendición.|n|nVe a Roca Roja, al este de Cima del Trueno, y busca al espíritu ancestral, $N.', },
    {'Ve a Roca Roja, al este de Cima del Trueno, y busca al espíritu ancestral.', },
  },
  [775] = {
    'Viaje a Cima del Trueno',
    {'Se te venerará en nuestra gran ciudad. Te mereces tal honor, $R, pues has completado los Ritos de la Madre Tierra.|n|nTu última misión consiste en buscar a nuestro noble jefe, Cairne Pezuña de Sangre, que vive en la cima de la mesa más alta de Cima del Trueno.', },
    {'Habla con Cairne Pezuña de Sangre en Cima del Trueno.', },
  },
  [776] = {
    'Los ritos de la Madre Tierra',
    {'Has superado los Ritos de la Madre Tierra y te has ganado un lugar en Cima del Trueno.|n|nPero no puedes dormirte en los laureles; debes probar tu valor constantemente.|n|nSomos cazadores, $N. En Mulgore vive un hermoso kodo que se llama Arra\'chea. Tráeme el cuerno de Arra\'chea para demostrarme tu habilidad para rastrear y cazar.', },
    {'Cairne Pezuña de Sangre de Cima del Trueno quiere que le lleves el cuerno de Arra\'chea.', },
  },
  [777] = {
    'Lo tienes crudo',
    {'Muy bien, aquí tienes.|n|nEstaré por aquí... a cubierto.|n|nSi quieres, puedes unirte a mí.', },
    {'Llévale un piñón del n.º 5 a Lotwil Veriatus.', },
  },
  [778] = {
    'Lo tienes crudo',
    {'¡Ea! ¡Ya está! ¡Los grilletes están listos!|n|nEs la hora, Lucien. ¡Es la hora, Servo!|n|n¿Estás $Gpreparado:preparada; para ser testigo de la perfecta combinación de alquimia, ingeniería y lo arcano, $N?|n|nAhora voy a invocar a un poderoso elemental. Este es un día marcado por la innovación para todos nosotros.', },
    {'Derrota al guardián Fam\'retor y devuélvele los grilletes de vínculo elemental a Lotwil Veriatus.', },
  },
  [779] = {
    'El Sello de la Tierra',
    nil,
    nil,
  },
  [780] = {
    'Los jabaguerreros',
    {'Los jabaguerreros del Barranco Cortazarza se están instalando en nuestro terreno de caza tribal. Los jabaespines Erizapúas, con quienes estamos en guerra, los amaestran para aumentar su ferocidad.|n|nAcaba con esas bestias y trae algunos hocicos y costillares para hacer caldo.', },
    {'Grull Viento de Halcón quiere que le lleves 8 hocicos y 8 costillares de jabaguerrero al Campamento Narache.', },
  },
  [781] = {
    'Ataque al Campamento Narache',
    {'Tras estudiar cuidadosamente el mapa, te das cuenta de que lo que has descubierto son los planes del jefe Erizapúas para un asedio prolongado sobre el Campamento Narache.|n|n¡Seguro que al jefe Viento de Halcón le hace falta esta información!', },
    {'Lleva los planes de ataque Erizapúas al jefe Viento de Halcón al Campamento Narache.', },
  },
  [782] = {
    'Alianzas rotas',
    {'Por la alianza de la Horda con el dragón Alamuerte durante la Segunda Guerra, sabemos que dos de sus tenientes, Latigoscuro y Hematus, estaban encarcelados en el Barranco Lethlor, un lugar remoto hacia el este. ¡Debemos acallar a nuestros depravados aliados ancestrales para restaurar el honor de la Horda!|n|nContratamos a Tho\'grun y a su grupo de ogros mercenarios para que nos ayuden a conseguir el Signo de la Tierra, una llave necesaria para desbloquear la cárcel de los dragones. Pero Tho\'grun nos traicionó, nos aplastó y se lo quedó. ¡Ve al Asentamiento Boff y recupéralo!', },
    {'Mata al jefe Tho\'grun y llévale el Signo de la Tierra a Gorn en Kargath.', },
  },
  [783] = {
    '[DEPRECATED] Una amenaza del interior',
    nil,
    {'Habla con el alguacil McBride.', },
  },
  [784] = {
    'Vencer a los traidores',
    {'Bajo el mando del almirante Valiente, los humanos de Kul Tiras invadieron Durotar, violando el pacto que el Jefe de Guerra selló con Jaina Valiente años atrás para derrotar a Archimonde.|n|nEl ataque humano fue rechazado y el Fuerte de Tiragarde cayó. Pero las reservas del Almirante, comandadas por el teniente Benedict, han retomado el fuerte y vuelven a amenazar nuestro territorio. Los humanos no tienen respeto alguno por la diplomacia.|n|nPor tu honor, viaja al sur hasta el Fuerte de Tiragarde y acaba con los invasores humanos.', },
    {'Mata a 10 navegantes Kul Tiras, 8 marineros Kul Tiras y al teniente Benedict. Luego vuelve a buscar a Gar\'Thok a Cerrotajo.', },
  },
  [785] = {
    'Una alianza estratégica',
    {'Thrall es un líder sabio y noble. Su tenacidad en el campo de batalla solo es comparable a su diplomacia.|n|nLos trols Lanza Negra han demostrado ser unos valiosos aliados para los orcos. Hemos sellado un pacto de protección con ellos basado en la lealtad y el honor.|n|nEl Jefe de Guerra ha dado instrucciones de que nos aseguremos que nuestros amigos Lanza Negra del Poblado Sen\'jin no están bajo amenaza directa. Uno de sus exploradores de confianza, Lar Colmillo Acechador está vigilando el flanco occidental.|n|nBusca a Lar y ayúdale en lo que necesite.', },
    {'Busca a Lar Colmillo Acechador en el flanco oeste del Poblado Sen\'jin.', },
  },
  [786] = {
    'Frustrar los planes kolkar',
    {'Baja la voz, $C. Los centauros Kolkar están justo al otro lado de este promontorio, al oeste, en el Risco Kolkar.|n|nLa otra noche, cuando estaban fuera, en una de sus batidas, me colé en su poblado y descubrí que esas bestias inmundas tienen planeado un ataque en tres oleadas contra los trols y orcos de Durotar.|n|nDebemos frustrar sus planes de invasión. Quizás tú puedas reunir la fuerza necesaria para infiltrarte en el Risco Kolkar y destruir sus planes.|n|nLo último que vi es que los habían repartido entre tres de sus líderes.', },
    {'Lar Colmillo Acechador, de las afueras del Poblado Sen\'jin, quiere que destruyas los 3 planes de ataque de Risco Kolkar.', },
  },
  [787] = {
    'La nueva Horda',
    {'Throm\'ka, $C. Soy Eitrigg, Thrall me encargó supervisar la instrucción de los reclutas.|n|nLa Horda ya no es lo que era. Hubo un tiempo en el que abandoné sus filas desilusionado por la creciente influencia de los peones, sedientos de poder, de la Legión Ardiente. Durante mi exilio fui hecho prisionero por un grupo de humanos pero me rescató el Jefe de Guerra. Regresé tras oír su visión de una Horda libre de influencia demoníaca y guiada por los chamanes.|n|nGornek te dará más instrucciones.', },
    {'Preséntate ante Gornek en El Cubil.', },
  },
  [788] = {
    'Dientes afilados',
    {'El primer punto del día será fortalecer un poco tu espalda. Te podría enviar a Los Baldíos, a cazar kodos, pero, sinceramente, nos eres más útil $Gvivo:viva; que $Gmuerto:muerta;.|n|nCreo que lo mejor será que empieces por los jabalíes jaspeados que encontrarás al norte de aquí.', },
    {'Mata a 8 jabalíes jaspeados y vuelve con Gornek en El Cubil.', },
  },
  [789] = {
    'Aguijón de escórpido',
    {'El poderoso guerrero y el torpe novicio... todos han caído bajo la venenosa picadura del escórpido. Encontrarás un gran número de escórpidos al noroeste de aquí. Tráeme 8 de sus colas como prueba de tu destreza en la batalla.|n|nEl antídoto para sus picaduras se hace a base del veneno extraído de sus aguijones. Conservamos a mano grandes cantidades de antídoto para el veneno de escórpido con las que curar sangres jóvenes como la tuya...|n|nPero seguro que a ti no te hace ninguna falta, ¿no es cierto?', },
    {'Consigue 8 colas de escórpidos obreros para Gornek en El Cubil.', },
  },
  [790] = {
    nil,
    {'¡$C! Creía que iba morir ahí fuera sin que nadie se enterara. Cuando estaba cazando los escórpidos del valle me crucé con uno que tenía un aspecto especialmente atroz. Me lancé contra él y conseguí asestarle un enorme golpe antes de que se enrollara en mi pierna.|n|nPero no estaba listo para su aguijón, y consiguió deslizarse en mi peto, desgarrando y penetrando en mi piel y derramando mi sangre. Por favor, ¡debes matar a ese escórpido! ¡Hay que defender mi honor! Combatí con él en la meseta que está al Sur.', },
    {'Mata a Sarkoth y llévale su zarpa a Hana\'zua.', },
  },
  [791] = {
    'Asume tu responsabilidad',
    {'El tiempo me ha inutilizado para el combate. A mi edad, busco otras formas de ser útil.|n|nDesde este punto estratégico puedo vigilar la llegada de invasores. A medida que nuestra fuerza aquí se consolida, me encuentro dando la alarma cada vez menos.|n|nPara pasar el tiempo, creo objetos para ayudar a guerreros jóvenes y capacitados para defender nuestro hogar.|n|nA ti podría hacerte una bolsa para que lleves tus pertenencias. Si crees que te vendría bien, tráeme un retal. Sabrás lo que es... es un artículo muy normal tanto para centauros como para humanos.', },
    {'Furl Ceñosprecio de la Atalaya de Cerrotajo quiere 8 retales.', },
  },
  [792] = {
    'Familiares viles',
    {'Estoy segura de que aprenderás mucho en el Valle de los Retos, joven $C.|n|nFui enviada al Valle para guiarte, pero aquí he descubierto una creciente corrupción...|n|nUn grupo que se llama a sí mismo el Filo Ardiente tiene un aquelarre aquí mismo, en el Valle de los Retos. Se esconden en una cueva al Noreste, y sus familiares viles se han esparcido desde la boca de la cueva sembrando el caos y la confusión.|n|nTe ofrezco tu primera tarea contra el Filo Ardiente: derrotar a esos familiares. Aniquila a tantos como puedas y, si sobrevives, vuelve a verme.', },
    {'Mata a 8 familiares viles.|n|nVuelve con Zureetha Vistalonga a las puertas de El Cubil.', },
  },
  [793] = {
    'Alianzas rotas',
    {'El Sello de la Tierra está controlado por tres piedras rúnicas, que se encuentran en el Pilar de diamante, el Pilar de ópalo y el Pilar de amatista en el Barranco Lethlor. Mediante el Signo de la Tierra, podrás deshacerte de las piedras rúnicas y desbloquear el Sello de la Tierra.|n|nAunque ándate con cuidado, $N, los dragones Negros Latigoscuro y Hematus son de armas tomar. Acaba con ellos y tráeme sus esclavas.|n|nPara llegar al barranco, dirígete hacia los confines orientales de las Tierras Inhóspitas. Y abre bien los ojos porque el barranco es tierra de multitud de dragones.', },
    {'Usa el Signo de la Tierra para activar el Pilar de diamante, el de ópalo y el de amatista y así obtener las piedras rúnicas.|n|nColoca las piedras rúnicas en el Sello de la Tierra para liberar a Latigoscuro y a Hematus.|n|nMátalos y llévale a Gorn las ataduras de Latigoscuro, las cadenas de Hematus y el Signo de la Tierra.', },
  },
  [794] = {
    'Medallón del Filo Ardiente',
    {'Mis adivinaciones me traen visiones de un objeto lleno de poder, oculto en las profundidades del Aquelarre del Filo Ardiente y custodiado por bestias y magia negra.|n|nEs el llamado medallón del Filo Ardiente y tu siguiente tarea es sacarlo del Aquelarre.|n|nPero ten mucha cautela, el medallón puede estar en posesión de un agente del Filo Ardiente y su poder podría ser mayor que el del resto de los familiares con los que te hayas encontrado.|n|nVete, $N. Encontrarás el Aquelarre en una cueva, al Norte y al Oeste.', },
    {'Lleva el medallón del Filo Ardiente a Zureetha Vistalonga, a las puertas de El Cubil.', },
  },
  [795] = {
    'El Sello de la Tierra',
    nil,
    nil,
  },
  [804] = {
    nil,
    {'La hazaña que has hecho por mí llena de valor mi corazón. ¡No puedo caer tan fácilmente! ¡Debo resistir!|n|nPero lo cierto es que no puedo hacer el camino de vuelta a El Cubil sin ayuda. Por favor, $N, vuelve a El Cubil e informa a Gornek de mi situación. Quizás él pueda ayudarme.', },
    {'Informa de la situación de Hana\'zua a Gornek en El Cubil.', },
  },
  [805] = {
    'Preséntate en el Poblado Sen\'jin',
    {'Tus retos contra el Filo Ardiente han terminado... aquí, en el Valle. Pero quiero que informes sobre todo lo que has descubierto.|n|nVe al Poblado trol Sen\'jin y busca al maestro Gadrin. Poblado Sen\'jin está al este del valle, y a la derecha cuando llegues al cruce.|n|nInforma a Gadrin sobre el Filo Ardiente y dile que han alcanzado el Valle de los Retos. Con él, averigua si también han llegado a Sen\'jin.|n|nEn marcha, $N, y sé $Grápido:rápida;. Temo que el mal del Aquelarre del Filo Ardiente solo sea el heraldo de una mayor amenaza...', },
    {'Habla con el maestro Gadrin en el Poblado Sen\'jin.', },
  },
  [806] = {
    'Oscuras tormentas',
    {'¡No podemos permitir que el Filo Ardiente se establezca en Durotar! ¡Debemos acabar con él antes de que extienda su maldad!|n|nYo conduje mi propia investigación y averigüé que un brujo del Filo Ardiente, un goblin llamado Fizzle Tormenta Oscura, ha acampado en el Monte del Trueno, al noroeste. Ahí es donde están propagando el caos él y sus esbirros.|n|nEncuentra a Fizzle y acaba con él. ¡Y tráeme una zarpa suya!', },
    {'Lleva la zarpa de Fizzle a Orgnil Escaralma a Cerrotajo.', },
  },
  [807] = {
    nil,
    {'Mis exploradores me informan de que algunos animales de Durotar han sido infectados con una mancha demoníaca. Se les ha avistado al norte y al oeste.|n|nParecen normales y se mezclan con los de su especie, pero están impregnados de poderes malignos y en ellos late un corazón agostado con magia negra.|n|n¡Hay que acabar con ellos!|n|nSi te cruzas con alguno de estos animales al explorar Durotar, mátalo y quédate con su corazón agostado. Tráeme los corazones y mandaré estudiarlos y, finalmente, destruirlos.', },
    {'Llévale 5 corazones agostados a Orgnil Escaralma en Cerrotajo.', },
  },
  [808] = {
    'Calavera de Minshina',
    {'En mis sueños oigo la voz de mi hermano Minshina llamándome.|n|nSe lo llevó Zalazane, el brujo de las Islas del Eco que hay al este. Y ahora está muerto.|n|nPero la muerte no lo ha liberado. Zalazane utilizó su magia para atrapar el espíritu de Minshina en su propia calavera. En mi sueño, lo veo con otras calaveras, en un círculo de poder que está en la más grande de las Islas del Eco. Mientras siga allí, el alma de mi hermano estará maldita.|n|nTe lo ruego, $N. Encuentra el círculo y recupera la calavera de Minshina. Luego tráemela.|n|n¡Libera a mi hermano!', },
    {'Recupera la calavera de Minshina del círculo de poder de las Islas del Eco.|n|nLlévasela al maestro Gadrin al Poblado Sen\'jin.', },
  },
  [809] = {
    nil,
    {'Desde la última Gran Guerra, aquella en la que la Legión Ardiente fue derrotada, he buscado fuentes de corrupción demoníaca entre los orcos. El collar que me has traído confirma mis temores.|n|nPertenece al Filo Ardiente, un culto que adora un objeto de gran poder demoníaco. Se llama Semilla del Demonio y se encuentra en Los Baldíos, en la Cima Calígine. ¡Debe aniquilarla!|n|nVe a la Avanzada del Puente, hacia el oeste en la frontera de Los Baldíos y habla con mi ayudante, Ak\'Zeloth. Él te guiará.', },
    {'Habla con Ak\'Zeloth en Los Baldíos.', },
  },
  [810] = {
    nil,
    {'Harías bien en aprender cuán peligrosa puede ser esta tierra, $C.|n|nLa naturaleza nos enseña ciertas cosas... si somos prudentes y observadores.|n|nLos escórpidos son un ejemplo perfecto de supervivencia en Durotar. Si hemos de sobrevivir, sería sensato adoptar algunas de sus características como si fueran tuyas. Sus caparazones endurecidos te pueden proteger del sol implacable o incluso de un arma mortal.|n|nTráeme 6 caparazones pequeños de escórpido de los escórpidos castañeteantes, $N, y veré como podemos recompensarte en la justa medida.', },
    {'Llévale 6 caparazones pequeños de escórpido a Kor\'ghan en Poblado Sen\'jin.', },
  },
  [811] = {
    nil,
    {'Uno de los rasgos de los escórpidos es su acérrima lealtad. Se protegerán los unos a los otros si están en peligro; probablemente habrás observado ya este comportamiento en tu primera caza de escórpidos.|n|nTen presente esta lección y hazla tuya: somos más fuertes unidos, somos más débiles cuanto más divididos.|n|nTráeme 8 caparazones grandes de escórpido de los escórpidos acorazados y te recompensaremos por asimilar tal sabiduría.', },
    {'Llévale 8 caparazones grandes de escórpido a Kor\'ghan en Poblado Sen\'jin.', },
  },
  [812] = {
    'Se necesita un remedio',
    {'$N... llegas en el momento perfecto. Solo espero poder alabar tu velocidad también.|n|nTuve un descuido combatiendo con unos venocolas aquí cerca y uno de ellos me picó. Siento que su veneno me debilita por momentos. A este paso, calculo que me queda una hora de vida. Voy a necesitar tu ayuda...|n|nKor\'ghan, de Orgrimmar, sabe cómo preparar el antídoto. Encuéntralo... y deprisa, $N. No viviré mucho. Debería estar en el Circo de las Sombras.', },
    {'Encuentra a Kor\'ghan en Orgrimmar y consigue el antídoto para venocola. Luego lleva el antídoto a Rhinag. Está cerca del límite noroeste de Durotar.', },
  },
  [813] = {
    'En busca del antídoto',
    {'Los venocolas son los escórpidos más mortíferos de Durotar. Rhinag no debería haber intentado cazar uno sin llevar el antídoto... pero ahora, lo último que necesita son mis reproches.|n|nTráeme unas cuantas glándulas de veneno de cualquiera de los ejemplares de venocola que encontrarás en la entrada de Orgrimmar y yo prepararé el antídoto.|n|nY date prisa, $N. Uno de los nuestros necesita nuestra ayuda.', },
    {'Lleva 4 glándulas de veneno de venocola a Kor\'ghan a Orgrimmar.', },
  },
  [814] = {
    nil,
    {'Cocinar y limpiar, ¡no hago otra cosa!|n|nQuieres comer, ¡pues consígueme carne! No tengo todo el día para cazar y preparar comida para todos estos canallas. Tienes que aprender a valerte por ti mismo por aquí si quieres que te traten como a un igual.|n|nConsigue unas piezas de carne de jabalí si quieres ayudar... no querrás morirte de hambre.', },
    {'Llévale 10 piezas de carne de jabalí al cocinero Torka en Cerrotajo.', },
  },
  [815] = {
    'Romper huevos',
    {'¡Ay! Casi me olvido de que tengo que preparar el desayuno.|n|n$N, muévete y tráeme unos huevos de colazote. Necesitaré por lo menos tres si quiero tener suficientes para la comida de mañana.|n|nLos colazotes Garrasangre son animales fieros y protegen sus huevos con la vida. A veces los entierran a gran profundidad y es difícil sacarlos sin correr peligro. Si te diriges a las Islas del Eco, al sureste del Poblado Sen\'jin, encontrarás muchos.', },
    {'Lleva 3 huevos de colazote al cocinero Torka de Cerrotajo.', },
  },
  [816] = {
    'Perdido, pero no olvidado',
    {'$N, por favor, ¿podrías ayudarme? Mi hijo Kron fue a cazar hace días y aún no ha regresado. Fue hacia el oeste, hacia Los Baldíos, a cazar crocoliscos en el Río Furia del Sur. Temo lo peor.|n|nEs muy fuerte pero su orgullo le mete siempre en líos. Yo le advertí de que los crocoliscos son fuertes y aviesos. Pero solo conseguí que se fuera enfadado.|n|nSi no puedes encontrarlo, al menos tráeme algún indicio de su suerte... aunque tengas que abrir el estómago de todos los crocoliscos de las orillas del Furia del Sur.', },
    {'Lleva un indicio del destino de Kron a Misha Tor\'kren, a la granja que hay al noroeste de Cerrotajo.', },
  },
  [817] = {
    'Presa práctica',
    {'Muchos de los pelajes que usamos provienen de tigres de Durotar, $N. Mantas, armaduras, tiendas... tenemos muchos motivos para cazar a esas bestias y muchos también para dejar que proliferen.|n|nPero ha llegado el momento de hacer una selección en la manada, por decirlo de algún modo. Nuestros números crecen y nuestras necesidades empiezan a superar nuestras reservas. Necesito más pelajes para preparar los bienes que nuestra gente necesita.|n|nTráeme 4 pelajes de tigres de Durotar. Te recompensaré. Puedes encontrarlos en las islas que hay al sur de aquí.', },
    {'Lleva 4 pelajes de tigres de Durotar a Vel\'rin Colmillo al Poblado Sen\'jin.', },
  },
  [818] = {
    'Un espíritu responsable',
    {'Mis ojos empiezan a fallarme, pero aún veo con claridad. Y a menudo tengo que utilizar mis habilidades alquímicas para ayudarme en hechizos que antes me salían con facilidad. Pero me niego a adoptar un aprendiz. No he encontrado ningún trol ni orco merecedor de serlo.|n|n¿Tú crees valer lo suficiente? Sí, claro... Es evidente que lo crees.|n|nNecesito unas cosillas. ¿Crees que podrás conseguírmelas?|n|nNecesito ojos de makrura intactos y frascos de moco de reptador. Puedes conseguirlos de cualquier makrura o reptador de Durotar. Volveremos a hablar pronto.', },
    {'Lleva 4 ojos de makrura intactos y 8 viales de moco de reptador al maestro Vornal al Poblado Sen\'jin.', },
  },
  [819] = {
    'Barril vacío de Chen',
    {'Un cartelito en uno de los extremos del barril reza,|n|n"Chen Cerveza de Trueno-|n|nQue tu ánimo se levante y con tu copa siempre brindes."', },
    {'Encuentra a alguien que sepa algo sobre el barril vacío de Chen.', },
  },
  [820] = {
    nil,
    {'Tu cuerpo alberga un auténtico espíritu de fuerza, ¿o acaso fue un golpe de suerte?|n|nEn eso lo basa todo la juventud ahora: suerte... y la generosidad de los que son más poderosos que ellos. Pocos se toman el tiempo de hallar su propio camino. Siempre rogando que los ayuden... siempre la recompensa y nunca la misión. Seguro que serás igual que todos ellos.|n|nAunque hay esperanza. Necesito una cosa más para mi poción, $N: 8 hierbas de cardaluz. Se encuentran en Monte del Trueno al noroeste de Cerrotajo.', },
    {'Llévale 8 hierbas de cardaluz al maestro Vornal en Poblado Sen\'jin.', },
  },
  [821] = {
    'Barril vacío de Chen',
    {'¿Te gustaría probar la cerveza a la que le dio nombre Chen? Ah, la Cerveza de Trueno es un poderoso brebaje. Chen le enseñó la receta a mi mentor y mi mentor, a su vez, me la transmitió. Necesitaré que me consigas unas cosas pero te lo aseguro: el subidón lo merece.|n|nTráeme 5 colmillos de leones de la sabana de cualquier león de la sabana, 5 riñones de zancudo de llanura de cualquier zancudo de llanura y un asta de truenagarto de cualquier especie de truenagarto. Eso debería irnos perfectamente.|n|nPuedes encontrar estos ingredientes por Los Baldíos.', },
    {'Llévale 5 colmillos de león de la sabana, 5 riñones de zancudo de llanura y 1 cuerno de truenagarto al maestro cervecero Drohn en Trinquete.', },
  },
  [822] = {
    'Barril vacío de Chen',
    {'De categoría esa Cerveza de Trueno, ¿eh?|n|nTengo otra receta que también aprendí de Chen. ¿Te interesaría? No llevará mucho tiempo prepararla y podría serte de utilidad si vas a seguir con tus aventuras.|n|nTráeme 5 glándulas de relámpago de cualquier tormentero, 1 glándula de saliva de un halcón trueno de los mayores halcones trueno y 1 hígado de kodo de cualquier kodo de Los Baldíos.|n|nComo te he dicho, este brebaje pega; es la cerveza de los troggs de la que te he hablado antes.', },
    {'Llévale 5 glándulas relampagueantes, 1 glándula salivaria de halcón trueno y 1 hígado de kodo al maestro cervecero Drohn en Trinquete.', },
  },
  [823] = {
    'Informa a Orgnil',
    {'En el Poblado Sen\'jin no nos faltan problemas, pero te agradecemos tu ayuda. Claro que las noticias que traes del Filo Ardiente podrían significar más problemas para todo el mundo.|n|nEn Cerrotajo hay un orco llamado Orgnil Escaralma que se encarga de librar Durotar de males como el que representa el Filo Ardiente. Busca a Orgnil y háblale de nuestra situación. Cuéntale también las noticias que traes del Valle de los Retos. Querrá saber esas cosas.|n|nCerrotajo se encuentra al norte.', },
    {'Habla con Orgnil Escaralma de Cerrotajo.', },
  },
  [824] = {
    'Je\'neu del Anillo de la Tierra',
    {'El Anillo de la Tierra es un grupo de chamanes dedicados al estudio y la conservación de los elementos. Les sobra conocimiento sobre lunáticos dioses antiguos, ancestrales leyendas y tradiciones como nunca alcanzará la mayoría de los eruditos.|n|nEstás de suerte, conozco a alguien del Anillo de la Tierra aquí en Vallefresno. Dirígete a la Avanzada de Zoram\'gar, en la costa de La Ensenada de Zoram, y enséñale a Je\'neu Sancrea lo que has encontrado. Si alguien es capaz de interpretar el significado del globo, es él.', },
    {'Llévale el globo de agua contaminada a Je\'neu Sancrea en Cavernas de Brazanegra.', },
  },
  [825] = {
    'Los restos del naufragio...',
    {'Uno de mis mejores exploradores me ha informado de que los restos de la flota naufragada de Valiente aún están en la costa de Durotar, al este del Fuerte de Tiragarde.|n|nNo es un secreto que los humanos, aliados con esas mínimas criaturas llamadas gnomos, han desarrollado sus conocimientos de mecánica. Debemos estudiar a fondo a todos nuestros enemigos potenciales. Y nosotros también nos beneficiaremos de sus conocimientos.|n|nNada entre los restos del naufragio, $N y recupera las herramientas de la Alianza.', },
    {'Gar\'Thok de Cerrotajo quiere que recuperes 3 herramientas gnómicas de los restos de naufragio de la costa.', },
  },
  [826] = {
    nil,
    {'Zalazane, el curandero brujo, vive en las Islas del Eco, hacia el este. En otro tiempo, esas islas eran nuestro hogar.|n|nDesde ellas, Zalazane envía a sus trols a la península, a maldecir a nuestra gente y a esclavizarnos bajo su dominio.|n|nHay que detenerle.|n|nDerrota a Zalazane y a sus esbirros, antiguos trols Lanza Negra que hemos dado por perdidos. Tráeme su cabeza. Así sabré que su demoníaco reinado ha llegado a su fin.', },
    {'Derrota a Zalazane.|n|nMata a 8 trols vudú y 8 trols maléficos.|n|nLleva la cabeza de Zalazane a Gadrin.', },
  },
  [827] = {
    'Roca del Cráneo',
    {'$N, el Filo Ardiente ha infestado la cueva que hay al este de Orgrimmar, Roca del Cráneo. En esa cueva celebran sus inmundos rituales y queman su propia carne con collares abrasadores.|n|nCreo que usando esos collares, los cultores entran en sintonía con los poderes demoníacos. Pero para confirmarlo, necesito estudiar esos collares.|n|nVe a Roca del Cráneo y recoge los collares abrasadores que lleven los cultores. Tráemelos y yo descubriré su secreto.', },
    {'Recoge los collares abrasadores de los cultores de Roca del Cráneo. |n|nLlévaselos a Margoz a su campamento.', },
  },
  [828] = {
    nil,
    {'Uno de nuestros chamanes, Margoz, sabe más sobre la corrupción del Filo Ardiente. Habla de una cueva de las montañas llamada Roca del Cráneo... ¡justo a las afueras de Orgrimmar! Esa cueva proporciona refugio a una banda de adeptos del Filo Ardiente.|n|nAntes de ir a Roca del Cráneo, habla con Margoz. Es sabio y su consejo es valioso.|n|nEstá acampado hacia el noreste, entre la costa y el Barranco Árido.|n|nSigue su consejo pero, diga lo que diga Margoz, $N, ¡aún quiero que aplastes a esos adeptos!', },
    {'Habla con Margoz.', },
  },
  [829] = {
    'Neeru Hojafuego',
    {'Los collares abrasadores que me trajiste son potentes instrumentos demoníacos. Pero me temo que discernir su origen está más allá de mis habilidades chamánicas. Necesitamos que los estudie un brujo.|n|nLleva un collar abrasador a Neeru Hojafuego. Es un brujo muy capacitado que dice que utiliza sus poderes contra los demonios. Asegura que sus investigaciones de lo oculto son beneficiosas. Sea esto cierto o no, creo que necesitaremos su ayuda para luchar contra el culto demoníaco de Durotar.|n|nEncontrarás a Neeru en Orgrimmar, en el Circo de las Sombras.', },
    {'Lleva un collar de muestra a Neeru Hojafuego a Orgrimmar.', },
  },
  [830] = {
    'Las órdenes del almirante',
    {'Abres el viejo y desgastado sobre y descubres un documento que parece oficial. Reconoces el sello del almirante Valiente.|n|nParece importante. Gar\'Thok, el Comandante de Cerrotajo, podría estar interesado en esta información.', },
    {'Lleva las órdenes del almirante Valiente a Gar\'Thok a Cerrotajo.', },
  },
  [831] = {
    'Las órdenes del almirante',
    {'No se puede confiar en los humanos. Luchamos junto a ellos con recelo, sabiendo que algún día nos traicionarían.|n|nLa muerte del almirante Valiente no bastó para eliminar su legado de traición; la escoria humana había preparado sus planes mucho antes de que él muriera.|n|nNi siquiera la muerte de Benedict acabará con esto; quién sabe cuándo llegará la próxima horda de hombres de Valiente.|n|nHay que llevar esta órdenes a Vol\'jin a Orgrimmar de inmediato. Lo encontrarás en la cámara de Thrall.', },
    {'Entrega las órdenes del almirante Valiente a Vol\'jin a la cámara de Thrall en Orgrimmar.', },
  },
  [832] = {
    'Sombras Ardientes',
    {'<Del colgante emanan unas palabras que se introducen en tu mente.>|n|n¿Gazz\'uz?|n|nGazz\'uz... ¡informa!|n|nHay noticias sobre tu descubrimiento en la Roca del Cráneo. ¡Debes prepararte para un ataque!|n|n¡Gazz\'uz! ¡Te ordeno que hables! Habla. O me aseguraré de que llegue a Neeru Hojafuego la noticia de tu presencia y dejaré que descargue sobre ti su brutalidad.|n|nY no creo que quieras medirte con Neeru...|n|n¿Gazz\'uz? ¿Estás ahí...?', },
    {'Lleva este ojo a Neeru Hojafuego que está en Orgrimmar.', },
  },
  [833] = {
    'Cementerio sagrado',
    {'Solo los tauren más valientes reposan en Roca Roja, nuestro cementerio sagrado. Es un honor que concedemos a los valientes guerreros que fundaron y defendieron Cima del Trueno y a aquellos que han entregado la vida por el bien de sus tribus y sus jefes.|n|nPero una vil amenaza se cierne sobre nuestra tierra sagrada. Una banda de Erizapúas está arrasando el cementerio; yo ya estoy mayor para enfrentarme a ellos.|n|nHay que emplear la fuerza, $N.', },
    {'Mata a 8 intrusos Erizapúas en Roca Roja.', },
  },
  [834] = {
    'Las arpías Viento Seco',
    {'Soy Rezlak, uno de los chicos de Gazlowe. El jefe me manda a ayudar a los orcos de Durotar. Las cosas han ido bien... excepto para las caravanas. ¡No consigo mantenerlas al seguro! Eso hace mi trabajo un poco más difícil, ¿sabes?|n|nEl último envío –que, dicho sea de paso, prometieron que llegaría– fue robado por arpías Viento Seco de... ¿de dónde era que eran? ¿El Cañón del Ventajo?|n|n¡Necesito conseguir esos suministros! Sigue el cañón hacia el sur. Encontrarás una brecha en las paredes este y oeste.', },
    {'Recupera 5 sacos de suministros.', },
  },
  [835] = {
    'Asegurar las rutas',
    {'Gazlowe me dijo una vez, "Rezlak. En la vida hay que saber una cosa: que si quieres algo bien hecho, tienes que hacerlo tú mismo."|n|nPues bien, como no me puedo permitir perder todas las caravanas, voy a tomar las riendas del asunto. Las arpías tienen invadidas nuestras rutas de suministros. Si matamos a todas las arpías, las rutas serán más seguras.|n|nY claro, Gazlowe me enseñó algo más: "Todo tiene un precio." Así que, ¿cuento contigo, $N? Bien... Te recomiendo que empieces por el cañón del este.', },
    {'Mata a 12 arpías de Durotar. No importa el tipo de arpía.', },
  },
  [836] = {
    '¡Rescata a OOX-09/TI!',
    {'Vuelves a oír la voz del gnomo que sale del robot:|n|n"Tengo que llevar a OOX-09/TI a un lugar abierto y seguro en el que pueda iniciar el largo proceso de despegue. Tiene un dispositivo de invisibilidad integrado, pero necesito tiempo para que vuelva a estar operativo. ¡Escolta al robot hasta, digamos, algunas rocas donde no sea visible! Allí podré tomarme mi tiempo para hacer que todo vuelva a funcionar correctamente."|n|n"¡Escóltalo para que llegue sano y salvo y después ven a verme a Bahía del Botín! Oglethorpe Obnoticus. ¡Corto y cierro!"', },
    {'Escolta a OOX-09/TI para que llegue sano y salvo e informa a Oglethorpe Obnoticus en Bahía del Botín.', },
  },
  [837] = {
    'Invasión',
    {'Cuando llegamos, los jabaespines Crines de Acero poseían gran parte de la tierra... era una espinita que teníamos clavada. Con mucho esfuerzo hemos expulsado a la mayoría, pero aún quedan algunos bien fortificados en algunas zonas.|n|nPero esto ha durado ya demasiado. Por nuestro propio bien, no podemos permitir que haya Crines de Acero en nuestras tierras. Sus campamentos están al oeste de aquí. Busca las zarzas y los encontrarás. Hoy los echaremos de Durotar y mañana... puede que hasta de Kalimdor.', },
    {'Mata a 4 jabaespines Crines de Acero, 4 exploradores Crines de Acero, 4 polvorosos Crines de Acero y 4 guardias de batalla Crines de Acero para Gar\'Thok, de Cerrotajo.', },
  },
  [838] = {
    nil,
    {'En la isla de Castel Darrow se encuentra Scholomance, una escuela que sirve como bastión de la Plaga. Nuestro enemigo habita en ella, y puede allí, con toda seguridad, seguir con sus investigaciones para reforzar su poder. Una puerta bloquea el camino y por más que lo intentemos no podremos entrar si no tenemos la llave adecuada.|n|nEl boticario Dithers está muy versado en todo lo relativo a Scholomance, y sabe cómo obtener una llave. Te has mostrado capaz de hacerlo por lo que te confío esta tarea. Habla con él sobre este asunto.', },
    {'Habla con el boticario Dithers en el Baluarte, en las Tierras de la Peste del Oeste.', },
  },
  [840] = {
    'Nuevo recluta de la Horda',
    {'Mmm, pareces fuerte.|n|nEscucha, mi buen amigo Kargal necesita nuevos reclutas para una misión en Los Baldíos. Sé que quieres servir bien a la Horda. Pues esta es tu oportunidad.|n|nLleva esta carta de reclutamiento a Kargal, a ver si la firma.', },
    {'Entrega tu carta de reclutamiento a Kargal Marca de Guerra, en la Avanzada de Los Baldíos.', },
  },
  [841] = {
    '¿Otra fuente de alimentación?',
    {'Déjame adivinar... no has conseguido a tiempo lo que fuera que debías conseguir. No, mejor aún... ¡se te cayó en la arena! Bueno, sea lo que sea que ha pasado, tengo más fuentes de energía que puedo venderte. Sin embargo, esta vez te costarán diez, ¡SÍ, DIEZ faltriqueras de agua de Vagayermos cada una!|n|nCorren tiempos difíciles, $N, y las fuentes de energía no crecen en los árboles. Mmm, ¿y qué si lo hicieran? Quizás podríamos HACER un árbol de fuentes de energía...', },
    {'Llévale 10 faltriquera de agua de Vagayermos al ingeniero jefe Pasaquillas, que está en Gadgetzan, para conseguir otra fuente de alimentación.', },
  },
  [842] = {
    'Servicio militar en El Cruce',
    {'<Kargal extrae una ajada carta de reclutamiento de su bolsillo y la firma. Te la entrega con solemnidad.>|n|nBueno, $Gchico:chica;, has demostrado ser un fichaje formidable. Considérate $Greclutado:reclutada;. Necesitamos a gente como tú en El Cruce, si puedes llegar con vida. Sigue el camino que va hacia el oeste desde aquí, y luego al sur en el cruce de caminos. Si de verdad quieres ayudar a tu nueva Horda, habla con Halga para que te lleven con la siguiente caravana. Cuando llegues, dale esta carta a Sergra Espinoscura.', },
    {'Entrega tu carta de reclutamiento firmada a Sergra Espinoscura, que está en El Cruce. Si todavía no lo has hecho, puedes pedirle a Halga Ojosangre que te lleven con la siguiente caravana.', },
  },
  [843] = {
    'La reclamación de Gann',
    {'Solitario, errante voy por estas carreteras.|n|nLos enanos de Bael Modan no muestran el menor respeto por mi tierra. Unas tremendas explosiones provocan enormes socavones en el suelo mientras sus máquinas destrozan las colinas. Esos destructivos enanos han cribado las tierras que otrora fueron nuestro hogar y de las que se alimentaba mi tribu.|n|nTodo intento de solución diplomática ha fracasado. Ha llegado la hora de una acción decisiva.|n|nExpulsa a la fuerza a los enanos de la excavación de Bael Modan y tráeme el diario de su jefe, el prospector Khazgorm.', },
    {'Gann Picopiedra quiere que mates a 15 excavadores de Bael\'dun y a 5 supervisores de Bael\'dun.|n|nLlévale el diario de Khazgorm a Gann Picopiedra.', },
  },
  [844] = {
    'La amenaza de los zancudos de llanura',
    {'¿Conoces a los zancudos de llanura? Son unos animales inútiles. No pueden volar. Se dejan cazar. Tienen cerebros del tamaño de mis nudillos. No tienen la sensatez de apartarse del camino de un carro. La de ejes que se me han roto por culpa de sus cráneos... A veces pienso que los jabaespines espantan bandadas de zancudos hacia nuestras caravanas intencionadamente antes de una emboscada. Haz que me sienta orgullosa, $C. Abre un paso sangriento entre esos repugnantes pajarracos para que despejen las carreteras y tráeme sus picos como prueba.', },
    {'Reúne 7 picos de zancudos de llanura.', },
  },
  [845] = {
    'La zhebra',
    {'Si quieres servir a mi amada Horda, $Gnovato:novata;, vas a tener que demostrarme tu fuerza. Puedes entrenarte cazando zhebras. Puede que no sean las bestias más fuertes de Los Baldíos, pero evita sus coces o te arrepentirás.|n|nCaza las zhebras que hay al norte y al sur y recoge sus pezuñas. Tráemelas y a lo mejor te mandamos a por algo más difícil.', },
    {'Mata a galopadores zhebras para reunir 4 pezuñas de zhebras.', },
  },
  [846] = {
    'La venganza de Gann',
    {'Es evidente que el prospector dependía de los explosivos y de esos ruidosos vehículos para destrozar el suelo. Cabe esperar que pronto llegará otro Capataz para sustituirlo.|n|nQuiero darles a los enanos un poco de su propia medicina. Según estos planos, si combinamos nitroglicerina con pasta de madera y nitrato sódico, podemos crear una carga explosiva. Es bien sabido que el fusilero, los soldados y los oficiales tienen los suministros.|n|nReúne estos objetos y tráemelos. ¡Voy a preparar una carga que los enanos no olvidarán!', },
    {'Gann Picopiedra quiere que le traigas 6 viales de nitroglicerina, 6 fajos de pulpa de madera y 6 muestras de nitrato sódico.', },
  },
  [847] = {
    'La astucia del raptor',
    {'Este... este poder... ¿Es este el poder de los chamanes que Tor\'gan intentó enseñarme? Debo admitirlo, es interesante. Dile a Tor\'gan que me ha convencido... por ahora. Escucharé lo que tenga que decir.', },
    {'Habla con Tor\'gan en Sentencia, en las Tierras Altas de Arathi.', },
  },
  [848] = {
    'Esporas de hongos',
    {'Los oasis de Los Baldíos ocultan un misterio. La energía de la vida fluye por sus aguas, revitalizando a las plantas y a los animales que las beben.|n|nRevitalizando... y alterando.|n|nCerca de las Charcas del Olvido, al noroeste, crece un tipo de champiñón. Sus esporas tienen unas propiedades que nosotros, los boticarios de Lordaeron, encontramos útiles.|n|nTráeme esas esporas y te ganarás nuestra gratitud.', },
    {'Reúne 5 esporas de hongos de los hongos de Las Charcas del Olvido.', },
  },
  [849] = {
    'La venganza de Gann',
    {'Según los planos de Khazgorm, no debería ser un problema preparar una carga explosiva.|n|nAh, eso es.|n|nBien, $N, voy a confiarte una tarea especial. Lleva este palo explosivo y úsalo para hacer saltar la máquina voladora de Bael Modan.|n|nLa máquina voladora no es solo una parte clave de la infraestructura del sitio sino que se usa además como máquina de guerra. Es más, constituye un icono de poder y un insulto a la memoria de mi tribu.|n|nDame un motivo de orgullo completando esta tarea heroica y recibirás justa recompensa.', },
    {'Destruye la máquina voladora de Bael Modan y regresa junto a Gann Picopiedra.', },
  },
  [850] = {
    'Los jefes Kolkar',
    {'Los centauros han acosado a los tauren durante años. Y recientemente, los centauros Kolkar de Los Baldíos se han convertido en una auténtica amenaza. No solían estar organizados pero han surgido nuevos jefes entre ellos. Y se han unido.|n|nPara mantener nuestras propiedades, hay que acabar con los jefes de los centauros.|n|nTráeme la cabeza de Barak Aterrakodos. Su campamento está al oeste de Las Charcas del Olvido.|n|nDerrótalo y vuelve aquí.', },
    {'Asesina a Barak Aterrakodos y hazte con su cabeza.', },
  },
  [851] = {
    'Verog el Derviche',
    {'Quizás Verog sea difícil de encontrar, pero a juzgar por la información que has reunido, su compañera Wyneth está siempre en la tienda de mando, justo al oeste de aquí. Si la matamos, Verog saldrá al galope.|n|nRegthar nos envió para observar, pero también dijo que deberíamos aprovechar cualquier oportunidad que surja para desestabilizar la estructura de mando de los centauros. ¡Saca a Verog de su escondite y mátalo!', },
    {'Mata a Wyneth para atraer a Verog el Derviche, después asesínalo y hazte con su cabeza.', },
  },
  [852] = {
    'Hezrul Marcasangre',
    {'Hezrul Marcasangre es el jefe de los centauros Kolkar en Los Baldíos. Es feroz, brutal y taimado. Si lo derrotas, sería un golpe contundente para los Kolkar y la amenaza que suponen se vería reducida en gran medida.|n|nAsí que mátalo. Tráeme su cabeza y la colgaré de un poste para que conozcan el miedo.|n|nHezrul dirige a los suyos desde el Oasis Aguaverde, hacia el sur.', },
    {'Asesina a Hezrul Marcasangre y recoge su cabeza.', },
  },
  [853] = {
    nil,
    {'He convertido las esporas que me diste en una emulsión. Debo enviársela a mi socia, la boticaria Zamah. Si se la llevas, seguro que tendrá algo para ti de nuestro fondo de productos alquímicos.|n|nSe encuentra en las Pozas de las Visiones, una caverna en el subsuelo de los chamanes de Cima del Trueno. El camino hacia esta caverna está muy bien escondido pero la encontrarás en el risco del Alto de los Espíritus.|n|nApúrate. Esta emulsión solo conservará su efectividad por poco tiempo y se debe procesar y volver a sellar antes de que eso ocurra.', },
    {'Llévale las esporas devueltas a la boticaria Zamah en Cima del Trueno antes de que se agote el límite de tiempo.', },
  },
  [854] = {
    'Viaja a El Cruce',
    {'Había vaticinado tu llegada, joven $C. Aunque quizás ya no seas tan joven.|n|nHa llegado el momento de que te internes más en estas tierras. Tu destino es conseguir grandes cosas.|n|nTienes que ir a El Cruce; nuestra vida está ligada a la de los orcos y necesitan ayuda. Sigue este camino hacia el este y después hacia el norte hasta El Cruce. Habla con Thork, que tiene la bendición de la Madre Tierra.', },
    {'Habla con Thork en El Cruce, en Los Baldíos.', },
  },
  [855] = {
    'Brazales centauro',
    {'El liderazgo de los centauros depende de un núcleo de guerreros leales y disciplinados que mantengan a raya a los demás. Si diezmamos sus filas, los Kolkar no tendrán fuerzas para contener su ira. De modo que tengo una misión para ti.|n|nMata maleantes y videntormentos Kolkar alrededor del Oasis Aguaverde, al sur, y coge sus brazales. Vuelve cuando tengas unos cuantos y la Horda te recompensará bien.', },
    {'Llévale 10 brazales centauro de maleantes y videntormentos Kolkar.', },
  },
  [856] = {
    nil,
    {'Aunque has llegado a Los Baldíos, tu viaje no ha acaba aquí. Debes seguir hasta El Cruce, donde más te necesitan.|n|nSigue la carretera en la que estabas y gira a la izquierda donde tienes la opción para hacerlo. Sigue hacia el Norte hasta que veas la muralla de El Cruce.|n|nJusto antes de entrar, verás al sabio anciano, tendrá sabias palabras para ti.', },
    {'Sigue carretera abajo desde Campamento Taurajo.|n|nGira a la izquierda en la trifurcación y sigue hacia el norte.|n|nSigue el camino que te llevará al sabio anciano en las afueras de El Cruce.', },
  },
  [857] = {
    'La Lágrima de las Lunas',
    {'¡Yo tenía el poder de la energía! ¡La tenía en mis propias manos! ¡Y quiero recuperarla! ¡Cuanto antes!|n|nEsos canallas excavadores la descubrieron... era tal su hermosura. Se consideraba la Lágrima de las Lunas, fue el primer gran descubrimiento que hicimos en Bael Modan.|n|n¡Tenía que ser mía! ¡Mía y solo mía!|n|nAl general Trenzado lo carcomían los celos del poder que me daba. Así que la encerró en el castillo. ¡Se atrevió a decir que estaba maldita! ¡Ignorante!|n|n¡Otros la codiciaban y había que detenerlos! Ese malnacido de Trenzado me apartó.|n|nAhora quiero recuperarla. ¡Cuanto antes!', },
    {'Feegly el Exiliado quiere que le consigas la Lágrima de las Lunas.', },
  },
  [858] = {
    'La llave de contacto',
    {'¿No te mandará Petardol? Estoy en un apuro. Me metí sin darme cuenta de que necesitaba una llave para desbloquear la columna que mueve la trituradora. Uno de los operarios de la trituradora me preguntó si todo iba bien ¡y me entró el pánico! En lugar de decirle que me faltaba la llave, le dije que había algún tipo de problema mecánico.|n|nTenemos que salir de aquí ¡a paso ligero! Busca en la parte de arriba de la grúa, el Supervisor Palarrastre debería tener una llave para esta trituradora.|n|n¡Ayúdame!', },
    {'Consigue la llave de contacto del Supervisor Palarrastre.', },
  },
  [860] = {
    'Sergra Espinoscura',
    {'Si deseas practicar la caza debes dirigirte a Los Baldíos. Las bestias que allí habitan son tozudas y fuertes. Si cazas allí aprenderás mucho y tu espíritu crecerá.|n|nHabla con Sergra Espinoscura pues ella será tu primera guía en Los Baldíos.|n|nSergra está en El Cruce. Para llegar hasta allí, viaja hacia el este desde el Poblado Pezuña de Sangre hasta Los Baldíos y después dirígete hacia el norte cuando el camino se bifurque. Y ten mucho cuidado por el camino pues Los Baldíos pueden ser muy peligrosos para los incautos y confiados.', },
    {'Habla con Sergra Espinoscura en El Cruce.', },
  },
  [861] = {
    'Los hábitos del cazador',
    {'Te veo con ganas de explorar. Yo también era así antes...|n|nMe gustaba explorar y cazar. Salir a cazar es un gran honor para los tauren.|n|nSi de verdad quieres dedicarte al arte de la caza, demuéstrame tu habilidad y determinación. Tráeme las garras de los merodeadores de las estepas de Mulgore. Son peligrosos y astutos... digna presa de $Gun:una; joven $C que sigue el camino de la caza.', },
    {'Reúne 4 garras de merodeador de las estepas.', },
  },
  [862] = {
    'Estofado de ratas de madriguera',
    {'$GUn:Una; $C debe de pasar hambre por Los Baldíos. Al menos yo, me muero de hambre.|n|n¿Sabes qué? Voy a preparar un rico estofado. Solo necesito unas ratas de madriguera.|n|nAl parecer, a esos condenados enanos de Bael Modan les sobra lo mejor de lo mejor. Dirígete hacia el sur a Bael Modan y tráeme unas ratas de excavación.|n|nNo eres digno de llamarte aventurero curtido ¡hasta que has pasado un tiempo matando ratas! ¡Andando!', },
    {'Llévale 8 ratas de madriguera a Larva al este de El Cruce.', },
  },
  [863] = {
    'La fuga',
    {'Supongo que aprenderé sobre la marcha... No puede ser muy difícil. Unos botones por aquí, una palanca o dos... Bueno, ¿$Glisto:lista;?', },
    {'Protege a Rabiaire y la trituradora goblin robada hasta que salgan de El Fangal.', },
  },
  [864] = {
    'Regresa junto a la boticaria Zinge',
    {'"Aquí tienes, la fuente de poder se ha quitado con seguridad y la información se ha mantenido intacta. Bueno, lo de viajes seguros y todo eso. Espero que este nefasto experimento científico haya funcionado para ti y todo eso."|n|nEl goblin se aleja para atender sus labores con la Compañía de Aguas de Gadgetzan. Cierras bien el paquete, en preparación de tu viaje a Entrañas. La boticaria Zinge te espera allí para probar el objeto.', },
    {'Llévale el equipo de prueba de campo sellado a la boticaria Zinge, que está en Entrañas.', },
  },
  [865] = {
    'El secreto está en el cuerno',
    nil,
    nil,
  },
  [866] = {
    'Recoge muestras de raíces',
    {'Las hierbas de Los Baldíos no son como las de otras regiones. Sus propiedades son casi idénticas pero el agua de oasis las altera por lo que hay diferencias apenas perceptibles.|n|nDeseo estudiar esas diferencias... ¡para ver si se les puede sacar partido!|n|nSi eres un entendido en herboristería, recolecta muestras de raíces de las hierbas que encuentres en Los Baldíos. Tráeme esas muestras para que las pueda comparar con las de otras regiones.', },
    {'Llévale 8 muestras de raíces de hierbas de los alrededores de Los Baldíos del Norte.', },
  },
  [867] = {
    'Arpías saqueadoras',
    {'Ya que estás aquí, $C, quizás puedas ayudarme con un pequeño problema. Las malditas arpías han estado saqueando los suministros de nuestras caravanas demasiado tiempo. Es hora de rebanarles la garganta y acabar con unas cuantas.|n|nEl ataque más devastador acabará con una buena parte de su cadena inferior de mando y entonces podemos seguir hacia arriba.|n|nVe a por las arpías Alabruja de cualquier tipo hacia el noroeste y tráeme 6 garras de Alabruja. No debería estar mal para empezar...', },
    {'Reúne 6 garras de Alabruja de arpías Alabruja.', },
  },
  [868] = {
    '¡A cazar huevos!',
    {'Hola, $N. Mis maestros de Orgrimmar me han enviado a El Cruce para patrullar por estas tierras e informar de los acontecimientos.|n|nUno de los objetos de mis pesquisas son esos insectoides que se encuentran al sur de la Tierra de Gigantes. No sabemos mucho de estas criaturas, así que me he propuesto averiguar más. Parecen tener inteligencia, una inteligencia superior a la de los animales corrientes.|n|nToma esta garra de excavación y recolecta unos huevos de sus montículos, pero ándate con ojo: si se dan cuenta, te atacarán.', },
    {'Llévale 12 huevos de silítido y la garra de excavación a Korran en El Cruce.', },
  },
  [869] = {
    'El rastro del ladrón',
    nil,
    nil,
  },
  [870] = {
    'Las Charcas del Olvido',
    {'¿Has sentido el temblor, $C? Algo ha partido estas tierras en dos. Pero los druidas también percibimos temblores de otros tipos.|n|nHay vida en tierras que antes estaban secas y muertas. La vida vuelve a despertar en los oasis alrededor de El Cruce. Puedo sentir que se está filtrando una energía hacia la superficie, ¿pero de dónde? ¿Tiene algo que ver con el desastre que ha destrozado Los Baldíos?|n|nDebemos encontrar la fuente. Dirígete a Las Charcas del Olvido, al noroeste de El Cruce. Busca en sus aguas una fuente de energía y entonces vuelve aquí.', },
    {'Busca en Las Charcas del Olvido, al noroeste de El Cruce.', },
  },
  [871] = {
    'Defender la Avanzada del Puente',
    nil,
    nil,
  },
  [872] = {
    'La ofensiva de Avanzada del Puente',
    nil,
    nil,
  },
  [873] = {
    nil,
    {'El gran Isha Awak es dueño y señor de estas aguas. Grande es su fuerza y solemne su orgullo. Los humanos de la costa lo temen, porque les ha infligido muchas bajas.|n|nPero no lo temo. Incluso doy las gracias por su presencia. Es un desafío digno y una presa honorable.|n|nSi estás $Glisto:lista;, nada mar adentro en busca de Isha Awak, la Condena Abisal.|n|nSu ánimo mora en su corazón y oírlo latir es conocer tu sino.', },
    {'Llévale el corazón de Isha Awak a Mahren Vidente del Cielo.', },
  },
  [874] = {
    'Mahren Vidente del Cielo',
    {'Has cazado las fieras de Los Baldíos. Eso demuestra fortaleza de espíritu. Pero $Gun cazador:una cazadora; siempre debe estar $Gpreparado:preparada;. En cualquier terreno, $Gun auténtico cazador:una auténtica cazadora;, puede seguirle la pista a una presa. No se detendrá ante montañas ni ciénagas.|n|nNi siquiera ante el mar.|n|nEncuentra a mi hermana, Mahren. Se dedica a cazar a los grandes monstruos marinos de la costa. Te enseñará todo lo que hay que saber sobre ellos.|n|nPero ándate con cuidado cuando la busques, ya que la costa de Los Baldíos está en manos de los humanos.', },
    {'Habla con Mahren Vidente del Cielo.', },
  },
  [875] = {
    'Las tenientes arpías',
    {'La única forma de detener a esas arpías saqueadoras es destruir su cadena de mando. Las arpías siguen a intrépidas tenientes, destripadoras Alabruja. Si caen las destripadoras, el resto las seguirá.|n|nVe a Las Colina Áridas y mata a destripadoras Alabruja. Asegúrate de que sufran una muerte dolorosa, $N. Queremos que esas muchachas arpías aprendan cuán descabellado es buscar pelea con la Horda.', },
    {'Reúne 6 anillos de tenientes arpías de las destripadoras Alabruja en Los Baldíos del Norte.', },
  },
  [876] = {
    'Serena Sangrepluma',
    {'Las arpías que mataste mencionaron a su matrona, Serena Sangrepluma. A juzgar por su encarnizado odio hacia la Horda, debe de ser algún tipo de vieja rencilla. Debes acabar con Serena Sangrepluma y zanjar este asunto de una vez por todas.', },
    {'Mata a Serena Sangrepluma y hazte con su cabeza.', },
  },
  [877] = {
    'El Oasis Estancado',
    {'¿Es posible que lo que está pasando al sur pase aquí también? A juzgar por tus descubrimientos en las Charcas del Olvido, puede que estos oasis sean la clave. Hagamos un experimento.|n|nTen, toma estas semillas que he recogido de la montaña. Están muertas y no son fértiles, pero llévalas a El Oasis Estancado justo al sur. Si allí también hay una grieta, coloca las semillas en su interior... y observa. Informa de tus descubrimientos a Tonga, en El Cruce.', },
    {'Usa las semillas secas para investigar las fisuras en el Oasis Estancado.', },
  },
  [878] = {
    'Tribus en guerra',
    {'Debes acabar con mis enemigos. <Gruñe.> Debes ayudar a Quebrantadientes y a los Crines de Acero a debilitar a los Erizapúas. Ambas tribus son muy espirituales, vinculadas a la tierra y a su poder. <Gruñe.> Nos da fuerza en todo... Especialmente en la guerra.|n|nSi quieres saber quién le causa realmente este suplicio a Thork <gruñe> y a la Horda, entonces ¡ayuda a Quebrantadientes! Ataca a los líderes espirituales de los Erizapúas hacia el norte; debilítalos lo suficiente para que los Crines de Acero puedan vencerlos y dominar Los Baldíos.', },
    {'Mata a 6 buscaquas Erizapúas, 12 tejespinas Erizapúas y 12 geománticas Erizapúas y vuelve junto a Quebrantadientes en el Campamento Taurajo en Los Baldíos.', },
  },
  [879] = {
    'Traidores',
    {'Tres miembros de mi tribu salieron del Horado para encabezar unas incursiones contra la Horda, $R. <Gruñe.> Son crueles y taimados, y si los derrotas, entonces El Cruce y la mayor parte de Los Baldíos conocerán la paz... <gruñe> al menos por lo que respecta a la tribu Crines de Acero <gruñe.>|n|nNak, Kuz y Lok Aterraorcos son a los que tienes que buscar. Se encuentran en un lugar remoto del sur de Los Baldíos. Uno lanza hechizos, otro es un rastreador y su líder, llamado Aterraorcos <gruñe> es un guerrero. Mátalos, $R, como ellos me han matado a mí.', },
    {'Mata a Nak, Kuz y Lok Aterraorcos y lleva sus calaveras a Quebrantadientes en el Campamento Taurajo en Los Baldíos.', },
  },
  [880] = {
    'Seres alterados',
    {'Es importante estudiar la vida, tanto animal como vegetal, afectada por los oasis y las energías extrañas que has descubierto. El Oasis Estancado es el hábitat de una especie de tortugas quijaforte. De un tiempo a esta parte su población se ha disparado, y lo que es peor, estos animales antes pacíficos se han vuelto agresivos, como he podido comprobar en mis carnes mientras venía hacia aquí.|n|n<Jerrik te enseña un dedo vendado.>|n|nSospecho que las ha alterado el oasis. Recoge sus caparazones y llévaselos a Tonga en El Cruce para que los estudie.', },
    {'Reúne 6 caparazones de quijafortes alterados de los quijafortes de El Oasis Estancado.', },
  },
  [881] = {
    nil,
    {'Albineblina, Echeyakee en la lengua de los Tauren, es el rey de los felinos de la sabana. Es tan sigiloso al cazar que dicen que es como una neblina blanca y etérea sobre la tierra. Y tan raudo mata a sus presas que no tienen tiempo de sentir miedo ni dolor.|n|nLos tauren dicen que es muerte y misericordia a la vez.|n|n$N te encomiendo que caces a Echeyakee. Su guarida está al noroeste de aquí, en el lado norte de una pequeña colina, entre los huesos de un kodo gigante.|n|nY ahora vete. Haz sonar este cuerno cuando hayas alcanzado su guarida. Hazlo sonar y él acudirá.', },
    {'Toca el cuerno en la guarida de Echeyakee para invocarlo. Mátalo o subyúgalo.', },
  },
  [882] = {
    nil,
    {'Ishamuhale, Dientarpón, es el más feroz de los raptores Solescama de Los Baldíos. No caza por deporte, ni por comida. Caza porque le apasiona la caza. Mata porque está en su naturaleza.|n|nY tendrás la oportunidad de conocer su naturaleza, $N, porque tu camino sigue ahora las huellas de las garras de Ishamuhale.|n|nEmpieza la caza. Mata a su presa favorita, una zhebra, y trae entonces sus despojos al árbol muerto al noroeste de Trinquete. Ishamuhale olerá los despojos y esto lo atraerá.|n|nPrepárate para cuando llegue.', },
    {'Llévale el colmillo de Ishamuhale a Jorn en el Campamento Taurajo.', },
  },
  [883] = {
    nil,
    {'La pezuña de Lakota\'mani es un símbolo de la fuerza del gran kodo.', },
    {'Llévale la pezuña de Lakota\'mani a Jorn en el Campamento Taurajo.', },
  },
  [884] = {
    nil,
    {'Al tocarla, saltan chispas de la espina caudal de Owatanka.', },
    {'Llévale la espina caudal de Owatanka a Jorn en el Campamento Taurajo.', },
  },
  [885] = {
    nil,
    {'La pluma de Washte Pawne hace daño al tocarla.', },
    {'Llévale la pluma de Washte Pawne a Jorn Vidente del Cielo en el Campamento Taurajo.', },
  },
  [886] = {
    'El oasis de Los Baldíos',
    {'Los druidas de Cima del Trueno sentimos la presencia de un extraño poder en Los Baldíos, al este de Mulgore.|n|nEnviamos a Tonga Tótem de Runa para que descubra la fuente de dicho poder pero tememos que necesite ayuda.|n|nVe a Los Baldíos y habla con Tonga. Lo encontrarás en El Cruce. Para llegar hasta allí, sigue el camino que sale del Poblado Pezuña de Sangre en dirección este. Una vez en Los Baldíos, coge hacia el norte cuando el camino se bifurque. Continúa en dirección norte y encontrarás El Cruce.|n|nTen cuidado de no abandonar el camino, $N, pues Los Baldíos es un terreno muy abrupto.', },
    {'Habla con Tonga Tótem de Runa en El Cruce.', },
  },
  [887] = {
    'Filibusteros de los Mares del Sur',
    {'Gazlowe me prometió un ascenso si le ayudo con el problema de piratas en Trinquete. El problema son los nuevos bucaneros que han venido y ocupado Isla de Batalla, al sur de aquí. No buscan solo nuestras cosas: ¡tienen agravios pendientes! La otra noche incluso fueron a por uno de nuestros galeones de guerra.|n|nTengo planes para manejar la situación, pero Gazlowe quiere resultados inmediatos. Vete a Isla de Batalla y empieza a rebanar cabezas, ¿quieres?', },
    {'Mata a 8 degolladores o corsarios de los Mares del Sur en Isla de Batalla.', },
  },
  [888] = {
    '[DEPRICATED] El botín robado',
    {'Aunque me gustaría recuperar toda mi mercancía, seguro que no es posible. Sin embargo, ¡es imprescindible que recupere unas cuantas cosas!|n|nComo puedes ver, mi observatorio está listo pero necesita la más pequeña de las dos lentes. La primera llegó de Durotar por caravana pero la segunda se envió por barco... y nunca llegó a puerto. ¡Y tampoco me ha llegado el envío por mar de Drizzlik desde Bahía del Botín!|n|nDirígete al campamento pirata y a ver si los puedes encontrar.', },
    {'Recupera el envío de botas y las lentes telescópicas a Gazlowe en Trinquete.', },
  },
  [889] = {
    'El espíritu del viento',
    nil,
    nil,
  },
  [890] = {
    '[DEPRECATED] El envío perdido',
    {'¡Llevo siglos esperando mi último cargamento de mercancías de Bahía del Botín! Pondría la mano en el fuego a que lo robaron los filibusteros pero para asegurarnos, podrías acercarte hasta el muelle y preguntarle a Vertipeluca si ya han guardado mi mercancía en el almacén sin notificármelo.|n|nToma mi libro de contabilidad y dile a Vertipeluca que coteje mis datos de inventario con sus registros.', },
    {'Llévale el libro de contabilidad de Gazlowe al maestro de muelles Vertipeluca.', },
  },
  [891] = {
    'La Venganza de un Capitan',
    nil,
    nil,
  },
  [892] = {
    '[DEPRECATED] El envío perdido',
    {'Todo parece cuadrar según mis registros, $N. Vuelve y dile a Gazlowe que no ha habido suerte. No me sorprendería nada que los piratas le hubiesen birlado ese material.|n|nNo puedo hacer nada más por él. Bueno, sí, podrías decirle que tengo unas cosas de Minahonda para él y que pase a recogerlas cuando tenga un rato.', },
    {'Llévale el libro de contabilidad de Gazlowe a Gazlowe en Trinquete.', },
  },
  [893] = {
    'Una selección de armas',
    {'Por lo que me han contado, los jabaespines Crines de Acero hacia el sur, más allá de la Tierra de Gigantes, no cuentan con herreros cualificados pero, al parecer, han empezado a desarrollar armas resistentes. Me gustaría ponerles la mano encima a varios tipos diferentes para aprender su técnica si fuera posible.|n|nSi deseas contribuir con honor a la Horda, tráeme algunas muestras de sus armas. Encuentra una daga de sus acechadores, una varita de sus videntes y un escudo de sus frenéticos bélicos. ¡Con eso debería bastar!', },
    {'Llévale 1 puñal Crines de Acero, 1 varita Crines de Acero carbonizada y 1 escudo de guerra Crines de Acero a Jironack Forjacero en Campamento Taurajo en Los Baldíos.', },
  },
  [894] = {
    'Churumbele',
    {'Ventura y Cía. ha montado un pequeño centro de investigación al oeste, pasando El Fangal. No tengo muy claro qué hacen allí pero logré descubrir que están haciendo pruebas con algo llamado "churumbele".|n|nY digo yo, ¿qué leches es un churumbele? Bueno, sea lo que sea, quiero examinarlo, así que necesito que alguien me lo consiga.|n|nConseguí una copia de su manual de instrucciones del sistema de control, gracias al cual deberías poder encontrar la forma de desconectar el churumbele.', },
    {'Accede a la consola de control del laboratorio de investigación de Ventura y Cía.', },
  },
  [895] = {
    'SE BUSCA: Capitán Garvey',
    nil,
    nil,
  },
  [896] = {
    'La fortuna de un minero',
    {'Oye, $R, ¿te interesaría algún tesoro? Sabía que eso llamaría tu atención.|n|nPor el muelle del río se dice que uno de los mineros de Mina Pedrusco de Ventura y Cía. al noreste de aquí descubrió una esmeralda del tamaño de tu puño.|n|nSé de unos cuantos compradores que estarían interesados en ponerle las manos encima y no me importaría ir a medias en la venta. ¿Qué dices?', },
    {'Recupera la esmeralda ojo de gato de un sobrestante o un déspota de Ventura y Cía.', },
  },
  [897] = {
    'El Cosechador',
    {'Esta extraña criatura insectoide parece de un orden natural por fuera, como si no perteneciera a Los Baldíos.', },
    {'Llévale la cabeza del Cosechador a Jorn Vidente del Cielo.', },
  },
  [898] = {
    'Escapar del fuerte',
    {'¡Por fin! ¡Alguien que viene a rescatarme!|n|nNo puedo creer que hayas logrado superar a los guardias. Estos zelotes de Theramore están completamente desquiciados. Hundieron nuestro barco y a mí, el único superviviente, me encarcelaron. Me calificaron de enemigo y de amenaza para la Alianza.|n|n¡Yo! ¿Una amenaza para su gran farsa de Alianza? Solo era un marinero de un envío de licor de luna entre Trinquete y Bahía del Botín.|n|nPero basta de charla. Me ayudarás a volver a Trinquete, ¿verdad? Dime cuando estés $Glisto:lista; y saldremos para allá.', },
    {'Escolta a Gilthares Ramafuego de vuelta hasta Trinquete con el Capitán Solbrillante.', },
  },
  [899] = {
    'Consumido por el odio',
    {'Asesinaron a mi esposa. Incendiaron mi hogar. Desde aquella fatídica noche he viajado por estas tierras, desde que el sol nace hasta que se pone, escudriñando el horizonte en busca de monstruos. He matado a cada hombre jabalí que se me ha cruzado pero mi sed de su sangre está lejos de estar saciada.|n|nTú, $C, tú podrías ayudarme.|n|nMátalos. Mata a tantos como puedas. Tráeme sus colmillos y celebraremos juntos su muerte.', },
    {'Reúne 30 colmillos de jabaespín.', },
  },
  [900] = {
    'Churumbele',
    {'Ahora las tres válvulas de control están abiertas. Por los indicadores del panel de control cabe suponer que se deberían apagar antes de que se pueda apagar el dispositivo.', },
    {'Cierra la válvula de control de combustible, la válvula reguladora y la válvula de control principal y usa entonces de nuevo la consola de control.', },
  },
  [901] = {
    'Churumbele',
    {'Una vez apagado el aparato, se puede abrir el panel de control y extraer el churumbele de la consola. Con todo lo demás listo, solo queda conseguir la llave que desbloquea la consola.', },
    {'Consigue la llave de la consola de Manitas el Risitas.', },
  },
  [902] = {
    'Churumbele',
    {'Al abrir el panel frontal de la consola de control se accede al denso cableado, conducciones y otros extraños mecanismos, la mayoría de los cuales no parece tener ninguna función práctica. Si se apartan y se mira hacia el interior de la consola, se verá el churumbele. Basta con tirar de él para sacarlo de su compartimento.', },
    {'Llévale el churumbele a Petardol a la Avanzada de Ollaboquilla en Los Baldíos del Norte.', },
  },
  [903] = {
    'Cazar a las cazadoras',
    nil,
    nil,
  },
  [905] = {
    'En la guarida del raptor',
    nil,
    nil,
  },
  [906] = {
    'Traidores',
    {'Llévale la cabeza de Lok a Thork en El Cruce, $R. <Gruñe.> Debería saber lo que le ha ocurrido a mi tribu sin más explicaciones, ¡vaya!, y no es que él se creyera que Quebrantadientes tuviera nada que ver con <gruñe> tales cosas. Pero seguro que te recompensará por llevarle tan gran trofeo <gruñe.>|n|nSeguiré bendiciéndote con el poder de Agamaggan por todo el tiempo que permanezca en esta jaula, $R. Hasta entonces, adiós.', },
    {'Llévale la calavera de Lok a Thork en El Cruce, en Los Baldíos.', },
  },
  [907] = {
    'Los truenagartos iracundos',
    {'Bien, $N, ahora debes enfrentarte a los colosales truenagartos. Son fieras tan monumentales que el suelo de las llanuras tiembla bajo sus pisadas. Ten cuidado cuando luches contra ellos, un paso en falso y te aplastarían como a una hormiga.|n|nEncontrarás a los truenagartos en Los Baldíos del Sur. Se llaman morrotormenta, Tormentero y Tronatesta. Vuelve cuando los hayas vencido.', },
    {'Llévale 3 unidades de sangre de truenagarto a Jorn Vidente del Cielo en el Campamento Taurajo.', },
  },
  [908] = {
    'Entre ruinas',
    {'El Martillo Crepuscular se ha trasladado a las ruinas del Santuario Lunar de las Cavernas de Brazanegra. Su presencia solo puede servir para forzar a los elementos a actuar contra nosotros. Si no nos ocupamos de ella, esta región caerá en sus manos definitivamente.|n|n$N, dirígete a Brazanegra y encuentra la piedra de las profundidades en las ruinas; debería estar cerca, en el agua. En su interior hay un núcleo de las profundidades, un dispositivo que cuando se lee correctamente, revela la historia de toda actividad elemental. Si lo consigo, y con la ayuda de los miembros del Anillo de la Tierra, ¡quizás podamos detenerlos!', },
    {'Llévale el núcleo de las profundidades a Je\'neu Sancrea de la Avanzada de Zoram\'gar, Vallefresno.', },
  },
  [909] = {
    nil,
    {'El elemental de agua derrotado ha dejado tras de sí un extraño globo de agua. Supones que el objeto de alguna forma alimentaba la energía de la bestia. En el interior del globo chapotea masa líquida repulsiva. El propio globo parece impermeable a todo tipo de fuerza física.|n|nSi alguien es capaz de interpretar este artilugio, es Je\'neu Sancrea del Anillo de la Tierra.', },
    {'Llévale el extraño globo de agua a Je\'neu Sancrea en las Cavernas de Brazanegra.', },
  },
  [910] = {
    'Un paseo por los embarcaderos',
    {'¡He oído hablar de los grandes barcos que navegan entre Trinquete y Bahía del Botín! Sería una pasada navegar por el mar y luchar en grandes batallas. ¡Quizás cuando sea mayor me haga un poderoso marinero de la Horda! ¡Sí!|n|n¿Quieres llevarme a ver los embarcaderos de Trinquete, por favor? Te prometo que no me tiraré al agua ni te daré problemas... ¡solo quiero ver los grandes barcos y oler el agua salada del mar! ¡Sí!', },
    {'Lleva a tu pupilo a los embarcaderos de Trinquete en Los Baldíos.', },
  },
  [911] = {
    'El acceso a la frontera',
    {'Dicen que Vallefresno es la nueva frontera y que La Empalizada de Mor\'shan en Los Baldíos es su puerta de entrada. ¡Sería una pasada ser uno de los pioneros y coger todo lo que necesitas de la naturaleza virgen! Dicen que ese será el principal campo de batalla entre la Horda y la Alianza ¡y yo quiero verlo, $N!|n|n¿Querrás llevarme a La Empalizada de Mor\'shan para que pueda ver cómo es la frontera, por favor? ¡Quiero ver el sitio donde la Horda está combatiendo a esos apestosos elfos de la noche!', },
    {'Lleva a tu pupilo a La Empalizada de Mor\'shan en la zona norte de Los Baldíos, antes de la entrada a Vallefresno.', },
  },
  [912] = {
    'Disfrazado de trogg Rompecantos',
    nil,
    nil,
  },
  [913] = {
    'El chillido del halcón trueno',
    {'$N, el halcón trueno es un animal de lo más feroz. Ha llegado la hora de que te enfrentes a uno de ellos. Debes averiguar por donde andan y traerme sus alas como prueba de haber cazado a uno.|n|nHazlo y ya casi habrás acabado tus tareas conmigo.', },
    {'Encuentra 1 halcón trueno, mátalo y llévale sus alas a Jorn Vidente del Cielo en el Campamento Taurajo.', },
  },
  [914] = {
    'Líderes del Colmillo',
    {'Los druidas de las Cuevas de los Lamentos, los Druidas del colmillo, son una aberración. Fueron parte de una orden de nobles druidas que pretendían sanar Los Baldíos, pero ahora tan solo pretender cambiar esta tierra para amoldarla a sus propios y retorcidos sueños.|n|nLos Druidas del colmillo tienen cuatro líderes, y cada uno de ellos posee una gema de sueño. ¡Sus rostros aún me siguen atormentando! Derrota a los líderes y tráeme sus gemas. Así Los Baldíos recuperarán la paz.|n|nVete, $N. Los encontrarás escondidos en las profundidades de las Cuevas de los Lamentos.', },
    {'Lleva las gemas de Cobrahn, Anacondra, Pythas y Serpentis a Nara Ferocrín en Cima del Trueno.', },
  },
  [915] = {
    '¡Quiero un heladooooo!',
    {'¡HELADO! Oh, por favor, por favor, por favor, ¡¿me puedo comer un helado?! El que más me gusta es el de fresa, ¡y el mejor helado de fresa del mundo es el helado de fresa de Tigule y Foror! ¡Es mi helado más favorito del mundo!|n|nHace mucho me comí uno, cuando estaba en la pista de carreras de El Desierto de Sal, pero he oído decir que ahora también los venden en la ciudad. ¡Por favor! ¡Muy por favor! ¡¿¡¿¿Me darás un helado de fresa de Tigule y Foror??!?!', },
    {'Consigue helado de fresa para tu pupilo. Parece que el favorito del muchacho es el helado de Tigule y Foror.', },
  },
  [916] = {
    'Corrupción Tejemadera',
    nil,
    {'Mata 12 arañas Tejemadera.', },
  },
  [917] = {
    'Huevo de Tejemadera',
    {'Ahora que lo pienso, a lo mejor me puedes ayudar un poco más. Vine para recoger un huevo de Tejemadera del fondo de la cueva, pero las arañas no están por la labor. Si pudieras coger un huevo y llevárselo a Dirania los dos te estaríamos muy agradecidos.', },
    {'Consigue un huevo Tejemadera.', },
  },
  [918] = {
    'Semillas de Brezomadera',
    {'Los Brezomadera de Teldrassil son elementales de la naturaleza. En cierto modo, representan el orden natural de las plantas y los animales de nuestro gran árbol.|n|nPor eso es desagradable ver lo malhumorados que están últimamente, especialmente cuando tenemos en cuenta que la situación debería estar mejorando.|n|nQuiero ayudar a localizar el origen. He estado trabajando en diferentes métodos de nutrición de plantas y me gustaría probarlos con semillas de Brezomadera. ¿Podrías recoger semillas de Brezomadera alrededor del Lago Al\'Ameth y traérmelas?', },
    {'Recoge 6 semillas de Brezomadera.', },
  },
  [919] = {
    'Brotes de Brezomadera',
    {'Están brotando pequeños Brezomadera alrededor de las aguas del Lago Al\'Ameth. Me temo que ya no es posible ayudarlos por lo que deberíamos eliminarlos antes de que crezcan más y empiecen a causar problemas.|n|nCuando pases por el lago, si ves algún brote de Brezomadera, arráncalo. ¡Ayúdanos a mantener la tierra limpia!', },
    {'Reúne 10 brotes de Brezomadera.', },
  },
  [920] = {
    'Las invocaciones de Tenaron',
    {'¿Eres $N? He oído que Tenaron te estaba buscando. Está en la sala más alta de Aldrassil.|n|nAunque es mejor tomarse la vida con calma, no lo hagas esperar demasiado.', },
    {'Habla con Tenaron Tormentagarre en Aldrassil, en Cañada Umbría.', },
  },
  [921] = {
    'Teldrassil: La corona de Azeroth',
    nil,
    nil,
  },
  [922] = {
    'Rellian Verdeguja',
    {'$N, ¿puedes llevarle una de las semillas que me trajiste a mi amigo Rellian Verdeguja? Él es un druida del Cobertizo Primigenio y la última vez que hablamos me confesó su interés por mi trabajo con los Brezomadera. Incluso tenía algunas ideas así que supongo que le encantaría tener una semilla para poder experimentar con ella.|n|nGracias, $N. Espero que algún día puedas ver el fruto de mi esfuerzo.|n|nEncontrarás el Cobertizo Primigenio a lo largo del camino que sale al oeste de Dolanaar, en dirección a Darnassus.', },
    {'Llévale 1 semilla de Brezomadera a Rellian Verdeguja, en el Cobertizo Primigenio.', },
  },
  [923] = {
    'Tumores musgosos',
    nil,
    nil,
  },
  [924] = {
    'La semilla del Demonio',
    {'La Semilla del Demonio es una poderosa herramienta para la Legión Ardiente. Se encuentra en una caverna en la Cima Calígine, sobre un altar de fuego demoníaco.|n|nHe preparado piedras de energía que cuando se colocan cerca de la semilla interfieren en su conexión con la Legión.|n|nCoge una piedra de la mesa y llévala al altar de fuego en lo más alto de la Cima Calígine. Dirígete hacia el oeste, luego hacia el norte en el cruce de caminos. Verás la montaña a tu izquierda. La cara norte es la más segura de escalar.|n|nY date prisa, la energía de la piedra se agota con el tiempo.', },
    {'Coge 1 piedra de energía imperfecta. Llévala al Altar de Fuego antes de que su energía desaparezca y vuelve junto a Ak\'Zeloth.', },
  },
  [925] = {
    'Marca de la pezuña de Cairne',
    {'Dicen que Cairne Pezuña de Sangre es uno de las mayores héroes de la Horda de todos los tiempos. ¡Cuando sea mayor también seré un héroe de la Horda!|n|n¿Conoces a Cairne, $N? ¿Puedes hacerme un favor? ¿Me conseguirás sus huellas de pezuñas? No me atrevo a pedírselo, seguramente estará muy ocupado para alguien como yo... ¡pero tú! ¡Tú eres $Gun aventurero:una aventurera; como él! ¡Seguro que te dará su autógrafo!|n|n¡¡Por favor!!', },
    {'Viaja a Cima del Trueno para intentar conseguir las huellas de pezuñas de Cairne Pezuña de Sangre para tu pupilo.', },
  },
  [926] = {
    'Piedra de energía con imperfecciones',
    nil,
    nil,
  },
  [927] = {
    'El corazón musgoso',
    {'El corazón de Negromusgo el Fétido está recubierto de un musgo oscuro y grasiento. De hecho, se sabe que es un corazón porque late lenta y rítmicamente... Incluso ahora se sigue oyendo su latido.|n|nPuede que Denalan quiera verlo.', },
    {'Llévale el corazón musgoso a Denalan, que está en el Lago Al\'Ameth.', },
  },
  [928] = {
    'Teldrassil: La transmisión del conocimiento',
    {'Aunque podría contarte mucho más de las Pozas de la Luna y de Teldrassil, debo dejarte ir; Corithras Furia Lunar te está esperando. He puesto el agua que has traído en esta vasija; llévasela.|n|nEstará en la Poza de la Luna de Dolanaar. Coge el camino del sur de Aldrassil al salir de Cañada Umbría y sigue los adoquines cuando el camino gira al oeste.|n|nTen cuidado, $N. Últimamente hay criaturas muy peligrosas en el bosque.', },
    {'Lleva la vasija casi llena a Corithras Furia Lunar a Dolanaar.', },
  },
  [929] = {
    'Teldrassil: La negativa de los Aspectos',
    nil,
    nil,
  },
  [930] = {
    'El fruto resplandeciente',
    {'Un gran fruto redondo pende entre las hojas de esta resplandeciente planta.|n|nTienes la certeza de que a Denalan le gustaría analizarlo.', },
    {'Llévale el fruto resplandeciente a Denalan, que está en el Lago Al\'Ameth.', },
  },
  [931] = {
    'Fronda fulgurante',
    {'Las hojas de esta planta fulguran con la luz del bosque, creando un aura intermitente.|n|nCrees que a Denalan le gustaría tener una muestra.', },
    {'Llévale una fronda fulgurante a Denalan. Normalmente está en el Lago Al\'Amethm, pero a veces viaja hasta el Cobertizo Primigenio.', },
  },
  [932] = {
    'Odio enraizado',
    {'Debo advertirte, $N, de que este asunto debe quedar entre nosotros. Los sátiros ya son bastante vergüenza para nosotros, y este en concreto está demasiado cerca.|n|nSe llama Lord Melenas y habita en la cercana cueva de Roca Mácula, al norte, donde ha reunido a un numeroso grupo de guerreros grells. Su corazón es negro como la noche, mas lo que trama es incluso más repugnante.|n|nDebes encontrarle en su cercana cueva, al norte de aquí, y traerme su cabeza.', },
    {'Consigue la cabeza de Lord Melenas.', },
  },
  [933] = {
    'Teldrassil: El alba del mañana',
    nil,
    nil,
  },
  [934] = {
    'Teldrassil: La corona de Azeroth',
    {'Sin embargo, no todo iba bien en Teldrassil. Corzocelada lo había planeado todo meticulosamente ya que el Árbol del Mundo había brotado según lo previsto, pero ocurrió un pequeño desajuste, desajuste al que se pueden atribuir muchos de los conflictos de Teldrassil.|n|nPero no entraré en detalles por ahora. Debes ir a la última Poza de la Luna, al noroeste de El Claro del Oráculo. Debajo de las ramas del Árbol del Oráculo se encuentra la primera y más poderosa de nuestras pozas. Llena una ampolla con agua de esta poza y tráemela.', },
    {'Llena la ampolla de amatista y devuélvesela a Corithras Furia Lunar en Dolanaar.', },
  },
  [935] = {
    'Las aguas de Teldrassil',
    nil,
    nil,
  },
  [936] = {
    'Ayuda al archidruida Tótem de Runa',
    {'¿Tienes un minuto, $C?|n|nEl Círculo Cenarion de Cima del Trueno está buscando aventureros curtidos para un importante proyecto de investigación. No conozco los detalles, pero has de saber que quien dirige el proyecto es el mismísimo archidruida Hamuul Tótem de Runa.|n|nSi te interesa, habla con él directamente. Lo encontrarás en el Alto de los Ancestros, en Cima del Trueno.', },
    {'Habla con el archidruida Hamuul Tótem de Runa en Cima del Trueno.', },
  },
  [937] = {
    'El claro encantado',
    {'Me enviaron aquí con un pequeño grupo de centinelas para proteger el Árbol del Oráculo de las arpías que han anidado en el claro. Poco a poco estamos intentando expulsarlas.|n|nCuando el Árbol del Oráculo envió a un mensajero a Darnassus con un informe, este fue atacado y asesinado por un grupo de arpías.|n|nSi te sientes $Gcapacitado:capacitada; para esta tarea, ve a sus nidos y acaba con ellas, y después tráeme sus cinturones como prueba de ello.', },
    {'Consigue 6 cinturones Sangrepluma.', },
  },
  [938] = {
    'Niebla',
    {'La piel de la dientes de sable es de un color gris característico que armoniza con el del bosque en el que se encuentra. Mientras permanece allí tendida, observas que está malherida, con profundas laceraciones en la espalda y el estómago.|n|nLevanta la cabeza y te observa fijamente, dejando ver a través de sus azules ojos la gran inteligencia que posee. Parece que desea seguirte.', },
    {'Lleva a Niebla ante la centinela Arynia Quiebranubes que se encuentra en la Poza de la Luna situada cerca del Árbol del Oráculo.', },
  },
  [939] = {
    '[DEPRECATED]La Flauta de Xavaric',
    {'Estudias la sencilla flauta de madera que recogiste tras derrotar a Xavaric.|n|nLa madera parece sólida, pero cuando giras la flauta en tus manos, te da la sensación de que los dibujos y espirales de su superficie empiezan a retorcerse. Entonces te invade un repentino pavor...|n|nSacudes la cabeza $Gseguro:segura; de que tu mente te está jugando una mala pasada.|n|nPuede que otros sátiros tengan más pistas sobre lo que has encontrado. Lleva lo que has descubierto al druida Eridan Vientoazul que vive al sur de Frondavil.', },
    {'Lleva la Flauta de Xavaric y 5 muestras de lazo vil de fuego de jade a Eridan Vientoazul al Frondavil meridional.', },
  },
  [940] = {
    nil,
    {'El bosque susurra tus osadas proezas, $N. Una vez expulsadas las arpías de sus nidos, el bosque vuelve a estar en calma y las criaturas que en él habitan se sienten de nuevo seguras. Temía enviar a otro mensajero al archidruida pero ahora sé que tú le harás llegar mi mensaje sin problema.|n|nEntrégaselo y el bosque te ofrecerá su protección en los caminos que conducen hasta el Bosque de Piedra.', },
    {'Llévale el informe del Árbol del Oráculo al archidruida Fandral Corzocelada de Darnassus.', },
  },
  [941] = {
    'Plantar el corazón',
    {'He quitado el musgo que recubría el corazón pero aun así sigue estando sucio...|n|nPonlo en mi maceta y veamos qué pasa. Contiene tierra nutritiva que podría limpiar y purificar el corazón.', },
    {'Coloca el corazón máculo en la maceta de Denalan.', },
  },
  [942] = {
    'El prospector despistado',
    {'Este fósil tiene un parecido asombroso con uno que vi en Forjaz una vez. Un arqueólogo llamado Gargavino lo trajo a nuestra conferencia anual de la Liga de Expedicionarios. Creía que el fósil encerraba un poder y que este podría liberarse de alguna forma.|n|nLo último que supe de Gargavino es que se había refugiado en el Mesón Aguahonda, en el Puerto de Menethil y que esperaba una escolta para llegar a la Excavación de Whelgar. Búscalo y muéstrale el fósil de Tripirrem. Quizás él consiga revelar los secretos del pasado.|n|nEl barco para Menethil zarpa de Ventormenta.', },
    {'Lleva el fósil misterioso al arqueólogo Gargavino al Puerto de Menethil.', },
  },
  [943] = {
    'El prospector despistado',
    {'El fósil original lo tiene ahora el prospector Whelgar, en su excavación de Los Humedales. Cuando descubrí la Piedra de Relu, creía que era la clave para desvelar el misterio del fósil.|n|nCuando me dirigía a reunirme con Whelgar, fui atacado por raptores y perdí la reliquia. No sé cuál de esas bestias se tragó la reliquia pero, si la recuperas, podré liberar el poder de esos artefactos.|n|nTráeme la Piedra de Relu y el fósil original.', },
    {'El arqueólogo Gargavino, del Puerto de Menethil, quiere que le lleves la Piedra de Relu y el fósil de Gargavino.', },
  },
  [944] = {
    'La Espada del Maestro',
    {'Es extraño que haya nagas aquí, en Costa Oscura. Pero aún más extraño es... lo del Martillo Crepuscular. Ese culto adora a los antiguos Señores de la Tierra, que fueron derrotados hace mucho tiempo.|n|nUno de ellos cayó en La Espada del Maestro, al sur de aquí.|n|nVe allí y busca a más adeptos del Martillo Crepuscular.|n|nLlévate esta ampolla de adivinación. Utilízala para crear un cuenco de visión cuando encuentres La Espada del Maestro. Y luego utilízalo para hablar conmigo.', },
    {'Reúne información y luego utiliza una ampolla de adivinación para crear un cuenco de visión. Utiliza el cuenco para hablar con Onus.', },
  },
  [945] = {
    'La fuga de Therylune',
    {'¡Socorro!|n|nEstaba paseando por La Espada del Maestro cuando esos asquerosos del Culto me rodearon. ¡Menos mal que se me da bien esconderme!|n|n¿Puedes ayudarme a salir de aquí? También necesito avisar a mi hermana Therysil de que estoy bien. Está al sur, en Vallefresno, en el Santuario de Aessina.', },
    {'Ayuda a escapar a Therylune y luego dile a Therysil, en el Santuario de Aessina, que su hermana está a salvo.', },
  },
  [947] = {
    'La cueva de las setas',
    {'Estoy ideando una poción para la que necesito unas setas muy raras, unas que solo crecen en una cueva determinada. Esa cueva se encuentra más allá del Salto de Fonroca, al este y un poco al norte por las montañas.|n|nIría hasta allí en persona, pero en el Páramo de los Ancianos me aconsejaron que me mantuviera lejos de ese lugar. Nuestros venerables aliados creen que la cueva es el refugio de un nuevo mal de Costa Oscura.|n|nTe lo ruego, $N, tráeme algunas de esas setas. Y aprovecha para explorar la cueva y confirmar los temores de los ancianos.', },
    {'Lleva 5 boletos rudos y 1 oronja verde a Barithras Sombra Lunar a Auberdine.', },
  },
  [948] = {
    nil,
    {'Onus, un anciano del Conocimiento del Páramo de los Ancianos, ha sabido de tu viaje a Salto de Fonroca y desea hablar contigo. El Páramo se encuentra hacia el sur, cerca de las montañas.|n|nLos ancianos son pacientes y sabios, $N. Si Onus busca tu consejo sobre lo que viste en el Salto, temo que la cosa es urgente.', },
    {'Ve al Páramo de los Ancianos y habla con Onus.', },
  },
  [949] = {
    'El campamento del Martillo Crepuscular',
    {'No se sabe qué motivos han llevado al Martillo Crepuscular a La Espada del Maestro. Pero sus motivos son, sin duda, oscuros.|n|nDebes ir a su campamento de La Espada. Busca algo que pueda arrojar un poco de luz sobre sus intenciones.|n|nPorque debemos saber cuáles son antes de preparar un plan.', },
    {'Encuentra una pista en el campamento del Martillo Crepuscular en La Espada del Maestro.', },
  },
  [950] = {
    'Regresa junto a Onus',
    {'Mirar el Escrito Crepuscular es una locura. El texto empieza a bailar tras un momento, y la belleza se torna en formas grotescas.|n|nSolo te da tiempo a arrancar una hoja de garabatos incomprensibles antes de que te desvanezcas.', },
    {'Lleva a Onus los garabatos incomprensibles que has encontrado.', },
  },
  [951] = {
    'Las reliquias de Mathystra',
    {'El papiro que encontraste en La Espada del Maestro es una página de un antiguo texto escrito por los elfos. Está terriblemente mancillado por la corrupción del Martillo Crepuscular, pero parece que el Culto está sirviéndose de una antigua magia élfica para devolver a sus maestros a nuestro mundo|n|nViaja hacia el noreste, hasta las Ruinas de Mathystra y busca antiguas reliquias entre los hierbajos y las piedras. Estudiándolas, podríamos averiguar cómo pretende explotar el Martillo Crepuscular la magia de los elfos.', },
    {'Lleva 6 reliquias de Mathystra a Onus al Páramo de los Ancianos.', },
  },
  [952] = {
    'Páramo de los Ancianos',
    {'Si tuviste tiempo para hacer de $Gmensajero:mensajera; para el Árbol del Oráculo, seguro que puedo persuadirte para que lleves un mensaje al Páramo de los Ancianos, en Costa Oscura, al sur de Auberdine.|n|nProbablemente, por motivos de seguridad, tengas que utilizar un hipogrifo como medio de transporte, pero confío plenamente en ti. Llévale esto a Onus, el anciano del Conocimiento. Ha estado a la espera de noticias mías, igual que yo he aguardado noticias de El Claro del Oráculo.', },
    {'Entrégale el mensaje de Fandral a Onus en el Páramo de los Ancianos en Costa Oscura, al sur de Auberdine.', },
  },
  [953] = {
    'La caída de Ameth\'Aran',
    {'Encontrarás las ruinas de Ameth\'Aran hacia el este. Ahora las habitan los inquietos espíritus de los Altonato que en vida moraban entre sus muros, unos muros entre los que los siervos de Azshara practicaban libremente su poderosa magia.|n|nCuando me enviaron a explorar las ruinas encontré dos grandes tablillas con grabados que relataban la historia de Ameth\'Aran y de su caída. Mientras leía las runas me abordaron los espíritus y tuve que huir.|n|nPor favor, si puedes, aventúrate entre las ruinas e intenta descifrar las tablillas en mi lugar.', },
    {'Estudia las tablillas que hablan de Ameth\'Aran y de su caída y reúnete con la centinela Tysha Filoluna en Costa Oscura.', },
  },
  [954] = {
    nil,
    {'Las ruinas de Bashal\'Aran, al este, están invadidas por esbirros demoníacos. Los espíritus y los sátiros que han establecido su morada en la zona se alimentan de la energía mágica del lugar. Sus poderes crecen continuamente.|n|nAun así, he notado que hay un santuario al que no se acercan jamás. En la parte occidental de las ruinas, sobre un pequeño acantilado, se ve una extraña aura azul... Debe haber una explicación a la reluctancia de los demonios.|n|nQuisiera que lo investigaras.', },
    {'Encuentra la fuente de la extraña aura azul en las Ruinas de Bashal\'Aran.', },
  },
  [955] = {
    nil,
    {'Si tuviera que contar la historia de mi vida, sobrepasaría sin duda los límites de tu paciencia. Digamos que la mía ha sido una vida larga y atormentada y que esta forma espectral es el peor de los tormentos que he sufrido.|n|nLa magia me ata a este lugar. Mis palabras pueden sonar falsas, porque no habría palabras que expresaran mi agradecimiento si me ayudaras a averiguar cómo me retiene mi prisión. Me ata un sello y, examinando los pendientes de duendecillos y grells, quizás encuentre alguna pista que me lleve a él.', },
    {'Consigue 8 pendientes de grell y llévaselos a Asterion a Bashal\'Aran.', },
  },
  [956] = {
    nil,
    {'Si los grells han entrado en contacto directo con el sello que me ata a mi prisión eterna, sospecho cuál podría ser la causa. Sin duda el sello está en poder del sátiro que los comanda.|n|nTengo el presentimiento de que es así, $N. Debe tenerlo uno de los sátiros. Si logras hacerte con él, me acercarías tanto al otro lado de los barrotes de mi prisión que me harías llorar.', },
    {'Consigue el sello de piedra lunar antiguo y llévaselo a Asterion a Bashal\'Aran.', },
  },
  [957] = {
    nil,
    {'El sello que conforma mi prisión fue obra de uno de los Altonato más poderosos. En Ameth\'Aran, al sur, hay unas ruinas idénticas a estas. En ellas persiste, incluso hoy, una antigua llama, una llama azul. Esa llama podría destruir el sello.|n|nPero no bajes la guardia en las ruinas, $N...', },
    {'Destruye el sello de piedra lunar antiguo en la antigua llama de Ameth\'Aran y vuelve a reunirte con Asterion en Bashal\'Aran.', },
  },
  [958] = {
    'Las herramientas de los Altonato',
    {'$C. Tengo que pedirte un favor.|n|n¿Has visto las ruinas de Ameth\'Aran? Si no las has visto, las puedes encontrar en el lado este del camino principal, viajando hacia el sur. En otro tiempo fueron el hogar de los poderosos Altonato. Hoy son testimonios de la destrucción que sus errores produjeron.|n|nLos centinelas me han dicho que los espíritus de los Altonato persisten y que aún poseen sus antiguos instrumentos mágicos. Hemos de hacernos con esas reliquias para poder destruirlas.', },
    {'Reúne 7 reliquias de los Altonato y llévaselas a Thundris Tejevientos a Auberdine.', },
  },
  [959] = {
    '¡A por la botella!',
    {'¡Vaya!|n|n¡He tenido un pequeño percance, como puedes ver! El envío del carguero de la mañana de Bahía del Botín era enorme. ¡Lo que se dice enorme de verdad! Nunca había visto tantas cajas. Bueno, estaba intentando acelerar las cosas, así que empecé a descargar un poco más de lo que podía manejar. Y ahí es cuando todo se vino abajo.|n|nAntes de que me pudiera dar cuenta, vi que esa amenaza de Loco Magglish salía corriendo con una botella de Oporto con 99 años de antigüedad. Lo perseguí hasta las Cuevas de los Lamentos. Pero ni hablar de meterme en ellas.|n|n¿Eres suficientemente valiente para encontrarlo?', },
    {'El operador de grúa Pelardo de Trinquete quiere que le consigas una botella de Oporto con 99 años de antigüedad de Loco Magglish, que se esconde en las Cuevas de los Lamentos.', },
  },
  [960] = {
    'Onus lo está meditando',
    nil,
    nil,
  },
  [961] = {
    'Onus lo está meditando',
    nil,
    nil,
  },
  [962] = {
    'Reptilia',
    {'La Sociedad Real de Boticarios, establecida en la gran Entrañas de Lordaeron, me ha enviado aquí con un propósito muy concreto, $N. Quizás quieras ayudarme a mí y, de paso, también a la Dama Oscura en nuestro intento de mejorar la forma física de los Renegados.|n|nÚltimamente he estado estudiando una extraña planta llamada reptilia y creo que en grandes cantidades tiene un gran potencial.|n|nLamentablemente, la reptilia solo se encuentra en los recesos más oscuros de las Cuevas de los Lamentos, un sistema de cuevas muy peligroso situado en Los Baldíos.', },
    {'La boticaria Zamah de Cima del Trueno quiere que recojas 10 reptilias.', },
  },
  [963] = {
    'Un amor eterno',
    {'En el período que siguió a las batallas en el Pozo de la Eternidad, oí que Ameth\'Aran había sido destruido y que su gente había muerto... y entre ellos, Anaia, mi amada.|n|nJamás habría pensado que, miles de años después, el recuerdo de Anaia seguiría atormentando mis sueños. Un día, deambulando por los bosques de Costa Oscura como en un letargo, me encontré en las ruinas de Ameth\'Aran... y allí vi el espíritu atormentado de mi amada.|n|nDebo liberarla, pero me faltan las fuerzas. Sin embargo, su espíritu debe ser destruido.', },
    {'Libera el espíritu de Anaia Correalba y lleva su colgante a Cerellean Zarpablanca a Auberdine.', },
  },
  [964] = {
    'Trozos esqueléticos',
    {'La llave de Scholomance es la llamada Llave esqueleto. Debe forjarse a partir de los restos de un esqueleto (varios, en realidad) y endurecerse con los metales más fuertes en el molde adecuado. Un sello de poder obtenido de un ser que pueda abrir el portal de Scholomance por medios naturales será el último componente de la llave.|n|nPero empecemos por el principio, $N. Necesitaremos trozos esqueléticos para forjar la llave. Los podrás obtener de los esqueletos que se encuentran dentro de Andorhal, aunque también deberían servirte los que están fuera de los muros de la ciudad.', },
    {'Lleva 15 trozos esqueléticos al boticario Dithers en El Baluarte, en las Tierras de la Peste del Oeste.', },
  },
  [965] = {
    'La Torre de Althalaxx',
    {'Saludos, joven $R. Soy Elissa Brisa Estelar y soy la encargada de proteger Auberdine de todo mal.|n|nCon tal propósito envié a Balthule Tenebroso a observar los extraños sucesos de la Torre de Althalaxx, al noreste.|n|nY ya debería haber regresado. Me preocupa que haya encontrado algún peligro imprevisto en el bosque. Apreciaría sobremanera que fueras en su busca y te aseguraras de que se encuentra bien.', },
    {'Encuentra a Balthule Tenebroso cerca de La Torre de Althalaxx en Costa Oscura.', },
  },
  [966] = {
    'La Torre de Althalaxx',
    {'Un grupo de brujos se ha instalado alrededor y dentro de la torre. Habría regresado a Auberdine a informar a Elissa, pero tenía miedo de perderme algo.|n|nDelgren sospechaba que una compañía como esta estaba reuniéndose en la torre, pero no sabía por qué.|n|nA mis manos han llegado algunos fragmentos de los papiros que llevan los brujos, pero necesito reunir más para resolver el enigma. Deja que te dé un consejo: no entres en la torre, los brujos que hay en ella son los más poderosos.', },
    {'Reúne 4 papiros desgastados para Balthule Golpesombra acerca de La Torre de Althalaxx.', },
  },
  [967] = {
    'La Torre de Althalaxx',
    {'Mi maestro, Delgren el Purificador es un paladín que ha ofrecido gentilmente su ayuda en la defensa de nuestros bosques de los demonios y los no-muertos. Me ha enseñado mucho sobre la Luz Sagrada y el arte de la guerra.|n|nDelgren debe saber de las operaciones del culto cuanto antes.|n|nLo encontrarás al sur de aquí, en la Atalaya de Maestra del Bosque de Vallefresno. Debes apresurarte: la amenaza de la Facción Oscura crece cada hora.', },
    {'Entrega la carta de Balthule a Delgren el Purificador que está en el Bosque de Vallefresno.', },
  },
  [968] = {
    'Los Poderes Subyacentes',
    {'Aunque la cubierta de este libro está gastada y arañada, aún se puede leer el título:|n|nLos Poderes Subyacentes|n|nEn el interior del libro hay una lista de nombres impronunciables con títulos terribles, rituales de adoración y sacrificios preferidos... muchos de los cuales incluyen criaturas vivas, humanoides.|n|nEn la cubierta interior del libro hay unas palabras escritas: "Runas y Maldiciones de Agarrahueso, La Caverna Abandonada, Forjaz. Propiedad de: Gerrig Agarrahueso."|n|nSi Agarrahueso vende libros de este tipo, quizás me vuelva a comprar este.', },
    {'Lleva el libro Los Poderes Subyacentes a Gerrig Agarrahueso a La Caverna Abandonada, en Forjaz.', },
  },
  [969] = {
    '[DEPRECATED]Que la suerte sea contigo',
    {'Ah, verte basta para saber que lo que quieres es un talismán de la suerte. ¡Mau\'ari todo sabe!|n|nAl Sur, encontrarás un cañón y gigantes hechos de hielo duro. A veces los gigantes las llevan, pero puedes recoger tú $Gmismo:misma; las esquirlas en el cañón. Las esquirlas tienen una poderosa cualidad reflectante.|n|nTráeme 4 esquirlas de los Machacahielo y mi talismán de la suerte será tuyo.', },
    {'Recoge 4 esquirlas de Machacahielo para la médica bruja Mau\'ari de Vista Eterna.', },
  },
  [970] = {
    'La Torre de Althalaxx',
    {'La carta de Balthule es espantosa. Este culto de la Facción Oscura es una espina clavada que debo eliminar. Me las he visto con algunos de los miembros de la Facción Oscura al noreste de este lugar, en Ordil\'Aran. Uno de ellos posee una gema de almas que, creo, guarda el secreto del poder del culto.|n|nTráemela y podré descifrar el secreto de su interior.', },
    {'Reúne una gema de alma resplandeciente y vuelve junto a Delgren el Purificador en la Atalaya de Maestra.', },
  },
  [971] = {
    'Conocimiento en las Cavernas',
    {'Recopilo conocimiento. Conocimiento antiguo. Conocimiento con poder. Conocimiento que abre puertas y puede despertar a los Durmientes si no se maneja con cuidado.|n|nSe dice que un antiguo documento, el manuscrito de Lorgalis, se halla en las Cavernas de Brazanegra al oeste. Es el hogar de nuestros antepasados que murieron hace mucho. Acumularon mucha sabiduría antes de que su ciudad se arruinara.|n|nBusca el manuscrito en las Cavernas de Brazanegra. Nunca olvidaré este favor. Ni siquiera después del fin de los días.', },
    {'Lleva el manuscrito de Lorgalis a la centinela practicante Issara que está en el Campamento Brazanegra.', },
  },
  [972] = {
    'Sapta de agua',
    nil,
    nil,
  },
  [973] = {
    'La Torre de Althalaxx',
    {'Ilkrud Magthrull. Sí, sé algo acerca de él. Es un poderoso orco brujo que mora en el Santuario de la Escara, un lugar de extrema maldad al suroeste de Vallefresno.|n|nHasta ahora no había pasado de ser una molestia menor y no he tenido que tratarlo pero, por lo visto, ha llegado su hora.', },
    {'Llévale el Libro de Ilkrud Magthrull a Delgren el Purificador en la Atalaya de Maestra.', },
  },
  [974] = {
    'Busca la fuente',
    {'Las fuentes termales de esta zona son un auténtico misterio. ¿De dónde viene el calor?|n|nTeniendo en cuenta su proximidad con las fuentes de la Cresta del Penacho en Llamas, me pregunto si el volcán puede tener algo que ver. He creado un termómetro para tomar lecturas de las temperaturas del volcán y me gustaría localizar la zona más caliente. ¡Mide las temperaturas en grados Kraklenheit!|n|nToma, cógelo, ¡y haz mediciones de las temperaturas en la cresta cada vez que localices una zona caliente!', },
    {'Krakle, en el Cráter de Un\'Goro, quiere que encuentres la zona más caliente de la Cresta del Penacho en Llamas.|n|nSiempre que des con un punto caliente, pulsa con el botón derecho sobre el termómetro para comprobar la temperatura. Sigue buscando hasta que encuentres el punto más caliente.', },
  },
  [975] = {
    '[DEPRECATED]Alijo de Mau\'ari',
    {'Antes del talismán darte, explico mejor cómo usarlo.|n|nSi encima lo llevas, caerán objetos de las criaturas que mates. Si encima el talismán no tienes no caerán. ¿Entiendes?|n|nLos objetos conocerás por el nombre... se llaman E\'ko. Si encuentras esos objetos, dáselos a la vieja Mau\'ari y ella te ayudará.|n|nEspera aquí, yo preparo tu talismán.', },
    {'Vuelve a hablar en un momento con la médica bruja Mau\'ari para recibir el talismán de la suerte.', },
  },
  [976] = {
    'Suministros a Auberdine',
    {'Delgren me ha pedido que le entregue varios mensajes y unos suministros a la centinela Brisa Estelar en Auberdine pero odio marcharme solo. Peligrosos enemigos acechan en el bosque y no me gustaría correr el riesgo de que esta información y estos suministros cayeran en manos malintencionadas.|n|nSi tú y alguien más pudieseis ser mis guardias, podría marcharme ahora. Con tu protección, seguro que estas cosas llegarán a buen puerto en Auberdine.', },
    {'Habla con Delgren el Purificador en la Atalaya de Maestra después ayudar a Feero a cruzar el Bosque de Vallefresno y dejarlo a buen recaudo.', },
  },
  [977] = {
    '[DEPRECATED]Yeti... ¿ya hemos llegado?',
    {'Ahora que tengo lo que necesito para cubrir las piezas mecánicas móviles, solo necesito una cosa más. Bueno, dos. ¡Dos cuernos!|n|nLos patriarcas y matriarcas Cardo Nevado tienen los cuernos más grandes así que, por supuesto, esos son los que quiero. Ese tipo de yeti habita una cueva al Sureste. Hay muchos de ellos, así no deberías tener ningún problema para encontrarlos.|n|nRecuerda que solo quiero los que tengan mejor aspecto... ¡no traigas cuernos rotos o arañados por favor!', },
    {'Reúne 2 cuernos prístinos de yeti para Umi Risitas en Vista Eterna.', },
  },
  [978] = {
    'Lechúcico Lunadón',
    {'Las plumas de lechúcico salvaje de las Tierras del Interior parecen tener rastros de cualidades mágicas. Estos poderes... no parece que las criaturas se valgan de ellos, es más bien algo inherente a la especie... parte de su esencia.|n|nDurante mis estudios pude oír que hay un gran número de lechúcicos salvajes en las tierras nevadas de Cuna del Invierno. ¿Tendrán esas criaturas los mismos poderes? Por favor, ayúdame a encontrar una respuesta, $N. Ve a Cuna del Invierno y recoge del suelo las plumas que se hayan caído. Cuando las tengas, vuelve a verme.', },
    {'Recoge 10 plumas Lunadón de Cuna del Invierno y regresa con Erelas Cieloámbar en Aldea Rut\'theran.', },
  },
  [979] = {
    'Encuentra a Ranshalla',
    {'Sí, sí... estas plumas parecen albergar el mismo encantamiento mágico que ya había observado... Aunque no estoy seguro de qué es lo que podemos encontrar, te pido encarecidamente que sigas buscando respuestas, $N.|n|nUna colega mía viajó recientemente a Cuna del Invierno para observar a los lechúcicos salvajes en su propio hábitat. ¿Por qué no vas con ella y averiguas qué ha descubierto?', },
    {'Encuentra a Ranshalla en la zona oriental de Cuna del Invierno.', },
  },
  [980] = {
    'Nuevos manantiales',
    {'Bien, he oído hablar de otras fuentes termales en un lugar llamado Cuna del Invierno, muy al norte de aquí. Lo extraño es que no hay volcanes cerca de ellas. Interesante, lo sé.|n|nBien, si quieres averiguar más cosas, deberías ir a Cuna del Invierno y hablar con una amiga mía llamada Donova Cubilnevado, se encuentra junto a las fuentes termales de esa zona.|n|n¡Gracias de nuevo por ayudarme con mi termómetro! ¡Hasta la vista!', },
    {'Viaja hasta Cuna del Invierno y habla con Donova Cubilnevado.', },
  },
  [981] = {
    'La Torre de Althalaxx',
    {'Por todo lo que has hecho, bien mereces una recompensa. Busca a Delgren y dile que Athrikus Narassin ha sido derribado por tu mano y que el Culto de la Facción Oscura ha sido derrotado y dispersado.', },
    {'Habla con Delgren el Purificador en la Atalaya de Maestra.', },
  },
  [982] = {
    'Profundo océano, mar inmenso',
    {'En Costa Oscura, al norte de aquí, naufragaron dos barcos, el Amanecer de Plata y el Halo de Bruma. Hace un tiempo, los dos barcos fueron abordados por unos múrlocs cuando navegaban hacia Auberdine. Ahora yacen en el fondo del océano como trofeos de esos demonios.|n|nLos capitanes no sobrevivieron y sus cuadernos de bitácora y otros efectos aún siguen en sus cajas fuertes. Me gustaría que los recuperaras para nosotros. Es importante para los miembros de la tripulación que aún están por aquí.', },
    {'Recupera el arcón del Amanecer de Plata y la caja fuerte del Halo de Bruma para Gorbold Mano de Acero de Auberdine. Ambos objetos deberían estar en los cascos de los navíos naufragados al norte de la aldea.', },
  },
  [983] = {
    'Caja mecánica 827',
    {'¡Eh! Necesito ayuda con mi último invento, la caja mecánica. ¡Sirve para hablar con gente que está lejos!|n|nPuede que hayas visto alguna ya. Son unas cajas con muchas palancas. El problema que tienen es que necesitan un mantenimiento constante.|n|nCada una tiene un problema diferente, pero yo he hecho una cosa muy inteligente. He colocado cada caja cerca de las criaturas que tienen las piezas adecuadas para repararlas. Y ahora, hay que reparar la caja mecánica 827. Está al sur de Auberdine, muy cerca. Hacen falta 6 patas de reptador para arreglarla. Te pagaré...', },
    {'Reúne 6 patas de reptador y colócalas en la caja mecánica 827.', },
  },
  [984] = {
    'La extensión de la amenaza',
    {'Algunos de mis hermanos fueron salvados de un fúrbolg corrupto en Teldrassil y yo he jurado impedir otras atrocidades. No permitiré que los nuestros resulten heridos... o algo peor.|n|nYa he detectado un par de indicios de corrupción en Costa Oscura, pero aún he de encontrar signos de que se haya extendido. Creo que lo lógico sería continuar la investigación con los fúrbolgs. ¿Podrías buscar alguno de sus campamentos y decirme si has visto algún signo de corrupción?', },
    {'Encuentra el campamento de fúrbolgs corruptos en Costa Oscura, vuelve a Auberdine y busca a Terenthis.', },
  },
  [985] = {
    'La extensión de la amenaza',
    {'Ya has demostrado que sabes rastrear a nuestros enemigos, $N. ¿Crees que también podrás enfrentarte a ellos?|n|nLo pregunto porque algunos aventureros prefieren eludir el combate directo...|n|nSi crees que estás a la altura de la tarea, puedo decirte que la mayor amenaza para nuestra gente proviene del campamento que hay al sur de Auberdine. Allí encontrarás una parte de la tribu Bosque Negro. Mata a 8 abrecaminos y a 5 soplavientos y vuelve aquí.', },
    {'Mata a 5 soplavientos y a 8 abrecaminos Bosque Negro y vuelve a Auberdine a buscar a Terenthis.', },
  },
  [986] = {
    'El maestro perdido',
    {'$N, con tus habilidades me has ayudado mucho en mi empresa. ¿Podría abusar una vez más de tu buena disposición y pedirte que ayudes a Zarpadura y a su maestro Volcor? Puedo crear para ti una capa mágica que te permitirá caminar entre las criaturas de Costa Oscura sin ser $Gdetectado:detectada;.|n|nPero para tener suficiente material para crear la capa necesitaré 5 buenas pelambres de algún patriarca acechalunas o de una matriarca acechalunas. Puedes encontrar felinos de esos al sur, cerca del Río Culebra o cerca de Vallefresno, más al sur todavía.', },
    {'Encuentra 5 pelambres de Acechalunas refinadas y llévaselas a Terenthis a Auberdine.', },
  },
  [988] = {
    nil,
    {'Me he fijado en la capa que llevas, $N. Si estás dispuesto a sacrificarla, puedo renovar su magia y usarla para escapar. Aunque hay una dificultad, y es que te quedarás solo en la cueva.|n|n¿Sabrás salir solo si nos inclinamos por esa opción?|n|nTe garantizo que Terenthis te recompensará por ayudarme, si es que te preocupa.|n|nLa elección es tuya, pero me vendría muy bien tu ayuda.', },
    {'Habla con Volcor.', },
  },
  [989] = {
    nil,
    {'Si decidimos luchar para escapar, el plan es sencillo: nos abriremos paso por la carretera matando a todo fúrbolg que se nos cruce... o lo que se interponga.|n|nOjalá hubiera otra forma, pero más tarde o más temprano había que enfrentarse a la amenaza fúrbolg. Mejor será que nos ocupemos personalmente, así sabremos que el trabajo está hecho.|n|nTómate tu tiempo para preparar cualquier arma o recurso mágico de que dispongas y vuelve entonces a hablar conmigo.', },
    {'Habla con Volcor.', },
  },
  [990] = {
    'El camino de Vallefresno',
    {'$N, mi señora, Raene Correlobo, te espera en la ciudad de Astranaar en Vallefresno. Con tu ayuda, quizás podamos reducir algo la corrupción que allí se ha extendido.|n|nDirígete al sur desde aquí y mantente cerca de la carretera, llegarás allí sin problemas si sigues estas instrucciones.', },
    {'Encuentra a Raene Correlobo en Vallefresno.', },
  },
  [991] = {
    'Encontrar a Teronis',
    {'Una amiga mía de Astranaar, Raene Correlobo, me pidió que enviara a un explorador al oeste, a Lago Falathim. Teronis se fue hace días, antes de que atacara la Horda.|n|nBuscaba un objeto que creía que podía detener los ataques de los fúrbolgs sobre nuestra gente: una vara creada por un difunto mago malvado.|n|nAntes de irse mencionó una gema para la vara; según él, estaría en un templo en una isla del lago.|n|nPor desgracia, ahora sabemos que una fuerza maligna ha invadido el lago. Por favor, $N, encuentra a mi amigo.|n', },
    {'Encuentra a Teronis en el Lago Falathim en Vallefresno.', },
  },
  [992] = {
    'Un estudio de agua de Gadgetzan',
    {'Por si te interesa, tenemos un puesto vacante para perito adjunto temporal en la compañía de aguas de Gadgetzan.|n|nDado que los nómadas se aprovechan de nuestros pozos, tenemos que explotar más fuentes gratuitas de agua. En el desierto hay agua pero solo para aquellos que sepan encontrarla.|n|nCoge esta pipeta y toma una muestra del agua de la poza situada al lado de Vigía Penas de Arena. Está a la vista de los trols que andan por allí. ¡Tráeme la pipeta cerrada cuando hayas acabado!', },
    {'Utiliza la pipeta de muestras abierta en la poza de agua de Vigía Penas de Arena. Cuando hayas recogido la muestra, llévale la pipeta de muestras cerrada al perito jefe Picoflojo, que está en Gadgetzan.', },
  },
  [993] = {
    'El maestro perdido',
    {'La capa está acabada, $N. Ha llegado el momento de ir a buscar a Volcor. Solo espero que aún estemos a tiempo.|n|nLa magia de la capa, una vez convocada, no durará mucho... solo unos cinco minutos. Tú decides cuándo es la ocasión de utilizarla: pero yo sugeriría que esperaras hasta que encuentres a Zarpadura.|n|nSi lo que me ha dicho es verdad, encontrarás a su maestro en una cueva al sur de aquí. Zarpadura te estará esperando al lado del camino. Cuando lo veas, saluda con un ademán y él te señalará el camino hacia su maestro.', },
    {'Encuentra a Volcor en Costa Oscura y dale la capa de Acechalunas encantada.', },
  },
  [994] = {
    'Escaparse por la fuerza',
    {'Muy bien, $N, llegó el momento. Salgamos de aquí. Cuando tú digas. Nos abriremos paso hasta el camino combatiendo. Zarpadura aún debería estar allí. Una vez allí, nos dividiremos.|n|nTerenthis querrá oír tu versión de la historia inmediatamente, así que dirígete a Auberdine en cuanto salgamos de aquí.', },
    {'Protege a Volcor hasta que lleguéis al camino y luego ve a Auberdine a hablar con Terenthis.', },
  },
  [995] = {
    'Escaparse furtivamente',
    {'Muy bien... si no tienes dudas, salgamos de aquí. Partiremos cuando tú digas.|n|nY recuerda, cuando hayas escapado, busca a Terenthis en Auberdine. Yo iré hacia allí por mi cuenta. Probablemente me muevo más rápido que tú.', },
    {'Escapa de la cueva fúrbolg y reúnete con Terenthis en Auberdine.', },
  },
  [996] = {
    'Flor del viento corrupta',
    nil,
    nil,
  },
  [997] = {
    'Las tierras de Denalan',
    {'¿Te diriges hacia el sur? ¿Al Lago Al\'Ameth? De ser así hay algo que quiero pedirte...|n|nMi compañero Denalan tiene un campamento en el extremo oriental del lago, donde está estudiando y haciendo experimentos con la flora de Teldrassil. Encargó un paquete con tierras raras de Darnassus que llegó con retraso pues no hace mucho que lo recibimos aquí en Dolanaar.|n|n¿Podrías llevarle tú el paquete?', },
    {'Llévale el paquete con tierras raras a Denalan, que está en el Lago Al\'Ameth.', },
  },
  [998] = {
    'Flor del viento corrupta',
    nil,
    nil,
  },
  [999] = {
    'Cuando los sueños se vuelven pesadillas',
    nil,
    nil,
  },
  [1000] = {
    'La nueva frontera',
    {'¡Atención, héroes!|n|n¡El Círculo Cenarion busca voluntarios sanos para que les ayuden a explorar las vastas nuevas fronteras de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en su lugar.|n|nTodos aquellos que estén interesados pueden solicitar audiencia con el Círculo Cenarion. ¡Hablad con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros en Cima del Trueno para más información!', },
    {'Habla con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros de Cima del Trueno acerca de la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.', },
  },
  [1001] = {
    'Caja mecánica 411',
    {'Del interior de la máquina sale una vocecita.|n|n"¡Soy Zumbang! La siguiente caja mecánica está al norte de Auberdine, en la playa.|n|nEs la número 411 y requiere 3 ojos de trillador para ser reparada. ¡Están cerca de la costa! Los trilladores de Costa Oscura... *Hip*... Uy, perdón...|n|nComo la vez anterior, cuando le das los artículos a la caja mecánica, te escupe tu recompensa. *Hip*... ¿Qué? No, ¡estoy bien!"', },
    {'Consigue 3 ojos de trillador de los trilladores de Costa Oscura en las profundidades del mar, cerca de la caja mecánica 411.', },
  },
  [1002] = {
    'La caja mecánica 323',
    {'La caja mecánica sufre un ataque estático y Zumbang empieza a hablar.|n|n"La siguiente caja mecánica es la 323. Está al norte de Auberdine pero..., ¿dónde está la cerveza? ¿Qué? Ah, está por el camino, cerca del puente. No deberías tener problemas."|n|nZumbang murmura algo incoherente y luego le oyes tragar escandalosamente.|n|n"Esta necesita colmillos de Acechalunas... 6 en total."', },
    {'Reúne 6 colmillos de Acechalunas y colócalos en la caja mecánica 323.', },
  },
  [1003] = {
    'Caja mecánica 525',
    {'Por encima de los ruidos que provienen de la máquina, oyes la voz de Zumbang que te llama.|n|n"La shiguiente eshtá al shur, por el camino. No deberías tener problemas para encontrarla... jushto al lado d\'un eshcondite... cerca de un pantano. Creo que la eshcondí en unosh robushtosh... Digo, arburshtosh. Je, je, je... Shí, la caja mecánica 525 neceshita cuerosh cabelludosh grisháceohs de los Oshos Cardosh esos. ¡Tuercash! ¡Qué bocado! Grisháceosh... Je, je, je..."|n|nLa máquina traga y traga y se desconecta. Y, de repente, vuelve a la vida.|n|n"¡4!"', },
    {'Consigue 4 cueros cabelludos grisáceos de los osos cardo grisáceos del sur de Auberdine y colócalos en la caja mecánica 525.', },
  },
  [1004] = {
    'La nueva frontera',
    {'¡Atención, héroes!|n|n¡El Círculo Cenarion busca voluntarios sanos para que les ayuden a explorar las vastas nuevas fronteras de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en su lugar.|n|nTodos aquellos que estén interesados pueden solicitar audiencia con el Círculo Cenarion. ¡Hablad con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros en Cima del Trueno para más información!', },
    {'Habla con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros de Cima del Trueno acerca de la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.', },
  },
  [1005] = {
    'Lo que acecha detrás',
    nil,
    nil,
  },
  [1006] = {
    'Lo que hay detrás',
    nil,
    nil,
  },
  [1007] = {
    'Las antiguas estatuillas',
    nil,
    {'Consigue 10 estatuillas antiguas.', },
  },
  [1008] = {
    'La Ensenada de Zoram',
    {'El mal nos acecha desde la costa noroeste conocida como La Ensenada de Zoram.|n|nEs el lugar de descanso de la ciudad maldita de Zoram, destruida en el Diluvio y desde entonces sumergida bajo los mares. Se perdió para los elfos de la noche durante siglos. Perdida y casi olvidada.|n|nAhora, los nagas han regresado y en cuanto a sus motivos... los ignoramos. Pero el porqué importa poco; debemos ejecutar a estos desalmados ¡y devolverlos a los abismos!|n|nVuelve a mí cuando hayas completado tu misión.', },
    {'Llévale 20 cabezas de Colafuria a Shindrell Fuegoveloz en Astranaar.', },
  },
  [1009] = {
    nil,
    {'Temo que los secretos de la estatuilla antigua permanezcan ocultos para siempre a menos que encuentres la llave de su ancestral cerradura.|n|nEsa llave es un anillo, el Anillo de Zoram. Pertenecía a los gobernantes de esta ciudad antes de que las olas del Diluvio la inundaran.|n|nDurante años el anillo estuvo perdido pero los nagas lo encontraron recientemente.|n|nSu jefe, Ruuzel, mora en una isla en los confines norte de Zoram. Te lo ruego, $N, ¡recupera ese anillo para mí!', },
    {'Consigue el Anillo de Zoram.', },
  },
  [1010] = {
    'Cabello de Bathran',
    {'Existe una planta que crece entre las Ruinas de Bathran al otro lado de la carretera, al este. La planta se llamaba cabello de Bathran y era famosa por curar enfermedades espirituales.|n|nAhora la Horda se dedica a recolectarla para sus propios planes malvados.|n|nHay una niña enferma en Astranaar y creo que se trata de algo más que una enfermedad física. Prometí a mi maestro que ayudaría a encontrar una cura, pero no soy un guerrero.|n|n¿Irás a las Ruinas de Bathran a por las plantas?', },
    {'Consigue 8 cabellos de Bathran.', },
  },
  [1011] = {
    'Los males de los Renegados',
    {'Los Renegados, el brazo de no-muertos de la Horda, se han infiltrado en Vallefresno y merodean entre nuestras ruinas y túmulos. Creemos que su objetivo es propagar enfermedades por la tierra de los elfos de la noche. ¡Tenemos que saberlo con seguridad!|n|nLos Renegados tienen un campamento al sur de este lugar, cerca de El Túmulo de Dor\'danil, donde crean venenos y enfermedades y los embotellan. Infíltrate en su campamento y roba una botella de enfermedades. Vuelve con esa botella. La probaré y averiguaré para qué sirve.', },
    {'Llévale una botella de enfermedad a Kayneth Ventoleve en Canción del Bosque.', },
  },
  [1012] = {
    'Druidas dementes',
    {'Los druidas han muerto a manos de sus líderes, que enloquecieron cuando la Horda corrompió el corazón del bosque. Puedo sentir la corrupción incluso desde aquí y no me atrevo a ir más allá.|n|nMientras que yo me armonizo con Vallefresno y el corazón del bosque, tú podrías... bajar hasta el túmulo y hacer lo debido. Te he dejado algunas pistas por allí.|n|nBien que me pese, debo pedirte que hagas descansar en paz a Taneel Leñoscuro, Uthil Llamaluna y Mavoris Quiebranubes, los que un día fueron grandes líderes druidas.', },
    {'Mata a los druidas enloquecidos: Taneel Leñoscuro, Uthil Llamaluna y Mavoris Quiebranubes.', },
  },
  [1013] = {
    'El libro de Ur',
    {'$N, en el Castillo de Colmillo Oscuro hay un libro que deseo para mi colección: el Libro de Ur. Ur era un gran mago de Dalaran antes de que llegara la Plaga; sus estudios sobre otros mundos son muy valiosos para... ciertas facciones entre los Renegados.|n|nVe al Castillo de Colmillo Oscuro y tráeme el libro. Informaré a la Dama Oscura de tus servicios...', },
    {'Lleva el Libro de Ur al vigilante Bel\'dugur al Apothecarium de Entrañas.', },
  },
  [1014] = {
    'Arugal debe morir',
    {'Arugal sigue viviendo en el Castillo de Colmillo Oscuro. No podemos reclamar Argénteos como bastión estratégico para la Dama Oscura hasta que no hayamos matado a Arugal.|n|nMe encargaré de erradicar su magia, $N. Pero dejo en tus manos que Arugal se encuentre con la muerte que tanto merece.|n|nVe al Castillo de Colmillo Oscuro y pon fin de una vez por todas a los terribles hechizos de Arugal. ¡Tráeme la cabeza del malvado mago!', },
    {'Mata a Arugal y lleva su cabeza a Dalar Tejealba en El Sepulcro.', },
  },
  [1015] = {
    'La nueva frontera',
    {'¡Atención, héroes!|n|n¡El Círculo Cenarion busca voluntarios sanos para explorar las vastas fronteras nuevas de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en representación suya.|n|nTodos aquellos que estén interesados pueden solicitar audiencia en el Círculo Cenarion. ¡Hablad con el archidruida Fandral Corzocelada de Darnassus para más información!', },
    {'Habla con el archidruida Fandral Corzocelada en el Enclave Cenarion de Darnassus sobre la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.', },
  },
  [1016] = {
    'Retomar el Lago Mystral',
    nil,
    {'Mata a 12 elementales de agua podrida y Marearess.', },
  },
  [1017] = {
    'Mago invocador',
    {'Solo hay un mago no-muerto en Los Baldíos capaz de envilecer a tantos elementales de agua. También es el único lo suficientemente inconsciente para intentarlo. Sarilus Fuenteviciosa probablemente se encuentre en la cumbre de Cima Calígine, riéndose de mí.|n|n$N, debes aventurarte en territorio enemigo y acabar con ese bellaco. Ya estoy cansada de su insensatez y tenemos que demostrarle lo que les ocurre a quienes irritan a las centinelas.|n|n¡Destrúyelo y tráeme su cabeza! Ve con cuidado, la Horda podría estar vigilándote.', },
    {'Mata a Sarilus Fuenteviciosa y lleva su cabeza a la centinela Velene Golpe Estelar en el Refugio Brisa de Plata.', },
  },
  [1018] = {
    'La nueva frontera',
    {'¡Atención, héroes!|n|n¡El Círculo Cenarion busca voluntarios sanos para que les ayuden a explorar las vastas nuevas fronteras de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en su lugar.|n|nTodos aquellos que estén interesados pueden solicitar audiencia con el Círculo Cenarion. ¡Hablad con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros en Cima del Trueno para más información!', },
    {'Habla con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros de Cima del Trueno acerca de la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.', },
  },
  [1019] = {
    'La nueva frontera',
    {'¡Atención, héroes!|n|n¡El Círculo Cenarion busca voluntarios sanos para explorar las vastas fronteras nuevas de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en representación suya.|n|nTodos aquellos que estén interesados pueden solicitar audiencia en el Círculo Cenarion. ¡Hablad con el archidruida Fandral Corzocelada de Darnassus para más información!', },
    {'Habla con el archidruida Fandral Corzocelada en el Enclave Cenarion de Darnassus sobre la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.', },
  },
  [1020] = {
    'Cura de Orendil',
    {'$N, ahora que está bañado en la luz sagrada de Elune, creo que el brebaje ayudará a la niña enferma. Por favor, llévalo a Astranaar y dáselo al padre de la niña, Pelturas Lunablanca.|n|nPara llegar a Astranaar, sigue el camino hacia el sur y luego al este. Si quieres llegar más rápido, habla con la centinela Avana.', },
    {'Llévale la cura de Orendil a Pelturas Lunablanca en Astranaar, en Vallefresno.', },
  },
  [1021] = {
    '¡Vil sátiro! ¡Dríades en peligro!',
    {'No sé de dónde has salido, pero necesito que me ayudes. Mis hermanas se fueron a quitarle la Rama de Cenarius al sátiro. Dijeron que volverían pronto, ¡pero hace ya dos días que se fueron!|n|n¡Encuéntralas, $N! Iban a buscar las ruinas de un templo de los elfos de la noche en Xavian, al noroeste. Busca a Anilia, era la líder del grupo.', },
    {'Encuentra a Anilia en Xavian, en Vallefresno.', },
  },
  [1022] = {
    'La Vega del Aullido',
    {'Aunque hemos puesto muchos recursos y esfuerzo en expulsar hacia el norte a los demonios restantes en Frondavil, no hemos tenido mucho éxito. Hemos logrado mantener apartados de Vallefresno a casi todos los demonios.|n|nHacia el norte, cerca de los límites de Frondavil, el altar en ruinas de Mel\'Thandris ha sido tomado por unos misteriosos hombres lobo. Sus llamadas te hielan la sangre y han hecho que se conozca esa zona como la Vega del Aullido. Es posible que el Libro de Mel\'Thandris que se conserva en el altar arroje algo de luz sobre el motivo que ha traído a estos hombres lobo.', },
    {'Ve a La Vega del Aullido y estudia el Libro de Mel\'Thandris, vuelve entonces junto a la Centinela Melyria Sombrigélida en la Canción del Bosque.', },
  },
  [1023] = {
    'La gema perdida',
    nil,
    {'Encuentra la gema resplandeciente.', },
  },
  [1024] = {
    'La entrega a la dríade',
    {'Ah, ahí estás, $N. He leído con cautela las notas que redactó Teronis y parece que tu siguiente paso será encontrar las demás piezas de la vara de Dartol.|n|nYo empezaría por dirigirme al este por el camino que conduce a la Torre de la Algaba.|n|nUna dríade llamada Shael\'dryn podrá indicarte mejor. Búscala.|n|nLleva la gema contigo, Shael\'dryn la necesitará si te va a ayudar a recrear la vara.', },
    nil,
  },
  [1025] = {
    'Una defensa agresiva',
    {'Antes de que vayas a la Poza de la Luna, tengo otra tarea que ayudará al pueblo de Vallefresno si te apetece poner a prueba tus habilidades.|n|nPor la carretera que va hacia el este antes de llegar al Río Falfarren, los fúrbolgs han estado asaltando a los viajeros. Sus torturadas mentes alimentándose del miedo y su apetito saciándose con sangre inocente.|n|nAyuda a las centinelas a proteger las tierras mostrando hacia esos monstruos la misma misericordia que ellos para con los de nuestra clase.|n|nMe parece que sus campamentos están al sur de la carretera... ve con cuidado.', },
    {'Mata a 1 vigía del cubil, 2 ursas, 10 totémicos y 12 guerreros de la tribu de los Maderiza y vuelve junto a Raene Correlobo en Astranaar.', },
  },
  [1026] = {
    '¿Dónde están las llaves?',
    {'Ojalá tus nuevas fueran mejores.|n|nRaene tiene razón, he oído hablar de la creación de Dartol y de los antárboles de la región, al menos una vez. Ahora se han corrompido, su naturaleza se ha pervertido.|n|nPara encontrar la siguiente pieza de la vara, tendrás que encontrar la llave que abre el cofre en el que se encuentra.|n|nLa llave de madera está en uno de los antárboles al noreste desde aquí, en la Vega del Aullido, cerca de los límites de Frondavil. Cuando la tengas, busca un pequeño claro en la vega a través del túnel. El cofre debería estar escondido por ahí.', },
    {'Encuentra la llave de madera y úsala para conseguir un trozo de asta de hierro de la vara de Dartol.', },
  },
  [1027] = {
    'Hacerse el muerto',
    {'Los druidas de la Zarpa poseen la última pieza de la vara. Cuando pedí a su líder, Oso Rajazarza, que la devolviera, ¡casi me matan sus guardias! Se les veía claramente afectados por la corrupción del corazón del bosque perpetrada por la Horda.|n|nSin embargo, tengo una idea sobre cómo puedes introducirte en la cueva de Oso y obtener la empuñadura.|n|nDesde que era un fauno, se me ha dado bastante bien hacerme el muerto. ¡Funciona de maravilla con los osos! ¡Te puedo enseñar! Dirígete hacia el este a El Rincón Lóbrego, y si intentan atraparte, utiliza mi técnica.', },
    {'Consigue el pomo de hierro, la última pieza de la vara de Dartol.', },
  },
  [1028] = {
    'Encontrar a Teronis',
    {'Aquí tienes la vara completada, $N. Volver a construirla ha sido sencillo... encontrar el santuario que tiene el poder para cargarla de nuevo será la parte complicada.|n|nCentrándote y con un poco de empeño, no debería ser demasiado difícil para alguien como tú, con tantos logros en tu haber.|n|nDirígete al sureste desde aquí, hay muy pocos caminos, así que ten cuidado, y mantén la vista hacia el norte. El santuario se encuentra oculto en las montañas que rodean este claro.|n|nUna vez allí, coloca la vara en el interior del santuario... el resto es magia. Je, je.', },
    {'Encuentra el Santuario Oculto y encanta de nuevo la vara de Dartol.', },
  },
  [1029] = {
    'Regresa con Raene',
    {'Te sugiero que encuentres a Raene y le digas que la vara está recompuesta. Seguro que sabrá aconsejarte sobre el siguiente paso.|n|nVe con cautela... presiento una gran fuente de poder que emana de la vara tan buena como maligna. Espero que tú y Raene sepáis lo que hacéis.|n|nBuena suerte, $N.', },
    {'Entrega la vara de Dartol a Raene Correlobo en Astranaar, en Vallefresno.', },
  },
  [1030] = {
    'La vara de Dartol',
    {'No estoy del todo segura de cuál era la intención de Teronis. Si era cierto lo que contaba del poder de la vara, entonces hasta te permitirá adoptar otra forma, probablemente la de un fúrbolg.|n|nQuizás pretendía usar sus poderes para acercarse a ellos, pero incluso la criaturas sin corromper lo asesinarían si no iba con cuidado. Transformado gracias a la vara, Dartol tendría que hablar con un fúrbolg que no estuviera corrupto.|n|nEmpezaría la búsqueda por uno al que llaman Krolg. Encontrarás su cabaña al sureste del Lago Mystral.', },
    nil,
  },
  [1031] = {
    'La Rama de Cenarius',
    {'Anilia te pone las manos en los hombros y te acerca. Entre jadeos, señala el arco al norte, antes de que sus ojos se cierren y el último soplo de vida salga de su boca. "Se la ha llevado... Geltharis..." En tu corazón sabes que el deseo póstumo de Anilia es que la Rama de Cenarius vuelva a las manos de la dríade.', },
    {'Consigue la Rama de Cenarius.', },
  },
  [1032] = {
    '¡Muerte a los sátiros!',
    {'No puedo creer que Anilia ya no esté... Solíamos pasarnos los días jugando juntas en el bosque. Casi siento... tristeza.|n|nSé de algo que podría hacer que me sienta mejor. ¡Por favor, ejecuta a los sátiros que me han arrebatado a Anilia! Tráeme sus cuernos como prueba de tus actos y tendrás mi gratitud eterna.|n', },
    {'Consigue 16 cuernos de sátiro.', },
  },
  [1033] = {
    'Lágrima de Elune',
    {'Esperaba que la cura de Orendil salvara a Relara pero me temo que solo ha frenado su enfermedad. ¡Tenemos que encontrar una medicina más eficaz! Por suerte, Orendil me habló de otros remedios que debía intentar si el suyo no funcionaba.|n|nLa lágrima de Elune es un tipo de piedra que solo se halla en un lugar: las ruinas del Lago Iris, destruidas por la erupción del Pico del Trueno, al noreste de Astranaar. Orendil dijo que la piedra se llevaría la corrupción.|n|nPor favor, $N, ¡tráeme la lágrima de Elune y reza para que acabe con la enfermedad de mi niña!', },
    {'Consigue la lágrima de Elune.', },
  },
  [1034] = {
    'Las Ruinas del Polvo Estelar',
    {'La lágrima de Elune logró curar en parte la enfermedad de mi hija. Tiene menos pesadillas y le estoy agradecido a la diosa por su bendición. Pero... sigue teniendo la fiebre muy alta.|n|nOrendil me habló de un polvo de escarcha que se encuentra en Las Ruinas del Polvo Estelar. Quizás mitigue la fiebre de Relara. Te ruego que consigas un poco de ese polvo y me lo traigas.|n|nLas Ruinas del Polvo Estelar se encuentran en el sur, $N. Que Elune haga breve tu viaje.', },
    {'Llévale 5 puñados de polvo estelar a Pelturas en Astranaar.', },
  },
  [1035] = {
    'Lago Cielo Estrellado',
    {'La fiebre de Relara ya queda atrás, pero todavía sigue débil. No creo que con el tiempo solamente logre recuperar la energía perdida. Creo que va a necesitar la energía de una piedra lunar.|n|nLas solíamos recoger en el Lago Cielo Estrellado, al sureste... hasta que los Sombramatorral llegaron.|n|nSu líder, un oráculo Sombramatorral, recogió todas las que había y las esconde como su tesoro. Tu misión consiste en recuperar una.|n|nY para hacerlo, creo que deberás matar al líder.', },
    {'Recupera una piedra lunar caída del Oráculo Sombramatorral y llévasela a Pelturas en Astranaar.', },
  },
  [1036] = {
    '¡Adelante, pillín!',
    {'$N... sí, he oído hablar de ti. Me han dicho que no eres $Gamigo:amiga; de la Bahía del Botín, igual que nosotros, los Bucaneros Velasangre. El maestro de flota Firallon está buscando reclutas robustos y fuertes como tú para una misión especial.|n|nSi te interesa, dirígete a El Velo Carmesí y habla con él bajo cubierta. Está en La Costa Salvaje, al este de aquí, junto a Las Mareas Vivas y La Damisela Afortunada.', },
    {'Habla con el maestro de flota Firallon a bordo de El Velo Carmesí cerca de la costa de la Vega de Tuercespina.', },
  },
  [1037] = {
    'Velinde Cantoestelar',
    {'Velinde Cantoestelar era mi predecesora aquí en el Bosque de Vallefresno. Al principio parecía que tenía la situación en Frondavil bajo control pero poco a poco sus esfuerzos flaquearon. Un buen día desapareció sin más.|n|nMe enviaron aquí para continuar su trabajo. Aunque me temo que no sé nada de la sacerdotisa. Quizás Thyn\'tel Tejespada, una Comandante de las centinelas, sepa algo sobre su desaparición que no me haya comentado.|n|nSeguro que entenderá la trascendencia de tal información.', },
    {'Habla con Thyn\'tel Tejespada en el Bancal del Guerrero en Darnassus.', },
  },
  [1038] = {
    'Las pertenencias de Velinde',
    {'¿El Libro de Mel\'Thandris te enseñó esto? Supongo que no hacemos daño a nadie si te permito examinar sus pertenencias. Esta llave abre el cofre en el que ella guardaba sus cosas en el barracón de centinelas. Llevaba un diario de servicio. Si hay algo que aprender por aquí, estará en su diario.|n|nDebería decirte que los centinelas creen que tenía sus propias razones para irse y esperan que vuelva en cualquier momento. La sacerdotisa ha demostrado en el pasado que merece toda nuestra confianza.', },
    {'Busca el diario de Velinde en su cofre y llévaselo, junto con la llave, a Thyn\'tel Tejespada a Darnassus.', },
  },
  [1039] = {
    'El puerto de Los Baldíos',
    {'Trinquete es el único puerto de Los Baldíos. Seguramente Velinde encontró un navío mercante en Trinquete que la llevó a la Cala Aguasnegras, en Azeroth. Hemos tratado poco con los goblins que llevan el puerto, pero el capataz del puerto debería tener información sobre los barcos de pasajeros.|n|nSigue el camino del sureste que atraviesa Vallefresno y te encontrarás en Los Baldíos. Pero ve con cuidado, $N. Hay guerreros de la Horda patrullando esa tierra. En el puerto estarás a salvo.', },
    {'Ve a Trinquete y habla con el maestro de muelles Vertipeluca.', },
  },
  [1040] = {
    'Pasaje a Bahía del Botín',
    {'Ah sí, por fin lo encontré. Tenía que haberme dicho que había estado por aquí hace tanto tiempo. Veamos.|n|nVelinde. Reservó un billete para Bahía del Botín en el Pigargo negro. No figura nada más, así que se supone que llegaron a puerto sanos y salvos.|n|nMe temo que no puedo ayudarte mucho más... bueno, ella preguntó sobre una expedición por tierra en esa parte del mundo y le hablé de Ruzzgot, un conductor de caravanas establecido en Bahía del Botín. Puede que la tal Velinde viajara con él.|n|nVenga, vete ya. Tengo otras cosas que hacer.', },
    {'Coge un barco a Bahía del Botín y habla con el caravanero Ruzzgot.', },
  },
  [1041] = {
    'La ruta de la caravana',
    {'Parece ser que me había equivocado contigo, y eso no me suele pasar todos los días.|n|nResulta que recuerdo a esa Velinde a quien estás buscando. No todos los días una sacerdotisa elfa de la noche quiere viajar en una vieja y sucia, aunque genial para transportes, caravana como la mía.|n|nNos separamos en el norte, ella se dirigía a Villa Oscura. El secretario de allí guarda todo tipo de registros. Quizás tenga alguna información útil.|n|nTen cuidado en la jungla, es un lugar lleno de peligros mortales en todo momento.', },
    {'Habla con el secretario Daltry en Villa Oscura.', },
  },
  [1042] = {
    'La familia Carevin',
    {'No, no tengo constancia de que ninguna Velinde Cantoestelar haya pasado por Villa Oscura. Aunque debo decir que no me imagino a una sacerdotisa elfa de la noche alojándose en la posada, ya me entiendes.|n|nPero de esos hombres-lobo de los que hablabas, sí que he oído algo. Precisamente el otro día vino Calor con una ristra de cabezas de hombres-lobo. Trabaja con la familia Carevin. Son cazadores de demonios, no-muertos y otras monstruosidades. Habla con Jonathan. Es el cabeza de familia.', },
    {'Habla con Jonathan Carevin en Villa Oscura.', },
  },
  [1043] = {
    'La Guadaña de Elune',
    {'Tu historia suena convincente... No acabo de entender tus motivos pero, si tus negocios en el Bosque del Ocaso implican cazar huargen en cualquier número, no necesito entender nada.|n|nHay una mina al sur que ha sido invadida por huargen. Salieron de la nada pero, por lo que sabemos, es precisamente donde fueron encontrados por vez primera.|n|nTú ocúpate de tus negocios. Y si encuentras algo importante, compártelo conmigo, si no es mucho pedir. Aceptaremos cualquier ayuda en nuestra guerra contra el mal.', },
    {'Busca signos de la Guadaña de Elune y regresa a Villa Oscura, con Jonathan Carevin.', },
  },
  [1044] = {
    'La respuesta a las preguntas',
    {'Solucionaremos el problema de los huargen, no lo dudes. Ese mal que tu amiga trajo a nuestros bosques será contenido. Y has de saber que no le guardo rencor por sus actos. En estos tiempos se fraguan extraños acontecimientos, $N, la oscuridad no descansa.|n|nNo te entretengo más. Sospecho que hay otros que también deberían saber de lo que has encontrado en las minas del Bosque del Ocaso.', },
    {'Regresa a Darnassus y habla con Thyn\'tel Tejespada.', },
  },
  [1045] = {
    'Un nuevo adorno',
    {'Estoy seguro de que Dartol, el difunto mago, pretendía usar su vara para someternos y destruirnos igual que lo han hecho los orcos y los elfos de la noche. Ahora le daremos un uso nuevo.|n|nRan Sangradientes es el rey de todos los fúrbolgs de Vallefresno. Su tribu, los Sangradientes, son los más poderosos y se recluyen en un campamento justo al este.|n|nMátalos a todos y tráeme la calavera de Ran. Veamos si le podemos dar un buen uso.', },
    {'Consigue la calavera de Ran Sangradientes y la vara de Dartol.', },
  },
  [1046] = {
    'El verdadero poder de la vara',
    {'Ahora, toma la vara y, mientras utilizas su poder, habla con mi hermano, Ota Wen.|n|nOta está entre los otros fúrbolgs que los orcos han capturado y encerrado en la jaula gigante del lado norte de Refugio Brisa de Plata. La vara te permitirá convencer a Ota y a los otros fúrbolgs levantarse y atacar a la Horda.|n|nEntonces podrás ir a donde te lleve tu camino. Solo recuerda que has encontrado un nuevo amigo por lo que has hecho.', },
    nil,
  },
  [1047] = {
    'La nueva frontera',
    {'¡Atención, héroes!|n|n¡El Círculo Cenarion busca voluntarios sanos para explorar las vastas fronteras nuevas de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en representación suya.|n|nTodos aquellos que estén interesados pueden solicitar audiencia en el Círculo Cenarion. ¡Hablad con el archidruida Fandral Corzocelada de Darnassus para más información!', },
    {'Habla con el archidruida Fandral Corzocelada en el Enclave Cenarion de Darnassus sobre la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.', },
  },
  [1048] = {
    'En el Monasterio Escarlata',
    {'Mientras la Dama Oscura se encarga de retener el avance del Rey Exánime por el norte, yo me ocupo de los problemas que tienen lugar cerca de nuestro hogar.|n|nSin duda, los humanos que se hacen llamar la Cruzada Escarlata representan la mayor amenaza en nuestra zona. Los Claros de Tirisfal están atestados de estas pequeñas hormigas rojas.|n|nVe al Monasterio, $C, y acaba con la alta inquisidora Melenablanca y sus principales tenientes.', },
    {'Mata a la alta inquisidora Melenablanca, al comandante Escarlata Mograine, a Herod el Campeón Escarlata y al maestro de canes Loksey, y después ve a ver de nuevo a Varimathras a Entrañas.', },
  },
  [1049] = {
    'Compendio de los Caídos',
    {'Las intenciones del Anillo de la Tierra para con nuestros hermanos eran puras. ¿Pero quién sabe las motivaciones de los que confabulaban con el Consejo de los Ancianos?|n|nLa historia de los Renegados con los que nos aliamos está plagada de grandes engaños, de ahí que nuestro pacto con ellos haya sido breve. Quizás Cairne fue lo suficientemente inteligente para atender a las advertencias de Orgrimmar...|n|nEn lo más profundo del Monasterio Escarlata se encuentra el Compendio de los Caídos, custodiado por agresivos y fanáticos humanos. Su método proviene de la locura pero su trabajo de investigación puede resultar de utilidad.', },
    {'Recupera el Compendio de los Caídos del Monasterio que se encuentra en los Claros de Tirisfal y regresa ante Sabio Buscador de la Verdad, que está en Cima del Trueno.', },
  },
  [1050] = {
    'Mitología de los titanes',
    {'¡El futuro es ineludible! Nos estrellamos contra él como las gotas de lluvia contra el Mare Magnum.|n|nPero quizás el estudio del pasado nos ayude a prepararnos mejor para lo desconocido.|n|nAntes de que la tragedia se abatiera sobre Lordaeron, existía un templo del saber oculto en los Claros de Tirisfal. Se dice que la biblioteca del antiguo Monasterio albergaba un libro llamado Mitología de los titanes.|n|nSi me lo traes, puede que consigamos desvelar los secretos del pasado.', },
    {'Coge Mitología de los titanes en el monasterio y llévaselo a la bibliotecaria Mae Palipolvo a Forjaz.', },
  },
  [1051] = {
    'La venganza de Vorrel',
    {'Aunque tengo libre albedrío, no puedo seguir sirviendo a la Dama Oscura. Siento que se acaba mi tiempo en Azeroth. Mi fuerza vital está mermada.|n|n¡Es culpa del interrogador Vishas! ¡Me torturó durante semanas! Me quitó la alianza y se la dio a su mujer. ¡Maldito!|n|nMe vengaré... ¡Juro que me vengaré!|n|nEse cretino pomposo anda presumiendo de su mujer, Nancy, que vive junto al Lago Lordamere. Liquida a esa bruja y llévale la alianza a mi mujer, Monika, a Molino Tarren.|n|nCumple mi último deseo...', },
    {'Lleva la alianza de Vorrel Sengutz a Monika Sengutz de Molino Tarren.', },
  },
  [1052] = {
    'El sendero Escarlata',
    {'Nosotros, los de la Cruzada Escarlata, hemos reclamado las fortalezas desde la Vega del Amparo hasta los Claros de Tirisfal. Nos sentimos bastante orgullosos de haber conseguido nuestros bastiones en Lordaeron.|n|nHas demostrado estar en contra de los no-muertos en Desolace. Pero el corazón de la Plaga está en Lordaeron.|n|nVe a la ciudad de Costasur, en los Reinos del Este. Busca a un cruzado llamado Raleigh el Devoto. Dale esta carta de recomendación que lleva mi sello y te escoltará a un lugar de honor en nuestro Monasterio Escarlata.', },
    {'Lleva la carta de mención honorífica del hermano Anton a Raleigh el Devoto, en Costasur.', },
  },
  [1053] = {
    'En el nombre de la Luz',
    {'Una vez serví a la Cruzada Escarlata con honor, lealtad y orgullo. Creí que su causa era noble: Librar Azeroth de los no-muertos.|n|nPero según pasé más y más tiempo en el Monasterio, en los Claros de Tirisfal, me di cuenta de que habían perdido la noción de la realidad. Ahora creen que todo aquel que no lleva el tabardo de la Cruzada, está apestado. Hombres y mujeres inocentes torturados porque, supuestamente, estaban apestados.|n|nHay que poner fin a la Cruzada Escarlata, en el nombre de la Luz. Tú, $N, debes destruir al enloquecido régimen.', },
    {'Mata a la alta inquisidora Melenablanca, al Comandante Escarlata Mograine, a Herod, el Campeón Escarlata y al maestro de canes Loksey. A continuación, preséntate ante Raleigh el Devoto, en Costasur.', },
  },
  [1054] = {
    'Matanza selectiva',
    {'Directamente al norte de Astranaar están los fúrbolgs Piel de Cardo. Mis exploradores me informan de que en los últimos meses han aumentado mucho sus efectivos. Si acaban siendo demasiados, podrían envalentonarse y atacar directamente Astranaar.|n|nMata a tantos de su clase como puedas pero tráeme la calavera de su jefe como prueba de que hemos reprimido el movimiento... por ahora.|n|nSeguiré aquí en Astranaar y esperaré tus noticias. Que Elune esté contigo.', },
    {'Llévale la calavera de Dal Zarpasangrante a Raene Correlobo en Astranaar.', },
  },
  [1055] = {
    'Encontrar a Teronis',
    {'La vara, ahora completa, está en tus manos. Shael\'dryn se alegrará al enterarse de tu éxito.', },
    {'Vuelve junto a Shael\'dryn en la Poza de la Luna.', },
  },
  [1056] = {
    'Viaje a Cima del Espolón',
    {'Según los espíritus del bosque, eres valiente y no te importa viajar.|n|nHacia el sur, cerca del Lago Mystral, se encuentra un túnel conocido como El Paso del Espolón. Este túnel lleva a una zona llamada Risco Cortaviento en Sierra Espolón. Cuando llegues allí, prosigue tu camino hacia el suroeste hasta pasar el Lago del Peñasco, dirígete entonces hacia el norte por una cuesta empinada hasta alcanzar la Cima del Espolón.|n|nAllí aguarda el vigilante Albagorm. Presta atención a su encargo, $R.|n|nEl viaje será peligroso.', },
    {'Ve junto al vigilante Albagorm en la Cima del Espolón.', },
  },
  [1057] = {
    'La reconquista de La Vega Carbonizada',
    {'Como $Gprotector:protectora; de los espíritus, sin duda sabrás por qué siento tanta inquietud.|n|nHas viajado a través de estas montañas para llegar a la cumbre. Seguro que has visto la parodia en la que se ha convertido esta tierra. La codicia ha llevado a la destrucción de estas colinas sagradas.|n|nEl ambicioso ejército de industriales mecanizados, incendió La Vega Carbonizada, al sur. Peor aún, los Furia Sangrienta que han invadido la tierra, nos niegan el paso para comenzar a reconstruir.|n|n¡Expulsa a las malvadas arpías, $N!', },
    {'El vigilante Albagorm en la Cima del Espolón quiere que mates a 7 arpías Furia Sangrienta, a 7 emboscadoras Furia Sangrienta, a 7 destripadoras Furia Sangrienta y a 7 malaplumas Furia Sangrienta.', },
  },
  [1058] = {
    'Magia del bosque de Jin\'Zil',
    {'¡Qué bien, qué bien!|n|n¡Tres cajitas para tres elfitos! ¿Pero qué haremos con nuestros simpáticos amiguitos "abraza-árboles"? Mmm... Démosles un poco de... ¿Cómo la llaman...? ¡Magia del bosque!|n|n¡Necesitaré un buen montón de savia del Espolón! Tráeme algunos mostachos Crepusculares de esos horribles felinos. Y muchos ojos de trotadores... Nunca se puede tener suficientes ojos de trotadores. Oh, y que no nos olvidemos, una preciosa escama de dragón hada.|n|n¡Vete rápidamente a la Cima del Espolón, $N! Así podré crear algo de magia del bosque.', },
    {'El médico brujo Jin\'Zil en Malaka\'jin quiere 5 porciones de savia del Espolón, 5 mostachos Crepusculares, 30 ojos de trotadores y una escama de dragón hada.', },
  },
  [1059] = {
    'La reconquista de La Vega Carbonizada',
    {'Hemos sometido a los Furia Sangrienta. Pero volverán a reagruparse pronto si no hacemos nada por remediarlo.|n|nAl sur de Los Baldíos hay una tierra conocida como Las Mil Agujas. Si te diriges hacia el oeste en Las Mil Agujas, hasta que llegues al Linde del Bosque de Feralas, encontrarás a un druida llamado el Díscolo Falfindel.|n|nEste sabio druida es capaz de invocar poderosos espíritus del bosque que podrán ayudarnos a reclamar La Vega Carbonizada.|n|n¡Háblale de nuestra gran necesidad! ¡Ve a buscarlo!', },
    {'Ve a ver al Díscolo Falfindel en la frontera entre Las Mil Agujas y Feralas.', },
  },
  [1060] = {
    '[DEPRECATED] Una carta para Jin\'Zil',
    {'Has hecho un gran trabajo para mí, $N. Eres como una pata de conejo de la suerte y eso es algo que siempre me alegro de ver.|n|nLas arpías no son de los alrededores de Los Baldíos. Proceden de un lugar llamado Espolón, muy lejos al noroeste desde aquí. Aunque es probablemente un lugar peligroso para ti, necesito que le entregues esta misiva a un viejo amigo que vive allí, un médico brujo que responde al nombre de Jin\'Zil.|n|nSe alegrará de saber que Serena Sangrepluma ha muerto y creo que Espolón te parecerá un lugar interesante.', },
    {'Entrégale la carta de Darsok a Jin\'Zil en su cueva de Malaka\'jin, en Espolón.', },
  },
  [1061] = {
    'Los espíritus del Espolón',
    {'Los espíritus de Sierra Espolón están enojados por la intrusión de los goblins y sus siervos. Por eso la tierra se ha lamentado y aquellos que aún escuchan han oído su súplica.|n|nSe envió a Seereth Petrajada, una prometedora chamán de la Horda. Nos dijo que los goblins están deforestando la tierra a gran velocidad y pidió ayuda.|n|nVe a Sierra Espolón a hablar con ella; su campamento está cerca de la Vega del Gran Bosque. Lo mejor será que sigas el camino hacia el oeste desde El Cruce, en Los Baldíos.', },
    {'Habla con Seereth Petrajada en la frontera entre Sierra Espolón y Los Baldíos.', },
  },
  [1062] = {
    'Los invasores goblin',
    {'La empresa goblin Ventura y Cía. llegó a Sierra Espolón, cortando árboles y quemando enormes secciones de bosque. Los espíritus del lugar están prácticamente ciegos de dolor e ira. ¡Debemos detener a Ventura y Cía.!|n|nDirígete al noroeste, más allá de la Vega del Gran Bosque hasta el Risco Cortaviento. Encontrarás a los goblins y a sus siervos en pleno trabajo. Demuéstrales que la Horda no permitirá la explotación de Espolón. Y hazlo utilizando el único idioma que comprenden...|n|nLa violencia.', },
    {'Mata a 15 leñadores de Ventura y Cía. y vuelve a ver a Seereth Petrajada, en la frontera entre Espolón y Los Baldíos.', },
  },
  [1063] = {
    '[DEPRECATED] La bruja anciana',
    {'Para conectar realmente con los espíritus de Espolón, debemos consultar con los ancestros tauren.|n|nNo sé el nombre de muchos de los líderes, pero sí conozco uno: Magatha. He oído que es muy vieja y muy sabia. Si hay alguien que pueda conseguir ayuda espiritual de los tauren, es ella.|n|nMagatha vive en la capital tauren de Cima del Trueno, en el Alto de los Ancestros. En el risco que queda al noreste de la ciudad. Habla con Magatha y cuéntale el peligro que corre Sierra Espolón.', },
    {'Habla con Magatha en Cima del Trueno.', },
  },
  [1064] = {
    '[DEPRECATED]La ayuda de los Renegados',
    {'Los tauren tienen un vínculo con la tierra y me apena conocer la difícil situación de Espolón pero me temo que para salvar a la tierra primero debemos eliminar el mal que la puebla.|n|n¿No es una suerte, pues, que los Renegados sean nuestros aliados? Ellos saben mucho del mal y creo que podrán ayudarnos. De ese modo, reforzarán la confianza entre nuestros pueblos.|n|nHabla con la boticaria Zamah, una erudita y emisaria de los Renegados. La podrás encontrar en las Pozas de las Visiones, al pie del Alto de los Espíritus.', },
    {'Habla con la boticaria Zamah en las Pozas de las Visiones de Cima del Trueno.', },
  },
  [1065] = {
    '[DEPRECATED]Viaja a Molino Tarren',
    {'Para liberar a Espolón de Ventura y Cía., debemos tomar medidas extremas pero evitar el derramamiento de sangre.|n|nPuede que un colega mío tenga lo que necesitamos. Su nombre es Lydon y se encuentra en la ciudad de Molino Tarren en las Laderas de Trabalomas, en la lejana tierra de Lordaeron.|n|nPara llegar a Trabalomas viaja en zepelín hasta nuestra capital, Entrañas. Después ve en dirección norte a los Claros de Tirisfal, al sudeste hasta Argénteos y en dirección sur para llegar a Trabalomas.|n|nBusca a Lydon y entrégale esta nota en la que se detalla todo lo que necesitamos.', },
    {'Entrégale la nota de Zamah al boticario Lydon, que está en Molino Tarren.', },
  },
  [1066] = {
    '[DEPRECATED]Sangre inocente',
    {'Voy a crear una toxina que drene la violencia de Ventura y Cía.; así se volverán débiles y dóciles. Eso solucionará el problema de la Horda en Sierra Espolón.|n|nPero necesito sangre inocente, que es difícil de conseguir.|n|nPor suerte, la Hermandad, que es un grupo de maleantes humanos de esta zona, emplea a magos de la sombra, que recolectan sangre inocente para sus turbios propósitos.|n|nLos encontrarás en el Castillo de Durnholde, al sureste de aquí.', },
    {'Lleva 5 viales de sangre inocente al boticario Lydon de Molino Tarren.', },
  },
  [1067] = {
    '[DEPRECATED]Regresa a Cima del Trueno',
    {'Aquí está la toxina. Tendrá un efecto favorable, quizás incluso contagioso, en Ventura y Cía. ¡Me emociona ver una demostración práctica de mi trabajo!|n|nPero antes de usarla, llévasela a la boticaria Zamah. Tiene que diseñar un proceso que intensifique el efecto de la toxina.', },
    {'Lleva la toxina de Lydon a la boticaria Zamah de Cima del Trueno.', },
  },
  [1068] = {
    'Las sierras XT:4 y XT:9',
    {'Existe una relación entre la magia espiritual del chamán y la magia natural del druida. Es por ello que el chamán puede escuchar la llamada de los espíritus del Espolón. Yo casi no puedo escuchar muchos de sus susurros, pero existe una visión, un mensaje, muy claro...|n|nTuve una visión... dos máquinas parecidas a dos hombres en el Risco Cortaviento, al noroeste de la Vega del Gran Bosque, derribando árboles a gran velocidad. Debemos detener a estas bestias metálicas.|n|nEn mi visión, las máquinas estaban marcadas con extraños símbolos:|n|nXT:4 y XT:9.', },
    {'Destruye las sierras XT:4 y XT:9, a continuación vuelve a ver a Seereth Petrajada, en la frontera entre Sierra Espolón y Los Baldíos.', },
  },
  [1069] = {
    '[DEPRICATED] Huevos de arañas Musgondo',
    {'¡Las tortillas de huevos de araña están causando furor en Bahía del Botín! Solo hay un problema... no hay huevos en Bahía del Botín.|n|n¡Puedo oler la oportunidad!|n|nLa araña Musgondo vive en el Risco Cortaviento y en el Cañón Sishir, en Sierra Espolón hacia el noroeste. Tráeme sus huevos ¡y te pagaré un dineral!|n|nEn el Risco Cortaviento, los huevos estarán cerca de lo que quede de arboleda.|n|nEn el Cañón Sishir... bueno, si no tienes un estómago a prueba de bomba, quizás debas limitarte a recolectar los huevos en el Risco Cortaviento...', },
    {'Llévale 15 huevos de Musgondo a Mebok Mizzyrix en Trinquete.', },
  },
  [1070] = {
    'Estar de guardia en Espolón',
    {'Hola, $N.|n|nPareces tener ansias de conocer mundo. ¿Has estado en Sierra Espolón? Es una tierra apestada por Ventura y Cía. y otros enemigos de los elfos nocturnos.|n|nRecientemente, la centinela Correlobo envió a mi amiga Kaela Lanzasombra allí para investigar lo que está pasando en la tierra, pero todavía no sé nada de ella. Y me preocupa mucho, porque la Alianza envió a un mago gnomo con ella... y eso es sin duda una señal de problemas.|n|n¿Podrías encontrarla y venir a informarme?', },
    {'Encuentra a Kaela Lanzasombra contemplando la vista del valle a la entrada del Risco Cortaviento, en Sierra Espolón.', },
  },
  [1071] = {
    'Una tregua para el gnomo',
    {'Verás, $N, soy miembro de la Asamblea Iluminada de Arcanología, Alquimia e Ingeniería, y mi objetivo... no, ¡mi DEBER!... es demostrar a esos elfos de la noche, que la unión de magia, combinaciones y mecanismos puede ayudarles a salvar sus bosques.|n|nPero se trata de una guerra dura, ¡y, por lo visto, esos goblins se reproducen como conejos! Ni siquiera he tenido tiempo de construir mis últimos inventos.|n|nNecesito algo de tiempo para planear y organizarme. Pero, para ello, necesito que me ayudes a mantener a raya a los goblins en el Risco Cortaviento, al este...', },
    {'Mata a 10 leñadores de Ventura y Cía. y a 10 deforestadores de Ventura y Cía. A continuación, vuelve a ver a Gaxim Silvóxido en Espolón.', },
  },
  [1072] = {
    'Un viejo colega',
    {'El dispositivo en el que estoy pensando, es la versión más avanzada hasta la fecha. Pero necesitaremos una poción especial para que funcione. Y creo que también podríamos intentar ir a lo grande, porque esta podría ser tu última misión.|n|nY, para eso, vamos a necesitar explosivos potentes: nitromirgliceronio.|n|nEl único que puede hacer NG-5 es un viejo amigo mío: Lomac Destrabaengranajes. Búscalo en Ciudad Manitas.|n|nConvéncelo para que nos haga NG-5. Me pondré a trabajar en mis dispositivos.', },
    {'Habla con Lomac Destrabaengranajes en Forjaz.', },
  },
  [1073] = {
    'Ineptitud + Productos químicos = Diversión',
    {'¡Ja, ja, ja! ¿Necesitas nitromirgliceronio para evitar que los goblins destruyan un bosque?|n|nNo me importa si conoces a Gaxim o no... Te lo daré solo para verte a ti, o a los otros, explotar en un millón de trocitos.|n|nPero hay un problema: me he quedado sin NG-5.|n|nPero mira, si me traes las pociones correctas, te prepararé lo que necesitas ahora mismo.|n|nLo mínimo que podías hacer es demostrar tu habilidad como $Gboticario:boticaria; antes de que te dé una muestra de mi mejor creación.', },
    {'Lleva 4 pociones menores de maná y 2 elixires de entereza menor a Lomac Destrabaengranajes en Forjaz.', },
  },
  [1074] = {
    'Ineptitud + Productos químicos = Diversión',
    {'Aquí tienes, $Gforastero:forastera;... Pero ten muchísimo cuidado... es un material muy volátil.|n|nSi, realmente, Gaxim es tu amigo, dale recuerdos de mi parte. Si no es así, que te diviertas cuando explotes...', },
    {'Lleva el nitromirgliceronio de vuelta a Gaxim Silvóxido en Espolón.', },
  },
  [1075] = {
    'Un pergamino de Mauren',
    {'Muy bien y, ahora, la parte de detonación remota de mi plan... Oh, eso no te lo he explicado todavía, ¿no?|n|nPues en resumen se trata de esto: con un poco de magia, puedo conseguir que los explosivos exploten cuando tú no estés cerca. Estoy creando un dispositivo que te permitirá, tan solo con pulsar un botón, hacer que el NG-5 explote.|n|nPero necesito un hechizo de un amigo de Ventormenta... Collin Mauren. Le encontrarás en el Barrio de los Magos. Es un humano, así que no deberías tener problemas para encontrarle.', },
    {'Encuentra a Collin Mauren en Ventormenta.', },
  },
  [1076] = {
    'Demonios en los Páramos de Poniente',
    {'Ah, creo que ya lo tengo. Un hechizo mensajero... Creo que ese es el efecto que está buscando.|n|nTendré que hacer un pergamino donde grabar el hechizo. Para ello, necesitaré restos de un demonio de polvo.|n|nMientras reúno el resto de los componentes, ¿qué te parece si vas a los Páramos de Poniente a buscar a una de esas malvadas criaturas? Los demonios de polvo son peligrosos, pero seguro que puedes encargarte de algo así si estás $Gdispuesto:dispuesta; a someterte a uno de los experimentos de Gaxim.|n|nEstaré aquí cuando vuelvas.', },
    {'Lleva restos de demonio de polvo a Collin Mauren en Ventormenta.', },
  },
  [1077] = {
    'Entrega especial para Gaxim',
    {'Aquí estás, $N. Con esto bastará.|n|nPor favor, dale recuerdos a Gaxim la próxima vez que le veas. Me muero de ganas por saber qué tal salió todo cuando terminéis.|n|nAdiós.', },
    {'Lleva el Pergamino de mensajes de vuelta a Gaxim Silvóxido en Espolón.', },
  },
  [1078] = {
    'Escamas cristalizadas para Mauren',
    {'Todos los viajeros siguen preguntándome por Sierra Espolón. Parece ser un lugar muy popular para aventureros... No importa si buscas dracoleones, elementales, o tienes algo que hacer con Ventura y Cía.|n|nEn La Vega Carbonizada, en Espolón, solía haber una especie de basiliscos cuyas escamas, al molerlas, producían un increíble componente para alguno de los hechizos que he creado.|n|nSi esos basiliscos siguen con vida, me encantaría conseguir algunas escamas.|n|nTómate tu tiempo, no corre prisa, pero puedo pagarte generosamente.', },
    {'Lleva 8 escamas cristalizadas a Collin Mauren en Ventormenta.', },
  },
  [1079] = {
    'Operaciones secretas: plan A',
    {'Muy bien, $N. Presta mucha atención. Los dispositivos están terminados y listos para usar.|n|nLlévate estas páginas. Contienen más información sobre los detonadores y explosivos y dónde deberías colocarlos.|n|nRecuerda, el éxito de tu misión no depende de la destrucción que provoques. El éxito del plan A depende de que recuperes los planos de ingeniería de Ventura y Cía. que están dentro de la serrería al sur del Lago del Peñasco.', },
    {'Recupera los planos de ingeniería de Ventura y Cía. de la serrería en el Risco Cortaviento.', },
  },
  [1080] = {
    'Operaciones secretas: plan B',
    {'El plan Beta es como el plan Alfa, $N.|n|nCrearemos una distracción y robamos las valiosas cartas.|n|nLo más importante es conseguir sus cartas... No lo olvides.|n|nLas páginas que te he dado te indicarán dónde colocar los explosivos. Solo tienes que volver aquí con vida... y con las cartas...', },
    {'Recupera las cartas de Ventura y Cía. de la Mina Cortaviento, en el extremo este del Risco Cortaviento.', },
  },
  [1081] = {
    'El recibimiento de Tyrande',
    {'$N, seguro que la mismísima Tyrande Susurravientos querrá agradecerte tu participación en esta misión.|n|nQuizás no te lo parezca a primera vista, pero lo que has ayudado a empezar, podría reforzar nuestra ciudadela en Sierra Espolón.|n|nSi te consideras $Gnuestro aliado:nuestra aliada; y estás en contra de estas atrocidades, vete a ver a Tyrande en el Templo de la Luna, en Darnassus.', },
    {'Encuentra a Tyrande Susurravientos en Darnassus.', },
  },
  [1082] = {
    'Noticias para Centinela Thenysil',
    {'$N, nos has prestado un gran servicio.|n|nLas Centinelas de Vallefresno te recompensarán generosamente si les informas de que Gaxim y yo estamos vivos. Diles que vamos de camino a detener a Ventura y Cía. y curar la tierra.|n|nBusca a Tara Thenysil en Astranaar; estará encantada al verte volver con buenas noticias.', },
    {'Ve a ver a la centinela Thenysil en Vallefresno.', },
  },
  [1083] = {
    'Los espíritus iracundos',
    {'No tengo muy claro lo que Ventura y Cía. hizo en La Vega, pero es obvio que consiguieron dominar a las criaturas que vivían allí.|n|nIncendiaron el bosque y utilizaron sus inventos de destrucción para diezmar La Vega tanto como pudieron.|n|nPero, en su ignorancia, hicieron algo más: liberaron espíritus ardientes, elementales de fuego, piedra y furia.|n|nLa tierra no tendrá la oportunidad de ver la sonrisa de Elune mientras esas criaturas vaguen a su libre albedrío.|n|nTráeme sus ascuas ardientes para demostrarme que has conseguido reducir sus filas.', },
    {'Lleva 8 ascuas ardientes de cualquiera de los elementales de fuego de la Vega Carbonizada a Kaela Lanzasombra, en Espolón.', },
  },
  [1084] = {
    'Los antárboles corruptos',
    {'Me parece que los protectores de La Vega, los antárboles, han tenido algo que ver con la marcha de Ventura y Cía. Por desgracia, incluso esos antiguos guardianes, están corruptos ahora.|n|nGaxim cree que su corrupción está, de alguna forma, vinculada con las armas que los goblins utilizaron en su retirada.|n|nLe dije que conseguiría una muestra de un antárbol muerto para que pudiera estudiarla y descubrir si es cierto.|n|nTráeme metralla para que el gnomo pueda contarme algo más...', },
    {'Lleva una pieza de metralla corroída a Kaela Lanzasombra en Espolón.', },
  },
  [1085] = {
    'Estar de guardia en Espolón',
    {'La situación aquí, en Espolón, es obviamente grave para que una elfa de la noche y un gnomo estén trabajando juntos.|n|nVentura y Cía. ha devastado estas tierras y yo he pasado la mayor parte de mi tiempo intentando poner fin a la destrucción.|n|nNo juzgues a Gaxim prematuramente. Comprende la necesidad que tenemos de trabajar juntos.|n|nSi quieres ayudarnos, empieza por hablar con Gaxim.|n|nSiento no poder enviarte de vuelta a ver a Tara con buenas noticias todavía. Quizás pronto...', },
    {'Habla con Gaxim en Sierra Espolón.', },
  },
  [1086] = {
    '[DEPRECATED]El aeropuerto',
    {'La toxina ya está lista. Solo queda entregarla. Y eso te toca a ti, $N.|n|nVentura y Cía. tiene que disponer de un sistema para enviar mensajes y paquetes ligeros entre su administración central y las operaciones de Sierra Espolón. Probablemente sea un aeropuerto, no lo bastante grande para un zepelín, pero sí para un transportador aéreo. Recorre las zonas de influencia de Ventura y Cía. en Sierra Espolón y encuentra el aeropuerto. Si lo localizas, planta la toxina.|n|nY sal de ahí inmediatamente.', },
    {'Lleva el nublador tóxico al aeropuerto de Ventura y Cía. e informa a la boticaria Zamah.', },
  },
  [1087] = {
    'El legado de Cenarius',
    {'No puedes ni imaginarte el odio que siento por esta tierra maldita. Los de Cenarius y los druidas kaldorei de la cima, utilizan sus patéticos poderes para reprimir el flujo de la magia, incluso muy lejos, al sur de sus patéticas posesiones... sus amados bosques.|n|nYo podría regresar a Jaedenar y regocijarme con el flujo de la magia, pero mi maestro no me permite volver hasta que no haya finalizado mi trabajo.|n|nNo me cabe la menor duda de que sientes tanto aprecio por los elfos de la noche y sus pequeños aliados como yo. Ayúdame y ambos quedaremos satisfechos.', },
    {'Mata a 4 Hijos de Cenarius, 4 Hijas de Cenarius y 4 botánicas Cenarion para Braelyn Manofuego, cerca del Refugio Roca del Sol.', },
  },
  [1088] = {
    nil,
    {'Creyeron poder detener el flujo de la magia. Se equivocaron. Creyeron que podían ocultar a Ordanus, ¡pero conseguiré su cabeza!|n|nLa magia me otorga la visión verdadera. Sí... ahí está. Una encrucijada... En la copa de un gran árbol en el Bosque de Vallefresno. Un nombre... Algaba. Uno de los hijos mayores del dios del bosque. Le hicieron desaparecer de la cima antes de que pudiera encontrarle, pero se está quedando sin tiempo.|n|nTráemelo y compartiré contigo un poderoso regalo.', },
    {'Lleva la cabeza de Ordanus a Braelyn Manofuego cerca del Refugio Roca del Sol.', },
  },
  [1089] = {
    'El Cubil',
    {'Los druidas construyeron El Cubil del Espolón, en la Cima del Espolón, y allí guardan poderosos objetos.|n|nDiseñaron un complejo sistema para mantener estos objetos alejados de manos equivocadas.|n|nPor fortuna, he logrado... extraer algunos detalles de uno al que he interrogado.|n|nEn una antorcha de la entrada a El Cubil encontrarás la llave del Guardián. Con esta podrás abrir los cofres de El Cubil. Los objetos que obtengas te permitirán abrir su tesoro, ubicado en una de las zonas centrales.', },
    {'Ve a El Cubil, en la Cima del Espolón. Utiliza la llave del Guardián y consigue los objetos ocultos del druida. Utiliza esos objetos para abrir el tesoro de El Cubil del Espolón.', },
  },
  [1090] = {
    'Órdenes de Gerenzo',
    {'¿Sabes? Una vez fui la segunda persona más importante de este lugar. Pero todo cambió con la llegada de Gerenzo. Despidió a mi jefe, Ziz Fizziks, y me envió a trabajar a las minas. Sin embargo, Ziz me dijo que permaneciese aquí y reuniese algo de información. Su nuevo jefe nos pagará bien si podemos descubrir los planes de Gerenzo.|n|nDe todas formas, lo que sí sé es que Gerenzo ha ordenado excavar grandes cantidades de su mineral dorado verdoso. Puedo conseguirte una muestra para que se la lleves a Ziz, pero tendrás que vigilar por si aparecen patrullas mientras lo hago.', },
    {'Consigue el misterioso mineral de Piznik cuando termine de extraerlo.', },
  },
  [1091] = {
    'Noticias para Kaela',
    {'$N, lleva estas cartas a Kaela. Seguro que querrá saberlo. O, al menos, las Centinelas querrán.|n|nAsegúrate de decirle que hemos tenido éxito y que no podríamos haberlo logrado sin ayuda de la magia.', },
    {'Lleva las cartas de Ventura y Cía. a Kaela Lanzasombra a Sierra Espolón.', },
  },
  [1092] = {
    'Órdenes de Gerenzo',
    {'Supongo que también debería pensar en cómo salir de aquí. Las noticias de lo ocurrido aquí no tardarán en llegar a los de arriba y seguro que no van a estar muy contentos al verme de nuevo.|n|nSaldré a hurtadillas para encontrarme con Ziz. Con suerte, ¡podrá encontrarme otro trabajo!|n|nVoy a intentar arreglar un poco este desastre, pero deberías llevar la muestra del mineral a Ziz ahora mismo. Me dijo que iba a establecer su campamento en alguna parte del lado oeste del Risco Cortaviento. Buena suerte.', },
    {'Lleva la mena sin identificar a Ziz Fizziks, en Sierra Espolón.', },
  },
  [1093] = {
    'Súper Segadora 6000',
    {'Es terrible lo que Ventura y Cía. ha hecho aquí, ¿verdad? ¿En qué estaban pensando? ¡Una compañía goblin contratando a un gnomo!|n|nPor suerte para mí, Petardol puede distinguir a un genio en cuanto lo ve. ¡Me contrató justo después de que me despidieran!|n|nMe dice que han construido una enorme máquina cortaleña y Petardol quiere que robe los planos para él. El problema es que Gerenzo, maldito gnomo, me quiere muerto... Quizás tú podrías robar los planos por mí... Seguro que los lleva encima alguno de sus operadores.', },
    {'Consigue los planos de la Súper Segadora 6000 para Ziz Fizziks en Sierra Espolón.', },
  },
  [1094] = {
    'Más instrucciones',
    {'Este sobre contiene toda la información que conseguí coger antes de que me echaran a patadas... Documentos internos de Ventura y Cía., algunos manuales, cosas técnicas... Oh y, por supuesto, los planos de la Súper Segadora 6000.|n|nPetardol vive en Trinquete, en Los Baldíos. No creo que tengas problemas para encontrarle, es pequeñito y verde.', },
    {'Lleva el sobre lacrado a Petardol a Trinquete, en Los Baldíos.', },
  },
  [1095] = {
    '[DEPRECATED] Más instrucciones',
    {'El asunto de este gnomo contratado por Ventura y Cía. ha provocado algo de revuelo en Minahonda. Los grandes comerciantes no aprueban la asociación de Razdunk con el tal Gerenzo.|n|nRiddlevox me ha pedido que me ocupe del problema y seguro que la orden viene de los grandes comerciantes. Por supuesto, el Director no me lo ha dicho. Digamos que... tengo un presentimiento.|n|nSea como fuere, hay que apartar a Gerenzo y eso parece una prueba a la medida de Fizziks.', },
    {'Lleva las nuevas órdenes a Ziz Fizziks en Sierra Espolón.', },
  },
  [1096] = {
    'Gerenzo Silbillave',
    {'Una vez vi a Gerenzo, pero te diré algo, es difícil de mirar... Su carne parece podrida y tiene injertos de metal y engranajes por todo su cuerpo. Ha reemplazado algunos de sus miembros por otros mecánicos.|n|nGerenzo vigila toda la zona, desde el noreste de aquí, más arriba del Lago del Peñasco, cerca de la noria. Yo no podría llegar hasta ahí arriba, por no mencionar enfrentarme a Gerenzo... Pero tú pareces muy capaz de hacerlo.|n|nSi le matas por mí, ¡te recompensaré!', },
    {'Lleva el brazo mecánico de Gerenzo Silbillave a Ziz Fizziks, en Sierra Espolón.', },
  },
  [1097] = {
    'La tarea de Elmore',
    {'Hay un enano forjador de armas en Ventormenta, Grimand Elmore, que ha enviado un mensaje diciendo que necesita ayuda con una entrega. Creo que quiere enviar un paquete a su hogar, en el norte.|n|n¡Tienes unas piernas muy fuertes! Si te interesa ponerlas en marcha, vete a hablar con Grimand. Podrías sernos muy útil aquí, pero también debemos mantener nuestros tratos con los enanos.|n|nPuedes encontrar a Grimand Elmore en la tienda de armas del Distrito de los Enanos de Ventormenta, en la sección noreste de la ciudad.', },
    {'Habla con Grimand Elmore en Ventormenta.', },
  },
  [1098] = {
    'Mortacechadores en Colmillo Oscuro',
    {'Estamos preparando un ataque a Colmillo Oscuro y enviamos a dos mortacechadores a investigar. De eso hace ya muchos días ¡y necesitamos su informe para preparar el ataque!|n|n$N, tienes que ir al Castillo de Colmillo Oscuro, hacia el sur, y localizar a los mortacechadores Adamant y Vincent. Ayúdalos si lo necesitan.|n|nEsta misión es tan peligrosa como crítica, $N. No falles.', },
    {'Encuentra a los mortacechadores Adamant y Vincent.', },
  },
  [1099] = {
    '¡Los goblins ganan!',
    nil,
    nil,
  },
  [1100] = {
    'Diario de Soliceja',
    {'Abres lentamente el desgastado diario de Henrig Soliceja...', },
    {'Lee el diario de Henrig Soliceja.', },
  },
  [1101] = {
    'La bruja del Horado',
    {'¡Pobre Heralath! Y el enano Soliceja, ¡qué valiente era!|n|nNo debemos permitir que su valentía caiga en el olvido. Hay que detener a esa malvada... Charlga Filonavaja.|n|nSin duda, infiltrarse en el Horado es arriesgado pero no hay tiempo para enviar noticias a Darnassus. $N, reúne un equipo para matar a Charlga.|n|nTráeme el medallón de Filonavaja como prueba de su defunción.', },
    {'Llévale el medallón de Filonavaja a Díscolo Falfindel de Thalanaar.', },
  },
  [1102] = {
    'Un destino vengador',
    {'Cairne es un líder noble que ha unido a nuestro pueblo aquí en Cima del Trueno.|n|nPero no puedo perdonar a aquellos que nos han echado de nuestras tierras ancestrales. Mi pueblo habitó en Los Baldíos del Sur durante décadas, una tierra que era sagrada para nosotros, hasta que numerosos enemigos nos expulsaron de ellas.|n|nEl destino le depara venganza a Charlga Filonavaja, que tiene a un ejército congregado en Horado Rajacieno.|n|nTráeme el corazón de Filonavaja y podré morir en paz, $N.', },
    {'Llévale el corazón de Filonavaja a Auld Picopiedra, que está en Cima del Trueno.', },
  },
  [1103] = {
    'La llamada del agua',
    {'¡Saluditos, $Ghermano:hermana;! ¿También has venío a purificar las aguas y a demostrarle a Islen que l\'has captao to\'?|n|nYo mesmamente m\'he cargao al espíritu del agua corrupto y estaba a punto de colocar los brazales y las gotas restantes d\'agua en el blandón.|n|n¿Qué pasha? Ah, ya. Tiev s\'entera cuando algo no anda bien. Vale, Tiev podrá ayudarte mogollón si tienes que volver a ver al espíritu del agua pura.|n|nTráeme una sapta d\'agua de Islen como prueba de qu\'estás $Glisto:lista; y esperaré pa\' cumplir mi parte.', },
    {'Llévale una sapta de agua a Tiev Mordune en el Bosque de Argénteos si no consigues hablar con la manifestación de agua menor.', },
  },
  [1104] = {
    'Veneno de El Desierto de Sal',
    {'¡Tengo un montón de diseños para nuestro coche cohete! ¡Muchos! ¡Y tengo que probarlos todos!|n|nEstoy trabajando en un nuevo tipo de combustible. ¡Uno que arde a muy, muy, muy alta temperatura! Aún no he conseguido la fórmula perfecta pero creo que ya sé lo que necesito...|n|nEl veneno de los escórpidos que rondan El Desierto de Sal contiene gran cantidad de sal. ¡Es algo único y es justo lo que necesito!|n|nTráeme ese veneno y... créeme, ¡nuestro coche volará!', },
    {'Llévale 6 glándulas de veneno de escórpidos salados a Fizzle Pernolatón, que está en El Desierto de Sal.', },
  },
  [1105] = {
    'Caparazones endurecidos',
    {'Mi hermano está trabajando en un nuevo tipo de combustible para su coche cohete. Es un coco, en serio. Es tan inteligente que... ¡creo que el nuevo combustible que está diseñando es tan potente que podría corroer el chasis del coche!|n|nQuiero reforzar sus depósitos de combustible antes de que eso ocurra.|n|nLas tortugas que habitan El Desierto de Sal tienen unas conchas muy resistentes y quiero utilizarlas para hacer nuevos depósitos para nuestro coche cohete que sean capaces de contener el nuevo combustible de mi hermano.|n|nTú pareces alguien responsable. ¿Podrías conseguirme esos caparazones?', },
    {'Llévale 9 caparazones de tortuga endurecidos a Wizzle Pernolatón, que está en El Desierto de Sal.', },
  },
  [1106] = {
    'Martek el Exiliado',
    {'Estoy trabajando en un nuevo motor que hará que el coche corra como el viento. ¡Podrá incluso volar, lo sé! Lo único que tengo que hacer es crear unos pistones que puedan aguantar una presión realmente alta. ¡Todos mis ensayos fueron un fracaso porque no consigo que los pistones sean lo suficientemente resistentes!|n|nAunque hay alguien que puede que sepa cómo conseguirlo.|n|nSu nombre es Martek el Exiliado. Es un gran herrero y sabe más sobre metales que ningún otro. Llévale esta carta, ¡seguro que nos puede ayudar!|n|nAunque está muy, muy lejos, en las Tierras Inhóspitas de Azeroth, en un campamento con un goblin.|n|n¡Ve y encuéntralo!', },
    {'Llévale la carta de Fizzle Pernolatón a Martek el Exiliado, que está en las Tierras Inhóspitas.', },
  },
  [1107] = {
    'Aletas dorsales taraceadas',
    {'¡Nuestro coche cohete es el más rápido de El Desierto de Sal! Es tan rápido que... ¡tengo miedo de que la fricción lo haga reventar en pedazos!|n|nPara evitarlo, tengo que crear un compuesto para recubrir con él las piezas móviles del coche. Tiene que ser duro pero que no se rompa, y tiene que ser resistente a la corrosión de la sal o después de un tiempo en El Desierto de Sal acabará desgastándose.|n|n¿Has oído hablar de El Arrecife Mortal, $N? Está en la costa, más allá de Vega de Tuercespina. Allí habitan múrlocs de escamas saladas, y sus aletas dorsales son el ingrediente imprescindible para mi compuesto.', },
    {'Llévale 10 aletas dorsales taraceadas a Wizzle Pernolatón, que está en El Desierto de Sal.', },
  },
  [1108] = {
    'Indurio',
    {'No estoy aquí solo para estar lejos de la gente. Hay metal en abundancia en las Tierras Inhóspitas, $N, siempre que tengas las agallas para ir a por él.|n|nEl metal se llama indurio y si es cierto lo que dicen, posee una alta resistencia al calor y a la presión. Puede que sirva para el coche de Fizzle.|n|nPero tenemos que asegurarnos. Consígueme unas muestras de indurio y así podré comprobar sus propiedades.|n|nLa verdadera mena de indurio se encuentra en Uldaman, pero los troggs Grutacanto de las Tierras Inhóspitas suelen llevar encima algunas láminas de indurio. Tráeme esas láminas.', },
    {'Llévale 10 láminas de indurio a Martek el Exiliado, que está en las Tierras Inhóspitas.', },
  },
  [1109] = {
    'Guano del Horado',
    {'Como puedes comprobar, $N, tenemos unos interesantes experimentos entre manos aquí en la Sociedad Real de Boticarios.|n|nDado que yo soy el maestro aquí, mi trabajo consiste en supervisar nuestros proyectos de alquimia más ambiciosos. ¡Hay tanto trabajo y tan poco tiempo!|n|nParece que tienes muchos kilómetros a tus espaldas, $C, así que quizás puedas ayudarnos.|n|nNecesito una sustancia no muy común y un tanto nauseabunda que proviene de una extraña especie de murciélagos que solo se encuentran en ese agujero apestoso conocido como Horado Rajacieno. Tráeme el guano de los murciélagos del Horado para que podamos ponernos manos a la obra.', },
    {'Llévale una pila de guano del Horado al maestro boticario Faranell en Entrañas.', },
  },
  [1110] = {
    'Piezas de coche cohete',
    {'Je, je, con tantas carreras que se celebran aquí no es de extrañar que haya tantos accidentes. Si echas un vistazo por El Desierto de Sal te darás cuenta de que está plagado de restos de accidentes. ¡Hay piezas de coches cohete por todas partes!|n|nY tienen mucho valor para los gnomos y los goblins, que siempre están en busca de nuevos artilugios que instalar en sus coches.|n|nAsí que sal ahí fuera y consígueme algunas piezas. Tráeme un buen montón y te pagaré como mereces.', },
    {'Llévale 30 piezas de coche cohete a Kravel Karbarbán, que está en El Desierto de Sal.', },
  },
  [1111] = {
    'Maestro de muelles Vertipeluca',
    {'Mi trabajo consiste en proporcionar a los demás lo que necesitan, y en este caso los gnomos me han hecho un pedido de piezas. Las piezas llegaron a Trinquete hace una semana pero yo no he podido ir a recogerlas.|n|nAsí pues, ¿te apetece ir a dar un paseo? Ve a Trinquete y entrégale este pedido de piezas al maestro de muelles Vertipeluca, que seguramente esté en el puerto.|n|nHaz esto por mí y te encargaré más trabajos.|n|nTrabajos, $Gamigo mío:amiga mía;, que te reportarán grandes beneficios...', },
    {'Llévale el pedido de piezas de Kravel al maestro de muelles Vertipeluca en Trinquete, en Los Baldíos.', },
  },
  [1112] = {
    'Las piezas de Kravel',
    {'Aquí está el paquete para Kravel, $N. Cuando se lo entregues, dile que si quiere más pedidos especiales ¡tendrá que correr con los gastos!', },
    {'Llévale las piezas de Kravel a Kravel Karbarbán, que está en El Desierto de Sal en Las Mil Agujas.', },
  },
  [1113] = {
    'Corazones de fanatismo',
    {'Por qué necesito un tipo de guano tan poco común, te preguntarás. Bueno, para este experimento quiero ver el efecto que dos sustancias químicas diametralmente opuestas tienen entre sí, sobre todo cuando se combinan con un agente incluso más tóxico para obtener... los resultados más horripilantes.|n|nEn las cumbres más nororientales de los Claros de Tirisfal se encuentra el Monasterio Escarlata, lugar en el que se reúnen los fervientes discípulos de la Cruzada Escarlata, tanto dentro como fuera del edificio. Aunque los mates, dará igual, ninguno tiene el corazón que necesito.', },
    {'El maestro boticario Faranell de Entrañas quiere 20 corazones de fanatismo.', },
  },
  [1114] = {
    'Un envío para los gnomos',
    {'Ahora que tengo lo que necesito, entrégale estas piezas a Fizzle Pernolatón. Lleva mucho tiempo esperando por ellas. Seguro que no echará en falta la pieza con la que me he quedado...|n|n¡Y yo que tú no se lo mencionaría! Era pequeña e insignificante.|n|n¡Confía en mí!', },
    {'Llévale las piezas de coche delicadas a Fizzle Pernolatón, que está en El Desierto de Sal.', },
  },
  [1115] = {
    'Rumores',
    {'Ahora que ya hemos prestado servicio a los gnomos, ha llegado el momento de hacerles un favor a los goblins.|n|nHe oído que el piloto de carreras goblin, Nazz Vaporio, no siempre ha sido conocido por ese nombre. Me pregunto por qué se lo habrá cambiado, si será un secreto y si realmente valora ese secreto.|n|nSi alguien sabe la verdad de todo esto, ese es Krazek de Bahía del Botín, en el extremo meridional de Tuercespina. Habla con Krazek y pregúntale acerca del piloto goblin.|n|nSi consigues información relevante, puede que le saquemos beneficios.', },
    {'Habla con Krazek en Bahía del Botín, en la Vega de Tuercespina.', },
  },
  [1116] = {
    'Polvo onírico en el pantano',
    {'Si te diera información sobre Nazz te estaría haciendo un favor, $N, un gran favor. Pero has venido desde El Desierto de Sal para conseguirla... ¿estás $Gdispuesto:dispuesta; a viajar un poco más?|n|nMientras contacto con mis fuentes, ¿por qué no vas a coger algo para mí, eh?|n|nVeamos, qué podría ser... ¿Qué te parece polvo onírico de las crías de dragón que hay en el Pantano de las Penas? ¡Sí, me encantaría tener pizcas de polvo onírico para mezclarlas con mi tabaco!|n|n$N, consígueme algunas y te daré la información que andas buscando.', },
    {'Llévale 10 pizcas de polvo onírico a Krazek a Bahía del Botín. El polvo onírico se obtiene de las crías de dragón que habitan en el Pantano de las Penas.', },
  },
  [1117] = {
    'Rumores para Kravel',
    {'¡Tuve que hacer algunos favores a cambio, regalar una botella muy especial de vino élfico y atar cabos! Pero finalmente conseguí la información que querías.|n|nAquí tienes, escribí una carta en la que explico lo más destacado de nuestro amigo, Nazz Vaporio. Haz con ella lo que creas oportuno pues es demasiado peligrosa para que yo la guarde.|n|n¡Pero no le digas a nadie de dónde la has sacado!', },
    {'Llévale los rumores goblin a Kravel Karbarbán, que está en El Desierto de Sal en Las Mil Agujas.', },
  },
  [1118] = {
    'De vuelta a Bahía del Botín',
    {'$N, sé que eres $Gun:una; $C en quien puedo confiar, tanto para realizar un trabajo como para mantener la boca cerrada mientras lo haces.|n|nHe ideado un nuevo plan. Es arriesgado pero si sale bien... ¡podríamos ganar un dineral! Y creo que tú eres la persona adecuada para conocer todos los detalles.|n|nPara empezar, debes volver a Bahía del Botín. Lo siento, $N. Sé que para el último encargo también tuviste que ir allí pero, en esta ocasión, tendrás que hablar con Loquillo Pinchabujas.|n|nEntrégale esta carta y si necesita ayuda haz todo lo posible por echarle una mano. El esfuerzo merecerá la pena.', },
    {'Llévale el esquema de Kravel a Loquillo Pinchabujas a Bahía del Botín, en Vega de Tuercespina.', },
  },
  [1119] = {
    'La mezcla de Zanzil y la cerveza de tontos',
    {'Creo que ya sé cómo preparar con la mezcla de Zanzil y un poco de cerveza un brebaje bárbaro: la cerveza de tontos. Creo que es justo lo que Kravel necesita pero quiero que la pruebes y me digas qué tal son los resultados.|n|nY $N, no estés mucho tiempo sin utilizarla pues la mezcla de Zanzil tiene un efecto muy extraño sobre la levadura y no tarda mucho en estropearse.', },
    {'Llévale la cerveza de tontos a Kravel, que está en El Desierto de Sal en Las Mil Agujas.', },
  },
  [1120] = {
    'Emborrachar a los gnomos',
    {'Tenemos que probar la cerveza de tontos con uno de los equipos técnicos. Si quieres probarla con los gnomos, coge la cerveza y dásela al encargado de foso gnomo.|n|nY no tardes mucho pues la cerveza podría estropearse.', },
    {'Llévale la cerveza de tontos al encargado de foso gnomo al Circuito del Espejismo, en Las Mil Agujas.', },
  },
  [1121] = {
    'Emborrachar a los goblins',
    {'Tenemos que probar la cerveza de tontos con uno de los equipos técnicos. Si quieres probarla con los goblins, coge la cerveza y dásela al encargado de foso goblin.|n|nY no tardes mucho pues la cerveza podría estropearse.', },
    {'Llévale la cerveza de tontos al encargado de foso goblin al Circuito del Espejismo, en Las Mil Agujas.', },
  },
  [1122] = {
    'Volver a informar a Pinchabujas',
    {'¡Esa cerveza de tontos funciona a las mil maravillas! He apostado en la próxima carrera así que esperemos que los técnicos la hayan hecho buena con los coches.|n|nHay una cosa más que debes hacer: llévale esta nota a Loquillo Pinchabujas a Bahía del Botín. Le gustará saber que la prueba ha sido todo un éxito.|n|nCon un poco de suerte, podremos además conseguir más cerveza de tontos para otras carreras.', },
    {'Llévale el informe de cerveza de tontos a Loquillo Pinchabujas, que está en Bahía del Botín en la Vega de Tuercespina.', },
  },
  [1123] = {
    nil,
    {'El mayordomo del guardián Remulos, Rabine Saturna, está en Claro de la Luna buscando ayuda para explorar los vastos páramos al oeste de Tanaris y Un\'Goro. Se encuentra en Amparo de la Noche, el poblado principal de Claro de la Luna.|n|nQuiero que seas consciente de lo importante que es que estés allí pues hay ciertas tensiones entre los elfos de la noche de Darnassus y el Círculo Cenarion de Claro de la Luna. Obvia los límites raciales y aplica la sabiduría heredada de tus ancestros a la hora de tratar con el Círculo, $N. Buena suerte.', },
    {'Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Rabine Saturna. Claro de la Luna se encuentra entre Frondavil y Cuna del Invierno; para llegar, tienes que seguir el camino que sale del Bastión Fauces de Madera.', },
  },
  [1124] = {
    'Páramo',
    {'Al oeste del Cráter de Un\'Goro vía la cresta noroccidental, se encuentra una tierra inhóspita: Silithus. Pocos saben que allí se libró una guerra entre los elfos de la noche y un poder maligno y extraño. El mal fue sellado, pero sospechamos que hay fuerzas que intentan despertar a este horror inimaginable.|n|nBusca a Layo Golpe Estelar, uno de nuestros agentes en Silithus; lo encontrarás en Sosiego del Valor, donde reposan los caídos en los eriales. Dale esta carta y él te entregará su confianza.', },
    {'Enséñale la carta de Rabine a Layo Golpe Estelar cerca del cementerio de Sosiego del Valor en Silithus.', },
  },
  [1125] = {
    'Los espíritus de Viento del Sur',
    {'Al suroeste de aquí hay un lugar trágico, las ruinas de la Aldea del Viento del Sur. Ahí es donde deberíamos empezar a trabajar, $N.|n|nPor lo que he descubierto, antiguamente, esa aldea era una base de operaciones de los elfos de la noche en Silithus. Mucho tiempo atrás fue tomada por las colmenas de silítidos que infestan los restos. Solo puedo imaginarme el horror de la destrucción de la aldea...|n|nLos espíritus torturados de los druidas y centinelas caídos, vagan por las ruinas sin rumbo fijo. Explora el lugar y libera las almas de esos pobres seres.', },
    {'Libera los espíritus de 8 druidas torturados y 8 centinelas torturados en la Aldea del Viento del Sur. A continuación, reúnete con Layo Golpe Estelar en el cementerio de Sosiego del Valor en Silithus.', },
  },
  [1126] = {
    'Una colmena en la torre',
    {'Hay que buscar las colmenas en la Aldea del Viento del Sur y creo que sé la forma de atacarlas. Según mi experiencia, las colmenas de silítidos son muy sensibles a su entorno. Esto explica que ataquen al oír los lamentos de los espíritus.|n|nLa presencia más fuerte de silítidos está en la torre, la que tiene una masa de avispas volando alrededor. Escala la torre y consigue que la colmena se agite. Vuelve a informarme sobre tus descubrimientos, ¡pero ten cuidado! Si descubres algo que pueda ayudar, tráemelo.', },
    {'Sube a la torre de la Aldea del Viento del Sur y encuentra la forma de agitar la colmena de silítidos para que entre en actividad. Recoge cualquier cosa extraña que encuentres y llévasela a Layo Golpe Estelar en el cementerio de Sosiego del Valor en Silithus.', },
  },
  [1127] = {
    'Cerveza de tontos',
    {'¿Así que quieres un poco de cerveza de tontos, eh? Seguro que estás pensando en volver a las carreras...|n|nEstá bien, tráeme más mezclas de Zanzil y yo te prepararé más cerveza de esa.', },
    {'Llévale 12 mezclas de Zanzil a Loquillo Pinchabujas, que está en Bahía del Botín.', },
  },
  [1128] = {
    '<NYI>El equipo técnico gnomo está sediento',
    nil,
    nil,
  },
  [1129] = {
    '<NYI>El equipo técnico goblin está sediento',
    nil,
    nil,
  },
  [1130] = {
    'Melor manda saludos',
    {'$N, Melor Pezuña Pétrea ha oído hablar de tus hazañas y ha trazado un camino para ti.|n|nSi deseas seguirlo, ve a Cima del Trueno y habla con Melor. Lo encontrarás en el Alto de los Cazadores.', },
    {'Habla con Melor Pezuña Pétrea en Cima del Trueno.', },
  },
  [1131] = {
    'Metaleador',
    {'A veces se caza para conseguir alimento, otras por honor e incluso se puede cazar para aprender las lecciones que enseña la Madre Tierra.|n|nPero la caza que yo te encargo no pertenece a ninguno de estos tipos. Se trata de matar a una criatura que no cuenta con la bendición de la Madre Tierra.|n|nLa hiena Metaleador vaga por Las Mil Agujas, al sur de Los Baldíos. Es un tirano que intenta atraer a otras hienas y que infunde miedo a otras criaturas más pacíficas, provocando un derramamiento de sangre.|n|nEncuentra a Metaleador, $N. Encuéntralo y derrótalo.', },
    {'Llévale la costilla de Metaleador a Melor Pezuña Pétrea, que está en Cima del Trueno.', },
  },
  [1132] = {
    'Fiora Orejona',
    {'¡Ay, estar de nuevo al lado del mar! Sentir la caricia del viento y dejar que las olas me mezan como hacía mi querida madre hace tiempo...|n|n¡Ay! Ojalá estuviera en tu lugar, $C, pues veo el mar en tu futuro.|n|nMi trabajo es hablarles a las almas ambiciosas de la tierra de Kalimdor, ¡la tierra de las oportunidades! Si deseas probar suerte en el mar, coge un barco y dirígete al maravilloso puerto de Auberdine. Allí habla con mi socia, la elfa Fiora Orejona.|n|n¡Ella te ayudará a comenzar tu aventura por Kalimdor!', },
    {'Habla con Fiora Orejona en los muelles de Auberdine, en Costa Oscura.', },
  },
  [1133] = {
    'Viaje a Astranaar',
    {'$N, ve a Astranaar. Seguro que un miembro de la Alianza entusiasta como tú podrá hacer mucho bien allí. Habla con Shindrell Fuegoveloz y ofrécele tus servicios.|n|nPero no le digas quién te envía pues Shindrell no me conoce...', },
    {'Habla con Shindrell Fuegoveloz en Astranaar.', },
  },
  [1134] = {
    'Alaorgullo del Espolón',
    {'No tenemos la guerra declarada a la Horda, pero nuestra paz es frágil. A menudo encontramos a sus agentes actuando en nuestra contra, pero lo hacen encubiertamente.|n|nNos enteramos de uno de esos avances mediante unas fuentes ocultas en Theramore, decían que los orcos recogen veneno de las alaorgullo, cerca del Lago Mirkfallon en Sierra Espolón, hacia el sur. Los asesinos orcos utilizan el veneno en sus asaltos secretos contra la Alianza.|n|nSi esto es cierto, debemos detenerlos, $N. Tenemos que impedir que accedan a su fuente de veneno.', },
    {'Lleva 12 sacos de veneno de alaorgullo a Shindrell Fuegoveloz en Astranaar.', },
  },
  [1135] = {
    'Glándulas de veneno de Nido Alto',
    {'Como ya sabrás, los orcos suelen domar a dracoleones para utilizarlos como montura. Lo que quizás no sepas es que el veneno de un dracoleón es, en algunos círculos, mucho más valioso que la propia bestia. Así que si no te da miedo ir a la caza del dracoleón, entonces... tengo un trabajo para ti.|n|nHay un lugar llamado Nido Alto en la tierra de Las Mil Agujas, al oeste de aquí. Los dracoleones de Nido Alto tienen un potente veneno. Potente y muy valioso...', },
    {'Llévale 10 glándulas de veneno de Nido Alto a Fiora Orejona, que está en Theramore.', },
  },
  [1136] = {
    '[DEPRECATED]Faucehielo',
    {'$N, ha llegado la hora de que viajes a lejanas tierras. Estás $Gpreparado:preparada;.|n|nAhora vas a cazar a Faucehielo, un yeti de las Montañas de Alterac. Es escurridizo, su inmaculado pelaje se confunde con la nieve de la montaña en la que mora. Rara vez se deja ver.|n|nPero te enseñaré a engatusar a una criatura como él. Aquí tienes, toma este pergamino. En él explico cómo atraer a Faucehielo.|n|nAhora vete, $N. Tu viaje es largo y te aguardan innumerables desafíos. Solo cuando vuelvas con la crin de Faucehielo habrás completado tu tarea.', },
    {'Lleva la crin de Faucehielo a Melor Pezuña Pétrea en Cima del Trueno.', },
  },
  [1137] = {
    'Noticias para Fizzle',
    {'¡El indurio tiene una extraordinaria resistencia al calor! Seguro que será perfecto para los pistones de Fizzle. Pero necesitará indurio de verdad, no tan solo unas láminas.|n|nPara poder acceder a él, habrá que extraerlo de las mismísimas profundidades de Uldaman, en el extremo norte de las Tierras Inhóspitas. Esa es la auténtica fuente del indurio.|n|nMándale recuerdos a Fizzle Pernolatón de mi parte y dile lo que te he contado.|n|nBuen viaje, $N. No me sorprendería que volviéramos a vernos pues cuando Fizzle compruebe las propiedades del indurio, es probable que te envíe a Uldaman a por él.', },
    {'Habla con Fizzle Pernolatón en El Desierto de Sal, en Las Mil Agujas.', },
  },
  [1138] = {
    'Rico marisco',
    {'Adoro los cangrejos. ¡Los cangrejos son el fruto del mar! Puedes asarlos, hervirlos, guisarlos, hacerlos a la plancha... Se hacen en sartén, en olla, en hogueras... Y también hay ensalada de cangrejo, sopa de cangrejo, guiso de cangrejo, cangrejo a la pimienta, cangrejo al limón y cangrejo-sorpresa de Forjaz. Creo que no me dejo nada.|n|nPero ahora estoy pescando. No voy a conseguir ningún cangrejo. Se pueden conseguir de reptadores de arrecife y de reptadores de marea escamados. Y se pueden hacer mil cosas con ellos. Puedes asarlos, hervirlos, guisarlos, hacerlos a la plancha...', },
    {'Reúne 6 trozos de cangrejo de gran calidad para Gubber Blump de Auberdine.', },
  },
  [1139] = {
    'Las tablillas perdidas de Voluntad',
    {'Hemos conseguido frenar al clan Forjatiniebla al aislarlos de la Cumbre de Roca Negra pero aún no hemos completado la misión de Piemartillo. Su muerte no debe ser en vano. Soñaba con encontrar la tablilla de Voluntad: un fragmento de piedra grabado con magia de los mismísimos titanes para ayudar a imbuir de vida a sus creaciones dándoles voluntad propia, o al menos eso cuenta la leyenda.|n|nDebemos recuperar la tablilla antes de que lo haga el clan Forjatiniebla.|n|nRegresa a Uldaman, encuentra la tablilla y vuelve aquí inmediatamente.', },
    {'Encuentra la tablilla de Voluntad y llévasela al consejero Belgrum en Forjaz.', },
  },
  [1140] = {
    'La Torre de Althalaxx',
    {'La letra de los orcos es un poco mejor que los garabatos de un niño. Muchos de los de mi orden se burlaron cuando decidí aprender su lengua pero me ha resultado de provecho tener un conocimiento más profundo de mis enemigos.|n|nPor los garabatos de Ilkrud, parece que Athrikus aún posee dos gemas de almas que se guardan en la Senda de la Noche y en Satyrnaar, áreas bajo el dominio de los sátiros al noreste de Vallefresno.|n|nVe con cuidado, $N, los templos de los sátiros bañados en sangre pueden ser perturbadores hasta para $Gun:una; $C $Gcurtido:curtida; como tú.', },
    {'Libera las almas de los Altonato atrapadas en la Senda de la Noche y en Satyrnaar y vuelve junto a Delgren el Purificador en la Atalaya de Maestra.', },
  },
  [1141] = {
    'La familia y la caña de pescar',
    {'Me encanta pescar. Los Blump somos una famosa familia de pescadores. Yo soy Gubber Blump. Yo también pesco.|n|nEn esta zona hay un pez que me gusta pescar: el mero de Costa Oscura. Yo solía salir en un barco a pescar meros, pero desde que aparecieron los múrlocs, ya no sale ningún barco. Además, seguro que los múrlocs se han comido todos los meros.|n|nOye, ¿quieres ayudarme a pescar un mero de Costa Oscura? Si lo haces, ¡te daré una auténtica caña de pescar de la familia Blump! Es una caña estupenda para pescar.', },
    {'Pesca 6 meros de Costa Oscura para Gubber Blump de Auberdine.', },
  },
  [1142] = {
    'Decaída mortal',
    {'No voy a durar mucho... Estoy débil.|n|nEl valiente enano Cimahuraña ha ido a advertir a Falfindel...|n|nAntes de morir, quisiera...|n|nSe han llevado el colgante de vínculo de mi esposa, Treshala...|n|nEncuéntralo, por favor... Llévaselo a Treshala a Darnassus...|n|nY dile que he... muerto.', },
    {'Encuentra el colgante de Treshala Arroyobarbecho y llévaselo a Darnassus.', },
  },
  [1143] = {
    'La Torre de Althalaxx',
    {'Entiendo. Bien, si lo que dices es cierto, es el momento de actuar. Creo que Athrikus reside en la parte superior de la torre. Pero ten cuidado, está protegido por muchos brujos poderosos, mucho más mortíferos que los que has afrontado hasta ahora.', },
    {'Mata a Athrikus Narassin y lleva su cabeza a Balthule Golpesombra que está cerca de La torre de Althalaxx.', },
  },
  [1144] = {
    'Willix el Importador',
    {'¡Por fin llega ayuda!|n|nNo sabes cuánto hace que me tienen aquí prisionero. Ya ni recuerdo la última vez que estuve fuera.|n|nVerás, es que soy empresario, siempre ando olfateando negocios. Oí decir que Mebok Mizzyrix pagaba bien el tubérculo hojazul para su porqueriza, y me pareció un negocio redondo y fácil. Como puedes ver, ¡calculé mal!|n|nPero si me ayudas a salir de aquí, te recompensaré.', },
    {'Escolta a Willix el Importador hasta la salida de Horado Rajacieno.', },
  },
  [1145] = {
    'El enjambre crece',
    {'Muchos viajeros que han pasado por El Cruce me han ayudado a recoger huevos de la Tierra de Gigantes y muchos de ellos podrán contarte historias de lo peligrosas que son esas bestias. Yo ya he oído las suficientes como para poder afirmar que esos insectos representan una amenaza mayor de lo que mis maestros pensaban.|n|nNecesito enviar a un mensajero a Orgrimmar, a ver a Belgrom Destrozarroca. No se trata de un asunto cualquiera por eso necesito que vaya alguien que se tome esta tarea en serio.|n|nBelgrom suele andar por las inmediaciones de la Casa de la Hermandad de Guerreros.', },
    {'Entrégale la nota lacrada de Korran a Belgrom Destrozarroca en Orgrimmar.', },
  },
  [1146] = {
    'El enjambre crece',
    {'Por lo que veo, Korran ha llegado a la misma conclusión que yo acerca de esos insectos... parece que representan una amenaza mayor de lo que yo pensaba.|n|nHace unos días, un cazador regresó agonizante de Las Mil Agujas. Formaba parte de un destacamento de asalto enviado a El Desierto de Sal para expulsar de allí a un equipo de excavación formado por enanos. Durante el ataque, empezaron a salir insectos de una cueva que formaba parte de la excavación y casi acaban con todo el destacamento.|n|nEstaban liderados por Moktar Krin y se han refugiado en la frontera de El Desierto de Sal. Llévale esta nota.', },
    {'Entrégale la nota lacrada de Belgrom a Moktar Krin en Las Mil Agujas.', },
  },
  [1147] = {
    'El enjambre crece',
    {'¡Vaya! Parece que Belgrom piensa que esos monstruos representan una amenaza y quiere que sean devueltos al lugar al que pertenecen.|n|nSupongo que haber matado a los enanos enviados por la Liga de Expedicionarios no ha sido suficiente y ahora tengo que enviar a un destacamento de guerra exhausto a otra batalla. No lo conseguiremos... no en estas condiciones. La excavación se encuentra al sur de aquí, y ya no debería quedar ningún enano por allí. ¿Te sientes con ánimos de blandir una espada o un bastón y echarnos una mano?', },
    {'Mata a 5 buscadores silítidos, 5 zánganos de colmena silítidos y 5 invasores silítidos, y después ve a ver de nuevo a Moktar Krin a Las Mil Agujas.', },
  },
  [1148] = {
    'Pedazos del enjambre',
    {'Inspeccionas el caparazón detenidamente. A medida que lo giras, te das cuenta de que la coraza de quitina está entrelazada de tal forma que le confiere una resistencia increíble. No se parece a nada que hayas visto antes. Observas el resto del cuerpo y te das cuenta de que estas criaturas son muy poderosas y están muy evolucionadas.|n|nAl mirar de nuevo el caparazón, crees que a Korran le gustaría recibir más muestras de estas criaturas. Le resultarían útiles para descubrir qué son y de dónde proceden.', },
    {'Llévale 1 corazón de silítido, 5 garfas de silítido y 3 caparazones de silítido intactos a Korran, que está en El Cruce.', },
  },
  [1149] = {
    'Prueba de fe',
    {'¿Me has estado buscando o quizás ha sido el destino el que te ha traído a mí? No tiene importancia... Ahora estás aquí y tu viaje encontrará un nuevo punto de partida.|n|nSon muchas las facetas que conforman un ser, tanto su espíritu como su cuerpo y su mente. Algunas de ellas son mensurables por las tradiciones de una cultura. Otras, sin embargo, solo podemos esperar que encuentren un lugar dentro de nosotros. Si no te opones, pondré a prueba algunas de tus facetas.|n|nSi superas las pruebas, te harás más fuerte. De lo contrario, descubrirás la inmensidad de El Vacío Abisal.|n|nLa primera es una prueba de fe.', },
    {'Si tienes fe, salta desde las tablas que dominan Las Mil Agujas.', },
  },
  [1150] = {
    'Prueba de resistencia',
    {'Me complace comprobar que tu valor permanece inquebrantable después de lo que acabas de hacer. Dado que tu fe está intacta, ha llegado el momento de poner a prueba tu cuerpo.|n|nEn primer lugar, harás una prueba de resistencia. Ve a Guarida Malapluma al oeste del Poblado Viento Libre. Consigue llegar hasta las profundidades de su guarida y destruye sus alimentos. Con eso provocarás su ira. Si eres capaz de aguantar con vida el tiempo suficiente, la propia Grenka Aullasangre irá a por ti. Acaba con ella y tráeme su garra para superar tu prueba.', },
    {'Llévale la garra de Grenka a Dorn Acechallanos, que está en Las Mil Agujas.', },
  },
  [1151] = {
    'Prueba de fuerza',
    {'En los tiempos de los dioses antiguos, los elementales ocupaban la mayor parte de este mundo. Ellos veneraban a los dioses antiguos y estos, haciendo uso de su poder, relegaron a los elementales a este mundo. Cuando los dioses antiguos desaparecieron, los elementales se desvanecieron de nuestro mundo y ahora solamente regresan cuando los poderosos magos requieren su presencia.|n|nAun así, hay algunas excepciones. Algunos elementales eran más poderosos y consiguieron permanecer aquí por su cuenta. Uno de ellos es Rok\'Alim.|n|nPara poner a prueba tu fuerza, encuentra a Rok\'Alim en Las Mil Agujas y acaba con él.', },
    {'Llévale fragmentos de Rok\'Alim a Dorn Acechallanos, que está en Las Mil Agujas.', },
  },
  [1152] = {
    'Prueba de conocimiento',
    {'Tu tiempo conmigo está llegando a su fin. Tengo una amplia cultura mas la prueba de conocimiento no seré yo quien te la haga. Hay lecciones que aprender y lugares que visitar que corresponden a otros.|n|nSi estás $Gpreparado:preparada;, busca a Braug Espíritu Tenue, un chamán muy sabio. Él continuará poniéndote a prueba, así que sigue sus indicaciones, $N.|n|nCuando lo desees, busca el túnel que comunica Sierra Espolón con Vallefresno pues Braug anda por esa zona. Y ten cuidado, $N, a los elfos de la noche les encantaría impedir que acabaras tus pruebas.', },
    {'Encuentra a Braug Espíritu Tenue cerca de la entrada de El Paso del Espolón en Sierra Espolón.', },
  },
  [1153] = {
    'Una nueva muestra de mineral',
    {'$C, me has ayudado con eficacia en el pasado. El Jefe de Guerra está satisfecho con mis logros y quiere que continúe con renovada determinación. Según me dicta mi honor, informaré al Jefe de Guerra de tu valía para que te otorgue el reconocimiento que te mereces. Pero antes he de pedirte que me ayudes otra vez.|n|nRecientemente han llegado unos viajeros del sur, de un lugar llamado Las Mil Agujas. Estos afirman que allí mataron a un kóbold que tenía una muestra de un extraño mineral, pero no están dispuestos a vendérmelo. Quiero una muestra de ese mineral para analizarlo.', },
    {'Arrebátale una muestra bruta de mena a un cavador o a un perito Gravamorro y llévasela a Jironack Forjacero al Campamento Taurajo de Los Baldíos.', },
  },
  [1154] = {
    'Prueba de conocimiento',
    {'Has superado con éxito las pruebas de Dorn y sé que quieres hacer lo mismo con la siguiente. Muy bien, pero ten en cuenta que hasta el momento las pruebas han sido demasiado sencillas. Es fácil poner a prueba el cuerpo... pero la mente es un tema aparte.|n|nTe lo explicaré bien para que lo entiendas: encuentra el libro que yo te diga, estúdiatelo bien y responde la pregunta que te haga acerca de su contenido.|n|nQué libro, te estarás preguntando... El Legado de los Aspectos. Lo encontrarás en la parte baja de Dor\'danil, en el sur de Vallefresno, bajo la protección de los druidas muertos y sus asesinos.', },
    {'Encuentra el Legado de los Aspectos y devuélveselo a Braug Espíritu Tenue que se encuentra cerca de la entrada de El Paso del Espolón en Sierra Espolón.', },
  },
  [1155] = {
    '<NYI> <TXT> misión alterna del bicho de cristal',
    nil,
    nil,
  },
  [1156] = {
    '<NYI> <TXT> habla con el alquimista pestlezugg',
    nil,
    nil,
  },
  [1157] = {
    '<NYI> <TXT> Morterozugg necesita objetos',
    nil,
    nil,
  },
  [1158] = {
    '<NYI> <TXT> Habla con Rabine Saturna',
    nil,
    nil,
  },
  [1159] = {
    'Prueba de conocimiento',
    {'Bien hecho, $N. Has superado la primera parte de la prueba de conocimiento pero aún hay otra pregunta que debes responder. Sin embargo, no seré yo quien te la haga.|n|nBusca a Parqual Fintallas en Entrañas de Lordaeron. Él era un gran historiador al servicio de los humanos antes de que la Plaga lo sorprendiera. Ahora sigue persiguiendo el conocimiento, pero de un modo distinto.|n|nAntes de formularte ninguna pregunta, te asignará otro encargo. Lo has hecho tan bien hasta el momento que no tengo ninguna duda de que superarás este obstáculo sin problemas.', },
    {'Encuentra a Parqual Fintallas en Entrañas.', },
  },
  [1160] = {
    'Prueba de conocimiento',
    {'Te diré lo que tienes que buscar, e incluso te formularé mi pregunta, pero no porque desees ponerte a prueba. El conocimiento va más allá de la fuerza física. Aunque otros puedan superarte en habilidad, el conocimiento del mundo te dará ventaja.|n|nDirígete al monasterio que está al norte de los Claros de Tirisfal. En la biblioteca que encontrarás allí, verás un libro titulado Comienzos de la amenaza de los no-muertos. Lo utilizaban los ahora corruptos paladines de allí para instruir a los no-muertos para luchar contra los de mi especie.|n|nTráemelo.', },
    {'Encuentra el libro Comienzos de la amenaza de los no-muertos y devuélveselo a Parqual Fintallas, que está en Entrañas.', },
  },
  [1161] = {
    '<NYI> <TXT> sombra chismosa de Lunámbar',
    nil,
    nil,
  },
  [1162] = {
    '<NYI> <TXT> Habla con Hamuul Tótem de runa',
    nil,
    nil,
  },
  [1163] = {
    '<NYI> <TXT> habla con Tyrande susurravientos',
    nil,
    nil,
  },
  [1164] = {
    'Robar a un ladrón...',
    {'¡Desgraciada! ¡Canalla! Kenata sigue viva, y su familia está sana y sigue prosperando mientras yo sufro. ¡Renegados tenían que ser!|n|nMi familia ha muerto debido a la peste. Arruinaron nuestra finca durante la guerra, la saquearon y le plantaron fuego. Y después de todo esto, ella y sus despreciables hijos tuvieron el descaro de robar las únicas posesiones de valor que me quedaban.|n|nYa no me preocupa lo que me fue robado. ¡Lo que quiero ahora son sus cabezas!|n|n¡Mátalos por mí! Ve a la Granja de los Dabyrie en Arathi, al noreste del Refugio de la Zaga.', },
    {'Llévale las cabezas de Kenata, Fardel y Marcel Dabyrie a Genavie Callow, que está en Entrañas.', },
  },
  [1165] = {
    '<NYI> Mineral para las carreras',
    nil,
    nil,
  },
  [1166] = {
    '[DEPRECATED]Las pertenencias del señor supremo Mok\'Morokk',
    {'¡Inclínate ante señor supremo Mok\'Morokk!|n|n¡Rexxar hacerme líder poderoso del clan Quebrantarrocas!|n|nYo buen jefe. Yo cuidar del clan.|n|nGrandes dragones vienen y hacen fuego en otra casa. Pero yo soy un ogro listo. Encontré nueva casa para el clan.|n|nClaro que dejamos casa vieja tan rápido que yo olvidé cosas. $GPequeño:Pequeña:r; $R, ve a por mis cosas. Ir al sur y encontrar mi rico grog, mi barril de tabaco y mi caja fuerte. Si haces eso, me caerás bien. Busca en Cubil de la Llama y en Ruinas Quebrantarrocas... Estar ahí, ¡yo seguro!', },
    {'El señor supremo Mok\'Morokk del Poblado Murohelecho quiere que recuperes su grog, su barril de tabaco y su caja fuerte del Pantano Revolcafango.', },
  },
  [1167] = {
    'La Torre de Althalaxx',
    {'Antes de enfrentarte a Athrikus, probablemente sería prudente que consultaras a Balthule. No me cabe la menor duda de que habrá estado muy atento en su observatorio de la torre y podría tener información sobre los últimos movimientos.', },
    {'Habla con Balthule Golpesombra cerca de La Torre de Althalaxx.', },
  },
  [1168] = {
    'El ejército de los dragones Negros',
    {'Mok\'Morokk fue nombrado señor supremo por Rexxar. Le preocupa más el poder que los ogros.|n|nLos dragones Negros matan a muchos ogros. Matan a la mujer de Tharg. Mok\'Morokk nos dice que huir. Nos hace venir aquí.|n|nLos ogros deben luchar. Los ogros no huir. No buenos corredores. Mok\'Morokk solo preocupa de Mok\'Morokk.|n|nYo llamo casa a las Ruinas Quebrantarrocas. A mí gustar el sur. Este lugar no casa.|n|nAyuda ogros combatir ejército de los dragones Negros. Quiero venganza. Quiero ir a casa.', },
    {'Tharg en el Poblado Murohelecho quiere que mates a 10 exploradores Pirocabello, 10 ceniazotes Pirocabello y 5 horrocrustos Pirocabello.', },
  },
  [1169] = {
    '[DEPRECATED]Identifica a los cachorros',
    {'Mientras ese loco cobarde de Mok\'Morokk se revuelca en poder y Tharg lucha contra los demonios de su pena y su venganza y compite por el liderazgo del clan, solo yo me preocupo de identificar la fuente de la agresión a nuestro antiguo hogar.|n|n¿Por qué me miras así, $N? ¿Esperabas que hablara como un burdo pueblerino solo porque soy un ogro?|n|nEn fin, volvamos a nuestros asuntos. Tráeme los corazones y las lenguas de los cachorros y las crías. Yo buscaré la raíz de este mal...', },
    {'Draz\'Zilb del Poblado Murohelecho quiere que le lleves 7 lenguas abrasadoras y 7 corazones abrasadores.', },
  },
  [1170] = {
    '[DEPRECATED]El linaje de Onyxia',
    {'El Poblado Quebrantarrocas fue invadido por el linaje de Onyxia. Pero, ¿por qué arrasaría nuestras tierras la hija de Alamuerte, el Señor de los dragones Negros?|n|nEs preocupante... Porque es evidente que Onyxia no vino aquí solo para asediar a un pequeño grupo de ogros.|n|n¡Informa a Mok\'Morokk de inmediato! Debemos actuar.', },
    {'Habla con el señor supremo Mok\'Morokk en el Poblado Murohelecho.', },
  },
  [1171] = {
    '[DEPRECATED]El linaje de Onyxia',
    {'No me molestes. Ve a decir a Draz\'Zilb que nos quedamos aquí. Aquí no hay dragones Negros.', },
    {'Ve al Poblado Murohelecho y habla con Draz\'Zilb.', },
  },
  [1172] = {
    '[DEPRECATED]El linaje de Onyxia',
    {'El linaje de Onyxia ha sido dispersado por todo El Pantano del Dragón. Es vital que impidamos que incube más crías.|n|nCorre hacia la Ciénaga de Fuego, al sur del Marjal Revolcafango. Seguro que ha establecido allí su guarida. Busca los huevos de ese ser maligno y destrúyelos.|n|nJamás reclamaremos el poblado Quebrantarrocas si los alrededores son un semillero de crías de dragón.|n|nY respecto a Mok\'Morokk... Tengo otros planes para ese demonio.', },
    {'Draz\'Zilb, del Poblado Murohelecho, quiere que destruyas 5 huevos de Onyxia.', },
  },
  [1173] = {
    '[DEPRECATED]Desafiar al señor supremo Mok\'Morokk',
    {'¿Osas desafiar al señor supremo Mok\'Morokk?|n|n¡Ja!|n|n¡Yo aplastar insignificante $R!|n|nDime cuándo estar $Glisto:lista; para la paliza.', },
    {'Derrota a Mok\'Morokk y ve al Poblado Murohelecho a informar a Draz\'Zilb.', },
  },
  [1174] = {
    '¡Los gnomos ganan!',
    nil,
    nil,
  },
  [1175] = {
    'Un bache en la carretera',
    {'Tras el choque del Trueno Rojo de los goblins con un basilisco, Kronkpiloto me contrató para que me ocupe de la pista. Yo no sé lo que comerán esos animales en el desierto para crecer tanto pero tenemos que encargarnos de ellos si no queremos que deambulen por la pista durante la celebración de una carrera.|n|nTe diré lo que vamos a hacer. Si quieres ir ahí fuera y hacer algo de provecho, sal y acaba con los basiliscos que encuentres por la zona.', },
    {'El maestro rastreador Zherin quiere que mates a 10 basiliscos Piedra de sal, 10 vitropieles Piedra de sal y 6 observadores Piedra de sal en El Desierto de Sal.', },
  },
  [1176] = {
    'Menos peso',
    {'¡Cuando se trata de correr, todo cuenta! Ya sea un pequeño ajuste en la salida de potencia, que se afloja la bobina de tensión o que se aligera el peso del cuadro. ¡Hay que tener todo en cuenta!|n|nUtilizamos huesos de buitre para la mayor parte de los pequeños cambios que hacemos en la estructura de los coches, por su perfecto equilibrio entre resistencia y peso. Y lo mejor de todo es que son muy fáciles de encontrar pues en el Desierto de Sal hay muchos buitres.|n|nTráeme algunos y te pagaré bien por ellos.', },
    {'Consigue 10 huesos huecos de buitre para Pozzik en El Desierto de Sal.', },
  },
  [1177] = {
    '¡Qué hambre!',
    {'Fango ogro grande.|n|nYo tiene hambre.|n|nTú buscar peces. Trae comida a Fango.|n|nTú das de comer a Fango o Fango te come a ti.', },
    {'Fangolpe Piesucio del norte de Revolcafango quiere 8 cabezas de Ancalodo.', },
  },
  [1178] = {
    'Patrocinio goblin',
    {'Nuestro equipo de carreras es el orgullo de todos los goblins. Te sorprendería saber quiénes contribuyen de un modo u otro en esto.|n|n¿Conoces a Gazlowe? Él nos busca piezas por todo el mundo. ¡Incluso en una ocasión vino aquí para arreglar uno de estos trastos!|n|nHace unas cuantas semanas, dijo que nos enviaría un prototipo de un nuevo regulador de combustible pero todavía no nos ha llegado. Y él suele ser muy rápido... ¿Te importaría ir a Trinquete y preguntarle por el regulador? ¡No me gusta meter prisa pero los gnomos nos están ganando!', },
    {'Habla con Gazlowe en Trinquete, en Los Baldíos.', },
  },
  [1179] = {
    'Los hermanos Pernolatón',
    {'¿Has oído hablar del Desierto de Sal? Es una franja de tierra salada y llana de Kalimdor, al sur del cañón de Las Mil Agujas. ¡Es un lugar ideal para echar una carrera ya que es totalmente llano!|n|nUn par de hermanos gnomos amigos míos están allí probando su nuevo coche cohete y, por lo que tengo entendido, ¡es una bala! Eh, es tan rápido que los pilotos se estrellan continuamente y sufren conmociones.|n|nPor eso me han pedido algunos cascos de máquinas de asedio pero tengo cosas que hacer aquí, ¡y no puedo ir!|n|n¿Podrías ir tú?', },
    {'Llévale el cajón de cascos de choque a Wizzle Pernolatón, que está en el Circuito del Espejismo en Las Mil Agujas.', },
  },
  [1180] = {
    'Patrocinio goblin',
    {'Has vuelto por lo que habías venido a buscar. Sé que le prometí a Pozzik que le entregaría un nuevo regulador de combustible pero aún no lo he recibido. Revilgaz de Bahía del Botín dijo que lo había enviado pero se debe de haber perdido por algún lado.|n|nSi es cierto, no hay mucho que podamos hacer. Al menos podemos averiguar si salió realmente de Bahía del Botín.|n|nVe para allá y compruébalo con el jefe de embarcadero Lozgil. Podrá comprobarlo en los registros de cargamentos.', },
    {'Habla con el jefe de embarcadero Lozgil en Bahía del Botín.', },
  },
  [1181] = {
    'Patrocinio goblin',
    {'Me temo que no puedo ayudarte más, $N. Si quieres seguir investigando, te sugiero que vayas a ver al Barón. Si alguien sabe lo que está haciendo Revilgaz, es Revilgaz.|n|nLe encontrarás en la taberna al otro lado del puerto, en el piso de arriba.', },
    {'Habla con el Barón Revilgaz en la Bahía del Botín.', },
  },
  [1182] = {
    'Patrocinio goblin',
    {'Verás, las trituradoras de Ventura y Cía. del Lago Nazferiti (en el Norte de la Vega de Tuercespina) están equipadas con un nuevo modelo de regulador de combustible. Creo que Pozzik podría sacar ventaja de eso si pudiera conseguir algunos detalles. Por desgracia, Cozzle, el supervisor que está ahí fuera, parece más inteligente de lo que yo había pensado.|n|nQuizás tú tengas más suerte para encontrar los planos. Sé que los guarda en su casa, pero seguro que los tiene bajo llave.', },
    {'Lleva los planos de regulador de combustible al Barón Revilgaz en la Bahía del Botín.', },
  },
  [1183] = {
    'Patrocinio goblin',
    {'Creo que ya estás $Glisto:lista; para irte. Da recuerdos a Pozzik de mi parte y dile que, si alguna vez necesita algo, no dude en pedírmelo. ¡Estaré esperando la noticia de que ha conseguido batir el récord!', },
    {'Entrega los planos de regulador de combustible a Pozzik en El Desierto de Sal.', },
  },
  [1184] = {
    'Pedazos del enjambre',
    {'Ve a ver a Belgrom a Orgrimmar y dile que Moktar está cumpliendo con su cometido en Las Mil Agujas. Dile también que yo he progresado en mis investigaciones y que espero saber más cosas pronto. Seguro que se alegra de saberlo.', },
    {'Ve a ver de nuevo a Belgrom Destrozarroca a Orgrimmar.', },
  },
  [1185] = {
    'Debajo de la quitina había...',
    nil,
    nil,
  },
  [1186] = {
    'El piloto nº18',
    {'Yo estaré muy ocupado intentando integrar el nuevo regulador de combustible con los diseños de nuestros coches pero si quieres seguir prestando tu ayuda al equipo, habla con Razzeric. Él es nuestro piloto, bueno... nuestro decimoctavo piloto para ser exactos, y disfruta realizando sus pequeñas modificaciones en los coches.|n|nEstá un poco chalado así que ten cuidado con lo que haces.', },
    {'Habla con Razzeric en El Desierto de Sal, en Las Mil Agujas.', },
  },
  [1187] = {
    'Los ajustes de Razzeric',
    {'Pozzik es un gran mecánico, lo sé, pero tiene miedo de aumentar la potencia y lanzarse a la carrera. Yo no, sin embargo.|n|nCuando Pozzik acaba con un coche, yo me tomo un tiempo para realizar mis propios ajustes... ya sabes, aflojo los mandos, quito algunas piezas del cuadro y le pongo más combustible.|n|nLe encargué un propulsor de seforio a Shreev para que me lo enviara desde la Cacharrería de Gadgetzan pero parece que el zepelín en el que venía se estrelló en Marjal Revolcafango. ¡Lo necesito, $N!', },
    {'Consigue el propulsor de seforio para Razzeric, en El Desierto de Sal.', },
  },
  [1188] = {
    'La seguridad primero',
    {'Pero espera, ¿qué es esto? Shreev dejó el seguro puesto y eso limitará la potencia del propulsor. ¡Le dije que se lo quitara! Esto no me gusta.|n|nTienes que llevar esto a la Cacharrería de Gadgetzan en el Desierto de Tanaris y decirle a Shreev que se lo quite.', },
    {'Llévale el propulsor de seforio a Shreev, que está en Gadgetzan en Tanaris.', },
  },
  [1189] = {
    'La seguridad primero',
    {'Aquí tienes, he hecho lo que Razzeric me pidió. Dile que tenga cuidado al activarlo. Si comete el más mínimo error, podría saltar por los aires.|n|nY sería una auténtica pena... ¿Quién sabe cómo sería el decimonoveno piloto?', },
    {'Devuélvele el propulsor de seforio modificado a Razzeric, que está en El Desierto de Sal en Las Mil Agujas.', },
  },
  [1190] = {
    'Mantener la velocidad',
    {'Los hermanos Pernolatón han descubierto un nuevo material de construcción, es la única explicación posible. Sus coches cada vez son más rápidos pero sus diseños y todos los datos que reunimos durante sus carreras son los de siempre.|n|nLo que sí sabemos es que Rizzle Pernolatón tiene unos diseños de ese nuevo descubrimiento.|n|nMientras Zamek los entretiene, tú roba los diseños.', },
    {'Consigue que Zamek haga una artimaña de distracción y roba los diseños de Rizzle para Pozzik en El Desierto de Sal, en Las Mil Agujas.', },
  },
  [1191] = {
    'La distracción de Zamek',
    nil,
    nil,
  },
  [1192] = {
    'Mena de indurio',
    nil,
    nil,
  },
  [1193] = {
    'Una trampa rota',
    nil,
    nil,
  },
  [1194] = {
    'Los esquemas de Rizzle',
    {'Los esquemas de Rizzle describen el proceso de refinado del indurio. En sus garabatos queda claro que el indurio se obtiene de la excavación dirigida por los enanos en Uldaman, en las Tierras Inhóspitas.|n|nEl resto de notas hablan de la resistencia al calor.|n|nEncima de los diseños, a modo de pisapapeles, hay lo que aparenta ser indurio no refinado.', },
    {'Llévale la muestra de mena de indurio a Pozzik, que está en El Desierto de Sal en Las Mil Agujas.', },
  },
  [1195] = {
    'La llama sacra',
    {'Los centauros Galak de Las Mil Agujas custodian un artefacto desde el comienzo de sus tiempos.|n|nNos gustaría arrebatárselo pero para ello necesitamos una ampolla de agua de una de las Pozas de la Luna de los elfos de la noche.|n|nPara conseguir el agua, primero tendrás que hacerte con una de las ampollas que portan los dríades cerca del Refugio de la Algaba en el corazón del Bosque de Vallefresno. Hay una Poza de la Luna cerca de la orilla occidental del Río Falfarren, al sur de la carretera principal, donde podrás llenar la ampolla de agua.', },
    {'Llévale una ampolla con grabados llena a Zangen Pezuña Pétrea, que está en Cima del Trueno.', },
  },
  [1196] = {
    'La llama sacra',
    {'Llévale la ampolla con agua a Rau Abiscorredor en el Poblado Viento Libre en la zona sudeste de Las Mil Agujas. Podrás llegar a Las Mil Agujas cogiendo El Gran Elevador que encontrarás en el extremo sur de Los Baldíos.|n|nNo me sorprendería que pudieras seguir ayudándonos.', },
    {'Entrégale la ampolla con grabados llena a Rau Abiscorredor del Poblado Viento Libre.', },
  },
  [1197] = {
    'La llama sacra',
    {'Con el agua que has traído podrás apagar temporalmente la llama que protege la reliquia de los centauros. Sin embargo, su efecto no es permanente por lo que tendrás que darte prisa.|n|nEncontrarás el Risco Pezuña Quebrada, el fuerte de los centauros, en dirección norte. La llama se encuentra en el Campamento Pezuña Quebrada, un lugar fuertemente custodiado del risco.|n|nTen cuidado pues los centauros Galak tienen a muchos hombres allí y no dejarán que les arrebates algo tan preciado para ellos con facilidad.', },
    {'Consigue la pezuña hendida para Rau Abiscorredor del Poblado Viento Libre.', },
  },
  [1198] = {
    'Buscando a Thaelrid',
    {'Estos últimos días circulan muchos rumores sobre la reunión del Martillo Crepuscular y los nagas en las Cavernas de Brazanegra al oeste.|n|nEstoy aquí para reunir toda la información que pueda para que sepamos dónde y cuándo necesitaremos ayuda.|n|nHace unos días envié a un explorador para observar la actividad de las Cavernas de Brazanegra... Pero el explorador Thaelrid aún no ha regresado.|n|nMis otros exploradores están ocupados con asuntos más urgentes.|n|nBusca a Thaelrid por mí, $N.', },
    {'Busca al explorador Thaelrid en las Cavernas de Brazanegra.', },
  },
  [1199] = {
    'Cascada Crepuscular',
    {'Con el poder que les confieren los ritos de los caóticos dioses antiguos, los miembros del Martillo Crepuscular trabajan para devolver a sus oscuros Señores a este mundo y así extender la muerte y el terror por él.|n|nCreemos que el Martillo Crepuscular se ha aliado con los nagas. Se están concentrando en las Cavernas de Brazanegra, al oeste.|n|nDebemos frustrar los planes que se forjan en las profundidades del viejo santuario, sean cuales sean.|n|nEnfréntate al Martillo y tráenos pruebas de tus hazañas. Tus esfuerzos serán ampliamente recompensados.', },
    {'Lleva 10 colgantes Crepusculares a la centinela Aluwyn en el Campamento Brazanegra.', },
  },
  [1200] = {
    'La vileza de Brazanegra',
    {'Las fuerzas me han abandonado. ¡Necesito tu ayuda!|n|nOtrora este lugar era un gran templo de Elune. Pero la desgracia lo ha llevado a la ruina cuando la corrupción de un dios antiguo empezó a calar desde el subsuelo y contaminó la sagrada Poza de la Luna.|n|nAku\'Mai, sirviente del dios antiguo, surgió de las aguas.|n|nLos adeptos del Martillo Crepuscular se han unido a los nagas para ocupar esas tierras. Esos adeptos, cuyo jefe es Kelris, sacrifican a inocentes a Aku\'Mai a cambio de poder.|n|nMata a Kelris y llévale su cabeza a Ashelan en el Campamento Brazanegra, $N, te lo ruego.', },
    {'Llévale la cabeza del señor crepuscular Kelris a Ashelan Bosquenorte en el Campamento Brazanegra.', },
  },
  [1201] = {
    'Los espías de Theramore',
    {'La tregua de Horda y la Alianza peligra. Ambas partes intentan dañar a la otra. Refriegas, acciones encubiertas... ¡Nuestro deber es asegurarnos de que gane la Horda!|n|nY esta es nuestra oportunidad de conseguirlo.|n|nHay infiltrados de la Alianza al este del Poblado Murohelecho. Espían el poblado e informan de nuestros movimientos a Theramore, cosa que no podemos permitir.|n|nDa caza a los infiltrados y mátalos. Envía un claro mensaje a sus superiores: ¡no toleraremos la presencia de sus espías!', },
    {'Mata a 9 infiltrados de Theramore y luego reúnete con Nazeer Picasangre en el Poblado Murohelecho.', },
  },
  [1202] = {
    'El puerto de Theramore',
    {'$N, enviamos a dos de nuestros espías a robar documentos de un navío de los puertos de Theramore. Consiguieron los papeles, pero fueron descubiertos y se vieron obligados a tirarlos al mar.|n|nUno de ellos consiguió escapar más tarde, pero no logró recuperar los documentos. Vino a mí a informar de su fracaso y ahora yo te encargo a ti la misión.|n|nLos documentos están en un baúl, en las aguas del puerto de Theramore. Encuéntralos y tráemelos aquí, $N.', },
    {'Lleva los documentos del Capitán a Nazeer Picasangre al Poblado Murohelecho.', },
  },
  [1203] = {
    'Jarl necesita una hoja',
    {'Tengo algo que cortar. No puedo decirte qué voy a cortar, pero... Necesito una hoja. Una en concreto...|n|nHay quien la llama espada. Yo prefiero llamarla hoja.|n|n¿Me ayudas? Esos hombres-pez, ya sabes, los múrlocs o como se llamen. Hay uno al que llaman Espinafilada, que lleva una gran espada y vive al norte, cerca de la playa. ¡Esa es la espada que necesito!|n|nPero no te duermas en los laureles. Lo que quiero cortar no esperará para siempre...', },
    {'Lleva la espada de Espinafilada a "Ojolodo" Jarl, en la Mansión Cienaluz.', },
  },
  [1204] = {
    'Sopa de Fangorroca con tropezones',
    {'Estoy trabajando en un plato que llamaré "sopa de Fangorroca con tropezones". Pero necesito los ingredientes principales y... bueno, no puedo ir a buscarlos al Marjal Revolcafango, ¡no creo que durara mucho allí!|n|nQuizás podrías ir tú por mí, $N. Para empezar, necesito lenguas de tortugas Fangorroca. Puedes encontrar tortugas Fangorroca en la costa, sobre todo en la bahía.|n|n¡Pero no me sirve cualquier lengua! Sé que algunas Fangorroca tienen lenguas bífidas...|n|nY se dice que las lenguas bífidas tienen un sabor especial... Quiero ese sabor en mi plato.', },
    {'Lleva 8 lenguas Fangorroca bífidas a Morgan Stern a Theramore.', },
  },
  [1205] = {
    'Lodomuerto',
    {'Lodomuerto es un anciano crocolisco del Marjal Revolcafango. Y ha llegado su hora.|n|nSus viejos huesos crujen cuando desplaza su enorme cuerpo por el pantano y aunque aún se mueve con el vigor y la velocidad de un joven, su anciano cuerpo tortura al gran espíritu que lo habita, un espíritu cuya llama no se extinguirá.|n|nSigue viviendo con constantes y enloquecedores dolores. Debes poner fin a la vida de esta noble criatura, $N. Debes dar paz a Lodomuerto.', },
    {'Lleva el Diente de Lodomuerto a Melor a Cima del Trueno.', },
  },
  [1206] = {
    'Jarl necesita ojos',
    {'El zumo de ojo es una bebida estupenda. Es una pena que la mayoría de los bichos solo tengan dos ojos.|n|nPero las arañas tienen muchos. Muchos, muchos. Y el zumo de ojo de araña Niebla Negra está muy rico. ¡Suavecito y salado! Redonditos ojos de araña... Se me hace la boca agua...|n|nLas arañas Niebla Negra están al oeste de aquí, en la Cueva Niebla Negra. Está claro que las arañas llevan el nombre de la cueva en la que viven... ¿o será al revés?', },
    {'Lleva 20 ojos de Niebla Negra sin reventar a "Ojolodo" Jarl a la Mansión Cienaluz.', },
  },
  [1218] = {
    'Ancas de rana de marisma',
    {'Me gusta cocinar. Sobre todo, la buena cocina del pantano. Ancas de rana verdes fritas y esas cosas.|n|nY me he quedado sin ancas. Pero, la casa está llena de ranas. Ranas de marisma gigantes. ¿Podrías traerme algunas de esas ancas? No es muy difícil, solo golpéalas en la cabeza y tráeme las ancas.|n|nLo removeré y removeré y luego me lo comeré. Y también te daré un poco a ti.|n|n¿Te gustan los guisos?', },
    {'Lleva 10 ancas de rana de marisma a "Ojolodo" Jarl al Marjal Revolcafango.', },
  },
  [1219] = {
    '[DEPRECATED]El informe orco',
    {'Una criba de la tierra revela la mano cortada de un orco. En la mano hay un tubo de hueso. Y en el tubo, un papiro manchado de tierra.|n|nEl pergamino está escrito en lenguaje orco... y parece importante.', },
    {'Lleva el informe de espía al teniente Aden a Theramore.', },
  },
  [1220] = {
    '[DEPRECATED]Capitán Vimes',
    {'El capitán Vimes debería ver el informe orco que encontraste, $N. Conoce el idioma orco mejor que muchos. ¡Y debería saber que hay espías de la Horda cerca de Theramore!|n|nEl Capitán está en los barracones que hay en la parte noreste de la Isla Theramore.', },
    {'Lleva el informe de espía al capitán Garran Vimes.', },
  },
  [1221] = {
    'Los tubérculos hojazul',
    {'Los tubérculos hojazul son muy apreciados en todo el mundo. Pero son muy raros. Solo se encuentran aquí, en Los Baldíos, enterrados profundamente en Horado Rajacieno.|n|n¡Y es imposible encontrarlos a no ser que sepas dónde mirar! Por eso he amaestrado husmeadores taltuza para que los busquen. Tienen un olfato extraordinario, huelen los tubérculos a una distancia de 50 pasos.|n|nNo será fácil, pero si me traes tubérculos te pagaré muy bien.', },
    {'Coge un cajón con agujeros.|nCoge una vara de mando de husmeador.|nLee el manual de propietario de husmeador. |n|nCuando llegues a Horado Rajacieno, usa el cajón con agujeros para invocar un husmeador taltuza; usa la vara para que busque tubérculos. |n|nLleva 6 tubérculos hojazul, la vara de mando de husmeador y el cajón con agujeros a Mebok Mizzyrix a Trinquete.', },
  },
  [1222] = {
    'La fuga de Apestoso',
    {'¡Genial! ¡Por fin algo que no quiere comerme!|n|nNecesito ayuda con los bichos de por aquí. Y tú pareces ser justo lo que necesito, $Gchaval:señorita;.|n|nEl cocinero Morgan Stern está trabajando en una nueva receta y me ha mandado aquí a recoger hojas de cienagrana. Creo que opina que son sabrosas.|n|nEs lo mismo... el caso es que cuando buscaba una planta de cienagrana... ¡Me vi rodeado! ¿Podrías ayudarme a salir de aquí y vigilarme las espaldas mientras busco la cienagrana?', },
    {'Escolta a "Apestoso" Ignatz y luego ve a Theramore a hablar con Morgan Stern.', },
  },
  [1238] = {
    'El informe perdido',
    {'Una criba de la tierra revela la mano cortada de un orco. En la mano hay un tubo de hueso. Y en el tubo, un papiro manchado de tierra.|n|nEl pergamino es el informe de un orco que pasó semanas espiando la ciudad de Theramore.|n|nCon una rápida lectura del pergamino te das cuenta de que debes llevarlo al maestro de espías orco del Poblado Murohelecho.', },
    {'Lleva el informe de espía a Nazeer Picasangre al Poblado Murohelecho.', },
  },
  [1239] = {
    'La cabeza cercenada',
    {'Una enérgica excavación revela la cabeza de un orco macho, salvajemente cercenada. Sus labios se petrificaron con un gruñido y sus ojos oscuros tienen aún una mirada desafiante.', },
    {'Lleva la cabeza de orco desafiante a Nazeer Picasangre al Poblado Murohelecho.', },
  },
  [1240] = {
    'El trol médico brujo',
    {'¡Debemos conocer las circunstancias de la muerte de Marg! Y la única forma de conocerlas, $N, es a través de la magia de los trols.|n|nLleva la cabeza de Marg a Kin\'weelay. Está en el Campamento Grom\'gol, en la Vega de Tuercespina.|n|nKin\'weelay es el médico brujo de los trols Lanza Negra. Es muy poderoso. Si alguien puede hablar al espíritu de Marg Ojonocturno, ese es él.', },
    {'Lleva la cabeza de orco desafiante a Kin\'weelay al Campamento Grom\'gol de Vega de Tuercespina.', },
  },
  [1241] = {
    'El diplomático desaparecido',
    {'Recientemente, un diplomático fue enviado a Theramore para encontrarse con Jaina Valiente. Ese diplomático nunca llegó a su destino.|n|nCreo que los Defias están implicados, aunque no sé exactamente cómo. La desaparición del diplomático sigue sin ser del dominio público, pero no seguirá así mucho tiempo.|n|nHay unos agentes del rey explorando la ciudad en busca de pistas, pero tengo a mis propios contactos que me gustaría que trabajasen en esto.|n|nEn el Valle de los Héroes hay un viejo amigo mío llamado Jorgen. Encuéntrale, dale esta nota y sigue sus instrucciones.', },
    {'Encuentra a Jorgen en la Ciudad de Ventormenta.', },
  },
  [1242] = {
    'El diplomático desaparecido',
    {'Lleva esta nota a Elling Trias. No le digas nada. Simplemente sé amable y espera a que te responda. Y no te preocupes, lo hará.|n|nVoy a decirte esto una vez más, $N. Trata este asunto con seriedad, y mantén la boca cerrada.|n|nPodrás encontrar a Trias en su tienda de quesos, Queso de Trias, en el Distrito de Mercaderes. Buena suerte.', },
    {'Entrega la nota lacrada de Jorgen a Elling Trias en la Ciudad de Ventormenta.', },
  },
  [1243] = {
    'El diplomático desaparecido',
    {'Jorgen, viejo hijo de... Así que, ¿así es como va a ser, eh?|n|nPues muy bien, puedo con eso. Espero que encuentre El Vacío Abisal muy pronto.|n|nEsto es lo que va a pasar, $N. Empezaré a usar mis contactos aquí, pero tú vas a encargarte de los paseítos, no quiero perder dinero.|n|nVete a Villa Oscura en el Bosque del Ocaso y encuentra al vigía Backus. Generalmente patrulla el camino del norte justo fuera de la ciudad. Dile que estás buscando actividad Defias, que yo te lo he pedido y te ayudará dándote toda la información que pueda.', },
    {'Entrega la nota lacrada al vigía Backus en el Bosque del Ocaso.', },
  },
  [1244] = {
    'El diplomático desaparecido',
    {'¿Actividad Defias? Bueno, siempre hay actividad; incluso si están tranquilitos, les seguimos considerando una amenaza.|n|nPero ahora que lo pienso, hace poco tiempo vimos algo extraño. Debe de haber sido hace un par de semanas, algunos de sus agentes se habían reunido en la Granja de Addle. Según el informe, supuse que algo grande estaba pasando.|n|n¿Por qué no vas a echar un vistazo y me traes lo que encuentres?|n|nLa granja está al sur del camino de los Páramos de Poniente, justo al entrar en el Bosque del Ocaso.', },
    {'Encuentra el certificado Defias y llévaselo al vigía Backus en el Bosque del Ocaso.', },
  },
  [1245] = {
    'El diplomático desaparecido',
    {'¡Guau! Me parece muy complicado para ser algo que pueda llevarte por mal camino. Ni siquiera debería estar viendo esto. Llévaselo a Trias, él podrá encontrarle el significado. Y NO permitas que nadie se interponga en tu camino. Esto me supera, quizás incluso le supere a él, pero ya veremos.|n|nY hazme un favor, $N, no le digas a nadie que te he ayudado. Si mis superiores se enterasen de que sé algo de esto y no se lo cuento, probablemente me colgarían.', },
    {'Lleva el certificado Defias a Elling Trias en Ventormenta.', },
  },
  [1246] = {
    'El diplomático desaparecido',
    {'Sí, ahora que lo pienso... Dashel... Dashel algo... ¿Cómo se llamaba? ¡PUÑO! Dashel Puñopiedra. Le llaman Puño en algunos círculos... probablemente debido a que le encanta meterse en peleas.|n|nSuele estar en el Casco Antiguo. Justo en el centro. Vete a hablar con él. Si tienes que hacerlo, utiliza una espada o algo pesado y contundente para persuadirle. Y no dudes. Si está metido en esto tanto como sugieren estos papeles, entonces no va a darte ninguna información por voluntad propia.', },
    {'Habla con Dashel Puñopiedra en Ventormenta.', },
  },
  [1247] = {
    'El diplomático desaparecido',
    {'Eh, sí... Mmm... Quizás sepa algo sobre esa reunión en la Granja de Addle. Creo que fue hace unas semanas. Yo no participé. Acabé cuando el plan A falló... Malditos aventureros.|n|nEl tipo que teníamos dentro para el plan B, salió de Menethil; un tal Flaco. Eso es todo lo que sé sobre su plan de reserva.', },
    {'Habla con Elling Trias en Ventormenta.', },
  },
  [1248] = {
    'El diplomático desaparecido',
    {'Uno de mis contactos se retiró y se fue a Los Humedales, en la ciudad portuaria de Menethil. Seguro que te ayuda si le dices que estás trabajando para mí. Se llama Mikhail. Dijo algo sobre convertirse en camarero antes de irse de Ventormenta hace unos años.|n|nHabla con él, encuentra al Flaco este, y descubre si hay algo más que saber sobre el diplomático secuestrado. Tenemos que descubrir dónde le han llevado, o al menos, quién es. En los papeles no se dice nada sobre sus planes después de la captura.', },
    {'Habla con Mikhail en Los Humedales.', },
  },
  [1249] = {
    'El diplomático desaparecido',
    {'¿Dices que Elling te ha enviado? Bueno, pues entonces, la hospitalidad que te expresé, multiplícala por diez. Si necesitas cualquier cosa, solo tienes que pedirla. Haré lo que pueda para ayudarte.|n|nMmm, ¿el Flaco dices? No sé si le conozco, pero mantendré los ojos abiertos por si le veo.|n|nNo mires ahora, $N, pero el caballero que está allí en la salida, está mirando hacia aquí. Está escuchando nuestra conversación con demasiado interés, ya sabes lo que quiero decir... Si yo fuera tú, haría algo para detenerle antes de que salga corriendo.', },
    {'Vence a Tapoke Jahn antes de que escape y vuelve a ver a Mikhail en Menethil.', },
  },
  [1250] = {
    'El diplomático desaparecido',
    {'Los Defias no me pagaron lo suficiente para morir por su causa. Cogieron al rey. Sí, el rey de Ventormenta, no cualquier diplomático. Estaba de camino a Theramore para encontrarse con Jaina Valiente. Por lo visto, se trataba de algo gordo, un gran secreto. Pero no solo los Defias están implicados. Trabajan con alguien. Creo que sabían que esto era algo grande.|n|nLo único que yo tenía que hacer era subir a bordo del barco del rey a su hombre, mientras el barco estaba en el puerto. El tipo se llamaba Hendel. Eso es todo lo que sé. Lo juro.', },
    {'Habla con Mikhail en Los Humedales.', },
  },
  [1251] = {
    '[DEPRECATED]El escudo negro',
    {'Un escudo de hierro, ennegrecido por el fuego que arrasó la posada, cuelga de la chimenea, una de las pocas partes de la estructura de la Posada Reposo Umbrío que han sobrevivido.|n|nEl escudo puede separarse del ladrillo de la chimenea.', },
    {'Lleva el escudo de hierro ennegrecido a Krog al Poblado Murohelecho.', },
  },
  [1252] = {
    '[DEPRECATED]Teniente Paval Reethe',
    {'Debajo de los escombros, en el suelo, ves un destello de luz. Apartas los escombros y la ceniza y descubres una insignia de esmalte blanco con un ancla de oro: el sello de Theramore.|n|nDebajo del ancla hay un nombre grabado: "Teniente Paval Reethe".', },
    {'Lleva el distintivo de Reethe al capitán Garran Vimes de Theramore.', },
  },
  [1253] = {
    '[DEPRECATED]El escudo negro',
    {'Un escudo de hierro, ennegrecido por el fuego que arrasó la posada, cuelga de la chimenea, una de las pocas partes de la estructura de la Posada Reposo Umbrío que han sobrevivido.|n|nEl escudo puede separarse del ladrillo de la chimenea.', },
    {'Lleva el escudo de hierro ennegrecido al capitán Garran Vimes a Theramore.', },
  },
  [1258] = {
    '...con tropezones',
    {'Otro ingrediente para mi nueva receta es la pata de cangrejo gigante sin pelar. Para ello, los cangrejos del Marjal Revolcafango, esos que llaman reptadores de roca espinosos, ¡serían perfectos!|n|nLa cáscara de la pata de cangrejo es un elemento clave de la presentación del plato, así que necesito patas impolutas, sin marcas. Un cangrejo adulto solo tiene una o dos patas de esas y yo necesitaré muchas para mis pruebas.|n|nDirígete a las rocas que rodean Theramore y ¡consígueme esas patas!', },
    {'Lleva 12 patas de reptador prístinas a Morgan Stern a Theramore.', },
  },
  [1259] = {
    '[DEPRECATED]Teniente Paval Reethe',
    {'No reconozco el nombre... Teniente Paval Reethe... Será mejor que consultes al ayudante Tesoran. Él lleva todos los registros de la Guardia de Theramore, desde el personal hasta el equipamiento.|n|nÉl debería poder decirte quién es Reethe, solo tendrá que echar un vistazo a los libros.', },
    {'Averigua más sobre Reethe hablando con el ayudante Tesoran en Theramore.', },
  },
  [1260] = {
    nil,
    {'Estoy preparando un nuevo menú para el restaurante. Estará lleno de platos rurales con un mismo tema: el pantano. ¡Seguro que a mis clientes de El Ermitaño Taciturno les encanta!|n|nEnvié a mi sobrino Morgan a Theramore, una ciudad que hay en la frontera del Marjal Revolcafango. Está recogiendo recetas de sus habitantes y necesito saber qué ha conseguido hasta ahora.|n|nEl viaje a Theramore es largo. Demasiado para mí. Pero seguro que $Gun:una; $C como tú, aprovecha cualquier oportunidad para viajar.', },
    {'Habla con Morgan Stern en Theramore.', },
  },
  [1261] = {
    'Las declaraciones de Marg',
    {'¡Maldito Valvafango! ¡No puedes matar a Marg! Ah... pero estoy muerto. Así que debió de matarme...|n|n¡Mi misión! ¡Mi misión! $N, debes completarla.|n|nCuando estaba cerca de Theramore, estuve espiando a un grupo de soldados de la Alianza que había acampado en la playa. Uno de esos soldados llevaba un colgante cargado de gemas. ¡Ningún soldado puede permitirse un colgante así!|n|nUna noche me colé en su campamento y robé el colgante, ¡pero cuando regresaba a la base, uno de esos hombres-cangrejo Valvafango me mató!|n|n¡$N, debes encontrar a ese Valvafango y recuperar el colgante!', },
    {'Lleva el colgante con joyas a Nazeer al Poblado Murohelecho.', },
  },
  [1262] = {
    'Informa a Zor',
    {'Es extraño que ese colgante que robó Marg estuviera en manos de simples soldados. Quizás su dueño estaba disfrazado... ¡o quizás los soldados lo habían robado a su vez!|n|nSea cual sea la verdad, este es el colgante de un noble. Debemos encontrar a su dueño si queremos conocer su misteriosa historia.|n|nLleva el colgante a Zor Árbol Solitario a Orgrimmar. Conoce muy bien el ámbito político de la Alianza. Él sabrá si la historia de este colgante se entrelaza en algún punto con la de los nobles de Ventormenta.', },
    {'Lleva el colgante con joyas a Zor Árbol Solitario a Orgrimmar.', },
  },
  [1263] = {
    'La posada quemada <CHANGE TO GOSSIP>',
    nil,
    nil,
  },
  [1264] = {
    'El diplomático desaparecido',
    {'A principios de mes, todos los marineros de Kul Tiras reciben la paga y, generalmente, se van de Theramore en busca de diversión. Muchos vienen aquí a buscar mujeres, jarana y a pasárselo bien. Hay uno de esos grupos que viene regularmente a la taberna, y creo que ese Hendel está con ellos.|n|nEl comandante Samaul de Theramore podrá ayudarte a encontrarle, si Hendel está destinado allí. Es completamente leal a Valiente, pero si dejas caer el nombre de Elling, te ayudará... discretamente.', },
    {'Encuentra al comandante Samaul en el Marjal Revolcafango.', },
  },
  [1265] = {
    'El diplomático desaparecido',
    {'¿Hendel? Sí, le conozco. ¿Pero para qué necesitas a uno de mis soldados?|n|n¿Elling te ha enviado a buscarle? Mmm, no me gusta cómo suena eso. Elling no te habría pedido que vinieses primero a hablar conmigo si no se tratase de algo preocupante. Comprendo que no puedas decirme de qué va el tema, pero has de saber algo. Mi deber es proteger estas tierras. Si vas a causar problemas, te sugiero que me informes de todo lo que puedas.|n|nCreo que Hendel estaba destinado a la primera torre de las afueras de Theramore. Ten cuidado.', },
    {'Explora el Alto del Centinela en busca de alguna señal del soldado Hendel.', },
  },
  [1266] = {
    'El diplomático desaparecido',
    {'El soldado Hendel está al oeste de aquí. Actualmente está de guardia, protegiendo a algunos de los infiltrados de Theramore mientras descansan. Han estado vigilando la base de la Horda, Murohelecho, y atentos a cualquier otra amenaza potencial en nuestras fronteras.|n|nNo deberías tener problemas para encontrarle. Busca las tiendas que están junto al camino.|n|nTengo que encargarme de otro asunto, pero hablaremos pronto. Si me necesitas, puedes encontrarme en la torre de Lady Valiente.', },
    {'Encuentra al soldado Hendel en el Marjal Revolcafango.', },
  },
  [1267] = {
    'El diplomático desaparecido',
    nil,
    {'Habla con Jaina Valiente en el Pantano Revolcafango.', },
  },
  [1268] = {
    '[DEPRECATED]Huellas de pezuñas sospechosas',
    {'Hay hileras de huellas que se alejan del esqueleto, aún humeante, de la Posada Reposo Umbrío. Hay unas pocas impresiones visibles y algunas hileras de huellas casi imperceptibles en el barro blando del pantano.', },
    {'Informa a Krog en el Poblado Murohelecho sobre las huellas sospechosas de la Posada Reposo Umbrío.', },
  },
  [1269] = {
    'Teniente Paval Reethe',
    {'Debajo de los escombros, en el suelo, ves un destello de luz. Apartas los escombros y la ceniza y descubres una insignia de esmalte blanco con un ancla de oro: el sello de Theramore.|n|nDebajo del ancla hay un nombre grabado: "Teniente Paval Reethe".', },
    {'Lleva el distintivo de Reethe a Krog al Poblado Murohelecho.', },
  },
  [1270] = {
    'La fuga de Apestoso',
    {'¡Genial! ¡Por fin algo que no quiere comerme!|n|nNecesito ayuda con los bichos de por aquí. Y tú pareces ser justo lo que necesito, $Gchaval:señorita;.|n|nUn goblin de Trinquete llamado Mebok Mizzyrix necesita unas hojas de cienagrana para una poción o algo así... Tampoco es que me importe mucho. Me dio un buen dinero y conozco el pantano, así que...|n|n¡Una pena que me rodearan antes de que encontrara la cienagrana! ¿Puedes ayudarme? ¿Podrías cubrirme las espaldas mientras busco la planta de Mebok?', },
    {'Escolta a "Apestoso" Ignatz y luego ve a Trinquete a hablar con Mebok Mizzyrix.', },
  },
  [1271] = {
    '¡Una fiesta en tu honor!',
    nil,
    nil,
  },
  [1272] = {
    'Encontrar a Reethe <CHANGE INTO GOSSIP>',
    nil,
    nil,
  },
  [1273] = {
    '[DEPRECATED]El interrogatorio de Reethe',
    {'Me llevó un buen rato, pero encontré a Reethe. Estaba bien escondido, para ser humano.|n|nOgron temía que pudiera haber enloquecido después de pasar tanto tiempo en la marisma. Ven conmigo. Tiene que darnos algunas respuestas.', },
    {'Ve con Ogron a hablar con Reethe y luego vuelve al Poblado Murohelecho a hablar con Krog.', },
  },
  [1274] = {
    'El diplomático desaparecido',
    {'Disculpa, noble $Gcaballero:gentil dama;. El Obispo DeLavey me pidió que buscara la ayuda de aventureros que quizás puedan ayudarle.|n|nSi pudieras ir discretamente al Castillo de Ventormenta a hablar con él, seguro que te lo agradecería mucho. Y, de nuevo, por favor, con mucha discreción. Se trata de un asunto muy importante.', },
    {'Encuentra al Obispo DeLavey en el Castillo de Ventormenta.', },
  },
  [1275] = {
    'Investigaciones acerca de la corrupción',
    {'Esos insensatos elfos de sangre están estudiando la magia demoníaca. ¿Acaso no vieron lo que ocurrió con los nagas y los sátiros de Kalimdor?|n|nTemo que los elfos de sangre acabarán sufriendo una deformación similar. Azeroth no puede permitirse el surgimiento de otra raza de monstruos maléficos.|n|nQuisiera estudiar los cerebros de los sátiros y los nagas. Quizás consiga averiguar qué destino espera a los sin\'dorei. Puedes encontrar sátiros y naga en las Cavernas de Brazanegra, al oeste.', },
    {'Relwyn Sombrestrella en el Campamento Brazanegra quiere 8 bulbos raquídeos corruptos.', },
  },
  [1276] = {
    '[DEPRECATED]El escudo negro',
    {'¡Ah, ya lo recuerdo! Mosarn es un respetado herrero de Cima del Trueno. Sabía que había oído ese nombre antes...|n|nComo agradecimiento, el Anillo de la Tierra me recompensó con una armadura hecha por Mosarn. Es un buen trabajo.|n|nQuizás él pueda decirte más sobre el escudo que forjó.|n|nNo es gran cosa, pero como no conseguimos nada de Reethe, es todo lo que tenemos.', },
    {'Ve a Cima del Trueno y enseña el escudo de hierro ennegrecido a Mosarn.', },
  },
  [1277] = {
    '<nyi> <TXT> Las huellas de centauro',
    {'Kagoro ha revelado que las huellas de centauro pertenecen esos locos de Mauradon.', },
    {'Acaba con ellos.', },
  },
  [1278] = {
    '<nyi> <TXT> El clan Tótem Siniestro',
    nil,
    nil,
  },
  [1279] = {
    '<nyi> <TXT> Las huellas de centauro',
    {'Acaba con uno de los tres.', },
    nil,
  },
  [1280] = {
    '<nyi> <TXT> Las huellas de centauro',
    nil,
    nil,
  },
  [1281] = {
    'La canción de Jim <CHANGE TO GOSSIP>',
    nil,
    nil,
  },
  [1282] = {
    '[DEPRECATED]Le llaman Jim Sonrisas',
    {'El viejo Jim me da mucha pena. Antes no era así. Llevó una posada en la marisma durante un tiempo; un lugar fantástico.|n|nMira, no me apetece mucho hablar del tema. Si realmente quieres saber qué ocurrió, habla con el capitán Vimes. Está apostado en el piso de arriba de la Ciudadela Garrida, en los grandes barracones que hay al este de la torre de Lady Jaina.', },
    {'Habla con el capitán Garran Vimes que está en el piso de arriba de la Ciudadela Garrida.', },
  },
  [1283] = {
    'El incendio de Reposo Umbrío <CHANGE TO GOSSIP>',
    nil,
    nil,
  },
  [1284] = {
    '[DEPRECATED]Huellas de pezuñas sospechosas',
    {'Hay hileras de huellas que se alejan del esqueleto, aún humeante, de la Posada Reposo Umbrío. Hay unas pocas impresiones visibles y algunas hileras de huellas casi imperceptibles en el barro blando del pantano.', },
    {'Informa al capitán Garran Vimes, en Theramore, sobre las huellas sospechosas de la Posada Reposo Umbrío.', },
  },
  [1285] = {
    '[DEPRECATED]Los hombres de Daelin',
    {'Reddon... Redpath... Ah, aquí está. Teniente Paval Reethe.|n|nSe unió a la Guardia de Theramore junto con los reclutas que llegaron del mar con Lady Valiente. Se alistó con los marinos de Kul Tiras a la edad de dieciséis años. Servicio distinguido, ascensos...|n|nConsta como desaparecido.', },
    {'Lleva la información sobre Reethe al capitán Garran Vimes a Theramore.', },
  },
  [1286] = {
    '[DEPRECATED]Los desertores',
    {'Mantener nuestra presencia en la marisma ha sido una lucha constante. Pero con la fuerza de nuestra determinación, hemos conseguido mantener varias atalayas defensivas en la zona.|n|nLos últimos informes que he recibido de los exploradores indican que hay un grupo de desertores en una de nuestras torres abandonadas en Punta Perdida, al sureste de la posada.|n|nEl teniente que los lidera se llama Balos Jacken. Ve a ver si consigues algo de información de él.|n|nPero ten cuidado, $N. Será duro de pelar.', },
    {'Consigue información sobre Reethe hablando con Balos Jacken y los desertores del Marjal Revolcafango.', },
  },
  [1287] = {
    '[DEPRECATED]Los desertores',
    {'¿Reethe? ¿Ese cobarde?|n|nLo expulsamos del campamento porque insistía en robar los suministros de los ogros del Poblado Murohelecho. Y no somos tantos como para afrontar a esos brutos inconscientes.|n|nCruzó la línea demasiadas veces, así que dejamos que se las apañara solito.|n|nBien, yo te he ayudado... ¿Qué tal si ahora nos ayudas tú olvidando que nos has visto?', },
    {'Ve a Theramore y habla con el capitán Garran Vimes sobre Reethe.', },
  },
  [1288] = {
    'Informe de Vimes',
    {'Has hecho un buen trabajo, $N, lo mejor que he visto en $Gun:una; amateur.|n|nLady Valiente me pidió que la mantuviera al corriente de esta delicada situación pero hace tiempo que no informo.|n|nIba a enviarle mi informe más tarde, pero creo que sería mejor que fueras tú quien hablara con ella. Probablemente podrás contestar mejor a sus preguntas que yo.', },
    {'Lleva el informe de Vimes a Lady Jaina Valiente a Theramore.', },
  },
  [1289] = {
    '<nyi> El informe de Vimes',
    {'Bien, a juzgar por el informe del capitán Vimes, has sido de gran ayuda en esta investigación y te doy las gracias por ello.|n|nMe tranquiliza saber que el asunto está en manos tan capaces. Si no te importa, me gustaría pedirte que vuelvas con el capitán Vimes y le ayudes a llegar al fondo de este misterio.', },
    {'Vuelve junto al capitán Garran Vimes a Theramore.', },
  },
  [1290] = {
    '<nyi> La investigación de Mosarn',
    {'Habla con el guardia Komak. Hacer preguntas hace que te maten.', },
    {'Habla.', },
  },
