  [3100] = {
    'Carta simple',
    {'$N, me han pedido que te diera esto en cuanto terminaras de encargarte de los espías Roca Negra. Parece una carta sellada con la insignia de Llane, nuestro instructor de guerreros. Si fuera tú, la leería antes de hacer cualquier otra cosa en la Abadía.', },
    {'Lee la carta simple y habla con Llane Beshere en la Abadía de Villanorte.', },
  },
  [3101] = {
    'Carta consagrada',
    {'$N, me han pedido que te diera esto en cuanto terminaras de encargarte de los espías Roca Negra. Parece una carta sellada con la insignia del hermano Sammuel, nuestro instructor de paladines. Si fuera tú, la leería antes de hacer cualquier otra cosa en la Abadía.', },
    {'Lee la carta consagrada y habla con el hermano Sammuel en la Abadía de Villanorte.', },
  },
  [3102] = {
