  [3105] = {
    'Carta manchada',
    {'$N, me han pedido que te diera esto en cuanto terminaras de encargarte de los espías Roca Negra. Parece una carta sellada con la insignia de Drusilla, una de nuestras instructoras. Si fuera tú, la leería antes de hacer cualquier otra cosa en la Abadía.', },
    {'Lee la carta impía y habla con Drusilla La Salle junto a la Abadía de Villanorte.', },
  },
  [3106] = {
    'Runa simple',
    {'$N, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Thran, el instructor de guerreros. Échale un vistazo y, cuando puedas, ve a buscar a Thran a Yunquemar.', },
    {'Lee la runa simple, luego ve al Valle de Crestanevada y habla con Thran Khorman.', },
  },
  [3107] = {
    'Runa consagrada',
    {'$N, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Bromos, el instructor de paladines. Échale un vistazo y, cuando puedas, ve a buscar a Bromos a Yunquemar.', },
    {'Lee la runa consagrada, luego ve a Yunquemar y habla con Bromos Grummner.', },
  },
  [3108] = {
    'Runa con grabados',
    {'$N, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Thorgas, el instructor de cazadores. Échale un vistazo y, cuando puedas, ve a buscar a Thorgas a Yunquemar.', },
    {'Lee la runa con grabados, luego ve a Anvilmar y habla con Thorgas Grimson.', },
  },
  [3109] = {
    'Runa codificada',
    {'$N, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Solm, el instructor de pícaros. Échale un vistazo y, cuando puedas, ve a buscar a Solm a Yunquemar.', },
    {'Lee la runa codificada, luego ve a Yunquemar y habla con Solm Hargrin.', },
  },
  [3110] = {
    'Runa sacralizada',
    {'$N, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Silo, el instructor de sacerdotes. Échale un vistazo y, cuando puedas, ve a buscar a Silo a Yunquemar.', },
    {'Lee la runa sacralizada, luego ve a Yunquemar y habla con Silo Khalder.', },
  },
  [3111] = {
    nil,
    {'Hace mucho tiempo elfos superiores nos enseñaron los secretos de la magia junto a nuestros aliados humanos. Nos aleccionaron sobre las reglas ¡y sobre cómo la magia puede hacer que pierdas el juicio! Pero no lo creas. No somos como los elfos, no tenemos las mismas debilidades. Solo has de mantenerte en el camino justo y descubrirás que la magia es una herramienta tan poderosa como lo es un arma.|n|nCuando estés $Gpreparado:preparada;, ven a verme en Yunquemar. ¡Te estaré esperando!|n|n- Marrek Stromnur, instructor de magos.', },
    {'Habla con Marrek Stromnur en Yunquemar.', },
  },
  [3112] = {
    'Memorándum simple',
    {'Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Thran, el instructor de guerreros. Échale un vistazo y, cuando puedas, ve a buscar a Thran a Yunquemar.', },
    {'Lee el memorándum simple, luego ve al Valle de Crestanevada y habla con Thran Khorman.', },
  },
  [3113] = {
    'Memorándum encriptado',
    {'Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Solm, el instructor de pícaros. Échale un vistazo y, cuando puedas, ve a buscar a Solm a Yunquemar.', },
    {'Lee el memorándum encriptado, luego ve al Valle de Crestanevada y habla con Solm Hargrin.', },
  },
  [3114] = {
    'Memorándum glífico',
    {'Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Marryk, el instructor de magos. Échale un vistazo y, cuando puedas, ve a buscar a Marryk a Yunquemar.', },
    {'Lee el memorándum glífico, luego ve a hablar con Marryk Nurribit, dentro de Yunquemar, sobre el Valle de Crestanevada.', },
  },
  [3115] = {
    'Runa corrupta',
    nil,
    nil,
  },
  [3116] = {
    'Sigilo simple',
    {'Un mensajero de nuestra instructora de guerreros, Alyissia, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.', },
    {'Habla con Alyissia dentro de Aldrassil, en Cañada Umbría.', },
  },
  [3117] = {
    'Sigilo con grabados',
    {'Este sigilo me lo entregó un mensajero de nuestra instructora de cazadores, Ayanna. Parece que quiere hablar contigo. Léelo y luego llévaselo.', },
    {'Habla con Ayanna Semprerguida dentro de Aldrassil, en Cañada Umbría.', },
  },
  [3118] = {
    'Sigilo cifrado',
    {'Un mensajero de nuestro instructor de pícaros, Frahun, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.', },
    {'Habla con Frahun Sombrusurro dentro de Aldrassil, en Cañada Umbría.', },
  },
  [3119] = {
    'Sigilo sacralizado',
    {'Un mensajero de nuestra instructora de sacerdotes, Shanda, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.', },
    {'Habla con Shanda dentro de Aldrassil, en Cañada Umbría.', },
  },
  [3120] = {
    'Sigilo verdeante',
    {'Este sigilo me lo entregó un mensajero de nuestro instructor de druidas, Mardant. Parece que quiere hablar contigo. Léelo y luego llévaselo.', },
    {'Habla con Mardant Fuerterroble dentro de Aldrassil, en Cañada Umbría.', },
  },
  [3121] = {
    'Una extraña petición',
    {'¡Xerash Hojafuego, en el Pabellón de Lariss al norte del Campamento Mojache, tiene lo que necesito para empezar aquí! Ha preparado un mejunje que necesito para mi... bueno, ya lo verás.|n|nPonte en marcha. ¡A Xerash! Y llévate esto contigo. Es una cabeza reducida que le prometí a Xerash a cambio de las hierbas. Es la cabeza de un pobre enano que se tropezó conmigo en el bosque. Seguro que le encantará.', },
    {'Lleva la cabeza reducida a Xerash Hojafuego al Pabellón de Lariss en Feralas.', },
  },
  [3122] = {
    'Regresa junto al médico brujo Uzer\'i',
    {'Aquí tienes las hierbas, $N. Llévaselas al médico brujo Uzer\'i.|n|nY dile por favor que estoy muy satisfecho con la cabeza reducida.', },
    {'Entrega la faltriquera de hierbas de Xerash al médico brujo Uzer\'i en Feralas.', },
  },
  [3123] = {
    'Probar la vasija',
    {'Esto va a ser una prueba. Del ritual que celebré y de tus habilidades. Coge esta vasija, $N. Con ella tendrás el poder de reducir y capturar a una criatura.|n|nViaja a las tierras que hay al este de aquí y busca bestias. Los sañosos osos Cueracero y los corredores Dientelargo serán tu objetivo, $N. Mátalos y utiliza la vasija de muisek para reducirlos y capturarlos antes de que sus espíritus escapen.', },
    {'Mata a 10 osos Cueracero o corredores Dientelargo y usa la vasija de muisek de bestia para reducir y capturar a las bestias caídas.|n|nLleva 10 muestras de muisek de bestia y la vasija de muisek de bestia al médico brujo Uzer\'i en Feralas.', },
  },
  [3124] = {
    'Muisek de hipogrifo',
    {'Has demostrado merecer mi confianza y tener facultad suficiente para utilizar a las vasijas de muisek. Ahora quisiera que capturases a otra criatura.|n|nLos hipogrifos han sido compañeros leales de los elfos de la noche durante muchos años; sus espíritus son leales e inquebrantables.|n|nTu tarea consiste en acabar con 10 hipogrifos Plumavieja y, rápidamente, encogerlos y capturarlos usando la vasija, de forma que podamos conservar su muisek. Podrás encontrarlos en las Altas Tierras Salvajes, al sur de aquí.', },
    {'Acaba con 10 hipogrifos Plumavieja de cualquier tipo y utiliza la vasija de muisek para encogerlos y capturarlos.', },
  },
  [3125] = {
    'Muisek de dragón feérico',
    {'$N, ahora quiero que captures a una criatura que es de apariencia frágil pero que posee un espíritu poderoso, que es lo que me interesa de ella. Hablo de los dragones feéricos, unas criaturas que han servido como aliadas a los elfos de la noche. Debemos capturar uno para que la Horda pueda beneficiarse de la fuerza de su espíritu.|n|nAquí tienes la vasija, $N. Mata a 8 duendes dardo o duendes dragón y captura su muisek. Puedes encontrarlos al oeste de aquí.', },
    {'Mata a 8 duendes dardo o duendes dragón. Utiliza la vasija de muisek para reducir y capturar a los dragones feéricos caídos.', },
  },
  [3126] = {
    'Muisek de antárbol',
    {'Los caminabosques deambulantes que vagan por el bosque son nuestro siguiente objetivo, $N. Los elfos de la noche se han aliado con los antárboles para combatir a la Horda. Se mueven con lentitud, pero su papel como protectores es innegable.|n|nPronto podrán usar ese poder en nuestro beneficio.|n|nEncuentra a 3 Caminabosques deambulantes, mátalos y utiliza la vasija de muisek para reducirlos y capturarlos.', },
    {'Mata a 3 caminabosques deambulantes. Utiliza la vasija de muisek de antárbol para reducir y capturar a los antárboles caídos.', },
  },
  [3127] = {
    'Muisek de gigante montés',
    {'La última tarea que te encargaré es que viajes al noroeste y encuentres al enemigo definitivo.|n|nLos gigantes monteses dejaron sus montañas para ir a ayudar a los elfos de la noche cuando la Legión Ardiente apareció en el mundo. Los reconocerás por su descomunal talla y los encontrarás por la forma en la que el suelo temblará cuando viajes por su rocosa tierra.|n|nEstoy deseando controlar ese descomunal poder. Mata a 7 gigantes monteses y luego utiliza la vasija de muisek para capturar su potente muisek.', },
    {'Mata a 7 caminantes de la tierra o gigantes del risco. Utiliza la vasija de muisek para reducir y capturar a los gigantes monteses caídos.', },
  },
  [3128] = {
    'Materiales naturales',
    {'Necesitaré algunos materiales para completar mi tarea... Podrías conseguírmelos a la vez que cumples otras tareas que te asignaré.|n|nNecesitaré un tronco astillado de un antárbol de Feralas. Y minerales taraceados. Los llevan los gigantes monteses y los dragones feéricos del oeste. También necesito algún tendón resistente de las lechubestias de las Tierras del Interior o de los hipogrifos de Feralas. Y por último, necesito una gran cantidad de fragmentos metálicos de cualquiera de las criaturas que he mencionado.', },
    {'Lleva 2 troncos astillados, 6 minerales taraceados, 20 tendones resistentes y 40 trozos metálicos al médico brujo Uzer\'i al Campamento Mojache.', },
  },
  [3129] = {
    'Armas del espíritu',
    {'Imbuir el muisek en las armas es un proceso difícil. Ahora que tengo todo el material que necesito y el muisek de las criaturas que has capturado, puedo empezar a trabajar. Por favor, espera. Volveré en un momento.', },
    {'El médico brujo Uzer\'i quiere que esperes mientras prepara las armas.', },
  },
  [3130] = {
    'En contra de los Crestafuria',
    {'Voy a remitirte a mi segundo, Latronicus. Ha estado vigilando de cerca a las tropas naga hasta hoy. Evaluaré la situación general de esta zona, en lo que a los nagas se refiere; aunque me encantaría enviar a todo un ejército contra ellos, dejar la fortaleza expuesta a un ataque directo de la Horda –o peor– no es una solución deseable.|n|nEn fin, Latronicus espera. Has hecho un buen trabajo hasta ahora, $N. Sigue así.|n|nRetírate.', },
    {'Preséntate ante Latronicus Lanzaluna, en el Bastión Plumaluna.', },
  },
  [3141] = {
    nil,
    {'¿Así que quieres enfrentarte a demonios? Harías bien en escuchar mi relato.', },
    {'Escucha la historia de Loramus Thalimedes.', },
  },
  [3161] = {
    'Gahz\'rilo',
    {'¡$N, yo soy un científico pero tengo alma de cazador de tesoros!|n|nMucho tiempo atrás, cuando los trols ocupaban estas tierras, crearon gran cantidad de adornos inspirados en Gahz\'rilla, una hidra a la que rindieron culto como a una deidad. Estos adornos están tallados en un material que yo denomino "gahz\'rilo", derivado del propio nombre de la diosa hidra.|n|nYo mismo encontré algunos pero me gustaría tener más para poder estudiarlos a fondo. Quizás tú puedas buscarlos...|n|n¡Incluso he ideado un detector que hace de buscar gahz\'rilo un juego de niños! ¡Simplemente enciéndelo y que empiece la búsqueda!', },
    {'Marvon Buscarroblones de Tanaris quiere que reúnas 30 adornos de gahz\'rilo.', },
  },
  [3181] = {
    'El cuerno de la bestia',
    {'El enorme cuerno está lleno de arañazos y grietas. Hay un objeto metálico peculiar incrustado.|n|nAl observarlo de cerca, ves que es una cabeza de hacha rota. En el metal están inscritas las palabras:|n|nPropiedad de la montaraz Guijarro.|n|nCuando saques la cabeza de hacha, se romperá en mil pedazos.|n|n¡Qué cosas!', },
    {'Lleva el cuerno enorme de Margol a la montaraz Guijarro.|n', },
  },
  [3182] = {
    'Certificado de autenticidad',
    {'¿Cómo quieres que me crea eso? El cuerno de verdad tendría todavía mi hacha clavada.|n|nLlévale esa falsificación al comisario Torio a Forjaz. Si confirma tu historia, te dará un certificado de autenticidad. Si me lo traes, te daré la llave de La Garganta de Fuego.|n|n¡Andando!', },
    {'Lleva el cuerno enorme de Margol al comisario Torio a Forjaz.', },
  },
  [3201] = {
    '¡Al fin!',
    {'No puedo creer que Guijarro dude de la autenticidad del cuerno. Entre tú y yo, creo que está celosa; quería matar a la bestia ella misma, por aquello del incidente y tal.|n|nAsí que necesitas un certificado de autenticidad; por supuesto, te lo has ganado.|n|n<El comisario Torio empieza a rellenar un documento.>|n|n¡Aquí lo tienes! Llévaselo a Guijarro.', },
    {'Lleva el certificado de autenticidad a la montaraz Guijarro.', },
  },
  [3221] = {
    'Habla con Renferrel',
    {'Mientras estabas ahí fuera ayudando a nuestros mortacechadores, el boticario Renferrel te envió un llamamiento. No me dio ningún detalle, pero quería hablar contigo sobre los corazones de lobo que le entregaste.', },
    {'Habla con el boticario Renferrel en El Sepulcro.', },
  },
  [3241] = {
    '<NYI> <TXT><redux> Campo de Piedra Mácula',
    {'Reúne los tótems de la Cima Calígine, aquello está asqueroso ahora y no es lugar para tótems relucientes.', },
    {'Llévaselos a Tonga Tótem de Runa.', },
  },
  [3261] = {
    '[DEPRECATED in 4.x] Jorn Vidente del Cielo',
    {'Tu formación conmigo ha llegado a su fin, $N. Para seguir aprendiendo, debes ir al Campamento Taurajo, hacia el sur, y habla con Jorn Vidente del Cielo. Él seguirá con tu aprendizaje.', },
    {'Habla con Jorn Vidente del Cielo en el Campamento Taurajo.', },
  },
  [3281] = {
    '[DEPRECATED] La plata robada',
    {'Puede que hayas matado a los raptores ¡pero aún hay que recuperar la plata que robaron! Me han informado que los raptores tienen un gran número de nidos al sur de Trinquete, llaman a ese lugar Tierras de los Raptores. Es probable que llevaran allí nuestra plata robada.|n|nVe a ese refugio de raptores y busca la plata robada. Cuando la encuentres, devuélvemela.', },
    {'Llévale la plata robada a Gazrog en El Cruce.', },
  },
  [3301] = {
    'Mura Tótem de Runa',
    {'Mi compañera de clan, Mura Tótem de Runa, se dirigía al Bosque de Argénteos así que podría ayudar a nuestros aliados no-muertos. Este bosque está enfermo, se está muriendo, y Mura tenía la esperanza de devolverle la vida. Quizás la extraña vida que hemos encontrado aquí en Los Baldíos pueda ayudarla en su trabajo en el Bosque de Argénteos.|n|nToma uno de los caparazones que recolectaste y llévaselo a Mura en el Bosque de Argénteos. La encontrarás en El Sepulcro. Con un poco de suerte, el estudio del caparazón le dará una idea de lo que necesita para curar ese lugar agonizante.', },
    {'Habla con Mura Tótem de Runa en El Sepulcro, en el Bosque de Argénteos.', },
  },
  [3321] = {
    '¿Has perdido esto?',
    {'Has hecho mucho por la Orden, $N. La dedicación necesaria para llegar hasta aquí hubiera desalentado a cualquier otro. No me cabe duda, ni a Galvan tampoco, de que eres $Guno:una; de los nuestros.|n|nPor eso considero que mereces una recompensa. No es nada de otro mundo, tan solo un pequeño detalle. Puede que conozcas sus propiedades, que creo que es lo que en realidad te ha traído hasta nosotros.', },
    {'Espera a que Trenton acabe su trabajo.', },
  },
  [3341] = {
    'Acaba con la amenaza',
    {'En Los Baldíos se encuentra una horrible maraña de vides llamadas Zahúrda Rajacieno. Aunque los primeros estudios de este lugar indicaban que no representaba una seria amenaza, nuestros últimos descubrimientos son un poco más desconcertantes...|n|nLos jabaespines de Zahúrda Rajacieno se han aliado con la Plaga. Un exánime llamado Amnennar el Gélido los gobierna, usando el poder de su vasto conocimiento para controlar cada uno de sus movimientos.|n|n$N, Amnennar tiene un vínculo telepático directo con Ner\'zhul que debemos eliminar y, para ello, hay que acabar con el Gélido cuanto antes.', },
    {'Andrew Brownell quiere que mates a Amnennar el Gélido y que le lleves su cráneo.', },
  },
  [3361] = {
    'Las penurias de un refugiado',
    {'Cuando me disponía a unirme a mis compañeros gnomos en Gnomeregan, ¡algo terrible ocurrió!|n|nDejé Yunquemar maleta en mano y me dispuse a atravesar la espesa capa de nieve. Entonces, estalló un estúpido terremoto y perdí el rumbo. Terminé aquí, y, lo que es peor, ¡los trols me robaron todo!|n|n$N, he demostrado ser bastante incompetente este último día y medio. ¿Te importaría infiltrarte en los campamentos trol del suroeste y recuperar mis cosas?', },
    {'Consigue la caja de Félix, el cofre de Félix y el cubo de tornillos de Félix.', },
  },
  [3362] = {
    'El Valle Cardizal',
    {'¿Has estado alguna vez en el Valle Cardizal? Es un lugar muy peligroso, $N.|n|nEsas extrañas bestias que hay allí... ¡no me fío ni un pelo de ellas! Creo que se llaman Cardizales nudosos y enraizadores Cardizales, o algo parecido...|n|nDe cualquier forma, quiero ir al valle pero con todos esos Cardizales deambulando por ahí, no creo que consiga volver con vida. Y aquí es donde entras tú. Si pudieras acabar con algunos de ellos, quizás consiga regresar de una pieza. ¿Qué te parece, $N? ¿Me ayudas?', },
    {'Tran\'rek de Gadgetzan quiere que mates a 8 Cardizales nudosos y a 8 enraizadores Cardizales.', },
  },
  [3363] = {
    'Melodía corrupta',
    nil,
    nil,
  },
  [3364] = {
    'Entrega una infusión de albaza hirviendo',
    {'¡Ay! Se supone que tenía que llevar esta deliciosa infusión de albaza a Durnan Cortapieles, de Yunquemar, pero antes tengo que entregar una a Grelin. ¡Se enfriará antes de que llegue a Yunquemar!|n|nTú pareces $Grápido:rápida;. Seguro que tú lo consigues. Esta taza estará caliente solo unos cinco minutos más y Durnan no pidió infusión fría de albaza, así que, ¡en marcha! Yunquemar está al noreste. Es un emplazamiento excavado en la montaña.|n|nGracias, $N. ¡Y no olvides devolverme la taza!', },
    {'Lleva la infusión de albaza hirviendo a Durnan Cortapieles a Yunquemar antes de que se enfríe, ¡tienes 5 minutos!', },
  },
  [3365] = {
    'Devuelve la jarra',
    {'¡Qué a gusto me he quedado, oye! Nada calienta el alma en un frío día de invierno como una infusión calentita –no, ARDIENTE– de albaza.|n|nTen, $N. Llévale a Nori esta jarra vacía de mi parte, ¿quieres?', },
    {'Devuelve la jarra a Nori Rumborgullo, en el Valle de Crestanevada.', },
  },
  [3366] = {
    'El fragmento resplandeciente',
    {'El fragmento es verde y brillante y, aunque sólido, parece que hubiera humo arremolinándose bajo su superficie. No se puede evitar perder la mirada en las profundidades del cristal y, al mismo tiempo, uno sabe que hay algo muy desconcertante.|n|nQuizás deberías ir a ver si alguien de Trinquete puede decirte algo más sobre este extraño fragmento.', },
    {'Viaja hasta Trinquete para averiguar el significado oculto tras el Fragmento de Pesadilla.', },
  },
  [3367] = {
    'Piedras de Suntara',
    {'<Dorius gruñe.>|n|nEstoy malherido, $R. Todo me da vueltas... Seguro que tengo hemorragias internas.|n|nTengo que volver a Forjaz. Ayúdame, $N.|n', },
    {'Ayuda a Dorius a volver a Forjaz.|n', },
  },
  [3368] = {
    'Piedras de Suntara',
    {'Hermano:|n|nSi estás leyendo esta carta, yo ya no estoy en este mundo. Da las gracias en mi nombre a quien te la haya entregado y recompénsale.|n|nEn cuanto a las piedras, te confirmo que existen y las tienen los Hierro Negro. Su jefe, Lathoric el Negro, las usa para tener esclavizado a mi equipo de excavación; se los llevaron a La Caldera. Están obsesionados con algo que llaman Obsidion.|n|nAyúdalos, hermano. Esta es mi última voluntad.|n|nDorius|n', },
    {'Lleva la carta chamuscada a Thorius a Forjaz. Está en la Sala de los Expedicionarios.', },
  },
  [3369] = {
    'En las pesadillas',
    {'Este fragmento alberga grandes secretos, es la esencia pura del Sueño Esmeralda. Sin embargo, lo que veo en él no es un sueño; hay quien llamaría a esta especie de visión una auténtica pesadilla.|n|nNo quiero alarmarte, $N, pero creo que lo mejor será que lleves este fragmento a manos de un sabio druida tan pronto como puedas...|n|nNecesitas encontrar a Hamuul Tótem de Runa del Alto de los Ancestros. Dirígete a Cima del Trueno. No puedo decirte nada más.', },
    {'Lleva el Fragmento de Pesadilla a Hamuul Tótem de Runa en el Alto de los Ancestros.', },
  },
  [3370] = {
    'En las pesadillas',
    {'Este fragmento alberga grandes secretos, es la esencia pura del Sueño Esmeralda. Sin embargo, lo que veo en él no es un sueño; hay quien llamaría a esta especie de visión una auténtica pesadilla.|n|nNo quiero alarmarte, $N, pero creo que lo mejor será que lleves este fragmento a manos de un sabio druida tan pronto como puedas...|n|nNecesitas encontrar a Mathrengyl Garroso del Círculo Cenarion. Dirígete a Darnassus. No puedo decirte nada más.', },
    {'Lleva el Fragmento de Pesadilla a Mathrengyl Garroso de Darnassus.', },
  },
  [3371] = {
    'La justicia de los enanos',
    {'Siento que hay un agujero en donde una vez estuvo mi corazón, $N. Tardaré en asumir la muerte de Dorius. Voy a cumplir su última voluntad: hay que llevar ante la justicia a su asesino.|n|nVuelve a La Garganta de Fuego y libera a sus hombres. Los enanos Hierro Negro obligan a sus esclavos a trabajar en una mina sofocante llamada La Fosa de la Escoria. Busca allí a los hombres de Dorius.', },
    {'Vuelve a La Garganta de Fuego y encuentra a la unidad arqueológica de Dorius.', },
  },
  [3372] = {
    'Libéralos',
    {'Libéralos, $R. Aunque fallen sus cuerpos, el poder de Suntara les empuja a seguir trabajando.|n|nLa clave está en el Altar de Suntara. Ve al noroeste; el Martillo Crepuscular guarda una reliquia en las colinas que hay sobre la cueva. Recógela y colócala en el Altar de Suntara.|n|n<Pierde el conocimiento.>', },
    {'Encuentra el artefacto misterioso que protegen los idólatras de Martillo Crepuscular en el cuadrante noroeste de La Garganta de Fuego y tráelo al altar de Suntara en la Fosa de la Escoria.|n', },
  },
  [3373] = {
    'La esencia de Eranikus',
    {'Cuando tocas la gema, una voz profunda resuena en tu cabeza.|n|n"Mortal, escucha esta súplica. Soy Eranikus del Vuelo Verde, guardián de este templo maldito. Mi deber de asegurarme de que los trols nunca jamás vuelvan a traer su abominación de dios, ha fracasado. Mientras esta gema queda imbuida de parte de mi esencia, puedo sentir que mi vínculo con el Sueño se dirige hacia el caos. Por favor, coloca esta gema en la fuente de esencia de mi guarida, y deja que nuestra magia purgue la corrupción de mi psique, para que pueda descansar."', },
    {'Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido.', },
  },
  [3374] = {
    'La esencia de Eranikus',
    {'Coges la piedra de juramento y oyes en tu cabeza la voz de Itharius que te habla a través de ella.|n|n"Al aceptar la orden que contiene esta piedra de juramento, te comprometes a ayudarme a mí y al Vuelo de Ysera a redimir la corrupta alma de Eranikus. El primero de los muchos sacrificios que con toda seguridad tú y yo haremos consiste en que me entregues la gema que está mermando lo poco de la psique de Eranikus que todavía estaba libre de malvadas influencias."|n|n"$N, hazlo y entonces podremos ofrecerle redención a un alma que bien la merece."', },
    {'Llévale la piedra de juramento del Vuelo de Ysera y la esencia encadenada de Eranikus a Itharius, que está en el Pantano de las Penas. Una vez allí, deberás decidir si quieres ayudar al Vuelo de Ysera o no.', },
  },
  [3375] = {
    'Otra ampolla',
    {'¿Que necesitas otra ampolla de adivinación? Estás de broma, ¿verdad? ¡¿Qué has hecho con la otra?! Tenemos mucho trabajo, $R. ¡Las ampollas no crecen en los árboles! Y ojalá lo hicieran, porque no tengo ninguna.|n|nTe haré una, pero necesito lo siguiente: una poción de maná, un trozo de carbón y algo de néctar dulce. No preguntes por qué, tú tráeme estas cosas y ya está.', },
    {'Lleva 1 poción de maná, 1 trozo de carbón y néctar dulce a Talvash del Kissel a Forjaz. Te dará una ampolla de adivinación.', },
  },
  [3376] = {
    'La cabeza de Cornapunta',
    {'He oído hablar de ti, $N. Quizás tú puedas ayudarnos donde otros han fallado.|n|nLos tauren hemos hecho un hogar de esta tierra, pero a un precio alto. Los jabaespines Erizapúas del Barranco Cortazarza, liderados por el Jefe Cornapunta Mantospina, nos acosan continuamente. ¡Quiero la cabeza del jefe! ¡Tráemela!|n|nEstará en el barranco que hay al este de su aldea.', },
    {'Lleva la cabeza del Jefe Cornapunta Mantospina a la Valiente Pluma de Viento en Mesa de la Nube Roja.', },
  },
  [3377] = {
    'Rezo a Elune',
    {'¿Quieres ayudarme, mortal? Escucha lo que tengo que decir.', },
    {'Escucha a Zamael.', },
  },
  [3378] = {
    'Rezo a Elune',
    {'¿Me ayudarás, mortal? Busca el rezo a Elune.|n|nEstá grabada en una tablilla dorada. Seguro que alguno de esos rufianes idólatras la lleva consigo.|n|nSi consigues recuperarla, llévasela a Astarii Buscaestelar, que está en Darnassus. Poco importa que haya recuperado la fe después de todos los crímenes que he cometido, pero quiero que se oiga mi oración. No espero la absolución.', },
    {'Lleva el rezo a Elune a Astarii Buscaestelar a Darnassus.|n', },
  },
  [3379] = {
    'Las tejedoras de sombra',
    {'Las arañas de La Garganta de Fuego son una fuente increíble de seda de las Sombras. Como ya sabrás, este elemento tiene mucha demanda.|n|nRecientemente, un grupo de furtivos ha invadido estas tierras, acabando con las arañas de forma masiva y sin pensar en los efectos a largo plazo de sus actos. Lo primero que te voy a pedir es muy sencillo: encuéntralos y acaba con ellos.|n|nComienza tu búsqueda por el norte.|n|nSi necesitas ayuda, habla con Arrasa.', },
    {'Mata a los furtivos Sedaumbría de La Garganta de Fuego. Nilith cree que son 5. Ve a ver a Nilith en La Garganta de Fuego cuando hayas terminado.|n', },
  },
  [3380] = {
    'El Templo Sumergido',
    {'En este mundo, hay espíritus inquietos, $N. Espíritus marcados por su aislamiento, atados a un mal ancestral...|n|nHe oído hablar de un lugar en el fondo de las profundidades de la tierra. Ha sido desterrado allí por poderes muy superiores a los que jamás he visto.|n|nSi quieres saber más cosas sobre este lugar, el Templo Sumergido, busca a un goblin llamado Marvon Buscarroblones. Ha estudiado muchas zonas antiguas del mundo. Se sabe que dejó su hogar en Trinquete para estudiar las ruinas trols en Tanaris.', },
    {'Encuentra a Marvon Buscarroblones en Tanaris.', },
  },
  [3381] = {
    'Un encuentro con el maestro',
    {'Ah, $Gun:una; joven; $R que viene a hablar con Sanath. ¡Qué día tan maravilloso! Es un gran honor el que me concedes visitándome. ¡Gracias!|n|nTe lo ruego... no seas tan arrogante como para pensar que mi sarcasmo era un cumplido. Dejemos esto claro: no me gustas. Pero esta charlita nada tiene que ver con nosotros, tiene que ver con mi maestro.|n|nTráeme un par de plumas de hipogrifo para mis flechas y te daré permiso para verlo. Me ha pedido que le envíe aventureros si demostraban tener arrestos.', },
    {'Llévale 2 plumas de hipogrifo intactas a Sanath Lim-yo en Azshara si deseas hablar con su maestro.', },
  },
  [3382] = {
    'Un equipo bajo el fuego enemigo',
    {'Estábamos a escasa distancia de la costa buscando un puerto seguro donde echar anclas. El sol se había puesto más de una hora antes cuando atacaron... ¡malditos nagas!|n|nNo estoy seguro de lo que buscaban pero está claro que no lo encontraron, ya han vuelto una vez. Tengo a un par de exploradores vigilando la entrada del valle para que nos puedan avisar con tiempo si ven otro ataque venir.|n|nSiento que hayas venido ahora, $N, pero no depende de mí.|n|n¿Estás $Glisto:lista; para el combate de tu vida?', },
    {'Defiende a la capitana Vanessa Beltis, su tripulación y los pasajeros del Explorador del horizonte frente al ataque de los nagas. La capitana Vanessa Beltis tiene que sobrevivir.', },
  },
  [3385] = {
    'El Mercado Negro',
    {'Se autodenominan El Mercado Negro: son mercaderes degolladores que venden, traslada, intercambian o hacen de todo por el precio adecuado.|n|nY es aún peor, $N. Han establecido una base de operaciones aquí en La Garganta de Fuego. El maestro de comercio Kovic encabeza las operaciones y mantiene estrechas relaciones con los enanos Hierro Negro de la región.|n|nTenemos que darles un duro golpe y enviar un mensaje a sus líderes. Mata al maestro de comercio Kovic y a su esbirro Clonk. Trae su cartera de mercader cuando hayas acabado.|n|n¡A La Caldera!', },
    {'Mata al maestro de comercio Kovic y a su esbirro, Clonk. Lleva su cartera a Nilith.|n', },
  },
  [3402] = {
    'El Mercado Negro',
    {'Quiero que tú des la noticia de la derrota de Kovic a Vizzklick, en Gadgetzan. Se alegrará de saber que Kovic ha muerto; seguro que su recompensa será generosa.', },
    {'Habla con Vizzklick en Gadgetzan.|n', },
  },
  [3421] = {
    'El viaje de vuelta',
    nil,
    nil,
  },
  [3441] = {
    'Castigo divino',
    {'Escúchame bien.', },
    {'Escucha a Kalaran Espada del Viento.', },
  },
  [3442] = {
    'La llama pura',
    {'Has tomado la decisión correcta, $N. |n|nDebemos atacar donde más daño hagamos: en las 4 torres del centinela. |n|nSi las incendiamos, podremos atacar sin darles tiempo a reaccionar. |n|nPara incendiar las torres necesitarás una herramienta. Necesito algunas cosas para fabricarla. |n|nTráeme 4 corazones de llama y 4 aceites de gólem; con eso te haré la antorcha de llama pura. |n|nBusca primero a los gólems y elementales de estas tierras.', },
    {'Lleva 4 corazones de llama y 4 globos de aceite gólem a Kalaran Espada del Viento.', },
  },
  [3443] = {
    'Forjar el mango',
    {'Necesitamos un soporte y un mango para transportar la llama pura. Busca primero el mango.|n|nLos capataces y esclavistas Hierro Negro de La Caldera usan armas de torio encantado, una aleación muy resistente. Si me traes 8 dagas bañadas en torio, fundiré la aleación para fabricar el mango.|n', },
    {'Lleva 8 dagas bañadas en torio a Kalaran Espada del Viento.', },
  },
  [3444] = {
    'El Círculo de Piedras',
    {'Una vez entré en las cámaras prohibidas del Templo Sumergido. El mal que yace en ese lugar penetra en todo lo que entra. Casi no consigo salir de allí, vadeando entre el lodo que cubre el suelo. Todo lo que puedo recordar es que pasé a trompicones por una gran sala circular llena de estatuas de la Serpiente...|n|nHace poco, descubrí una piedra redonda que parece tener el mismo símbolo de la Serpiente grabado. Hice que me la enviaran a mi taller en Trinquete. Recupérala y podré decirte más cosas.', },
    {'Recupera el Círculo de Piedras del taller de Marvon Buscarroblones, en Trinquete.', },
  },
  [3445] = {
    'El Templo Sumergido',
    {'He oído hablar de un lugar que yace en la profundidad de la tierra... Ha sido desterrado allí por poderes muy superiores a los que jamás he visto.|n|nSi quieres saber más cosas sobre este lugar, el Templo Sumergido, busca a un goblin llamado Marvon Buscarroblones. Al igual que Troyas y yo, ha estudiado muchas zonas antiguas del mundo. Dejó su hogar en Trinquete para estudiar las ruinas trols en Tanaris.|n|nTe deseo buena suerte para encontrarle, hace mucho tiempo que no se oye nada de él.', },
    {'Encuentra a Marvon Buscarroblones en Tanaris.', },
  },
  [3446] = {
    'En las profundidades',
    {'Dentro del templo, encontré una sala circular con seis balcones. Cada uno de ellos tenía una estatua de la Serpiente en el borde. Curioso, empujé una de ellas para ver lo que pasaba, ¡era una trampa! Casi encuentro la muerte en la explosión que surgió. Allí, en el borde, miré hacia abajo y vi otra estatua en el fondo de la sala, una especie de altar... Creo que se llamaba Hakkar.|n|nMe da la impresión de que ese altar es el secreto. Debes llevar este objeto al altar del Templo Sumergido.', },
    {'Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas.', },
  },
  [3447] = {
    'El secreto del círculo',
    {'Mis recuerdos son borrosos, pero te diré lo que pueda. Aunque el círculo de estatuas del Templo Sumergido es peligroso, creo que contiene el secreto para encontrar un tesoro mucho mayor.|n|nDesde el altar principal, conseguí activar una serie de luces. Si puedes descubrir el significado de esas luces, quizás puedas revelar el secreto que se esconde en esa sala.|n|nPero te lo advierto, $N. Un gran mal yace en el templo. Lo más probable es, que si hay algo de valor, estará muy protegido...', },
    {'Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas.', },
  },
  [3448] = {
    'Encargarse de la investigación',
    {'Me han encargado que investigue Azshara, una tierra que fue hermosa y que los elfos llamaban hogar. Eso fue en la época en la que practicaban la magia. Ahora es un lugar más peligroso que hermoso, pero debemos buscar respuestas sobre nuestro pasado.|n|nUn compañero llamado Tymor se interesa por estas cosas y se ofreció a ayudarme.|n|nTiene una pequeña tienda a la derecha de la Sala de los Misterios, aquí en la ciudad.', },
    {'Habla con Tymor en Forjaz.', },
  },
  [3449] = {
    'Runas Arcanas',
    {'Hubo un tiempo en que algunos elfos veneraban la magia tanto como a Elune. Sus magos más poderosos crearon runas y tablillas con leyes de lo arcano y reflexiones sobre sus descubrimientos. Las dejaban en lugares públicos para quien quisiera estudiarlas.|n|nQuisiera que calcaras las runas de las Ruinas de Eldarath. Te daré el material necesario para calcar, pero las runas tendrás que encontrarlas tú. Pero ten cuidado; la Liga de Expedicionarios no es el único grupo interesado en Eldarath.', },
    {'Haz calcos de la Runa de Beth\'Amara, la Runa de Jin\'yael, la Runa de Markri y la Runa de Sael\'hai. Luego ve a la isla frente a la península meridional de Azshara y avisa al piloto Xiggs Botafuego para que recoja los calcos.', },
  },
  [3450] = {
    'Un simple envío',
    {'Quiero que los calcos se entreguen en mi torre, pero no hace falta que vayas hasta allí. Haré que sean transportados por aire desde Azshara.|n|nXiggs Botafuego me debe un par de favores y estará en esta zona en breve; lo han destinado a patrullar la costa. Habla con él antes de irte. Te dará una pistola de bengalas para comunicaros. Cuando tengas los calcos, ve a donde te diga y dáselos para que los envíe a mi torre. Estará en el hangar de la Sala Militar.', },
    {'Habla con Xiggs Botafuego en Forjaz.', },
  },
  [3451] = {
    'Una señal para el envío',
    {'Así que te envía Tymor, ¿eh? Sí, le debo un par de favores. ¿Qué es esto? Vaya con el ladino de él. Bueno, puedo ocuparme de esto. Necesitas una pistola de bengalas y un punto de encuentro; eso es fácil.|n|nHay una isla pequeña con una zona de aterrizaje junto a la península sur de Azshara. Lanza una bengala cuando llegues. Yo iré a recoger esto, lo que sea que es.', },
    {'Habla con Xiggs Botafuego para que te dé una pistola de bengalas en Forjaz.', },
  },
  [3452] = {
    'El soporte para la llama',
    {'Nos falta un elemento para acabar la antorcha.|n|nEn las montañas del noroeste encontrarás un campamento de Martillo Crepuscular. Se dice que llevan símbolos e ídolos en honor a su dios; seguro que tienen suficiente magia para crear un soporte encantado. Tráeme un símbolo de Ragnaros; intentaré extraer su magia.', },
    {'Lleva un Símbolo de Ragnaros a Kalaran Espada del Viento.', },
  },
  [3453] = {
    'La antorcha de reprensión',
    {'Déjame montar el conjunto y pronunciar los encantamientos.|n', },
    {'Espera a que Kalaran Espada del Viento termine la antorcha de reprensión.|n', },
  },
  [3454] = {
    'La antorcha de reprensión',
    {'Ahora hay que vincular la antorcha a quien la porta. Cógela, $N.', },
    {'Coge la antorcha de reprensión.', },
  },
  [3461] = {
    'Regresa junto a Tymor',
    {'Tymor no me ha dado nada para pagarte, así que háblalo con él cuando vuelvas a Forjaz. Seguro que estará en la Sala Mística. Ve a saludar y no te vayas hasta que pague. Esto que te ha encargado no era fácil.|n|nPero gracias otra vez por ayudarle y buena suerte.|n|nAh, y llévate las cosas de calcar. Dáselas a Tymor cuando lo veas.', },
    {'Devuelve el juego de calco a Tymor, que está en Forjaz.', },
  },
  [3462] = {
    'Escudero Maltrake',
    {'Habla con mi enviado, el escudero Maltrake; te dirá cómo usar la antorcha de reprensión.', },
    {'Habla con mi enviado, el escudero Maltrake.', },
  },
  [3463] = {
    '¡Préndeles fuego!',
    {'Escúchame bien, $N. Aunque no es posible destruir las torres, con la antorcha de reprensión provocarás unos incendios muy difíciles de extinguir, un fuego que no puede apagar ninguna fuerza ni elemento.|n|nMientras ardan no podrá haber centinelas ni guardias; su primera línea de defensa quedará anulada.|n|nTienes que entrar en cada torre y usar la antorcha de reprensión dentro de las fortificaciones. Ten cuidado con los oteadores de los Hierro Negro, $N.', },
    {'Entra en las 4 torres del centinela e incéndialas con la antorcha de reprensión.|n', },
  },
  [3481] = {
    'Abalorios...',
    {'El cofre está cerrado con llave.', },
    {'Abre el cofre.', },
  },
  [3482] = {
    '<NYI> <TXT> La caja negra con agujeros',
    {'Esta es la versión para la Horda de la misión de la caja negra.', },
    {'Llévale esta caja a Kravel.', },
  },
  [3483] = {
    'Una señal para el envío',
    nil,
    nil,
  },
  [3501] = {
    'Todo cuenta en grandes cantidades',
    {'Aunque probablemente no encuentres nunca una esfera draenetista perfecta, seguro que encontrarás trozos draenetistas imperfectos al explorar estas tierras.|n|nAunque es improbable que Kum\'isha pueda usar los trozos imperfectos para volver a su hogar, las piezas podrían ser de utilidad para otros fines de los draenei.|n|nTráeme todos los trozos draenetistas imperfectos que encuentres y te recompensaré.', },
    {'Llévale a Kum\'isha trozos draenetistas imperfectos y te recompensará por cada fragmento entregado.|n', },
  },
  [3502] = {
    'Un trasto de Draenei...',
    {'Vaya, después de semejante despliegue de voraz codicia, siento náuseas.|n|nEn fin, no me detendré en tu materialismo.|n|nPor cada trozo draenetista imperfecto que traigas, te recompensaré con más baratijas. Mi pila de chatarra se reduce mientras la tuya crece. Como se dice en Draenor, no hay nada que perder.|n', },
    {'Llévale a Kum\'isha trozos draenetistas imperfectos. Cualquier forma de monstruo de Las Tierras Devastadas podría llevar uno de estos fragmentos.|n', },
  },
  [3503] = {
    'Encuentro con el maestro',
    nil,
    nil,
  },
  [3504] = {
    'Traición',
    {'¡Ladrona traidora! Es el único nombre por el que merece ser llamada.|n|nHe cometido un gravísimo error, $N. Confié en una elfa de sangre.|n|nAfirmaba que Azshara estaba llena de tesoros, de objetos de poder. Le concedí algunos guerreros como escolta esperando obtener beneficio, y mira lo que obtuve: los mató a todos.|n|nQuiero vengarme, pero no puedo prescindir de nadie más, $N. Ve a ver a Ag\'tor a Valormok, al norte del Campamento Haldarr. Te dará más información.', },
    {'Entrega la carta lacrada a Ag\'tor Puñosangre en Azshara.', },
  },
  [3505] = {
    '[DEPRECATED 4.x] Traición',
    {'Esperaba algo así.|n|nEmpezaremos la campaña contra su gente en los riscos meridionales de la península norteña de Azshara. Masácralos a todos; que sepan que traicionarnos se paga muy caro.|n|nNo te preocupes por ella de momento; pasa casi todo el tiempo explorando Azshara con sus guardaespaldas. Cuando acabes con los suyos, busca su campamento privado. Explora formas de ataque. Puede que encuentres algo con lo que podamos provocarla.', },
    {'Mata a 10 reivindicadores y 10 peritos elfos de sangre antes de buscar el campamento de Maga Rimtori. Una vez allí, busca algo que sea importante para ella, algo con lo que provocar un combate.', },
  },
  [3506] = {
    'Traición',
    {'Piensas un poco y se te ocurre algo que te hace sonreír: puede que destruir los cristales irrite a la responsable de la muerte de tantos orcos y la traición de Belgrom.|n|nSigues descifrando las imágenes y el texto y ves que uno de los cristales está unido al creador del círculo; los demás lo están a algo mucho más siniestro.|n|nCierras el libro y te pones a pensar en qué cristal vas a destruir.', },
    {'Destruye el cristal de enfoque Arcano de Maga Rimtori y entonces mátala. Lleva su cabeza a Ag\'tor Puñosangre a Azshara.', },
  },
  [3507] = {
    '[DEPRECATED 4.x] Traición',
    {'Ve a ver a Belgrom a Orgrimmar. ¡Seguro que querrá ver la cabeza con sus propios ojos! Nosotros iremos pronto.|n|nAh, qué bien ha ido. Gracias por tu ayuda, $N.', },
    {'Habla con Belgrom Destrozarroca en Orgrimmar.', },
  },
  [3508] = {
    'Romper el amuleto',
    {'Eres imprudente, $N. Una cualidad admirable la de acometer una batalla a sabiendas de que apenas tienes posibilidades de salir $Gairoso:airosa;. Te ayudaré, aunque solo sea para ver cómo cae uno de los esbirros de Razelikh.|n|nLlevará algún tiempo romper la protección de los subordinados de Razelikh y requerirá además algunos artefactos raros.|n|nNo te muevas, primero realizaré el ritual de ilustración. La información que reúna servirá para forjar armas de gran potencia.', },
    {'Espera que Loramus acabe el hechizo de ilustración.', },
  },
  [3509] = {
    'El nombre de la bestia',
    {'Solo hay una forma de causarles daño al señor demoníaco y a sus esbirros. Un arma así de potente debe forjarse con su propio nombre inscrito en ella.|n|nCuando se forje semejante arma, el demonio y todo aquel bajo su mando serán vulnerables.|n|nEn Azshara reside una deidad menor: Lord Arkkoroc. Tienes que encontrarlo pero ándate con ojo, sus esbirros no se detendrán ante nada para destruirte si te descubren.|n|nPor supuesto, tendrás que pagar un precio por tal información.', },
    {'Habla con Lord Arkkoroc en Azshara. Empieza tu búsqueda en la orilla para encontrar el Templo de Arkkoran.', },
  },
  [3510] = {
    'El nombre de la bestia',
    {'Ella mata a mis hijos, mortal. La misma que se atribuye el dominio sobre estos océanos. Una deidad de pacotilla, eso es lo que es. Aplástala y tráeme todas sus cabezas.|n|nA cambio, te daré el nombre que buscas y algo más de igual importancia.|n|nRonda la nidada... La llaman Hetaera.|n|n<Lord Arkkoroc señala hacia el suroeste.>|n|n¡Ve!|n', },
    {'Mata a Hetaera y lleva la cabeza ensangrentada, la cabeza golpeada y la cabeza amoratada a Lord Arkkoroc.', },
  },
  [3511] = {
    'El nombre de la bestia',
    {'Lo prometido es deuda, te revelaré el nombre del señor demoníaco, Razelikh el Rapiñador. No obstante, primero debo preparar algo de vital importancia para tu viaje.|n|nEl arma que vas a crear requiere un temple especial. Dame un segundo para exprimir la sangre de estas cabezas.|n|n<Lord Arkkoroc aplasta las cabezas entre sus colosales puños y exprime la sangre de su interior.>|n|nLlévale el temple a Loramus además del nombre de la bestia: Rakh\'likh.', },
    {'Llévale el temple a Loramus Thalimedes.|n', },
  },
  [3512] = {
    'Como diría Eranikus...',
    {'$N, lo primero que debemos hacer es encontrar un modo de hablar con Eranikus a través de la gema. Él ahora se encuentra en un estado intermedio entre el sueño y la muerte, sufriendo el acoso de horripilantes pesadillas. A pesar de que la esencia que me has entregado está bastante contaminada, todavía existe una posibilidad de que podamos contactar con él.|n|nViaja a las heladas tierras del este de Cuna del Invierno y encuentra a Umbranse el Hablaalmas, uno de nuestros aliados. Es un médium humano que puede comunicarse con los muertos. Aunque Eranikus no esté muerto, puede que igualmente nos sirva de ayuda.', },
    {'Viaja a la parte este de Cuna del Invierno y habla con Umbranse el Hablaalmas.', },
  },
  [3513] = {
    'El pergamino rúnico',
    {'El pergamino con aspecto oficial está firmemente atado con un lazo plateado. Seguro que alguien estará interesado en verlo, ¿pero quién?|n|nHay una avanzada cerca de la frontera con Vallefresno hacia el norte y si la información de este pergamino tiene que ver con los elfos de la noche, este es el lugar al que se debe llevar.', },
    {'Llévale el pergamino rúnico de la torre de vigilancia norte en Los Baldíos.', },
  },
  [3514] = {
    'La presencia de la Horda',
    {'Este pergamino es de esa intrigante dríade de Rynthariel, la maestra de llaves de El Cubil del Espolón en la Cima del Espolón.|n|nYa no se pondrá en contacto con el mensajero al que le robaste esto, ja, pero debemos mantener la posición aquí. La Horda no tolerará a sus mensajeros aquí.|n|n$N, dirígete a El Cubil del Espolón. Mata a Rynthariel y deja un símbolo para que todos lo vean. Llévate esta bandera de la Horda, $N. Colócala en El Cubil del Espolón para que se lo piensen dos veces antes de enviar a otro mensajero por nuestro territorio.', },
    {'Mata a la jefa de El Cubil del Espolón, Rynthariel la Maestra de llaves.', },
  },
  [3517] = {
    'El robo de conocimientos',
    {'Lo reconozco, $N, he sacado provecho de mi situación en Azshara. Del castigo de Belgrom han resultado algunas cosas buenas.|n|nAntes de marcharme, hice algunas pesquisas y te sorprendería saber cuántos objetos valiosos hay por los alrededores.|n|nTe contaré más detalles de mis asuntos y hasta te daré una parte de los beneficios si me ayudas a recolectarlos.|n|nHay unas tablillas esparcidas por las Ruinas de Eldarath hacia el este que necesito. Son cuatro y cada una recibe el nombre de cuatro zahoríes Altonato. Consíguelas y seguiremos hablando.', },
    {'Encuentra la tablilla de Beth\'Amara, la tablilla de Jin\'yael, la tablilla de Markri y la tablilla de Sael\'hai antes de volver junto a Jediga en Azshara.', },
  },
  [3518] = {
    'Entrega a Magatha',
    {'La primera tablilla es para una tauren... una tauren llamada Magatha. Forma parte de los Ancianos Cima del Trueno y está entre los que han propuesto una alianza entre los tauren y los Renegados. Ella, más que ningún otro Anciano, piensa que los tauren y sus métodos pueden ayudar a que los Renegados encuentren una vía para volver a ser humanos.|n|nLlévale la tablilla de Beth\'Amara. Es posible que la tablilla sea lo que le permita encontrar la forma de ayudar a los Renegados... o al menos eso dice.', },
    {'Llévale la tablilla de Beth\'Amara a Magatha en Cima del Trueno.', },
  },
  [3519] = {
    'Un amigo en apuros',
    {'Uy... Me ha picado una araña llamada Gythyiss la Vil mientras exploraba la cueva de las arañas cerca de aquí. Seguro que me ha envenenado así que tienes que ayudarme.|n|nPor favor, habla con Dirania Brillargente. Ella podrá ayudarme.|n|nDate prisa... me estoy mareando...', },
    {'Habla con Dirania Brillargente en Cañada Umbría.', },
  },
  [3520] = {
    'Los espíritus de los estridadores',
    {'Busco espíritus de los estridadores del valle de Feralas. Son primos lejanos de un viejo dios y sus espíritus están unidos al suyo.|n|nCoge esta rama de zarza y ve a Feralas. Busca estridadores del valle en la zona sur y central de Feralas y derrótalos. Después agita mi rama sobre sus cuerpos para que sus espíritus se muestren. Toca el espíritu y recoge su esencia.|n|nRegresa con mi rama y con la esencia que hayas recogido y te contaré más acerca del viejo dios del que te hablé.', },
    {'Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh\'kinya al Puerto Bonvapor.', },
  },
  [3521] = {
    'Antídoto de Iverron',
    {'Estoy muy preocupada por mi amigo Iverron. Lleva fuera casi un día entero y temo que se haya envenenado... o algo peor.|n|nQuiero que reúnas los materiales para preparar un antídoto, por si acaso. Recoge champiñones jacinto, que nacen al lado de los árboles, lirios alunados, que solamente nacen cerca del agua, e icor Tejemadera, de las arañas que hay al norte.|n|nMezclarlo todo es muy fácil, incluso si está envenenado. Se dirigía hacia el norte, a la Gruta Narácnida. Espero que puedas encontrarlo.', },
    {'Reúne 7 champiñones jacinto, 4 lirios alunados y 1 icor Tejemadera.', },
  },
  [3522] = {
    'Antídoto de Iverron',
    {'El antídoto está listo, $N. Por favor, encárgate de que Iverron se lo tome.|n|nHay algo más que debes saber; el antídoto solamente será efectivo durante los próximos 5 minutos. Debes llevárselo a tiempo.|n|nEspero que lo logres, $N.', },
    {'Llévale el antídoto de Iverron a Iverron antes de que se acabe el tiempo. Lo encontrarás junto a la cueva situada al norte.', },
  },
  [3523] = {
    'La plaga de la Zahúrda',
    {'¡Fantástico! Me llamo Belnistrasz, gracias por rescatarme. Esperaba la muerte o algo peor, como servir de cena a estas alimañas infectadas de Plaga. Sí, la Plaga. Han sellado algún pacto con los jabaespines y el resultado es esta pesadilla.|n|nNo quiero limitarme a huir; quiero cambiar las cosas, por el bien de todos. ¿Quieres ayudarme? Seguro que es peligroso, pero no parece que el peligro te preocupe mucho.', },
    {'Si decides ayudar a Belnistrasz, habla con él otra vez y devuélvele la piedra de juramento.', },
  },
  [3524] = {
    'Varado',
    {'Se dice que hay unas majestuosas criaturas que van a las playas de Costa Oscura a morir encalladas. Últimamente, estas criaturas han empezado a llegar cada vez en mayor número a la costa. Yo he venido aquí a petición del Templo de la Luna para investigar el suceso, pero la gran cantidad de múrlocs que he encontrado en el agua dificulta mucho mis estudios.|n|nUna de esas gigantes criaturas llegó a la costa al sur de Auberdine para acabar rodeada de rabiosos múrlocs Bruma Gris. ¿Podrías ir a traerme algunos huesos de la criatura para que los estudie?', },
    {'Recoge huesos de la criatura marina varada que está al sur de Auberdine y llévaselos a Gwennyth Bly\'Leggonde a Auberdine.', },
  },
  [3525] = {
    'Extinguir el ídolo',
    {'Cerca de la entrada hay un ídolo que sirve de horno macabro para los jabaespines. Esas bestias consumen literalmente a quienes secuestran en Los Baldíos. Puedo cerrar el ídolo e impedir que vuelvan a usarlo, pero necesito tu ayuda. Llévame hasta el ídolo y ejecutaré mi ritual. Apenas si podré comunicarme contigo, por no hablar de defenderme. Protégeme; si me matan, será el fin para todos nosotros.|n|n¿Estás conmigo?', },
    {'Acompaña a Belnistrasz al ídolo jabaespín en Zahúrda Rajacieno. |n|nProtégelo mientras realiza el ritual para inutilizar el ídolo.', },
  },
  [3526] = {
    'Ingeniería goblin',
    {'La ingeniería avanzada se divide en dos disciplinas: la de los gnomos y la de los goblins. Claramente, la ingeniería goblin es la elección de todos los ingenieros brillantes. ¡Aprende a controlar el mundo a través del juicioso uso de potentes explosivos e increíbles aparatos!|n|n$N, lee este manual. Si quieres aprender ingeniería goblin, llévaselo a Nixx Muellepiñón que está en Gadgetzan. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!', },
    {'Si quieres saber más sobre ingeniería goblin, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón de Gadgetzan.', },
  },
  [3527] = {
    'La profecía de Mosh\'aru',
    {'La antigua profecía de Mosh\'aru cuenta el modo de encerrar la esencia del dios Hakkar. Está escrita en dos tablillas que fueron depositadas en la ciudad trol de Zul\'Farrak, al oeste de Gadgetzan.|n|n¡Tráeme las Tablillas Mosh\'aru!|n|nLa primera tablilla obra en poder de un trol difunto llamado Theka el Mártir. Se dice que sus perseguidores fueron transformados en escarabajos que ahora vagan por los alrededores de su sepulcro.|n|nLa segunda tablilla está en manos de la hidromántica Velratha, cerca de la poza sagrada de Gahz\'rilla.|n|nCuando tengas las tablillas, tráemelas.', },
    {'Llévale la primera y segunda tablillas Mosh\'aru a Yeh\'kinya, que está en Tanaris.', },
  },
  [3528] = {
    'El dios Hakkar',
    {'Ha llegado la hora de atrapar la esencia del avatar de Hakkar.|n|nLleva el huevo de Hakkar a El Sagrario del Dios Caído que se encuentra en el Templo Sumergido de Azeroth. Convoca el poder del huevo para agitar al dios muerto.|n|nÉl enviará a sus esbirros a atacarte. Derrota a sus chupasangres y extráeles su sangre Hakkari. A continuación, utiliza la sangre para apagar las llamas eternas que protegen el espíritu de Hakkar. Cuando el fuego haya sido sofocado, el avatar de Hakkar entrará en nuestro mundo.|n|nDerrótalo y coloca su esencia en el interior del huevo de Hakkar.', },
    {'Llévale el huevo de Hakkar relleno a Yeh\'kinya, que está en Tanaris.', },
  },
  [3541] = {
    'Entrega a Jes\'rimon',
    {'Tengo un perista en Orgrimmar. Reside en La Calle Mayor. No es fácil dar con él si no sabes dónde buscar pero si miras en uno de los edificios más altos, no deberías tardar en encontrarlo.|n|nAunque hazme un favor, no vayas pregonando por todo Kalimdor que está allí y a qué se dedica, sería perjudicial para ambos.|n|nTe dará un precio más que correcto por la tablilla de Jin\'yael. No sé muy bien por qué pero deberías haber visto lo nervioso que se puso cuando supo su paradero.', },
    {'Envía la tablilla de Jin\'yael a Jes\'rimon en Orgrimmar.', },
  },
  [3542] = {
    'Entrega a Andron Gant',
    {'Andron Gant es mi siguiente contacto. Suele andar por Entrañas... al ladito de El Apothecarium.|n|nTenía la lengua algo más suelta cuando se trataba de hablar de para qué quería la tablilla. Al parecer, algunos de los magos de Entrañas están estudiando algunos hechizos arcanos que los Altonato usaban. Piensan que esta tablilla los ayudará. Markri era un adepto a los conjuros de criaturas, sobre todo los elementales.|n|nLleva la tablilla de Markri y vuelve aquí para tu parte de la recompensa.', },
    {'Llévale la tablilla de Markri a Andron Gant en Entrañas.', },
  },
  [3561] = {
    'Entrega al archimago Xylem',
    {'Esta última tablilla es para alguien muy peligroso, $N. Créeme cuando te digo que confío menos en esta persona que en cualquiera de los otros a los que te he pedido que vayas a ver.|n|nEl archimago Xylem tiene una torre en las colinas que se elevan junto a Azshara. Es humano pero no se comporta como los humanos que he conocido... o matado. Exuda poder y no oso preguntarle cuáles son sus intenciones con la tablilla.|n|nVino a mi encuentro pero me dijo que su guardaespaldas Sanath me ayudaría a llegar a la torre cuando estuviera listo para verle. Busca a Sanath hacia el norte.', },
    {'Llévale la tablilla de Sael\'hai al archimago Xylem en Azshara.', },
  },
  [3562] = {
    '[DEPRECATED]El pago de Magatha a Jediga',
    {'Llévale esta nota a Jediga. Dile que el pago estará aquí para ella cuando regrese. Y dile que estoy satisfecha con su trabajo.|n|nCorre, $N. Dile a tu maestra que estaré esperándola aquí.', },
    {'Entrega la nota de Magatha a Jediga en Azshara.', },
  },
  [3563] = {
    'El pago de Jes\'rimon a Jediga',
    {'Lleva esta carta a Jediga. Dile que nuestro trato ha sido provechoso y que estoy satisfecho con su trabajo.|n|nDile que regrese rápidamente a Orgrimmar y que Jes\'rimon se asegurará de cuidar bien de ella.|n|nDile eso, y quizás en el futuro ya no necesitaré tus servicios otra vez, $N.', },
    {'Entrega la nota de Jes\'rimon a Jediga en Azshara.', },
  },
  [3564] = {
    'El pago de Andron a Jediga',
    {'Ahí va... lleva... (hic) esto a Jediga. ¡Que te vaya daguten!', },
    {'Entrega la nota de Andron a Jediga en Azshara.', },
  },
  [3565] = {
    'El pago de Xylem a Jediga',
    {'¡¿Qué ocurre?! Ah sí, tu pago. Desde luego.|n|nToma esto y hasta luego. Seguro que Jediga aguarda con santa paciencia tu regreso.', },
    {'Entrega la nota de Xylem a Jediga en Azshara.', },
  },
  [3566] = {
    '¡Arriba, Obsidion!',
    {'Era una trampa...|n|nPerdóname.|n|nMata a ese traidor. Hazlo por nosotros... Por Thorius.', },
    {'Lleva la cabeza de Lathoric el Negro y el corazón de Obsidion a Torio a Forjaz.', },
  },
  [3567] = {
    'A la cima',
    nil,
    nil,
  },
  [3568] = {
    'La filtración de la corrupción',
    {'¿Ves a la tauren que se encuentra detrás de mí, la que parece que va a estirar la pata de un momento a otro? Hace poco estuvo en Azshara. Afirma que unos nagas la hirieron cuando atravesaba las Ruinas de Eldarath.|n|nTras su enfrentamiento con ellos, se tomó un descanso en la playa y bebió de una de las pozas de las mareas. Ahora tiene náuseas... entre otros síntomas.|n|nMe gustaría descubrir qué ha bebido. Coge esta caja que contiene algunos viales vacíos que he etiquetado. Recoge muestras en las distintas pozas y regresa aquí.', },
    {'Llena los 4 viales vacíos en las pozas de las mareas que se encuentran a lo largo de la costa de las Ruinas de Eldarath en Azshara y después ve a ver al químico Cuely.', },
  },
  [3569] = {
    'La filtración de la corrupción',
    {'Dale esto a Thersa. Quizás la cure... o quizás no. No lo sabremos hasta que se lo tome.', },
    {'Dale el elixir de Cuely a Thersa Son del Viento, que está en Entrañas.', },
  },
  [3570] = {
    'La filtración de la corrupción',
    nil,
    nil,
  },
  [3581] = {
    nil,
    {'Imagínate corriendo por las llanuras, a través de los bosques y por las montañas, el viento azota tu cara... Viajando por territorios vírgenes; la maravilla del camino por recorrer, tu destino esperándote a la vuelta del horizonte.|n|nRecuerda siempre que a pie, se pueden conseguir muchas cosas; como un tauren, se te concederá la presteza de correllanuras. No hay límites a las distancias que podrás recorrer.', },
    {'Habla de nuevo con Saern Correorgullo para aprender la habilidad de los correllanuras.', },
  },
  [3601] = {
    '¡Kim\'jael, claro!',
    {'¡¡Kim\'jael, claro!! ¿Sabes lo que significa Kim\'jael para los elfos de sangre, $N? Ratita... o algo parecido. ¡Abusones!|n|nMe contrataron para que los ayudara a rastrear el área en busca de algún tipo de tesoro perdido. Por supuesto, no me lo pensé un momento cuando mencionaron el "tesoro" y el dinero que me iban a pagar pero claro, se volvieron contra mí e intentaron matarme... ¡A MÍ!|n|nToma prueba, un elfo de sangre no es de fiar.|n|nEl problema es que aún tienen mi equipo y no puedo recuperarlo. ¿Me ayudas?', },
    {'Busca en el Campamento base thalassiano la brújula de Kim\'jael, la mira, el pollo relleno y el cachivache y llévaselo todo a Azshara.', },
  },
  [3602] = {
    'Azsharita',
    {'Los ancianos gigantes de los acantilados al sur de la región de Azshara se alimentan de las rocas y de las edificaciones. El excremento resultante es un material altamente maleable, un cristal de increíble resistencia conocido como azsharita.|n|nEstas formaciones abundan en el arco sur pero rara vez se recuperan debido a la naturaleza de los gigantes es extremadamente violenta.|n|nHas de dirigirte al sur y recuperar suficiente azsharita para crear el cuerpo de la herramienta. Mis canes manáfagos te ayudarán a conseguir el cristal.', },
    {'Recupera 20 azsharitas cristalizadas del sur de Azshara. Puede que encuentres canes manáfagos dispuestos a ayudarte a rastrear la ubicación de los depósitos hábilmente escondidos.|n|nVuelve con Loramus cuando hayas completado la tarea.|n', },
  },
  [3621] = {
    'La formación de Aterravil',
    {'Las armas están listas para ser forjadas. Debes lograr que la azsharita adquiera un temple con potencia para dañar la energía vil.|n|nEn la Vega de Tuercespina encontrarás al herrero a la altura de esta tarea. Galvan el Antiguo, jefe de la Orden del mitril, fabricará las armas como tú se lo encargues. Encontrarás su campamento entre Zul\'Gurub y el Túmulo Ogro Mosh\'Ogg.|n|nQue tu determinación y fe te acompañen en tu odisea. Si fracasas, ten la certeza de que cuentas con el orgullo de tu dios, mortal.', },
    {'Llévale el envío a Galvan el Antiguo en la Vega de Tuercespina.', },
  },
  [3625] = {
    'Armas Fel en Azsharita encantada',
    {'$N, llevará un tiempo crear cada arma.|n|nAdemás, solo puedes usar el poder del Vilhechizo un minuto de cada tres. Sus propiedades debilitadoras contra Razelikh el Rapiñador y sus esbirros pueden tener una duración variable. ¡Por eso debes utilizar el Vilhechizo en el momento justo!|n|nAhora dame un momento para fabricarte el arma, $N.|n', },
    {'Espera que Galvan acabe de forjar las armas.', },
  },
  [3626] = {
    'Regresa a Las Tierras Devastadas',
    {'Se acerca la hora de la redención, $N. Debes regresar a Las Tierras Devastadas con tus nuevas armas y hablar con el héroe caído de la Horda, él te indicará tu objetivo final.|n', },
    {'Vuelve junto al héroe caído de la Horda en el Cruce Lanzarrota, en el Pantano de las Penas.', },
  },
  [3627] = {
    'Juntar pedazos del amuleto',
    {'Para llegar hasta el Rapiñador, antes debes destruir la tríade de poderes y recuperar las piezas del amuleto. Cuando hayas recuperado las tres piezas, vuelve aquí y te daré el resto de las instrucciones.|n|n¡Vete, $N! ¡A Las Tierras Devastadas! ¡Sevine, Allistarj y Grol deben caer!|n', },
    {'Mata a Grol el Destructor, a Lady Sevine y al archimago Allistarj. De sus cadáveres coge el amuleto de Grol, el amuleto de Sevine y el amuleto de Allistarj.|n|nAcuérdate de USAR tus armas viles de azsharita encantada para debilitar a la tríade. Es la única forma de matarlos, pero úsalas con moderación...|n', },
  },
  [3628] = {
    'Eres Rakh\'likh, demonio',
    {'La guarida de Razelikh está en la cima de la montaña más alta de Las Tierras Devastadas. La única forma de acceder es mediante las runas de teletransporte próximas a la montaña. Siempre que tengas el amuleto, podrás teletransportarte sin problemas hasta la guarida. Cuando llegues allí, debes invocar a la bestia. La clave está en el amuleto, $N. Utilízalo en el Altar de los Rapiñadores.|n|nSi logras derrotar al Rapiñador, tráeme su cuerno. Se convertirá en un símbolo de esperanza para quien lo vea, una prueba de que existen héroes en este mundo desgarrado por la guerra.|n', },
    {'Destruye a Razelikh el Rapiñador y llévale el cuerno de Rapiñador cortado al héroe caído de la Horda. También tendrás que devolver el Resguardo del Rapiñador para que el héroe caído pueda destruirlo y así impedir que caiga en las manos equivocadas.|n', },
  },
  [3629] = {
    'Ingeniería goblin',
    {'La ingeniería avanzada se divide en dos disciplinas: la de los gnomos y la de los goblins. Menciono a los goblins puramente porque existen. Les gustan las cosas que explotan y les da igual quién esté en medio, aun ellos mismos.|n|nLéete este manual, $N. Si quieres hacerte saltar por los aires, ve a ver a Nixx Muellepiñón en Gadgetzan. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!', },
    {'Si quieres saber más sobre ingeniería goblin, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón de Gadgetzan.', },
  },
  [3630] = {
    'Ingeniería gnómica',
    {'En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. ¡La ingeniería de los gnomos es mejor con diferencia! Se concentra en la creación de aparatos e instrumentos que hacen la vida más fácil.|n|nLéete este manual, $N. Si quieres saber más sobre el tema, llévaselo aI maestro manitas Sobrechispa, en Forjaz. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!', },
    {'Si quieres saber más sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería al maestro manitas Sobrechispa en Forjaz.', },
  },
  [3631] = {
    'Invoca un corcel vil',
    {'Bah. Creo que no estás a punto, pero no soy yo quien decide. Strahad piensa lo contrario, así que haremos lo que quiere... por esta vez.|n|nQuiere hablar contigo lo antes posible. Estará en su torre con sus acólitos, más allá de Trinquete, en Los Baldíos.|n|nNo te entretengas por el camino.', },
    {'Habla con Strahad Farsan en Los Baldíos.', },
  },
  [3632] = {
    'Ingeniería gnómica',
    {'En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. ¡La ingeniería de los gnomos es mejor con diferencia! Se concentra en la creación de aparatos e instrumentos que hacen la vida más fácil.|n|nLéete este manual, $N. Si quieres saber más sobre el tema, llévaselo aI maestro manitas Sobrechispa, aquí en Forjaz. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!', },
    {'Si quieres saber más sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería al maestro manitas Sobrechispa en Forjaz.', },
  },
  [3633] = {
    'Ingeniería goblin',
    {'La ingeniería avanzada se divide en dos disciplinas: la de los gnomos y la de los goblins. Claramente, la ingeniería goblin es la elección de todos los ingenieros brillantes. ¡Aprende a controlar el mundo a través del juicioso uso de potentes explosivos e increíbles aparatos!|n|n$N, lee este manual. Si quieres aprender ingeniería goblin, llévaselo a Nixx Muellepiñón que está en Gadgetzan. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!', },
    {'Si quieres saber más sobre ingeniería goblin, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón de Gadgetzan.', },
  },
  [3634] = {
    'Ingeniería gnómica',
    {'En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. Aunque yo piense que no sirve para nada, deberías de estar al corriente de la especialización de los gnomos. Crean objetos y aparatos que piensan van a cambiar el mundo, pero que raras veces funcionan.|n|n$N, lee este manual. Si deseas aprender a hacer pisapapeles metálicos, lleva el manual aI maestro manitas Sobrechispa que está en Forjaz. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!', },
    {'Si quieres saber más sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería al maestro manitas Sobrechispa en Forjaz.', },
  },
  [3635] = {
    'Ingeniería gnómica',
    {'En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. Aunque yo piense que no sirve para nada, deberías de estar al corriente de la especialización de los gnomos. Crean objetos y aparatos que piensan van a cambiar el mundo, pero que raras veces funcionan.|n|n$N, lee este manual. Si deseas aprender a hacer pisapapeles metálicos, lleva el manual a Oglethorpe Obnoticus que está en Bahía del Botín. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!', },
    {'Si quieres aprender más cosas sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería a Oglethorpe Obnoticus en Bahía del Botín.', },
  },
  [3636] = {
    'Trae la Luz',
    {'La Plaga es una amenaza constante para la Alianza, lo cual no es nada nuevo. Hace poco, nos topamos con unos hallazgos muy peculiares, $N.|n|nEn los Baldíos existe un laberinto de púas llamado Zahúrda Rajacieno. Solía ser el hogar de jabaespines, pero ahora parece ser que han hecho algún tipo de pacto con la Plaga, creando criaturas mucho peores... Las gobierna el exánime Amnennar el Gélido.|n|nÚnete a la Luz, $N, y acaba con tal pacto.', },
    {'El arzobispo Benedictus quiere que mates a Amnennar el Gélido en Zahúrda Rajacieno.', },
  },
  [3637] = {
    'Ingeniería gnómica',
    {'En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. Aunque yo piense que no sirve para nada, deberías de estar al corriente de la especialización de los gnomos. Crean objetos y aparatos que piensan van a cambiar el mundo, pero que raras veces funcionan.|n|n$N, lee este manual. Si deseas aprender a hacer pisapapeles metálicos, lleva el manual a Oglethorpe Obnoticus que está en Bahía del Botín. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!', },
    {'Si quieres aprender más cosas sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería a Oglethorpe Obnoticus en Bahía del Botín.', },
  },
  [3638] = {
    'La promesa del secreto',
    {'La ingeniería goblin persigue que sus creaciones tengan una aplicación práctica real y un poder explosivo aún mayor. Nuestros esquemas nos permiten fabricar potentes bombas y un poderoso armamento. En el manual que has leído se explica todo.|n|nEn él también se cita el juramento que hace mucho tiempo hicimos de mantener nuestros esquemas en secreto. Si decides dedicarte a la ingeniería goblin, ya está. No tendrás acceso de ningún tipo a la ingeniería de los gnomos.|n|nSi aun así sigues queriendo convertirte en un ingeniero goblin, firma este compromiso de secreto perpetuo y vuelve a hablar conmigo. Piénsatelo muy bien, $N.', },
    {'Si decides dedicarte a la ingeniería goblin, haz clic con el botón derecho del ratón en el compromiso de secreto perpetuo y habla de nuevo con Nixx Muellepiñón de Gadgetzan.', },
  },
  [3639] = {
    'Muestra tu trabajo',
    {'El brillo de tus ojos lo dice todo; quieres reventar cosas. Tienes talento en ciernes, $N. Sin embargo, quiero muestras de tu trabajo para poder examinarlas y ver si te puedo orientar hacia técnicas más propias de la ingeniería de los goblins. Necesito lo siguiente: 20 bombas de hierro grandes, 20 cartuchos de dinamita sólida y 5 ovejas explosivas. ¡Y mantente alerta!|n|n¡Entrégame todo esto y serás $Gun ingeniero:una ingeniera; goblin oficial!', },
    {'Llévale 20 bombas grandes de hierro, 20 cartuchos de dinamita sólida y 5 ovejas explosivas a Nixx Muellepiñón de Gadgetzan.', },
  },
  [3640] = {
    'La promesa del secreto',
    {'La ingeniería de los gnomos pone la teoría de la ingeniería al servicio de nuestras necesidades. Nuestros sistemas nos permiten fabricar instrumentos que controlan el mundo que nos rodea. El manual que has leído habla de eso.|n|nTambién explica que juramos mantener nuestros planos en secreto. Cuando te conviertas en $Gun ingeniero:una ingeniera; gnomo, claro está. No podrás leer nada sobre la ingeniería goblin.|n|nSi ya te has decidido, firma este compromiso de secreto perpetuo y vuelve a hablar conmigo. Piénsatelo muy bien, $N.', },
    {'Si decides dedicarte a la ingeniería gnómica, haz clic con el botón derecho del ratón en el compromiso de secreto perpetuo y habla de nuevo con el maestro manitas Sobrechispa en Forjaz.', },
  },
  [3641] = {
    'Muestra tu trabajo',
    {'Si lo que quieres es crear aparatos fantásticos, has venido al lugar adecuado. Puedo ver tu destreza en ingeniería, pero quiero algunas muestras de tu trabajo. Me gustaría ver si te puedo orientar hacia técnicas más gnómicas para el futuro. Necesito lo siguiente: 6 tubos de mitril, una mira de precisión y 2 muñecos-diana avanzados.|n|n¡Dame todo esto y te convertirás en $Gun ingeniero gnómico:una ingeniera gnómica; con acceso a todos los esquemas!', },
    {'Lleva 6 tubos de mitril, una mira de precisión y 2 muñecos-diana avanzados al maestro manitas Sobrechispa a Forjaz.', },
  },
  [3642] = {
    'La promesa del secreto',
    {'La ingeniería de los gnomos pone la teoría de la ingeniería al servicio de nuestras necesidades. Nuestros sistemas nos permiten fabricar instrumentos que controlan el mundo que nos rodea. El manual que has leído habla de eso.|n|nTambién explica que juramos mantener nuestros planos en secreto. Cuando te conviertas en $Gun ingeniero:una ingeniera; gnomo, claro está. No podrás leer nada sobre la ingeniería goblin.|n|nSi ya te has decidido, firma este compromiso de secreto perpetuo y vuelve a hablar conmigo. Piénsatelo muy bien, $N.', },
    {'Si decides dedicarte a la ingeniería gnómica, haz clic con el botón derecho del ratón en el compromiso de secreto perpetuo y habla de nuevo con Oglethrope Obnoticus en Bahía del Botín.', },
  },
  [3643] = {
    'Muestra tu trabajo',
    {'Si lo que quieres es crear aparatos fantásticos, has venido al lugar adecuado. Puedo ver tu destreza en ingeniería, pero quiero algunas muestras de tu trabajo. Me gustaría ver si te puedo orientar hacia técnicas más gnómicas para el futuro. Necesito lo siguiente: 6 tubos de mitril, una mira de precisión y 2 muñecos-diana avanzados.|n|n¡Dame todo esto y te convertirás en $Gun ingeniero gnómico:una ingeniera gnómica; con acceso a todos los esquemas!', },
    {'Lleva 6 tubos de mitril, 1 mira de precisión y 2 muñecos-diana avanzados a Oglethorpe Obnoticus en la Bahía del Botín.', },
  },
  [3644] = {
    'Renovación de la tarjeta de miembro',
    nil,
    nil,
  },
  [3645] = {
    'Renovación de la tarjeta de miembro',
    nil,
