  [4449] = {
    'Atrapado',
    {'¡Eh! ¡Oye, tú! ¡Ven aquí!|n|nAyúdame. Me escondí aquí para huir de los Hierro Negro. ¡Malditos sean los geólogos y sus trucos mágicos! Supongo que me vieron entrar y bloquearon la puerta.|n|n¡Dales una lección! Ah, y tráeme unos cuantos paños de seda para... Esto, para... Para nada.', },
    {'Mata a 8 geólogos Hierro Negro y lleva 15 paños de seda a la persona encerrada en las letrinas de La Garganta de Fuego.', },
  },
  [4450] = {
    'El libro de contabilidad de Tanaris',
    {'Ah, ahora que me acuerdo:|n|n¿quieres acabar un trabajito que acepté en Tanaris? Es fácil...|n|nKrinkle Buenacero, de Gadgetzan, anda buscando unos objetos en La Garganta de Fuego y otros sitios. ¿Qué tal si te encargas tú?|n|nSi te interesa, te pasaré su libro de contabilidad por debajo de la puerta. Dáselo a Buenacero cuando vayas a llevarle los objetos.', },
    {'Coge el libro de contabilidad de Buenacero y busca los objetos de la lista antes de ir a verlo a Tanaris.', },
  },
  [4451] = {
    'La llave de la libertad',
    {'Esta pequeña llave de latón es muy sencilla. Lo único que destaca es un grabado:|n|n"Letrina Hierro Negro. No hacer copia."|n|nNo tienes ni idea de qué significa o qué abre.', },
    {'Busca en La Garganta de Fuego para ver cómo se usa la llave de la letrina de Limugre.', },
  },
