  [7401] = {
    'Se buscan: ¡ENANOS!',
    {'Por orden del sargento Yazra Gruñido Sangriento, todos los enanos del campo de batalla han de ser ejecutados en el acto.|n|nSi das muerte a un enano en combate, arráncale la espina dorsal, dejando un putrefacto y hediondo montón sin espina que sirva de advertencia a todo aquel que ose oponerse al poder de los Lobo Gélido.|n|nTráele al sargento Yazra Gruñido Sangriento la prueba de tu hazaña.', },
    {'Se te asignado la tarea de matar a los jugadores enanos en el Valle de Alterac.|n|nMata a un enano y sácale la espina dorsal. Llévasela al sargento Yazra Gruñido Sangriento en el Bastión Lobo Gélido.', },
  },
  [7402] = {
    'Se buscan: ¡ORCOS!',
    {'Por orden del cabo Noreg Pico Tormenta, se exige de todos los soldados Pico Tormenta sanos que maten a todo orco que muestre oposición en el campo de batalla.|n|nLos soldados deberán llevarse un colmillo o un diente de las fauces del enemigo y presentar dicho diente como prueba de haber cumplido.|n|nLlevar guantes protectores.', },
    {'Se te asignado la tarea de matar a los jugadores orcos en el Valle de Alterac.|n|nMata a un orco y llévale un colmillo de la víctima al cabo Noreg Pico Tormenta en Dun Baldar.', },
  },
