  [7810] = {
    'Maestro de arena',
    {'¡Ser un maestro de la arena tiene que ser algo más que esto! ¡Quizás lo sepa el pirata que lleva el evento en Gurubashi!', },
    {'Habla con Corto John Mitril en la Arena de la Vega de Tuercespina.', },
  },
