  [7815] = {
    '¡Quijafortes, colega!',
    {'¡No te fíes de su jeta! Los quijafortes marinos son peligrosos. Cada cinco minutos viene uno de esos aspiradores acuáticos y me arranca el cebo.|n|nHaz un favor a todo el Poblado Sañadiente y acaba con ellos.|n|n¡No dejes ni uno!', },
    {'Katoom el Pescador, del Poblado Sañadiente en las Tierras del Interior, quiere que mates 10 quijafortes marinos. Ve a verlo cuando hayas terminado.', },
  },
  [7816] = {
    '¡Gammerita, colega!',
    {'¡Eh! Hay una tortuga que no es como las otras. Es Gammerita, la jefa de los quijafortes marinos; una condenada ladrona también es.|n|nSe llevó mi mejor cebo. ¡Lo mordió y se lo llevó! Desde entonces, pican menos.|n|nBusca a Gammerita y sácale mi cebo del estómago.', },
    {'Katoom el Pescador, del Poblado Sañadiente en las Tierras del Interior, quiere que mates a Gammerita y que le saques el cebo del estómago.|n|nDijo que Gammerita está en la costa con las otras tortugas.', },
  },
