  [7905] = {
    'La Feria de la Luna Negra',
    {'¡La Feria de la Luna Negra está al caer! ¡No te pierdas nuestros emocionantes juegos, gana premios increíbles y averigua qué te depara el futuro!|n|nSi te decides, ¡puedes canjear este cupón por vales gratuitos y una copia de la mundialmente famosa guía de campo de la Luna Negra para que te ayude a identificar los tesoros que te encuentres en tus viajes!|n|nLlévale el cupón a Gelvas Roñoso dentro de la feria.|n|nAhora mismo, la feria se encuentra a las afueras de Villadorada, en el Bosque de Elwynn.', },
    {'Entrega el vale de entrada gratuita a Gelvas Roñoso en la Feria de la Luna Negra.', },
  },
  [7906] = {
    'Cartas de la Luna Negra: bestias',
    nil,
    nil,
  },
  [7907] = {
    'La baraja de Bestias de la Luna Negra',
    {'Ahora que has reunido todos los naipes de la baraja de Bestias, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: "Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.', },
    {'Lleva la baraja de Bestias a la Feria de la Luna Negra cuando pase por la ciudad.', },
  },
  [7908] = {
    'Maestro de arena',
    {'¡Ser un maestro de la arena tiene que ser algo más que esto! ¡Quizás lo sepa el pirata que lleva el evento en Gurubashi!', },
    {'Habla con Corto John Mitril en la Arena de la Vega de Tuercespina.', },
  },
  [7926] = {
    'La Feria de la Luna Negra',
    {'¡La Feria de la Luna Negra está al caer! ¡No te pierdas nuestros emocionantes juegos, gana premios increíbles y averigua qué te depara el futuro!|n|nSi te decides, ¡puedes canjear este cupón por vales gratuitos y una copia de la mundialmente famosa guía de campo de la Luna Negra para que te ayude a identificar los tesoros que te encuentres en tus viajes!|n|nLlévale el cupón a Gelvas Roñoso dentro de la feria.|n|nAhora mismo, la feria se encuentra en Cima del Trueno, en Mulgore.', },
    {'Entrega el vale de entrada gratuita a Gelvas Roñoso en la Feria de la Luna Negra.', },
  },
  [7927] = {
    'La baraja de Portales de la Luna Negra',
    {'Ahora que has reunido todos los naipes de la baraja de Portales, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: "Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.', },
    {'Lleva la baraja de Portales a la Feria de la Luna Negra cuando pase por la ciudad.', },
  },
  [7928] = {
    'La baraja de Señores de la Guerra de la Luna Negra',
    {'Ahora que has reunido todos los naipes de la baraja de Señores de la Guerra, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: "Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.', },
    {'Lleva la baraja de Señores de la Guerra a la Feria de la Luna Negra cuando pase por la ciudad.', },
  },
  [7929] = {
    'La baraja de Elementales de la Luna Negra',
    {'Ahora que has reunido todos los naipes de la baraja de Elementales, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: "Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.', },
