  [7944] = {
    'La Fortuna te espera...',
    {'"La Fortuna te espera en las Cuevas de los Lamentos."|n|nEl papelito de la Fortuna que te dio Sayge está caliente. Cuando lo aprietas, ves una imagen de una cueva al suroeste de El Cruce, en Los Baldíos. Te acercas más y te encuentras moviéndote a gran velocidad por unos enrevesados pasadizos hasta que llegas a un resplandeciente portal que lleva al mismísimo corazón de la cueva. Cuando lo cruzas, aparece de la nada un extraño cofre.', },
    {'Ve a las Cuevas de los Lamentos de Los Baldíos y busca tu fortuna.', },
  },
  [7945] = {
    'La Fortuna te espera...',
    {'"La Fortuna te espera fuera de la Roca Crines Pálidas."|n|nEl papelito de la Fortuna que te dio Sayge está caliente. Cuando lo aprietas, ves una imagen de la Roca Crines Pálidas de Mulgore. Te acercas más y ves un tocón de árbol al lado de la entrada de la cueva.', },
    {'Ve a la Roca Crines Pálidas de Mulgore y busca tu fortuna.', },
  },
