  [8227] = {
    'Cinta métrica de Nat',
    {'Entre los cebos y aparejos de pesca hay una cinta métrica de seda, enrollada. Unida a ella hay una etiqueta que dice:|n|n"Nat Pagle, Marjal Revolcafango."', },
    {'Devuelve la Cinta métrica de Nat a Nat Pagle en el Marjal Revolcafango.', },
  },
