  [8380] = {
    'Armamentos de guerra',
    nil,
    nil,
  },
  [8381] = {
    'Armamentos de guerra',
    nil,
    nil,
  },
  [8382] = {
    'Armamentos de guerra',
    nil,
    nil,
  },
  [8409] = {
    'Los barriles dañados',
    {'Has conseguido meter los huevos podridos en los barriles. ¡Sin duda se arruinarán muchas partidas de cerveza en la Taberna Costasur!|n|nAhora debes ir a ver a la clamasombras Yanka al Festival del Hombre de Mimbre en los Claros de Tirisfal e informarle de tu éxito.', },
    {'Ve a ver de nuevo a la clamasombras Yanka, que está en el Festival del Hombre de Mimbre en los Claros de Tirisfal.', },
  },
  [8410] = {
    'Maestría elemental',
    {'Bath\'rah el Vigía del viento ha reclamado un chamán de tu sabiduría. Pide que lleves contigo una muestra de cada uno de los elementos para mostrar que estás $Gpreparado:preparada;.|n|nPara encontrar a Bath\'rah dirígete al río al este del Molino Tarren. Sigue el río hacia el Norte, hasta que des con las ruinas en las que vive Bath\'rah.', },
    {'Recoge una muestra de aire, fuego, tierra y agua para Bath\'rah el Vigía del viento.', },
  },
  [8411] = {
    '[DEPRECATED]Dominar los elementos',
    {'Me alegro de verte, $C. Tráeme los elementos y luego hablamos.|n|nEl fuego, el aire, el agua y la tierra, m\'harán falta pa\' confiar en ti, colega. Tengo qu\'asegurarme qu\'eres $Gun entendido:una entendida;.', },
    {'Lleva los elementos tierra, aire, fuego y agua a Bath\'rah el Vigía del viento.', },
  },
  [8412] = {
    '[DEPRECATED]Tótem de espíritu',
    {'Ya no les gusto a los espíritus elementales de este lugar.|n|nTú sabes de los tótems más que nadie y yo necesito un tótem de espíritu que me proteja. Ya tenemos los elementos y necesitamos algo más de Naturaleza. Más primigenio.|n|nEn las Tierras de la Peste del Oeste podrás encontrar osos para quitarles las garras y arañas para quitarles los ojos. Los pájaros carroñeros comen de todo, así que seguro que también tendrán algo de eso adentro.', },
    {'Lleva lo necesario para el tótem del espíritu a Bath\'rah el Vigía del viento.', },
  },
  [8413] = {
    'Vudú',
    {'El tótem de espíritu no alcanza. Vamos a necesitar un poco de magia vudú.|n|nLos trols del Templo Sumergido tienen plumas mágicas muy poderosas. Debes ir allí y matar a Gasher, Mijan, Zolo, Hukku, Zul\'lor y Loh\'ro. Entonces tendremos suficiente magia para un verdadero tótem de espíritu.', },
    {'Lleva las plumas vudú a Bath\'rah el Vigía del viento.', },
  },
  [8414] = {
    'Expulsión de los demonios',
    {'Saludos, $C. Los cruzados como tú siempre son bienvenidos en esta tierra desolada.|n|nTu sagrada fuerza es necesaria para combatir al número infinito de no-muertos. Necesitamos que reúnas un gran número de piedras de la Plaga y que las entregues al sumo sacerdote Thel\'danis. Podrás encontrarlo custodiando la Tumba de Uther en la Colina de las Penas, no lejos de aquí.|n|nSolo quien lleve una Comisión de El Alba Argenta podrá encontrar piedras de la Plaga, así que habla con la oficial Purocorazón si aún no tienes ninguna.', },
    {'Recoge 20 piedras de la Plaga del esbirro y entrégaselas al sumo sacerdote Thel\'danis en las Tierras de la Peste del Oeste.', },
  },
  [8415] = {
    'Campamento del Orvallo',
    {'El comandante Ashlam Puñovalor ha hecho un llamamiento en busca de un paladín de tu pureza y valor, $N. Podrás encontrarle en el Campamento del Orvallo, en la parte meridional de las Tierras de la Peste del Oeste. ¡Búscalo y contribuye a su causa en defensa de la Luz!', },
    {'Habla con el comandante Ashlam Puñovalor en el Campamento del Orvallo.', },
  },
  [8416] = {
    'Piedras de la Plaga inertes',
    {'Las piedras han purgado el mal, $N.|n|nConozco los planes del comandante Ashlam y solo necesitará una piedra inerte. Llévasela y podremos purificar a la Plaga en el fuego de los justos.', },
    {'Lleva la piedra de la Plaga inerte al comandante Ashlam Puñovalor en el Alto del Orvallo.', },
  },
  [8417] = {
    'Un espíritu afligido',
    {'En Las Tierras Devastadas habita un espíritu preocupado que fue un día un gran héroe de la Horda. El honor de un guerrero no perece con su cuerpo, debería serte de ayuda hablar con él.', },
    {'Habla con el héroe caído de la Horda en la entrada de Las Tierras Devastadas.', },
  },
  [8418] = {
    'La forja de la piedra de poderío',
    {'Ahora tenemos que combinar las piedras de la Plaga inertes y crear un arma que destroce las filas de no-muertos. No es una tarea sencilla, $N. Solo los trols del Templo Sumergido son portadores del tipo de extraña magia que puede convertir el mal en algo contrario a sí mismo.|n|nLos trols del Templo son conocidos como Gasher, Mijan, Zolo, Hukku, Zul\'lor y Loh\'ro. No sientas ningún remordimiento por sus corruptas almas... no están libres de mal.', },
    {'Obtén plumas vudú ámbar, azules y verdes de los trols del Templo Sumergido.', },
  },
  [8419] = {
    'Pedido de un diablillo',
    {'$N, un diablillo de Frondavil, llamado Diblis, ha solicitado tu presencia. Es algo extraño, pidió que llevaras contiguo una pieza de tela vil como símbolo de tu buena fe. Teniendo en cuenta tu poder como brujo supongo que ya sabrás que los sátiros de Frondavil llevan consigo telas viles.|n|nEncontrarás a Diblis al norte de las Cascadas del Veneno, un lugar realmente encantador en esta época del año.', },
    {'Lleva un retal de tela vil a Diblis a Frondavil.', },
  },
  [8420] = {
    'Caliente y picante',
    {'Puede que suene extraño viniendo de un diablillo, pero quiero tener una mascota. Me encantaría tener una. ¡No es justo que Niby me tenga a mí y yo no tenga nada!|n|nNi siquiera tiene que ser una mascota viva. Solo necesito algo para empezar a hacer una, como una tela vil. Los sátiros de Frondavil a veces tienen tela vil. Solo tendrás que ir matando a los que encuentres hasta que consigas una. No está mal el plan, ¿verdad?', },
    {'Lleva un retal de tela vil a Diblis a Frondavil.', },
  },
  [8421] = {
    'La mercancía equivocada',
    {'Ahora que tengo mi tela vil, puedo empezar a hacer mi mascota.|n|nPero va a necesitar unos ojos... Quizás puedas robar un poco de madera podrida de los Troncoferro, para que pueda tallarle unos bonitos ojos. Están al norte, en el Bosque de Troncoferro.|n|nY también necesitaré un poco de esencia de veneno para que tenga olorcillo a demonio. Los mocos corruptos tienen esa esencia. Suelen estar por aquí, cerquita de Niby y de mí.', },
    {'Lleva 10 maderas putrefactas y 4 esencias de veneno a Diblis a Frondavil.', },
  },
  [8422] = {
    'Plumas de trol',
    {'Casi he acabado mi mascota. Ahora necesito algo para rellenarla.|n|nY solo pueden ser plumas vudú de los trols del Templo Sumergido. Se llaman Gasher, Mijan, Zolo, Hukku, Zul\'lor y Loh\'ro. Mátalos. Mátalos a todos.|n|nNo será tarea fácil, $N, pero haré que te merezca la pena correr el riesgo. Te daré una cosa de Niby... no creo que vaya a necesitarla de todas formas.', },
    {'Reúne un total de 6 plumas vudú en el Templo Sumergido.', },
  },
  [8423] = {
    'Parentesco guerrero',
    {'<El Héroe te mira detenidamente.>|n|nEres $Gun:una; $C, vaya si lo eres. Te encargaría una tarea honorable pero primero debo poner a prueba tu fuerza.|n|nDicen que Rexxar mide el filo de sus espadas matando a un jabinferno de un solo sablazo. Así que mediré la fuerza que tienes por cómo los matas.', },
    {'Mata a 7 jabinfernos de Las Tierras Devastadas y vuelve junto al héroe caído de la Horda.', },
  },
  [8424] = {
    'La guerra contra los Sombra Jurada',
    {'La continuada presencia de los Sombra Jurada en Las Tierras Devastadas me entristece sobremanera. Sus oscuros rituales y hechizos causan agonía como nada que yo sufriera en vida.|n|nA través de ti puedo enviar mi mensaje de dolor. Adelante y transmíteles mi ira.', },
    {'Acaba con los Sombra Jurada en Las Tierras Devastadas y regresa junto al héroe caído de la Horda.', },
  },
  [8425] = {
    'Plumas Vudú',
    {'Tu honor me ha devuelto algo de paz. Es de justicia que te entregue algo a cambio.|n|nMis armas y armadura eran espléndidas en vida pero ahora ya no me sirven. Cumplirán mejor su función en tu posesión.|n|nVe al Templo Sumergido y destruye a los trols guardianes Gasher, Mijan, Zolo, Hukku, Zul\'lor y Loh\'ro. Llevan plumas mágicas que pueden recrear mi cuerpo físico lo suficiente para que te pueda dar tu premio.', },
    {'Llévale las plumas vudú de los trols del Templo Sumergido al héroe caído de la Horda.', },
  },
  [8444] = {
    '<NYI> <TXT> sombra chismosa de Lunámbar',
    nil,
    nil,
  },
  [8445] = {
    '<NYI> <TXT> sombra chismosa de Lunámbar',
    nil,
    nil,
  },
  [8446] = {
    'Inundación de Pesadilla',
    {'El objeto transpira corrupción.|n|nPuede haber un vínculo entre él y los dragones que siguen viniendo del Sueño. Debes encontrar a alguien que pueda desentrañar el significado de este objeto. Quizás los druidas del Claro de la Luna o del Fuerte Cenarion puedan seguir ayudándote.', },
    {'Encuentra a alguien que pueda descifrar el significado del objeto envuelto en pesadillas.|n|nQuizás un druida de gran poder pueda ayudarte.', },
  },
  [8447] = {
    'Leyendas veraces',
    {'Las aguas de Lago Elune\'ara deberían disolver las pesadillas que inundan este objeto. Dame un momento para purificarlo, $N.', },
    {'Espera a que el Guardián Remulos del Claro de la Luna purifique el objeto envuelto en pesadillas.', },
  },
