  [8867] = {
    'Fuegos artificiales lunares',
    {'Todos los años los druidas del Claro de la Luna celebran la gran victoria de nuestra ciudad sobre un antiguo mal.|n|nCelebramos la sabiduría de nuestros ancestros, participamos en magníficas fiestas y, por supuesto... ¡disparamos fuegos artificiales!|n|nA cambio de una pequeña donación puedes adquirir cohetes de colores de nuestro vendedor. Prueba a usarlos en uno de los lanzacohetes que hay por aquí, $N.', },
    {'Dispara 8 fuegos artificiales lunares y 2 cohetes y acude a una presagista del Festival Lunar de cualquier capital.', },
  },
  [8868] = {
    'La bendición de Elune',
    {'La bestia Augurio fue un héroe de este mundo en otros tiempos. Era un lobo de gran fuerza y fortuna que luchó junto a los héroes de la Guerra de los Ancestros hasta que cayó víctima de una magia demoníaca. Se volvió contra sus aliados y arrasó Azeroth dejando una estela de terror y muerte a su paso.|n|nFue derrotado aquí, en Claro de la Luna, y descansa en el cieno del Lago Elune\'ara. Pero cada año nuevo, durante el festival, se agita en su sueño eterno...|n|nRecluta un ejército, $N, y junto a él invoca y derrota a la bestia. ¡Merecerás la bendición de Elune!', },
    {'Invoca a Augurio y derrótalo para ganar la bendición de Elune. Ve a ver a Valadar Cantoestelar a Amparo de la Noche.', },
  },
  [8869] = {
    'Dulce serenidad',
    {'Viaja a Stratholme y mata al forjamartillos Carmesí. Consigue el delantal del forjamartillos Carmesí y regresa con Lilith.|n', },
    {'Viaja a Stratholme y mata al forjamartillos Carmesí. Consigue el delantal del forjamartillos Carmesí y regresa con Lilith.|n', },
  },
  [8870] = {
    'El Festival Lunar',
    {'¡Ha llegado ese momento del año, $N! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.', },
    {'Habla con la presagista del Festival Lunar en la Sala Mística de Forjaz. También puedes hablar con la presagista del Festival Lunar en otras capitales.', },
  },
  [8871] = {
    'El Festival Lunar',
    {'¡Ha llegado ese momento del año, $N! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.', },
    {'Habla con el presagista del Festival Lunar en la Ciudad de Ventormenta.', },
  },
  [8872] = {
    'El Festival Lunar',
    {'¡Ha llegado ese momento del año, $N! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.', },
    {'Habla con la presagista del Festival Lunar en el Enclave Cenarion de Darnassus. También puedes hablar con los presagistas del Festival Lunar en otras capitales.', },
  },
  [8873] = {
    'El Festival Lunar',
    {'¡Ha llegado ese momento del año, $N! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.', },
    {'Habla con la presagista del Festival Lunar en el Valle de la Sabiduría, en Orgrimmar. También puedes hablar con la presagista del Festival Lunar en otras capitales.', },
  },
  [8874] = {
    'El Festival Lunar',
    {'¡Ha llegado ese momento del año, $N! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.', },
    {'Habla con la presagista del Festival Lunar en la entrada de Entrañas. También puedes hablar con otras presagistas del Festival Lunar de otras capitales.', },
  },
  [8875] = {
    'El Festival Lunar',
    {'¡Ha llegado ese momento del año, $N! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.', },
    {'Habla con la presagista del Festival Lunar en el Alto de los Ancestros de Cima del Trueno. También puedes hablar con otras presagistas del Festival Lunar de otras capitales.', },
