  [9042] = {
    'Brazales acorator',
    {'Si mientras luchas contra la Plaga en Naxxramas encuentras restos de corazas y de almenas profanadas, tráemelos y te haré una armadura digna de un héroe.', },
    {'Korfax de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, te hará unos brazales acorator si le llevas lo siguiente: 1 par de brazales profanados, 6 restos de coraza, 1 barra de arcanita y 1 cristal nexo.', },
  },
  [9043] = {
    'Guerrera de redención',
    {'Encontrarás los restos de nuestros héroes caídos en los cadáveres de los señores de Naxxramas. Tráeme esos restos profanados, restos de coraza y materia prima para revitalizar la armadura maldita y la convertiré en una armadura adecuada para ti.', },
    {'El comandante Eligor Albar de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, te hará una guerrera de redención si le llevas lo siguiente: 1 guerrera profanada, 25 restos de coraza, 4 barras de arcanita y 3 pellejos bastos curtidos.', },
  },
  [9044] = {
    'Musleras de redención',
    {'Encontrarás los restos de nuestros héroes caídos en los cadáveres de los señores de Naxxramas. Tráeme esos restos profanados, restos de coraza y materia prima para revitalizar la armadura maldita y la convertiré en una armadura adecuada para ti.', },
    {'El comandante Eligor Albar de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, te hará unas musleras de redención si le llevas lo siguiente: 1 par de musleras profanadas, 20 restos de coraza, 4 barras de arcanita y 2 cristales nexo.', },
  },
  [9045] = {
    'Celada de redención',
    {'Encontrarás los restos de nuestros héroes caídos en los cadáveres de los señores de Naxxramas. Tráeme esos restos profanados, restos de coraza y materia prima para revitalizar la armadura maldita y la convertiré en una armadura adecuada para ti.', },
    {'El comandante Eligor Albar de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, te hará un celada de redención si le llevas lo siguiente: 1 celada profanada, 15 restos de coraza, 5 barras de arcanita y 2 pellejos bastos curtidos.', },
  },
  [9046] = {
    'Bufas de redención',
    {'Encontrarás los restos de nuestros héroes caídos en los cadáveres de los señores de Naxxramas. Tráeme esos restos profanados, restos de coraza y materia prima para revitalizar la armadura maldita y la convertiré en una armadura adecuada para ti.', },
    {'El comandante Eligor Albar de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, te hará unas bufas de redención si le llevas lo siguiente: 1 par de hombreras profanadas, 12 restos de coraza, 2 barras de arcanita y 2 cristales nexo.', },
  },
  [9047] = {
    'Botas de redención',
    {'Encontrarás los restos de nuestros héroes caídos en los cadáveres de los señores de Naxxramas. Tráeme esos restos profanados, restos de coraza y materia prima para revitalizar la armadura maldita y la convertiré en una armadura adecuada para ti.', },
    {'El comandante Eligor Albar de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, te hará unas botas de redención si le llevas lo siguiente: 1 par de botas profanadas, 12 restos de coraza, 2 barras de arcanita y 3 pellejos bastos curtidos.', },
  },
  [9048] = {
    'Manoplas de redención',
    {'Encontrarás los restos de nuestros héroes caídos en los cadáveres de los señores de Naxxramas. Tráeme esos restos profanados, restos de coraza y materia prima para revitalizar la armadura maldita y la convertiré en una armadura adecuada para ti.', },
