  [10472] = {
    'El pacto del sabio',
    {'Tus hazañas han llegado más allá de mis mejores esperanzas, $N.|n|nEntras y sales de las corrientes del tiempo igual que cualquier dragón de bronce que he conocido. Tu destino está marcado por un gran poder y me alegro de poder acompañarte hasta él.|n|nSigue al servicio de la Escama de Arenas y desataré todo el potencial de tu don.', },
    {'Devuelve tu sortija de eternidad a Soridormi en las Cavernas del Tiempo después de alcanzar la reputación de exaltado ante La Escama de las Arenas.', },
  },
  [10473] = {
    'El pacto del restaurador',
    {'Tus hazañas han llegado más allá de mis mejores esperanzas, $N.|n|nEntras y sales de las corrientes del tiempo igual que cualquier dragón de bronce que he conocido. Tu destino está marcado por un gran poder y me alegro de poder acompañarte hasta él.|n|nSigue al servicio de la Escama de Arenas y desataré todo el potencial de tu don.', },
