  },
  [11108] = {
    'Lord Illidan Tempestira',
    {'¡Ven, $Galto señor:alta señora; $N! ¡Illidan en persona nos espera!', },
    {'Ve al encuentro de Illidan Tempestira. Si vives para contarlo, busca a Barthamus en el Bajo Arrabal de Shattrath.', },
  },
