  [13688] = {
    'Un Valeroso de Gnomeregan',
    {'Has demostrado que eres $Gdigno:digna; de competir bajo el estandarte de Gnomeregan, $N. Ahora preséntate ante Ambrose Chisparrayo, que dirige la delegación de Gnomeregan. Como Gran Campeón de los gnomos, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en $GValeroso:Valerosa;.|n|nHa sido un honor trabajar contigo, $N, te deseo suerte en la competición que te espera.', },
    {'Habla con Ambrose Chisparrayo en los Campos del Torneo Argenta para convertirte en $Gun Valeroso:una Valerosa; de Gnomeregan.', },
  },
  [13689] = {
    'Un Valeroso de Darnassus',
    {'Has demostrado que eres $Gdigno:digna; de competir bajo el estandarte de Darnassus, $N. Ahora preséntate ante Jaelyne Unicanto, que dirige la delegación de Darnassus. Como Gran Campeona de los elfos de la noche, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en $GValeroso:Valerosa;.|n|nHa sido un honor trabajar contigo, $N, te deseo suerte en la competición que te espera.', },
    {'Habla con Jaelyne Unicanto en los Campos del Torneo Argenta para convertirte en $Gun Valeroso:una Valerosa; de Darnassus.', },
  },
  [13690] = {
    'Un Valeroso de El Exodar',
    {'Has demostrado que eres $Gdigno:digna; de competir bajo el estandarte de El Exodar, $N. Ahora preséntate ante Colosos, que dirige la delegación de El Exodar. Como Gran Campeón draenei, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en $GValeroso:Valerosa;.|n|nHa sido un honor trabajar contigo, $N, te deseo suerte en la competición que te espera.', },
    {'Habla con Colosos en los Campos del Torneo Argenta para convertirte en $Gun Valeroso:una Valerosa; de El Exodar.', },
  },
  [13691] = {
    'Un Valeroso de Orgrimmar',
    {'Has demostrado que eres $Gdigno:digna; de competir bajo el estandarte de Orgrimmar, $N. Ahora habla con Mokra el Trituracráneos, que dirige a los competidores de Orgrimmar. Como Gran Campeón de Orgrimmar, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en $GValeroso:Valerosa;.|n|nHa sido un honor trabajar contigo, $N, te deseo suerte en la competición que te espera.', },
    {'Habla con Mokra el Trituracráneos en los Campos del Torneo Argenta para convertirte en $Gun Valeroso:una Valerosa; de Orgrimmar.', },
  },
  [13692] = {
    'La espada y el mar',
    {'Perdí mi espada en el mar. ¡Encuéntrala y tráemela!', },
    {'El viejo Barlo en el Bosque Canto de Cristal quiere que le lleves la espada de caballería.', },
  },
  [13693] = {
    'Un Valeroso de Sen\'jin',
    {'Has demostrado que eres $Gdigno:digna; de competir bajo el estandarte de Sen\'jin, $N. Ahora habla con Zul\'tore, que dirige a los guerreros de Sen\'jin. Como Gran Campeón trol, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en $GValeroso:Valerosa;.|n|nHa sido un honor trabajar contigo, $N, te deseo suerte en la competición que te espera.', },
    {'Habla con Zul\'tore en los Campos del Torneo Argenta para convertirte en $Gun Valeroso:una Valerosa; de Sen\'jin.', },
  },
  [13694] = {
    'Un Valeroso de Cima del Trueno',
    {'Has demostrado que eres $Gdigno:digna; de competir bajo el estandarte de Cima del Trueno, $N. Ahora habla con Runok Ferocrín, que dirige a los competidores de Cima del Trueno. Como Gran Campeón de Cima del Trueno, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en $GValeroso:Valerosa;.|n|nHa sido un honor trabajar contigo, $N, te deseo suerte en la competición que te espera.', },
    {'Habla con Runok Ferocrín en los Campos del Torneo Argenta para convertirte en $Gun Valeroso:una Valerosa; de Cima del Trueno.', },
  },
  [13695] = {
    'Un Valeroso de Entrañas',
    {'Has demostrado que eres $Gdigno:digna; de competir bajo el estandarte de Entrañas, $N. Ahora habla con el mortacechador Visceri, que dirige la delegación de Entrañas. Como Gran Campeón, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en $GValeroso:Valerosa;.|n|nHa sido un honor trabajar contigo, $N, te deseo suerte en la competición que te espera.', },
    {'Habla con el mortacechador Visceri en los Campos del Torneo Argenta para convertirte en $Gun Valeroso:una Valerosa; de Entrañas.', },
  },
  [13696] = {
    'Un Valeroso de Lunargenta',
    {'Has demostrado que eres $Gdigno:digna; de competir bajo el estandarte de Lunargenta, $N. Ahora habla con Eressea Cantoalba, que dirige la delegación de Lunargenta. Como Gran Campeona de Lunargenta, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en $GValeroso:Valerosa;.|n|nHa sido un honor trabajar contigo, $N, te deseo suerte en la competición que te espera.', },
    {'Habla con Eressea Cantoalba en los Campos del Torneo Argenta para convertirte en $Gun Valeroso:una Valerosa; de Lunargenta.', },
  },
  [13697] = {
    'La carga del Valeroso',
    {'En tu entrenamiento como $GValeroso:Valerosa; tendrás la oportunidad de poner a prueba tu habilidad contra valerosos que representan a otras ciudades. Aunque las batallas de $Gun Valeroso:una Valerosa; no son parte formal de la competición, aprenderás una valiosa lección sobre los estilos de lucha y las debilidades de tus oponentes.|n|nLos valerosos son gente voluntariosa que compite entre sí en pos del honor y la notoriedad.|n|nEntrénate como $Gun Valeroso:una Valerosa; hasta que confíes en tu habilidad para derrotar a todo aquel que se enfrente a ti. Después tráeme los sellos que hayas ganado.', },
    {'Lleva 25 sellos de Valeroso a Mokra el Trituracráneos en los Campos del Torneo Argenta.', },
  },
  [13698] = {
    'Explosivos que trituran',
    {'Odio volver a enviarte allí, pero si nos basamos en tu descripción de lo que está pasando, ¡no podemos dejar que utilicen todos los explosivos que hemos almacenado!|n|nEs demasiado peligroso que intentes destruirlos tú $Gmismo:misma;, pero si robases una de sus trituradoras, estoy seguro de que sería lo suficientemente fuerte para resistir las explosiones.|n|nCuando hayas destruido sus explosivos, vuelve aquí con la trituradora. No tiene sentido que se la devolvamos.', },
    {'Utiliza una trituradora Grito de Guerra para destruir 8 barriles de explosivos.', },
  },
  [13699] = {
    'El desafío del Valeroso',
    {'Ya casi estás $Glisto:lista; para competir en el gran combate cuerpo a cuerpo en nombre de Ventormenta. Para demostrar que eres $Gdigno:digna; de entrar en las listas en nombre de nuestra ciudad, debes derrotar a un campeón de la Cruzada Argenta.|n|nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta. Habla con el escudero Danny en La Liza de los Valerosos Argenta en el extremo oeste de los campos. El escudero llamará a tu oponente cuando estés $Glisto:lista;.|n|nCuando la batalla haya concluido, hablaremos del resultado.', },
    {'Habla con el escudero Danny para llamar a tu oponente. Cuando hayas derrotado al Campeón Argenta, regresa con el mariscal Jacob Alerius en los Campos del Torneo Argenta.|n|nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.', },
  },
  [13700] = {
    'Marcador de Campeón de la Alianza',
    nil,
    nil,
  },
  [13701] = {
    'Marcador de Campeón de la Horda',
    nil,
    nil,
  },
  [13702] = {
    'Se alza un Campeón',
    {'Felicidades, $N. Has dominado muchos tipos de combate y has superado todos los desafíos a los que te has enfrentado. No cabe duda de que estás $Gpreparado:preparada; para competir con los mejores guerreros que se han reunido en este torneo, contra los campeones de las ciudades capitales.|n|nLa justicar Mariel Corazón Veraz ha solicitado hablar contigo, $N, e introducirte formalmente en el gran combate cuerpo a cuerpo de los campeones.', },
    {'Habla con la justicar Mariel Corazón Veraz en los Campos del Torneo Argenta.', },
  },
  [13703] = {
    'Valeroso de Forjaz',
    {'Te doy la bienvenida, $GCampeón:Campeona;. Ya he oído hablar de tu destreza en el combate. ¿Deseas unirte a la delegación de Forjaz en el torneo?|n|nTe entrenarás y subirás de rango como has hecho antes, pero cuando seas $Gnombrado Campeón:nombrada Campeona; de Forjaz tu escudero tendrá la opción de llevar nuestro estandarte a la batalla.', },
    {'Habla de nuevo con Lana Martillotenaz si quieres convertirte en $GValeroso:Valerosa; de Forjaz.', },
  },
  [13704] = {
    'Valeroso de Gnomeregan',
    {'Te doy la bienvenida, $GCampeón:Campeona;. Ya he oído hablar de tu destreza en combate. La delegación de Gnomeregan podría sacar partido de verdad a $Gun:una; $C como tú.|n|nTe entrenarás y subirás de rango como antes, pero cuando seas $Gnombrado Campeón:nombrada Campeona; de Gnomeregan tu escudero podrá optar a llevar nuestro estandarte a la batalla.', },
    {'Habla de nuevo con Ambrose Chisparrayo si quieres convertirte en $GValeroso:Valerosa; de Gnomeregan.', },
  },
  [13705] = {
    'Valeroso de El Exodar',
    {'Te doy la bienvenida, $GCampeón:Campeona;. Ya he oído hablar de tus gestas. ¿Deseas unirte a la delegación de El Exodar en el torneo?|n|nTe entrenarás y subirás de rango como antes, pero cuando seas $Gnombrado Campeón:nombrada Campeona; de El Exodar, tu escudero podrá optar a llevar nuestro estandarte a la batalla.', },
    {'Habla con Colosos de nuevo si deseas convertirte en $GValeroso:Valerosa; de El Exodar.', },
  },
  [13706] = {
    'Valeroso de Darnassus',
    {'Te doy la bienvenida, $GCampeón:Campeona;. Ya he oído hablar de tus logros y nos honraría que te unieras a la delegación de Darnassus.|n|nTe entrenarás y subirás de rango como antes, pero cuando seas $Gnombrado Campeón:nombrada Campeona; de Darnassus, tu escudero podrá optar a llevar nuestro estandarte a la batalla.', },
    {'Habla de nuevo con Jaelyne Unicanto si quieres convertirte en $GValeroso:Valerosa; de Darnassus.', },
  },
  [13707] = {
    'Valeroso de Orgrimmar',
    {'¿Así que ahora eres $Gun Campeón:una Campeona;? Entonces has demostrado ser $Gun combatiente digno:una combatiente digna; y me llena de orgullo darte la bienvenida a nuestra delegación de Orgrimmar.|n|nTe entrenarás y subirás de rango como antes, pero cuando seas $Gnombrado Campeón:nombrada Campeona; de Orgrimmar, tu brutito podrá optar a llevar nuestro estandarte a la batalla.', },
    {'Habla de nuevo con Mokra el Trituracráneos si quieres convertirte en $GValeroso:Valerosa; de Orgrimmar.', },
  },
  [13708] = {
    'Valeroso de Sen\'jin',
    {'Saludos, $GCampeón:Campeona;. Si lo deseas, te doy la bienvenida a nuestra delegación de Sen\'jin en el torneo.|n|nTe entrenarás y subirás de rango como antes, pero cuando seas $Gnombrado Campeón:nombrada Campeona; de Sen\'jin, tu brutito podrá optar a llevar nuestro estandarte a la batalla.', },
    {'Habla de nuevo con Zul\'tore si deseas convertirte en $Gun Valeroso:una Valerosa; de Sen\'jin.', },
  },
  [13709] = {
    'Valeroso de Cima del Trueno',
    {'Te doy la bienvenida, $GCampeón:Campeona;. Como Gran Campeón de la delegación de Cima del Trueno, me honraría darte la bienvenida a nuestra organización, si así lo deseas.|n|nTe entrenarás y subirás de rango como antes, pero cuando te nombren $GCampeón:Campeona; de Cima del Trueno, tu brutito podrá optar a llevar nuestro estandarte a la batalla.', },
    {'Habla de nuevo con Runok Ferocrín si quieres convertirte en $GValeroso:Valerosa; de Cima del Trueno.', },
  },
  [13710] = {
    'Valeroso de Entrañas',
    {'Te doy la bienvenida, $GCampeón:Campeona;. La delegación de los Renegados siempre podría emplear a $Gun:una; $C como tú. ¿Te gustaría unirte a nosotros?|n|nTe entrenarás y subirás de rango como antes, pero cuando seas nombrad$Go Campeón:a Campeona; de Entrañas, tu brutito podrá optar a llevar nuestro estandarte a la batalla.', },
    {'Habla de nuevo con el mortacechador Visceri si deseas convertirte en Valeroso de Entrañas.', },
  },
  [13711] = {
    'Valeroso de Lunargenta',
    {'¿Así que ahora eres $Gun Campeón:una Campeona;? Entonces has demostrado ser $Gun combatiente digno:una combatiente digna; y me llena de orgullo darte la bienvenida a nuestra delegación de Lunargenta.|n|nTe entrenarás y subirás de rango como antes, pero cuando seas $Gnombrado Campeón:nombrada Campeona; de Lunargenta, tu brutito podrá optar a llevar nuestro estandarte a la batalla.', },
    {'Habla de nuevo con Eressea Cantoalba si quieres convertirte en $GValeroso:Valerosa; de Lunargenta.', },
  },
  [13712] = {
    '¡Al rescate!',
    {'Tú vienes conmigo, $N.|n|nNo puedo prescindir de nadie más y no podemos permitirnos perder El Hachazo.|n|nPrepárate y ven a avisarme cuando estés $Glisto:lista;.', },
    {'Habla con Kadrak en la Empalizada de Mor\'shan y acompáñale hasta el Puesto del Hachazo.', },
  },
  [13713] = {
    'El desafío del Valeroso',
    {'Ya casi estás $Glisto:lista; para competir en el gran combate cuerpo a cuerpo en nombre de Forjaz. Para demostrar que eres $Gdigno:digna; de entrar en las listas en nombre de nuestra ciudad, debes derrotar a un campeón de la Cruzada Argenta.|n|nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta. Habla con el escudero Danny en La Liza de los Valerosos Argenta en el extremo oeste de los campos. El escudero llamará a tu oponente cuando estés $Glisto:lista;.|n|nCuando la batalla haya concluido, hablaremos del resultado.', },
    {'Habla con el escudero Danny para llamar a tu oponente. Cuando hayas derrotado al Campeón Argenta, regresa con Lana Martillotenaz en los Campos del Torneo Argenta.|n|nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.', },
  },
  [13714] = {
    'La carga del Valeroso',
    {'En tu entrenamiento como $GValeroso:Valerosa; tendrás la oportunidad de poner a prueba tu habilidad contra valerosos que representan a otras ciudades. Aunque las batallas de $Gun Valeroso:una Valerosa; no son parte formal de la competición, aprenderás una valiosa lección sobre los estilos de lucha y las debilidades de tus oponentes.|n|nLos valerosos son gente voluntariosa que compite entre sí en pos del honor y la notoriedad.|n|nEntrénate como $Gun Valeroso:una Valerosa; hasta que confíes en tu habilidad para derrotar a todo aquel que se enfrente a ti. Después tráeme los sellos que hayas ganado.', },
    {'Lleva 25 sellos de Valeroso a Lana Martillotenaz en los Campos del Torneo Argenta.', },
  },
  [13715] = {
    'La carga del Valeroso',
    {'En tu entrenamiento como $GValeroso:Valerosa; tendrás la oportunidad de poner a prueba tu habilidad contra valerosos que representan a otras ciudades. Aunque las batallas de $Gun Valeroso:una Valerosa; no son parte formal de la competición, aprenderás una valiosa lección sobre los estilos de lucha y las debilidades de tus oponentes.|n|nLos valerosos son gente voluntariosa que compite entre sí en pos del honor y la notoriedad.|n|nEntrénate como $Gun Valeroso:una Valerosa; hasta que confíes en tu habilidad para derrotar a todo aquel que se enfrente a ti. Después tráeme los sellos que hayas ganado.', },
