  [13736] = {
    'Se alza un Campeón',
    {'Te has ganado mi respeto y el de tus compañeros. Has derrotado a todo el que te ha desafiado y dominas el combate en torneo. ¡No dudo de que estás $Gpreparado:preparada; para enfrentarte a los campeones de otras ciudades por la gloria de Orgrimmar!|n|nLa justicar Mariel Corazón Veraz ha solicitado hablar contigo, $N, e introducirte formalmente en el gran combate cuerpo a cuerpo de los campeones.', },
    {'Habla con la justicar Mariel Corazón Veraz en los Campos del Torneo Argenta.', },
  },
  [13737] = {
    'Se alza un Campeón',
    {'Te has ganado mi respeto y el de tus compañeros. Has derrotado a todo el que te ha desafiado y dominas el combate en torneo. ¡No dudo de que estás $Gpreparado:preparada; para enfrentarte a los campeones de otras ciudades por la gloria de Lanza Negra!|n|nLa justicar Mariel Corazón Veraz ha solicitado hablar contigo, $N, e introducirte formalmente en el gran combate cuerpo a cuerpo de los campeones.', },
