  [24787] = {
    'Mejor de lo esperado',
    {'Definitivamente, eres mejor de lo que pensaba, colega. Seguro que hay cosas más impoh\'tantes en las que inveh\'tir tu talento. Ya no tienes por qué mezclah\'te con los novatos.|n|nDirígete al poblao del sureh\'te y date a conocé. Echa una mano por aquí y allá y aumentarás tu preh\'tigio rápidamente.', },
    {'Preséntate ante Vol\'jin en el Bastión Lanza Negra.', },
  },
  [24792] = {
    'El topo',
    {'Pareces lo bastante hábil para enfrentarte al cerebro de toda esta operación. El libro de contabilidad dice que se esconde en el Castillo de Colmillo Oscuro, así que allí te voy a enviar.|n|nYa tenemos a un hombre dentro, pero no puede desarticular una operación él solo. Entra y el investigador se reunirá contigo. Llévate unos amigos.', },
    {'Preséntate ante el investigador Fezzen Arreolatón en el Castillo de Colmillo Oscuro.', },
  },
  [24793] = {
    'El topo',
    {'Pareces lo bastante hábil para enfrentarte al cerebro de toda esta operación. El libro de contabilidad dice que se esconde en el Castillo de Colmillo Oscuro, así que allí te voy a enviar.|n|nYa tenemos a un hombre dentro, pero no puede desarticular una operación él solo. Entra y el investigador se reunirá contigo. Llévate unos amigos.', },
    {'Preséntate ante el investigador Fezzen Arreolatón en el Castillo de Colmillo Oscuro.', },
  },
  [24794] = {
    'Habla con Spraggle',
    {'Mi buena amiga Spraggle lleva algún tiempo preocupada por algo. Le ayudaría, pero, como puedes observar, estoy bastante cómodo ahora mismo.|n|n¿Podrías ir a verla y comprobar qué necesita?', },
    {'Habla con Spraggle Frock en el Alto de Marshal.', },
  },
  [24795] = {
    'Una victoria para El Pacto de Plata',
    {'A pesar de la fanfarronería de la Reina Lana\'thel, has restaurado Quel\'Delar, $N. Hemos soñado con reclamar Quel\'Delar tanto tiempo.|n|nEl Pacto de Plata y por supuesto todos los quel\'dorei están en deuda contigo.|n|nComo $C, la espada parece saber que no tienes la formación para blandirla y no se ha ligado a ti. ¿De dónde vendrá su próximo maestro? Quizás la Cruzada Argenta encuentre uno. Ve al norte, a los Campos del Torneo Argenta y presenta la espada a la justicar Mariel Corazón Veraz en nombre de El Pacto de Plata.', },
    {'Llévale la Quel\'Delar restaurada a la justicar Mariel Corazón Veraz a los Campos del Torneo Argenta.', },
  },
  [24796] = {
    'Una victoria para El Pacto de Plata',
    {'A pesar de la fanfarronería de la Reina Lana\'thel, has restaurado Quel\'Delar, $N. Hemos soñado con reclamar Quel\'Delar tanto tiempo.|n|nEl Pacto de Plata y por supuesto todos los quel\'dorei están en deuda contigo.|n|nVereesa Brisaveloz, la líder de El Pacto de Plata, ha pedido verte tras tu vuelta de La Fuente del Sol. Llévate a Quel\'Delar y ve a La Ciudadela Violeta de Dalaran donde te espera, $N.', },
    {'Llévale la Quel\'Delar restaurada a Vereesa Brisaveloz a la Ciudadela Violeta de Dalaran.', },
  },
  [24798] = {
    'Una victoria para los Atracasol',
    {'¡Por fin, Quel\'Delar ha sido restaurada por la gloria de los Atracasol y los sin\'dorei!|n|nToda Lunargenta te aclamará como $Gun héroe:una heroína;, $N.|n|nComo $C, la espada parece saber que no tienes la formación para blandirla y no se ha ligado a ti. ¿De dónde vendrá su próximo maestro? No ha aparecido ningún sin\'dorei digno. Pidamos ayuda a la Cruzada Argenta. Ve al norte, a los Campos del Torneo Argenta y presenta la espada a la justicar Mariel Corazón Veraz en nombre de los Atracasol.', },
    {'Llévale la Quel\'Delar restaurada a la justicar Mariel Corazón Veraz a los Campos del Torneo Argenta.', },
  },
  [24799] = {
    'Una victoria para los Atracasol',
    {'¡Por fin, Quel\'Delar ha sido restaurada por la gloria de los Atracasol!|n|nToda la Horda te aclamará como $Gun héroe:una heroína;, $N.|n|nComo $C, la espada parece saber que no tienes la formación para blandirla y no se ha ligado a ti. ¿De dónde vendrá su próximo maestro? No ocultaré mi desilusión; esperaba que fuera un sin\'dorei digno. Pidamos ayuda a la Cruzada Argenta. Ve al norte, a los Campos del Torneo Argenta y presenta la espada a la justicar Mariel Corazón Veraz en nombre de los Atracasol.', },
    {'Llévale la Quel\'Delar restaurada a la justicar Mariel Corazón Veraz a los Campos del Torneo Argenta.', },
  },
  [24800] = {
    'Una victoria para los Atracasol',
    {'¡Por fin, Quel\'Delar ha sido restaurada por la gloria de los Atracasol y los sin\'dorei! Toda Lunargenta y toda la Horda te proclamará $Gun héroe:una heroína;.|n|nEl archimago Aethas Atracasol, líder de los Atracasol, ha pedido verte tras tu regreso de La Fuente del Sol. Viaja a La Ciudadela Violeta en Dalaran en cuanto puedas, $N, y lleva contigo a Quel\'Delar. ¡El Archimago quiere felicitarte personalmente!', },
    {'Llévale la Quel\'Delar restaurada al archimago Aethas Atracasol a la Ciudadela Violeta de Dalaran.', },
  },
  [24801] = {
    'Una victoria para los Atracasol',
    {'¡Por fin, Quel\'Delar ha sido restaurada por la gloria de los Atracasol y la Horda! Es una bendición por nuestros esfuerzos contra el Rey Exánime.|n|nEl archimago Aethas Atracasol, líder de los Atracasol, ha pedido verte tras tu regreso de La Fuente del Sol. Viaja a La Ciudadela Violeta en Dalaran en cuanto puedas, $N, y lleva contigo a Quel\'Delar. ¡El Archimago quiere felicitarte personalmente!', },
    {'Llévale la Quel\'Delar restaurada al archimago Aethas Atracasol a la Ciudadela Violeta de Dalaran.', },
  },
  [24802] = {
    'La cólera del Rey Exánime',
    {'Es difícil creer que haya esperanzas de derrotar a Arthas en los peldaños de su propio trono. ¿Y quién se hará con la corona del Rey Exánime si es así?|n|nQuedan demasiadas preguntas, pero tienes que encontrar a Sylvanas y escapar del Rey Exánime mientras aún haya tiempo.', },
    {'Encuentra a Lady Sylvanas Brisaveloz y escapa de Las Cámaras de Reflexión.', },
  },
  [24803] = {
    'Competición de pesca Kalu\'ak',
    nil,
    nil,
  },
  [24804] = {
    'Olores extraños',
    {'Hay gato encerrado en Químicos La Corona, S.L. Los de Bonvapor le tienen echado el ojo, pero me vendría bien otro par.|n|nVe a Ventormenta si te interesa ayudarnos. El inspector Snip Tuerceganzúas dirige la investigación desde allí, y necesita toda la ayuda que podamos prestarle.', },
    {'Preséntate ante el inspector Snip Tuerceganzúas en Ventormenta.', },
  },
  [24805] = {
    'Olores extraños',
    {'Hay gato encerrado en Químicos La Corona, S.L. Los de Bonvapor le tienen echado el ojo, pero me vendría bien otro par.|n|nVe a Orgrimmar si te interesa ayudarnos. El detective Snap Tuerceganzúas dirige la investigación desde allí, y necesita toda la ayuda que podamos prestarle.', },
    {'Preséntate ante el detective Snap Tuerceganzúas en Orgrimmar.', },
  },
  [24806] = {
    'Más suerte la próxima vez',
    nil,
    nil,
  },
  [24807] = {
    'Winnoa Bosque de Pinos',
    {'Tras haber conseguido grandes logros, sería una tragedia que parte de la corrupción hubiera pasado inadvertida. Los pasillos de las Cuevas de los Lamentos se extienden por todos los Baldíos y, si otro foco de energía salvaje hubiera conseguido salir a la superficie...|n|nSin embargo, ya has hecho bastante por mí. Solo te pediré que informes a una camarada druida de lo que ha ocurrido. Encontrarás a Winnoa Bosque de Pinos en Punta Vendetta, al suroeste.', },
    {'Habla con Winnoa Bosque de Pinos en Punta Vendetta, en Los Baldíos del Sur.', },
  },
  [24812] = {
    'Sin piedad',
    {'Lo\'h nagas han cometío grandes atrocidades contra nueh\'tro pueblo. Ya no podemos seguir moh\'trando piedad.|n|nEntra en la cueva y mata a cualquier naga que encuentres. Cada naga muerto significa uno menos por el que preocupah\'nos el día de mañana. Confío en que será exhaustivo.', },
    {'Mata a 12 nagas Escama Maliciosa.', },
  },
  [24813] = {
    'Fetiche territorial',
    {'Eh\'te contraataque no es casual. Eh\'tamos intentando eliminar por todos los medios hasta el último naga de la zona y hacer lo posible p\'a asegurarnos de que no les queden ganas de regresar.|n|nQuiero que coloques eh\'tos fetiches en cualquier estandarte Escama Maliciosa que encuentres dentro de su cueva. Debería bastá p\'a demostrar lo que opinamos de su presencia aquí. Ademá\'h, la magia de estos fetiches debilitará a cualquier Escama Maliciosa que se acerque, lo que debería hacerles reflexioná otra vez sobre su eh\'tancia en nuestra isla.', },
    {'Coloca 8 fetiches territoriales en las banderas Escama Maliciosa.', },
  },
  [24814] = {
    'Viejos enemigos',
    {'La Bruja del Mar eh\'tá aquí, en la cima de eh\'ta isla. Hemos aguardado durante musho tiempo una oportunidad para vengarnos y, ahora tú, gozarás del privilegio de presenciarla.|n|nReúnete con Vol\'jin en el alto del noreste y avísale cuando eh\'tés $Glisto:lista; p\'a unirte a la batalla.', },
    {'Habla con Vol\'jin en la Cala Escama Maliciosa y ayúdale a matar a la Bruja del Mar Zar\'jira.', },
  },
  [24815] = {
    'Elige tu camino',
    nil,
    nil,
  },
  [24816] = {
    '¿Y ahora quién encabeza la cadena alimentaria?',
    {'Bueno vale, quizás todo el rollo del huevo no resultó ser un éxito. ¿A quién le apetece algo de carne de tiburón?|n|nSolo existe un pequeño problema. Bueno, en realidad, un gran problema. Un verdadero GRAN problema: ¡El Martillo!|n|nPero claro, tengo una idea brillante. Nada por el Estrecho Temible del oeste y consíguenos unos cuantos trozos de tiburón. Dáselos a mi asistente, Greely. Soy demasiado importante como para ensuciarme las manos con detalles insignificantes.', },
    {'Recoge 5 trozos de tiburón.', },
  },
  [24817] = {
    'Un goblin con piel de tiburón',
    {'Al combinar los restos del mecapollo con estos trozos de tiburón hemos creado el mejor sumergible de combate de la historia: ¡el Mecatiburón Vapor-X!|n|nHobart y yo queremos que lo pilotes, $N. Dirígete al oeste, hasta el agua, y activa el controlador de Mecatiburón Vapor-X.|n|nDebes matar a El Martillo para que tengamos alguna posibilidad de explotar al máximo los recursos naturales del Estrecho Temible. ¡Es por el bien del cártel!', },
    {'Activa el controlador de Mecatiburón Vapor-X y usa el Mecatiburón Vapor-X para matar a El Martillo.', },
  },
