  [28020] = {
    'Se buscan aventureros: Cementerio del Monasterio Escarlata',
    {'El rey Varian Wrynn ha solicitado que todos los aventureros aptos se dirijan al Cementerio del Monasterio Escarlata, al noreste de Entrañas, ¡de inmediato!|n|n¡Joseph el Despierto, un antiguo cruzado, ha solicitado ayuda para eliminar a sus líderes y reformar la cruzada! Si decides ayudar, dirígete al Cementerio del Monasterio Escarlata y habla con Joseph el Despierto para contribuir.', },
    {'Habla con Joseph el Despierto.', },
  },
  [28021] = {
    'Se buscan aventureros: Cámaras Escarlata',
    nil,
    {'Habla con Joseph el Despierto.', },
  },
  [28022] = {
    'Se buscan aventureros: Arsenal del Monasterio Escarlata',
    {'El rey Varian Wrynn ha solicitado que todos los aventureros aptos se dirijan al Arsenal del Monasterio Escarlata, al noreste de Entrañas, ¡de inmediato!|n|n¡Joseph el Enloquecido ha solicitado ayuda para matar a Herod, el Campeón Escarlata! Si decides ayudar, dirígete al Arsenal del Monasterio Escarlata y habla con Joseph el Enloquecido para ayudarle.', },
    {'Habla con Joseph el Enloquecido.', },
  },
  [28023] = {
