  [28811] = {
    'No temerás peligro alguno',
    {'¿Ya te has entregado a la Luz Sagrada, $Ghermano:hermana;? ¡Es la Luz Sagrada la que nos salva! ¡Es la Luz Sagrada la que me permite sanar a estos soldados demasiado exigentes! ¡La misma Luz Sagrada que te permitirá adentrarte en el campo que hay al norte y rescatar a nuestros hermanos caídos!|n|nLlévate este libro de oraciones al campo y aplica el toque de sanación de la Luz a los heridos.', },
    {'Revive a 4 soldados de Ventormenta heridos.', },
  },
  [28812] = {
    'No temerás peligro alguno',
    {'¿Ya te has entregado a la Luz Sagrada, $Ghermano:hermana;? ¡Es la Luz Sagrada la que nos salva! ¡Es la Luz Sagrada la que me permite sanar a estos soldados demasiado exigentes! ¡La misma Luz Sagrada que te permitirá adentrarte en el campo que hay al norte y rescatar a nuestros hermanos caídos!|n|nLlévate este libro de oraciones al campo y aplica el toque de sanación de la Luz a los heridos.', },
    {'Revive a 4 soldados de Ventormenta heridos.', },
  },
  [28813] = {
    'No temerás peligro alguno',
    {'¿Ya te has entregado a la Luz Sagrada, $Ghermano:hermana;? ¡Es la Luz Sagrada la que nos salva! ¡Es la Luz Sagrada la que me permite sanar a estos soldados demasiado exigentes! ¡La misma Luz Sagrada que te permitirá adentrarte en el campo que hay al norte y rescatar a nuestros hermanos caídos!|n|nLlévate este libro de oraciones al campo y aplica el toque de sanación de la Luz a los heridos.', },
    {'Revive a 4 soldados de Ventormenta heridos.', },
  },
  [28814] = {
    'Seguidores y líderes',
    {'Los documentos relatan la llegada de la Suma sacerdotisa Azil a las profundidades de El Núcleo Pétreo.|n|nDescribe a Azil como un miembro de alto rango del Consejo Crepuscular. Además, su cortejo de más de un centenar de seguidores devotos se prepara para un ritual profano de oscuridad inaudita.|n|nParece tratarse de un acontecimiento que debes detener.', },
    {'Mata a la Suma sacerdotisa Azil y a 101 seguidores devotos.', },
  },
  [28815] = {
    'Documentos Crepusculares',
    {'Hemos estado siguiendo a uno de los operativos del Martillo Crepuscular. Se hace llamar Molino Tormenta de Maná.|n|nTenemos razones para sospechar que lleva unos documentos importantes.|n|nSin embargo, no podemos ir más lejos sin abandonar nuestra tarea de defender el perímetro interior del Templo de la Tierra.|n|nLocaliza a Tormenta de Maná y quítale los documentos.', },
    {'Hazte con los documentos Crepusculares.', },
  },
  [28816] = {
    'A las profundidades',
    {'El Anillo de la Tierra ha identificado el reino acuático de Vashj\'ir como una fuente de energías destructoras del adversario.|n|nLos peligros que podríamos afrontar allí aún son inciertos, así que toda la información que puedas reunir será muy valiosa.|n|nLa Horda está enviando naves de guerra a la región. Para que te lleven habla con el comandante Thorak en la Bahía de Garrafilada.|n|nQue los espíritus te guíen, $N.', },
    {'Preséntate al comandante Thorak en la Bahía de Garrafilada, en Durotar.', },
  },
  [28817] = {
    'Retaguardia despejada',
    {'¡Un trabajo excelente, $N! Ahora la retaguardia está oficialmente despejada. Nos encargaremos de los rezagados. Quiero que vuelvas a ver al alguacil McBride, que se encuentra frente a la Abadía de Villanorte, y le cuentes que la situación goblin está controlada.|n|nAdiós, $C.', },
    {'Preséntate ante el alguacil McBride frente a la Abadía de Villanorte, en el Bosque de Elwynn.', },
  },
  [28818] = {
    'Retaguardia despejada',
    {'¡Un trabajo excelente, $N! Ahora la retaguardia está oficialmente despejada. Nos encargaremos de los rezagados. Quiero que vuelvas a ver al alguacil McBride, que se encuentra frente a la Abadía de Villanorte, y le cuentes que la situación goblin está controlada.|n|nAdiós, $C.', },
    {'Preséntate ante el alguacil McBride frente a la Abadía de Villanorte, en el Bosque de Elwynn.', },
