  [28934] = {
    'Aplasta La Corona',
    {'Este libro de contabilidad está lleno de lugares y necesito que los investigues y tomes medidas, $Gamigo:amiga;. Esto tiene que acabar.|n|nEsta es la entrada que quiero que investigues: parece que está en Uldum, al este de la Tumba de Khartut, cerca de la entrada desde Tanaris. Ve y dales una paliza.|n|nAh, y si ves algo grande y peligroso que haya que destruir, tírale esta bomba.', },
    {'Mata a 5 técnicos de La Corona y utiliza la bomba de korio de Tuerceganzúas para destruir un vagón químico al este de la Tumba de Khartut, en Uldum. Después, vuelve con el inspector Snip Tuerceganzúas en Ventormenta.', },
  },
  [28935] = {
    'Aplasta La Corona',
    {'Este libro de contabilidad está lleno de lugares y necesito que los investigues y tomes medidas, $Gamigo:amiga;. Esto tiene que acabar.|n|nEsta es la entrada que quiero que investigues: parece que está en Uldum, al este de la Tumba de Khartut, cerca de la entrada desde Tanaris. Ve y dales una paliza.|n|nAh, y si ves algo grande y peligroso que haya que destruir, tírale esta bomba.', },
    {'Mata a 5 técnicos de La Corona y utiliza la bomba de korio de Tuerceganzúas para destruir un vagón químico al este de la Tumba de Khartut, en Uldum. Después, vuelve con el detective Snap Tuerceganzúas en Orgrimmar.', },
  },
  [28936] = {
    'Dilema de divas',
    nil,
    {'Mata a 6 nagas.', },
  },
  [28937] = {
    'Miga de la Alianza',
    {'¡Monstruos! ¡Eran monstruos, te lo aseguro!|n|nNuestro barco atracó en el puerto al sur de Stromgarde, pero la costa estaba infestada de criaturas extrañas.|n|nSolo vi sus horribles jarras y escuché los extraños sonidos que emitían, no esperé a enterarme de lo que querían. ¡Será mejor que vayas a ayudar a mis compañeros, $N!', },
    {'Habla con lady Gurga en la Cala de Faldir.', },
  },
  [28938] = {
    'Salva a los niños',
    nil,
    {'Salva a 6 bebés múrloc.', },
  },
  [28939] = {
    'No hables con desconocidos',
    nil,
    {'Mata a Malaescama.', },
  },
  [28940] = {
    'Conseguir el antídoto',
    nil,
    {'Reúne 6 plantas.', },
  },
  [28941] = {
